const PTASKS=id=>{const c=PTC;if(c.v!==TVER||c.n!==TASKS.length){c.m=new Map();TASKS.forEach(t=>{(c.m.get(t.p)||c.m.set(t.p,[]).get(t.p)).push(t)});c.v=TVER;c.n=TASKS.length}return c.m.get(id)||(XT.on&&XT.pm.get(id))||[]};
