const workOf=t=>{if(t.ms)return 0;const f=(t.res||[]).reduce((a,r)=>a+r[1],0);if(f)return f*t.dur*HRS;const u=(t.asg||[]).reduce((a,r)=>a+r[1],0)/100;return (u||.25)*t.dur*HRS};
