 cis(){if(this._cis)return this._cis;const r=RNG("cis"),pick=a=>a[Math.floor(r()*a.length)];const cls=[["Server",.22],["Virtual machine",.2],["Database",.08],["Network device",.1],["Application",.12],["Container",.1],["Storage",.05],["Load balancer",.03],["Cloud resource",.1]];const env=["Production","Production","Test","Dev","DR"];const svc=["Codification Portal","Search","Contract Repository","Lease subledger","Identity","Email and collaboration","Data platform","Network and VPN","Endpoint","Integration hub"];const out=[];for(let i=0;i<this.n.cis;i++){let x=r(),c=cls[0][0];for(const k of cls){x-=k[1];if(x<=0){c=k[0];break}}const e=pick(env);out.push({id:"CI"+String(100000+i),name:c.split(" ")[0].toLowerCase().slice(0,3)+"-"+pick(["mer","nor","az1","az2","edge","app","db","core"])+"-"+String(i%900+100),class:c,env:e,svc:pick(svc),status:r()<.03?"Degraded":r()<.01?"Non-operational":"Operational",owner:pick(DIR.filter(d=>d.kind==="human"&&!d.generated)).name,crit:pick(["1 - Mission critical","2 - Somewhat critical","3 - Less critical","3 - Less critical","4 - Not critical"]),uptime:+(99+r()*.99).toFixed(2),disc:"Oct "+(1+Math.floor(r()*6))})}return this._cis=out},
 tickets(){if(this._tk)return this._tk;const r=RNG("tk"),pick=a=>a[Math.floor(r()*a.length)];const kinds=["Incident","Request","Problem","Change"];const st=["New","In progress","On hold","Resolved","Closed"];const svc=["Codification Portal","Search","Contract Repository","Lease subledger","Identity","Email and collaboration","Data platform","Network and VPN","Endpoint"];const out=[];for(let i=0;i<this.n.tickets;i++){const k=pick(kinds);out.push({id:({Incident:"INC",Request:"RITM",Problem:"PRB",Change:"CHG"})[k]+String(300000+i),kind:k,t:pick(["Cannot sign in","Slow response","Access request","New laptop","Report is wrong","Sync failing","Certificate expiring","Disk space low","VPN drops","Permission change"])+" ("+pick(svc)+")",svc:pick(svc),st:pick(st),pri:pick(["P1","P2","P3","P3","P4","P4"]),grp:pick(["Service desk","Ops team","Platform team","Data team","Security"]),age:Math.floor(r()*40)});}return this._tk=out},
