const sw=()=>{const tb=document.querySelector(".railfoot");if(!tb||document.getElementById("scaleSw"))return;const d=document.createElement("div");d.id="scaleSw";d.className="scalesw";d.setAttribute("role","group");d.setAttribute("aria-label","Data volume");d.innerHTML=`<button type="button" data-scale="0" aria-pressed="true" title="Small demo data">Demo</button><button type="button" data-scale="1" aria-pressed="false" title="Thousands of CIs and tickets, dozens of projects">Enterprise</button>`;tb.insertBefore(d,tb.firstChild);const l=document.createElement("div");l.className="muted small";l.style.cssText="padding:0 6px 4px";l.textContent="Data volume";tb.insertBefore(l,d)};
