function views(name,labels,panes){const cur=S.v[name]||0,id=i=>`v-${name}-${i}`;
 return `<div class="views" data-views="${name}">${labels.map((l,i)=>`<input type="radio" name="vw-${name}" id="${id(i)}" data-vw="${name}:${i}" ${i===cur?"checked":""}>`).join("")}<div class="vsw glass">${labels.map((l,i)=>`<label for="${id(i)}">${l}</label>`).join("")}</div><div class="panes">${panes.map(p=>`<div class="pane">${p}</div>`).join("")}</div></div>`}
