function msRows(P,pids){const out=[];pids.forEach(pid=>{const pj=projOf(pid);PTASKS(pid).filter(t=>t.ms).forEach(t=>{const r=P.R[t.id],b=baseCalc(P.list||TASKS).R[t.id];if(!r||!b)return;const fedBy=msChain(P,t.id,-1),feeds=msChain(P,t.id,1);out.push({id:t.id,wbs:(wbsLn(t.id)||{}).wbs||"",n:t.n,p:pid,pj:pj.short,pjn:pj.n,own:t.own,b:b.es,f:r.es,v:r.es-b.es,pct:t.pct,st:lineStat(t,P),fedBy,feeds,as:t.af})})});return out.sort((a,c)=>a.f-c.f)}
