function track(type,name,diff){A.pkgs=A.pkgs||[];let d=A.pkgs.find(p=>p.id===A.draftId&&p.env==="dev");if(!d){d={id:"PKG-0"+(A.pkgSeq++),n:"Studio changes (draft)",env:"dev",by:"Omar Hamid",at:nowStamp(),g:{},items:[],fail:{}};A.pkgs.unshift(d);A.draftId=d.id}
 d.items.push({type,name,diff:diff||[["+","  "+name]]});d.at=nowStamp();return d}
const visFor=f=>A.asPersona==="all"||!f.vis.length||f.vis.includes(A.asPersona);
const toKit=f=>{const o={k:f.k,label:f.label,type:f.type,req:f.req,help:[f.help,f.rule?"Rule: "+f.rule+".":""].filter(Boolean).join(" ")};if(f.type==="select"||f.type==="multi")o.opts=f.opts;if(f.type==="select")o.ph="Choose one";if(f.type==="text"||f.type==="longtext")o.ph=f.help?"":"";return o};
