 const spec={id:"admprev",fields:sec,submit:"Save"};FORMSPEC.admprev=spec;if(!FORMST.admprev||FORMST.admprev.obj!==o){FORMST.admprev={vals:{},err:{},obj:o};A.fields[o].forEach(f=>{if(f.def!=="")FORMST.admprev.vals[f.k]=f.type==="toggle"?f.def==="true":f.def})}
