 const init=ex?{label:ex.label,k:ex.k,type:ex.type,req:ex.req,def:ex.def,opts:ex.opts.join("\n"),rule:ex.rule,vis:ex.vis.slice(),help:ex.help,_kman:true}:{type:"text",req:false,vis:[]};
