 if(ti<fi){if(ti!==fi-1)return {ok:false,msg:"Roll back one environment at a time"};p.env=to;p.rolled=true;audit("rolled back package",p.id+" from "+ENVS[fi][1]+" to "+ENVS[ti][1]+(why?" · "+why:""));p.at=nowStamp();A.env[to].drift++;return {ok:true,msg:p.id+" rolled back to "+ENVS[ti][1]+". The earlier version is live again."}}
 if(ti!==fi+1){A.promo.tries++;recalcProm();audit("blocked promotion",p.id+" cannot skip environments");return {ok:false,msg:"A package moves one environment at a time. Next stop for "+p.id+" is "+ENVS[fi+1][1]+"."}}
 const key=ENVS[fi][0]+">"+ENVS[ti][0],gs=gateState(p,key),miss=gs.filter(g=>!g.ok);
