 recalcProm();p.env=to;p.rolled=false;p.at=nowStamp();const e=A.env[to];e.ver="26.10.06+"+(144+A.pkgs.indexOf(p)+1);e.deployed="Today "+nowStamp();e.drift=Math.max(0,e.drift-1);
