function overage(m,mult){const over=Math.max(0,proj(m)-m.q);if(!over)return {over:0,t1:0,t2:0,cost:0,txt:"Within quota"};const band=m.q*.25,o1=Math.min(over,band),o2=Math.max(0,over-band),c1=o1/m.per*m.rate*(mult||1),c2=o2/m.per*m.rate*1.5*(mult||1);return {over,o1,o2,t1:c1,t2:c2,cost:c1+c2,txt:`${fmtN(o1)} × ${usd(m.rate*(mult||1),2)} per ${fmtN(m.per)}${o2?` + ${fmtN(o2)} × ${usd(m.rate*1.5*(mult||1),2)} per ${fmtN(m.per)}`:""}`}}
const seatCost=()=>A.seats.reduce((a,s)=>a+s.bought*s.price,0);
const PLAN=()=>byId(PLANS,"pro");
const SBX=2*250,CREDIT=.08;
function lines(){const L=[];A.seats.forEach(s=>L.push({id:"seat_"+s.id,n:s.n+" seats",q:s.bought,p:s.price,amt:s.bought*s.price,kind:"seat",s}));L.push({id:"base",n:"Professional platform fee",q:1,p:PLAN().base,amt:PLAN().base,kind:"base"});L.push({id:"sbx",n:"Sandbox environments (Dev and Test)",q:2,p:250,amt:SBX,kind:"sbx"});
 MET.forEach(m=>{const o=overage(m);if(o.cost>0)L.push({id:"ov_"+m.id,n:m.n+" overage (projected)",q:o.over,p:null,amt:o.cost,kind:"ov",m,o})});
 const sub=L.reduce((a,l)=>a+l.amt,0),seatsSub=L.filter(l=>l.kind==="seat").reduce((a,l)=>a+l.amt,0),cr=-seatsSub*CREDIT;L.push({id:"credit",n:"Annual commitment credit (8% of seats)",q:1,p:null,amt:cr,kind:"credit"});L.total=sub+cr;L.sub=sub;return L}
function explain(l){const m=l.m;let s="",f="",src="",rel="";
 if(l.kind==="seat"){s=`Meridian bought ${l.q} ${l.s.n.toLowerCase()} seats and ${l.s.assigned} are assigned, so ${l.q-l.s.assigned} sit unused. Seats are billed on purchased quantity, not on assigned, because they are reserved for you. ${l.s.id==="agent"?"Two agent seats were added mid-month; the statement shows the full month because they will be billed that way from November.":""}`;f=`${l.q} seats × ${usd(l.p)} per seat per month = ${usd(l.amt)}`;src="Licence assignments from Entra ID groups and the agent registry";rel=`Unused seats cost ${usd((l.q-l.s.assigned)*l.p)} a month. The Licence utilization metric tracks this.`}
 else if(l.kind==="base"){s="The Professional plan includes SSO and SCIM, break-glass access, multi-model routing and two sandbox environments. It is a flat monthly fee that covers the quotas shown on the usage meters.";f=`Flat fee ${usd(l.amt)} per month`;src="Plan record";rel="Compare tiers in Plans to see what changes at Enterprise."}
 else if(l.kind==="sbx"){s="Dev and Test environments are billed as sandboxes. Production and UAT are included in the platform fee.";f=`2 sandboxes × ${usd(250)} = ${usd(l.amt)}`;src="Environment registry";rel="Visible on the Environments and releases screen."}
 else if(l.kind==="ov"){s=`${m.n} is on pace for ${fmtN(proj(m))} against a quota of ${fmtN(m.q)}, so about ${fmtN(l.o.over)} ${m.unit} would be billed as overage. ${m.story} Overage is tiered: the first 25% over quota is billed at the standard rate, beyond that at 1.5 times the rate.`;f=`${projTxt(m)}; over quota by ${fmtN(l.o.over)}; ${l.o.txt} = ${usd(l.amt,2)}`;src="Usage meter, "+DAYS+" days of data";rel="Slow the burn or raise the quota to avoid it: see the what-if on the Plans tab."}
 else{s="Meridian committed to a year of seats, which earns 8% off seat charges. The credit does not apply to usage overage or sandboxes.";f=`8% × seat charges = ${usd(-l.amt,2)}`;src="Contract: annual commitment";rel="Renews Jan 2027."}
 openDrawer(`<span class="pill info">Statement line</span><h2 style="font-size:28px;margin:12px 0 6px;padding-right:60px">${esc(l.n)}</h2><div class="num" style="font-size:40px" data-role="metric">${l.amt<0?"−":""}${usd(Math.abs(l.amt),l.kind==="ov"||l.kind==="credit"?2:0)}</div><p class="story" data-role="story" style="font-size:16px;margin:10px 0">${esc(s)}</p><div class="formula">${esc(f)}</div><dl class="kv"><dt>Source</dt><dd>${esc(src)}</dd><dt>Related</dt><dd>${esc(rel)}</dd></dl><div class="row">${aiChip({model:"Claude Sonnet",conf:.9,title:"Explanation drafted from the rating rules",src:["Rating rules","Usage meter","Contract"],guards:["Numbers come from the meter, not the model"]})}</div>`);audit("explained statement line",l.n)}
function stmtText(){const L=lines();return "Oukala statement, October 2026 (projected)\n"+L.map(l=>`${l.n}\t${l.amt<0?"-":""}${usd(Math.abs(l.amt),2)}`).join("\n")+`\nTotal\t${usd(L.total,2)}`}
function seatTab(){const full=A.seats.reduce((a,s)=>a+s.bought*s.price,0),used=A.seats.reduce((a,s)=>a+s.assigned*s.price,0),u=Math.round(used/full*1000)/10;METRICS.m_licuse.cur=u;METRICS.m_licuse.tr[7]=u;
 return `<div class="card glass"><div class="cardhead"><div><h3>Seat types</h3><span class="muted small" data-role="story">Four seat types match four kinds of work. <b>${usd(full-used)}</b> a month pays for seats nobody uses, so utilization is <b>${u}%</b>.</span></div><div class="row">${fchip("m_licuse")}<button class="btn" data-adm="seatbuy">Change seats</button></div></div><div class="grid g4">${A.seats.map(s=>{const p=Math.round(s.assigned/s.bought*100);return `<div class="tile glass"><span class="lbl">${s.n}</span><span class="big num" data-role="metric">${s.assigned}<small class="muted" style="font-size:18px"> of ${s.bought}</small></span><div class="adm-bar" aria-label="${p} percent assigned"><i style="width:${p}%"></i></div><span class="muted small">${usd(s.price)} per seat per month</span><span class="small">${esc(s.d)}</span></div>`}).join("")}</div></div>
 <div class="card glass"><div class="cardhead"><h3>Plan comparison and what-if</h3><span class="muted small" data-role="story">Slide the numbers to see which tier is cheapest for the usage you expect.</span></div>${planTab()}</div>`}
function whatif(i){i=i||A.wi||(A.wi={seats:138,tok:100,api:5});return PLANS.map(p=>{const seat=i.seats*p.price.full+52*p.price.light+27*p.price.appr+5*p.price.agent;const mt={reset:true,per:1000000,rate:4,q:p.tok/1e6*1e6,used:i.tok*1e6,spark:[]};const tokOv=Math.max(0,i.tok*1e6-p.tok)/1e6*4*p.ovx,apiOv=Math.max(0,i.api*1e6-p.api)/1000*.4*p.ovx;return {p,seat,tokOv,apiOv,total:p.base+seat+tokOv+apiOv}})}
function wiHTML(){const r=whatif(),best=r.reduce((a,b)=>b.total<a.total?b:a),cur=r.find(x=>x.p.cur);
 return `<div class="adm-wi">${r.map(x=>`<div class="adm-wip ${x.p===best.p?"best":""}"><b>${x.p.n}</b>${x.p.cur?pill("Current","info"):""}${x.p===best.p?pill("Cheapest","good"):""}<span class="num" style="font-size:28px" data-role="metric">${usd(x.total)}</span><span class="muted small">${usd(x.p.base)} base + ${usd(x.seat)} seats${x.tokOv+x.apiOv>0?` + ${usd(x.tokOv+x.apiOv)} overage`:""}</span>${x.p!==cur?`<span class="small ${x.total<cur.total?"good":"warn"}" style="font-weight:700">${x.total<cur.total?"Saves ":"Costs "}${usd(Math.abs(x.total-cur.total))} a month vs current</span>`:""}</div>`).join("")}</div><p class="muted small"><span class="fx">Total = base fee + Σ(seats × seat price) + overage above plan quota × rate × plan multiplier</span></p>`}
function planTab(){const w=A.wi||(A.wi={seats:138,tok:100,api:5});
 const rows=[["Base fee per month",p=>usd(p.base)],["Full user seat",p=>usd(p.price.full)],["Included API calls",p=>fmtN(p.api/1e6)+"M"],["Included AI tokens",p=>fmtN(p.tok/1e6)+"M"],["Included automation runs",p=>fmtN(p.aut/1000)+"K"],["Included storage",p=>fmtN(p.sto)+" GB"],["Sandbox environments",p=>p.sbx],["Identity",p=>p.sso],["Break-glass and reviews",p=>p.bg],["AI gateway",p=>p.gw],["Support",p=>p.sla],["Overage rate multiplier",p=>p.ovx+" ×"]];
 return `<div class="grid g2" style="align-items:start"><div class="tablewrap" style="max-height:none"><table class="adm-tbl" style="min-width:520px"><thead><tr><th></th>${PLANS.map(p=>`<th>${p.n}${p.cur?" (yours)":""}</th>`).join("")}</tr></thead><tbody>${rows.map(r=>`<tr><td><b>${r[0]}</b></td>${PLANS.map(p=>`<td>${r[1](p)}</td>`).join("")}</tr>`).join("")}</tbody></table></div>
 <div><div class="fgrid" style="grid-template-columns:1fr"><label class="fld"><span class="flab">Full user seats planned</span><span class="frange"><input type="range" class="rng" min="60" max="320" value="${w.seats}" data-adm-in="wi_seats" aria-label="Full user seats"><b class="num" id="adm_wi_seats">${w.seats}</b></span></label><label class="fld"><span class="flab">AI tokens per month (millions)</span><span class="frange"><input type="range" class="rng" min="20" max="600" step="10" value="${w.tok}" data-adm-in="wi_tok" aria-label="AI tokens in millions"><b class="num" id="adm_wi_tok">${w.tok}M</b></span></label><label class="fld"><span class="flab">API calls per month (millions)</span><span class="frange"><input type="range" class="rng" min="1" max="30" value="${w.api}" data-adm-in="wi_api" aria-label="API calls in millions"><b class="num" id="adm_wi_api">${w.api}M</b></span></label></div><div id="adm_wires" style="margin-top:12px">${wiHTML()}</div><div class="row" style="margin-top:10px"><button class="btn primary" data-adm="upreq">Request a plan change</button></div></div></div>`}
function meterTab(){const tot=MET.map(m=>overage(m)).reduce((a,o)=>a+o.cost,0);
 return `<div class="card glass"><div class="cardhead"><div><h3>Usage meters</h3><span class="muted small" data-role="story">Day ${DAYS} of ${DIM}. <b>${MET.filter(m=>proj(m)>m.q).length}</b> of ${MET.length} meters are on pace to pass their quota, worth about <b>${usd(tot)}</b> in overage if nothing changes.</span></div><div class="row">${fchip("m_tokcost","AI cost per outcome")}<button class="btn" data-adm="gogate">AI budget guard</button></div></div>
 <div class="grid g2">${MET.map(m=>{const p=proj(m),pct=Math.round(m.used/m.q*100),pp=Math.round(p/m.q*100),o=overage(m),st=pp>100?"bad":pp>85?"warn":"good";return `<div class="tile glass adm-met"><div class="row sp"><span class="lbl">${m.n}</span>${pill(pp>100?"Over quota by month end":pp>85?"Close to quota":"On pace",st)}</div><span class="big num" data-role="metric">${m.id==="tok"?fmtN(m.used/1e6)+"M":m.id==="api"?(m.used/1e6).toFixed(2)+"M":fmtN(m.used)}<small class="muted" style="font-size:16px"> of ${m.id==="tok"?fmtN(m.q/1e6)+"M":m.id==="api"?(m.q/1e6)+"M":fmtN(m.q)} ${m.id==="tok"||m.id==="api"?"":m.unit}</small></span>
 <div class="adm-bar big q" aria-label="${pct} percent of quota used"><i style="width:${Math.min(100,pct)}%"></i><u style="left:${Math.min(99.5,Math.max(pp,0))}%" title="Projected"></u></div>
 <div class="row sp small"><span>${pct}% used</span><span>Projected <b>${pp}%</b></span></div><div>${spark(m.spark,300,38,col(st==="good"?"--good-f":st==="warn"?"--warn-f":"--bad-f"))}</div>
 <div class="formula" style="font-size:14px;padding:8px 12px">${esc(projTxt(m))}${m.reset?"":" (storage grows, it does not reset)"}</div><span class="muted small">${esc(m.story)}</span>${o.cost>0?`<span class="small" style="font-weight:700;color:var(--bad)">Overage preview: ${usd(o.cost,2)} (${esc(o.txt)})</span>`:""}</div>`}).join("")}</div></div>
 <div class="card glass"><div class="cardhead"><div><h3>Rating and overage preview</h3><span class="muted small" data-role="story">How a meter becomes money: usage above quota is rated in two bands.</span></div></div><div class="tablewrap" style="max-height:none"><table class="adm-tbl" style="min-width:640px"><thead><tr><th>Meter</th><th>Quota</th><th>Projected</th><th>Over</th><th>Rating</th><th>Charge</th></tr></thead><tbody>${MET.map(m=>{const o=overage(m);return `<tr><td><b>${m.n}</b></td><td>${m.id==="tok"?fmtN(m.q/1e6)+"M":fmtN(m.q)}</td><td>${m.id==="tok"?fmtN(proj(m)/1e6)+"M":fmtN(proj(m))}</td><td>${o.over?fmtN(m.id==="tok"?o.over/1e6:o.over)+(m.id==="tok"?"M":""):"—"}</td><td class="small">${esc(o.txt)}</td><td><b class="num" data-role="metric">${usd(o.cost,2)}</b></td></tr>`}).join("")}</tbody></table></div><p class="muted small" style="margin-top:8px"><span class="fx">Charge = min(over, 25% of quota) × rate + max(0, over − 25% of quota) × rate × 1.5, per unit price</span></p></div>`}
function stmtTab(){const L=lines();
 return `<div class="card glass"><div class="cardhead"><div><h3>Statement: October 2026 (projected)</h3><span class="muted small" data-role="story">Invoice date Nov 1, net 30. Projected total <b>${usd(L.total,2)}</b>, of which <b>${usd(L.filter(l=>l.kind==="ov").reduce((a,l)=>a+l.amt,0),2)}</b> is overage you can still avoid. Select any line to hear its story.</span></div><button class="btn" data-adm="stmtcopy">Copy as text</button></div>
 <div class="adm-stmt">${L.map(l=>`<button class="adm-sl ${l.kind}" data-adm="explain:${l.id}"><span><b>${esc(l.n)}</b>${l.p!=null?`<br><span class="muted small">${fmtN(l.q)} × ${usd(l.p)}</span>`:""}</span><span class="num" data-role="metric">${l.amt<0?"−":""}${usd(Math.abs(l.amt),l.kind==="ov"||l.kind==="credit"?2:0)}</span><span class="pill info">Explain this line</span></button>`).join("")}<div class="adm-sl tot"><span><b>Subtotal</b></span><span class="num">${usd(L.sub,2)}</span><span></span></div><div class="adm-sl tot"><span><b>Tax</b><br><span class="muted small">Exempt: nonprofit certificate on file</span></span><span class="num">$0.00</span><span></span></div><div class="adm-sl tot grand"><span><b>Total due</b></span><span class="num" data-role="metric">${usd(L.total,2)}</span><span></span></div></div><textarea id="adm_stmtcopy" class="fin sr" readonly aria-hidden="true" tabindex="-1"></textarea></div>`}
A.sb=A.sb||"seats";const DEP=[["Delivery",32,8,3,0],["Finance",18,6,9,1],["IT Operations",24,12,2,0],["Engineering",22,4,1,1],["Portfolio office",9,3,4,1],["Executive office",4,1,5,1],["Editorial",19,14,1,1],["Vendor management",10,4,2,0]];
function showback(){const L=lines(),shared=L.filter(l=>l.kind!=="seat"&&l.kind!=="credit").reduce((a,l)=>a+l.amt,0)+L.filter(l=>l.kind==="credit").reduce((a,l)=>a+l.amt,0);const seat=DEP.map(d=>d[1]*42+d[2]*14+d[3]*6+d[4]*95),tS=seat.reduce((a,b)=>a+b,0);
 const use=DEP.map((d,i)=>MET.reduce((a,m)=>a+m.w[i],0)/MET.length);
 return DEP.map((d,i)=>{const share=A.sb==="seats"?seat[i]/tS:A.sb==="usage"?use[i]:1/DEP.length,alloc=shared*share;return {n:d[0],seat:seat[i],alloc,total:seat[i]+alloc,use:use[i],ppl:d[1]+d[2]+d[3]}})}
function sbTab(){const rows=showback(),tot=rows.reduce((a,r)=>a+r.total,0),mx=Math.max(...rows.map(r=>r.total));
 return `<div class="card glass"><div class="cardhead"><div><h3>Usage by department (showback)</h3><span class="muted small" data-role="story">The projected bill of <b>${usd(tot)}</b> split by department. Platform fee, sandboxes and overage are shared <b>${A.sb==="seats"?"in proportion to seat charges":A.sb==="usage"?"in proportion to metered usage":"evenly"}</b>.</span></div><div class="row">${[["seats","By seats"],["usage","By usage"],["even","Evenly"]].map(x=>`<button class="chip" data-adm="sb:${x[0]}" aria-pressed="${A.sb===x[0]}">${x[1]}</button>`).join("")}</div></div>
 <div class="tablewrap" style="max-height:none"><table class="adm-tbl" style="min-width:640px"><thead><tr><th>Department</th><th>People</th><th>Seat charges</th><th>Shared share</th><th>Total</th><th>Share of bill</th></tr></thead><tbody>${rows.sort((a,b)=>b.total-a.total).map(r=>`<tr><td><b>${r.n}</b></td><td>${r.ppl}</td><td>${usd(r.seat)}</td><td>${usd(r.alloc)}</td><td><b class="num" data-role="metric">${usd(r.total)}</b></td><td><div class="adm-bar"><i style="width:${Math.round(r.total/mx*100)}%"></i></div><span class="muted small">${Math.round(r.total/tot*100)}%</span></td></tr>`).join("")}</tbody></table></div><p class="muted small" style="margin-top:8px"><span class="fx">Department charge = Σ(department seats × seat price) + shared charges × allocation share</span> Showback informs; chargeback would post these to cost centers.</p></div>`}
function meterHTML(){const L=lines(),ov=L.filter(l=>l.kind==="ov").reduce((a,l)=>a+l.amt,0);
 return `<div class="screen">${hero("Platform · Licensing, usage and billing","What Meridian pays for, and why",`The October statement is projected at <b>${usd(L.total)}</b>. <b>${usd(ov)}</b> of it is overage on <b>${MET.filter(m=>proj(m)>m.q).map(m=>m.n.toLowerCase()).join(" and ")||"no meters"}</b>, and <b>${usd(A.seats.reduce((a,s)=>a+(s.bought-s.assigned)*s.price,0))}</b> pays for seats nobody has been given.`,`<div class="row">${fchip("m_licuse")}${fchip("m_tokcost","AI cost per outcome")}${aiChip({model:"Claude Sonnet",conf:.9,title:"Statement explanations",note:"Explains each line from the rating rules. The amounts are computed from meters, not generated.",src:["Usage meters","Rating rules","Seat assignments"],guards:["Never edits an amount"]})}</div>`)}${lensNote()}
 ${views("adm_meter",["Seats and plans","Usage meters","Statement","Showback"],[seatTab(),meterTab(),stmtTab(),sbTab()])}</div>`}
REG("adm_meter","Licensing and billing","platform","M4 6h16v12H4zM4 10h16M8 15h3",meterHTML);

