A.models=A.models||[
 {id:"sonnet",n:"Claude Sonnet 5.5",prov:"Anthropic",pin:3,pout:15,lat:1.9,q:92,res:"US region",zdr:true,st:"approved",max:3},
 {id:"haiku",n:"Claude Haiku 5",prov:"Anthropic",pin:.8,pout:4,lat:.6,q:81,res:"US region",zdr:true,st:"approved",max:2},
 {id:"gpt",n:"GPT-5",prov:"OpenAI",pin:1.25,pout:10,lat:2.2,q:90,res:"US region",zdr:true,st:"approved",max:2},
 {id:"gem",n:"Gemini 3 Pro",prov:"Google",pin:2,pout:12,lat:1.7,q:88,res:"US and EU",zdr:false,st:"review",max:1},
 {id:"azure",n:"Azure OpenAI GPT-4.1 (Meridian tenant)",prov:"Microsoft",pin:2,pout:8,lat:1.4,q:86,res:"US East, private endpoint",zdr:true,st:"approved",max:3},
 {id:"llama",n:"Llama 4 Scout (self-hosted)",prov:"Meridian Azure",pin:.2,pout:.2,lat:.9,q:72,res:"Meridian Azure, no egress",zdr:true,st:"approved",max:3},
 {id:"grok",n:"Unvetted public model",prov:"Other",pin:1,pout:3,lat:1.2,q:70,res:"Unknown",zdr:false,st:"denied",max:0}];
const MOD=id=>byId(A.models,id)||{n:id,st:"denied"};
const TASKS_G=["Any task","Invoice scoring","Meeting summary","Knowledge drafting","Triage and classification","Test generation","General"];
A.routes=A.routes||[
 {id:"rt1",task:"Any task",minLbl:2,pri:"azure",fb:"llama",ceil:.6,why:"Confidential or Restricted data never leaves the Meridian tenant."},
 {id:"rt2",task:"Invoice scoring",minLbl:0,pri:"gpt",fb:"gem",ceil:.15,why:"Council check by a second vendor above $25,000."},
 {id:"rt3",task:"Meeting summary",minLbl:0,pri:"sonnet",fb:"gpt",ceil:.4,why:"Best quality on long transcripts."},
 {id:"rt4",task:"Knowledge drafting",minLbl:0,pri:"gem",fb:"sonnet",ceil:.3,why:"Strong at long documents at a lower price."},
 {id:"rt5",task:"Triage and classification",minLbl:0,pri:"haiku",fb:"llama",ceil:.02,why:"Fast and cheap; quality is enough for routing."},
 {id:"rt6",task:"Test generation",minLbl:0,pri:"sonnet",fb:"gpt",ceil:.5,why:"Sandbox data only."},
 {id:"rt7",task:"General",minLbl:0,pri:"haiku",fb:"azure",ceil:.05,why:"Default for everything else."}];
A.rt=A.rt||{task:"Invoice scoring",lbl:1};
function route(task,lbl){const tr=[];for(const r of A.routes){const m=(r.task==="Any task"||r.task===task);const l=lbl>=r.minLbl;if(m&&l){const p=MOD(r.pri),f=MOD(r.fb);const okp=p.st==="approved"&&p.max>=lbl,okf=f.st==="approved"&&f.max>=lbl;tr.push(`Policy ${A.routes.indexOf(r)+1} (${r.task}${r.minLbl?", data "+LABELS[r.minLbl]+" or above":""}) matches.`);
   if(okp){tr.push(`Primary ${p.n} is approved for ${LABELS[lbl]} data. Using it.`);return {r,m:p,tr}}
   tr.push(`Primary ${p.n} is ${p.st!=="approved"?p.st:"not cleared for "+LABELS[lbl]+" data"}. Trying the fallback.`);
   if(okf){tr.push(`Fallback ${f.n} is approved. Using it.`);return {r,m:f,tr,fell:true}}
   tr.push(`Fallback ${f.n} is also unavailable. Continuing to the next policy.`)}else tr.push(`Policy ${A.routes.indexOf(r)+1} (${r.task}${r.minLbl?", "+LABELS[r.minLbl]+"+":""}) does not match.`)}
 return {r:null,m:null,tr:tr.concat("No policy produced an approved model. The call is refused.")}}
DND.on("adm_route",(id,from,to,idx)=>{const L={r:A.routes.map(r=>r.id)};if(moveIn(L,id,"r","r",idx)){A.routes=L.r.map(i=>byId(A.routes,i));audit("reordered routing policies",id+" now priority "+(L.r.indexOf(id)+1));toast("Priority saved. Policy "+(L.r.indexOf(id)+1)+" is evaluated "+(L.r.indexOf(id)?"after the "+L.r.indexOf(id)+" above it":"first"));render()}});
function routeRow(r,i){const p=MOD(r.pri),f=MOD(r.fb),bad=p.st!=="approved";return `<div class="adm-fi rt" data-dnd-id="${r.id}" tabindex="0">${grip}<b class="num adm-pri">${i+1}</b><div class="adm-fmain"><b>${esc(r.task)}${r.minLbl?` <span class="muted small">when data is ${LABELS[r.minLbl]}+</span>`:""}</b><span class="muted small">${esc(r.why)}</span></div><span class="adm-mdl"><span class="muted small">Primary</span><b>${esc(p.n)}</b>${bad?pill(p.st,"bad"):""}</span><span class="adm-mdl"><span class="muted small">Fallback</span><b>${esc(f.n)}</b></span><span class="adm-mdl"><span class="muted small">Ceiling</span><b>${usd(r.ceil,2)} per run</b></span><span class="adm-acts"><button class="btn quiet" data-nodrag data-adm="rtedit:${r.id}" aria-label="Edit policy ${i+1}">Edit</button><button class="btn quiet" data-nodrag data-adm="rtdel:${r.id}" aria-label="Remove policy ${i+1}">Remove</button></span></div>`}
