function waterfall(){const t=T(B().lines),W=760,H=310,L=64,R=14,Tp=24,Bt=62,lo=Math.floor((Math.min(t.appr,t.fcst)-100e3)/100e3)*100e3;
 const env=t.appr+resOpen(),top=Math.ceil((Math.max(t.fcst,env)+40e3)/100e3)*100e3,ys=v=>Tp+(H-Tp-Bt)*(1-(v-lo)/(top-lo));
 const items=[{l:"Approved",v:t.appr,k:"tot",c:"--p4"}];PROJ.forEach(p=>{const d=T(PL(p.id));items.push({l:p.id+" "+p.short,v:d.fcst-d.appr,k:"d"})});
 items.push({l:"Forecast",v:t.fcst,k:"tot",c:"--w1"},{l:"Reserve headroom",v:env-t.fcst,k:"d2"},{l:"Envelope",v:env,k:"tot",c:"--s3"});
 const n=items.length,bw=(W-L-R)/n,x=i=>L+i*bw+bw*.18,w=bw*.64;let run=0,g="";
 for(let v=lo;v<=top;v+=100e3){g+=`<line class="grid-l" x1="${L}" x2="${W-R}" y1="${ys(v)}" y2="${ys(v)}"/><text class="ax" x="${L-8}" y="${ys(v)+4}" text-anchor="end">${C$(v)}</text>`}
 items.forEach((it,i)=>{let y1,y2,fill,txt;
  if(it.k==="tot"){y1=ys(it.v);y2=ys(lo);fill=`var(${it.c})`;run=it.v;txt=C$(it.v)}
  else{const a=run,b=run+it.v;run=b;y1=ys(Math.max(a,b));y2=ys(Math.min(a,b));fill=it.k==="d2"?"var(--s4)":(it.v>0?"var(--e4)":"var(--s3)");txt=sgn(it.v);if(it.k==="d2")fill="var(--s4)"}
  const h=Math.max(2,y2-y1);g+=`<rect x="${x(i)}" y="${y1}" width="${w}" height="${h}" rx="6" fill="${fill}" opacity="${it.k==="d2"?.55:.92}"><title>${esc(it.l)}: ${txt}</title></rect><text class="ax bud-vl" x="${x(i)+w/2}" y="${y1-7}" text-anchor="middle">${txt}</text>`;
  const words=it.l.split(" ");g+=`<text class="ax" x="${x(i)+w/2}" y="${H-Bt+18}" text-anchor="middle">${esc(words[0])}</text><text class="ax" x="${x(i)+w/2}" y="${H-Bt+32}" text-anchor="middle">${esc(words.slice(1).join(" "))}</text>`;
  if(i<n-1){const yy=ys(run);g+=`<line x1="${x(i)+w}" x2="${x(i+1)}" y1="${yy}" y2="${yy}" stroke="var(--muted)" stroke-width="1" stroke-dasharray="3 3" opacity=".6"/>`}});
 return `<svg class="chart bud-wf" viewBox="0 0 ${W} ${H}" width="100%" role="img" aria-label="Waterfall from approved budget ${C$(t.appr)} to forecast ${C$(t.fcst)} and the envelope ${C$(env)}. The axis starts at ${C$(lo)}.">${g}</svg><p class="small muted" style="margin:6px 0 0">The vertical axis starts at ${C$(lo)} so the changes are visible. Every bar is drawn to the same scale.</p>`}
function burnChart(big){const b=burn(),t=T(B().lines),env=t.appr+resOpen();
 return lineChart(FM,[{vals:b.plan,color:col("--faint"),dash:true,w:2.5},{vals:b.act,color:col("--p4"),area:true},{vals:b.fc,color:col("--w1"),dash:true,start:2,w:3.5}],{w:760,h:big?340:280,max:Math.ceil((env+120e3)/500e3)*500e3,ticks:Math.round(Math.ceil((env+120e3)/500e3)),fmt:v=>C$(v),alt:"Cumulative spend by month against the plan, with the forecast",marks:[{v:t.appr,color:"var(--good-f)",label:"Approved "+C$(t.appr)}]})}
const burnKey=`<div class="row small muted" style="gap:16px"><span class="bud-key"><i style="background:var(--faint)"></i>Plan (phasing of approved budget)</span><span class="bud-key"><i style="background:var(--p4)"></i>Actual, closed through Sep 30</span><span class="bud-key"><i style="background:var(--w1)"></i>Forecast</span></div>`;
function varTable(){const rows=B().lines.filter(l=>vr(l)!==0).sort((a,b)=>Math.abs(vr(b))-Math.abs(vr(a)));
 return wrap(`<table><thead><tr><th>Budget line</th><th>Approved</th><th>Forecast</th><th>Variance</th><th>Why it varies</th><th>What we are doing</th><th>Reserve</th><th></th></tr></thead><tbody>${rows.map(l=>{const dr=-sum(B().led.filter(e=>e.line===l.id&&e.st==="Approved"),e=>e.amt),pe=-sum(B().led.filter(e=>e.line===l.id&&e.st==="Pending"),e=>e.amt);
  return `<tr><td>${lineName(l)}<span class="sub">${esc(PJ(l.p).short)} · ${esc(l.own)}</span></td><td class="tabular">${D$(l.appr)}</td><td class="tabular">${D$(l.fcst)}</td><td>${vpill(vr(l))}</td><td style="min-width:240px;white-space:normal" data-role="story">${esc(l.why||"Within the approved amount.")}</td><td style="min-width:240px;white-space:normal" data-role="story">${esc(l.fix||"No action needed.")}</td><td class="small">${dr?`<span class="pill good">${C$(dr)} drawn</span> `:""}${pe?`<span class="pill warn">${C$(pe)} pending</span>`:""}${!dr&&!pe?'<span class="muted">None</span>':""}</td><td><button class="btn" data-bud-edit="${l.id}">Edit</button></td></tr>`}).join("")}</tbody></table>`)}
function overView(){const t=T(B().lines),b=burn(),env=t.appr+resOpen(),bal=resBal(),pend=resPend();
 const tiles=`<div class="grid g3 bud-tiles">${[
  stat("Approved budget",C$(t.appr),`${PROJ.length} projects, ${new Set(Object.values(PRG)).size} programs`,"good"),
  stat("Committed",C$(t.comm),`${pc(t.comm/t.appr*100)} of approved`,tcls(t.comm,t.appr)),
  stat("Actual, closed Sep 30",C$(t.act),`${pc(t.act/t.appr*100)} of approved · ${sgn(t.act-b.plan[2])} vs phasing plan`,t.act>b.plan[2]?"warn":"good"),
  stat("Forecast at completion",C$(t.fcst),`${sgn(t.fcst-t.appr)} (${pc((t.fcst-t.appr)/t.appr*100,1)}) vs approved`,tcls(t.fcst,t.appr)),
  stat("Not yet committed",C$(t.appr-t.comm),`${C$(t.fcst-t.comm)} more is forecast to be needed`,t.fcst-t.comm>t.appr-t.comm?"warn":"good"),
  stat("Management reserve left",C$(bal),`${C$(bal-pend)} if ${C$(pend)} pending is approved`,bal-pend>=Math.max(0,unfunded())?"good":"warn")].join("")}</div>`;
 const cat=CATS.map(c=>{const a=T(B().lines.filter(l=>l.cat===c));return {c,...a}});
 const legend=`<div class="row small muted" style="gap:16px;margin-top:6px"><span class="bud-key"><i style="background:var(--p4)"></i>Approved</span><span class="bud-key"><i style="background:var(--e4)"></i>Increase</span><span class="bud-key"><i style="background:var(--w1)"></i>Forecast</span><span class="bud-key"><i style="background:var(--s3)"></i>Envelope (approved + opening reserve)</span></div>`;
 return `${tiles}
 <div class="grid g2" style="align-items:start">${card("From approved to forecast","Each project's forecast change, then the reserve that is left against the envelope.",waterfall()+legend,`<span class="row">${fchip("m_budvar")}</span>`)}
 ${card("Monthly spend against plan","Actual is "+sgn(t.act-b.plan[2])+" against the phasing plan at Sep 30. That is timing: Lumen and Northwind were paid earlier than planned.",burnChart()+burnKey,`<span class="row">${aiChip({model:"Forecast Agent",conf:.84,title:"How the forecast line is built",src:["Actuals through Sep 30","Open commitments","Project schedules (IMS)","Lumen milestone plan"],guards:["Cannot post journal entries","Reserve requests need human approval","Every change is audited"]})}</span>`)}</div>
 ${card("Where the forecast differs from the approved budget","Every variance has a reason and a remediation. Select Edit to change a line, or Reforecast to ask for reserve.",varTable(),`<button class="btn primary" data-bud-refc>Reforecast</button>`)}`}
function projCard(p){const a=T(PL(p.id)),v=a.fcst-a.appr,mx=Math.max(a.appr,a.fcst);
 const lines=PL(p.id).map(l=>{const hr=l.appr-l.comm;return `<div class="bud-ln" data-dnd-id="${l.id}" tabindex="0" aria-label="${esc(l.n)}, approved ${D$(l.appr)}, uncommitted ${D$(Math.max(0,hr))}. Drag to move budget to another project.">
  <div class="row sp" style="gap:6px;flex-wrap:nowrap">${grip}<span style="flex:1;min-width:0"><b class="bud-lt">${esc(l.n)}</b><span class="small muted"><i class="dot" style="background:${col(CATC[l.cat])}"></i>${l.cat} · ${esc(l.id)}</span></span><button class="btn quiet" data-bud-edit="${l.id}" data-nodrag aria-label="Edit ${esc(l.id)}" style="padding:4px 10px">Edit</button></div>
  ${meter([{w:l.act/Math.max(l.appr,l.fcst,l.comm)*100,c:"var(--p4)",l:"Actual"},{w:(l.comm-l.act)/Math.max(l.appr,l.fcst,l.comm)*100,c:"var(--p4)",o:.35,l:"Committed"}])}
  <div class="row sp small tabular"><span>${C$(l.appr)} approved</span><span class="${hr<0?"bud-bad":"muted"}">${hr<0?C$(-hr)+" over committed":C$(hr)+" uncommitted"}</span></div></div>`}).join("");
 return `<section class="card glass bud-col"><div class="row sp" style="gap:8px"><div><div class="eyebrow" style="color:${col(p.c)}">${p.id} · ${esc(PRG[p.id])}</div><h3 style="font-size:19px">${esc(p.short)}</h3><span class="small muted">${esc(p.owner)}</span></div>${vpill(v)}</div>
 ${meter([{w:a.act/mx*100,c:"var(--p4)",l:"Actual"},{w:(a.comm-a.act)/mx*100,c:"var(--p4)",o:.35,l:"Committed"},{w:Math.max(0,a.fcst-a.comm)/mx*100,c:"var(--w1)",o:.55,l:"Forecast to commit"}])}
 <div class="grid bud-mini"><div><small>Approved</small><b class="num">${C$(a.appr)}</b></div><div><small>Forecast</small><b class="num">${C$(a.fcst)}</b></div><div><small>Reserve</small><b class="num">${C$(drawn(p.id))}</b></div></div>
 <div class="bud-list" data-dnd="${p.id}" data-dnd-scope="budmove">${lines}</div></section>`}
function projView(){return `<p class="story" data-role="story" style="margin:0">Drag a budget line onto another project to move its uncommitted money. The system shows the effect on both projects and who must approve under the delegation of authority before anything changes. Keyboard: focus a line and press Alt with the arrow keys.</p><div class="bud-board">${PROJ.map(projCard).join("")}</div>
 <div class="row small muted" style="gap:14px"><span class="bud-key"><i style="background:var(--p4)"></i>Actual</span><span class="bud-key"><i style="background:var(--p4);opacity:.35"></i>Committed</span><span class="bud-key"><i style="background:var(--w1);opacity:.55"></i>Forecast, not yet committed</span>${B().xf.length?`<span class="pill info">${B().xf.length} transfer${B().xf.length>1?"s":""} recorded</span>`:""}</div>`}
function groupTable(rows,label,kc){const tt=T(B().lines),mx=Math.max(...rows.map(r=>Math.max(r.appr,r.fcst)));
 return wrap(`<table><thead><tr><th>${label}</th><th>Approved</th><th>Committed</th><th>Actual</th><th>Forecast</th><th>Variance</th><th style="min-width:180px">Approved and forecast</th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${esc(r.n)}</b>${r.s?`<span class="sub">${esc(r.s)}</span>`:""}</td><td class="tabular">${D$(r.appr)}</td><td class="tabular">${D$(r.comm)}</td><td class="tabular">${D$(r.act)}</td><td class="tabular">${D$(r.fcst)}</td><td>${vpill(r.fcst-r.appr)}</td><td>${meter([{w:r.appr/mx*100,c:r.c||"var(--p4)",l:"Approved"}])}<div style="height:4px"></div>${meter([{w:r.fcst/mx*100,c:"var(--w1)",o:.8,l:"Forecast"}])}</td></tr>`).join("")}<tr><td><b>Total</b></td><td class="tabular"><b>${D$(tt.appr)}</b></td><td class="tabular"><b>${D$(tt.comm)}</b></td><td class="tabular"><b>${D$(tt.act)}</b></td><td class="tabular"><b>${D$(tt.fcst)}</b></td><td>${vpill(tt.fcst-tt.appr)}</td><td></td></tr></tbody></table>`)}
function catView(){const L=B().lines;
 const byCat=CATS.map(c=>({n:c,c:`var(${CATC[c]})`,...T(L.filter(l=>l.cat===c))}));
 const byDept=DEPTS.map(d=>({n:d[1],s:d[2],...T(L.filter(l=>l.dept===d[0]))})).filter(r=>r.appr||r.fcst);
 const byPrg=[...new Set(Object.values(PRG))].map(n=>({n,s:Object.keys(PRG).filter(k=>PRG[k]===n).join(", "),...T(L.filter(l=>PRG[l.p]===n))}));
 const cap=PROJ.map(p=>{const ls=PL(p.id),c=capTot(ls),f=sum(ls,l=>l.fcst);return {p,c,o:f-c,f}}),ct=sum(cap,x=>x.c),ft=sum(cap,x=>x.f);
 const capHTML=`<div class="bud-split">${cap.map(x=>`<div class="bud-sp"><div class="row sp"><b>${x.p.id} ${esc(x.p.short)}</b><span class="small tabular muted">${pc(x.c/x.f*100)} capital</span></div>${meter([{w:x.c/x.f*100,c:"var(--u3)",l:"CapEx"},{w:x.o/x.f*100,c:"var(--s3)",o:.7,l:"OpEx"}])}<div class="row sp small tabular"><span><i class="dot" style="background:var(--u3)"></i>CapEx ${C$(x.c)}</span><span><i class="dot" style="background:var(--s3)"></i>OpEx ${C$(x.o)}</span></div></div>`).join("")}</div>
  <div class="formula" style="margin-top:12px" data-role="metric">Forecast ${C$(ft)} = CapEx ${C$(ct)} (${pc(ct/ft*100,1)}) + OpEx ${C$(ft-ct)} (${pc((ft-ct)/ft*100,1)}) · Capital used ${pc(ct/B().envelope*100,1)} of the ${C$(B().envelope)} board envelope</div>`;
 return `${card("By category","Labor, vendor, hardware, cloud and licences. Vendor is the only category over its commitment.",groupTable(byCat,"Category"))}
 ${card("By department and cost center","Who carries the budget. Showback to the people who consume the services is on the Financial model screen.",groupTable(byDept,"Department"))}
 ${card("By program","Digital Publishing holds two projects and the Lumen dependency.",groupTable(byPrg,"Program"))}
 ${card("CapEx and OpEx","Capital share comes from the ASC 350-40 rules in the Financial model, not from a typed percentage.",capHTML,`<span class="row">${fchip("m_capex")}<button class="btn" data-go="bud_model">Open capitalization rules</button></span>`)}`}
function fcView(){const b=burn(),t=T(B().lines),rows=FM.map((m,i)=>{const isA=i<3;const v=isA?ACTM[i]:b.fcM[i-3];return {m,plan:b.planM[i],v,isA,cp:b.plan[i],cv:isA?b.act[i]:b.fc[i+1]}});
 return `${card("Monthly burn and forecast","Forecast spend after September follows each project's schedule, scaled so the year ends at the forecast total of "+C$(t.fcst)+".",burnChart(true)+burnKey,`<span class="row">${fchip("m_budvar")}<button class="btn primary" data-bud-refc>Reforecast</button></span>`)}
 ${card("Month by month","Actual is closed through Sep 30. Oct is the current month.",wrap(`<table><thead><tr><th>Month</th><th>Plan</th><th>Actual or forecast</th><th>Cumulative plan</th><th>Cumulative actual or forecast</th><th>Difference</th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${r.m}</b>${r.isA?'<span class="pill mute" style="margin-left:8px">Actual</span>':'<span class="pill info" style="margin-left:8px">Forecast</span>'}</td><td class="tabular">${D$(r.plan)}</td><td class="tabular">${D$(r.v)}</td><td class="tabular">${D$(r.cp)}</td><td class="tabular">${D$(r.cv)}</td><td>${vpill(r.cv-r.cp)}</td></tr>`).join("")}</tbody></table>`))}`}
function ledRows(){return B().led.map(e=>{const bal=sum(B().led.slice(0,B().led.indexOf(e)+1).filter(x=>x.st==="Approved"),x=>x.amt);const can=e.st==="Pending"&&e.t==="draw"&&(omarCan(-e.amt,"Reserve release",e.req,{proj:e.p}));
 return `<tr><td><b>${e.id}</b><span class="sub">${dfmt(e.d)}</span></td><td>${e.t==="open"?"Opening balance":e.p?esc(PJ(e.p).short)+(e.line?`<span class="sub">${e.line}</span>`:""):"Portfolio"}</td><td style="min-width:260px;white-space:normal" data-role="story">${esc(e.why)}${e.ai?` ${aiChip({model:"Forecast Agent",conf:.84,title:"Drafted reserve request",src:["Northwind quote","Incident INC1","Budget line "+e.line],guards:["Agents cannot approve or release funds","Needs a human approver"]})}`:""}</td><td class="tabular" style="color:${e.amt<0?"var(--bad)":"var(--good)"}">${e.amt<0?"−":"+"}${D$(Math.abs(e.amt))}</td><td class="tabular">${e.st==="Approved"?D$(bal):'<span class="muted">Not posted</span>'}</td><td><span class="pill ${e.st==="Approved"?"good":e.st==="Pending"?"warn":"bad"}">${e.st}</span><span class="sub">${esc(e.apr)}${e.st==="Approved"?" approved":" to approve"}</span></td><td>${e.st==="Pending"?(can?`<div class="row" style="flex-wrap:nowrap"><button class="btn primary" data-bud-led="${e.id}:ok">Approve</button><button class="btn" data-bud-led="${e.id}:no">Reject</button></div>`:`<span class="small muted">Needs ${esc(whoApproves(-e.amt,"Reserve release",e.req,{proj:e.p}).final)}</span>`):""}</td></tr>`}).join("")}
function resView(){const bal=resBal(),pend=resPend(),op=resOpen(),dr=drawn(),un=unfunded(),mine=B().led.filter(e=>e.st==="Pending"&&e.t==="draw"&&omarCan(-e.amt,"Reserve release",e.req,{proj:e.p})),xp=B().xf.filter(x=>x.st==="Pending");
 const ms=[{w:dr/op*100,c:"var(--p4)",l:"Drawn"},{w:pend/op*100,c:"var(--w1)",o:.8,l:"Pending"},{w:Math.max(0,bal-pend)/op*100,c:"var(--s3)",l:"Left"}];
 return `<div class="grid g4">${[stat("Opening reserve",C$(op),pc(op/T(B().lines).appr*100,1)+" of approved budgets","good"),stat("Drawn so far",C$(dr),B().led.filter(e=>e.st==="Approved"&&e.t==="draw").length+" approved draws","good"),stat("Balance now",C$(bal),C$(pend)+" pending requests",bal>=pend?"good":"bad"),stat("After pending",C$(bal-pend),un>0?C$(Math.max(0,un))+" of overrun still unfunded":"Nothing unfunded",headroom()>=0?"good":"bad")].join("")}</div>
 ${card("Reserve at a glance","The reserve is the CFO's pool for the whole portfolio. Project contingency stays inside each project's own budget.",`<div style="padding:4px 0 10px">${meter(ms)}</div><div class="row small muted" style="gap:16px"><span class="bud-key"><i style="background:var(--p4)"></i>Drawn ${C$(dr)}</span><span class="bud-key"><i style="background:var(--w1)"></i>Pending ${C$(pend)}</span><span class="bud-key"><i style="background:var(--s3)"></i>Left after pending ${C$(bal-pend)}</span></div>
  <div class="formula" style="margin-top:12px" data-role="metric">Reserve coverage = ${C$(bal)} balance ÷ ${C$(Math.max(0,netOver()-dr))} overrun not yet funded by an approved draw = ${METRICS.m_reserve.cur}%</div>
  <p class="story" data-role="story" style="margin:12px 0 0">${bal-pend>=Math.max(0,un)?`If both pending requests are approved, ${C$(bal-pend)} is left and ${C$(Math.max(0,un))} of forecast overrun still needs a source (PR3 ${C$(Math.max(0,T(PL("PR3")).fcst-T(PL("PR3")).appr-drawn("PR3")-pendP("PR3")))} and PR4 ${C$(Math.max(0,T(PL("PR4")).fcst-T(PL("PR4")).appr-drawn("PR4")-pendP("PR4")))}). The reserve covers it with ${C$(bal-pend-Math.max(0,un))} to spare.`:`The reserve cannot cover the unfunded overrun: ${C$(Math.max(0,un)-(bal-pend))} short. Cut scope or ask for more funding.`}</p>`,`<span class="row">${fchip("m_reserve")}<button class="btn primary" data-bud-refc>Request reserve</button></span>`)}
 ${(mine.length||xp.length)?card("Waiting for you","These are inside your delegated authority as CIO (up to "+D$(B().doa[CIOIDX()].max)+"). Approve or reject here.",`<div class="needs">${mine.map(e=>`<div class="need"><div class="ico warn">${ico("warn")}</div><div><b>${e.id}: ${C$(-e.amt)} from reserve to ${esc(PJ(e.p).short)}</b><span class="muted" data-role="story">${esc(e.why)}</span></div><div class="act"><button class="btn primary" data-bud-led="${e.id}:ok">Approve</button><button class="btn" data-bud-led="${e.id}:no">Reject</button></div></div>`).join("")}${xp.map(x=>`<div class="need"><div class="ico info">${ico("info")}</div><div><b>${x.id}: move ${C$(x.amt)} from ${x.from} to ${x.to}</b><span class="muted">${esc(x.why)} · Needs ${esc(x.apr)}</span></div><div class="act"><button class="btn" data-bud-xf="${x.id}:ok">Record ${esc(x.apr)} approval</button><button class="btn" data-bud-xf="${x.id}:no">Record rejection</button></div></div>`).join("")}</div>`):""}
 ${card("Reserve ledger","Every opening balance, draw and decision, in order. Approving or rejecting here posts to the ledger and writes the audit log.",wrap(`<table><thead><tr><th>Entry</th><th>Project</th><th>Reason</th><th>Amount</th><th>Balance</th><th>Status</th><th></th></tr></thead><tbody>${ledRows()}</tbody></table>`),`<button class="btn" data-bud-refc>Reforecast</button>`)}
 ${B().xf.length?card("Budget transfers between projects","Money moved by drag and drop, with the approver.",wrap(`<table><thead><tr><th>Transfer</th><th>From</th><th>To</th><th>Amount</th><th>Reason</th><th>Status</th></tr></thead><tbody>${B().xf.map(x=>`<tr><td><b>${x.id}</b><span class="sub">${dfmt(x.d)}</span></td><td>${esc(x.from)} · ${esc(x.line)}</td><td>${esc(x.to)}</td><td class="tabular">${D$(x.amt)}</td><td style="white-space:normal;min-width:220px" data-role="story">${esc(x.why)}</td><td><span class="pill ${x.st==="Approved"?"good":x.st==="Pending"?"warn":"bad"}">${x.st}</span><span class="sub">${esc(x.apr)}</span></td></tr>`).join("")}</tbody></table>`)):""}
 ${card("Approval rules that apply here","Reserve releases follow the delegation of authority. The invoice auto-approval rule from the Invoice approval screen sits underneath.",`<div class="grid g2"><div>${B().doa.map(t=>`<div class="row sp small" style="padding:5px 0;border-bottom:1px solid var(--hair)"><span><b>${t.id}</b> up to ${t.max===Infinity?"any amount":D$(t.max)}</span><span>${esc(t.role)}</span></div>`).join("")}</div><div class="small muted" data-role="story"><b>Invoices.</b> Rule r1 clears invoices up to ${D$((S.rules[0]&&S.rules[0].amt)||25000)} from vendors with an index of ${S.rules[0]&&S.rules[0].idx||.85} or better when they match the PO. Rule r4 sends anything over ${D$(((S.rules[3]&&S.rules[3].big)||100000))} to the CFO. Reserve draws, transfers and change orders are not covered by those rules and always follow the tiers on the left.<div class="row" style="margin-top:12px"><button class="btn" data-go="bud_doa">Open delegation of authority</button><button class="btn" data-go="inv">Open invoice rules</button></div></div></div>`)}`}
REG("bud_over","Budgets overall","portfolio","M4 19V9M10 19V5M16 19v-7M22 19H2",()=>{syncM();const t=T(B().lines),b=burn(),bal=resBal(),pend=resPend();
 return `<div class="screen">${hero("Budgets overall · FY27 (Jul 2026 to Jun 2027)","The portfolio is "+pc((t.fcst-t.appr)/t.appr*100,1)+" over budget, and the reserve can cover it",`Approved <b>${C$(t.appr)}</b>, forecast <b>${C$(t.fcst)}</b>, so <b>${sgn(t.fcst-t.appr)}</b> over. Vendor services is <b>${C$(Math.max(0,sum(B().lines.filter(l=>l.cat==="Vendor"),l=>Math.max(0,l.comm-l.appr))))}</b> over commitment because of Lumen change order CO-2, and the larger hosting tier adds <b>${C$(LN("PR1-CLD").fcst-LN("PR1-CLD").appr)}</b>. The management reserve holds <b>${C$(bal)}</b>, <b>${C$(bal-pend)}</b> after the two requests waiting for approval.`,`<div class="row">${fchip("m_budvar")}${fchip("m_commit")}${fchip("m_reserve")}${fchip("m_capex")}<button class="btn primary" data-bud-refc>Reforecast</button>${whyPop("A CIO sees approved against forecast first, then what is over, why, and which decision unblocks it.")}</div>`)}${lensNote()}
 ${views("budv",["Overview","By project","By category","Forecast","Reserve and approvals"],[overView(),projView(),catView(),fcView(),resView()])}</div>`});
/* ---- forms: edit line, reforecast, transfer ---- */
const lineOpts=()=>B().lines.map(l=>[l.id,l.id+" · "+l.n]);
function editForm(id){const l=LN(id);if(!l)return;B().sel=id;
 openF({id:"bud_edit",title:"Edit budget line "+l.id,story:`Change what this line says. A new approved amount changes the portfolio total, so it needs approval at the tier shown below. Forecast and commitment changes are recorded as they are.`,submit:"Save line",
 fields:[{section:"Line"},{k:"n",label:"Description",type:"text",req:true},{k:"own",label:"Budget owner",type:"people",req:true},{k:"cat",label:"Category",type:"chips",opts:CATS},{k:"dept",label:"Department and cost center",type:"select",opts:DEPTS.map(d=>[d[0],d[1]+" ("+d[2]+")"])},
  {section:"Amounts"},{k:"appr",label:"Approved",type:"money",req:true,help:"Changing this moves the portfolio total; use Transfer by dragging when moving money between projects."},{k:"comm",label:"Committed (POs and signed contracts)",type:"money"},{k:"fcst",label:"Forecast at completion",type:"money",req:true},
  {section:"The story"},{k:"why",label:"Why the forecast differs from approved",type:"longtext",ai:{label:"Draft with Claude",fn:v=>{const d=v.fcst-v.appr;return d>0?`Forecast is ${D$(d)} above approved. The main driver is ${l.cat.toLowerCase()} cost on ${l.n.toLowerCase()}.`:d<0?`Forecast is ${D$(-d)} under approved because the work is coming in cheaper than estimated.`:""}}},{k:"fix",label:"Remediation",type:"longtext",ai:{label:"Suggest",fn:v=>v.fcst>v.appr?"Draw from the management reserve if the cause is outside the project's control, or absorb it by moving a task. Decide at the next steering group.":"Release the saving to the reserve at project close."}}],
 defaults:{n:l.n,own:l.own,cat:l.cat,dept:l.dept,appr:l.appr,comm:l.comm,fcst:l.fcst,why:l.why,fix:l.fix},
 live:v=>{const d=(+v.appr||0)-l.appr,r=whoApproves(Math.abs(d),"Budget transfer",v.own,{proj:l.p}),va=(+v.fcst||0)-(+v.appr||0);liveBox(`<div class="rem"><div class="ico">${ico("info")}</div><div><b>Variance after saving: ${va>0?"+":va<0?"−":""}${D$(Math.abs(va))}</b><div class="muted small">Forecast ${D$(+v.fcst||0)} − Approved ${D$(+v.appr||0)}. ${+v.comm>+v.appr?"Committed is above approved, so this line stays flagged as over commitment. ":""}</div>${d?`<div class="small" style="margin-top:6px">Approved changes by <b>${sgn(d)}</b>: ${r.chain.map(c=>c.n).slice(-1)[0]} must approve (tier ${r.tier.id}).</div>`:""}</div></div>`)},
 onSubmit:v=>{if(+v.fcst<l.act||+v.comm<l.act)return {close:false,toast:"Forecast and committed cannot be below the "+D$(l.act)+" already paid.",audit:"rejected: below actual"};
  const d=+v.appr-l.appr;
  Object.assign(l,{n:v.n,own:v.own,cat:v.cat,dept:v.dept,appr:+v.appr,comm:+v.comm,fcst:+v.fcst,why:v.why||"",fix:v.fix||""});render();return {toast:l.id+" updated",audit:l.id+" "+(d?"approved "+sgn(d)+", ":"")+"forecast "+D$(l.fcst)}}})}
function refcForm(lineId){const l0=lineId?LN(lineId):B().lines.find(l=>l.id==="PR4-VEN");
 openF({id:"bud_refc",title:"Reforecast a budget line",story:"Tell the portfolio what the line will really cost and where the money comes from. A reserve request goes into the reserve ledger and is approved at the tier the delegation of authority sets.",submit:"Submit reforecast",
 fields:[{section:"What changes"},{k:"line",label:"Budget line",type:"select",req:true,opts:lineOpts()},{k:"newf",label:"New forecast at completion",type:"money",req:true,help:"The full amount, not the increase."},
  {section:"Why"},{k:"why",label:"Reason",type:"longtext",req:true,ph:"What changed since the last forecast?",ai:{label:"Draft with Claude",fn:v=>{const l=LN(v.line);if(!l)return null;const d=(+v.newf||l.fcst)-l.fcst;return (l.why||"The estimate changed.")+" Evidence: "+(l.cat==="Vendor"?"signed change order and Lumen milestone plan":l.cat==="Cloud"?"Northwind quote and incident INC1":"updated estimate from "+l.own)+". Effect: "+(d>=0?"+":"−")+D$(Math.abs(d))+" on forecast."}}},
  {section:"Source of funds"},{k:"src",label:"Fund the increase from",type:"chips",opts:["Management reserve","Project contingency","Another budget line","Not funded yet"],req:true},{k:"res",label:"Amount from the reserve",type:"money",show:v=>v.src==="Management reserve",help:"Usually the whole increase."},{k:"req",label:"Requested by",type:"select",opts:["Priya Shah","Dev Rao","Tom Becker","Maya Ortiz","Jordan Lee"]}],
 defaults:{line:l0.id,newf:l0.fcst,src:"Management reserve",res:Math.max(0,l0.fcst-l0.appr),req:l0.own,why:l0.why||""},
 live:v=>{const l=LN(v.line);if(!l)return;const inc=Math.max(0,(+v.newf||0)-l.fcst),res=v.src==="Management reserve"?(+v.res||0):0,r=whoApproves(res||inc,"Reserve release",v.req,{proj:l.p}),bal=resBal(),pe=resPend();
  liveBox(`<div class="rem"><div class="ico">${ico("info")}</div><div><b>Forecast moves ${D$(l.fcst)} to ${D$(+v.newf||0)} (${sgn((+v.newf||0)-l.fcst)}); variance to approved becomes ${sgn((+v.newf||0)-l.appr)}</b><div class="small muted" style="margin-top:4px">${res?`Reserve after this request: ${D$(bal-pe)} now free − ${D$(res)} = <b>${D$(bal-pe-res)}</b>${bal-pe-res<0?" (not enough)":""}. `:""}${v.src==="Not funded yet"?"The line shows as unfunded overrun until a source is chosen. ":""}</div>${res?`<div class="small" style="margin-top:6px"><b>${esc(r.fname)}</b> approves (tier ${r.tier.id}). ${r.why.slice(-1)[0]||""}</div>`:""}</div></div>`)},
 onSubmit:v=>{const l=LN(v.line);if(+v.newf<l.act)return {close:false,toast:"Forecast cannot be below the "+D$(l.act)+" already paid.",audit:"rejected"};
  const res=v.src==="Management reserve"?+v.res||0:0;const old=l.fcst;
  if(res>resBal()-resPend())return {close:false,toast:"The reserve has "+D$(resBal()-resPend())+" free. Lower the amount or choose another source.",audit:"rejected: reserve too low"};
  l.fcst=+v.newf;l.why=v.why;let msg=l.id+" forecast "+D$(old)+" to "+D$(l.fcst);
  if(res>0){const can=delegateCan(res,"Reserve release",v.req,{proj:l.p}),r=whoApproves(res,"Reserve release",v.req,{proj:l.p});const e=addLed({t:"draw",amt:-res,p:l.p,line:l.id,why:v.why,req:v.req,apr:can?"Omar (CIO)":r.final,st:can?"Approved":"Pending"});msg+=`; ${e.id} ${can?"approved by you":"pending "+r.final}`}
  render();return {toast:msg,audit:msg}}})}
function xferForm(lineId,to){const l=LN(lineId);if(!l||l.p===to)return;const from=l.p,hr=Math.max(0,l.appr-l.comm);
 openF({id:"bud_xfer",title:`Move budget from ${from} to ${to}`,story:`You dropped ${esc(l.id)} (${esc(l.n)}) onto ${esc(PJ(to).short)}. Only money that is not yet committed can move. Nothing changes until you confirm below.`,submit:"Confirm the transfer",
 fields:[{k:"amt",label:"Amount to move",type:"money",req:true,help:hr?"Uncommitted on this line: "+D$(hr)+".":"This line has nothing uncommitted. A committed amount needs a contract change first."},{k:"req",label:"Requested by",type:"select",opts:["Priya Shah","Dev Rao","Tom Becker","Maya Ortiz"]},{k:"why",label:"Reason",type:"longtext",req:true,ai:{label:"Draft with Claude",fn:v=>`${PJ(to).short} needs the funds more: forecast ${C$(T(PL(to)).fcst)} against approved ${C$(T(PL(to)).appr)}. ${l.id} has ${C$(hr)} that nothing is committed against.`}}],
 defaults:{amt:hr,req:PJ(from).owner,why:""},
 live:v=>{const a=+v.amt||0,A=T(PL(from)),Bp=T(PL(to)),r=whoApproves(a,"Budget transfer",v.req,{proj:from}),can=delegateCan(a,"Budget transfer",v.req,{proj:from}),over=l.fcst>l.appr-a;
  liveBox(`<div class="grid g2" style="gap:10px"><div class="rem"><div><b>${esc(PJ(from).short)}</b><div class="small muted">Approved ${C$(A.appr)} → <b>${C$(A.appr-a)}</b><br>Variance ${sgn(A.fcst-A.appr)} → <b>${sgn(A.fcst-A.appr+a)}</b></div></div></div><div class="rem"><div><b>${esc(PJ(to).short)}</b><div class="small muted">Approved ${C$(Bp.appr)} → <b>${C$(Bp.appr+a)}</b><br>Variance ${sgn(Bp.fcst-Bp.appr)} → <b>${sgn(Bp.fcst-Bp.appr-a)}</b></div></div></div></div>
  <div class="rem"><div class="ico ${can?"":"warn"}">${ico(can?"check":"warn")}</div><div><b>${can?"Inside your authority":"Needs "+esc(r.fname)}</b><div class="small muted">${esc(r.why.join(" "))}</div>${a>hr?`<div class="small" style="color:var(--bad);margin-top:4px">${D$(a)} is more than the ${D$(hr)} uncommitted.</div>`:""}${over&&a<=hr?`<div class="small" style="color:var(--warn);margin-top:4px">This leaves ${esc(l.id)} forecast above its approved amount.</div>`:""}</div></div>`)},
 onSubmit:v=>{const a=+v.amt;if(a<=0||a>hr)return {close:false,toast:"Amount must be between $1 and the "+D$(hr)+" uncommitted.",audit:"rejected transfer"};
  const can=delegateCan(a,"Budget transfer",v.req,{proj:from}),r=whoApproves(a,"Budget transfer",v.req,{proj:from});
  const x={id:"TR-"+String(B().nx.tr++).padStart(2,"0"),d:iso(TODAYD),from,to,line:l.id,amt:a,why:v.why,req:v.req,apr:can?"Omar (CIO)":r.final,st:can?"Approved":"Pending"};B().xf.push(x);if(can)applyXf(x);
  render();return {toast:can?`${C$(a)} moved from ${from} to ${to}`:`Transfer ${x.id} sent to ${r.final}`,audit:`${x.id} ${from} to ${to} ${D$(a)} ${x.st}`}}})}
function applyXf(x){const l=LN(x.line);l.appr-=x.amt;let t=B().lines.find(q=>q.p===x.to&&q.cat===l.cat);if(!t){t={id:x.to+"-"+l.cat.slice(0,3).toUpperCase(),p:x.to,cat:l.cat,n:l.cat+" (moved from "+x.from+")",dept:PJ(x.to).id==="PR4"?"FN":"IT",appr:0,comm:0,act:0,fcst:0,own:PJ(x.to).owner,why:"",fix:""};B().lines.push(t)}t.appr+=x.amt;x.st="Approved"}
DND.on("budmove",(id,from,to)=>{if(from===to)return;xferForm(id,to)});
/* ---- delegated clicks for screen 1 ---- */
document.addEventListener("click",e=>{
 let t=e.target.closest("[data-bud-edit]");if(t){editForm(t.dataset.budEdit);return}
 t=e.target.closest("[data-bud-refc]");if(t){refcForm();return}
 t=e.target.closest("[data-bud-led]");if(t){const [id,a]=t.dataset.budLed.split(":"),en=B().led.find(x=>x.id===id);if(!en||en.st!=="Pending")return;
  if(a==="ok"){if(-en.amt>resBal()){toast("The reserve balance is "+D$(resBal())+", below this request.","bad");return}en.st="Approved";en.apr="Omar (CIO)";audit("approved reserve draw",en.id+" "+D$(-en.amt)+" to "+en.p);toast(en.id+" approved. Reserve balance is now "+D$(resBal()),"good")}
  else{en.st="Rejected";en.apr="Omar (CIO)";audit("rejected reserve draw",en.id);toast(en.id+" rejected. The forecast stays unfunded.","warn")}render();return}
 t=e.target.closest("[data-bud-xf]");if(t){const [id,a]=t.dataset.budXf.split(":"),x=B().xf.find(q=>q.id===id);if(!x||x.st!=="Pending")return;if(a==="ok"){applyXf(x);audit("recorded approval",x.id+" by "+x.apr);toast(x.id+" applied: "+D$(x.amt)+" moved","good")}else{x.st="Rejected";audit("recorded rejection",x.id);toast(x.id+" rejected","warn")}render();return}
});
/* kit re-renders the form on blur, which steals focus when the user clicks the next field. For bud_ forms store the value here and re-render later, only when other fields depend on it. */
document.addEventListener("change",e=>{const t=e.target,k=t.dataset&&t.dataset.fk;if(!k||!k.startsWith("bud_"))return;const [fid,f]=k.split(":"),st=FORMST[fid],sp=FORMSPEC[fid];if(!st||!sp)return;
 if(t.type==="file"){st.vals[f]=t.files&&t.files[0]?t.files[0].name:"";}else st.vals[f]=t.type==="number"&&t.value!==""?+t.value:t.value;
 if(fid==="bud_refc"&&f==="line"){const l=LN(t.value);if(l){st.vals.newf=l.fcst;st.vals.res=Math.max(0,l.fcst-l.appr);st.vals.req=l.own;st.vals.why=l.why||""}}
 e.stopImmediatePropagation();
 const dep=sp.fields.some(x=>x.show)||(fid==="bud_refc"&&f==="line")||t.type==="file";if(dep)setTimeout(()=>{if(document.activeElement===t||!document.activeElement||document.activeElement===document.body||!document.activeElement.closest(".fbody"))refreshForm(fid);else{const id=document.activeElement.id;refreshForm(fid);const n=id&&document.getElementById(id);if(n&&n.focus)n.focus()}},160);
 setTimeout(()=>{if(sp.live)sp.live(formValues(fid),fid)},200)},true);
document.addEventListener("change",e=>{const t=e.target,k=t.dataset&&t.dataset.fk;if(!k||!k.startsWith("bud_"))return;const [fid,f]=k.split(":");
 if(fid==="bud_refc"&&f==="line"){const l=LN(t.value),st=FORMST[fid];if(l){st.vals.newf=l.fcst;st.vals.res=Math.max(0,l.fcst-l.appr);st.vals.req=l.own;st.vals.why=l.why||"";refreshForm(fid)}}
 setTimeout(()=>{const sp=FORMSPEC[fid];if(sp&&sp.live)sp.live(formValues(fid),fid)},20)});
document.addEventListener("input",e=>{const k=e.target.dataset&&e.target.dataset.fk;if(!k||!k.startsWith("bud_"))return;const fid=k.split(":")[0];setTimeout(()=>{const sp=FORMSPEC[fid];if(sp&&sp.live)sp.live(formValues(fid),fid)},0)});
document.addEventListener("click",e=>{const t=e.target.closest("[data-fchip],[data-fmulti],[data-ftog],[data-fai]");if(!t)return;const v=t.dataset.fchip||t.dataset.fmulti||t.dataset.ftog||t.dataset.fai;if(!v||!v.startsWith("bud_"))return;const fid=v.split(":")[0];setTimeout(()=>{const sp=FORMSPEC[fid];if(sp&&sp.live)sp.live(formValues(fid),fid)},30)});
/* ---------- 2. Financial model ---------- */
function amortSplit(p,f){const L=B().life;let sw=0,hw=0;PS(p).forEach(q=>{const ls=PL(q),h=sum(ls.filter(l=>l.cat==="Hardware"),capOf),s=sum(ls.filter(l=>l.cat!=="Hardware"),capOf),g=goLive(q).mi+1;
 const mon=life=>Math.max(0,Math.min(f*12+12,g+life*12)-Math.max(f*12,g));sw+=s/(L*12)*mon(L);hw+=h/48*mon(4)});return {sw,hw}}
const mPL=()=>B().mproj==="all"?B().lines:PL(B().mproj);
const mpName=()=>B().mproj==="all"?"the whole portfolio":PJ(B().mproj).short;
const monYr=mi=>new Date(Date.UTC(2026,6+mi,1)).toLocaleDateString("en-US",{month:"short",year:"numeric",timeZone:"UTC"});
function costPlanHTML(){const p=B().mproj;if(p==="all")return `<div class="grid g2">${PROJ.map(q=>`<div class="tile glass"><span class="lbl">${esc(q.short)}</span><span class="big num" data-role="metric">${C$(T(PL(q.id)).fcst)}</span><span class="delta ${tcls(T(PL(q.id)).fcst,T(PL(q.id)).appr)}">${sgn(T(PL(q.id)).fcst-T(PL(q.id)).appr)} vs approved</span></div>`).join("")}</div><p class="muted small">Select one project to see its labor plan by role.</p>`;
 const cp=B().cp[p],lab=laborPlan(p),ll=PL(p).find(l=>l.cat==="Labor"),non=PL(p).filter(l=>l.cat!=="Labor");
 const rows=cp.map((r,i)=>`<tr><td><b>${esc(r[0])}</b></td><td class="tabular">${D$(r[1])}</td><td><input class="fin bud-num" type="number" step="0.5" min="0" data-bud-cp="${i}:2" value="${r[2]}" aria-label="FTE for ${esc(r[0])}"></td><td><input class="fin bud-num" type="number" step="1" min="0" max="12" data-bud-cp="${i}:3" value="${r[3]}" aria-label="Months for ${esc(r[0])}"></td><td class="tabular"><b>${D$(cpCost(r))}</b></td></tr>`).join("");
 const tot=lab+sum(non,l=>l.fcst);
 return `${wrap(`<table style="min-width:620px"><thead><tr><th>Role</th><th>Loaded rate per FTE-month</th><th>FTE</th><th>Months in FY27</th><th>Cost = rate × FTE × months</th></tr></thead><tbody>${rows}<tr><td><b>Labor plan</b></td><td></td><td class="tabular">${sum(cp,r=>r[2])} FTE</td><td></td><td class="tabular"><b>${D$(lab)}</b></td></tr></tbody></table>`)}
 <div class="row" style="margin:12px 0"><span class="pill ${lab===ll.fcst?"good":"warn"}" data-role="metric">Budget labor forecast ${D$(ll.fcst)} · plan ${lab>ll.fcst?"+":lab<ll.fcst?"−":""}${D$(Math.abs(lab-ll.fcst))}</span>${lab!==ll.fcst?`<button class="btn primary" data-bud-push="${ll.id}">Push labor plan to the forecast</button>`:""}<button class="btn" data-bud-addrole>Add a role</button></div>
 ${wrap(`<table style="min-width:620px"><thead><tr><th>Other cost lines (from the budget)</th><th>Category</th><th>Approved</th><th>Forecast</th><th></th></tr></thead><tbody>${non.map(l=>`<tr><td>${lineName(l)}</td><td>${l.cat}</td><td class="tabular">${D$(l.appr)}</td><td class="tabular">${D$(l.fcst)}</td><td><button class="btn" data-bud-edit="${l.id}">Edit</button></td></tr>`).join("")}<tr><td><b>Total FY27 cost plan</b></td><td></td><td class="tabular"><b>${D$(T(PL(p)).appr)}</b></td><td class="tabular"><b>${D$(tot)}</b></td><td></td></tr></tbody></table>`)}`}
function capHTML(){const ls=mPL(),p=B().mproj,tot=T(ls).fcst,cap=capTot(ls);
 const sum_=(f)=>sum(ls.filter(f),l=>l.fcst);
 const stage=p==="all"?null:B().mp[p],lv=sum_(l=>l.cat==="Labor"||l.cat==="Vendor");
 const st=stage?`<div class="grid g3 bud-stages">${[["Preliminary project stage",stage.pre,"Expense","Evaluating vendors, selecting, proof of concept. ASC 350-40-25-1","--w1"],["Application development stage",stage.dev,"Capitalize","Design, coding, installation, testing. Directly associated payroll and external costs. ASC 350-40-25-2","--u3"],["Post-implementation stage",100-stage.pre-stage.dev,"Expense","Training, maintenance, data conversion. Upgrades that add function are capitalized. ASC 350-40-25-6","--s3"]].map(x=>`<div class="tile glass" style="border-top:4px solid var(${x[4]})"><span class="lbl">${x[0]}</span><span class="big num" data-role="metric">${x[1]}%</span><span class="small muted">${x[3]}</span><span class="pill ${x[2]==="Capitalize"?"metric":"mute"}">${x[2]} · ${C$(lv*x[1]/100)} of labor and vendor cost</span></div>`).join("")}</div>`:"";
 const rows=ls.map(l=>{const sh=capShare(l),m=B().mp[l.p];const rule=l.cat==="Labor"?`${m.dev}% development stage × ${m.dir}% directly associated payroll`:l.cat==="Vendor"?`${m.dev}% development stage (external direct cost)`:l.cat==="Hardware"?"Always capital: property and equipment (ASC 360)":l.cat==="Cloud"?"Hosting is a service contract, expensed":"Subscriptions are expensed";
  return `<tr><td>${lineName(l)}</td><td class="tabular">${D$(l.fcst)}</td><td style="white-space:normal;min-width:240px" class="small">${rule}</td><td class="tabular">${pc(sh*100,0)}</td><td class="tabular"><b>${D$(l.fcst*sh)}</b></td><td class="tabular">${D$(l.fcst*(1-sh))}</td></tr>`}).join("");
 return `${st}<div class="formula" data-role="metric" style="margin:12px 0">CapEx = Σ line forecast × capital share · Labor share = development % × directly associated payroll % · ${C$(tot)} forecast → <b>${C$(cap)} CapEx</b> (${pc(cap/tot*100,1)}) and <b>${C$(tot-cap)} OpEx</b></div>
 ${wrap(`<table><thead><tr><th>Line</th><th>FY27 forecast</th><th>Rule applied</th><th>Capital share</th><th>CapEx</th><th>OpEx</th></tr></thead><tbody>${rows}<tr><td><b>Total</b></td><td class="tabular"><b>${D$(tot)}</b></td><td></td><td class="tabular">${pc(cap/tot*100,1)}</td><td class="tabular"><b>${D$(cap)}</b></td><td class="tabular"><b>${D$(tot-cap)}</b></td></tr></tbody></table>`)}
 <p class="small muted" style="margin-top:10px">Cloud hosting fees are expensed. Implementation costs of a cloud computing arrangement are capitalized as a prepaid asset under ASU 2018-15 and shown in operating expense; this prototype treats the Northwind tier change as hosting only.</p>`}
function depHTML(){const rows=[0,1,2,3,4,5].map(f=>({fy:"FY"+(27+f),...amortSplit(B().mproj,f)})),mx=Math.max(1,...rows.map(r=>r.sw+r.hw));
 const gl=PS(B().mproj).map(q=>`${PJ(q).short}: ${monYr(goLive(q).mi)}`).join(" · "),ls=mPL(),hw=sum(ls.filter(l=>l.cat==="Hardware"),capOf),sw=capTot(ls)-hw;
 const W=620,H=220,Lx=48,bw=(W-Lx-10)/6;let g="";[0,.5,1].forEach(k=>{const y=16+(H-46)*(1-k);g+=`<line class="grid-l" x1="${Lx}" x2="${W-6}" y1="${y}" y2="${y}"/><text class="ax" x="${Lx-6}" y="${y+4}" text-anchor="end">${C$(mx*k)}</text>`});
 rows.forEach((r,i)=>{const x=Lx+i*bw+bw*.2,w=bw*.6,hS=(H-46)*r.sw/mx,hH=(H-46)*r.hw/mx,yb=H-30;g+=`<rect x="${x}" y="${yb-hS}" width="${w}" height="${hS}" rx="5" fill="var(--u3)"><title>${r.fy} software ${D$(r.sw)}</title></rect><rect x="${x}" y="${yb-hS-hH}" width="${w}" height="${hH}" rx="5" fill="var(--w1)"><title>${r.fy} hardware ${D$(r.hw)}</title></rect><text class="ax" x="${x+w/2}" y="${H-12}" text-anchor="middle">${r.fy}</text><text class="ax bud-vl" x="${x+w/2}" y="${yb-hS-hH-6}" text-anchor="middle">${C$(r.sw+r.hw)}</text>`});
 return `<div class="formula" data-role="metric">Amortization = Software CapEx ${C$(sw)} ÷ (${B().life} years × 12) × months in service · Hardware ${C$(hw)} ÷ (4 years × 12) × months in service · straight line from the month after go-live</div>
 <p class="small muted" style="margin:8px 0">Go-live from the master schedule: ${gl}</p>
 <div class="grid g2" style="align-items:start"><svg class="chart" viewBox="0 0 ${W} ${H}" width="100%" role="img" aria-label="Amortization and depreciation by fiscal year">${g}</svg>
 ${wrap(`<table style="min-width:420px"><thead><tr><th>Year</th><th>Software</th><th>Hardware</th><th>Total expense</th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${r.fy}</b></td><td class="tabular">${D$(r.sw)}</td><td class="tabular">${D$(r.hw)}</td><td class="tabular"><b>${D$(r.sw+r.hw)}</b></td></tr>`).join("")}<tr><td><b>Total</b></td><td class="tabular">${D$(sum(rows,r=>r.sw))}</td><td class="tabular">${D$(sum(rows,r=>r.hw))}</td><td class="tabular"><b>${D$(sum(rows,r=>r.sw+r.hw))}</b></td></tr></tbody></table>`)}</div>
 <div class="row small muted" style="gap:16px"><span class="bud-key"><i style="background:var(--u3)"></i>Software amortization</span><span class="bud-key"><i style="background:var(--w1)"></i>Hardware depreciation</span></div>`}
function pairBars(rows){const W=620,H=230,Lx=50,mx=Math.max(...rows.map(r=>Math.max(r.cost,r.ben)))*1.1,bw=(W-Lx-8)/rows.length;let g="";[0,.5,1].forEach(k=>{const y=14+(H-44)*(1-k);g+=`<line class="grid-l" x1="${Lx}" x2="${W-6}" y1="${y}" y2="${y}"/><text class="ax" x="${Lx-6}" y="${y+4}" text-anchor="end">${C$(mx*k)}</text>`});
 rows.forEach((r,i)=>{const x=Lx+i*bw+bw*.12,w=bw*.36,yb=H-30,hc=(H-44)*r.cost/mx,hb=(H-44)*r.ben/mx;g+=`<rect x="${x}" y="${yb-hc}" width="${w}" height="${hc}" rx="4" fill="var(--e4)"><title>${r.fy} cost ${D$(r.cost)}</title></rect><rect x="${x+w+3}" y="${yb-hb}" width="${w}" height="${hb}" rx="4" fill="var(--s3)"><title>${r.fy} benefit ${D$(r.ben)}</title></rect><text class="ax" x="${x+w}" y="${H-12}" text-anchor="middle">${r.fy}</text>`});
 return `<svg class="chart" viewBox="0 0 ${W} ${H}" width="100%" role="img" aria-label="Cost and benefit by fiscal year">${g}</svg><div class="row small muted" style="gap:16px"><span class="bud-key"><i style="background:var(--e4)"></i>Cost</span><span class="bud-key"><i style="background:var(--s3)"></i>Benefit</span></div>`}
function tcoHTML(){const p=B().mproj,sc=B().scen,mult=SCEN[sc][2],g=B().grow/100;
 const comp=y=>{const o={build:0,cld:0,lic:0,sup:0};PS(p).forEach(q=>{if(y===0)o.build+=T(PL(q)).fcst;else{const r=B().run[q],f=Math.pow(1+g,y-1);o.cld+=r.cld*f;o.lic+=r.lic*f;o.sup+=(r.sup+r.ven)*f}});Object.keys(o).forEach(k=>o[k]*=mult);return o};
 const cs=[0,1,2,3,4].map(comp),tot=sum(cs,c=>c.build+c.cld+c.lic+c.sup);
 const rs=roi(p),mxc=Math.max(...cs.map(c=>c.build+c.cld+c.lic+c.sup));
 const stack=cs.map((c,i)=>{const t=c.build+c.cld+c.lic+c.sup;return `<div class="bud-tc"><span class="small"><b>FY${27+i}</b></span>${meter([{w:c.build/mxc*100,c:"var(--p4)",l:"Build"},{w:c.cld/mxc*100,c:"var(--s3)",l:"Hosting"},{w:c.lic/mxc*100,c:"var(--e4)",l:"Licences"},{w:c.sup/mxc*100,c:"var(--w1)",l:"Support"}])}<span class="small tabular">${C$(t)}</span></div>`}).join("");
 const terms=rs.rows.map(r=>`${r.net<0?"(−":"("}${C$(Math.abs(r.net))}${r.net<0?")":")"}${r.y?` ÷ ${(1/r.df).toFixed(3)}`:""}`).join(" + ");
 const pbTxt=rs.pb==null?"beyond FY31":`${rs.pb.toFixed(1)} years, about ${monYr(Math.round(rs.pb*12))}`;
 const cmp=Object.keys(SCEN).map(k=>{const r=roi(p,B().rate,k);return `<tr${k===sc?' style="outline:2px solid var(--accent)"':""}><td><b>${SCEN[k][0]}</b><span class="sub">${SCEN[k][3]}</span></td><td class="tabular">${C$(r.sb)}</td><td class="tabular">${C$(r.sc)}</td><td class="tabular"><b>${r.npv<0?"−":""}${C$(Math.abs(r.npv))}</b></td><td class="tabular">${pc(r.roi*100)}</td><td class="tabular">${r.pb==null?"Beyond FY31":r.pb.toFixed(1)+" yrs"}</td></tr>`}).join("");
 return `<div class="grid g4">${[stat("5-year TCO",C$(tot),SCEN[sc][0]+", "+mpName(),"good"),stat("NPV at "+B().rate+"%",(rs.npv<0?"−":"")+C$(Math.abs(rs.npv)),rs.npv>=0?"Worth doing at this rate":"Does not pay back at this rate",rs.npv>=0?"good":"bad"),stat("ROI",pc(rs.roi*100),"Benefit-cost ratio "+rs.bcr.toFixed(2),rs.roi>=.3?"good":rs.roi>=.1?"warn":"bad"),stat("Payback",rs.pb==null?"Beyond FY31":rs.pb.toFixed(1)+" yrs",rs.pb==null?"Cumulative net stays negative":monYr(Math.round(rs.pb*12)),rs.pb!=null&&rs.pb<=3.5?"good":"warn")].join("")}</div>
 <div class="grid g2" style="align-items:start">${card("Total cost of ownership by year","FY27 is the build; FY28 onward is incremental run cost, growing "+B().grow+"% a year.",stack+`<div class="row small muted" style="gap:14px;margin-top:8px"><span class="bud-key"><i style="background:var(--p4)"></i>Build</span><span class="bud-key"><i style="background:var(--s3)"></i>Hosting</span><span class="bud-key"><i style="background:var(--e4)"></i>Licences</span><span class="bud-key"><i style="background:var(--w1)"></i>Support</span></div>${p!=="all"?`<div class="row" style="margin-top:10px"><button class="btn" data-bud-runedit>Edit run costs</button></div>`:""}`)}
 ${card("Cost against benefit","Benefits come from the Benefits realization register, shifted by the scenario.",pairBars(rs.rows))}</div>
 ${card("Return on investment, with the arithmetic","Every number below is computed from the cost plan, the run costs and the benefits register.",`${wrap(`<table style="min-width:640px"><thead><tr><th>Year</th><th>Cost</th><th>Benefit</th><th>Net</th><th>Discount factor 1 ÷ (1 + ${B().rate}%)^t</th><th>Present value</th><th>Cumulative net</th></tr></thead><tbody>${rs.rows.map(r=>`<tr><td><b>${r.fy}</b> <span class="muted small">t = ${r.y}</span></td><td class="tabular">${D$(r.cost)}</td><td class="tabular">${D$(r.ben)}</td><td class="tabular" style="color:${r.net<0?"var(--bad)":"var(--good)"}">${r.net<0?"−":""}${D$(Math.abs(r.net))}</td><td class="tabular">${r.df.toFixed(3)}</td><td class="tabular">${r.pv<0?"−":""}${D$(Math.abs(r.pv))}</td><td class="tabular">${r.cum<0?"−":""}${D$(Math.abs(r.cum))}</td></tr>`).join("")}</tbody></table>`)}
 <div class="formula" data-role="metric" style="margin-top:12px">NPV = Σ (Benefit − Cost) ÷ (1 + ${B().rate}%)^t = ${terms} = <b>${rs.npv<0?"−":""}${D$(Math.abs(rs.npv))}</b></div>
 <div class="formula" data-role="metric" style="margin-top:8px">ROI = (Total benefit ${D$(rs.sb)} − Total cost ${D$(rs.sc)}) ÷ Total cost ${D$(rs.sc)} = <b>${pc(rs.roi*100,1)}</b> · Payback = first year cumulative net turns positive = <b>${pbTxt}</b></div>`,`<span class="row">${fchip("m_roi")}</span>`)}
 ${card("Scenarios side by side","Same discount rate, different assumptions. The highlighted row is the one selected above.",wrap(`<table style="min-width:600px"><thead><tr><th>Scenario</th><th>Benefit</th><th>Cost</th><th>NPV</th><th>ROI</th><th>Payback</th></tr></thead><tbody>${cmp}</tbody></table>`))}`}
function shareRows(){const p=B().mproj;const ps=p==="all"?PROJ.map(x=>x.id):[p];return ps}
function showHTML(){const ps=PROJ.map(x=>x.id),M=ps.map(q=>({q,f:T(PL(q)).fcst,pct:allocPct(q)}));
 const dep=DEPTS.map(d=>({d,row:M.map(m=>(m.pct[d[0]]||0)/100*m.f)}));
 const tot=sum(dep,x=>sum(x.row,v=>v));const mx=Math.max(...dep.map(x=>sum(x.row,v=>v)));
 const drv={usage:"Usage report",headcount:"Headcount",equal:"Equal split",fixed:"Fixed percentages"};
 return `<div class="row" style="margin-bottom:6px"><div class="recchips"><button class="chip" data-bud-sbm="showback" aria-pressed="${B().showMode==="showback"}">Showback: report only</button><button class="chip" data-bud-sbm="chargeback" aria-pressed="${B().showMode==="chargeback"}">Chargeback: post to cost centers</button></div></div>
 <p class="small muted" data-role="story" style="margin:0 0 10px">${B().showMode==="showback"?"Showback tells each department what its services cost. No money moves. It is the right first step before chargeback.":"Chargeback would post these amounts to each department's cost center at month end. In this prototype nothing is posted; the view shows the journal that would be created."}</p>
 ${wrap(`<table style="min-width:760px"><thead><tr><th>Department</th>${M.map(m=>`<th>${m.q}</th>`).join("")}<th>Total</th><th style="min-width:150px">Share</th></tr></thead><tbody>${dep.map(x=>{const t=sum(x.row,v=>v);return `<tr><td><b>${esc(x.d[1])}</b><span class="sub">${x.d[2]}${B().showMode==="chargeback"?" · debit":""}</span></td>${x.row.map(v=>`<td class="tabular">${v?D$(v):'<span class="muted">0</span>'}</td>`).join("")}<td class="tabular"><b>${D$(t)}</b></td><td>${meter([{w:t/mx*100,c:"var(--p4)",l:"Share"}])}<span class="small muted">${pc(t/tot*100,1)}</span></td></tr>`}).join("")}<tr><td><b>Total FY27 forecast</b></td>${M.map(m=>`<td class="tabular"><b>${D$(m.f)}</b></td>`).join("")}<td class="tabular"><b>${D$(tot)}</b></td><td></td></tr></tbody></table>`)}
 <div class="grid g4" style="margin-top:14px">${M.map(m=>`<div class="tile glass"><span class="lbl">${esc(PJ(m.q).short)}</span><span class="small muted">Driver</span><b>${drv[B().alloc[m.q].driver]}</b><span class="small muted">${Object.keys(m.pct).map(k=>k+" "+Math.round(m.pct[k])+"%").join(" · ")}</span><button class="btn" data-bud-alloc="${m.q}">Edit rule</button></div>`).join("")}</div>`}
const CALC={cap:capHTML,dep:depHTML,tco:tcoHTML,cp:costPlanHTML,show:showHTML};
const sl=(k,label,min,max,step,val,unit,help)=>`<label class="bud-sl"><span class="row sp"><b>${label}</b><b class="num" data-bud-val="${k}">${val}${unit}</b></span><input type="range" class="rng" data-bud-rng="${k}" min="${min}" max="${max}" step="${step}" value="${val}" aria-label="${label}"><span class="small muted">${help}</span></label>`;
function modelView(){const p=B().mproj,m=p!=="all"?B().mp[p]:null;
 const ctl=`<div class="row" style="gap:16px"><div class="recchips" role="group" aria-label="Project">${PROJ.map(x=>`<button class="chip" data-bud-mproj="${x.id}" aria-pressed="${p===x.id}">${x.id} ${esc(x.short)}</button>`).join("")}<button class="chip" data-bud-mproj="all" aria-pressed="${p==="all"}">Portfolio</button></div><div class="recchips" role="group" aria-label="Scenario">${Object.keys(SCEN).map(k=>`<button class="chip" data-bud-scen="${k}" aria-pressed="${B().scen===k}">${SCEN[k][0]}</button>`).join("")}</div></div>`;
 const capCtl=m?`<div class="grid g3 bud-sls">${sl("pre","Preliminary stage share",0,100,5,m.pre,"%","Vendor selection and proof of concept. Expensed.")}${sl("dev","Development stage share",0,100,5,m.dev,"%","Design, build and test. Capitalized.")}${sl("dir","Directly associated payroll",50,100,5,m.dir,"%","Share of labor that qualifies as direct.")}</div>`:`<p class="muted small">Select one project to change its stage shares. The portfolio view is read only.</p>`;
 return `${card("Project and scenario","Choose what to model. Everything on this screen recalculates from the cost plan, the capitalization rules and the benefits register.",ctl)}
 ${views("budm",["Cost plan","Capitalization","Depreciation","TCO and ROI","Showback"],[
  `<div data-bud-calc="cp">${costPlanHTML()}</div>`,
  `${capCtl}<div data-bud-calc="cap">${capHTML()}</div>`,
  `${sl("life","Software useful life",3,7,1,B().life," years","Straight line. Hardware uses 4 years.")}<div data-bud-calc="dep">${depHTML()}</div>`,
  `<div class="grid g3 bud-sls">${sl("rate","Discount rate",3,15,.5,B().rate,"%","Meridian hurdle rate is 8%.")}${sl("grow","Run cost growth a year",0,10,1,B().grow,"%","Applies from FY29.")}</div><div data-bud-calc="tco">${tcoHTML()}</div>`,
  `<div data-bud-calc="show">${showHTML()}</div>`])}`}
REG("bud_model","Financial model","portfolio","M4 20h16M7 16V9M12 16V5M17 16v-4M3 5l5 3 4-4 5 4",()=>{syncM();const r=roi("all",8,"base"),w=PROJ.map(p=>({p,r:roi(p.id,8,"base")})).sort((a,b)=>a.r.roi-b.r.roi)[0],cap=capTot(B().lines),t=T(B().lines);
 return `<div class="screen">${hero("Financial model · cost plan, capitalization, TCO and return","The portfolio returns "+pc(r.roi*100)+" over five years, and "+w.p.short+" is the weakest case",`Five-year cost <b>${C$(r.sc)}</b> against benefit <b>${C$(r.sb)}</b> gives an NPV of <b>${C$(r.npv)}</b> at 8% and payback in about <b>${r.pb==null?"more than five":r.pb.toFixed(1)}</b> years. Of the ${C$(t.fcst)} FY27 forecast, <b>${C$(cap)}</b> (${pc(cap/t.fcst*100,1)}) is capitalized under ASC 350-40. ${esc(w.p.short)} returns ${pc(w.r.roi*100)} and depends on benefits that start only after the Dec 2 pilot.`,`<div class="row">${fchip("m_roi")}${fchip("m_capex")}${aiChip({model:"Claude Sonnet",conf:.8,title:"How the capitalization split was drafted",note:"Claude read the project stage from the master schedule and applied the ASC 350-40 stage rules. The Controller confirms the split before it is booked.",src:["Master schedule stage","Budget lines","ASC 350-40 stage rules","Benefits register"],guards:["Cannot book entries","Controller approves the split","Assumptions are shown, not hidden"]})}${whyPop("A CIO sees the return first, then the assumption that matters most. A Controller would open the capitalization tab first.")}</div>`)}${lensNote()}${modelView()}</div>`});
/* ---- model interactions ---- */
function calcRefresh(){$$("[data-bud-calc]").forEach(el=>{el.innerHTML=CALC[el.dataset.budCalc]()})}
document.addEventListener("input",e=>{const t=e.target.closest("[data-bud-rng]");if(!t)return;const k=t.dataset.budRng,v=+t.value,b=B(),p=b.mproj;
 if(k==="rate")b.rate=v;else if(k==="life")b.life=v;else if(k==="grow")b.grow=v;else if(p!=="all"){const m=b.mp[p];m[k]=v;
  if(k==="pre"&&m.pre+m.dev>100){m.dev=100-m.pre;sync("dev",m.dev)}if(k==="dev"&&m.pre+m.dev>100){m.pre=100-m.dev;sync("pre",m.pre)}}
 $$(`[data-bud-val="${k}"]`).forEach(o=>o.textContent=v+(k==="life"?" years":"%"));calcRefresh();
 function sync(kk,vv){const r=$(`[data-bud-rng="${kk}"]`);if(r)r.value=vv;$$(`[data-bud-val="${kk}"]`).forEach(o=>o.textContent=vv+"%")}});
document.addEventListener("change",e=>{const t=e.target.closest("[data-bud-rng]");if(t){audit("changed model assumption",t.dataset.budRng+" = "+t.value);syncM();return}
 const c=e.target.closest("[data-bud-cp]");if(c){const [i,f]=c.dataset.budCp.split(":").map(Number),r=B().cp[B().mproj][i];r[f]=Math.max(0,+c.value||0);audit("changed cost plan",r[0]+" "+(f===2?"FTE ":"months ")+r[f]);render()}});
document.addEventListener("click",e=>{
 let t=e.target.closest("[data-bud-mproj]");if(t){B().mproj=t.dataset.budMproj;render();return}
 t=e.target.closest("[data-bud-scen]");if(t){B().scen=t.dataset.budScen;audit("selected scenario",SCEN[B().scen][0]);render();return}
 t=e.target.closest("[data-bud-sbm]");if(t){B().showMode=t.dataset.budSbm;audit("switched allocation mode",B().showMode);render();return}
 t=e.target.closest("[data-bud-push]");if(t){const l=LN(t.dataset.budPush),lab=laborPlan(l.p);if(lab<l.act){toast("The labor plan is below the "+D$(l.act)+" already paid.","bad");return}audit("pushed labor plan to forecast",l.id+" "+D$(l.fcst)+" to "+D$(lab));l.fcst=lab;toast(l.id+" forecast is now "+D$(lab),"good");render();return}
 t=e.target.closest("[data-bud-addrole]");if(t){roleForm();return}
 t=e.target.closest("[data-bud-runedit]");if(t){runForm();return}
 t=e.target.closest("[data-bud-alloc]");if(t){allocForm(t.dataset.budAlloc);return}});
const RATECARD={"Platform engineer":16000,"Data engineer":16000,"Architect":20000,"Editor subject expert":13000,"Test lead":15000,"Operations engineer":14000,"Project manager":18000};
function roleForm(){const p=B().mproj;if(p==="all")return;
 openF({id:"bud_role",title:"Add a role to "+PJ(p).short,story:"Add people time to the cost plan. The loaded rate comes from the internal rate card, so every project prices the same role the same way.",submit:"Add to cost plan",
 fields:[{k:"role",label:"Role",type:"select",req:true,opts:Object.keys(RATECARD).map(r=>[r,r+" ("+D$(RATECARD[r])+" per FTE-month)"])},{k:"fte",label:"FTE",type:"number",req:true,min:.25,step:.25,help:"1 is one full-time person."},{k:"mo",label:"Months in FY27",type:"number",req:true,min:1,max:12}],defaults:{role:"Test lead",fte:1,mo:3},
 live:v=>liveBox(`<div class="formula">${D$(RATECARD[v.role]||0)} × ${+v.fte||0} FTE × ${+v.mo||0} months = <b>${D$((RATECARD[v.role]||0)*(+v.fte||0)*(+v.mo||0))}</b></div>`),
 onSubmit:v=>{const m=Math.min(12,+v.mo);B().cp[p].push([v.role,RATECARD[v.role],+v.fte,m]);render();return {toast:v.role+" added: "+D$(RATECARD[v.role]*v.fte*m),audit:"added role "+v.role+" to "+p}}})}
function runForm(){const p=B().mproj;if(p==="all")return;const r=B().run[p];
 openF({id:"bud_run",title:"Run costs for "+PJ(p).short,story:"What the new system costs every year after go-live, on top of what the organization already pays. These feed the five-year TCO.",submit:"Save run costs",
 fields:[{k:"cld",label:"Hosting per year",type:"money"},{k:"lic",label:"Licences per year",type:"money"},{k:"sup",label:"Internal support per year",type:"money",help:"For example 0.5 FTE × 12 months × $16,000."},{k:"ven",label:"Vendor support per year",type:"money"}],defaults:{...r},
 live:v=>liveBox(`<div class="formula">Run cost per year = ${D$(+v.cld||0)} + ${D$(+v.lic||0)} + ${D$(+v.sup||0)} + ${D$(+v.ven||0)} = <b>${D$((+v.cld||0)+(+v.lic||0)+(+v.sup||0)+(+v.ven||0))}</b></div>`),
 onSubmit:v=>{B().run[p]={cld:+v.cld||0,lic:+v.lic||0,sup:+v.sup||0,ven:+v.ven||0};render();return {toast:"Run costs saved",audit:"run costs "+p}}})}
function allocForm(p){const rule=B().alloc[p],fx=rule.fixed||USE[p];
 const flds=[{section:"Cost pool"},{k:"p",label:"Project",type:"chips",opts:PROJ.map(x=>[x.id,x.id+" "+x.short])},{k:"driver",label:"Allocation driver",type:"chips",opts:[["usage","Usage report"],["headcount","Headcount"],["equal","Equal split"],["fixed","Fixed percentages"]],help:"Usage reflects who actually uses the service; headcount spreads by people; fixed is a negotiated split."},{section:"Fixed percentages (when selected)"}];
 DEPTS.forEach(d=>flds.push({k:"f_"+d[0],label:d[1],type:"number",min:0,max:100,show:v=>v.driver==="fixed"}));
 const init={p,driver:rule.driver};DEPTS.forEach(d=>init["f_"+d[0]]=fx[d[0]]||0);
 const prev=v=>{const q=v.p||p,old=B().alloc[q];const save=old;B().alloc[q]={driver:v.driver,fixed:Object.fromEntries(DEPTS.map(d=>[d[0],+v["f_"+d[0]]||0]).filter(x=>x[1]))};let pct;try{pct=allocPct(q)}finally{B().alloc[q]=save}return {q,pct}};
 openF({id:"bud_alloc",title:"Allocation rule for "+PJ(p).short,story:"Decide how this project's cost is shared with the departments that benefit. Showback shows the result; chargeback would post it. Percentages always total 100.",submit:"Save rule",fields:flds,defaults:init,
 live:v=>{const {q,pct}=prev(v),f=T(PL(q)).fcst,s=DEPTS.reduce((a,d)=>a+(+v["f_"+d[0]]||0),0);liveBox(`<div class="formula">${Object.keys(pct).map(k=>`${DN(k)} ${pc(pct[k],0)} = ${D$(pct[k]/100*f)}`).join(" · ")}</div>${v.driver==="fixed"&&Math.round(s)!==100?`<div class="small" style="color:var(--bad)">Fixed percentages total ${s}, not 100.</div>`:""}`)},
 onSubmit:v=>{const q=v.p||p;if(v.driver==="fixed"){const s=DEPTS.reduce((a,d)=>a+(+v["f_"+d[0]]||0),0);if(Math.round(s)!==100)return {close:false,toast:"Fixed percentages total "+s+". They must total 100.",audit:"rejected allocation rule"}}
  B().alloc[q]={driver:v.driver,fixed:v.driver==="fixed"?Object.fromEntries(DEPTS.map(d=>[d[0],+v["f_"+d[0]]||0]).filter(x=>x[1])):undefined};render();return {toast:"Allocation rule saved for "+q,audit:q+" driver "+v.driver}}})}
