/* ---------- 5. Delegation of authority ---------- */
B().pol=B().pol||[{v:"v2",d:"2026-07-01",who:"CFO",what:"Raised tier T3 from $75,000 to $100,000 for the CIO and aligned reserve releases to the same tiers."},{v:"v1",d:"2025-07-01",who:"Board finance committee",what:"First delegation of authority for FY26."}];
B().sodAck=B().sodAck||{};
const NAMEROLE={"Omar (CIO)":"CIO","CIO":"CIO","CFO":"CFO","CEO":"CEO","Board finance committee":"Board finance committee","Maya Ortiz":"Portfolio lead","Priya Shah":"Budget owner","Dev Rao":"Budget owner","Tom Becker":"Budget owner"};
const roleIdx=n=>{const r=NAMEROLE[n];return B().doa.findIndex(t=>t.role===r)};
const topOf=t=>t.max===Infinity?2e6:t.max;
const upTo=m=>m===Infinity?"Any amount":D$(m);
function sodChecks(){const po=B().po,out=[];
 const selfA=po.filter(p=>p.aBy&&p.aBy===p.cBy);
 out.push({n:"Creator is not the approver",rule:"Nobody approves a purchase order they raised.",ok:!selfA.length,items:selfA.map(p=>`${p.id} ${p.d}: raised and approved by ${p.cBy}`),fix:selfA[0]?["data-bud-porr",selfA[0].id,"Re-route "+selfA[0].id+" to the CIO"]:null});
 const over=po.filter(p=>p.aBy&&p.st!=="Pending approval"&&roleIdx(p.aBy)>=0&&tierIdx(p.ord)>roleIdx(p.aBy));
 out.push({n:"Approver is inside their authority",rule:"The approver's tier must cover the full order value.",ok:!over.length,items:over.map(p=>`${p.id} ${D$(p.ord)} was approved by ${p.aBy}, whose limit is ${upTo(B().doa[roleIdx(p.aBy)].max)}`),fix:over[0]&&over[0].aBy===over[0].cBy?null:over[0]?["data-bud-porr",over[0].id,"Re-route "+over[0].id]:null});
 const rc=po.filter(p=>p.rBy&&p.rBy===p.cBy);
 out.push({n:"Receipt is confirmed by someone else",rule:"The person who orders does not confirm delivery.",ok:!rc.length,items:rc.map(p=>`${p.id}: ${p.cBy} raised and received`)});
 const groups={};po.forEach(p=>{const k=p.v+"|"+p.cBy;(groups[k]=groups[k]||[]).push(p)});const splits=[];
 Object.values(groups).forEach(g=>{g=g.sort((a,b)=>a.date<b.date?-1:1);if(g.length<2)return;const w=g.filter(p=>(dd(p.date)-dd(g[0].date))/864e5<=30),s=sum(w,p=>p.ord);if(w.length>1&&tierIdx(s)>Math.max(...w.map(p=>tierIdx(p.ord))))splits.push({w,s})});
 out.push({n:"No split purchases",rule:"Orders to one vendor by one requester within 30 days are added together before choosing the tier.",ok:!splits.length||splits.every(x=>B().sodAck["split:"+x.w[0].id]),items:splits.filter(x=>!B().sodAck["split:"+x.w[0].id]).map(x=>`${x.w.map(p=>p.id).join(", ")} to ${VID(x.w[0].v).n}: ${x.w.length} orders of ${x.w.map(p=>C$(p.ord)).join(", ")} total ${D$(x.s)}, which belongs in tier ${B().doa[tierIdx(x.s)].id}`),fix:splits.find(x=>!B().sodAck["split:"+x.w[0].id])?["data-bud-split",splits.find(x=>!B().sodAck["split:"+x.w[0].id]).w[0].id,"Route as one order to the "+B().doa[tierIdx(splits[0].s)].role]:null});
 const led=B().led.filter(e=>e.st==="Approved"&&e.t==="draw"&&e.req===e.apr);
 out.push({n:"Reserve requester is not the approver",rule:"A reserve draw is approved by someone other than the requester, and never by an agent.",ok:!led.length,items:led.map(e=>`${e.id} requested and approved by ${e.req}`)});
 out.push({n:"Vendor master changes and payments are separate roles",rule:"The person who edits bank details cannot release payments.",ok:true,items:[],note:"From the Entra ID access review of Sep 30: no user holds both roles."});
 return out}
function matrixView(){const cats=DCATS;
 return `${card("Approval matrix","Who approves, by amount. Each cell lists the reviews that must finish before the approver signs, at the top of the band.",wrap(`<table style="min-width:1080px"><thead><tr><th>Tier</th><th>Up to</th><th>Approves</th>${cats.map(c=>`<th>${c}</th>`).join("")}</tr></thead><tbody>${B().doa.map(t=>{const top=topOf(t);return `<tr><td><b>${t.id}</b></td><td class="tabular">${upTo(t.max)}</td><td><span class="pill ${B().doa.indexOf(t)<=CIOIDX()?"good":"warn"}">${esc(t.role)}</span></td>${cats.map(c=>{const rv=B().crules.filter(r=>r.cat===c&&top>=r.min).map(r=>r.role);if(top>=10000&&!rv.includes("Controller"))rv.unshift("Controller");return `<td class="small" style="white-space:normal;min-width:110px">${rv.length?rv.map(x=>`<span class="pill mute" style="margin:1px">${esc(x)}</span>`).join(" "):'<span class="muted">None</span>'}</td>`}).join("")}</tr>`}).join("")}</tbody></table>`),`<span class="row"><button class="btn" data-bud-simgo>Try it: who approves this?</button></span>`)}
 ${card("Where the invoice rules fit","The Invoice approval screen decides payment of an invoice against an approved order. This matrix decides who may commit the money in the first place.",`<div class="grid g2"><div class="small" data-role="story">An order approved at tier T3 can still be paid by rule r1 if the invoice is up to <b>${D$((S.rules[0]&&S.rules[0].amt)||25000)}</b>, the vendor index is at least <b>${(S.rules[0]&&S.rules[0].idx)||.85}</b> and it matches the order. Rule r4 escalates invoices above <b>${D$(((S.rules[3]&&S.rules[3].big)||100000))}</b> to the CFO, the same line as the top of tier T3.</div><div class="row" style="align-content:flex-start"><button class="btn" data-go="inv">Open invoice rules</button><button class="btn" data-go="bud_ven">Open purchase orders</button></div></div>`)}`}
