function pendingFor(name){const out=[];ST.reqs.forEach(r=>r.gates.forEach((g,i)=>{if(g.st==="pending"&&g.who===name&&r.state==="Approvals")out.push({r,g,i,mine:true})}));G(()=>window.REQREG).forEach(r=>Object.keys(r.ap||{}).forEach(k=>{const a=r.ap[k];if(a.st==="pending"&&a.who===name)out.push({real:r,k,a})}));return out}
CX.pendingFor=pendingFor;
