 if(polOn("G7")&&x.r&&(x.r.by===tg||x.r.by===ME_NAME&&tg===ME_NAME&&x.r.for===ME_NAME))return{ok:false,error:"Separation of duties: "+tg+" cannot approve a request they made."};
