 if(/(can|may|ok to|safe to).*(deploy|release)|deployment freeze|freeze/.test(t)){const dm=q.match(/\d{4}-\d{2}-\d{2}/),d=dm?dm[0]:TODAY,r=canDeploy(d);go("dev_pipe");S.v.dev_v=5;render();say(q,{t:r.t,steps:["Read the freeze calendar","Checked other planned releases"]});return true}
