/* ---------- pan and zoom shared by both maps ---------- */
const PZ=M.pz;
function pzInit(id,w,h,vh){const vw=(document.getElementById("view")||document.body).clientWidth||window.innerWidth,avail=Math.max(300,vw-60);if(!PZ[id]||PZ[id].w!==w||PZ[id].h!==h){const k=Math.min(1,avail/w,vh/h);PZ[id]={x:8,y:8,k,w,h,vh,k0:k}}return PZ[id]}
const pzCss=id=>{const s=PZ[id];return `transform:translate(${s.x}px,${s.y}px) scale(${s.k})`};
function pzApply(id){const s=PZ[id],w=document.querySelector(`[data-pz-world="${id}"]`);if(!w)return;w.style.transform=`translate(${s.x}px,${s.y}px) scale(${s.k})`;w.parentElement.classList.toggle("lo",s.k<.5);const z=document.querySelector(`[data-pz-z="${id}"]`);if(z)z.textContent=Math.round(s.k*100)+"%";pzMini(id)}
function pzMini(id){const s=PZ[id],vp=document.querySelector(`[data-pz="${id}"]`),r=document.querySelector(`[data-mm-vp="${id}"]`);if(!vp||!r)return;const sc=+r.dataset.sc;r.setAttribute("x",(-s.x/s.k)*sc);r.setAttribute("y",(-s.y/s.k)*sc);r.setAttribute("width",vp.clientWidth/s.k*sc);r.setAttribute("height",vp.clientHeight/s.k*sc)}
function pzZoom(id,f,cx,cy){const s=PZ[id],vp=document.querySelector(`[data-pz="${id}"]`);if(!s||!vp)return;const nk=Math.max(.12,Math.min(2.5,s.k*f));cx=cx==null?vp.clientWidth/2:cx;cy=cy==null?vp.clientHeight/2:cy;s.x=cx-(cx-s.x)*nk/s.k;s.y=cy-(cy-s.y)*nk/s.k;s.k=nk;pzApply(id)}
function pzFit(id){const s=PZ[id],vp=document.querySelector(`[data-pz="${id}"]`);if(!s||!vp)return;s.k=Math.min(vp.clientWidth/s.w,vp.clientHeight/s.h)*.97;s.x=(vp.clientWidth-s.w*s.k)/2;s.y=(vp.clientHeight-s.h*s.k)/2;pzApply(id)}
function pzCenter(id,wx,wy){const s=PZ[id],vp=document.querySelector(`[data-pz="${id}"]`);if(!s||!vp)return;s.x=vp.clientWidth/2-wx*s.k;s.y=vp.clientHeight/2-wy*s.k;pzApply(id)}
const pzBar=id=>`<div class="map-ctl row" role="group" aria-label="Zoom and pan"><button class="btn quiet" data-pz-in="${id}" aria-label="Zoom in">Zoom in</button><button class="btn quiet" data-pz-out="${id}" aria-label="Zoom out">Zoom out</button><button class="btn quiet" data-pz-fit="${id}">Fit to screen</button><button class="btn quiet" data-pz-100="${id}">100%</button><span class="muted small">Zoom <b data-pz-z="${id}">${Math.round(PZ[id].k*100)}%</b>. Drag to pan. Hold Ctrl and scroll to zoom.</span></div>`;
let drag=null,supp=false;
document.addEventListener("pointerdown",e=>{const vp=e.target.closest&&e.target.closest("[data-pz]");if(!vp||e.button>0||e.target.closest("input,select,textarea,[data-nopan]"))return;const id=vp.dataset.pz,s=PZ[id];if(!s)return;drag={id,x:e.clientX,y:e.clientY,ox:s.x,oy:s.y,moved:false}});
document.addEventListener("pointermove",e=>{if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(!drag.moved&&Math.hypot(dx,dy)<5)return;drag.moved=true;const s=PZ[drag.id];s.x=drag.ox+dx;s.y=drag.oy+dy;pzApply(drag.id);e.preventDefault()},{passive:false});
const pzUp=()=>{if(drag&&drag.moved){supp=true;setTimeout(()=>supp=false,80)}drag=null};document.addEventListener("pointerup",pzUp);document.addEventListener("pointercancel",pzUp);
document.addEventListener("click",e=>{if(supp){e.stopPropagation();e.preventDefault()}},true);
document.addEventListener("wheel",e=>{const vp=e.target.closest&&e.target.closest("[data-pz]");if(!vp||!(e.ctrlKey||e.metaKey))return;e.preventDefault();const r=vp.getBoundingClientRect();pzZoom(vp.dataset.pz,e.deltaY<0?1.15:1/1.15,e.clientX-r.left,e.clientY-r.top)},{passive:false});
document.addEventListener("keydown",e=>{const vp=e.target.closest&&e.target.closest("[data-pz]");if(!vp)return;const id=vp.dataset.pz,s=PZ[id];if(e.key==="+"||e.key==="="){pzZoom(id,1.2)}else if(e.key==="-"){pzZoom(id,1/1.2)}else if(e.key==="0"){pzFit(id)}else if(e.key==="ArrowLeft"&&e.target===vp){s.x+=60;pzApply(id)}else if(e.key==="ArrowRight"&&e.target===vp){s.x-=60;pzApply(id)}else if(e.key==="ArrowUp"&&e.target===vp){s.y+=60;pzApply(id);e.preventDefault()}else if(e.key==="ArrowDown"&&e.target===vp){s.y-=60;pzApply(id);e.preventDefault()}});
document.addEventListener("click",e=>{const t=e.target.closest("[data-pz-in],[data-pz-out],[data-pz-fit],[data-pz-100],[data-mm]");if(!t)return;const d=t.dataset;if(d.pzIn)pzZoom(d.pzIn,1.25);else if(d.pzOut)pzZoom(d.pzOut,1/1.25);else if(d.pzFit)pzFit(d.pzFit);else if(d.pz100){const s=PZ[d.pz100];s.k=1;s.x=8;s.y=8;pzApply(d.pz100)}else if(d.mm){const r=t.getBoundingClientRect(),sc=+t.dataset.sc;pzCenter(d.mm,(e.clientX-r.left)/sc,(e.clientY-r.top)/sc)}});
