function procSteps(n){const out=[];n.scr.forEach(s=>{const d=window.PROC&&PROC.defs[s];if(d)(d.steps||[]).forEach(x=>out.push(Object.assign({scr:s},x)))});return out}
function nodeStats(n){const st=procSteps(n),tot=st.length,au=st.filter(x=>x.who==="auto"||x.who==="agent").length,sla=st.filter(x=>x.sla).length,pct=tot?Math.round(au/tot*100):0,lv=pct>=75?4:pct>=50?3:pct>=30?2:pct>=10?1:0,defs=n.scr.filter(s=>window.PROC&&PROC.defs[s]).length;return {tot,au,pct,lv,sla:tot?Math.round(sla/tot*100):0,defs,nodef:!defs}}
const LVN=["Manual","Assisted","Scripted","Agentic with approval","Autonomous"];
const wfsFor=n=>(window.WFX?WFX.defs.filter(d=>n.wf.test((d.id||"")+" "+(d.name||"")+" "+(d.service||""))):[]);
function nodeDims(){const k=LY.filter(l=>M.layers[l[0]]).length,h=132+k*38,gap=108;return {h,gap,w:40+4*COLW+NW+90,ht:90+3*h+2*gap+60}}
function pos(n,D){return {x:40+n.c*COLW,y:90+n.r*(D.h+D.gap)}}
function edgesSvg(D){const P={};NODES.forEach(n=>P[n.id]=pos(n,D));const mid=(id,side)=>{const p=P[id];return side==="r"?[p.x+NW,p.y+D.h/2]:side==="l"?[p.x,p.y+D.h/2]:side==="t"?[p.x+NW/2,p.y]:[p.x+NW/2,p.y+D.h]};
 const arr=(a,b,lbl,dash)=>{const A=mid(a[0],a[1]),B=mid(b[0],b[1]),d=`M${A[0]} ${A[1]}L${B[0]} ${B[1]}`,mx=(A[0]+B[0])/2,my=(A[1]+B[1])/2;return `<path d="${d}" class="map-ed ${dash?"dash":""}" marker-end="url(#mapArr)"/>${lbl?`<g transform="translate(${mx},${my})"><rect x="${-lbl.length*2.9-6}" y="-10" width="${lbl.length*5.8+12}" height="19" rx="9" class="map-lb"/><text text-anchor="middle" y="4" class="map-lt">${H(lbl)}</text></g>`:""}`};
 let g=`<defs><marker id="mapArr" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0L10 5L0 10z" class="map-ah"/></marker></defs>`;
 EDGES.forEach(([a,b])=>{const na=NODES.find(n=>n.id===a),nb=NODES.find(n=>n.id===b);if(a==="mat"){const A=mid("mat","r"),B=mid("strat","t"),X=D.w-40;g+=`<path d="M${A[0]} ${A[1]}H${X}V40H${B[0]}V${B[1]}" class="map-ed" marker-end="url(#mapArr)"/><g transform="translate(${X},${(A[1]+40)/2})"><rect x="-70" y="-10" width="140" height="19" rx="9" class="map-lb"/><text text-anchor="middle" y="4" class="map-lt">Back to strategy</text></g>`;return}
  const dr=na.r===nb.r?(nb.c>na.c?["r","l"]:["l","r"]):["b","t"];g+=arr([a,dr[0]],[b,dr[1]],na.hand,false)});
 FEED.forEach(([a,b,l])=>{const A=mid(a,"t"),B=mid(b,"b");const yy=A[1]-(D.gap/2)-(a==="sla"?0:0);g+=a==="prb"?`<path d="M${A[0]} ${A[1]}V${A[1]-D.gap/2}H${B[0]}V${B[1]}" class="map-ed dash" marker-end="url(#mapArr)"/><g transform="translate(${(A[0]+B[0])/2},${A[1]-D.gap/2})"><rect x="-96" y="-10" width="192" height="19" rx="9" class="map-lb"/><text text-anchor="middle" y="4" class="map-lt">${H(l)}</text></g>`:""});
 return `<svg class="map-svg" width="${D.w}" height="${D.ht}" viewBox="0 0 ${D.w} ${D.ht}" aria-hidden="true">${g}</svg>`}
function nodeHTML(n,D){const p=pos(n,D),st=nodeStats(n),show=l=>M.layers[l];const lay=LY.filter(l=>show(l[0])).map(l=>{const a=n[l[0]],m=a.slice(0,2);return `<span class="map-ly" style="--c:var(${l[2]})"><i></i>${m.map(H).join(", ")}${a.length>2?" +"+(a.length-2):""}</span>`}).join("");
 return `<button class="map-nd ${st.nodef?"nodef":""} ${M.sel===n.id?"on":""}" style="left:${p.x}px;top:${p.y}px;width:${NW}px;height:${D.h}px" data-map-nd="${n.id}" aria-label="${H(n.n)}: automation ${st.pct}%"><span class="map-num">${NODES.indexOf(n)+1}</span><b>${H(n.n)}</b><span class="muted small map-own">${H(n.own)}</span><span class="map-stds">${n.std.map(s=>`<i>${H((STD[s]||{n:s}).n.split(":")[0].split(" (")[0])}</i>`).join("")}</span><span class="map-met"><span class="map-ab" title="Automation: ${LVN[st.lv]}"><u style="width:${st.pct}%"></u></span><small>${st.nodef?"No process defined":"Auto "+st.pct+"%"}</small><small>SLA ${st.sla}%</small></span>${lay}</button>`}
function mapHTML(){const D=nodeDims(),s=pzInit("proc",D.w,D.ht,640);return `<div class="map-vp ${s.k<.5?"lo":""}" data-pz="proc" tabindex="0" role="application" aria-label="Master process flow. Drag to pan, plus and minus to zoom." style="height:${Math.min(640,Math.round(D.ht*s.k)+24)}px"><div class="map-world" data-pz-world="proc" style="width:${D.w}px;height:${D.ht}px;${pzCss("proc")}">${edgesSvg(D)}${NODES.map(n=>nodeHTML(n,D)).join("")}</div></div>`}
function procList(){return btHTML({id:"map_proc",h:420,rowH:52,key:"id",sort:{k:"n",d:1},exportName:"process-areas",facets:["lvn","own"],cols:[{k:"n",label:"Process area",val:r=>r.nn,fmt:r=>`<b>${H(r.n)}</b><span class="sub">${H(r.scr.map(scrName).filter(Boolean).join(", "))}</span>`},{k:"own",label:"Owner",val:r=>r.own,fmt:r=>H(r.own)},{k:"std",label:"Standards",val:r=>r.std.join(","),fmt:r=>H(r.std.map(s=>(STD[s]||{n:s}).n.split(":")[0]).join(", "))},{k:"auto",label:"Automation",val:r=>r.st.pct,fmt:r=>`${r.st.pct}% · ${H(LVN[r.st.lv])}`},{k:"lvn",label:"Level",val:r=>r.lvn,fmt:r=>H(r.lvn)},{k:"sla",label:"SLA coverage",val:r=>r.st.sla,fmt:r=>r.st.tot?r.st.sla+"%":"None defined"},{k:"def",label:"Process defined",val:r=>r.st.defs,fmt:r=>r.st.nodef?pill("No","warn"):pill(r.st.defs+" of "+r.scr.length,"good")},{k:"wf",label:"Workflows",val:r=>r.wfn,fmt:r=>N0(r.wfn)}],
 rows:()=>NODES.map((n,i)=>Object.assign({},n,{nn:String(i+1).padStart(2,"0")+n.n,st:nodeStats(n),lvn:"Level "+nodeStats(n).lv+" "+LVN[nodeStats(n).lv],wfn:wfsFor(n).length})),open:id=>nodeDrawer(id)})}
Object.assign(METRICS,{m_proc_auto:Object.assign({n:"Process automation level",u:"%",cur:42,tgt:60,badAt:25,dir:"max",max:100},{f:"Steps done by automation or an AI agent ÷ all steps, across every end-to-end process with a definition",tr:[28,31,34,36,38,40,41,42],owner:"Process owners",use:["Master process flow"],rem:{kind:"agent",ref:"RB-PA",title:"Find the next step to automate",agent:"Ops Agent",auto:false,state:"idle",prog:"Ranks manual steps by volume and wait time"}}),
 m_proc_sla:Object.assign({n:"Process steps with an SLA",u:"%",cur:55,tgt:80,badAt:35,dir:"max",max:100},{f:"Steps with a stated time limit ÷ all steps in defined processes",tr:[40,42,45,47,50,52,54,55],owner:"Service level manager",use:["Master process flow"],rem:{kind:"agent",ref:"RB-PS",title:"Propose SLAs for steps without one",agent:"SLA Agent",auto:false,state:"idle",prog:"Uses the measured duration of each step"}}),
 m_data_ref:Object.assign({n:"Data model reference integrity",u:"%",cur:96,tgt:100,badAt:85,dir:"max",max:100},{f:"Reference fields that point to a registered table ÷ all reference fields in the master data model",tr:[88,90,91,93,94,95,95,96],owner:"Data architect",use:["Master data model"],rem:{kind:"agent",ref:"RB-DR",title:"Fix unresolved references",agent:"Knowledge Curator",auto:false,state:"idle",prog:"Lists reference fields with no target table"}})});
function mapStats(){const sts=NODES.map(nodeStats),tot=sts.reduce((a,x)=>a+x.tot,0),au=sts.reduce((a,x)=>a+x.au,0),sl=sts.reduce((a,x)=>a+Math.round(x.sla*x.tot/100),0);METRICS.m_proc_auto.cur=tot?Math.round(au/tot*100):0;METRICS.m_proc_sla.cur=tot?Math.round(sl/tot*100):0;return {tot,au,sl,nodef:sts.filter(x=>x.nodef).length,defs:window.PROC?Object.keys(PROC.defs).length:0,wf:window.WFX?WFX.defs.length:0}}
function mapPane(){const st=mapStats(),D0=nodeDims();pzInit("proc",D0.w,D0.ht,640);
 return `<div class="statrow">${stat("Process areas",NODES.length,"from strategy back to strategy")}${stat("Steps automated",METRICS.m_proc_auto.cur+"%",N0(st.au)+" of "+N0(st.tot)+" steps")}${stat("Steps with an SLA",METRICS.m_proc_sla.cur+"%","time limit stated")}${stat("Without a process definition",st.nodef,"dashed boxes on the map")}${stat("Process definitions",st.defs,st.wf+" workflows registered")}</div>
 <div class="row dev-chips">${fchip("m_proc_auto")}${fchip("m_proc_sla")}${stdChip("itil5","Service value chain: plan, improve, engage, design, obtain, deliver and support")}${stdChip("pmbok","Project processes")}${stdChip("safe","Lean portfolio and release train")}${stdChip("tbm","Cost transparency from resources to services")}</div>
 ${card("The whole system on one page","Strategy turns into demand, projects and a backlog. The pipeline builds it, the change gate lets it through, operations runs it, and service performance and cost feed back into strategy. Select a box for its owner, standards and handoffs. Dashed boxes have no process definition yet.",`<div class="row dev-act" role="group" aria-label="Layers"><span class="muted small">Layers</span>${LY.map(l=>`<label class="fchip ${M.layers[l[0]]?"on":""}"><input type="checkbox" data-map-layer="${l[0]}" ${M.layers[l[0]]?"checked":""}> <i class="map-dot" style="background:var(${l[2]})"></i>${l[1]}</label>`).join("")}</div>${pzBar("proc")}${mapHTML()}${legend([["Process area","--p4"],["Handoff of data between areas","--faint"],["Feedback loop","--warn-f"],["Data objects","--p4"],["Systems","--s3"],["Roles","--u3"],["AI agents","--e4"]])}`)}
 ${card("Process areas","Automation is the share of steps done by automation or an AI agent. SLA coverage is the share of steps with a stated time limit.",procList())}`}
function handoffPane(){const rows=EDGES.map(([a,b])=>({a:NODES.find(n=>n.id===a),b:NODES.find(n=>n.id===b)})).map((x,i)=>({id:String(i),from:x.a.n,to:x.b.n,data:x.a.hand,obj:x.a.data.join(", "),owner:x.a.own})).concat(FEED.map((f,i)=>({id:"f"+i,from:NODES.find(n=>n.id===f[0]).n,to:NODES.find(n=>n.id===f[1]).n,data:f[2],obj:NODES.find(n=>n.id===f[0]).data.join(", "),owner:NODES.find(n=>n.id===f[0]).own})));
 return card("Data handoffs between process areas","What one area hands to the next, and the data objects behind it. Select a row to open the sending area.",btHTML({id:"map_hand",h:520,rowH:50,key:"id",exportName:"handoffs",facets:["from","to"],cols:[{k:"from",label:"From",val:r=>r.from,fmt:r=>H(r.from)},{k:"to",label:"To",val:r=>r.to,fmt:r=>H(r.to)},{k:"data",label:"What is handed over",val:r=>r.data,fmt:r=>H(r.data)},{k:"obj",label:"Data objects",val:r=>r.obj,fmt:r=>H(r.obj),wrap:1},{k:"owner",label:"Sending owner",val:r=>r.owner,fmt:r=>H(r.owner)}],rows:()=>rows,open:id=>{const r=rows.find(x=>x.id===id);const n=NODES.find(x=>x.n===r.from);if(n)nodeDrawer(n.id)}}))}
function coveragePane(){const pd=window.PROC?Object.keys(PROC.defs):[],noPD=SCREENS.filter(s=>!pd.includes(s[0])&&!/^(home|trace|inv|fo|tower|metrics|kg|loop|adm_|chat_)/.test(s[0]));const wf=window.WFX?WFX.defs:[];
 const groups=[{key:"nopd",label:"Screens without a process definition",rows:noPD.map(s=>({id:s[0],t:s[1],sub:s[0],tag:"Screen",st:"warn",go:()=>go(s[0])}))},{key:"pd",label:"Process definitions",rows:pd.map(s=>({id:s,t:(PROC.defs[s].title||s),sub:scrName(s)+" · "+(PROC.defs[s].steps||[]).length+" steps",tag:"Process",st:"good",go:()=>hasScr(s)&&go(s)}))},{key:"wf",label:"Workflows",rows:wf.map(w=>({id:w.id,t:w.name||w.id,sub:(w.kind||"")+" · "+(w.service||""),tag:"Workflow",st:"info",go:()=>go("flw_design")}))}];
 return `<div class="statrow">${stat("Process definitions",pd.length,"on "+SCREENS.length+" screens")}${stat("Workflows",wf.length,"in the workflow designer")}${stat("Screens without a definition",noPD.length,"candidates to define")}</div>`+card("Coverage of process definitions and workflows","Every screen should answer who does what, how fast, and what standard it follows. Gaps are listed first.",lrHTML({id:"map_cov",groups,limit:8,search:true}))}
function nodeDrawer(id){const n=NODES.find(x=>x.id===id);if(!n)return;M.sel=id;const st=nodeStats(n),steps=procSteps(n),wf=wfsFor(n),i=NODES.indexOf(n),prev=EDGES.filter(e=>e[1]===id).map(e=>NODES.find(x=>x.id===e[0])),next=EDGES.filter(e=>e[0]===id).map(e=>NODES.find(x=>x.id===e[1]));
 const groups=[{key:"steps",label:"Process steps ("+steps.length+")",rows:steps.map(s=>({id:s.scr+s.n,t:s.n,sub:(s.d||"").slice(0,110),tag:s.who==="human"?"Person":s.who==="agent"?"AI agent":s.who==="gate"?"Approval gate":"Automatic",st:s.who==="human"?"mute":s.who==="gate"?"warn":"good",go:()=>hasScr(s.scr)&&go(s.scr)}))},{key:"wf",label:"Workflows ("+wf.length+")",rows:wf.map(w=>({id:w.id,t:w.name||w.id,sub:(w.kind||"")+" · owner "+(w.owner||""),tag:"Workflow",st:"info",go:()=>go("flw_design")}))},{key:"data",label:"Data objects ("+n.data.length+")",rows:n.data.map(d=>({id:d,t:d,sub:"Open in the master data model",tag:"Data",st:"mute",go:()=>{closeDrawer();const t=Object.entries(DATAMODEL.tables).find(([k,v])=>v.label.toLowerCase().includes(d.toLowerCase().split(" ")[0])||k.includes(d.toLowerCase().replace(/ /g,"_")));if(t){M.er.sel=t[0];M.er.q=t[0]}go("plat_data")}}))}];
 openDrawer(`<div class="eyebrow">Process area ${i+1} of ${NODES.length}</div><h2 class="dev-h2">${H(n.n)}</h2><div class="row">${n.std.map(s=>stdChip(s)).join("")}${st.nodef?pill("No process defined","warn"):""}</div>
 <div class="statrow">${stat("Process owner",H(n.own),"")}${stat("Automation",st.pct+"%",LVN[st.lv]+" (level "+st.lv+")")}${stat("SLA coverage",st.sla+"%",st.tot?N0(st.tot)+" steps":"no steps defined")}${stat("Workflows",wf.length,"registered")}</div>
 <div class="row dev-act">${n.scr.filter(hasScr).map(s=>`<button class="btn primary" data-map-open="${s}">Open ${H(scrName(s))}</button>`).join("")}<button class="btn" data-map-go="flw_design">Open the workflow designer</button>${fchip("m_proc_auto")}</div>
 <div class="dfullgrid"><section class="card glass"><h3>Handoffs</h3><p><b>Receives from:</b> ${prev.map(p=>H(p.n)+" ("+H(p.hand)+")").join(", ")||"none"}</p><p><b>Hands over:</b> ${H(n.hand)} to ${next.map(x=>H(x.n)).join(", ")||"none"}</p>${FEED.filter(f=>f[0]===id||f[1]===id).map(f=>`<p class="muted small">Feedback loop: ${H(f[2])}</p>`).join("")}</section>
 <section class="card glass"><h3>Who and what takes part</h3><p><b>Roles:</b> ${n.role.map(H).join(", ")}</p><p><b>Systems:</b> ${n.sys.map(H).join(", ")}</p><p><b>AI agents:</b> ${n.agent.map(a=>{try{return pchip(a)}catch(e){return H(a)}}).join(" ")}</p></section></div>
 <section class="card glass"><h3>Linked records</h3>${lrHTML({id:"map_lr_"+id,groups,limit:6,search:true,empty:"Nothing linked."})}</section>`);audit("opened process area",n.n)}
document.addEventListener("click",e=>{const t=e.target.closest("[data-map-nd],[data-map-go],[data-map-open]");if(!t)return;const d=t.dataset;if(d.mapNd){nodeDrawer(d.mapNd);return}if(d.mapGo){go(d.mapGo);return}if(d.mapOpen){closeDrawer();go(d.mapOpen)}});
