SEARCHX.push(()=>NODES.map(n=>({g:"Process areas",t:n.n,m:"Owner "+n.own,c:"--p4",f:()=>{go("plat_map");setTimeout(()=>nodeDrawer(n.id),150)},k:n.data.join(" ")+" "+n.sys.join(" ")+" process flow"})));
