/* ---------- master data model ---------- */
const DOMS=[["ITSM","--p4","Tom Becker"],["PPM","--p1","Priya Shah"],["CMDB","--s3","Sam Patel"],["Catalog","--u3","Grace Whitfield"],["SLA","--e4","Nia Brooks"],["Contract","--w1","Maya Ortiz"],["Finance","--p5","Avery Chen"],["People","--s1","Leila Haddad"],["Knowledge","--u1","Knowledge Curator"],["Observability and DevOps","--e1","Omar Hamid"]];
const DOMC=Object.fromEntries(DOMS.map(d=>[d[0],d[1]])),DOMO=Object.fromEntries(DOMS.map(d=>[d[0],d[2]]));
function domOf(k,t){const s=(t&&t.source||"").toLowerCase();
 if(/^(alert|correlation_group|maintenance_window|false_positive|automation_rule|standard_change|runbook|slo$|synthetic|metric_series|dashboard|log_pattern|pull_request|release$|release_task)/.test(k))return "Observability and DevOps";
 if(/^(incident|change_|problem|major_|known_error)/.test(k))return "ITSM";
 if(/^(request_item|catalog_|fulfillment|vendor_ticket)/.test(k))return "Catalog";
 if(/^(sla_|task_sla|xla_)/.test(k))return "SLA";
 if(/^(contract|ast_contract)/.test(k))return "Contract";
 if(/^(invoice|scaling_step|cost_allocation|budget)/.test(k))return "Finance";
 if(/^(person|oncall|skill|time_off|team|training)/.test(k))return "People";
 if(/^(kb_|article|prompt|kcs|knowledge)/.test(k)||/knowledge/.test(s))return "Knowledge";
 if(/^(cmdb|core_company|service_offering|business_service|asset)/.test(k))return "CMDB";
 if(/^(project|wbs|demand|raid|user_story|feature|maturity)/.test(k))return "PPM";
 return /cmdb|service/.test(s)?"CMDB":/itsm/.test(s)?"ITSM":"PPM"}
const RALIAS={service:"business_service",offering:"service_offering",ci:"cmdb_ci",caller:"person",requested_for:"person",opened_by:"person",manager:"person",owner:"person",owned_by:"person",assigned_to:"person",author:"person",approver:"person",release_manager:"person",accountable_human:"person",verified_by:"person",service_owner:"person",executor:"person",person:"person",marked_by:"person",project:"project",story:"user_story",feature:"feature",epic:"feature",release:"release",cat_item:"catalog_item",request_item:"request_item",request:"request_item",contract:"contract",definition:"sla_definition",sla_link:"sla_definition",wbs_link:"wbs_line",skill:"skill",incident:"incident",change:"change_request",standard_change:"standard_change",location:"cmdb_ci_site",parent:"cmdb_ci",child:"cmdb_ci",group:"correlation_group",alert:"alert_event"};
function model(){const T=DATAMODEL.tables,keys=Object.keys(T),refs=[],unres=[];
 keys.forEach(k=>{const t=T[k];(t.fields||[]).forEach(f=>{if(f.type!=="ref")return;let to=f.to||RALIAS[f.k];if(k==="alert_rule"&&f.k==="owner")to="person";if(k==="alert_event"&&f.k==="rule")to="alert_rule";if(k==="automation_rule"&&f.k==="rule")to="automation_rule";if(k==="runbook_execution"&&f.k==="rule")to="automation_rule";if(k==="runbook_execution"&&f.k==="alert")to="alert_event";if(k==="change_approval_policy"&&f.k==="service")to="business_service";
   if(to&&T[to])refs.push({from:k,to,f:f.k,lab:f.label});else if(!["assignment_group","support_group","managed_by_group","team","vendor","po","rota","sprint","table","schedule","task","objective","fulfillment_flow","playbook_clause","from","to","program_increment","release_train","verified_by"].includes(f.k)&&!(to&&!T[to]&&false))unres.push({from:k,f:f.k,lab:f.label,guess:to||""})});
  if(/^cmdb_ci_/.test(k)&&T.cmdb_ci)refs.push({from:k,to:"cmdb_ci",f:"extends",lab:"Extends",ext:true})});
 return {T,keys,refs,unres,dom:Object.fromEntries(keys.map(k=>[k,domOf(k,T[k])]))}}
let MC=null,MCK="";const MOD=()=>{const T=DATAMODEL.tables,key=Object.keys(T).length+"|"+Object.values(T).reduce((a,t)=>a+(t.fields||[]).length,0);if(!MC||MCK!==key){MC=model();MCK=key}return MC};
const BW=236,PITCH=286;
const boxH=t=>{const n=(t.fields||[]).length;return 32+Math.min(n,6)*16+(n>6?16:0)+10};
function layout(keys,Md){const byD={};keys.forEach(k=>{(byD[Md.dom[k]]=byD[Md.dom[k]]||[]).push(k)});const doms=DOMS.map(d=>d[0]).filter(d=>byD[d]);const pos={},rect={};let x=0,y=0,rowH=0;const MAXW=keys.length>60?3700:2400;
 doms.forEach(d=>{const ks=byD[d].sort(),cols=Math.max(1,Math.min(ks.length,Math.ceil(Math.sqrt(ks.length*1.25)))),rows=Math.ceil(ks.length/cols),w=cols*PITCH+30,h=rows*176+64;if(x>0&&x+w>MAXW){x=0;y+=rowH+50;rowH=0}
  rect[d]={x,y,w,h};ks.forEach((k,i)=>{pos[k]={x:x+20+(i%cols)*PITCH,y:y+54+Math.floor(i/cols)*176}});x+=w+50;rowH=Math.max(rowH,h)});
 return {pos,rect,w:Math.max(...Object.values(rect).map(r=>r.x+r.w))+20,h:y+rowH+20}}
const trunc=(s,n)=>String(s).length>n?String(s).slice(0,n-1)+"…":String(s);
function erSvg(L,Md,keys){const E=M.er,q=E.q.toLowerCase(),match=k=>{if(!q)return true;const t=Md.T[k];return k.includes(q)||(t.label||"").toLowerCase().includes(q)||(t.fields||[]).some(f=>f.k.includes(q)||(f.label||"").toLowerCase().includes(q))};
 const vis=new Set(keys);let g="";
 Object.entries(L.rect).forEach(([d,r])=>{g+=`<g class="er-dom"><rect x="${r.x}" y="${r.y}" width="${r.w}" height="${r.h}" rx="22" style="fill:var(${DOMC[d]});opacity:.07"/><rect x="${r.x}" y="${r.y}" width="${r.w}" height="${r.h}" rx="22" class="er-df" style="stroke:var(${DOMC[d]})"/><text x="${r.x+20}" y="${r.y+34}" class="er-dt" style="fill:var(${DOMC[d]})">${H(d)}</text></g>`});
 const hot=E.sel,edges=Md.refs.filter(r=>vis.has(r.from)&&vis.has(r.to)&&r.from!==r.to);let eg="";
 edges.forEach(r=>{const isH=hot&&(r.from===hot||r.to===hot);if(E.refs==="none"||(E.refs==="sel"&&!isH))return;if(r.ext&&!isH&&E.dom!=="CMDB")return;const a=L.pos[r.from],b=L.pos[r.to],ha=boxH(Md.T[r.from]),hb=boxH(Md.T[r.to]);let x1,x2,y1=a.y+ha/2,y2=b.y+hb/2;if(a.x+BW<b.x){x1=a.x+BW;x2=b.x}else if(b.x+BW<a.x){x1=a.x;x2=b.x+BW}else{x1=a.x+BW/2;x2=b.x+BW/2;y1=a.y<b.y?a.y+ha:a.y;y2=a.y<b.y?b.y:b.y+hb}
  const dx=Math.max(40,Math.abs(x2-x1)/2)*(x2>=x1?1:-1);const hz=x1!==a.x+BW/2||true;eg+=`<path d="M${x1} ${y1}C${x1+(Math.abs(x1-x2)<2?0:dx)} ${y1},${x2-(Math.abs(x1-x2)<2?0:dx)} ${y2},${x2} ${y2}" class="er-e ${isH?"hot":""} ${r.ext?"ext":""}"><title>${H(Md.T[r.from].label+" "+r.f+" to "+Md.T[r.to].label)}</title></path>`});
 g+=`<g>${eg}</g>`;
 keys.forEach(k=>{const t=Md.T[k],p=L.pos[k],d=Md.dom[k],fs=(t.fields||[]),ref=new Set(fs.filter(f=>f.type==="ref").map(f=>f.k)),shown=fs.slice().sort((a,b)=>(b.type==="ref")-(a.type==="ref")).slice(0,6).sort((a,b)=>fs.indexOf(a)-fs.indexOf(b)),h=boxH(t),dim=!match(k);
  g+=`<g class="er-t ${E.sel===k?"sel":""} ${dim?"dim":""}" data-er-t="${k}" transform="translate(${p.x},${p.y})" tabindex="0" role="button" aria-label="${H(t.label+", "+fs.length+" fields")}"><rect width="${BW}" height="${h}" rx="12" class="er-b"/><path d="M0 12a12 12 0 0 1 12-12h${BW-24}a12 12 0 0 1 12 12v20H0z" style="fill:var(${DOMC[d]})" class="er-h"/><text x="12" y="21" class="er-n">${H(trunc(t.label||k,25))}</text><text x="${BW-10}" y="21" text-anchor="end" class="er-c">${fs.length}</text>${shown.map((f,i)=>`<g class="er-f"><text x="12" y="${48+i*16}" class="er-ft ${ref.has(f.k)?"rf":""}">${ref.has(f.k)?"→ ":""}${H(trunc(f.label||f.k,22))}</text><text x="${BW-10}" y="${48+i*16}" text-anchor="end" class="er-fy">${H(f.type||"string")}</text></g>`).join("")}${fs.length>6?`<text x="12" y="${48+6*16}" class="er-fy er-f">+ ${fs.length-6} more fields</text>`:""}</g>`});
 return `<svg class="er-svg" width="${L.w}" height="${L.h}" viewBox="0 0 ${L.w} ${L.h}" role="group" aria-label="Entity relationship diagram">${g}</svg>`}
function miniSvg(L,Md,keys){const sc=200/L.w,h=Math.max(30,L.h*sc);return `<div class="er-mm" data-nopan="1"><svg width="200" height="${h}" data-mm="er" data-sc="${sc}" viewBox="0 0 200 ${h}" aria-label="Minimap. Select to move the view.">${Object.entries(L.rect).map(([d,r])=>`<rect x="${r.x*sc}" y="${r.y*sc}" width="${r.w*sc}" height="${r.h*sc}" style="fill:var(${DOMC[d]});opacity:.35" rx="2"/>`).join("")}${keys.map(k=>`<rect x="${L.pos[k].x*sc}" y="${L.pos[k].y*sc}" width="${BW*sc}" height="${boxH(Md.T[k])*sc}" style="fill:var(${DOMC[Md.dom[k]]})"/>`).join("")}<rect data-mm-vp="er" data-sc="${sc}" class="er-mv" x="0" y="0" width="40" height="30"/></svg></div>`}
function erPane(){const Md=MOD(),E=M.er,keys=Md.keys.filter(k=>E.dom==="All"||Md.dom[k]===E.dom),L=layout(keys,Md),s=pzInit("er",L.w,L.h,640);if(s.sig!==E.dom+"|"+keys.length){s.sig=E.dom+"|"+keys.length;const vp=Math.max(300,((document.getElementById("view")||document.body).clientWidth||1000)-60);s.k=Math.min(vp/L.w,640/L.h)*.97;s.x=8;s.y=8}
 return `<div class="row dev-ctl"><label class="small muted" for="erDom">Domain</label><select id="erDom" class="txtin" data-er-dom><option>All</option>${DOMS.map(d=>`<option ${E.dom===d[0]?"selected":""}>${H(d[0])}</option>`).join("")}</select><input type="search" class="txtin" placeholder="Search tables and fields" value="${H(E.q)}" data-er-q aria-label="Search tables and fields"><label class="small muted" for="erRef">References</label><select id="erRef" class="txtin" data-er-refs><option value="all" ${E.refs==="all"?"selected":""}>Show all</option><option value="sel" ${E.refs==="sel"?"selected":""}>Selected table only</option><option value="none" ${E.refs==="none"?"selected":""}>Hide</option></select><button class="btn" data-er-exp="json">Export JSON</button><button class="btn" data-er-exp="csv">Export CSV</button></div>
 ${pzBar("er")}<div class="er-wrap"><div class="map-vp er-vp ${s.k<.5?"lo":""}" data-pz="er" tabindex="0" role="application" aria-label="Master data model diagram. Drag to pan, plus and minus to zoom." style="height:640px"><div class="map-world" data-pz-world="er" style="width:${L.w}px;height:${L.h}px;${pzCss("er")}">${erSvg(L,Md,keys)}</div></div>${miniSvg(L,Md,keys)}</div>
 ${legend(DOMS.filter(d=>keys.some(k=>Md.dom[k]===d[0])).map(d=>[d[0],d[1]]).concat([["Reference field (arrow)","--faint"],["Selected table's references","--accent"]]))}<p class="muted small">At low zoom only table names show. Zoom in to read fields. ${keys.length} of ${Md.keys.length} tables shown.</p>`}
function stats(){const Md=MOD(),nf=Md.keys.reduce((a,k)=>a+(Md.T[k].fields||[]).length,0),totRef=Md.refs.filter(r=>!r.ext).length+Md.unres.length;METRICS.m_data_ref.cur=totRef?Math.round(Md.refs.filter(r=>!r.ext).length/totRef*100):100;return {Md,nf,tr:totRef}}
function tableRows(){const Md=MOD(),inn={},out={};Md.refs.forEach(r=>{out[r.from]=(out[r.from]||0)+1;inn[r.to]=(inn[r.to]||0)+1});return Md.keys.map(k=>{const t=Md.T[k];return {id:k,label:t.label||k,dom:Md.dom[k],source:t.source||"",nf:(t.fields||[]).length,out:out[k]||0,inn:inn[k]||0,own:DOMO[Md.dom[k]]}})}
function dataList(){return btHTML({id:"map_dm",h:520,rowH:52,key:"id",sort:{k:"label",d:1},exportName:"data-model-tables",facets:["dom","source"],groupBy:["dom","source"],cols:[{k:"label",label:"Table",val:r=>r.label,fmt:r=>`<b>${H(r.label)}</b><span class="sub">${H(r.id)}</span>`},{k:"dom",label:"Domain",val:r=>r.dom,fmt:r=>`<span class="pill" style="background:color-mix(in srgb,var(${DOMC[r.dom]}) 22%,transparent)">${H(r.dom)}</span>`},{k:"source",label:"Source",val:r=>r.source,fmt:r=>H(r.source)},{k:"nf",label:"Fields",val:r=>r.nf,fmt:r=>N0(r.nf)},{k:"out",label:"References out",val:r=>r.out,fmt:r=>N0(r.out)},{k:"inn",label:"Referenced by",val:r=>r.inn,fmt:r=>N0(r.inn)},{k:"own",label:"Data owner",val:r=>r.own,fmt:r=>H(r.own)}],rows:tableRows,open:id=>tableDrawer(id)})}
function overviewPane(){const {Md,nf,tr}=stats(),rows=tableRows(),bd={};rows.forEach(r=>bd[r.dom]=(bd[r.dom]||0)+1);const mx=Math.max(1,...Object.values(bd));
 return `<div class="statrow">${stat("Tables",N0(Md.keys.length),"registered by every module")}${stat("Fields",N0(nf),"across all tables")}${stat("References",N0(Md.refs.filter(r=>!r.ext).length),"between tables")}${stat("Domains",DOMS.filter(d=>bd[d[0]]).length,"of "+DOMS.length)}${stat("Reference integrity",METRICS.m_data_ref.cur+"%",Md.unres.length+" fields with no target table",null)}</div>
 <div class="row dev-chips">${fchip("m_data_ref")}${stdChip("dmbok","Data management: models, owners and quality for every data domain")}${stdChip("csdm","Common Service Data Model")}</div>
 ${card("Domains","The model reads every table that a module registers, so it is always current. Select a domain to see it in the diagram.",`<div class="er-doms">${DOMS.map(d=>`<button class="er-dc" data-er-dom-go="${H(d[0])}" style="--c:var(${d[1]})"><b>${H(d[0])}</b><span class="num" data-role="metric">${bd[d[0]]||0}</span><small>${bd[d[0]]?"tables · owner "+H(d[2]):"no tables registered yet"}</small><span class="er-db"><u style="width:${(bd[d[0]]||0)/mx*100}%"></u></span></button>`).join("")}</div>`)}
 ${card("All tables","Search, filter by domain or source, group, and export. Select a row for fields, references and the metrics that use it.",dataList())}`}
function integPane(){const {Md}=stats(),iso=Md.keys.filter(k=>!Md.refs.some(r=>r.from===k||r.to===k)),groups=[{key:"un",label:"Reference fields with no target table ("+Md.unres.length+")",rows:Md.unres.slice(0,200).map((u,i)=>({id:u.from+u.f+i,t:Md.T[u.from].label+": "+(u.lab||u.f),sub:"Field "+u.f+(u.guess?" points to "+u.guess+", which is not registered":" has no target declared"),tag:"Unresolved",st:"warn",go:()=>tableDrawer(u.from)}))},{key:"iso",label:"Tables with no references ("+iso.length+")",rows:iso.map(k=>({id:k,t:Md.T[k].label,sub:Md.T[k].source+" · "+Md.T[k].fields.length+" fields",tag:Md.dom[k],st:"mute",go:()=>tableDrawer(k)}))}];
 return `<div class="statrow">${stat("Reference integrity",METRICS.m_data_ref.cur+"%","resolved references")}${stat("Unresolved fields",Md.unres.length,"declare a target table")}${stat("Tables without references",iso.length,"may be standalone")}</div>`+card("Model checks","Unresolved fields mostly point to groups, vendors and sprints that are not registered as tables yet. Registering them closes the gap.",lrHTML({id:"map_int",groups,limit:8,search:true}))+`<div class="row dev-act">${fchip("m_data_ref")}</div>`}
function tableDrawer(k){const Md=MOD(),t=Md.T[k];if(!t)return;M.er.sel=k;const out=Md.refs.filter(r=>r.from===k),inn=Md.refs.filter(r=>r.to===k),d=Md.dom[k],word=(t.label||k).toLowerCase().split(/[ (]/)[0],ms=Object.entries(METRICS).filter(([id,m])=>word.length>3&&((m.f||"")+" "+(m.n||"")).toLowerCase().includes(word)).slice(0,8);
 const groups=[{key:"out",label:"References out ("+out.length+")",rows:out.map(r=>({id:r.from+r.f+r.to,t:(r.ext?"Extends ":"")+Md.T[r.to].label,sub:"Field "+r.f,tag:Md.dom[r.to],st:"info",go:()=>tableDrawer(r.to)}))},{key:"in",label:"Referenced by ("+inn.length+")",rows:inn.map(r=>({id:r.from+r.f+"in",t:Md.T[r.from].label,sub:"Field "+r.f,tag:Md.dom[r.from],st:"info",go:()=>tableDrawer(r.from)}))},{key:"met",label:"Metrics that use it ("+ms.length+")",rows:ms.map(([id,m])=>({id,t:m.n,sub:(m.owner||"")+" · "+(m.f||"").slice(0,90),tag:"Metric",st:"good",go:()=>go("metrics",id)}))}];
 openDrawer(`<div class="eyebrow">${H(d)} · ${H(t.source||"")}</div><h2 class="dev-h2">${H(t.label||k)}</h2><p class="muted"><code>${H(k)}</code></p>
 <div class="statrow">${stat("Fields",t.fields.length,"")}${stat("References out",out.length,"")}${stat("Referenced by",inn.length,"")}${stat("Data owner",H(DOMO[d]),"for the "+H(d)+" domain")}</div><div class="row dev-act"><button class="btn primary" data-er-show="${k}">Show on the diagram</button><button class="btn" data-er-json="${k}">Export this table as JSON</button>${fchip("m_data_ref")}</div>
 <div class="dfullgrid"><section class="card glass"><h3>Fields</h3><div class="tscroll"><table class="dev-tb"><thead><tr><th>Field</th><th>Name</th><th>Type</th><th>Detail</th></tr></thead><tbody>${t.fields.map(f=>{const to=(f.type==="ref")&&(f.to||RALIAS[f.k]);return `<tr><td><b>${H(f.label||f.k)}</b></td><td><code>${H(f.k)}</code></td><td>${H(f.type||"string")}</td><td>${to&&Md.T[to]?`<button class="dev-lk" data-er-t2="${to}">${H(Md.T[to].label)}</button>`:f.calc?H("Calculated "+f.calc):f.opts?H(f.opts.slice(0,4).join(", ")+(f.opts.length>4?"…":"")):""}</td></tr>`}).join("")}</tbody></table></div></section>
 <section class="card glass"><h3>Linked tables and metrics</h3>${lrHTML({id:"er_lr_"+k,groups,limit:6,search:true,empty:"Nothing linked."})}</section></div>`);audit("opened table",k)}
function dl(name,mime,txt){try{const a=document.createElement("a");a.href=URL.createObjectURL(new Blob([txt],{type:mime}));a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},500);return true}catch(e){return false}}
function exportModel(kind,only){const Md=MOD(),ks=only?[only]:Md.keys.filter(k=>M.er.dom==="All"||Md.dom[k]===M.er.dom);let ok;if(kind==="json")ok=dl(only?only+".json":"oukala-data-model.json","application/json",JSON.stringify(ks.map(k=>({table:k,label:Md.T[k].label,domain:Md.dom[k],source:Md.T[k].source,fields:Md.T[k].fields})),null,2));else{const q=s=>'"'+String(s==null?"":s).replace(/"/g,'""')+'"',rows=[["table","domain","field","label","type","references","calculated"].map(q).join(",")];ks.forEach(k=>Md.T[k].fields.forEach(f=>rows.push([k,Md.dom[k],f.k,f.label,f.type,f.type==="ref"?(f.to||RALIAS[f.k]||""):"",f.calc||""].map(q).join(","))));ok=dl("oukala-data-model.csv","text/csv",rows.join("\n"))}
 audit("exported data model",kind+" "+ks.length+" tables");toast(ok?"Exported "+ks.length+" table"+(ks.length===1?"":"s")+" as "+kind.toUpperCase():"The browser blocked the download.",ok?"good":"warn")}
document.addEventListener("click",e=>{const t=e.target.closest("[data-er-t],[data-er-t2],[data-er-exp],[data-er-json],[data-er-show],[data-er-dom-go]");if(!t)return;const d=t.dataset;
 if(d.erT){M.er.sel=d.erT;document.querySelectorAll("[data-er-t]").forEach(x=>x.classList.toggle("sel",x.dataset.erT===d.erT));tableDrawer(d.erT);if(M.er.refs==="sel"){render()}return}
 if(d.erT2){tableDrawer(d.erT2);return}if(d.erExp){exportModel(d.erExp);return}if(d.erJson){exportModel("json",d.erJson);return}
 if(d.erShow){closeDrawer();S.v.map_d=1;render();setTimeout(()=>{const L=document.querySelector(`[data-er-t="${d.erShow}"]`);if(L){const m=/translate\(([\d.]+),([\d.]+)\)/.exec(L.getAttribute("transform"));pzZoom("er",1/PZ.er.k*Math.max(.8,PZ.er.k),0,0);pzCenter("er",+m[1]+118,+m[2]+60)}},100);return}
 if(d.erDomGo){M.er.dom=d.erDomGo;S.v.map_d=1;render()}});
