/* ---------------- Monte Carlo (triangular durations, risk events, 2,000 trials) ---------------- */
const mulberry=a=>()=>{a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296};
const tri=(r,a,m,b)=>{if(b<=a)return m;const u=r(),c=(m-a)/(b-a);return u<c?a+Math.sqrt(u*(b-a)*(m-a)):b-Math.sqrt((1-u)*(b-a)*(b-m))};
const MAPR={RK1:["p1_3",4],RK7:["p1_4",3],RK2:["p3_4",6],RK6:["p4_4",8]},BIZ={RK2:1,RK3:1,RK5:1};
function mcRun(o){const r=mulberry(o.seed),n=o.n,ex=Object.assign({},S.imsSlip||{});Object.keys(o.slip||{}).forEach(k=>ex[k]=(ex[k]||0)+o.slip[k]);if(o.crash)ex.p1_3=(ex.p1_3||0)-4;
 const base={};TASKS.forEach(t=>{base[t.id]=(o.cut&&t.p==="PR4")?0:Math.max(t.ms?0:1,t.dur+(ex[t.id]||0))});
 const dR=cpm(t=>base[t.id]).R,pst={},pen={};
 PROJ.forEach(p=>{const ts=TASKS.filter(t=>t.p===p.id);pst[p.id]=Math.min(...ts.map(t=>dR[t.id].es));pen[p.id]=Math.max(...ts.map(t=>dR[t.id].ef))});
 const fc=PROJ.map(p=>({id:p.id,f:(o.cut&&p.id==="PR4")?0:p.bac*METRICS.m_burn.cur/100,db:.6*p.bac/Math.max(20,pen[p.id]-pst[p.id])}));
 const TO=[],seen={},byId={};TASKS.forEach(t=>byId[t.id]=t);const visit=t=>{if(seen[t.id])return;seen[t.id]=1;t.pred.forEach(p=>{const q=byId[predId(p)];if(q)visit(q)});TO.push(t)};TASKS.forEach(visit);
 const out={beta:[],live:[],pilot:[],cost:[]};
 for(let i=0;i<n;i++){const add={};let cost=0;
  if(o.events)E.risks.forEach(x=>{if(x.st!=="Closed"&&r()<x.p){const m=MAPR[x.id];if(o.cut&&x.id==="RK6")return;if(!BIZ[x.id])cost+=x.amt;if(m)add[m[0]]=(add[m[0]]||0)+m[1]}});
  const ef={},pe={};
  for(const t of TO){let d=base[t.id];
   if(!t.ms&&t.pct<100&&d>0){const a=Math.max(.8,1-.08*o.unc),b=1+(t.ven?.22*o.lum:.12)*o.unc,f=tri(r,a,1,b);d=d*t.pct/100+d*(1-t.pct/100)*f}
   if(d>0||t.ms)d+=add[t.id]||0;d=Math.round(d);if(!t.ms&&base[t.id]>0)d=Math.max(1,d);
   let es=t.snet?wdOf(t.snet):0;for(const p of t.pred)es=Math.max(es,ef[predId(p)]+predLag(p));ef[t.id]=es+d;pe[t.p]=Math.max(pe[t.p]||0,es+d)}
  let c=cost;fc.forEach(x=>{c+=x.f*tri(r,.99,1,1+.05*o.unc)+x.db*Math.max(0,pe[x.id]-pen[x.id])});
  out.beta.push(ef.p1_5);out.live.push(ef.p1_9);out.pilot.push(ef.p2_5);out.cost.push(c)}
 ["beta","live","pilot","cost"].forEach(k=>out[k].sort((a,b)=>a-b));
 out.det={beta:dR.p1_5.ef,live:dR.p1_9.ef,pilot:dR.p2_5.ef,cost:fc.reduce((s,x)=>s+x.f,0)};
 out.n=n;out.q=(k,p)=>out[k][Math.floor(p*(out.n-1))];out.pr=(k,x)=>{let lo=0,hi=out[k].length;while(lo<hi){const m=(lo+hi)>>1;if(out[k][m]<=x)lo=m+1;else hi=m}return lo/out[k].length};
 out.mean=k=>out[k].reduce((s,v)=>s+v,0)/out[k].length;return out}
const mcC={};
function mc(o){o=Object.assign({},E.mc,o||{});const key=JSON.stringify([o.unc,o.lum,o.events,o.seed,o.n,o.slip,o.cut,o.crash,S.imsSlip,E.risks.map(r=>r.id+r.p+":"+r.amt)]);if(!mcC[key]){const ks=Object.keys(mcC);if(ks.length>40)delete mcC[ks[0]];mcC[key]=mcRun(o)}return mcC[key]}
