function appStats(){const t=appCost(),by={Invest:0,Migrate:0,Tolerate:0,Eliminate:0};E.apps.forEach(a=>by[tOf(a)]+=a.cost);
 const waste=E.apps.filter(a=>tOf(a)==="Eliminate"||a.red).reduce((s,a)=>s+a.cost,0);return {total:t,by,waste,pct:t?waste/t*100:0}}
function appRecs(){return E.apps.map(a=>{const t=tOf(a),red=a.red&&E.apps.find(x=>x.id===a.red);let act=null;
 if(E.timeWhy[a.id]&&E.timeWhy[a.id].done)return null;
 if(a.red&&red)act={k:"Retire",why:`${a.n} duplicates ${red.n}. ${a.users} users can move with no loss of function.`,save:a.cost,conf:.88,eff:"4 to 6 weeks"};
 else if(t==="Eliminate")act={k:"Retire",why:`Business value ${a.val} and technical health ${a.hlt} are both low. ${a.users} users, $${a.cost}K a year.`,save:a.cost,conf:.82,eff:"6 to 8 weeks"};
 else if(t==="Migrate"&&a.life==="Sunset")act={k:"Replace",why:`Valuable (${a.val}) but failing (health ${a.hlt}) and already at sunset. A funded project is the replacement path.`,save:0,conf:.74,eff:"Tracked in its project"};
 return act?{a,...act}:null}).filter(Boolean).sort((x,y)=>y.save-x.save)}

