const SC_BEN_PR4=480;
function scenCalc(sc){const ex=Object.assign({},S.imsSlip||{}),lum=+sc.lumen||0,cr=sc.crash?-4:0;
 const dur=t=>(sc.cut&&t.p==="PR4")?0:Math.max(t.ms?0:1,t.dur+(ex[t.id]||0)+(t.id==="p1_3"?lum+cr:0));
 const P=cpm(dur),L=rank(S.w,sc.env,S.cap),extra=L.filter(d=>d.fund).map(d=>({res:d.res,m0:d.m0,mo:d.mo})),g=load(P,extra);
 let peak={v:0},over=0;Object.keys(g).forEach(t=>g[t].forEach((v,i)=>{if(i>=3&&i<=6){if(v>peak.v)peak={v,team:t,mo:MONTHS[i][0]};if(v>1.05)over++}}));
 const m=mc({slip:{p1_3:lum},crash:!!sc.crash,cut:!!sc.cut}),cw=commitWd(),bud=PROJ.reduce((s,p)=>s+(sc.cut&&p.id==="PR4"?0:p.bac),0);
 const expo=E.risks.reduce((s,r)=>{if(r.st==="Closed")return s;if(sc.cut&&r.id==="RK6")return s;let p=r.p;if(r.id==="RK1"){p=clamp(p+.02*lum-(sc.crash?.1:0),.02,.95)}return s+p*r.amt},0);
 const fin=id=>Math.max(...TASKS.filter(t=>t.p===id).map(t=>P.R[t.id].ef));
 return {beta:P.R.p1_5.ef,live:P.R.p1_9.ef,pilot:P.R.p2_5.ef,pr4:sc.cut?null:fin("PR4"),p80:m.q("beta",.8),p80live:m.q("live",.8),pr:m.pr("beta",cw),bud,cost80:m.q("cost",.8),costM:m.mean("cost"),dem:L.spent,demN:L.filter(d=>d.fund).length,peak,over,expo,ben:L.filter(d=>d.fund).reduce((s,d)=>s+d.ben,0)+(sc.cut?0:SC_BEN_PR4)}}
