 if(/retire|decommission|redundan|duplicate app|which apps|app portfolio|application portfolio/.test(l)){const R=appRecs().filter(r=>r.k==="Retire"),sv=R.reduce((s,r)=>s+r.save,0);S.v.exeappv=3;go("exe_apps");say(q,{t:`Retire ${R.map(r=>r.a.n).join(", ")}: ${R.length} applications worth ${money(sv*1000)} a year. Each is duplicated by something we already own or sits in the Eliminate group. ${appRecs().filter(r=>r.k==="Replace").map(r=>r.a.n).join(" and ")} should be replaced through projects already funded.`,steps:["Scored value and technical health for every application","Checked overlap and usage","Left acceptance to the owner"],act:()=>{S.v.exeappv=3;go("exe_apps")}});return true}
 if(/heat ?map|top risks?|risk (register|exposure)|biggest risk/.test(l)){const s=snap(),t=topRisks(3);S.v.exeriskv=0;go("exe_risk");say(q,{t:`Expected loss is ${K$(Math.round(s.exposure))}, ${Math.round(s.exposure/s.contingency*100)}% of the ${K$(Math.round(s.contingency))} contingency. Top three: ${t.map(r=>`${r.n} (${K$(Math.round(rX(r)))})`).join("; ")}.`,steps:["Multiplied probability by impact for each risk","Compared with contingency"],act:()=>{S.v.exeriskv=0;go("exe_risk")}});return true}
 if(/scenario|compare.*(plan|option)|what if we cut|cut the contract/.test(l)){const sel=E.scSel.map(id=>E.scens.find(x=>x.id===id)).filter(Boolean),R=sel.map(sc=>[sc,scenCalc(sc)]);go("exe_scen");say(q,{t:R.map(([sc,r])=>`${sc.n}: beta ${dstr(r.beta)}, ${Math.round(r.pr*100)}% by ${dstr(commitWd())}, project cost ${K$(Math.round(r.cost80))} at 80%`).join(". ")+".",steps:["Ran each scenario through schedule, capacity and Monte Carlo"],act:()=>go("exe_scen")});return true}
