const doaTiers=()=>(S.bud&&S.bud.doa&&S.bud.doa.length?S.bud.doa:DOA_FALLBACK);
const doaFor=amt=>doaTiers().find(t=>amt<=t.max)||doaTiers()[doaTiers().length-1];
function approverFor(n,rec,ctx){const a=n.a;if(a.tiers==="doa"){const amt=num(ctx[a.amountField||"rec.amount"]!=null?ctx[a.amountField||"rec.amount"]:rec.amount||rec.budget||rec.target,0);const t=doaFor(amt);return{who:t.role,why:"delegation of authority: "+usd(amt)+" falls in tier "+t.id+" up to "+(t.max===Infinity?"no limit":money(t.max))}}return{who:(a.approvers||[]).join(" and ")||"nobody",why:a.mode==="quorum"?"quorum of "+a.quorum:a.mode==="all"?"all must approve":a.mode==="seq"?"in sequence":"any one"}}
