function convCard(f,n,c,link){return `<article class="wfd-cc glass"><div class="row sp"><b>${X(n.n)}</b>${pill(Math.round(c.conf*100)+"% confidence",c.conf>.8?"good":"warn")}</div><div class="muted small">${X(f.name)}</div><div class="wfd-ccn"><span><b class="num" data-role="metric">${fh(c.saveH)}</b> saved per run</span><span><b class="num" data-role="metric">${usd(c.perMonth)}</b> a month</span></div><div class="small">${X(c.why[0])}</div><div class="row">${link?`<button class="btn" data-wfd-go="${X(f.id)}" data-wfd-gonode="${X(n.id)}">Open step</button>`:""}<button class="btn primary" data-wfd-conv="${X(f.id)}|${X(n.id)}">Convert to agentic</button></div></article>`}
function newFlowForm(){openForm({id:"wfd_new",title:"New workflow",story:"Creates a draft with a trigger and an end. Nothing runs until you publish. Pick a table and the designer offers its fields as data pills in every step.",submit:"Create and open",defaults:{kind:"approval",table:"request_item",src:"record",from:"blank",owner:me()},
 fields:[{section:"What it is"},{k:"name",label:"Workflow name",type:"text",req:true,ph:"Vendor onboarding approval"},{k:"desc",label:"What it does",type:"longtext",ph:"One sentence a new owner would understand"},{k:"kind",label:"Kind",type:"select",opts:["request","incident","change","approval","onboarding","release","contract","purchase"]},{k:"owner",label:"Workflow owner",type:"people"},{section:"Starts when"},{k:"src",label:"Trigger",type:"chips",opts:TRIG},{k:"table",label:"Trigger record (data pills come from here)",type:"select",opts:Object.entries(DATAMODEL.tables).map(([k,v])=>[k,v.label])},{section:"Start from"},{k:"from",label:"Starting point",type:"select",opts:[["blank","Blank canvas"]].concat(allFlows().slice(0,60).map(f=>["copy:"+f.id,"Copy of "+f.name]))}],
 onSubmit:v=>{let nf;if(v.from&&v.from.startsWith("copy:")){const s=getFlow(v.from.slice(5));nf=clone(Object.assign({},s,{_row:null,_st:null,_val:null,_def:null,undo:[],redo:[]}));nf.id="wf_"+uid();nf.name=v.name;nf.src="designer";nf.srcId="";nf.ver=1;nf.pub=null;nf.history=[]}else{nf=BF("wf_"+uid(),v.name,v.desc,{kind:v.kind,owner:v.owner||me(),table:v.table,lanes:[{n:"Requester"},{n:"Team"},{n:"AI agents"}]},[["T1","trigger","Start",0,0,0,{src:v.src||"record",ev:(TRIG.find(t=>t[0]===v.src)||[0,"Record change"])[1]},{}],["H1","human","First step",1,1,0,{},{tg:{sla:"1 d",dur:4}}],["E1","end","Done",1,2,0,{},{}]],[["T1","H1"],["H1","E1"]])}
  nf.owner=v.owner||nf.owner;if(v.desc)nf.desc=v.desc;nf.dirty=true;F.W.push(nf);audit("created workflow",nf.name);openEditor(nf.id);return{toast:"Workflow created. Drag steps from the palette."}}})}
/* ================================================================ WORKFLOW DESIGNER: EDITOR, CANVAS, INTERACTIONS */
F.ed=F.ed||{ovl:"mix",q:"",pane:"valid",conn:null,sel:null,selE:null,sim:null,insp:"step",grp:true};
const E=F.ed;
const curFlow=()=>F.open?getFlow(F.open):null;
const selNode=f=>E.sel&&nodeById(f,E.sel);
const snapF=f=>JSON.stringify({nodes:f.nodes,edges:f.edges,lanes:f.lanes,groups:f.groups,vars:f.vars});
function pushU(f,s){s=s||snapF(f);if(f.undo[f.undo.length-1]!==s){f.undo.push(s);if(f.undo.length>60)f.undo.shift();f.redo=[]}}
function restoreF(f,s){const o=JSON.parse(s);f.nodes=o.nodes;f.edges=o.edges;f.lanes=o.lanes;f.groups=o.groups;f.vars=o.vars;touch(f)}
function undo(){const f=curFlow();if(!f||!f.undo.length){toast("Nothing to undo","info");return}f.redo.push(snapF(f));restoreF(f,f.undo.pop());if(E.sel&&!selNode(f))E.sel=null;audit("undo",f.name);paintAll()}
function redo(){const f=curFlow();if(!f||!f.redo.length){toast("Nothing to redo","info");return}f.undo.push(snapF(f));restoreF(f,f.redo.pop());audit("redo",f.name);paintAll()}
function mut(fn,msg,quiet){const f=curFlow();pushU(f);fn(f);touch(f);if(msg&&!quiet)audit(msg[0],msg[1]||f.name);paintAll()}
function openEditor(id,node){F.open=id;E.sel=node||null;E.selE=null;E.conn=null;stopSim();E.sim=null;E.q="";E.tab="do";E.insp="step";E.pane="valid";if(S.screen==="flw_design"){render();window.scrollTo({top:0})}else go("flw_design");if(node)setTimeout(()=>{paintInsp();const el=$q(`[data-wfd-node="${node}"]`);if(el)el.scrollIntoView({block:"center",inline:"center"})},60)}
const rs=()=>matchMedia("(prefers-reduced-motion:reduce)").matches||document.documentElement.dataset.motion==="reduced";
/* ---- view graph: collapsed sub-flow groups become one node ---- */
function viewG(f){const col=f.groups.filter(g=>g.collapsed);if(!col.length)return{nodes:f.nodes.map(n=>({n,id:n.id,x:n.x,y:nodeY(n),l:n.l})),edges:f.edges};
 const mem={};f.nodes.forEach(n=>{if(n.g&&col.some(g=>g.id===n.g))mem[n.id]="grp:"+n.g});const nodes=f.nodes.filter(n=>!mem[n.id]).map(n=>({n,id:n.id,x:n.x,y:nodeY(n),l:n.l}));
 col.forEach(g=>{const ms=f.nodes.filter(n=>n.g===g.id);if(!ms.length)return;nodes.push({virt:g,id:"grp:"+g.id,x:Math.min(...ms.map(m=>m.x)),y:laneTop(ms[0].l)+12,l:ms[0].l,ms})});
 const seen=new Set(),edges=[];f.edges.forEach(e=>{const a=mem[e.f]||e.f,b=mem[e.t]||e.t;if(a===b)return;const k=a+"|"+(mem[e.f]?"next":e.p)+"|"+b;if(seen.has(k))return;seen.add(k);edges.push({id:e.id,f:a,p:mem[e.f]?"next":e.p,t:b})});return{nodes,edges}}
const findV=(vg,id)=>vg.nodes.find(v=>v.id===id);
function portFr(v,port){if(v.virt)return .5;const o=outs(v.n),i=Math.max(0,o.indexOf(port)),k=o.length;return k<=1?.5:.2+.6*i/(k-1)}
function edgeGeom(vg,e){const a=findV(vg,e.f),b=findV(vg,e.t);if(!a||!b)return null;const x1=a.x+NW,y1=a.y+NH*portFr(a,e.p),x2=b.x,y2=b.y+NH/2;let d,mx=(x1+x2)/2,my=(y1+y2)/2;
 if(x2<x1+30){const ym=Math.max(a.y,b.y)+NH+16+(a.l===b.l?0:0);d=`M${x1} ${y1}C${x1+50} ${y1} ${x1+50} ${ym} ${(x1+x2)/2} ${ym}S${x2-50} ${y2} ${x2} ${y2}`;mx=(x1+x2)/2;my=ym}
 else{const dx=Math.max(40,(x2-x1)/2);d=`M${x1} ${y1}C${x1+dx} ${y1} ${x2-dx} ${y2} ${x2} ${y2}`}return{d,mx,my}}
function metaOf(f,n){const a=n.a;switch(n.t){case"trigger":return a.ev||"Starts";case"human":return asgName(n)+(slaOf(n)?" · SLA "+fh(slaOf(n)):"");case"approval":{const ap=approverFor(n,recOf(f),{});return ap.who+(a.asm&&a.asm.length?" · "+a.asm.length+" assessment"+(a.asm.length>1?"s":""):"")}case"assessment":return((ASSESS_TYPES().find(t=>t.id===a.type)||{}).n||"Choose a type")+" · "+(a.gate==="advisory"?"advisory":"required gate");case"agent":return a.agent+" · "+((AUTON.find(x=>x[0]===a.autonomy)||[0,"Propose"])[1]);case"auto":return a.op;case"decision":return a.mode==="dmn"?"Table: "+(((F.dmn||[]).find(t=>t.id===a.dmn)||{}).name||"choose"):(a.branches||[]).length+" branch"+((a.branches||[]).length===1?"":"es")+" + else";case"wait":return a.kind==="timer"?"Wait "+fh(isoH(a.dur)):"Until "+(a.until||a.ev||"event");case"parallel":return a.kind==="fork"?"Fork: all paths run":"Join: wait for all";case"loop":return"For each in "+(a.over||"list");case"subflow":return(a.name||((getFlow(a.ref)||{}).name)||"Choose a workflow");default:return a.outcome}}
function ovChip(f,n,st){const o=E.ovl;if(o==="mix")return"";if(!WORKT.includes(n.t)&&n.t!=="wait")return"";const s=st(n);
 if(o==="sla"){const sl=slaOf(n);if(!sl&&!n.p.tg.ola&&!n.p.tg.xla)return`<i class="wfd-oc none" title="No SLA, OLA or XLA target">no target</i>`;return`<i class="wfd-oc ${s.met==null?"none":s.met>=95?"good":s.met>=85?"warn":"bad"}" title="Target met in ${s.met==null?"n/a":s.met+"%"} of the last 30 days">${sl?fh(sl):"OLA"} · ${s.met==null?"-":Math.round(s.met)+"%"}</i>`}
 if(o==="cost"){const c=costOf(n);return`<i class="wfd-oc ${c>40?"bad":c>10?"warn":"good"}" title="${X(costBasis(n))}">${usd(c)}</i>`}
 if(o==="perf"){return`<i class="wfd-oc ${s.el>12?"bad":s.el>4?"warn":"good"}" title="Average elapsed time including queue wait">${fh(s.el)}</i>`}return""}
function nodeHTML(f,v,ctx){const z=E.q&&E.q.length>1,T=v.virt?null:NTY[v.n.t];
 if(v.virt){const ms=v.ms,h=ms.filter(n=>dClass(n)==="human").length,a=ms.filter(n=>dClass(n)==="agentic").length,d=ms.filter(n=>dClass(n)==="deterministic").length;
  return `<div class="wfd-node t-group${E.sel===v.id?" sel":""}" data-wfd-node="${v.id}" tabindex="0" role="button" aria-label="Collapsed sub-flow ${X(v.virt.n)}, ${ms.length} steps. Press Enter to expand." style="left:${v.x}px;top:${v.y}px;--nc:var(--u4)"><button class="wfd-nin" data-wfd-in="${v.id}" aria-label="Connect here"></button><div class="wfd-nh"><span class="wfd-ni">${IC(NTY.subflow.d)}</span><span>Collapsed sub-flow</span></div><div class="wfd-nn">${X(v.virt.n)}</div><div class="wfd-nm">${ms.length} steps ${mixBar(h,a,d)}</div><button class="wfd-nout" data-wfd-out="${v.id}|next" style="top:50%" aria-label="Connect from ${X(v.virt.n)}"></button></div>`}
 const n=v.n,sim=E.sim,res=sim&&sim.res,idx=res?res.steps.slice(0,sim.i+1):[],act=res&&res.steps[sim.i]&&res.steps[sim.i].nid===n.id,dn=res&&idx.some(s=>s.nid===n.id),sk=res&&idx.some(s=>s.nid===n.id&&s.status==="skipped");
 const hit=z&&(n.n+" "+metaOf(f,n)+" "+T.l).toLowerCase().includes(E.q.toLowerCase());const iss=validate(f).some(x=>x.node===n.id&&x.sev==="err");
 const o=outs(n),ports=o.map((p,i)=>{const fr=portFr(v,p);return `<button class="wfd-nout${E.conn&&E.conn.from===n.id&&E.conn.port===p?" on":""}${f.edges.some(e=>e.f===n.id&&e.p===p)?" used":""}" data-wfd-out="${n.id}|${p}" style="top:${fr*100}%" aria-label="Start a connection from ${X(n.n)}${p!=="next"?", "+p+" port":""}" title="${p==="next"?"Drag to the next step":p+": drag to a step"}">${o.length>1?`<i>${X(p.length>14?p.slice(0,13)+"…":p)}</i>`:""}</button>`}).join("");
 const m=modeOf(n);return `<div class="wfd-node t-${n.t} m-${m}${E.sel===n.id?" sel":""}${act?" run-act":""}${dn&&!act?" run-done":""}${sk?" run-skip":""}${hit?" hit":""}${z&&!hit?" dim":""}${E.conn&&E.conn.from!==n.id&&n.t!=="trigger"?" can-in":""}${iss?" has-err":""}" data-wfd-node="${n.id}" tabindex="0" role="button" aria-label="${X(T.l)}: ${X(n.n)}. ${X(metaOf(f,n))}. Press Enter to edit, arrow keys to move, Delete to remove." style="left:${v.x}px;top:${v.y}px;--nc:var(${m==="control"?T.c:MODES[m][1]})"><span class="wfd-stripe" style="background:var(${T.c})"></span>
  ${n.t!=="trigger"?`<button class="wfd-nin" data-wfd-in="${n.id}" aria-label="Connect here: ${X(n.n)}" title="Drop a connection here"></button>`:""}
  <div class="wfd-nh"><span class="wfd-ni" style="--nc:var(${T.c})">${IC(T.d)}</span><span class="wfd-nt">${T.l}${n.t==="approval"||n.t==="assessment"?(n.t==="assessment"?(n.a.gate==="advisory"?" · advisory":" · gate"):""):""}</span>${iss?`<i class="wfd-err" title="Blocking problem">!</i>`:""}${ovChip(f,n,x=>ctx.st(x))}</div><div class="wfd-nn">${X(n.n)}</div><div class="wfd-nm">${X(metaOf(f,n))}</div>${ports}</div>`}
function canvasHTML(f){const vg=viewG(f),zm=E.zoom||1,W=Math.max(1000,...vg.nodes.map(v=>v.x+NW+140)),H=Math.max(LH*2,f.lanes.length*LH+30);const runs=flowStat(f).runs,cache={};const ctx={st:n=>cache[n.id]||(cache[n.id]=stepStat(f,n,runs))};
 let e="";vg.edges.forEach(ed=>{const g=edgeGeom(vg,ed);if(!g)return;const sim=E.sim,done=sim&&sim.res.steps.slice(0,sim.i+1).some(s=>(s.edges||[]).includes(ed.id)),sel=E.selE===ed.id;e+=`<g class="wfd-edge${sel?" sel":""}${done?" done":""}" data-wfd-edge="${ed.id}" tabindex="0" role="button" aria-label="Connection from ${X((findV(vg,ed.f).n||findV(vg,ed.f).virt).n||"")} to ${X((findV(vg,ed.t).n||findV(vg,ed.t).virt).n||"")}"><path class="hit" d="${g.d}"/><path class="vis" d="${g.d}" marker-end="url(#wfdArr)"/>${ed.p!=="next"?`<text class="wfd-elab" x="${g.mx}" y="${g.my-6}" text-anchor="middle">${X(ed.p)}</text>`:""}</g>`});
 const lanes=f.lanes.map((l,i)=>{const cnt=f.nodes.filter(n=>n.l===i).length;return `<div class="wfd-lane${i%2?" alt":""}" style="top:${i*LH}px;height:${LH}px;width:${W}px"><div class="wfd-lanelab"><b>${X(l.n)}</b><small>${cnt} step${cnt===1?"":"s"}</small><button class="wfd-lbtn" data-wfd-lane="${i}" aria-label="Edit lane ${X(l.n)}" title="Rename or delete lane">${IC("M4 20h4l10-10-4-4L4 16zM13 7l4 4")}</button></div></div>`}).join("");
 return `<div class="wfd-sizer" style="width:${W*zm}px;height:${H*zm}px"><div class="wfd-world" style="width:${W}px;height:${H}px;transform:scale(${zm})">${lanes}<svg class="wfd-edges" width="${W}" height="${H}" aria-hidden="false"><defs><marker id="wfdArr" viewBox="0 0 10 10" refX="9" refY="5" markerUnits="userSpaceOnUse" markerWidth="11" markerHeight="11" orient="auto-start-reverse"><path d="M0 1L10 5L0 9z" class="wfd-arrow"/></marker></defs>${e}<path class="wfd-tmp" d="" style="display:none"/></svg>${vg.nodes.map(v=>nodeHTML(f,v,ctx)).join("")}</div></div>`}
function mmHTML(f){const vg=viewG(f),W=Math.max(1000,...vg.nodes.map(v=>v.x+NW+140)),H=Math.max(LH*2,f.lanes.length*LH+30);
 return `<svg class="wfd-mmsvg" viewBox="0 0 ${W} ${H}" preserveAspectRatio="xMinYMin meet" data-wfd-mm aria-label="Minimap. Click to move the view." role="img">${f.lanes.map((l,i)=>`<rect x="0" y="${i*LH}" width="${W}" height="${LH}" class="${i%2?"la":"lb"}"/>`).join("")}${vg.edges.map(e=>{const g=edgeGeom(vg,e);return g?`<path d="${g.d}" class="me"/>`:""}).join("")}${vg.nodes.map(v=>`<rect x="${v.x}" y="${v.y}" width="${NW}" height="${NH}" rx="10" style="fill:var(${v.virt?"--u4":(modeOf(v.n)==="control"?NTY[v.n.t].c:MODES[modeOf(v.n)][1])})"/>`).join("")}<rect class="vp" x="0" y="0" width="100" height="100"/></svg>`}
function updateMM(){const cv=$q("#wfdCanvas"),mm=$q(".wfd-mmsvg .vp");if(!cv||!mm)return;const z=E.zoom||1;mm.setAttribute("x",cv.scrollLeft/z);mm.setAttribute("y",cv.scrollTop/z);mm.setAttribute("width",cv.clientWidth/z);mm.setAttribute("height",cv.clientHeight/z)}
function paletteHTML(){return `<div class="wfd-pal" role="list" aria-label="Step palette. Drag onto the canvas, or press Enter to add."><div class="eyebrow">Add a step</div>${PAL.map(t=>`<button class="wfd-pi" role="listitem" data-wfd-pal="${t}" style="--nc:var(${NTY[t].mode==="control"?NTY[t].c:MODES[NTY[t].mode][1]})" title="${X(NTY[t].note)}"><span class="wfd-ni" style="--nc:var(${NTY[t].c})">${IC(NTY[t].d)}</span><span><b>${NTY[t].l}</b><small>${X(NTY[t].note)}</small></span></button>`).join("")}</div>`}
const OVL=[["mix","Who does it"],["sla","Targets"],["cost","Cost"],["perf","Performance"]];
function ovlLegend(){const o=E.ovl;if(o==="mix")return legend([["Human","--u3"],["Agentic","--p4"],["Deterministic","--s3"],["Control (trigger, wait, gateway, sub-flow, end)","--muted"]]);if(o==="sla")return legend([["Target met 95% or more of the time","--good-f"],["85 to 95%","--warn-f"],["Under 85%","--bad-f"],["No SLA, OLA or XLA set","--faint"]]);if(o==="cost")return legend([["Under $10 a run","--good-f"],["$10 to $40","--warn-f"],["Over $40","--bad-f"]]);return legend([["Average elapsed time under 4 h","--good-f"],["4 to 12 h","--warn-f"],["Over 12 h (including queue wait)","--bad-f"]])}
function statusHTML(f){const dirty=f.dirty,pub=f.pub;return pub==null?pill("Draft v"+f.ver+" · never published","warn"):dirty?pill("Draft v"+f.ver+" · changes since v"+pub,"warn")+" "+pill("Published v"+pub,"good"):pill("Published v"+pub,"good")}
function headHTML(f){const v=validate(f),errs=v.filter(x=>x.sev==="err").length,r=rowOf(f),hasG=f.groups.length;
 return `<section class="card glass wfd-head"><div class="row sp"><div class="row"><button class="btn quiet" data-wfd-back aria-label="Back to all workflows">${IC("M15 5l-7 7 7 7")} All workflows</button><div><h3 style="margin:0">${X(f.name)}</h3><span class="muted small" data-role="story">${X(f.desc)}</span></div></div><div class="row" id="wfdStatus">${statusHTML(f)}${pill(errs?errs+" problem"+(errs>1?"s":""):"Validates clean",errs?"bad":"good")}<span class="pill mute">${r.src}</span></div></div>
 <div class="wfd-tb"><span class="row" role="group" aria-label="History"><button class="chip" data-wfd-undo ${f.undo.length?"":"disabled"} aria-label="Undo" title="Undo (Ctrl+Z)">${IC("M9 7L4 12l5 5M4 12h11a5 5 0 0 1 0 10h-2")} Undo</button><button class="chip" data-wfd-redo ${f.redo.length?"":"disabled"} aria-label="Redo" title="Redo (Ctrl+Y)">Redo ${IC("M15 7l5 5-5 5M20 12H9a5 5 0 0 0 0 10h2")}</button></span>
  <span class="row" role="group" aria-label="Show"><span class="muted small">Show</span>${OVL.map(o=>`<button class="chip" data-wfd-ovl="${o[0]}" aria-pressed="${E.ovl===o[0]}">${o[1]}</button>`).join("")}</span>
  <span class="row" role="group" aria-label="Zoom"><button class="chip" data-wfd-zoom="-" aria-label="Zoom out">−</button><button class="chip" data-wfd-zoom="fit">Fit</button><button class="chip" data-wfd-zoom="+" aria-label="Zoom in">+</button><span class="muted small num">${Math.round((E.zoom||1)*100)}%</span></span>
  <input class="txtin wfd-find" type="search" placeholder="Find a step (${f.nodes.length})" value="${X(E.q)}" data-wfd-find aria-label="Search steps">${hasG?`<button class="chip" data-wfd-colall aria-pressed="${f.groups.every(g=>g.collapsed)}">${f.groups.every(g=>g.collapsed)?"Expand":"Collapse"} ${f.groups.length} sub-flows</button>`:`<button class="chip" data-wfd-mkgroup>Group selected step into a sub-flow</button>`}<button class="chip" data-wfd-tidy>Tidy layout</button><button class="chip" data-wfd-addlane>+ Lane</button></div>
 <div class="row wfd-actions"><button class="btn primary" data-wfd-test>${ico("bolt")}Test run</button><button class="btn" data-wfd-publish>Publish…</button><button class="btn" data-wfd-export>Export JSON</button><button class="btn" data-wfd-import="here">Import JSON</button><button class="btn quiet" data-wfd-edit>Rename and settings</button>${MET("m_wfauto","m_wfsla","m_wfstep")}<span class="muted small">${r.work} work steps · ${r.autoPct}% automated · ${r.slaCov}% with a target</span></div></section>`}
function editorBody(f){return `<div data-wfd-root>${headHTML(f)}<div class="wfd-main">${paletteHTML()}<div class="wfd-canvaswrap glass${E.conn?" connecting":""}"><div class="wfd-canvas" id="wfdCanvas" tabindex="-1">${canvasHTML(f)}</div><div class="wfd-mm glass" aria-label="Minimap">${mmHTML(f)}</div></div><aside class="wfd-insp card glass" id="wfdInsp">${inspHTML(f)}</aside></div><div class="wfd-leg row small muted">${ovlLegend()}<span>Lanes are the team, agent or system that owns the step. Drag a step to another lane to reassign its owner.</span></div><div id="wfdBottom">${bottomHTML(f)}</div></div>`}
function editorScreen(f){const r=rowOf(f),v=validate(f),errs=v.filter(x=>x.sev==="err").length;
 return `<div class="screen">${hero("Automation · Workflow designer",X(f.name),`<b>${r.steps} steps</b> across ${f.lanes.length} lanes: <b>${r.hum} human</b>, <b>${r.agt} agentic</b> and <b>${r.aut} deterministic</b> work steps. ${r.slaCov}% of work steps carry an SLA, OLA or XLA target and a typical run costs <b>${usd(r.cost)}</b>. ${errs?`<b>${errs} blocking problem${errs>1?"s":""}</b> must be fixed before publishing.`:"No blocking problems."}`,`<div class="row">${stdChip("bpmn","Swim lanes, gateways, events and sub-processes follow BPMN 2.0.")}<span class="muted small">Click a step to tell it what to do. Drag from a round port to connect.</span></div>`)}${lensNote()}${editorBody(f)}</div>`}
REG("flw_design","Workflow designer","automate","M4 5h6v5H4zM14 5h6v5h-6zM9 14h6v5H9zM7 10v2h10v-2M12 12v2",()=>{const f=curFlow();return f?editorScreen(f):listScreen()});
/* ---- repaint helpers ---- */
function paintAll(){const root=$q("[data-wfd-root]");if(!root){render();return}const cv=$q("#wfdCanvas"),sl=cv?cv.scrollLeft:0,st=cv?cv.scrollTop:0,ae=document.activeElement,keep=ae&&ae.hasAttribute&&ae.hasAttribute("data-wfd-find")?ae.selectionStart:null;const f=curFlow();root.outerHTML=editorBody(f);const nc=$q("#wfdCanvas");if(nc){nc.scrollLeft=sl;nc.scrollTop=st;nc.addEventListener("scroll",updateMM,{passive:true});updateMM()}if(keep!==null){const fi=$q("[data-wfd-find]");if(fi){fi.focus();fi.setSelectionRange(keep,keep)}}}
function paintCanvas(){const f=curFlow(),cv=$q("#wfdCanvas");if(!cv)return;const sl=cv.scrollLeft,st=cv.scrollTop;cv.innerHTML=canvasHTML(f);cv.scrollLeft=sl;cv.scrollTop=st;const mm=$q(".wfd-mm");if(mm)mm.innerHTML=mmHTML(f);updateMM()}
function paintInsp(){const f=curFlow(),el=$q("#wfdInsp");if(!el)return;const sy=el.scrollTop;el.innerHTML=inspHTML(f);el.scrollTop=sy}
function paintBottom(){const f=curFlow(),el=$q("#wfdBottom");if(el)el.innerHTML=bottomHTML(f)}
function paintHead(){const f=curFlow(),h=$q(".wfd-head");if(h){const t=document.createElement("div");t.innerHTML=headHTML(f);h.replaceWith(t.firstElementChild)}}
/* soft update after typing in the inspector: do not rebuild what the user is typing in */
function soft(){const f=curFlow(),n=selNode(f);if(n){const el=$q(`[data-wfd-node="${n.id}"]`);if(el){const a=$q(".wfd-nn",el),b=$q(".wfd-nm",el);if(a)a.textContent=n.n;if(b)b.textContent=metaOf(f,n)}}const st=$q("#wfdStatus");if(st)st.innerHTML=statusHTML(f)+" "+pill(validate(f).filter(x=>x.sev==="err").length?validate(f).filter(x=>x.sev==="err").length+" problems":"Validates clean",validate(f).filter(x=>x.sev==="err").length?"bad":"good");if(E.pane==="valid")paintBottom();const mm=$q(".wfd-mm");if(mm)mm.innerHTML=mmHTML(f);updateMM()}
/* ---- add, connect, remove ---- */
function addNode(type,x,y,l,r){const f=curFlow();pushU(f);const id="N"+uid();const lane=l!=null?l:Math.max(0,Math.min(f.lanes.length-1,Math.floor(y/LH)));const row=r!=null?r:((y%LH)>LH/2?1:0);const n=mkNode(id,type,NEWNAME[type],lane,Math.max(LW+10,Math.round(x/22)*22),row,type==="agent"?{agent:"Triage Agent",goal:""}:{},type==="human"||type==="approval"?{tg:{sla:"1 d",dur:4}}:{});f.nodes.push(n);touch(f);E.sel=id;E.selE=null;E.tab="do";E.insp="step";audit("added workflow step",NTY[type].l+" in "+f.name);toast(NTY[type].l+" added. Tell it what to do on the right, then connect its port.","info");paintAll();return n}
function freePos(f){for(let c=1;c<40;c++)for(let l=0;l<f.lanes.length;l++)for(let r=0;r<2;r++)if(!f.nodes.some(n=>n.l===l&&Math.abs(n.x-colX(c))<NW&&n.r===r))return{x:colX(c),l,r};return{x:colX(1),l:0,r:0}}
function addEdge(from,port,to){const f=curFlow();if(from===to){toast("A step cannot connect to itself.","bad");return}const tn=findV(viewG(f),to),fn=findV(viewG(f),from);if(!tn||!fn)return;if(!tn.virt&&tn.n.t==="trigger"){toast("Nothing can lead into a trigger.","bad");return}
 const real=id=>id.startsWith("grp:")?(f.nodes.find(n=>n.g===id.slice(4))||{}).id:id;const a=fn.virt?null:from,b=tn.virt?(f.nodes.find(n=>n.g===to.slice(4))||{}).id:to;if(!a||!b){toast("Expand the sub-flow to connect to its inside.","warn");return}
 const fnode=nodeById(f,a);if(f.edges.some(e=>e.f===a&&e.p===port&&e.t===b)){toast("Already connected.","info");return}pushU(f);const single=!(["next"].includes(port)&&["trigger","human","auto","agent","wait","subflow","parallel"].includes(fnode.t));const had=single&&f.edges.some(e=>e.f===a&&e.p===port);if(single)f.edges=f.edges.filter(e=>!(e.f===a&&e.p===port));f.edges.push({id:"e"+uid(),f:a,p:port,t:b});E.conn=null;touch(f);audit("connected steps",fnode.n+" → "+nodeById(f,b).n);toast(had?"Connection replaced.":"Connected.","good");paintAll()}
function delNode(id){mut(f=>{f.nodes=f.nodes.filter(n=>n.id!==id);f.edges=f.edges.filter(e=>e.f!==id&&e.t!==id);if(E.sel===id)E.sel=null},["deleted workflow step",id])}
function selectNode(id,show){E.sel=id;E.selE=null;E.conn=null;E.insp=E.sim&&E.sim.res.steps.some(s=>s.nid===id)?"run":"step";paintCanvas();paintInsp();if(show){const el=$q(`[data-wfd-node="${id}"]`);if(el)el.scrollIntoView({block:"center",inline:"center",behavior:rs()?"auto":"smooth"})}}
function tidy(){mut(f=>{autoLayout(f)},["tidied layout"])}
function fitZoom(){const cv=$q("#wfdCanvas"),f=curFlow();if(!cv||!f)return;const vg=viewG(f),W=Math.max(1000,...vg.nodes.map(v=>v.x+NW+140)),H=Math.max(LH*2,f.lanes.length*LH+30);E.zoom=Math.round(Math.max(.35,Math.min(1,Math.min((cv.clientWidth-6)/W,(cv.clientHeight-6)/H)))*100)/100;paintCanvas();paintHead();const w=$q("#wfdCanvas");if(w){w.scrollLeft=0;w.scrollTop=0}}
/* ---- pointer interactions ---- */
let drag=null,supClick=false;
const wpt=(cx,cy)=>{const cv=$q("#wfdCanvas");if(!cv)return{in:false,x:0,y:0};const rc=cv.getBoundingClientRect(),z=E.zoom||1;return{in:cx>=rc.left&&cx<=rc.right&&cy>=rc.top&&cy<=rc.bottom,x:(cx-rc.left+cv.scrollLeft)/z,y:(cy-rc.top+cv.scrollTop)/z}};
document.addEventListener("pointerdown",e=>{if(e.pointerType==="mouse"&&e.button)return;const f=curFlow();if(!f)return;
 const pal=e.target.closest("[data-wfd-pal]");if(pal){drag={k:"pal",type:pal.dataset.wfdPal,x0:e.clientX,y0:e.clientY,moved:false};return}
 const out=e.target.closest("[data-wfd-out]");if(out){const[id,p]=out.dataset.wfdOut.split("|");drag={k:"conn",from:id,port:p,x0:e.clientX,y0:e.clientY,moved:false};return}
 if(e.target.closest("[data-wfd-in]"))return;
 const nd=e.target.closest("[data-wfd-node]");if(nd){const id=nd.dataset.wfdNode;if(id.startsWith("grp:"))return;const n=nodeById(f,id);if(!n)return;drag={k:"node",id,x0:e.clientX,y0:e.clientY,ox:n.x,oy:nodeY(n),moved:false,snap:snapF(f),el:nd};return}
 const mm=e.target.closest("[data-wfd-mm]");if(mm){drag={k:"mm",moved:true};mmMove(e);e.preventDefault();return}
 const cv=e.target.closest("#wfdCanvas");if(cv&&!e.target.closest("[data-wfd-edge],[data-wfd-lane]")){drag={k:"pan",x0:e.clientX,y0:e.clientY,sl:cv.scrollLeft,st:cv.scrollTop,moved:false}}});
function mmMove(e){const svg=$q(".wfd-mmsvg"),cv=$q("#wfdCanvas");if(!svg||!cv)return;const r=svg.getBoundingClientRect(),vb=svg.viewBox.baseVal,sc=Math.min(r.width/vb.width,r.height/vb.height),wx=(e.clientX-r.left)/sc,wy=(e.clientY-r.top)/sc,z=E.zoom||1;cv.scrollLeft=wx*z-cv.clientWidth/2;cv.scrollTop=wy*z-cv.clientHeight/2;updateMM()}
document.addEventListener("pointermove",e=>{if(!drag)return;const dx=e.clientX-drag.x0,dy=e.clientY-drag.y0;if(drag.k==="mm"){mmMove(e);return}
 if(!drag.moved&&Math.hypot(dx,dy)<5)return;
 if(drag.k==="pal"){if(!drag.moved){drag.moved=true;const g=document.createElement("div");g.className="wfd-ghost";g.style.setProperty("--nc","var("+NTY[drag.type].c+")");g.innerHTML=IC(NTY[drag.type].d)+"<b>"+NTY[drag.type].l+"</b>";document.body.appendChild(g);drag.ghost=g;document.body.classList.add("wfd-dragging")}drag.ghost.style.transform=`translate(${e.clientX+12}px,${e.clientY+12}px)`;const p=wpt(e.clientX,e.clientY),w=$q(".wfd-canvaswrap");if(w)w.classList.toggle("drop",p.in);e.preventDefault()}
 else if(drag.k==="node"){drag.moved=true;const f=curFlow(),n=nodeById(f,drag.id),z=E.zoom||1;n._x=Math.max(LW+4,Math.round((drag.ox+dx/z)/22)*22);const ny=drag.oy+dy/z;n._l=Math.max(0,Math.min(f.lanes.length-1,Math.floor((ny+NH/2)/LH)));n._r=((ny+NH/2)%LH)>LH/2?1:0;drag.el.style.left=n._x+"px";drag.el.style.top=(laneTop(n._l)+12+n._r*(NH+10))+"px";const sv=$q("#wfdCanvas .wfd-edges");if(sv){const o={x:n.x,l:n.l,r:n.r};n.x=n._x;n.l=n._l;n.r=n._r;redrawEdges(f);n.x=o.x;n.l=o.l;n.r=o.r}e.preventDefault()}
 else if(drag.k==="conn"){drag.moved=true;const f=curFlow(),vg=viewG(f),a=findV(vg,drag.from),p=wpt(e.clientX,e.clientY),tmp=$q("#wfdCanvas .wfd-tmp");if(a&&tmp){const x1=a.x+NW,y1=a.y+NH*portFr(a,drag.port);tmp.setAttribute("d",`M${x1} ${y1}C${x1+60} ${y1} ${p.x-60} ${p.y} ${p.x} ${p.y}`);tmp.style.display=""}document.querySelectorAll(".wfd-node").forEach(el=>el.classList.toggle("can-in",el.dataset.wfdNode!==drag.from));e.preventDefault()}
 else if(drag.k==="pan"){drag.moved=true;const cv=$q("#wfdCanvas");if(cv){cv.scrollLeft=drag.sl-dx;cv.scrollTop=drag.st-dy}e.preventDefault()}},{passive:false});
function redrawEdges(f){const sv=$q("#wfdCanvas .wfd-edges");if(!sv)return;const vg=viewG(f);const defs=sv.querySelector("defs").outerHTML,tmp=sv.querySelector(".wfd-tmp").outerHTML;let e="";vg.edges.forEach(ed=>{const g=edgeGeom(vg,ed);if(!g)return;e+=`<g class="wfd-edge${E.selE===ed.id?" sel":""}" data-wfd-edge="${ed.id}"><path class="hit" d="${g.d}"/><path class="vis" d="${g.d}" marker-end="url(#wfdArr)"/>${ed.p!=="next"?`<text class="wfd-elab" x="${g.mx}" y="${g.my-6}" text-anchor="middle">${X(ed.p)}</text>`:""}</g>`});sv.innerHTML=defs+e+tmp}
function endDrag(e){if(!drag)return;const d=drag;drag=null;document.body.classList.remove("wfd-dragging");const w=$q(".wfd-canvaswrap");if(w)w.classList.remove("drop");if(d.k==="mm")return;
 const sup=()=>{supClick=true;setTimeout(()=>supClick=false,90)};
 if(d.k==="pal"&&d.moved){d.ghost.remove();sup();const p=wpt(e.clientX,e.clientY);if(p.in)addNode(d.type,p.x-NW/2,p.y-NH/2);else toast("Drop it on the canvas to add the step.","warn")}
 else if(d.k==="node"&&d.moved){sup();const f=curFlow(),n=nodeById(f,d.id);const lane=n._l!==n.l;pushU(f,d.snap);n.x=n._x;n.l=n._l;n.r=n._r;delete n._x;delete n._l;delete n._r;touch(f);audit("moved workflow step",n.n+(lane?" to lane "+f.lanes[n.l].n:""));if(lane&&n.p.asg.kind==="team"&&f.lanes[n.l].n&&TEAMN.includes(f.lanes[n.l].n)){n.p.asg.team=f.lanes[n.l].n;toast("Moved to lane “"+f.lanes[n.l].n+"”; the step is now assigned to that team.","info")}paintCanvas();paintInsp();soft()}
 else if(d.k==="conn"){const tmp=$q("#wfdCanvas .wfd-tmp");if(tmp)tmp.style.display="none";document.querySelectorAll(".wfd-node.can-in").forEach(el=>el.classList.remove("can-in"));if(d.moved){sup();const el=document.elementFromPoint(e.clientX,e.clientY),t=el&&el.closest&&el.closest("[data-wfd-node]");if(t&&t.dataset.wfdNode!==d.from)addEdge(d.from,d.port,t.dataset.wfdNode);else paintCanvas()}else{E.conn=E.conn&&E.conn.from===d.from&&E.conn.port===d.port?null:{from:d.from,port:d.port};sup();paintCanvas();if(E.conn)toast("Now click the step to connect to (Esc cancels).","info")}}
 else if(d.k==="pan"&&d.moved)sup()}
document.addEventListener("pointerup",endDrag);document.addEventListener("pointercancel",endDrag);
document.addEventListener("wheel",e=>{const cv=e.target.closest&&e.target.closest("#wfdCanvas");if(!cv||!e.ctrlKey)return;e.preventDefault();E.zoom=Math.max(.35,Math.min(1.5,Math.round(((E.zoom||1)+(e.deltaY<0?.1:-.1))*100)/100));paintCanvas();paintHead()},{passive:false});
/* ================================================================ STEP INSPECTOR */
const gp=(o,path)=>String(path).split(".").reduce((a,k)=>a==null?a:a[k],o);
function sp(o,path,v){const ks=String(path).split(".");let c=o;ks.slice(0,-1).forEach(k=>{if(c[k]==null)c[k]={};c=c[k]});c[ks[ks.length-1]]=v}
const rootOf=(f,n,path)=>path.startsWith("f.")?[f,path.slice(2)]:[n,path];
function fi(label,path,v,o){o=o||{};const id="wfdi_"+path.replace(/\W/g,"_");const at=`data-wfd-set="${path}" data-wfd-ty="${o.ty||"str"}" id="${id}"${o.re?" data-wfd-re":""}`;let inner;
 if(o.sel)inner=`<select class="fin" ${at}>${o.ph?`<option value="">${X(o.ph)}</option>`:""}${o.sel.map(x=>{const a=Array.isArray(x)?x:[x,x];return `<option value="${X(a[0])}" ${String(a[0])===String(v)?"selected":""}>${X(a[1])}</option>`}).join("")}</select>`;
 else if(o.area)inner=`<textarea class="fin" rows="${o.rows||3}" ${at} placeholder="${X(o.ph||"")}">${X(v)}</textarea>`;
 else if(o.chk)inner=`<button type="button" class="ftog" role="switch" aria-checked="${!!v}" data-wfd-tog="${path}" aria-label="${X(label)}"><i></i><span>${v?"On":"Off"}</span></button>`;
 else inner=`<input class="fin" type="${o.ty==="num"?"number":"text"}" ${at} value="${X(v==null?"":v)}" placeholder="${X(o.ph||"")}" ${o.min!=null?`min="${o.min}"`:""} ${o.max!=null?`max="${o.max}"`:""} ${o.step?`step="${o.step}"`:""}>`;
 return `<div class="fld ${o.wide?"wide":""}"><label class="flab" for="${id}">${X(label)}</label>${inner}${o.help?`<small class="fhelp">${X(o.help)}</small>`:""}</div>`}
const chipsF=(label,path,v,opts,help)=>`<div class="fld"><span class="flab">${X(label)}</span><div class="fchips" role="radiogroup" aria-label="${X(label)}">${opts.map(o=>{const a=Array.isArray(o)?o:[o,o];return `<button type="button" class="chip" data-wfd-chip="${path}|${X(a[0])}" aria-pressed="${String(a[0])===String(v)}">${X(a[1])}</button>`}).join("")}</div>${help?`<small class="fhelp">${X(help)}</small>`:""}</div>`;
const multiF=(label,path,arr,opts,help)=>`<div class="fld"><span class="flab">${X(label)}</span><div class="fchips" role="group" aria-label="${X(label)}">${opts.map(o=>{const a=Array.isArray(o)?o:[o,o];return `<button type="button" class="chip" data-wfd-multi="${path}|${X(a[0])}" aria-pressed="${(arr||[]).includes(a[0])}">${X(a[1])}</button>`}).join("")}</div>${help?`<small class="fhelp">${X(help)}</small>`:""}</div>`;
function pillOpts(pm,sel,pred){const g={};Object.values(pm).forEach(p=>{if(pred&&!pred(p))return;(g[p.grp]=g[p.grp]||[]).push(p)});return Object.entries(g).map(([k,v])=>`<optgroup label="${X(k)}">${v.map(p=>`<option value="${X(p.id)}" ${p.id===sel?"selected":""}>${X(p.label)} (${TLAB[p.type]||p.type})</option>`).join("")}</optgroup>`).join("")}
const pillSelect=(pm,path,sel,ph,pred)=>`<select class="fin" data-wfd-set="${path}" data-wfd-re aria-label="Data pill"><option value="">${X(ph||"Choose a data pill")}</option>${pillOpts(pm,sel,pred)}</select>`;
const insertPill=(pm,path)=>`<select class="fin wfd-ins" data-wfd-ins="${path}" aria-label="Insert a data pill"><option value="">Insert data pill…</option>${pillOpts(pm)}</select>`;
const peopleOpts=(sel,kinds)=>DIR.filter(d=>!kinds||kinds.includes(d.kind)).slice(0,400).map(d=>`<option value="${X(d.name)}" ${d.name===sel?"selected":""}>${X(d.name)} · ${KINDS[d.kind]}</option>`).join("");
const TABTITLES=[["do","Do"],["in","Inputs"],["out","Outputs"],["cond","Conditions"],["par","Parameters"],["asg","Assignment"],["tgt","Targets"],["vis","Visibility"],["grd","Guardrails"]];
function inspHTML(f){const e=E.selE&&f.edges.find(x=>x.id===E.selE);const sim=E.sim;
 const tabs=sim?`<div class="wfd-itabs" role="tablist"><button class="chip" role="tab" data-wfd-insp="step" aria-pressed="${E.insp!=="run"}">Step settings</button><button class="chip" role="tab" data-wfd-insp="run" aria-pressed="${E.insp==="run"}">${ico("bolt")}Run data</button></div>`:"";
 if(sim&&E.insp==="run")return tabs+runPanelHTML(f);
 if(e){const a=nodeById(f,e.f),b=nodeById(f,e.t)||{n:"a collapsed sub-flow"};return tabs+`<div class="eyebrow">Connection</div><h3 style="margin:2px 0 8px">${X(a?a.n:"?")} → ${X(b.n)}</h3><p class="muted small">Leaves the ${e.p==="next"?"main":"“"+X(e.p)+"”"} port. A step that fans out on its main port runs every connected path in parallel.</p><div class="row"><button class="btn danger" data-wfd-deledge="${e.id}">Remove connection</button><button class="btn quiet" data-wfd-desel>Done</button></div>`}
 const n=selNode(f);if(E.sel&&E.sel.startsWith("grp:")){const g=f.groups.find(x=>"grp:"+x.id===E.sel);if(g)return tabs+`<div class="eyebrow">Collapsed sub-flow</div><h3 style="margin:2px 0 8px">${X(g.n)}</h3><p class="muted small">${f.nodes.filter(x=>x.g===g.id).length} steps are folded into this box. Expand it to edit them.</p><div class="row"><button class="btn primary" data-wfd-expand="${g.id}">Expand</button><button class="btn" data-wfd-ungroup="${g.id}">Dissolve group</button></div>`}
 if(!n)return tabs+flowInsp(f);
 const T=NTY[n.t],m=modeOf(n);
 return tabs+`<div class="row sp"><div class="row" style="gap:10px"><span class="wfd-ni lg" style="--nc:var(${T.c})">${IC(T.d)}</span><div><div class="eyebrow" style="margin:0">${T.l}</div><b>${m==="control"?"Control step":MODES[m][0]+" step"}</b></div></div><button class="btn quiet" data-wfd-desel aria-label="Close inspector">Done</button></div>
 <div class="wfd-itabs" role="tablist" aria-label="Step settings">${TABTITLES.map(t=>`<button class="wfd-itab" role="tab" data-wfd-tab="${t[0]}" aria-selected="${E.tab===t[0]}">${t[1]}</button>`).join("")}</div>
 <div class="wfd-ibody">${({do:doHTML,in:inHTML,out:outHTML,cond:condTab,par:parHTML,asg:asgHTML,tgt:tgtHTML,vis:visHTML,grd:grdHTML})[E.tab](f,n)}</div>
 <div class="row wfd-ifoot"><button class="btn" data-wfd-startconn="${n.id}">${ico("bolt")}Connect from here</button><button class="btn" data-wfd-dup="${n.id}">Duplicate</button><button class="btn danger" data-wfd-del="${n.id}">Delete</button></div>`}
function flowInsp(f){const r=rowOf(f);return `<div class="eyebrow">Workflow settings</div><h3 style="margin:2px 0 8px">Select a step</h3>
 <div class="wfd-how"><b>How to tell a step to do something</b><ol class="small"><li><b>Do</b>: choose who acts (a person, an AI agent, or an automatic action) and the exact action.</li><li><b>Inputs</b> and <b>Outputs</b>: pick data pills from the trigger record and earlier steps. Types are checked.</li><li><b>Conditions</b>: run or skip the step with AND and OR rules.</li><li><b>Parameters</b>: timeout, retries, backoff, error path and rollback.</li><li><b>Assignment</b>, <b>Targets</b>, <b>Visibility</b> and <b>Guardrails</b> complete the step.</li></ol></div>
 ${fi("Trigger record (source of data pills)","f.table",f.table,{sel:Object.entries(DATAMODEL.tables).map(([k,v])=>[k,v.label]),re:1,help:DATAMODEL.tables[f.table]?DATAMODEL.tables[f.table].fields.length+" fields from "+DATAMODEL.tables[f.table].source:""})}
 <div class="eyebrow" style="margin:12px 0 6px">Flow variables</div>${(f.vars||[]).map((v,i)=>`<div class="wfd-var"><input class="fin" data-wfd-set="f.vars.${i}.name" value="${X(v.name)}" aria-label="Variable name"><select class="fin" data-wfd-set="f.vars.${i}.type" data-wfd-re aria-label="Type">${Object.keys(TLAB).map(t=>`<option value="${t}" ${t===v.type?"selected":""}>${TLAB[t]}</option>`).join("")}</select><input class="fin" data-wfd-set="f.vars.${i}.init" value="${X(v.init)}" placeholder="start value" aria-label="Start value"><button class="flw-x" data-wfd-vardel="${i}" aria-label="Remove variable">${IC("M6 6l12 12M18 6L6 18")}</button></div>`).join("")}<button class="chip" data-wfd-varadd>+ Variable</button>
 <div class="eyebrow" style="margin:12px 0 6px">Step types</div><div class="wfd-legend">${PAL.map(t=>`<span title="${X(NTY[t].note)}"><i style="background:var(${NTY[t].c})"></i>${NTY[t].l}</span>`).join("")}</div>
 <div class="muted small" style="margin-top:10px">${r.steps} steps · ${f.edges.length} connections · ${f.groups.length} sub-flow groups. ${E.conn?"<b>Connecting:</b> click the target step. Esc cancels.":""}</div>`}
/* ---------- Do ---------- */
function doHTML(f,n){const a=n.a,pm=pillMap(f,n),m=modeOf(n),isW=WORKT.includes(n.t);let h=fi("Step name","n",n.n,{});
 h+=`<div class="fld"><span class="flab">Step type</span><select class="fin" data-wfd-type aria-label="Step type">${PAL.map(t=>`<option value="${t}" ${t===n.t?"selected":""}>${NTY[t].l}</option>`).join("")}</select></div>`;
 if(isW)h+=`<div class="fld"><span class="flab">Who does this step</span><div class="wfd-seg3" role="radiogroup">${["human","agentic","deterministic"].map(k=>`<button type="button" role="radio" aria-checked="${m===k||(k==="human"&&dClass(n)==="human")||(k===dClass(n))}" class="k-${k}" data-wfd-mode="${k}"><i style="background:var(${MODES[k][1]})"></i>${MODES[k][0]}<small>${({human:"A person decides or does the work",agentic:"An AI agent works toward a goal within guardrails",deterministic:"A rule, API call or script does exactly the same thing every time"})[k]}</small></button>`).join("")}</div></div>`;
 switch(n.t){
 case"trigger":h+=chipsF("Starts when","a.src",a.src,TRIG)+fi("Event or description","a.ev",a.ev,{sel:({record:["Record created","Record updated","Record deleted","State changes"],catalog:["Catalog request: "+(f.name),"Catalog request submitted"],event:["Invoice received (ERP)","Hire accepted (HR system)","Demand submitted","Webhook received","Application event"],schedule:["Schedule"],email:["Email to a monitored mailbox"],api:["API call to /workflows/"+f.id]})[a.src]||[a.ev],re:0})+(a.src==="schedule"?fi("Schedule (cron)","a.sched",a.sched,{ph:"0 8 * * 1-5",help:"Weekdays at 08:00"}):"")+fi("Trigger record","f.table",f.table,{sel:Object.entries(DATAMODEL.tables).map(([k,v])=>[k,v.label]),re:1})+fi("Only start when","a.filter",a.filter,{ph:"vendor is not internal",help:"Optional. Use Conditions for a full rule."});break;
 case"human":h+=fi("Instructions for the person","a.instr",a.instr,{area:1,ph:"What good looks like, in a sentence or two."})+fi("Form shown to the person","a.form",a.form,{ph:"Milestone acceptance"})+`<div class="fld"><span class="flab">Outcomes the person can choose</span><input class="fin" data-wfd-set="a.outcomes" data-wfd-ty="list" value="${X((a.outcomes||[]).join(", "))}" placeholder="Accepted, Not accepted"><small class="fhelp">Separate with commas. The chosen outcome is available as a data pill.</small></div>`;break;
 case"approval":{const ap=approverFor(n,recOf(f),Object.assign({},ctxOfRec(f)));h+=`<div class="wfd-note glass"><b>Who has to approve</b><div>${ap.who}</div><div class="muted small">${X(ap.why)}</div></div>`+multiF("Approver roles","a.approvers",a.approvers,ALLROLES,"Anyone holding the role can decide. Roles come from the permission model; budget tiers come from delegation of authority.")+chipsF("Approver rights","a.tiers",a.tiers,[["fixed","Fixed roles"],["doa","Delegation of authority by amount"]])+(a.tiers==="doa"?`<div class="fld"><span class="flab">Amount used to find the tier</span>${pillSelect(pm,"a.amountField",a.amountField,"Choose an amount",p=>p.type==="num")}</div><div class="wfd-doa">${doaTiers().map(t=>`<span class="${ap.why.includes("tier "+t.id+" ")?"on":""}"><b>${t.id}</b> up to ${t.max===Infinity?"no limit":money(t.max)}<small>${X(t.role)}</small></span>`).join("")}</div>`:"")+chipsF("Decision mode","a.mode",a.mode,[["any","Any one"],["all","All must approve"],["seq","In sequence"],["quorum","Quorum"]])+(a.mode==="quorum"?fi("Quorum (people needed)","a.quorum",a.quorum,{ty:"num",min:1}):"")+fi("When the SLA passes","a.onTimeout",a.onTimeout,{sel:["Escalate to manager","Remind every 4 hours","Route to delegate","Auto-reject","Auto-approve safe items"]})+fi("Approver may return it for more information","a.allowReturn",a.allowReturn!==false,{chk:1})+asmAttach(f,n);break}
 case"assessment":h+=asmNode(f,n);break;
 case"agent":h+=agentDo(f,n,pm);break;
 case"auto":h+=autoDo(f,n,pm);break;
 case"decision":h+=decisionDo(f,n,pm);break;
 case"wait":h+=chipsF("Waits for","a.kind",a.kind,[["timer","A set time"],["until","A date or field"],["event","An event"]])+(a.kind==="timer"?fi("How long","a.dur",a.dur,{sel:[["PT1H","1 hour"],["PT4H","4 hours"],["PT24H","24 hours"],["P2D","2 days"],["P5D","5 days"],["P30D","30 days"]],re:1}):a.kind==="until"?fi("Until this field or date","a.until",a.until,{ph:"start_date"}):fi("Event name","a.ev",a.ev,{ph:"Milestone accepted"})+fi("Give up after","a.dur",a.dur,{sel:[["PT24H","24 hours"],["P5D","5 days"],["P30D","30 days"]]}));break;
 case"parallel":h+=chipsF("Gateway","a.kind",a.kind,[["fork","Fork: run every path"],["join","Join: wait for every path"]],"A fork starts all connected paths together. A join waits for all of them, then continues.");break;
 case"loop":h+=`<div class="fld"><span class="flab">List to loop over</span>${pillSelect(pm,"a.over",a.over,"Choose a list",p=>p.type==="list")}</div>`+fi("Most iterations","a.max",a.max,{ty:"num",min:1,max:1000})+fi("Stop early when","a.until",a.until,{ph:"count is 0",help:"The Each port runs the body once per item; Done runs after the last one."});break;
 case"subflow":h+=`<div class="fld"><span class="flab">Workflow to run</span><select class="fin" data-wfd-set="a.ref" data-wfd-re><option value="">Choose a workflow</option>${allFlows().filter(x=>x.id!==f.id).slice(0,300).map(x=>`<option value="${X(x.id)}" ${x.id===a.ref?"selected":""}>${X(x.name)}</option>`).join("")}</select></div>`+(getFlow(a.ref)?`<div class="row"><button class="btn" data-wfd-go="${X(a.ref)}">Open that workflow</button><span class="muted small">${getFlow(a.ref).nodes.length} steps</span></div>`:"");break;
 case"end":h+=fi("Outcome recorded","a.outcome",a.outcome,{sel:["Completed","Rejected","Cancelled","Held pending acceptance","Escalated","Failed"],help:"Reports count runs by outcome."})}
 return h}
const ctxOfRec=f=>{const c={},r=recOf(f);Object.keys(r).forEach(k=>c["rec."+k]=r[k]);return c};
function asmAttach(f,n){const a=n.a;return `<div class="wfd-asm"><div class="row sp"><b>Assessments for this approval</b><button class="chip" data-wfd-asmadd>+ Attach</button></div>${legend([["Required gate: blocks the approval until complete and passing","--bad-f"],["Advisory: approver sees the score and may override with a reason","--warn-f"]])}${(a.asm||[]).map((x,i)=>`<div class="wfd-asmrow"><select class="fin" data-wfd-set="a.asm.${i}.type" data-wfd-re aria-label="Assessment type">${ASSESS_TYPES().map(t=>`<option value="${t.id}" ${t.id===x.type?"selected":""}>${X(t.n)}</option>`).join("")}</select><span class="fchips"><button type="button" class="chip gate" data-wfd-chip="a.asm.${i}.mode|gate" aria-pressed="${x.mode==="gate"}">Required gate</button><button type="button" class="chip adv" data-wfd-chip="a.asm.${i}.mode|advisory" aria-pressed="${x.mode==="advisory"}">Advisory</button></span><button class="flw-x" data-wfd-asmdel="${i}" aria-label="Remove assessment">${IC("M6 6l12 12M18 6L6 18")}</button></div>`).join("")||'<p class="muted small">None attached. Attach one when the approver needs a scored view of risk.</p>'}</div>`}
function asmNode(f,n){const a=n.a,t=ASSESS_TYPES().find(x=>x.id===a.type);return fi("Assessment type","a.type",a.type,{sel:ASSESS_TYPES().map(x=>[x.id,x.n]),re:1,help:t?t.q.length+" questions, pass mark "+t.pass:""})+chipsF("How it is used","a.gate",a.gate,[["gate","Required gate"],["advisory","Advisory input"]],a.gate==="gate"?"Required gate: the path continues on Pass only. A failing score sends the run down Fail.":"Advisory input: the score travels with the run and the next approver may override it with a reason.")+fi("Pass mark (0 to 100)","a.pass",a.pass,{ty:"num",min:0,max:100})+`<div class="fld"><span class="flab">Answered by (subject matter experts)</span><div class="fchips">${(a.sme||[]).map((s,i)=>`<span class="chip pchip on">${avatar(s,{size:22})}${X(s)}<button class="wfd-xs" data-wfd-smedel="${i}" aria-label="Remove ${X(s)}">×</button></span>`).join("")||'<span class="muted small">Anyone on the owning team</span>'}</div><select class="fin" data-wfd-sme aria-label="Add an expert"><option value="">Add a person, agent, contractor or provider…</option>${peopleOpts("")}</select></div><div class="row"><button class="btn" data-wfd-asmopen="${X(a.type)}">Open assessment</button></div>`}
function agentDo(f,n,pm){const a=n.a,names=[...new Set(DIR.filter(d=>d.kind==="ai").map(d=>d.name).concat(AGN))];const hr=a.risk==="high"||a.writes;
 return fi("Agent","a.agent",a.agent,{sel:names})+fi("Goal","a.goal",a.goal,{area:1,rows:3,ph:"Check each invoice against accepted work and recommend approve, hold or reject, citing sources.",help:"One sentence a reviewer can judge the result against."})+multiF("Tools it may use","a.tools",a.tools,TOOLS.map(t=>[t[0],t[0]+" ("+t[1]+")"]),"Only these tools are granted by the AI gateway for this step.")+chipsF("Human in the loop","a.autonomy",a.autonomy,AUTON,a.autonomy==="autonomous"?"Acts, then logs. Not allowed for high-risk steps.":a.autonomy==="propose"?"Prepares an action and waits for a person to approve it.":"Shows a suggestion; the workflow continues without waiting.")+chipsF("Risk of this step","a.risk",a.risk,[["low","Low"],["medium","Medium"],["high","High: money, access or outbound messages"]])+fi("Can change records or call write tools","a.writes",!!a.writes,{chk:1})+`<div class="fld"><span class="flab">Confidence threshold: ${a.conf}%</span><input type="range" class="rng" min="40" max="95" step="5" value="${a.conf}" data-wfd-set="a.conf" data-wfd-ty="num" aria-label="Confidence threshold"><small class="fhelp">Under this confidence the step goes to the human fallback.</small></div>`+fi("Human fallback (team that takes over)","a.fallback",a.fallback,{sel:TEAMN,ph:"Choose a team"})+fi("Most steps the agent may take","a.maxSteps",a.maxSteps,{ty:"num",min:1,max:30})+fi("Spend cap per run ($)","a.cap",a.cap,{ty:"num",min:.05,step:.05})+`<div class="wfd-note glass ${hr&&a.autonomy==="autonomous"?"bad":""}"><b>Guardrails at a glance</b><div class="small">Writes ${a.writes?"allowed":"blocked"} · ${a.maxSteps} steps · $${(+a.cap).toFixed(2)} a run · escalates under ${a.conf}% to ${X(a.fallback||"nobody (set a fallback)")}</div></div><div class="row">${aiChip({model:"Claude Sonnet",conf:.84,title:"Suggested guardrails",note:"Based on the tools chosen and what the goal says the step changes.",src:["Tool scopes","Goal text","Similar agent steps"],guards:["Suggestion only"]})}<button class="chip" data-go="flw_agent">Open Agentic workflows</button></div>`}
function autoDo(f,n,pm){const a=n.a,op=a.op;let h=fi("Action","a.op",op,{sel:OPS_A,re:1});
 if(/REST|Place|Release|Post|Schedule|Entra|M365|Planner/i.test(op))h+=fi("Method","a.method",a.method,{sel:["GET","POST","PUT","PATCH","DELETE"]})+fi("Endpoint or connector call","a.endpoint",a.endpoint,{ph:"/erp/odata/payments",help:"Credentials live in the Integration hub, never in the step."});
 if(/script/i.test(op))h+=fi("Script","a.script",a.script,{area:1,rows:5,ph:"return { total: input.a + input.b }"});
 if(/Update|Create/i.test(op))h+=fi("Table","a.target",a.target,{sel:Object.entries(DATAMODEL.tables).map(([k,v])=>[k,v.label]).concat([["task","Task"]]),ph:"Choose a table"})+fi("Fields to set","a.fields",a.fields,{area:1,rows:4,ph:"status = approved\npay_on = {{rec.due}}"})+insertPill(pm,"a.fields");
 if(/notification/i.test(op))h+=fi("Channel","a.chan",a.chan,{sel:["Teams","Email","Slack","Webex"]})+fi("Send to","a.to",a.to,{ph:"Requester, project manager, #finance-ap"})+fi("Message","a.msg",a.msg,{area:1,rows:3,ph:"Invoice {{rec.id}} is on hold."})+insertPill(pm,"a.msg");
 return h}
function decisionDo(f,n,pm){const a=n.a;let h=chipsF("Decide with","a.mode",a.mode,[["rules","Conditions"],["dmn","Decision table"]],a.mode==="dmn"?"Each distinct value in the chosen output column becomes a path. Overlap and gap checks live in the table editor.":"The first branch whose condition is true wins. Anything else takes Else.");
 if(a.mode==="dmn"){const t=F.dmn.find(x=>x.id===a.dmn);h+=fi("Decision table","a.dmn",a.dmn,{sel:F.dmn.map(x=>[x.id,x.name]),ph:"Choose a table",re:1});if(t){h+=fi("Output column that picks the path","a.col",a.col,{sel:t.outputs.map(o=>[o.k,o.l]),re:1})+`<div class="wfd-note glass"><b>Paths from this table</b><div class="row" style="gap:6px;margin-top:6px">${dmnPorts(t.id,a.col).map(p=>pill(X(p),"info")).join("")}${pill("No match","mute")}</div><div class="muted small" style="margin-top:6px">${t.rows.length} rows · ${HPX[t.hp]?HPX[t.hp][0]:t.hp} hit policy · map its input columns in Inputs.</div></div><div class="row"><button class="btn" data-wfd-opendmn="${t.id}">Open the table</button><button class="btn" data-wfd-mapdmn>Map table inputs</button></div>`}return h}
 (a.branches||[]).forEach((b,i)=>{h+=`<div class="wfd-br"><div class="row sp"><input class="fin" data-wfd-set="a.branches.${i}.label" data-wfd-re value="${X(b.label)}" aria-label="Branch name"><button class="flw-x" data-wfd-brdel="${i}" aria-label="Remove branch">${IC("M6 6l12 12M18 6L6 18")}</button></div>${condHTML(f,n,"a.branches."+i+".c",b.c,pm)}</div>`});
 return h+`<button class="chip" data-wfd-bradd>+ Branch</button><p class="muted small">Else path: anything no branch matches.</p>`}
/* ---------- conditions builder ---------- */
function ruleHTML(f,n,r,pth,pm,del){const p=pm[r.f],t=p?p.type:"text",ops=OPSBY[t]||OPSBY.text;const vc=UNARY.includes(r.o)?"":r.vt==="pill"?pillSelect(pm,pth+".v",r.v,"Compare with a pill"):p&&p.opts&&p.opts.length&&["=","!=","in"].includes(r.o)?`<select class="fin" data-wfd-set="${pth}.v" aria-label="Value">${p.opts.map(o=>`<option ${o===r.v?"selected":""}>${X(o)}</option>`).join("")}</select>`:`<input class="fin" data-wfd-set="${pth}.v" value="${X(r.v)}" placeholder="${t==="num"?"50000":t==="date"?"2026-10-19":"value"}" aria-label="Value" ${t==="num"?'inputmode="decimal"':""}>`;
 const bad=!UNARY.includes(r.o)&&r.vt!=="pill"&&t==="num"&&r.v!==""&&isNaN(parseFloat(r.v));
 return `<div class="wfd-rule${bad?" bad":""}"><select class="fin" data-wfd-set="${pth}.f" data-wfd-re aria-label="Field"><option value="">${r.f===""&&r.vt==="text"?"(free text) "+X(r.v):"Choose a field"}</option>${pillOpts(pm,r.f)}</select><select class="fin" data-wfd-set="${pth}.o" data-wfd-re aria-label="Operator">${ops.map(o=>`<option ${o===r.o?"selected":""}>${o}</option>`).join("")}</select>${vc}${UNARY.includes(r.o)?"":`<button class="chip" data-wfd-vt="${pth}" title="Switch between a typed value and another data pill" aria-pressed="${r.vt==="pill"}">${r.vt==="pill"?"pill":"value"}</button>`}<button class="flw-x" data-wfd-cdel="${del}" aria-label="Remove rule">${IC("M6 6l12 12M18 6L6 18")}</button>${bad?`<small class="ferr">Expects a number</small>`:""}</div>`}
function condHTML(f,n,path,c,pm){c=c||{j:"AND",rules:[],groups:[]};if(!c.groups)c.groups=[];const empty=!c.rules.length&&!c.groups.length;
 return `<div class="wfd-cond"><div class="row"><span class="muted small">Match</span><span class="fchips"><button class="chip" data-wfd-chip="${path}.j|AND" aria-pressed="${c.j==="AND"}">All (AND)</button><button class="chip" data-wfd-chip="${path}.j|OR" aria-pressed="${c.j==="OR"}">Any (OR)</button></span></div>${c.rules.map((r,i)=>ruleHTML(f,n,r,path+".rules."+i,pm,path+".rules|"+i)).join("")}${c.groups.map((g,gi)=>`<div class="wfd-grp"><div class="row sp"><span class="fchips"><span class="muted small">Group:</span><button class="chip" data-wfd-chip="${path}.groups.${gi}.j|AND" aria-pressed="${g.j==="AND"}">All</button><button class="chip" data-wfd-chip="${path}.groups.${gi}.j|OR" aria-pressed="${g.j==="OR"}">Any</button></span><button class="flw-x" data-wfd-cdel="${path}.groups|${gi}" aria-label="Remove group">${IC("M6 6l12 12M18 6L6 18")}</button></div>${g.rules.map((r,i)=>ruleHTML(f,n,r,path+".groups."+gi+".rules."+i,pm,path+".groups."+gi+".rules|"+i)).join("")}<button class="chip" data-wfd-cadd="${path}.groups.${gi}|rule">+ Rule in group</button></div>`).join("")}${empty?'<p class="muted small" style="margin:6px 0">No rules yet.</p>':""}<div class="row"><button class="chip" data-wfd-cadd="${path}|rule">+ Rule</button><button class="chip" data-wfd-cadd="${path}|group">+ Group</button></div></div>`}
/* ---------- Inputs / Outputs ---------- */
function inHTML(f,n){const pm=pillMap(f,n),ctx=ctxOfRec(f),ins=n.p.inputs;const stub=(window.DATAMODEL&&n.a.mode==="dmn")?`<button class="chip" data-wfd-mapdmn>Map decision table inputs</button>`:"";
 return `<p class="muted small">Inputs are the data this step needs. Pick a <b>data pill</b> from the trigger record or an earlier step, type a <b>literal</b>, or write a <b>formula</b>. Types are checked as you go.</p>${ins.map((i,k)=>{const is=inputIssue(f,n,i,pm,ctx),val=resolveIn(i,ctx);return `<div class="wfd-inrow ${is?is.sev:""}"><div class="wfd-inhd"><input class="fin" data-wfd-set="p.inputs.${k}.name" value="${X(i.name)}" aria-label="Input name"><select class="fin" data-wfd-set="p.inputs.${k}.type" data-wfd-re aria-label="Type">${Object.keys(TLAB).map(t=>`<option value="${t}" ${t===i.type?"selected":""}>${TLAB[t]}</option>`).join("")}</select><button class="flw-x" data-wfd-ldel="p.inputs|${k}" aria-label="Remove input">${IC("M6 6l12 12M18 6L6 18")}</button></div>
 <div class="wfd-insrc"><span class="fchips"><button class="chip" data-wfd-chip="p.inputs.${k}.src|pill" aria-pressed="${i.src==="pill"}">Data pill</button><button class="chip" data-wfd-chip="p.inputs.${k}.src|lit" aria-pressed="${i.src==="lit"}">Literal</button><button class="chip" data-wfd-chip="p.inputs.${k}.src|formula" aria-pressed="${i.src==="formula"}">Formula</button></span></div>
 ${i.src==="pill"?pillSelect(pm,"p.inputs."+k+".val",i.val):`<input class="fin" data-wfd-set="p.inputs.${k}.val" value="${X(i.val)}" placeholder="${i.src==="formula"?"if({{rec.amount}}>50000,'High','Low')":"Type a value"}" aria-label="Value">${i.src==="formula"?insertPill(pm,"p.inputs."+k+".val"):""}`}
 <div class="wfd-instat small ${is?is.sev:"ok"}">${is?X(is.msg):"OK · "+X(fmtV(val==null||val===""?"(empty)":val))+" as "+(TLAB[i.type]||i.type)}</div><label class="small wfd-req"><input type="checkbox" data-wfd-chk="p.inputs.${k}.req" ${i.req?"checked":""}> Required</label></div>`}).join("")||'<p class="muted small">This step takes no inputs yet.</p>'}<div class="row"><button class="chip" data-wfd-inadd>+ Input</button>${stub}</div>`}
function outHTML(f,n){const used=name=>f.nodes.filter(x=>x!==n&&(x.p.inputs||[]).some(i=>i.val===n.id+"."+name||(i.src==="formula"&&String(i.val).includes("{{"+n.id+"."+name+"}}")))).map(x=>x.n);
 return `<p class="muted small">Outputs are named results later steps can use as data pills. They appear in downstream pickers as <code>${X(n.id)}.name</code>.</p>${(n.p.outputs||[]).map((o,k)=>`<div class="wfd-outrow"><input class="fin" data-wfd-set="p.outputs.${k}.name" value="${X(o.name)}" aria-label="Output name"><select class="fin" data-wfd-set="p.outputs.${k}.type" aria-label="Type">${Object.keys(TLAB).map(t=>`<option value="${t}" ${t===o.type?"selected":""}>${TLAB[t]}</option>`).join("")}</select><input class="fin" data-wfd-set="p.outputs.${k}.desc" value="${X(o.desc)}" placeholder="What it holds" aria-label="Description"><button class="flw-x" data-wfd-ldel="p.outputs|${k}" aria-label="Remove output">${IC("M6 6l12 12M18 6L6 18")}</button><div class="small muted">${used(o.name).length?"Used by "+used(o.name).map(X).join(", "):"Not used by any step yet"}</div></div>`).join("")||'<p class="muted small">No named outputs.</p>'}<button class="chip" data-wfd-outadd>+ Output</button><div class="eyebrow" style="margin:14px 0 6px">Always available</div><div class="row" style="gap:6px">${(AUTOOUT[n.t]||[]).map(o=>`<span class="pill mute" title="${X(o[2])}">${n.id}.${o[0]} · ${TLAB[o[1]]||o[1]}</span>`).join("")||'<span class="muted small">None for this step type</span>'}</div>`}
function condTab(f,n){const pm=pillMap(f,n),ctx=ctxOfRec(f);const ev=(c)=>{const hasR=c&&((c.rules||[]).length||(c.groups||[]).length);if(!hasR)return"";const r=evalCond(c,ctx,pm);return `<div class="wfd-cres ${r.ok?"good":"warn"}">With the test record this is <b>${r.ok?"true":"false"}</b>: ${X(r.why.join("; "))}</div>`};
 return `<p class="muted small">Control whether the step runs. Rules use the same data pills as inputs.</p><div class="eyebrow">Run only when</div>${condHTML(f,n,"p.entry",n.p.entry,pm)}${ev(n.p.entry)}<div class="eyebrow" style="margin-top:14px">Skip when</div>${condHTML(f,n,"p.skip",n.p.skip,pm)}${ev(n.p.skip)}`}
function parHTML(f,n){const p=n.p.params,h=["human","approval","assessment"].includes(n.t);
 return `<p class="muted small">How the step behaves when it is slow or fails.</p>${fi("Timeout","p.params.timeout",p.timeout,{ph:h?"P5D":"PT30S",help:"ISO 8601, for example PT30S, PT2H, P5D. Empty means the SLA decides."})}${fi("Retries","p.params.retries",p.retries,{ty:"num",min:0,max:10})}${chipsF("Backoff between retries","p.params.backoff",p.backoff,[["none","None"],["fixed","Fixed"],["exponential","Exponential"]],p.backoff==="exponential"?"Waits 30 s, then 2 min, then 8 min, with jitter.":"")}${fi("When it fails","p.params.onError",p.onError,{sel:[["stop","Stop the run and alert the owner"],["retry","Retry, then alert the owner"],["path","Follow the Error path"],["continue","Continue to the next step"],["compensate","Run the compensation step"]],re:1})}${p.onError==="path"?`<div class="wfd-note glass"><b>Error path</b><div class="small">An “Error” port appears on the step. Connect it to a notification or a fix-up step.</div></div>`:""}${fi("Compensation (what undoes it)","p.params.comp",p.comp,{ph:"Release payment hold",help:"Required for steps that move money or grant access."})}${fi("Safe to repeat (idempotent)","p.params.idem",!!p.idem,{chk:1})}${h?fi("Remind at percent of SLA","p.params.remind",p.remind,{ty:"num",min:10,max:100,ph:"75"})+fi("Escalate to","p.params.esc",p.esc,{sel:TEAMN,ph:"Manager of the assignee"}):""}`}
function asgHTML(f,n){const a=n.p.asg,kinds=[["team","Team"],["person","Person"],["agent","AI agent"],["contractor","Contractor"],["msp","Managed service provider"]],kmap={person:["human"],agent:["ai"],contractor:["contractor"],msp:["msp"]};
 let cand="";if(window.routeBy&&["human","approval","assessment","agent"].includes(n.t)){try{const rr=routeBy({skills:a.skills,team:a.team||undefined,service:f.service,priority:"P3",limit:3,kinds:a.kind==="agent"?["ai"]:["human","contractor"]});cand=`<div class="eyebrow" style="margin:12px 0 6px">Routing suggestions</div><div class="row">${rr.map(c=>`<button class="chip pchip" data-wfd-pick="${X(c.name)}">${avatar(c.name,{size:22})}${X(c.name)}${c.score?` <small>${Math.round(c.score)}</small>`:""}</button>`).join("")||'<span class="muted small">No matches</span>'}</div>`}catch(e){}}
 return `<p class="muted small">Assign to a <b>team first</b>. Pick a person only by claiming or with a stated reason. The kind is shown everywhere with an avatar badge.</p>${chipsF("Assign to","p.asg.kind",a.kind,kinds)}${a.kind==="team"?fi("Team","p.asg.team",a.team,{sel:TEAMN,ph:"Choose a team"})+chipsF("How work is picked","p.asg.mode",a.mode,[["claim","Claim from queue"],["route","Route by skills and workload"],["round","Round robin"]]):`<div class="fld"><span class="flab">${kinds.find(k=>k[0]===a.kind)[1]}</span><select class="fin" data-wfd-set="p.asg.person" data-wfd-re><option value="">Choose</option>${peopleOpts(a.person,kmap[a.kind])}</select></div>`+(a.kind==="person"?fi("Reason for naming a person","p.asg.why",a.why,{ph:"Only person with Lumen contract knowledge"}):"")}${multiF("Skills required","p.asg.skills",a.skills,SKILLS().slice(0,24))}${a.person?`<div class="row">${pchip(a.person,{role:1})}</div>`:""}${cand}<div class="muted small" style="margin-top:8px">Lane: <b>${X(f.lanes[n.l]?f.lanes[n.l].n:"")}</b>. Dragging the step to another lane changes its owning team.</div>`}
function tgtHTML(f,n){const t=n.p.tg,s=stepStat(f,n,flowStat(f).runs),h=WORKT.includes(n.t)||n.t==="wait";let tbm="";if(window.TBMX&&TBMX.service&&f.service){try{const sv=svcOf(f.service),x=sv&&TBMX.service(sv.id);if(x&&x.monthly)tbm=`<div class="small muted">Service “${X(f.service)}” costs ${money(Math.round(x.monthly))} a month in the TBM model.</div>`}catch(e){}}
 return `<p class="muted small">Targets make the step measurable: SLA (customer), OLA (between teams) and XLA (experience). Costs roll up per run.</p>${fi("SLA target","p.tg.sla",t.sla,{ph:"24 h",help:"Customer-facing time. Accepts 15 min, 4 h, 2 d."})}${fi("OLA target","p.tg.ola",t.ola,{ph:"8 h",help:"Internal commitment between teams."})}${fi("XLA target","p.tg.xla",t.xla,{ph:"Requester told within 1 day",help:"How the person should feel about this step."})}${fi("Expected duration (hours)","p.tg.dur",t.dur,{ty:"num",min:0,step:.01})}${chipsF("Cost basis","p.tg.costMode",t.costMode,[["fixed","Fixed per run"],["hourly","Effort × rate"]])}${t.costMode==="hourly"?fi("Effort (hours per run)","p.tg.effort",t.effort,{ty:"num",min:0,step:.05})+fi("Rate ($ an hour)","p.tg.rate",t.rate,{ty:"num",min:0}):fi("Cost per run ($)","p.tg.cost",t.cost,{ty:"num",min:0,step:.01})}<div class="wfd-note glass"><b>${usd(costOf(n))} per run</b><div class="small muted">${X(costBasis(n))}</div>${tbm}</div>${h?`<div class="eyebrow" style="margin:12px 0 6px">Last 30 days</div><div class="statrow wfd-st"><div class="stat"><small>Average elapsed</small><span class="num" data-role="metric">${fh(s.el)}</span><em>${fh(s.dur)} work + ${fh(s.wait)} queue</em></div><div class="stat"><small>Target met</small><span class="num" data-role="metric">${s.met==null?"-":s.met+"%"}</span><em>${s.sl?"SLA "+fh(s.sl):"no target"}</em></div><div class="stat"><small>Rework</small><span class="num" data-role="metric">${s.rework}%</span><em>sent back or repeated</em></div><div class="stat"><small>Cost</small><span class="num" data-role="metric">${usd(s.cost)}</span><em>vs ${usd(costOf(n))} planned</em></div></div><div class="row">${MET("m_wfstep","m_wfsla","m_rework")}</div>`:""}<div class="row" style="margin-top:8px"><button class="chip" data-go="svc_sla">Open SLA coverage</button>${window.SLAX?'<span class="muted small">Coverage is read from the SLA module.</span>':""}</div>`}
function visHTML(f,n){const v=n.p.vis,vs=f.nodes.filter(x=>x.p.vis&&x.p.vis.show).sort((a,b)=>a.x-b.x);return `<p class="muted small">What the requester sees. Steps are shown in plain words, never in internal jargon.</p>${fi("Show this step to the requester","p.vis.show",!!v.show,{chk:1,re:1})}${v.show?fi("Label the requester sees","p.vis.label",v.label,{ph:"Waiting for finance approval"})+fi("Short explanation","p.vis.desc",v.desc,{area:1,rows:2,ph:"Finance checks the amount against your budget."}):""}<div class="eyebrow" style="margin:12px 0 6px">Requester timeline preview</div><ol class="wfd-tl">${vs.map(x=>`<li class="${x===n?"on":""}"><b>${X(x.p.vis.label||x.n)}</b>${x.p.vis.desc?`<span class="muted small">${X(x.p.vis.desc)}</span>`:""}</li>`).join("")||'<li class="muted">No step is visible yet.</li>'}</ol>`}
function grdHTML(f,n){const g=n.p.guard,money_=/pay|journal|release|hold/i.test(n.a.op||"")||n.t==="approval";const sod=n.t==="approval"?`<div class="wfd-note glass"><b>Separation of duties</b><div class="small">The requester can never approve their own request. The approver is checked against the requester at decision time.</div></div>`:"";
 return `<p class="muted small">What is written down and what is blocked. Every step already writes who, what and when to the audit trail.</p>${fi("Write an audit entry for every execution","p.guard.audit",g.audit!==false,{chk:1})}${fi("Redact personal data in logs and prompts","p.guard.pii",!!g.pii,{chk:1})}${fi("Require evidence (a file or link) to finish","p.guard.evidence",!!g.evidence,{chk:1})}${fi("Four eyes: a second person confirms","p.guard.four",!!g.four,{chk:1,help:money_?"Recommended: this step moves money or decides.":""})}${fi("Note for auditors","p.guard.note",g.note,{area:1,rows:2,ph:"Policy AP-4.2 requires a second approver over $50,000."})}${sod}<div class="eyebrow" style="margin:12px 0 6px">Audit entries this step writes</div><ul class="small wfd-aud"><li>${X(n.n)} started for the record (who, when, inputs)</li><li>${X(n.n)} finished with outcome and outputs</li>${n.t==="agent"?"<li>Agent tool calls, tokens, confidence and fallback decisions</li>":""}${n.t==="approval"?"<li>Decision, comment, assessment scores and any override reason</li>":""}${n.t==="assessment"?"<li>Answers, evidence, score and who prefilled with AI</li>":""}</ul>${n.t==="agent"?`<div class="row"><button class="chip" data-go="flw_agent">Kill switch and spend caps</button></div>`:""}`}
/* ---------- run data panel ---------- */
function runPanelHTML(f){const sim=E.sim,res=sim.res,st=res.steps[sim.i];const ps=res.steps;
 const ctl=`<div class="row wfd-runctl"><button class="chip" data-wfd-sim="prev" aria-label="Previous step">${IC("M15 6l-6 6 6 6")}</button><button class="btn primary" data-wfd-sim="${sim.playing?"pause":"play"}">${sim.playing?"Pause":"Play"}</button><button class="chip" data-wfd-sim="next" aria-label="Next step">${IC("M9 6l6 6-6 6")}</button><button class="chip" data-wfd-sim="restart">Restart</button><span class="muted small num">Step ${sim.i+1} of ${ps.length}</span></div>`;
 const head=`<div class="row sp"><b>${res.ok?"Run: "+X(res.outcome):"Run stopped"}</b><span class="muted small">${fh(res.total)} · ${usd(res.cost)}</span></div>`;
 if(!st)return head+ctl;const T=NTY[st.t],kv=o=>Object.keys(o||{}).length?`<dl class="kv wfd-kv">${Object.entries(o).map(([k,v])=>`<dt>${X(k)}</dt><dd>${X(fmtV(v))}</dd>`).join("")}</dl>`:`<div class="muted small">None</div>`;
 return `${head}${ctl}<div class="wfd-tline" role="list">${ps.map((s,i)=>`<button role="listitem" class="wfd-tl-i ${i===sim.i?"on":""} ${s.status}" data-wfd-simgo="${i}" title="${X(s.name)}" aria-label="Step ${i+1}: ${X(s.name)}"><i></i></button>`).join("")}</div>
 <div class="wfd-stepcard"><div class="row sp"><div><div class="eyebrow" style="margin:0">${T.l}</div><b>${X(st.name)}</b></div>${pill(({done:"Done",skipped:"Skipped",failed:"Failed",blocked:"Blocked by gate",escalated:"Escalated to human"})[st.status]||st.status,st.status==="done"?"good":st.status==="skipped"?"mute":st.status==="failed"?"bad":"warn")}</div>
 <dl class="kv"><dt>Who</dt><dd>${X(st.who||"System")}</dd><dt>Started</dt><dd>${clk(st.start)}</dd><dt>Took</dt><dd class="num">${fh(st.dur)} work${st.wait?" + "+fh(st.wait)+" waiting":""}</dd><dt>Cost</dt><dd class="num">${usd(st.cost)}</dd>${st.sla?`<dt>Target</dt><dd>${st.sla.met?pill("Met ("+fh(st.sla.h)+")","good"):pill("Missed ("+fh(st.sla.h)+")","bad")}</dd>`:""}${st.port&&st.port!=="next"?`<dt>Path taken</dt><dd><b>${X(st.port)}</b></dd>`:""}</dl>
 ${st.why&&st.why.length?`<div class="eyebrow" style="margin:10px 0 4px">Why this path</div><ul class="flw-why">${st.why.map(w=>`<li class="ok">${ico("check")}${X(w)}</li>`).join("")}</ul>`:""}<div class="eyebrow" style="margin:10px 0 4px">Log</div><ul class="wfd-slog">${st.log.map(l=>`<li>${X(l)}</li>`).join("")}</ul>
 <div class="eyebrow" style="margin:10px 0 4px">Data in</div>${kv(st.in)}<div class="eyebrow" style="margin:10px 0 4px">Data out</div>${kv(st.out)}</div>
 <details class="flw-det"><summary>Test record</summary>${kv(res.rec)}</details>`}
/* ================================================================ BOTTOM PANES: PROBLEMS, TEST, VERSIONS, CONVERSIONS, JSON */
const PANES=[["valid","Problems"],["test","Test and runs"],["ver","Versions"],["conv","Conversions"],["json","Import and export"]];
function bottomHTML(f){const v=validate(f),errs=v.filter(x=>x.sev==="err").length,conv=f.nodes.filter(n=>{const c=convSuggest(f,n);return c&&c.conf>=.55}).length,runs=(F.runs[f.id]||[]).length;
 const cnt={valid:v.length,test:runs,ver:(f.history||[]).length+1,conv:conv};
 return `<section class="card glass wfd-bottom"><div class="wfd-ptabs" role="tablist" aria-label="Workflow checks">${PANES.map(p=>`<button class="wfd-ptab" role="tab" data-wfd-pane="${p[0]}" aria-selected="${E.pane===p[0]}">${p[1]}${cnt[p[0]]!=null&&cnt[p[0]]!==0?` <span class="pill ${p[0]==="valid"&&errs?"bad":"mute"}">${cnt[p[0]]}</span>`:""}</button>`).join("")}</div><div class="wfd-pbody">${({valid:validPane,test:testPane,ver:verPane,conv:convPane,json:jsonPane})[E.pane](f)}</div></section>`}
function validPane(f){const v=validate(f),errs=v.filter(x=>x.sev==="err").length;
 return `<div class="row sp"><div><b>${errs?errs+" blocking problem"+(errs>1?"s":""):"No blocking problems"}</b> <span class="muted small">${v.length-errs} warning${v.length-errs===1?"":"s"}</span></div>${legend([["Blocking: fix before publishing","--bad-f"],["Warning: publishes, but worth fixing","--warn-f"]])}</div>${v.length?`<ul class="flw-vl wfd-vl">${v.slice(0,80).map((x,i)=>`<li class="${x.sev}"><span class="flw-vi">${ico(x.sev==="err"?"warn":"info")}</span><div><b>${X(x.msg)}</b><div class="muted small">${X(x.sug||"")}</div></div><div class="row">${x.node?`<button class="chip" data-wfd-focus="${x.node}">Show step</button>`:""}${x.fix?`<button class="btn" data-wfd-fix="${i}">${X(x.fix.l)}</button>`:""}</div></li>`).join("")}</ul>${v.length>80?`<p class="muted small">Showing the first 80 of ${v.length}.</p>`:""}`:`<div class="flw-ok">${ico("check")}<span>Every step is reachable, every input is mapped, every high-risk agent has a human, and every path ends.</span></div>`}`}
const SCEN=[["typical","Typical record"],["high","High value (4x amount)"],["low","Low value (a quarter of the amount)"],["gatefail","Assessment fails"]];
function testPane(f){const rec=recOf(f),flds=DATAMODEL.fields(f.table||"request_item").slice(0,10),runs=F.runs[f.id]||[],sim=E.sim;
 return `<div class="wfd-testgrid"><div><div class="row sp"><b>Test record</b><span class="muted small">${X((DATAMODEL.tables[f.table]||{}).label||f.table)}</span></div><p class="muted small">Edit the values, then run. The record travels through the graph and every step shows the data it received.</p><div class="wfd-recform">${flds.map(fd=>`<label class="fld"><span class="flab">${X(fd.label)}</span><input class="fin" data-wfd-rec="${fd.k}" value="${X(rec[fd.k])}"></label>`).join("")}</div><div class="row"><span class="fchips" role="group" aria-label="Scenario">${SCEN.map(s=>`<button class="chip" data-wfd-scen="${s[0]}">${s[1]}</button>`).join("")}</span></div><div class="row" style="margin-top:8px"><button class="btn primary" data-wfd-test>${ico("bolt")}Run test</button>${sim?`<button class="btn" data-wfd-simstop>Clear run</button>`:""}${f.dirty?'<span class="muted small">Runs the draft, not the published version.</span>':""}</div></div>
 <div><div class="row sp"><b>Run history</b>${legend([["Completed","--good-f"],["Stopped or failed","--bad-f"],["Escalated or blocked","--warn-f"]])}</div>${runs.length?`<div class="wfd-runs">${runs.slice(0,12).map((r,i)=>`<details class="flw-det wfd-run"><summary><i class="wfd-dot ${r.ok?(r.blocked?"warn":"good"):"bad"}"></i><b>${X(r.outcome)}</b> <span class="muted small">${X(r.at)} · ${fh(r.res.total)} · ${usd(r.res.cost)} · ${r.res.steps.length} steps · ${X(r.by)}</span></summary><div class="row" style="margin:6px 0"><button class="chip" data-wfd-runopen="${i}">Replay on canvas</button></div><ol class="wfd-slog2">${r.res.steps.map(s=>`<li class="${s.status}"><b>${X(s.name)}</b> <span class="muted small">${X(s.status)}${s.port&&s.port!=="next"?" via "+X(s.port):""} · ${fh(s.dur+s.wait)}</span><div class="muted small">${X(s.log.slice(-1)[0]||"")}</div></li>`).join("")}</ol></details>`).join("")}</div>`:empty("No test runs yet","Press Run test to watch a record move through this workflow.")}</div></div>`}
function verPane(f){const h=f.history||[];
 return `<div class="row sp"><div><b>Version ${f.ver}${f.dirty?" (draft)":""}</b> <span class="muted small">${f.pub==null?"Never published":"Last published: v"+f.pub}</span></div><button class="btn primary" data-wfd-publish>Publish…</button></div>${f.src==="wfx"||f.src==="process"?`<p class="muted small">This ${f.src==="wfx"?"workflow is registered by another module":"process drives the strip on its tab"}. Publishing writes the changes back so everything that reads it follows.</p>`:""}<table class="wfd-vt"><thead><tr><th>Version</th><th>Status</th><th>By</th><th>When</th><th>What changed</th><th></th></tr></thead><tbody>${[{v:f.ver,st:f.dirty?"draft":"published",by:me(),at:"Now",note:f.dirty?"Unpublished changes ("+f.undo.length+" edits this session)":"Current",cur:1}].concat(h).map(x=>`<tr><td class="num">v${x.v}</td><td>${pill(x.st,x.st==="published"?"good":"warn")}</td><td>${X(x.by)}</td><td>${X(x.at)}</td><td>${X(x.note||"")}</td><td>${x.snap?`<button class="chip" data-wfd-restore="${x.v}">Restore as draft</button>`:x.cur?"":'<span class="muted small">Snapshot not kept</span>'}</td></tr>`).join("")}</tbody></table>`}
function convPane(f){const cs=f.nodes.map(n=>({n,c:convSuggest(f,n)})).filter(x=>x.c&&x.c.conf>=.4).sort((a,b)=>b.c.conf-a.c.conf);
 return `<div class="row sp"><div><b>${cs.length} human step${cs.length===1?"":"s"} an agent could take on</b></div>${aiChip({model:"Claude Sonnet",conf:.78,title:"Agentic conversion",note:"Compares each step's wording, inputs and rework with steps agents already complete reliably.",src:["Step names and instructions","Rework rates","Agent step outcomes"],guards:["Suggestion only"]})}</div>${cs.length?`<div class="wfd-ccs">${cs.map(x=>convCard(f,x.n,x.c,false)).join("")}</div>`:empty("Nothing to convert","Every human step here needs judgment, negotiation or a signature.")}`}
function exportJSON(f){return JSON.stringify({format:"oukala.workflow",version:1,id:f.id,name:f.name,desc:f.desc,kind:f.kind,owner:f.owner,service:f.service,table:f.table,lanes:f.lanes,nodes:f.nodes,edges:f.edges,groups:f.groups,vars:f.vars},null,1)}
function jsonPane(f){return `<div class="row sp"><b>Workflow as JSON</b><span class="row"><button class="chip" data-wfd-copy>Copy</button><button class="chip" data-wfd-dl>Download</button><button class="btn" data-wfd-import="here">Import…</button></span></div><p class="muted small">Portable and diff-able. Importing creates a new draft; it never overwrites this workflow.</p><textarea class="fin wfd-json" readonly rows="10" aria-label="Workflow JSON">${X(exportJSON(f))}</textarea>`}
function importForm(){openForm({id:"wfd_imp",title:"Import a workflow",story:"Paste workflow JSON exported from Oukala. It becomes a new draft; nothing is published.",submit:"Import as draft",fields:[{k:"json",label:"Workflow JSON",type:"longtext",req:true,ph:'{"format":"oukala.workflow",...}'}],onSubmit:v=>{let o;try{o=JSON.parse(v.json)}catch(e){toast("That is not valid JSON: "+e.message,"bad");return{close:false,toast:"Import failed"}}
  if(!o||o.format!=="oukala.workflow"||!Array.isArray(o.nodes)||!Array.isArray(o.edges)){toast("Not an Oukala workflow export.","bad");return{close:false,toast:"Import failed"}}
  const nf=mkFlowBase("wf_"+uid(),(o.name||"Imported workflow")+" (imported)",o.desc,{kind:o.kind||"approval",owner:o.owner||me(),service:o.service||"",table:o.table||"request_item",lanes:o.lanes||[{n:"Team"}],nodes:o.nodes,edges:o.edges,groups:o.groups||[],vars:o.vars||[]});nf.nodes.forEach(n=>{const b=blankP();n.p=Object.assign(b,n.p||{});n.a=Object.assign((A0[n.t]||A0.human)(),n.a||{})});nf.ver=1;nf.pub=null;nf.dirty=true;F.W.push(nf);audit("imported workflow",nf.name);openEditor(nf.id);return{toast:"Imported as a draft: "+nf.nodes.length+" steps"}}})}
function exportFile(f){const b=new Blob([exportJSON(f)],{type:"application/json"}),a=document.createElement("a");a.href=URL.createObjectURL(b);a.download=f.id.replace(/\W/g,"_")+".json";document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},500);audit("exported workflow",f.name);toast("Exported "+f.name+" as JSON","good")}
/* ---- publish ---- */
function publishForm(f){const v=validate(f),errs=v.filter(x=>x.sev==="err");if(errs.length){E.pane="valid";paintBottom();toast(errs.length+" blocking problem"+(errs.length>1?"s":"")+" must be fixed first.","bad");return}
 const r=rowOf(f);openForm({id:"wfd_pub",title:"Publish "+f.name,story:`Publishing makes v${f.ver} the live version. ${f.src==="wfx"?"The registered workflow is updated, so modules that run it follow.":f.src==="process"?"The process strip on its tab is updated.":"Running instances finish on the old version; new ones use this one."} ${v.length?v.length+" warning"+(v.length>1?"s":"")+" remain.":"No warnings."}`,submit:"Publish v"+f.ver,fields:[{k:"note",label:"What changed (shown in version history)",type:"longtext",req:true,ph:"Added an approval over $50,000"},{k:"notify",label:"Tell the people who own these steps",type:"toggle"}],defaults:{note:"",notify:true},
  onSubmit:x=>{const snap=snapF(f);(f.history=f.history||[]).unshift({v:f.ver,st:"published",by:me(),at:"Oct 7",note:x.note,snap});f.pub=f.ver;f.dirty=false;f._v++;writeBack(f);audit("published workflow",f.name+" v"+f.pub);paintAll();return{toast:"Published v"+f.pub+(x.notify?". Step owners notified.":""),audit:x.note}}})}
function writeBack(f){try{if(f.src==="wfx"&&window.WFX){const d=f._def||WFX.get(f.srcId||f.id.replace(/^wfx:/,""));if(!d)return;const steps=f.nodes.filter(n=>!["trigger","end"].includes(n.t)).map(n=>{const nx=f.edges.filter(e=>e.f===n.id).map(e=>e.t).filter(t=>{const x=nodeById(f,t);return x&&x.t!=="end"});const sl=slaOf(n);return Object.assign({},(d.steps||[]).find(s=>s.id===n.id)||{},{id:n.id,n:n.n,type:({human:"human",agent:"agent",auto:"auto",approval:"gate",assessment:"gate",wait:"wait"})[n.t]||"auto",owner:n.p.asg.person||n.p.asg.team||"",team:(f.lanes[n.l]||{}).n,sla:sl?sl:"",cost:costOf(n),next:nx,requesterVisible:!!n.p.vis.show})});const nd=Object.assign({},d,{name:f.name.replace(/ \(.*\)$/,"")===d.name?d.name:f.name,steps});WFX.reg(nd);f._def=nd;delete F.cache[f.id]}
 else if(f.src==="process"&&f.screen){S.proc[f.screen]=f.nodes.filter(n=>!["trigger","end"].includes(n.t)).sort((a,b)=>a.x-b.x).map(n=>({n:n.n,d:n.a.instr||n.a.goal||"",who:({agent:"agent",auto:"auto",approval:"gate"})[n.t]||"human",owner:n.p.asg.person||n.p.asg.team||"",sla:n.p.tg.sla||""}))}}catch(e){console.error("write back",e)}}
/* ---- fixes ---- */
function applyFix(i){const f=curFlow(),it=validate(f)[i];if(!it||!it.fix)return;const[a,id,port]=it.fix.a.split(":");mut(f=>{const n=id&&nodeById(f,id);
 if(a==="addTrigger"){const t=mkNode("T"+uid(),"trigger","Start",0,LW+30,0,{},{});f.nodes.push(t);const first=f.nodes.find(x=>!f.edges.some(e=>e.t===x.id)&&x!==t&&x.t!=="end");if(first)f.edges.push({id:"e"+uid(),f:t.id,p:"next",t:first.id})}
 else if(a==="addEndFree"){const last=f.nodes[f.nodes.length-1],e=mkNode("E"+uid(),"end","Done",last?last.l:0,(last?last.x:LW)+CW,0,{},{});f.nodes.push(e);const tail=f.nodes.filter(x=>x!==e&&x.t!=="end"&&!f.edges.some(ed=>ed.f===x.id));tail.forEach(x=>f.edges.push({id:"e"+uid(),f:x.id,p:outs(x)[0],t:e.id}))}
 else if(a==="addEnd"){const e=mkNode("E"+uid(),"end","Done",n.l,n.x+CW,(n.r||0)?0:1,{outcome:port==="Error"?"Failed":port==="Rejected"?"Rejected":"Completed"},{});f.nodes.push(e);f.edges.push({id:"e"+uid(),f:n.id,p:port,t:e.id})}
 else if(a==="delNode"){f.nodes=f.nodes.filter(x=>x.id!==id);f.edges=f.edges.filter(e=>e.f!==id&&e.t!==id)}
 else if(a==="errPath"){n.p.params.onError="path";n.p.params.retries=Math.max(3,n.p.params.retries||0);n.p.params.backoff="exponential";if(!f.edges.some(e=>e.f===n.id&&e.p==="Error")){const e=mkNode("N"+uid(),"auto","Alert the owner",n.l,n.x+CW,(n.r||0)?0:1,{op:"Send notification",to:f.owner,msg:n.n+" failed for {{rec.id}}"},{});const en=mkNode("E"+uid(),"end","Failed",n.l,n.x+CW*2,(n.r||0)?0:1,{outcome:"Failed"},{});f.nodes.push(e,en);f.edges.push({id:"e"+uid(),f:n.id,p:"Error",t:e.id},{id:"e"+uid(),f:e.id,p:"next",t:en.id})}}
 else if(a==="setComp")n.p.params.comp="Reverse the "+n.n.toLowerCase()+" and release any hold";
 else if(a==="setAuton"){n.a.autonomy="propose";if(!n.a.fallback)n.a.fallback=(f.lanes[0]||{}).n||"Service desk"}
 else if(a==="setFallback")n.a.fallback=TEAMN[0];
 else if(a==="setApprover")n.a.approvers=["Controller"];
 else if(a==="setDur")n.a.dur="PT24H";
 else if(a==="setSla")n.p.tg.sla="24 h"},["applied suggested fix",it.fix.l])}
function convertNode(fid,nid){const f=getFlow(fid);if(!f)return;const n=nodeById(f,nid),c=n&&convSuggest(f,n);if(!n||!c)return;
 const done=()=>{const nn=nodeById(f,nid);pushU(f);nn.t="agent";nn.a=Object.assign(A0.agent(),{agent:AGN[Math.abs(nn.n.length)%AGN.length],goal:(nn.a.instr||nn.n)+". Cite sources and say how sure you are.",autonomy:c.conf>.75?"suggest":"propose",tools:["Articles","Search index"],conf:c.conf>.75?70:80,fallback:(f.lanes[nn.l]||{}).n||"",risk:"low",outcomesWas:(nn.a.outcomes||[]).join(", ")});nn.p.asg={kind:"agent",team:"",person:nn.a.agent,skills:[],mode:"claim"};nn.p.tg.cost=.4;nn.p.tg.dur=Math.max(.02,+(expDur(nn)*.2).toFixed(2));nn.p.tg.costMode="fixed";touch(f);audit("converted step to agentic",f.name+": "+nn.n+" · saves "+fh(c.saveH)+" a run");toast(nn.n+" is now an agent step, proposing for a person to confirm. Review its guardrails.","good");if(F.open===f.id){E.sel=nid;E.tab="grd";paintAll()}else{openEditor(f.id,nid)}};
 openForm({id:"wfd_conv",title:"Convert “"+n.n+"” to an agent step",story:`${Math.round(c.conf*100)}% confidence. Expected saving: ${fh(c.saveH)} a run and about ${usd(c.perMonth)} a month. The agent starts in "${c.mode}" mode and a person stays in the loop.`,submit:"Convert",fields:[{k:"keep",label:"Keep a human fallback for low confidence",type:"toggle"},{k:"why",label:"Why (logged for audit)",type:"longtext",ph:"Routine reading step; 14 of 15 past outcomes matched"}],defaults:{keep:true},onSubmit:()=>{done();return{toast:"Converted"}}})}
/* ---- simulation ---- */
let simT=null;
function stopSim(){if(simT){clearInterval(simT);simT=null}}
function startSim(f,opt){const rec=Object.assign({},recOf(f)),res=simulate(f,rec,opt||{});stopSim();if(!res.steps.length){toast("Add a trigger first, then run the test.","warn");return}
 E.sim={res,i:0,playing:!rs(),opt:opt||{}};E.insp="run";E.sel=res.steps[0].nid;E.pane="test";
 const log=(F.runs[f.id]=F.runs[f.id]||[]);log.unshift({at:"Oct 7, "+new Date().toLocaleTimeString("en-US",{hour:"2-digit",minute:"2-digit"}),by:me(),outcome:res.outcome,ok:res.ok,blocked:res.steps.some(s=>s.status==="blocked"||s.status==="escalated"),res});if(log.length>25)log.pop();
 audit("ran workflow test",f.name+" → "+res.outcome);paintAll();if(E.sim.playing)playSim();else{E.sim.i=res.steps.length-1;E.sel=res.steps[E.sim.i].nid;paintAll()}}
function playSim(){stopSim();E.sim.playing=true;simT=setInterval(()=>{const s=E.sim;if(!s||!document.querySelector("[data-wfd-root]")){stopSim();return}if(s.i>=s.res.steps.length-1){s.playing=false;stopSim();paintAll();toast("Run finished: "+s.res.outcome+" in "+fh(s.res.total)+", "+usd(s.res.cost),s.res.ok?"good":"warn");return}s.i++;E.sel=s.res.steps[s.i].nid;paintCanvas();paintInsp();const el=$q(`[data-wfd-node="${E.sel}"]`);if(el)el.scrollIntoView({block:"nearest",inline:"center",behavior:"smooth"})},950)}
function simStep(d){const s=E.sim;if(!s)return;stopSim();s.playing=false;s.i=Math.max(0,Math.min(s.res.steps.length-1,s.i+d));E.sel=s.res.steps[s.i].nid;paintCanvas();paintInsp()}
/* ================================================================ EVENTS FOR THE DESIGNER */
function setAt(path,val){const f=curFlow(),n=selNode(f);const[o,k]=rootOf(f,n||{},path);if(path.startsWith("f.")||n){if(!E._lu||Date.now()-E._lu>1500)pushU(f);E._lu=Date.now();if(k==="n"&&!path.startsWith("f."))n.n=val;else sp(o,k,val);touch(f);return true}return false}
function setType(n,t){if(n.t===t)return;const old=n.a;n.t=t;n.a=Object.assign((A0[t]||A0.human)(),t==="agent"?{goal:old.instr||old.goal||n.n}:t==="human"?{instr:old.goal||old.instr||""}:{});if(t==="agent"){n.p.asg.kind="agent";n.p.asg.person=n.a.agent}else if(n.p.asg.kind==="agent"){n.p.asg.kind="team";n.p.asg.person=""}}
const arrAt=(f,n,path)=>{const[o,k]=rootOf(f,n||{},path);let v=gp(o,k);if(v==null){sp(o,k,[]);v=gp(o,k)}return v};
const mkRule=()=>({f:"",o:"=",v:"",vt:"lit"});
function mkGroupFromSel(){const f=curFlow(),n=selNode(f);if(!n){toast("Select a step first; it and the steps right after it in the same lane join the sub-flow.","warn");return}
 openForm({id:"wfd_grp",title:"Group into a sub-flow",story:"Folds the selected step and the steps that follow it in the same lane into one collapsible box, so big workflows stay readable.",submit:"Create sub-flow",fields:[{k:"n",label:"Sub-flow name",type:"text",req:true,ph:"Security review"}],defaults:{n:(f.lanes[n.l]||{}).n+" sub-flow"},onSubmit:v=>{mut(f=>{const g={id:"G"+uid(),n:v.n,collapsed:false};f.groups.push(g);let cur=n,k=0;while(cur&&k<5){cur.g=g.id;k++;const nx=f.edges.filter(e=>e.f===cur.id).map(e=>nodeById(f,e.t)).filter(x=>x&&x.l===n.l&&!x.g&&x.t!=="end");cur=nx[0]}},["created sub-flow",v.n]);return{toast:"Sub-flow created. Collapse it from the toolbar."}}})}
function laneForm(i){const f=curFlow(),l=f.lanes[i],cnt=f.nodes.filter(n=>n.l===i).length;
 openForm({id:"wfd_lane",title:"Lane: "+l.n,story:"A lane is the team, AI agent or system that owns the steps in it. Moving a step into a lane assigns it to that team.",submit:"Save lane",fields:[{k:"n",label:"Lane name",type:"select",opts:[l.n].concat(TEAMN.filter(t=>t!==l.n)).concat(["AI agents","System","Requester"].filter(t=>t!==l.n&&!TEAMN.includes(t)))},{k:"x",label:cnt?"Delete lane (move its "+cnt+" steps to the first lane)":"Delete this empty lane",type:"toggle"}],defaults:{n:l.n,x:false},onSubmit:v=>{mut(f=>{if(v.x&&f.lanes.length>1){f.nodes.forEach(n=>{if(n.l===i)n.l=i?0:1;else if(n.l>i)n.l--});f.lanes.splice(i,1)}else f.lanes[i].n=v.n},["edited lane",v.x?"deleted "+l.n:l.n+" → "+v.n]);return{toast:v.x?"Lane deleted":"Lane saved"}}})}
function addLaneForm(){openForm({id:"wfd_alane",title:"Add a lane",story:"Pick the team, AI agent or system that will own the steps in this lane.",submit:"Add lane",fields:[{k:"n",label:"Owner",type:"select",opts:TEAMN.concat(["AI agents","System","Requester","Contractor","Managed service provider"])}],onSubmit:v=>{mut(f=>{f.lanes.push({n:v.n})},["added lane",v.n]);return{toast:"Lane added"}}})}
function settingsForm(){const f=curFlow();openForm({id:"wfd_set",title:"Workflow settings",story:"Name, owner and where it applies. Changes are saved to the draft.",submit:"Save",fields:[{k:"name",label:"Name",type:"text",req:true},{k:"desc",label:"What it does",type:"longtext"},{k:"owner",label:"Owner",type:"people"},{k:"service",label:"Business service it supports",type:"text"},{k:"kind",label:"Kind",type:"select",opts:["request","incident","change","approval","onboarding","release","contract","purchase","process"]}],defaults:{name:f.name,desc:f.desc,owner:f.owner,service:f.service,kind:f.kind},onSubmit:v=>{mut(f=>{Object.assign(f,{name:v.name,desc:v.desc,owner:v.owner||f.owner,service:v.service,kind:v.kind})},["edited workflow settings",v.name],true);audit("edited workflow settings",v.name);return{toast:"Saved"}}})}
function dupNode(id){mut(f=>{const n=nodeById(f,id),c=clone(n);c.id="N"+uid();c.n=n.n+" (copy)";c.x=n.x+22;c.r=n.r?0:1;f.nodes.push(c);E.sel=c.id},["duplicated step",id])}
function expandG(id,on){mut(f=>{const g=f.groups.find(x=>x.id===id);if(g)g.collapsed=on},["toggled sub-flow",id],true)}
function mapDmn(){const f=curFlow(),n=selNode(f),t=F.dmn.find(x=>x.id===n.a.dmn);if(!t){toast("Choose a decision table first.","warn");return}const pm=pillMap(f,n),pills=Object.values(pm);
 mut(()=>{t.inputs.forEach(i=>{if(n.p.inputs.some(x=>x.name===i.l))return;const lab=i.l.toLowerCase(),hit=pills.find(p=>p.label.toLowerCase()===lab)||pills.find(p=>p.label.toLowerCase().includes(lab)||lab.includes(p.label.toLowerCase()));n.p.inputs.push({name:i.l,type:i.t==="num"?"num":"text",src:hit?"pill":"lit",val:hit?hit.id:"",req:true})})},["mapped decision table inputs",t.name])}
