const qFL=(id,q,w,o)=>Object.assign({id,t:"file",q,w},o||{});
const qMX=(id,q,w,rows,o)=>Object.assign({id,t:"matrix",q,w,rows,lo:"Weak",hi:"Strong"},o||{});
