const SUBJ=["Lumen Search Services renewal","Azure region expansion","Okta replacement","Vendor: Northwind Staffing","Codification Platform release 4.2","New e-signature provider","Data lake for member analytics","Contoso Cloud Operations contract","Entra ID conditional access change","Expense tool migration","Teams telephony cutover","Backup vault consolidation","Search relevance model","Lease subledger upgrade","Public API gateway","Standards PDF generator","Member portal redesign","Payroll provider change","Disaster recovery site move","Contract repository OCR service"];
const SME_ALL=()=>DIR.filter(d=>d.kind!=="msp").slice(0,60).map(d=>d.name);
const SEEDR=[["AS-3001","asm_vend","Lumen Search Services renewal","Contract Repository","Maya Ortiz","complete",.78,"gate","AP-2104","Sep 29"],["AS-3002","asm_sec","Lumen Search Services renewal","Search and indexing","Rina Okafor","complete",.62,"gate","AP-2104","Sep 30"],["AS-3003","asm_sec","Okta replacement","Identity (Entra ID)","Rina Okafor","complete",.84,"advisory","AP-2106","Oct 1"],["AS-3004","asm_chg","Entra ID conditional access change","Identity (Entra ID)","Nia Brooks","complete",.55,"advisory","AP-2107","Oct 2"],["AS-3005","asm_arch","Data lake for member analytics","Data platform","Jordan Lee","complete",.7,"advisory","AP-2110","Oct 2"],["AS-3006","asm_priv","Member portal redesign","Member portal","Chief Editor","complete",.45,"gate","AP-2111","Oct 3"],["AS-3007","asm_data","Standards PDF generator","Codification Platform","Rina Okafor","complete",.8,"advisory","","Oct 3"],["AS-3008","asm_vend","New e-signature provider","Contract Repository","Maya Ortiz","progress",.7,"gate","AP-2112","Oct 9"],["AS-3009","asm_sec","Public API gateway","Integration hub","Rina Okafor","progress",.6,"gate","AP-2113","Oct 8"],["AS-3010","asm_chg","Backup vault consolidation","Azure","Nia Brooks","assigned",.7,"advisory","AP-2108","Oct 12"],["AS-3011","asm_sec","Contoso Cloud Operations contract","Azure","Rina Okafor","assigned",.7,"gate","AP-2114","Oct 14"],["AS-3012","asm_priv","Payroll provider change","Payroll","Chief Editor","assigned",.7,"gate","","Oct 6"]];
let _gen=null,_genN=-1;
function genResults(){const n=SCALE.on?620:0;if(_gen&&_genN===n)return _gen;_genN=n;const r=RNG("asmgen"),out=[];const st=["complete","complete","complete","complete","progress","assigned"];for(let i=0;i<n;i++){const t=AS.types[Math.floor(r()*AS.types.length)],bias=.35+r()*.6,s=SUBJ[Math.floor(r()*SUBJ.length)]+(i>19?" "+(1+i%9):""),sme=SME_ALL(),who=sme[Math.floor(r()*sme.length)];out.push({id:"AS-"+(4000+i),type:t.id,subject:s,svc:"",by:who,status:st[Math.floor(r()*st.length)],bias,mode:r()<.55?"gate":"advisory",appr:"",due:"Oct "+(1+Math.floor(r()*28)),seq:100+i,gen:1})}_gen=out;return out}
function fitAnswers(t,id,target,tries){let best=null,bd=1e9;for(let k=0;k<tries;k++){const a=autoAnswers(t,id+"#"+k,target,1.1),d=Math.abs(scoreOf(t,a).score-target*100);if(d<bd){bd=d;best=a;if(d<=2)break}}return best}
function hydrate(r){if(r._h&&r._h===r.status+(r.ovr?1:0))return r;const t=aType(r.type);if(!t)return r;if(!r.answers)r.answers=r.status==="assigned"?{}:fitAnswers(t,r.id,r.bias==null?.6:r.bias,r.gen?30:120);if(r.status==="progress"&&!r._part){r._part=1;Object.keys(r.answers).forEach((k,i)=>{if(i%2)delete r.answers[k]})}const sc=scoreOf(t,r.answers);r.score=r.status==="assigned"?null:sc.score;r.band=r.status==="assigned"?null:sc.band;r.pass=sc.pass;r._h=r.status+(r.ovr?1:0);return r}
function allResults(){if(!AS._seeded){AS._seeded=1;SEEDR.forEach((x,i)=>{AS.results.push({id:x[0],type:x[1],subject:x[2],svc:x[3],by:x[4],status:x[5]==="complete"?"complete":x[5],bias:x[6],mode:x[7],appr:x[8],due:x[9],seq:i+1})})}return AS.results.concat(genResults()).map(hydrate)}
const BANDTONE={good:"--good-f",info:"--story-f",warn:"--warn-f",bad:"--bad-f"};
const STATLAB={complete:"Complete",progress:"In progress",assigned:"Assigned, not started"};
const bandPill=r=>r.band?pill(r.band.n+" · "+r.score,r.band.tone):pill("Not started","mute");
const modePill=m=>m==="gate"?pill("Required gate","bad"):pill("Advisory","warn");
const MODELEG=()=>legend([["Required gate: blocks the approval until complete and passing","--bad-f"],["Advisory: the approver sees the score and can override with a reason","--warn-f"]]);
const BANDLEG=()=>legend([["Low risk","--good-f"],["Moderate","--story-f"],["High","--warn-f"],["Critical","--bad-f"]]);
function asmTotals(){const rs=allResults(),done=rs.filter(r=>r.status==="complete"),gates=done.filter(r=>r.mode==="gate"),gp=gates.filter(r=>r.pass),ov=done.filter(r=>r.ovr).length,od=rs.filter(r=>r.status!=="complete"&&r.due&&/^Oct (\d+)/.test(r.due)&&+r.due.slice(4)<7).length;
 const byT={};done.forEach(r=>{const k=byT[r.type]=byT[r.type]||{n:0,low:0,mod:0,high:0,crit:0};k.n++;const b=r.band.tone;if(b==="good")k.low++;else if(b==="info")k.mod++;else if(b==="warn")k.high++;else k.crit++});
 return{n:rs.length,done:done.length,avg:done.length?Math.round(done.reduce((s,r)=>s+r.score,0)/done.length):0,gatePass:gates.length?Math.round(gp.length/gates.length*100):0,gates:gates.length,ov,od,open:rs.length-done.length,byT,rs}}
/* ---- screen ---- */
function asmScreen(){const t=asmTotals();METRICS.m_gatepass.cur=t.gatePass;const tab=AS.tab;
 return `<div class="screen">${hero("Automation · Assessments","Questions that score a risk, kept apart from the decision",`<b>${t.done} assessments</b> are complete and average <b>${t.avg}</b> out of 100. <b>${t.gatePass}%</b> of required gates passed first time, <b>${t.open}</b> are still open${t.od?` and <b>${t.od}</b> are overdue`:""}. An assessment is a form with weights and a score. It never approves anything. Attach it to an approval or a workflow step as a <b>required gate</b> that blocks, or as an <b>advisory input</b> that an approver may override with a reason.`,`<div class="row">${MET("m_gatepass","m_aprover")}${stdChip("nist","Security assessments are scored against NIST CSF 2.0 control families.")}${stdChip("iso27k")}<button class="btn primary" data-asm-assign>Assign an assessment</button><button class="btn" data-asm-new>New assessment type</button></div>`)}${lensNote()}
 ${tiles([TL("Completed",t.done,"of "+t.n+" in the last 90 days","good"),TL("Average score",t.avg,"Σ weighted answers ÷ Σ weights, 0 to 100",t.avg<70?"warn":"good"),TL("Gate pass rate",t.gatePass+"%","Σ gates passed ÷ gates completed",t.gatePass<METRICS.m_gatepass.tgt?"warn":"good"),TL("Advisories overridden",t.ov,"approver decided against the score",t.ov?"warn":"good")])}
 <div class="row asm-tabs" role="tablist" aria-label="Assessments">${[["res","Results"],["bld","Builder"],["use","Where they are used"]].map(x=>`<button class="chip" role="tab" data-asm-tab="${x[0]}" aria-pressed="${tab===x[0]}">${x[1]}</button>`).join("")}</div>
 ${tab==="res"?asmResults(t):tab==="bld"?asmBuilder():asmUsed()}${procCard("flw_asmt")}</div>`}
function asmResults(t){const rows=AS.types.map(x=>({x,k:t.byT[x.id]||{n:0,low:0,mod:0,high:0,crit:0}}));const open=t.rs.filter(r=>r.status!=="complete"&&r.seq<100);const smes=[...new Set(open.map(r=>r.by))].slice(0,4);
 return `<div class="grid g2"><section class="card glass"><div class="cardhead"><div><h3>Results by risk band</h3><span class="muted small" data-role="story">Each bar is 100% of the completed assessments of that type.</span></div>${fchip("m_gatepass")}</div>${rows.map(({x,k})=>`<div class="asm-br"><button class="wfd-lnk" data-asm-type="${x.id}">${X(x.n)}</button><span class="asm-stack" role="img" aria-label="${k.n} completed: ${k.low} low, ${k.mod} moderate, ${k.high} high, ${k.crit} critical">${[["low","--good-f"],["mod","--story-f"],["high","--warn-f"],["crit","--bad-f"]].map(b=>k[b[0]]?`<i style="width:${k[b[0]]/k.n*100}%;background:var(${b[1]})"></i>`:"").join("")}</span><span class="num small" data-role="metric">${k.n}</span></div>`).join("")}${BANDLEG()}</section>
 <section class="card glass"><div class="cardhead"><div><h3>Waiting on experts</h3><span class="muted small" data-role="story">Drag an assessment to another expert to reassign it. Alt plus arrow keys also work.</span></div></div><div class="asm-cols">${smes.map(s=>`<div class="asm-col"><div class="row"><span class="pchip">${avatar(s,{size:22})}<b>${X(s)}</b></span><span class="muted small">${open.filter(r=>r.by===s).length}</span></div><div data-dnd="${X(s)}" data-dnd-scope="asm_assign" class="asm-dl">${open.filter(r=>r.by===s).map(r=>`<div class="asm-dc" data-dnd-id="${r.id}" tabindex="0"><span class="grip" aria-hidden="true"></span><button class="wfd-lnk" data-asm-open="${r.id}">${X(aType(r.type).n)}</button><small class="muted">${X(r.subject)} · due ${X(r.due)}</small></div>`).join("")||'<small class="muted">Nothing waiting</small>'}</div></div>`).join("")||empty("Nothing waiting","Every assessment is complete.")}</div></section></div>
 ${card("All assessment results","Search, filter and sort "+t.n.toLocaleString("en-US")+" results. Select one for the answers, score and where it is used.",btHTML({id:"asm_list",key:"id",h:480,rowH:48,exportName:"assessments",facets:["type","bandn","status","mode"],groupBy:["type","bandn","status","mode","by"],sort:{k:"seq",d:-1},rows:()=>allResults().map(r=>Object.assign({},r,{typen:aType(r.type)?aType(r.type).n:r.type,bandn:r.band?r.band.n:"Not scored"})),cols:[{k:"id",label:"Assessment"},{k:"type",label:"Type",val:r=>r.typen,fmt:r=>X(r.typen)},{k:"subject",label:"About",wrap:1,fmt:r=>`<b>${X(r.subject)}</b>${r.svc?`<div class="muted small">${X(r.svc)}</div>`:""}`},{k:"score",label:"Score",cls:"num",val:r=>r.score==null?-1:r.score,fmt:r=>r.score==null?"-":r.score},{k:"bandn",label:"Band",fmt:r=>bandPill(r)},{k:"mode",label:"Used as",val:r=>r.mode,fmt:r=>modePill(r.mode)},{k:"status",label:"Status",val:r=>STATLAB[r.status],fmt:r=>pill(STATLAB[r.status],r.status==="complete"?"good":"warn")},{k:"by",label:"Expert",fmt:r=>`<span class="pchip">${avatar(r.by,{size:20})}${X(r.by)}</span>`},{k:"due",label:"Due"},{k:"appr",label:"Approval",fmt:r=>r.appr?X(r.appr):"-"}],open:id=>openResult(id)})+MODELEG()+BANDLEG())}`}
function asmBuilder(){const t=aType(AS.type)||AS.types[0];const w=t.q.reduce((s,q)=>s+q.w,0)||1;
 return `<div class="row asm-types" role="tablist" aria-label="Assessment types">${AS.types.map(x=>`<button class="chip" role="tab" data-asm-type="${x.id}" aria-pressed="${x.id===t.id}">${X(x.n)}</button>`).join("")}</div>
 <div class="asm-g"><section class="card glass"><div class="cardhead"><div><h3>${X(t.n)}</h3><span class="muted small" data-role="story">${X(t.desc)}</span></div><div class="row"><button class="btn" data-asm-edit="${t.id}">Details</button><button class="btn" data-asm-dup="${t.id}">Duplicate</button><button class="btn primary" data-asm-try="${t.id}">Try it</button></div></div>
  <div class="row" style="margin-bottom:10px"><span class="muted small">Pass mark <b class="num" data-role="metric">${t.pass}</b> of 100 · ${t.q.length} questions · weights add to ${w}</span><span class="muted small">Answered by ${t.sme.map(X).join(", ")||"anyone"}</span></div>
  <div data-dnd="${t.id}" data-dnd-scope="asm_q" class="asm-ql">${t.q.map((q,i)=>`<div class="asm-q" data-dnd-id="${q.id}" tabindex="0" aria-label="Question ${i+1}. Alt plus arrow keys to reorder."><span class="grip" aria-hidden="true"></span><span class="num asm-qn">${i+1}</span><div class="asm-qt"><b>${X(q.q)}</b><div class="muted small">${pill(QTYPE[q.t],"mute")} ${q.show?`<span class="asm-cond">Shown when “${X((t.q.find(x=>x.id===q.show.q)||{q:"?"}).q.slice(0,40))}” is ${q.show.v.map(X).join(" or ")}</span>`:""}${q.hint?` · ${X(q.hint)}`:""}</div></div><span class="asm-w" title="Weight: share of the score"><span class="asm-wb"><i style="width:${q.w/w*100}%"></i></span><b class="num">${q.w?Math.round(q.w/w*100)+"%":"unscored"}</b></span><button class="chip" data-asm-qedit="${q.id}">Edit</button><button class="flw-x" data-asm-qdel="${q.id}" aria-label="Delete question ${i+1}">${IC("M6 6l12 12M18 6L6 18")}</button></div>`).join("")}</div><div class="row" style="margin-top:10px"><button class="btn" data-asm-qadd>Add a question</button><span class="muted small">Types: yes or no, choice, scale, matrix, text and file evidence. Any question can depend on an earlier answer.</span></div></section>
 <section class="card glass"><div class="cardhead"><div><h3>Scoring</h3><span class="muted small" data-role="story">Higher is safer. The score is a weighted average of the answers shown, from 0 to 100.</span></div></div><div class="asm-formula"><code>score = Σ(weight × answer points) ÷ Σ(weight of visible scored questions) × 100</code></div><div class="eyebrow" style="margin:12px 0 6px">Risk bands</div>${t.bands.slice().sort((a,b)=>b[1]-a[1]).map((b,i,a)=>`<div class="asm-band"><i style="background:var(${BANDTONE[b[2]]})"></i><b>${X(b[0])}</b><span class="muted small num">${b[1]} to ${i?a[i-1][1]-1:100}</span></div>`).join("")}${BANDLEG()}<div class="row" style="margin-top:8px"><button class="chip" data-asm-bands="${t.id}">Edit pass mark and bands</button></div><div class="eyebrow" style="margin:14px 0 6px">Experts who can answer</div><div class="row">${t.sme.map(s=>`<span class="pchip">${avatar(s,{size:22})}${X(s)}</span>`).join("")||'<span class="muted small">Anyone</span>'}</div></section></div>`}
const QTYPE={yn:"Yes or no",choice:"Choice",scale:"Scale 1 to 5",matrix:"Matrix",text:"Text",file:"File evidence"};
/* where each assessment type is used: workflow steps, approval kinds */
function usesOf(tid){const out={flows:[],kinds:[]};allFlows().forEach(f=>f.nodes.forEach(n=>{if(n.t==="assessment"&&n.a.type===tid)out.flows.push({f,n,mode:n.a.gate==="advisory"?"advisory":"gate",via:"Assessment step"});if(n.t==="approval"&&(n.a.asm||[]).some(a=>a.type===tid))out.flows.push({f,n,mode:n.a.asm.find(a=>a.type===tid).mode,via:"Attached to approval step"})}));AS.attach.filter(a=>a.type===tid).forEach(a=>out.kinds.push(a));return out}
function asmUsed(){return `<div class="grid g2">${AS.types.map(t=>{const u=usesOf(t.id);return `<section class="card glass"><div class="cardhead"><div><h3>${X(t.n)}</h3><span class="muted small">${u.flows.length} workflow step${u.flows.length===1?"":"s"} · ${u.kinds.length} approval type${u.kinds.length===1?"":"s"}</span></div><button class="btn" data-asm-attach="${t.id}">Attach to…</button></div>${lrHTML({id:"asm_use_"+t.id,limit:5,search:false,empty:"Not attached anywhere yet.",groups:[{key:"k",label:"Approval types",rows:u.kinds.map(a=>({id:a.target,t:(APK_LABEL(a.target)),sub:"Attached by "+a.by+" on "+a.at,tag:a.mode==="gate"?"Required gate":"Advisory",st:a.mode==="gate"?"bad":"warn",go:()=>go("flw_appr")}))},{key:"f",label:"Workflow steps",rows:u.flows.map(x=>({id:x.f.id+x.n.id,t:x.n.n,sub:x.f.name+" · "+x.via,tag:x.mode==="gate"?"Required gate":"Advisory",st:x.mode==="gate"?"bad":"warn",go:()=>openEditor(x.f.id,x.n.id)}))}]})}</section>`}).join("")}</div>${MODELEG()}`}
const APK_LABEL=t=>String(t).replace(/^kind:/,"").replace(/^./,c=>c.toUpperCase()).replace(/_/g," ")+" approvals";
/* ---- result drawer ---- */
function openResult(id){const r=allResults().find(x=>x.id===id);if(!r)return;const t=aType(r.type);if(!t)return;AS.sel=id;const sc=scoreOf(t,r.answers||{});
 const links=lrHTML({id:"asm_lr_"+id,limit:4,search:false,groups:[{key:"a",label:"Approval",rows:r.appr?[{id:r.appr,t:r.appr,sub:r.subject,tag:r.mode==="gate"?"Gate":"Advisory",st:r.mode==="gate"?"bad":"warn",go:()=>{closeDrawer();go("flw_appr",r.appr)}}]:[]},{key:"s",label:"Service",rows:r.svc?[{id:r.svc,t:r.svc,sub:"Assessed service",tag:"Service",st:"info",go:()=>{if(window.openImpact)openImpact({type:"service",service:r.svc,id:r.svc})}}]:[]},{key:"w",label:"Workflow steps that use this type",rows:usesOf(t.id).flows.slice(0,8).map(x=>({id:x.f.id+x.n.id,t:x.n.n,sub:x.f.name,tag:x.mode==="gate"?"Gate":"Advisory",st:x.mode==="gate"?"bad":"warn",go:()=>{closeDrawer();openEditor(x.f.id,x.n.id)}}))}]});
 openDrawer(`<div class="eyebrow">${X(t.n)} · ${X(r.id)}</div><h2 style="font-size:28px;margin:6px 0">${X(r.subject)}</h2><div class="row">${r.status==="complete"?bandPill(r):pill(STATLAB[r.status],"warn")}${modePill(r.mode)}${pill(r.pass||r.status!=="complete"?(r.status==="complete"?"Passing":"Not finished"):"Below pass mark "+t.pass,r.status!=="complete"?"mute":r.pass?"good":"bad")}${r.ovr?pill("Overridden","warn"):""}</div>
 <p class="story" data-role="story">${r.status==="complete"?`Scored <b class="num" data-role="metric">${r.score}</b> out of 100 by ${X(r.by)}. ${r.mode==="gate"?(r.pass?"It passed, so the approval may proceed.":"It did not pass, so the approval stays blocked until the answers improve or an exception is approved."):(r.pass?"The approver sees a healthy score.":"The approver sees a low score and may still decide, but must give a reason to go against it.")}`:`Waiting on ${X(r.by)}, due ${X(r.due)}.`}</p>
 ${r.ovr?`<div class="asm-ovr glass"><b>Override logged</b><div class="small">${X(r.ovr.by)} on ${X(r.ovr.at)}: ${X(r.ovr.reason)}</div></div>`:""}
 <div class="row" style="margin:10px 0">${r.status==="complete"?"":`<button class="btn primary" data-asm-resume="${r.id}">${r.status==="assigned"?"Start":"Continue"}</button>`}<button class="btn" data-asm-reassign="${r.id}">Reassign</button>${r.status==="complete"&&r.mode==="advisory"&&!r.pass&&!r.ovr?`<button class="btn" data-asm-ovr="${r.id}">Record an override</button>`:""}${r.status==="complete"?`<button class="btn" data-asm-redo="${r.id}">Run again</button>`:""}</div>
 ${r.status==="complete"?`<div class="eyebrow">How the score was worked out</div><div class="tablewrap"><table class="asm-tt"><thead><tr><th>Question</th><th>Answer</th><th class="num">Points</th><th class="num">Weight</th></tr></thead><tbody>${sc.rows.map(x=>`<tr><td>${X(x.q.q)}</td><td>${X(ansTxt(x.q,x.a))}${r.prefill&&r.prefill.includes(x.q.id)?" "+pill("AI prefilled","info"):""}</td><td class="num">${x.p==null?"-":Math.round(x.p*100)}</td><td class="num">${x.q.w||"-"}</td></tr>`).join("")}</tbody></table></div><div class="muted small" style="margin-top:6px">Score = Σ(weight × points) ÷ Σ(weight) = ${sc.score}. Pass mark ${t.pass}.</div>`:""}
 ${r.prefill&&r.prefill.length?`<div class="row" style="margin-top:10px">${aiChip({model:"Claude Sonnet",conf:.8,title:"Prefilled from evidence",note:r.prefill.length+" answers were drafted from documents the subject already has on file. The expert confirmed or changed each one.",src:["SOC 2 report","Vendor questionnaire","Contract Repository","CMDB record"],guards:["Expert confirms every answer","Prefill never submits"]})}<span class="muted small">${r.prefill.length} answers drafted by AI</span></div>`:""}
 <div class="eyebrow" style="margin-top:14px">Linked records</div>${links}`)}
function ansTxt(q,a){if(a==null||a==="")return"(not answered)";if(q.t==="matrix")return Object.entries(a).map(([k,v])=>k+": "+v+"/5").join(", ");if(q.t==="scale")return a+" of 5";if(q.t==="file")return a?"File: "+a:"No file";return String(a)}
/* ---- answering ---- */
function startTake(tid,subject,o){o=o||{};const t=aType(tid);if(!t){toast("That assessment type does not exist.","bad");return}const ex=o.rid&&allResults().find(r=>r.id===o.rid);
 AS.take={tid,subject:subject||(ex&&ex.subject)||"Untitled subject",rid:o.rid||null,answers:ex&&ex.answers&&Object.keys(ex.answers).length?clone(ex.answers):{},prefill:(ex&&ex.prefill)||[],preview:!!o.preview,mode:o.mode||(ex&&ex.mode)||"gate",appr:o.appr||(ex&&ex.appr)||"",svc:o.svc||(ex&&ex.svc)||"",done:o.done||null,tried:false};drawTake()}
function takeBody(){const T=AS.take,t=aType(T.tid),vis=visQ(t,T.answers),sc=scoreOf(t,T.answers);
 return `<div class="asm-live glass"><div><div class="eyebrow" style="margin:0">Score so far</div><b class="num asm-big" data-role="metric">${sc.score}</b> <span class="muted small">of 100 · pass mark ${t.pass}</span></div><div class="row">${pill(sc.band.n,sc.band.tone)}${sc.pass?pill("Passing","good"):pill("Under pass mark","warn")}${modePill(T.mode)}</div></div>
 <div class="asm-qs">${vis.map((q,i)=>{const a=T.answers[q.id],ai=T.prefill.includes(q.id),miss=T.tried&&q.t!=="text"&&!qAnswered(q,a);return `<fieldset class="asm-qa${miss?" miss":""}"><legend><span class="num">${i+1}.</span> ${X(q.q)}${q.w?"":""} ${ai?`<span class="asm-ai">${aiChip({model:"Claude Sonnet",conf:.8,title:"Drafted from evidence",note:"This answer was drafted from documents on file. Change it if it is wrong.",src:["Vendor questionnaire","SOC 2 report"],guards:["You confirm every answer"]})}</span>`:""}</legend>${q.hint?`<div class="muted small">${X(q.hint)}</div>`:""}${qInput(q,a)}${miss?'<small class="ferr">Answer this to submit.</small>':""}</fieldset>`}).join("")}</div>`}
function qInput(q,a){if(q.t==="yn"||q.t==="choice")return `<div class="fchips" role="radiogroup">${q.opts.map((o,i)=>`<button type="button" class="chip" role="radio" aria-checked="${a===o[0]}" aria-pressed="${a===o[0]}" data-asm-pick="${q.id}|${i}">${X(o[0])}</button>`).join("")}</div>`;
 if(q.t==="scale")return `<div class="asm-scale" role="radiogroup"><span class="muted small">${X(q.lo)}</span>${[1,2,3,4,5].map(v=>`<button type="button" class="chip" role="radio" aria-checked="${num(a)===v}" aria-pressed="${num(a)===v}" data-asm-pick="${q.id}|${v}">${v}</button>`).join("")}<span class="muted small">${X(q.hi)}</span></div>`;
 if(q.t==="matrix")return `<div class="asm-mx">${q.rows.map(r=>`<div class="asm-mr"><span>${X(r)}</span><span class="asm-scale" role="radiogroup" aria-label="${X(r)}"><span class="muted small">${X(q.lo)}</span>${[1,2,3,4,5].map(v=>`<button type="button" class="chip" role="radio" aria-checked="${a&&a[r]===v}" aria-pressed="${!!a&&a[r]===v}" data-asm-mx="${q.id}|${X(r)}|${v}">${v}</button>`).join("")}<span class="muted small">${X(q.hi)}</span></span></div>`).join("")}</div>`;
 if(q.t==="file")return `<div class="row">${a?`<span class="pill info">${ico("check")} ${X(a)}</span><button class="chip" data-asm-file="${q.id}|clear">Remove</button>`:`<button class="btn" data-asm-file="${q.id}">Attach evidence</button><span class="muted small">PDF, image or spreadsheet</span>`}</div>`;
 return `<textarea class="fin" rows="2" data-asm-ans="${q.id}" aria-label="${X(q.q)}">${X(a||"")}</textarea>`}
function drawTake(){const T=AS.take,t=aType(T.tid);openDrawer(`<div class="eyebrow">${T.preview?"Preview":"Answer"} · ${X(t.n)}</div><h2 style="font-size:26px;margin:6px 0">${X(T.subject)}</h2><p class="muted">${X(t.desc)}</p><div class="row" style="margin:8px 0"><button class="btn" data-asm-prefill>${ico("sparkle")}Prefill with AI</button><span class="muted small">Drafts answers from documents on file. You confirm each one.</span></div><div id="asmTake">${takeBody()}</div><div class="row asm-foot"><button class="btn primary" data-asm-submit>${T.preview?"Close preview":"Submit assessment"}</button><button class="btn" data-asm-save>Save draft</button></div>`)}
function repaintTake(){const el=$q("#asmTake");if(el){const y=el.closest("#drawer")?document.querySelector("#drawer").scrollTop:0;el.innerHTML=takeBody();const d=$q("#drawer");if(d)d.scrollTop=y}}
function saveTake(final){const T=AS.take,t=aType(T.tid);if(T.preview){closeDrawer();return}const sc=scoreOf(t,T.answers);if(final){T.tried=true;if(sc.missing.length){repaintTake();toast(sc.missing.length+" question"+(sc.missing.length>1?"s":"")+" still to answer.","warn");return}}
 let r=T.rid&&AS.results.find(x=>x.id===T.rid);const base={type:T.tid,subject:T.subject,answers:clone(T.answers),prefill:T.prefill.slice(),mode:T.mode,appr:T.appr,svc:T.svc};if(!r){r=Object.assign({id:"AS-"+(3100+AS.results.length),by:me(),due:"Oct 14",seq:200+AS.results.length},base);AS.results.push(r)}else Object.assign(r,base);
 r.status=final?"complete":"progress";r.bias=null;r._h=null;if(final){r.by=me();r.at="Oct 7"}hydrate(r);audit(final?"completed assessment":"saved assessment draft",t.n+" · "+T.subject+(final?" · score "+r.score:""));toast(final?`${t.n} complete: ${r.score} (${r.band.n}). ${r.mode==="gate"?(r.pass?"The gate passes.":"The gate stays closed."):"The approver will see it."}`:"Draft saved",final?(r.pass?"good":"warn"):"info");const cb=T.done;closeDrawer();if(final&&cb)cb(r);if(typeof render==="function")render()}
function prefill(){const T=AS.take,t=aType(T.tid),a=autoAnswers(t,T.subject,.72),vis=visQ(t,a);let n=0;vis.forEach(q=>{if(T.answers[q.id]==null||T.answers[q.id]===""){if(q.t==="text"&&!a[q.id])return;T.answers[q.id]=a[q.id];if(!T.prefill.includes(q.id))T.prefill.push(q.id);n++}});audit("AI prefilled assessment",t.n+": "+n+" answers");toast(n+" answers drafted from evidence. Review each one before you submit.","info");repaintTake()}
/* ---- forms ---- */
function assignForm(tid){const sme=SME_ALL();openForm({id:"asm_assign",title:"Assign an assessment",story:"Pick the type and the experts who should answer. Experts can be employees, AI agents, contractors or a managed service provider.",submit:"Assign",defaults:{type:tid||AS.type,mode:"gate",due:"2026-10-14",prefill:true,sme:[]},fields:[{section:"What"},{k:"type",label:"Assessment type",type:"select",opts:AS.types.map(t=>[t.id,t.n])},{k:"subject",label:"What is being assessed",type:"text",req:true,ph:"Lumen Search Services renewal"},{k:"mode",label:"How it is used",type:"chips",opts:[["gate","Required gate"],["advisory","Advisory input"]]},{section:"Who"},{k:"sme",label:"Experts who answer",type:"people",multi:true},{k:"due",label:"Due",type:"date"},{k:"prefill",label:"Draft answers with AI first",type:"toggle"}],
 onSubmit:v=>{const t=aType(v.type),by=(v.sme&&v.sme[0])||(t.sme[0]||me());const r={id:"AS-"+(3100+AS.results.length),type:v.type,subject:v.subject,svc:"",by,sme:v.sme||[],status:"assigned",mode:v.mode,appr:"",due:v.due?fmtDue(v.due):"Oct 14",seq:200+AS.results.length,answers:{}};if(v.prefill){const a=autoAnswers(t,v.subject,.72);r.answers={};r.prefill=[];visQ(t,a).forEach((q,i)=>{if(i%3!==2&&(q.t!=="text")){r.answers[q.id]=a[q.id];r.prefill.push(q.id)}});r.status="progress"}AS.results.push(r);audit("assigned assessment",t.n+" · "+v.subject+" → "+by);AS.tab="res";render();return{toast:`Assigned to ${by}${v.prefill?". AI drafted "+r.prefill.length+" answers for them to confirm.":"."}`}}})}
const fmtDue=d=>{const m=String(d).match(/(\d{4})-(\d{2})-(\d{2})/);return m?["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"][+m[2]-1]+" "+(+m[3]):d};
function typeForm(id){const t=id&&aType(id);openForm({id:"asm_type",title:t?"Edit "+t.n:"New assessment type",story:t?"Name, purpose and who may answer.":"Starts with one question. Add the rest in the builder.",submit:t?"Save":"Create",defaults:t?{n:t.n,desc:t.desc,sme:t.sme,kind:t.kind}:{n:"",desc:"",sme:[],kind:"Custom"},fields:[{k:"n",label:"Name",type:"text",req:true},{k:"desc",label:"What it decides",type:"longtext"},{k:"sme",label:"Default experts",type:"people",multi:true}],onSubmit:v=>{if(t){Object.assign(t,{n:v.n,desc:v.desc,sme:v.sme||[]});audit("edited assessment type",t.n)}else{const nt={id:"asm_"+uid(),n:v.n,kind:"Custom",desc:v.desc,pass:60,bands:BANDS_STD.map(b=>b.slice()),std:"",sme:v.sme||[],q:[qYN("q1","Is this ready to go ahead?",1)]};AS.types.push(nt);AS.type=nt.id;AS.tab="bld";audit("created assessment type",nt.n)}render();return{toast:"Saved"}}})}
function dupType(id){const t=aType(id),c=clone(t);c.id="asm_"+uid();c.n=t.n+" (copy)";AS.types.push(c);AS.type=c.id;audit("duplicated assessment type",t.n);toast("Duplicated. Edit the copy.","good");render()}
function bandsForm(id){const t=aType(id);openForm({id:"asm_bands",title:"Pass mark and bands: "+t.n,story:"Scores of this value and above fall in the band. The pass mark decides whether a required gate opens.",submit:"Save",defaults:{pass:t.pass,b1:t.bands[0][1],b2:t.bands[1][1],b3:t.bands[2][1]},fields:[{k:"pass",label:"Pass mark (0 to 100)",type:"number"},{k:"b1",label:"“"+t.bands[0][0]+"” starts at",type:"number"},{k:"b2",label:"“"+t.bands[1][0]+"” starts at",type:"number"},{k:"b3",label:"“"+t.bands[2][0]+"” starts at",type:"number"}],onSubmit:v=>{t.pass=Math.max(0,Math.min(100,+v.pass));t.bands[0][1]=+v.b1;t.bands[1][1]=+v.b2;t.bands[2][1]=+v.b3;t.bands[3][1]=0;AS.results.forEach(r=>r._h=null);_gen=null;audit("changed assessment scoring",t.n+" pass mark "+t.pass);render();return{toast:"Scoring updated. Existing results were re-scored."}}})}
