const tsp=(L,x,y,lh,cls,anchor)=>`<text class="${cls}" x="${x}" y="${y}" text-anchor="${anchor||"middle"}">${L.map((l,i)=>`<tspan x="${x}" dy="${i?lh:0}">${X(l)}</tspan>`).join("")}</text>`;
