 b.runs=mkRuns(b,[["R-5120","Oct 6 10:30","RB-031",24100,3800,"awaiting","52s",4],["R-5098","Oct 5 09:12","RB-018",22800,3500,"completed","47s"],["R-5071","Oct 3 09:10","RB-007",23400,3600,"completed","49s"],["R-5044","Oct 2 09:15","RB-012",21900,3300,"killed","12s",1,["Stopped by kill switch (level 2)"]]]);
