  fields:[{section:"Limits"},{k:"steps",label:"Maximum steps per run",type:"range",min:3,max:30},{k:"spend",label:"Spend cap per run ($)",type:"number",min:.05,step:.05},{k:"perDay",label:"Runs per day",type:"number",min:1},{k:"money",label:"Most money it may move",type:"money"},{k:"hours",label:"Allowed hours",type:"select",opts:["24 hours a day","Business hours","Weekdays only"]},{section:"Protections"},{k:"pii",label:"Redact personal data in prompts and outputs",type:"toggle"},{k:"cite",label:"Block answers that cite no source",type:"toggle"},{k:"ext",label:"Allow calls to external domains",type:"toggle"},{k:"writes",label:"Writes always need approval",type:"toggle"},{k:"conf",label:"Escalate to a person under this confidence",type:"range",min:40,max:95,unit:"%"},{section:"People"},{k:"reviewers",label:"Reviewers",type:"people",multi:true,req:true}],
