F.qsel=F.qsel||[];F.retry=F.retry||{max:5,base:30,jitter:true,keep:14};
const cn=id=>F.conns.find(c=>c.id===id);
const hst={healthy:["Healthy","good"],degraded:["Degraded","warn"],failing:["Failing","bad"],paused:["Paused","mute"]};
const attn=()=>F.conns.filter(c=>c.st==="degraded"||c.st==="failing");
function connCard(c){const[l,k]=hst[c.st];return `<article class="flw-cn glass ${c.st}" data-flw-conn="${c.id}" tabindex="0" role="button" aria-label="${X(c.n)}, ${l}"><div class="row sp"><div><b>${X(c.n)}</b><div class="muted small">${X(c.cat)}</div></div>${pill(l,k)}</div>
 <div class="flw-cnspark" aria-hidden="true">${spark(c.tr,220,34,col(c.st==="healthy"?"--good-f":c.st==="degraded"?"--warn-f":c.st==="failing"?"--bad-f":"--faint"))}</div>
 <dl class="flw-cnkv"><div><dt>Auth</dt><dd>${X(c.auth)}</dd></div><div><dt>Last sync</dt><dd>${X(c.last)}</dd></div><div><dt>Error rate</dt><dd class="num" data-role="metric">${c.err}%</dd></div></dl>
 <div class="flw-flows">${c.flows.map(f=>`<span class="flw-fl ${f[0]}" title="${f[0]==="in"?"Data into Oukala":"Data out of Oukala"}">${f[0]==="in"?"←":"→"} ${X(f[1])}</span>`).join("")}</div></article>`}
function connDrawer(c){const[l,k]=hst[c.st],q=F.dlq.filter(d=>d.c===c.id).length;
 openDrawer(`<div class="eyebrow">${X(c.cat)} connector</div><h3 style="margin:4px 0 8px">${X(c.n)} ${pill(l,k)}</h3>${c.note?`<p class="small ${c.st==="failing"?"":"muted"}" data-role="story">${X(c.note)}</p>`:""}
 <dl class="kv"><dt>Authentication</dt><dd>${X(c.auth)}</dd><dt>Scopes</dt><dd class="mono small">${X(c.scopes||"none recorded")}</dd><dt>Schedule</dt><dd>${X(c.sched)}</dd><dt>Last sync</dt><dd>${X(c.last)}</dd><dt>Error rate</dt><dd class="num" data-role="metric">${c.err}% of ${c.calls.toLocaleString()} calls, 24 h</dd><dt>Latency</dt><dd class="num" data-role="metric">${c.lat?c.lat+" ms median":"No calls"}</dd><dt>Rate limit</dt><dd>${c.rl[0].toLocaleString()} of ${c.rl[1].toLocaleString()} ${X(c.rl[2])}</dd><dt>Dead letters</dt><dd>${q}</dd><dt>Owner</dt><dd>${X(c.owner)}</dd></dl>
 <div class="eyebrow" style="margin:12px 0 6px">Data flows</div><div class="flw-flows">${c.flows.map(f=>`<span class="flw-fl ${f[0]}">${f[0]==="in"?"← into Oukala":"→ out of Oukala"}: ${X(f[1])}</span>`).join("")}</div>
 <div class="row" style="margin-top:16px"><button class="btn primary" data-flw-ctest="${c.id}">Test connection</button><button class="btn" data-flw-csync="${c.id}">Sync now</button><button class="btn" data-flw-crot="${c.id}">Rotate credential</button><button class="btn" data-flw-cpause="${c.id}">${c.st==="paused"?"Resume":"Pause"}</button>${q?`<button class="btn" data-flw-cdlq="${c.id}">View ${q} dead letters</button>`:""}</div>`);audit("opened connector",c.n)}
function rotForm(c){openForm({id:"flw_rot",title:"Rotate credential for "+c.n,story:"Installs the new secret in Azure Key Vault, retires the old one after a 24-hour overlap and re-tests the connection. Nothing is shown again after you save.",submit:"Install and test",defaults:{kind:/certificate/i.test(c.auth)?"cert":/token/i.test(c.auth)?"pat":"secret",until:"2027-10-05"},fields:[{k:"kind",label:"Credential type",type:"chips",opts:[["cert","Certificate"],["secret","Client secret"],["pat","Access token"]]},{k:"file",label:"New certificate or secret file",type:"file",req:true,help:"A .pfx, .pem or .txt file. Stored in Key Vault."},{k:"until",label:"Valid until",type:"date",req:true},{k:"replay",label:"Replay this connector's dead letters afterwards",type:"toggle"}],
 onSubmit:v=>{const was=c.st;c.st="healthy";c.err=Math.min(c.err,.4);c.last="just now";c.note="";c.tr=c.tr.map(x=>Math.max(x,98));if(v.replay)F.dlq=F.dlq.filter(d=>d.c!==c.id);audit("rotated credential",c.n+(v.replay?" and replayed dead letters":""));render();return{toast:c.n+" reconnected"+(was==="failing"?". Calls succeed again.":".")+(v.replay?" Dead letters replayed.":"")}}})}
/* MCP */
const PERMS=[["allow","Allow"],["ask","Ask first"],["deny","Deny"]];
function mcpCard(s){const[l,k]=hst[s.st];return `<section class="card glass"><div class="cardhead"><div><h3>${X(s.n)}</h3><span class="muted small mono">${X(s.url)}</span></div><div class="row">${pill(s.tr,"mute")}${pill(l,k)}</div></div>
 <div class="row small" style="margin-bottom:10px"><span><b class="num" data-role="metric">${s.calls.toLocaleString()}</b> calls, 7 days</span><span><b class="num" data-role="metric">${s.p95} ms</b> p95</span><span><b class="num" data-role="metric">${s.err}%</b> errors</span><span class="muted">Auth: ${X(s.auth)}</span></div>
 <div class="tablewrap"><table class="flw-tbl"><thead><tr><th>Tool</th><th>Scope</th><th>Permission</th><th>Calls</th></tr></thead><tbody>${s.tools.map(t=>`<tr><td><b class="mono">${X(t.n)}</b><div class="muted small">${X(t.d)}</div></td><td>${pill(t.sc,t.sc==="admin"?"bad":t.sc==="write"?"warn":"mute")}</td><td><div class="flw-seg" role="radiogroup" aria-label="Permission for ${X(t.n)}">${PERMS.map(p=>`<button class="${p[0]}" role="radio" aria-checked="${t.p===p[0]}" data-flw-perm="${s.id}|${t.n}|${p[0]}">${p[1]}</button>`).join("")}</div></td><td class="num">${t.c.toLocaleString()}</td></tr>`).join("")}</tbody></table></div>
 <div class="eyebrow" style="margin:12px 0 6px">Resources</div><div class="row" style="gap:6px">${s.res.map(r=>`<span class="pill mute mono">${X(r)}</span>`).join("")}</div>
 <div class="eyebrow" style="margin:12px 0 6px">Agents allowed to call it</div><div class="row" style="gap:6px">${s.agents.map(a=>`<span class="pill info">${X(a)}</span>`).join("")}<button class="chip" data-flw-mcpagents="${s.id}">Edit access</button></div></section>`}
function mcpForm(){const tpl={search:["search","Search records the caller may read","read"],get:["get_item","Fetch one item by ID","read"],create:["create_item","Create an item","write"],delete:["delete_item","Delete an item","admin"]};openForm({id:"flw_mcp",title:"Register an MCP server",story:"The Model Context Protocol lets agents discover a server's tools and resources. Registering it here puts the server behind the AI gateway: nothing can call it until you grant an agent, and write or admin tools start at Ask first or Deny.",submit:"Register server",defaults:{tr:"Streamable HTTP",auth:"OAuth 2.1 with Entra ID",wp:"ask",agents:[]},
 fields:[{section:"Server"},{k:"n",label:"Server name",type:"text",req:true,ph:"contracts-mcp"},{k:"tr",label:"Transport",type:"chips",opts:["Streamable HTTP","stdio (local gateway)"]},{k:"url",label:"Endpoint or command",type:"text",req:true,ph:"https://mcp.meridian.example/contracts",ai:{label:"Suggest",fn:v=>"https://mcp.meridian.example/"+(v.n||"server").toLowerCase().replace(/[^a-z0-9]+/g,"-")}},{k:"auth",label:"Authentication",type:"select",opts:["OAuth 2.1 with Entra ID","OAuth client credentials","Personal access token","App-only certificate","None (local only)"]},
 {section:"Access"},{k:"wp",label:"Starting permission for write tools",type:"chips",opts:[["ask","Ask first"],["deny","Deny"]],help:"Admin tools always start at Deny."},{k:"agents",label:"Agents allowed to call it",type:"multi",opts:AGN}],
 onSubmit:v=>{F.mcps.push({id:"mcp_"+uid(),n:v.n,tr:v.tr,url:v.url,auth:v.auth,st:"healthy",agents:v.agents||[],calls:0,p95:0,err:0,tools:Object.values(tpl).map(t=>({n:t[0],d:t[1],sc:t[2],p:t[2]==="read"?"allow":t[2]==="admin"?"deny":v.wp||"ask",c:0})),res:["mcp://"+v.n+"/items/{id}"]});audit("registered MCP server",v.n+" "+v.tr);render();return{toast:v.n+" registered. Discovered 4 tools, 1 resource."}}})}
/* webhooks and keys */
function keyForm(){openForm({id:"flw_key",title:"Create an API key",story:"Keys act as a service account with only the scopes you pick. The full key is shown once. Oukala stores a hash, never the key.",submit:"Create key",defaults:{sc:["records:read"],rl:"60/min",exp:"90"},fields:[{k:"n",label:"Key name",type:"text",req:true,ph:"Finance dashboard refresher"},{k:"sc",label:"Scopes",type:"multi",opts:["records:read","records:write","metrics:read","tickets:write","approvals:read"],req:true},{k:"rl",label:"Rate limit",type:"chips",opts:["60/min","120/min","300/min"]},{k:"exp",label:"Expires after",type:"chips",opts:[["30","30 days"],["90","90 days"],["365","1 year"]]},{k:"ip",label:"Allowed IP range",type:"text",ph:"10.20.0.0/16 (optional)"},{k:"own",label:"Owner",type:"people",req:true}],
 onSubmit:v=>{const sec="okl_live_"+uid()+uid()+uid()+uid();F.keys.unshift({id:"k"+uid(),n:v.n,pre:sec.slice(0,13)+"…"+sec.slice(-4),sc:v.sc,made:"Oct 6",used:"never",exp:"in "+(v.exp||90)+" days",own:v.own,rl:v.rl||"60/min"});audit("created API key",v.n+" "+v.sc.join(","));render();openDrawer(`<div class="eyebrow">API key created</div><h3 style="margin:4px 0">${X(v.n)}</h3><p class="muted">Copy it now. It is shown once.</p><div class="formula mono" style="overflow-wrap:break-word">${sec}</div><div class="row" style="margin-top:12px"><button class="btn primary" onclick="navigator.clipboard&&navigator.clipboard.writeText('${sec}');toast('Copied','good')">Copy key</button><button class="btn quiet" popovertarget="drawer" popovertargetaction="hide">Done</button></div>`);return{close:false,toast:"Key created. Copy it now."}}})}
function hookForm(){openForm({id:"flw_hook",title:"Create a webhook",story:"Inbound webhooks give a system a signed URL to call. Outbound ones send Oukala events to a URL you control, retried with backoff and sent to the dead-letter queue when they keep failing.",submit:"Create webhook",defaults:{dir:"in",ev:"approval.decided",sig:"HMAC-SHA256",retry:"5 attempts, exponential"},fields:[{k:"n",label:"Name",type:"text",req:true,ph:"Contract signed to Planner"},{k:"dir",label:"Direction",type:"chips",opts:[["in","Inbound (they call us)"],["out","Outbound (we call them)"]]},{k:"ev",label:"Event",type:"select",opts:["approval.decided","invoice.held","incident.created","workflow.completed","agent.run.failed"]},{k:"url",label:"Target URL",type:"text",req:true,show:v=>v.dir==="out",ph:"https://example.com/hooks/oukala"},{k:"sig",label:"Signature",type:"select",opts:["HMAC-SHA256","mTLS","OAuth 2.0 bearer"]},{k:"retry",label:"Retry policy",type:"select",opts:["5 attempts, exponential","3 attempts, linear","No retries"],show:v=>v.dir==="out"}],
 onSubmit:v=>{F.hooks.push({id:"wh"+uid(),dir:v.dir||"in",n:v.n,url:v.dir==="out"?v.url:"https://hooks.oukala.example/in/"+uid()+"/"+uid(),ev:v.ev,sig:v.sig,last:"never",st:"healthy",ok:"-"});audit("created webhook",v.n);render()}})}
