F.map=null;
function mapInit(type,auto){const m=MAPS[type]||MAPS["Custom REST"];F.map={type,tgt:{}};if(auto)Object.entries(m.auto).forEach(([k,v])=>{F.map.tgt[k]=v[0]})}
function mapHTML(){const m=MAPS[F.map.type]||MAPS["Custom REST"],used=Object.values(F.map.tgt),pool=m.src.filter(s=>!used.includes(s)),miss=m.tgt.filter(t=>t[2]&&!F.map.tgt[t[0]]).length;
 const chip=s=>`<span class="flw-mchip" data-dnd-id="src:${X(s)}" tabindex="0">${grip}<span class="mono">${X(s)}</span></span>`;
 return `<div class="row sp"><div><div class="eyebrow" style="margin:0">Field mapping</div><div class="muted small">Drag a source field onto a target. Required targets are marked.</div></div><button type="button" class="aisug" data-flw-automap>${ico("sparkle")}Auto-map</button></div>
 <div class="flw-map"><div><div class="muted small" style="margin-bottom:6px">Source fields in ${X(F.map.type)}</div><div class="flw-pool" data-dnd="src" data-dnd-scope="flw_map">${pool.map(chip).join("")||'<span class="muted small">All source fields are mapped.</span>'}</div></div>
 <div class="flw-tg">${m.tgt.map(t=>`<div class="flw-trow"><span class="small"><b>${X(t[1])}</b>${t[2]?'<i class="flw-req" title="Required">*</i>':""}<br><span class="mono muted">${X(t[0])}</span></span><div class="flw-slot${F.map.tgt[t[0]]?" full":""}" data-dnd="tgt:${t[0]}" data-dnd-scope="flw_map">${F.map.tgt[t[0]]?chip(F.map.tgt[t[0]]):""}</div></div>`).join("")}</div></div>
 <div class="small ${miss?"":"muted"}" style="margin-top:8px">${miss?`<b style="color:var(--bad)">${miss} required target${miss>1?"s":""} still unmapped.</b>`:"All required targets are mapped."}</div>`}
function mapPaint(){const b=$q("[data-flw-mapbox]");if(b)b.innerHTML=mapHTML()}
DND.on("flw_map",(id,from,to)=>{const s=id.replace(/^src:/,"");if(!F.map)return;if(from.startsWith("tgt:"))delete F.map.tgt[from.slice(4)];if(to.startsWith("tgt:")){Object.keys(F.map.tgt).forEach(k=>{if(F.map.tgt[k]===s)delete F.map.tgt[k]});F.map.tgt[to.slice(4)]=s;toast(s+" → "+to.slice(4),"info")}mapPaint()});
