/* screen */
function hubStory(){const e=F.conns.find(c=>c.st==="failing");return `<b>${F.conns.length} connectors</b>: ${F.conns.filter(c=>c.st==="healthy").length} healthy, ${F.conns.filter(c=>c.st==="degraded").length} degraded, ${F.conns.filter(c=>c.st==="failing").length} failing, ${F.conns.filter(c=>c.st==="paused").length} paused. ${e?`<b>${X(e.n)}</b> has failed since its certificate expired, and <b>${F.dlq.filter(d=>d.c===e.id).length} events</b> wait in the dead-letter queue, including the Lumen payment hold.`:"Nothing is failing."}`}
function hubConnPane(){const ord={failing:0,degraded:1,healthy:2,paused:3};const L=F.conns.slice().sort((a,b)=>ord[a.st]-ord[b.st]).filter(c=>F.hubF==="All"||(F.hubF==="Needs attention"?c.st==="degraded"||c.st==="failing":F.hubF==="Healthy"?c.st==="healthy":c.st==="paused"));return `<div class="row">${["All","Needs attention","Healthy","Paused"].map(f=>`<button class="chip" data-flw-hubf="${f}" aria-pressed="${F.hubF===f}">${f}</button>`).join("")}</div><div class="grid g3">${L.map(connCard).join("")||empty("None here","Nothing matches this filter.")}</div>`}
function hubKeysPane(){return `${card("Webhooks","Inbound endpoints are signed; outbound ones retry with backoff",`<div class="tablewrap"><table class="flw-tbl"><thead><tr><th>Name</th><th>Direction</th><th>Event</th><th>Signature</th><th>Last delivery</th><th>Success</th><th>Status</th></tr></thead><tbody>${F.hooks.map(h=>`<tr><td><b>${X(h.n)}</b><div class="muted small mono">${X(h.url)}</div></td><td>${pill(h.dir==="in"?"Inbound":"Outbound","mute")}</td><td class="mono small">${X(h.ev)}</td><td class="small">${X(h.sig)}</td><td>${X(h.last)}</td><td class="num">${X(h.ok)}</td><td>${pill(hst[h.st][0],hst[h.st][1])}</td></tr>`).join("")}</tbody></table></div>`,`<button class="btn" data-flw-newhook>Create webhook</button>`)}
 ${card("API keys","Service accounts with only the scopes they need",`<div class="tablewrap"><table class="flw-tbl"><thead><tr><th>Name</th><th>Key</th><th>Scopes</th><th>Last used</th><th>Expires</th><th>Owner</th><th></th></tr></thead><tbody>${F.keys.map(k=>`<tr><td><b>${X(k.n)}</b><div class="muted small">Created ${X(k.made)} · ${X(k.rl)}</div></td><td class="mono small">${X(k.pre)}</td><td>${k.sc.map(s=>pill(s,"mute")).join(" ")}</td><td>${X(k.used)}</td><td>${X(k.exp)}${/Oct 20/.test(k.exp)?" "+pill("14 days","warn"):""}</td><td>${X(k.own)}</td><td><button class="chip" data-flw-krot="${k.id}">Rotate</button> <button class="chip" data-flw-krev="${k.id}">Revoke</button></td></tr>`).join("")}</tbody></table></div>`,`<button class="btn" data-flw-newkey>Create API key</button>`)}`}
function hubDlqPane(){const by={};F.dlq.forEach(d=>(by[d.c]=by[d.c]||[]).push(d));const r=F.retry;
 return `<div class="grid g2" style="align-items:start">${card("Rate limits","How close each connector runs to its limit",`${F.conns.filter(c=>c.st!=="paused").sort((a,b)=>b.rl[0]/b.rl[1]-a.rl[0]/a.rl[1]).slice(0,7).map(c=>{const p=Math.min(100,c.rl[0]/c.rl[1]*100),cl=p>=90?"bad":p>=70?"warn":"good";return `<div class="flw-wbar"><span class="small">${X(c.n)}</span><div class="flw-rl ${cl}"><i style="width:${p}%"></i></div><span class="num small">${Math.round(p)}%</span></div>`}).join("")}<p class="muted small" style="margin:8px 0 0">Oukala throttles itself at 80% of each vendor limit and honors Retry-After headers.</p>`)}
 ${card("Retry policy","What happens to a failed delivery",`<div class="flw-back">${[0,1,2,3,4].slice(0,r.max).map(i=>`<span class="pill info">${i?"then ":"first "}${(()=>{const s=r.base*Math.pow(i?4:1,i)*(i>2?1.5:1);return s<120?Math.round(s)+"s":s<7200?Math.round(s/60)+" min":Math.round(s/3600)+" h"})()}</span>`).join("")}<span class="pill bad">dead letter</span></div><p class="small" data-role="story" style="margin:10px 0">Up to <b>${r.max} attempts</b>, starting at ${r.base} seconds and growing about 4 times each step${r.jitter?", with ±20% jitter so retries do not stampede":""}. After the last attempt the event waits in the dead-letter queue for ${r.keep} days.</p><button class="btn" data-flw-retry>Edit retry policy</button>`)}</div>
 ${card("Dead-letter queue",`${F.dlq.length} events wait for a person`,F.dlq.length?`<div class="row" style="margin-bottom:10px"><button class="btn primary" data-flw-replay="sel" ${F.qsel.length?"":"disabled"}>Replay selected (${F.qsel.length})</button>${Object.keys(by).map(c=>`<button class="btn" data-flw-replay="c:${c}">Replay all ${X(cn(c).n)} (${by[c].length})</button>`).join("")}</div><div class="tablewrap"><table class="flw-tbl"><thead><tr><th></th><th>Event</th><th>Connector</th><th>Attempts</th><th>Error</th><th>Age</th><th></th></tr></thead><tbody>${F.dlq.map(d=>`<tr><td><button class="flw-chk" role="checkbox" aria-checked="${F.qsel.includes(d.id)}" aria-label="Select ${X(d.ev)}" data-flw-dsel2="${d.id}">${F.qsel.includes(d.id)?IC("M5 12l5 5 9-10"):""}</button></td><td><b class="mono small">${X(d.ev)}</b></td><td>${X(cn(d.c).n)}</td><td class="num">${d.att}/${r.max}</td><td class="small">${X(d.err)}</td><td>${X(d.age)}</td><td><button class="chip" data-flw-replay="${d.id}">Replay</button> <button class="chip" data-flw-dview="${d.id}">Payload</button></td></tr>`).join("")}</tbody></table></div>`:empty("Dead-letter queue is empty","Every failed delivery was replayed or discarded."),"")}`}
REG("flw_hub","Integration hub","automate","M12 12m-3 0a3 3 0 1 0 6 0 3 3 0 1 0-6 0M12 3v6M12 15v6M3 12h6M15 12h6M5.6 5.6l4.2 4.2M14.2 14.2l4.2 4.2",()=>{const bad=attn(),mc=F.mcps.reduce((s,x)=>s+x.tools.length,0);
 return `<div class="screen">${hero("Automation · Integration hub",`Every connection, healthy or not`,hubStory(),`<div class="row">${fchip("m_intfail")}<button class="btn primary" data-flw-newconn>Add connector</button><button class="btn" data-flw-newmcp>Register MCP server</button></div>`)}${lensNote()}
 ${tiles([TL("Connectors",F.conns.length,F.conns.filter(c=>c.st==="healthy").length+" healthy","good"),TL("Need attention",bad.length,bad.map(c=>c.n.split(" ")[0]).join(", ")||"none",bad.length?"bad":"good"),TL("Failure rate",METRICS.m_intfail.cur+"%","failed ÷ total calls, 24 h",mstat(METRICS.m_intfail)==="good"?"good":"warn"),TL("Dead letters",F.dlq.length,"waiting for replay",F.dlq.length?"warn":"good")])}
 ${views("flw_hub",["Connectors","MCP servers","Webhooks and keys","Retries and dead letters"],[hubConnPane(),`<div class="hint" style="display:block;background:var(--story-s);color:var(--story)"><b>${F.mcps.length} MCP servers, ${mc} tools.</b> Agents can only call a tool when the server allows the agent and the tool permission is Allow, or Ask first with a person approving. <button class="chip" data-flw-newmcp>Register a server</button></div>${F.mcps.map(mcpCard).join("")}`,hubKeysPane(),hubDlqPane()])}</div>`});
document.addEventListener("click",e=>{const t=e.target.closest("[data-flw-hubf],[data-flw-conn],[data-flw-ctest],[data-flw-csync],[data-flw-crot],[data-flw-cpause],[data-flw-cdlq],[data-flw-newconn],[data-flw-newmcp],[data-flw-perm],[data-flw-mcpagents],[data-flw-newkey],[data-flw-newhook],[data-flw-krot],[data-flw-krev],[data-flw-dsel2],[data-flw-replay],[data-flw-dview],[data-flw-retry],[data-flw-automap]");if(!t)return;const d=t.dataset;
 if(d.flwHubf){F.hubF=d.flwHubf;render();return}
 if(d.flwConn){connDrawer(cn(d.flwConn));return}
 if(d.flwCtest){const c=cn(d.flwCtest);if(c.st==="failing")toast(c.n+": 401 Unauthorized. "+c.note.split(".")[0]+".","bad");else if(c.st==="paused")toast(c.n+" is paused. Resume it first.","warn");else toast(c.n+": connected in "+c.lat+" ms"+(c.st==="degraded"?", but throttled (429) at the limit.":"."),c.st==="degraded"?"warn":"good");audit("tested connection",c.n);return}
 if(d.flwCsync){const c=cn(d.flwCsync);if(c.st==="failing"){toast("Sync not started: the credential is expired. Rotate it first.","bad");return}c.last="just now";audit("synced now",c.n);toast("Sync started for "+c.n+". "+Math.round(c.calls/60)+" records queued.","good");return}
 if(d.flwCrot){rotForm(cn(d.flwCrot));return}
 if(d.flwCpause){const c=cn(d.flwCpause);c.st=c.st==="paused"?"healthy":"paused";audit(c.st==="paused"?"paused connector":"resumed connector",c.n);toast(c.n+(c.st==="paused"?" paused. Events queue until you resume.":" resumed."),"info");closeDrawer();render();return}
 if(d.flwCdlq){F.hubF="All";S.v.flw_hub=3;closeDrawer();render();return}
 if(d.flwNewconn!==undefined){connForm();return}
 if(d.flwNewmcp!==undefined){mcpForm();return}
 if(d.flwPerm){const[sid,tn,p]=d.flwPerm.split("|"),s=F.mcps.find(x=>x.id===sid),tl=s.tools.find(x=>x.n===tn);let np=p;if(tl.sc==="admin"&&p==="allow"){np="ask";toast("Admin tools can only be Ask first or Deny. Set to Ask first.","warn")}else toast(tn+": "+PERMS.find(x=>x[0]===p)[1]+(p==="allow"&&tl.sc==="write"?". Agents will write without asking.":"."),p==="allow"&&tl.sc==="write"?"warn":"info");tl.p=np;audit("changed tool permission",s.n+"."+tn+" → "+np);render();return}
 if(d.flwMcpagents){const s=F.mcps.find(x=>x.id===d.flwMcpagents);openForm({id:"flw_mcpa",title:"Agents allowed on "+s.n,story:"Only the agents you tick can discover and call this server's tools. Everything else is refused by the AI gateway.",submit:"Save access",defaults:{agents:s.agents.slice()},fields:[{k:"agents",label:"Allowed agents",type:"multi",opts:AGN}],onSubmit:v=>{s.agents=v.agents||[];audit("changed MCP agent access",s.n+": "+s.agents.join(", "));render();return{toast:s.agents.length+" agent"+(s.agents.length===1?"":"s")+" allowed on "+s.n}}});return}
 if(d.flwNewkey!==undefined){keyForm();return}
 if(d.flwNewhook!==undefined){hookForm();return}
 if(d.flwKrot){const k=F.keys.find(x=>x.id===d.flwKrot);k.pre="okl_live_"+uid()+"…"+uid().slice(0,4);k.made="Oct 6";k.used="never";audit("rotated API key",k.n);toast("New key issued for "+k.n+". The old one works for 24 more hours.","good");render();return}
 if(d.flwKrev){const k=F.keys.find(x=>x.id===d.flwKrev);F.keys=F.keys.filter(x=>x!==k);audit("revoked API key",k.n);toast(k.n+" revoked. Callers get 401 now.","warn");render();return}
 if(d.flwDsel2){F.qsel=F.qsel.includes(d.flwDsel2)?F.qsel.filter(x=>x!==d.flwDsel2):F.qsel.concat(d.flwDsel2);render();return}
 if(d.flwReplay){const w=d.flwReplay;let items=w==="sel"?F.dlq.filter(x=>F.qsel.includes(x.id)):w.startsWith("c:")?F.dlq.filter(x=>x.c===w.slice(2)):F.dlq.filter(x=>x.id===w);let ok=0,bad=0;items.forEach(it=>{if(cn(it.c).st==="failing"||(cn(it.c).st==="degraded"&&it.err.startsWith("429")&&Math.random()<.5&&false)){it.att=Math.min(F.retry.max,it.att+1);it.age=it.age;bad++}else{F.dlq=F.dlq.filter(x=>x!==it);ok++}});F.qsel=F.qsel.filter(x=>F.dlq.some(q=>q.id===x));audit("replayed dead letters",ok+" delivered, "+bad+" failed again");toast(ok?`${ok} replayed and delivered.${bad?" "+bad+" failed again.":""}`:`${bad} failed again: the ERP certificate is still expired. Rotate it, then replay.`,ok?"good":"bad");render();return}
 if(d.flwDview){const q=F.dlq.find(x=>x.id===d.flwDview);openDrawer(`<div class="eyebrow">Dead letter · ${X(cn(q.c).n)}</div><h3 style="margin:4px 0">${X(q.ev)}</h3><p class="small" data-role="story">Failed ${q.att} times over ${q.age}. Last error: ${X(q.err)}</p><div class="eyebrow" style="margin:10px 0 6px">Payload</div><pre class="flw-pre">${X(JSON.stringify(q.body,null,2))}</pre><div class="row" style="margin-top:12px"><button class="btn primary" data-flw-replay="${q.id}">Replay</button><button class="btn danger" data-flw-ddisc="${q.id}">Discard</button></div>`);return}
 if(d.flwRetry!==undefined){openForm({id:"flw_retry",title:"Retry policy",story:"Applies to every outbound delivery and connector call that does not set its own policy.",submit:"Save policy",defaults:{max:F.retry.max,base:F.retry.base,jitter:F.retry.jitter,keep:F.retry.keep},fields:[{k:"max",label:"Maximum attempts",type:"range",min:1,max:5},{k:"base",label:"First retry after (seconds)",type:"number",min:5},{k:"jitter",label:"Add ±20% jitter",type:"toggle"},{k:"keep",label:"Keep dead letters (days)",type:"number",min:1}],onSubmit:v=>{Object.assign(F.retry,{max:+v.max,base:+v.base,jitter:!!v.jitter,keep:+v.keep});audit("changed retry policy",v.max+" attempts");render()}});return}
 if(d.flwAutomap!==undefined){const m=MAPS[F.map.type]||MAPS["Custom REST"];F.map.tgt={};Object.entries(m.auto).forEach(([k,v])=>F.map.tgt[k]=v[0]);mapPaint();const n=Object.keys(m.auto).length;const lo=Object.values(m.auto).filter(v=>v[1]<.85).length;toast(n?`Claude mapped ${n} fields.${lo?" "+lo+" under 85% confidence: check them.":""}`:"No known pattern for a custom REST source. Drag fields by hand.","info");audit("accepted AI suggestion","field mapping for "+F.map.type)}});
document.addEventListener("click",e=>{const t=e.target.closest("[data-flw-ddisc]");if(!t)return;F.dlq=F.dlq.filter(x=>x.id!==t.dataset.flwDdisc);audit("discarded dead letter",t.dataset.flwDdisc);toast("Discarded.","warn");closeDrawer();render()});
document.addEventListener("keydown",e=>{if((e.key==="Enter"||e.key===" ")&&e.target.matches&&e.target.matches("[data-flw-conn]")){e.preventDefault();e.target.click()}});
