new MutationObserver(ms=>ms.forEach(m=>m.addedNodes.forEach(n=>{if(n.classList&&n.classList.contains("dnd-ghost")){const dr=$q("#drawer");if(dr&&dr.matches(":popover-open")){n.setAttribute("popover","manual");try{n.showPopover()}catch(e){}}}}))).observe(document.body,{childList:true});
