PROC.reg("flw_design",{title:"How a workflow is made and kept",std:["bpmn","itil5"],steps:[{n:"Pick a trigger",d:"Event, schedule, record change, catalog request, email or API call.",who:"human",owner:"Process owner",sla:"1 d"},{n:"Draw the steps",d:"Human, agentic or deterministic. Drag, connect, set inputs and targets.",who:"human",owner:"Process owner"},{n:"Validate",d:"Unreachable steps, missing inputs and high-risk agents with no human are blocked.",who:"auto",owner:"Designer"},{n:"Test with a record",d:"A test record travels the graph and shows the data at each step.",who:"auto",owner:"Designer"},{n:"Approve to publish",d:"The workflow owner publishes. The old version stays in history.",who:"gate",owner:"Workflow owner"},{n:"Measure",d:"Cost, time and target met per step, every day.",who:"agent",owner:"Forecast Agent"}]});
PROC.reg("flw_appr",{title:"How an approval gets decided",std:["itil5","cobit"],steps:[{n:"Request raised",d:"From a workflow step, a catalog item or a form.",who:"human",owner:"Requester",sla:"instant"},{n:"Route to approvers",d:"By role and delegation of authority. Out of office cover applies.",who:"auto",owner:"Workflow engine",sla:"1 min"},{n:"Assessments run",d:"Required gates must pass. Advisory ones inform the approver.",who:"agent",owner:"Assessment owner",sla:"1 d"},{n:"AI recommends",d:"With sources. It never decides.",who:"agent",owner:"Claude Sonnet",sla:"1 min"},{n:"Approver decides",d:"Approve, approve with conditions, return, ask, reject or delegate.",who:"gate",owner:"Approver",sla:"24 h"},{n:"Audit and notify",d:"Decision, reason and overrides are written to the audit trail.",who:"auto",owner:"Workflow engine",sla:"instant"}]});
PROC.reg("flw_asmt",{title:"How an assessment is built, answered and used",std:["nist","iso27k"],steps:[{n:"Build the form",d:"Questions, weights, conditions and risk bands.",who:"human",owner:"Assessment owner"},{n:"Attach it",d:"To an approval type or a workflow step, as a required gate or advisory input.",who:"human",owner:"Process owner"},{n:"Assign experts",d:"People, AI agents, contractors or providers.",who:"auto",owner:"Workflow engine",sla:"instant"},{n:"AI prefills",d:"Drafts answers from documents on file. Experts confirm.",who:"agent",owner:"Claude Sonnet",sla:"5 min"},{n:"Expert answers",d:"The score is worked out live.",who:"human",owner:"Subject matter expert",sla:"3 d"},{n:"Gate or advise",d:"A gate blocks until it passes. Advice can be overridden with a reason.",who:"gate",owner:"Approver",sla:"24 h"}]});
if(typeof PROC.defs.flw_dmn==="undefined")PROC.reg("flw_dmn",{title:"How a decision table is made and used",std:["bpmn"],steps:[{n:"Name the decision",d:"What it decides and what the outputs mean.",who:"human",owner:"Process owner"},{n:"Add rules",d:"Rows of conditions and outputs, with a hit policy.",who:"human",owner:"Process owner"},{n:"Check coverage",d:"Gaps and overlaps are found before anyone relies on it.",who:"auto",owner:"Designer"},{n:"Test",d:"Enter values and see which row fires and why.",who:"human",owner:"Process owner"},{n:"Use in a workflow",d:"A decision step reads the table.",who:"auto",owner:"Workflow engine"}]});
