function gLegend(){return legend([...Object.values(FAMC).map(x=>[x[0],x[1]]),["Collapsed group, click to expand","--muted"],["Degraded or down (red ring)","--bad-f"]])}
function pathCard(){const g=I.g,P=g.path;const f=ciOf(g.focus);return `<div class="itom-pf"><div class="grid g2"><div class="itom-fld"><label class="muted small" for="itomPa">From</label><input class="fin" id="itomPa" data-itom-gq="a" value="${esc(P&&ciOf(P.a)?ciOf(P.a).name:f?f.name:"")}" autocomplete="off" placeholder="CI or service"><div class="itom-sgl" id="itomSgA" hidden></div></div><div class="itom-fld"><label class="muted small" for="itomPb">To</label><input class="fin" id="itomPb" data-itom-gq="b" value="${esc(P&&ciOf(P.b)?ciOf(P.b).name:"")}" autocomplete="off" placeholder="CI or service"><div class="itom-sgl" id="itomSgB" hidden></div></div></div><div class="row"><button class="btn primary" data-itom-a="findpath">Find shortest path</button>${g.view==="path"?`<button class="btn" data-itom-a="gback">Back to the neighborhood</button>`:""}<span class="muted small">Walks relationships in either direction and shows how the two are connected.</span></div>
 ${P&&P.list?`<div class="itom-pathl">${P.list.map((x,i)=>{const c=ciOf(x.id);return `${i?`<i class="itom-fa" title="${esc(x.e?(x.w==="in"?rtRv(x.e[2]):rtFw(x.e[2])):"")}">${esc(x.e?(x.w==="in"?rtRv(x.e[2]):rtFw(x.e[2])).toLowerCase():"")} →</i>`:""}<button class="chip" data-itom-a="${c&&c.isSvc?"svcopen":"open"}" data-itom-v="${esc(x.id)}">${famDot(c?c.cls:"cmdb_ci")}${esc(c?c.name:x.id)}</button>`}).join("")}</div><p class="story" data-role="story">${P.list.length-1} hop${P.list.length===2?"":"s"} connect <b>${esc((ciOf(P.a)||{}).name||"")}</b> and <b>${esc((ciOf(P.b)||{}).name||"")}</b>. A failure in either can travel along this chain.</p>`:P&&P.none?`<div class="itom-note">No path: these two are not connected by any relationship. If you expected one, add the missing relationship from either CI.</div>`:""}</div>`}
const WALK_PRE=[["Service to rack","svc_erp",[["down","service_offering"],["down","cmdb_ci_service_auto"],["down","cmdb_ci_appl"],["down","cmdb_ci_vm_instance"],["down","cmdb_ci_server"],["down","cmdb_ci_rack"]]],["Who depends on db-prod-02","ci_x_db2",[["up","cmdb_ci_appl"],["up","cmdb_ci_service_auto"],["up","service_offering"],["up","cmdb_ci_service_business"]]],["What a server connects to","ci_x_esx1",[["down","cmdb_ci_netgear"],["down","cmdb_ci_rack"],["down","cmdb_ci_datacenter"]]]];
function walkCard(){const g=I.g,w=g.walk,sets=walkSets(),st=ciOf(w.start);const text=[clsLabel(st?st.cls:"cmdb_ci")].concat(w.steps.map(s=>clsLabel(s.cls))).map(x=>snake(x)).join(".");
 const nx=nextOptions(sets[sets.length-1]).slice(0,10);const fin=sets[sets.length-1];const rows=[...fin].slice(0,300).map(id=>{const c=ciOf(id);return c?{id,t:c.name,sub:clsLabel(c.cls),tag:c.isSvc?c.tier:c.env,st:stCls(c.status),go:()=>c.isSvc?openSvc(id):ciDrawer(id)}:null}).filter(Boolean);
 return `<div class="itom-walk"><div class="row" role="group" aria-label="Presets"><span class="muted small">Try</span>${WALK_PRE.map((p,i)=>`<button class="chip" data-itom-wpre="${i}">${esc(p[0])}</button>`).join("")}<button class="btn quiet" data-itom-a="wstartfocus">Start from the graph focus</button></div>
 <div class="itom-wpath" aria-label="Dot-walk path"><button class="chip itom-ws" data-itom-wtrim="0">${famDot(st?st.cls:"cmdb_ci")}${esc(st?st.name:w.start)} <b class="num">1</b></button>${w.steps.map((s,i)=>`<i class="itom-fa" title="${s.dir==="up"?"Used by":"Depends on"}">${s.dir==="up"?"↑":"↓"}</i><button class="chip itom-ws ${sets[i+1]&&sets[i+1].size?"":"empty"}" data-itom-wtrim="${i+1}" title="Select to cut the walk back to this step">${esc(clsLabel(s.cls))} <b class="num" data-role="metric">${fmt((sets[i+1]||new Set()).size)}</b></button>`).join("")}</div>
 <form class="itom-wq" data-itom-wform><label class="muted small" for="itomWq">Path</label><input class="fin" id="itomWq" value="${esc(text)}" aria-label="Dot-walk path, classes separated by dots" spellcheck="false"><button class="btn" type="submit">Walk</button></form>
 <div class="muted small">Each name is a class. The walk follows relationships step by step and counts what it finds at every step. The arrow shows which way it went: down follows Depends on, up follows Used by.</div>
 ${nx.length?`<h4>Walk one step further</h4><div class="row">${nx.map(o=>`<button class="chip" data-itom-wnext="${o.dir}|${esc(o.cls)}">${o.dir==="up"?"↑":"↓"} ${esc(clsLabel(o.cls))} <b class="num">${fmt(o.n)}</b></button>`).join("")}</div>`:`<p class="muted small">Nothing further in this direction.</p>`}
 <h4>Result: ${fmt(fin.size)} ${w.steps.length?esc(clsLabel(w.steps[w.steps.length-1].cls).toLowerCase()):"item"}${fin.size===1?"":"s"}</h4>${lrHTML({id:"itom_walkr",groups:[{key:"r",label:"At the end of the path",rows}],limit:6,empty:"The walk found nothing. Cut it back by selecting an earlier step."})}
 <div class="row"><button class="btn primary" data-itom-a="wshow">Show this walk in the graph</button><button class="btn" data-itom-a="wback">Back to the neighborhood</button></div></div>`}
function gDeep(){return `${card("Path finder","How are two things connected? Pick any two CIs or services.",pathCard())}${card("Dot-walk query builder","Walk the model class by class, for example business service to offering to application service to application to virtual machine to server to rack, and see how many records exist at each step.",walkCard(),stdChip("csdm","The walk follows the CSDM chain from a business service through its offering and application service down to hardware and location."))}`}
function gList(){const V=GVW.V||build();const by=new Map();V.nodes.forEach(n=>{const k=n.more?"More":"Depth "+n.d;let a=by.get(k);if(!a)by.set(k,a=[]);a.push({id:n.id,t:n.name,sub:n.more?"Click to show "+n.ids.length+" items":clsLabel(n.cls),tag:n.svc?"service":n.st,st:stCls(n.st),go:()=>{if(n.more){I.g.exp[n.gk]=true;I.gseq++;gRebuild(true);return}I.g.sel=n.id;gPanel();gDraw(performance.now())}})});return[...by.entries()].map(([k,rows])=>({key:k,label:k===" Depth 0"?"Focus":k,rows}))}
function gHubList(){const hubs=gHubs();return `<div class="itom-hubl">${hubs.map(h=>{const c=ciOf(h.id);return `<button class="itom-hub" data-itom-a="gfocus" data-itom-v="${esc(h.id)}"><span>${famDot(c.cls)}<b>${esc(c.name)}</b><small>${esc(clsLabel(c.cls))}</small></span><span class="itom-hn"><b class="num" data-role="metric">${fmt(h.n)}</b><small>${h.s} services, ${h.t1} Tier 1</small></span></button>`}).join("")||empty("No dependencies yet","Add relationships to see blast radius.")}</div>`}
function graphScreen(){ensure();const h=health();I.gseq=I.gseq||1;if(GVW.seq!==I.gseq||!GVW.V||SCALE.on!==GVW.scale){GVW.V=build();GVW.seq=I.gseq;GVW.scale=SCALE.on;GVW.prev=new Map()}const V=GVW.V,g=I.g,f=ciOf(g.focus),imp=impactSum(g.focus);
 const story=`<b data-role="metric">${esc(f?f.name:"")}</b> sits in a graph of <b>${fmt(G_().cim.size+SVCREG.length)}</b> nodes and <b>${fmt(CIEDGE.length)}</b> relationships. ${g.mode==="causes"?`It relies on <b data-role="metric">${fmt(V.total)}</b> items within ${g.depth} steps`:`If it fails, <b data-role="metric">${fmt(V.total)}</b> items within ${g.depth} steps are affected`}, including <b>${imp.svcs.length}</b> business services (${imp.tier1} Tier 1) and up to <b>${fmt(imp.users)}</b> users. Only this neighborhood is drawn, so it stays fast: ${V.nodes.length} nodes in ${V.ms.toFixed(0)} ms.`;
 const extra=`<div class="row">${fchip("m_cmdb_corr")}${stdChip("csdm","Dependency views walk the CSDM service chain: business service, offering, application service, CIs.")}${stdChip("itil5","Impact analysis supports change enablement and incident prioritization: every incident, problem and change names a service and a CI and can open this view.")}<button class="btn primary" data-itom-a="impact" data-itom-v="${esc(g.focus)}">Impact analysis for the focus</button>${whyPop("Omar asked for the same living graph the knowledge vault has, for the CMDB: hover to light up neighbors, select to trace a path, double-click to walk.")}</div>`;
 const dash=`${card("Largest blast radius","CIs whose failure reaches the most business services, Tier 1 first. Select one to open it in the graph below.",gHubList())}`;
 const explorer=`<div class="itom-gx glass"><aside class="itom-gl" id="itomGraphTop">${gTop()}</aside><div class="itom-gc"><canvas id="itomCv" role="img" aria-label="Dependency graph of ${V.nodes.length} nodes around ${esc(f?f.name:"")}. Use the list below for a text version."></canvas><div class="itom-ctl"><div class="vx-seg"><button data-itom-a="gzoom" data-itom-v="1.3" aria-label="Zoom in">+</button><button data-itom-a="gzoom" data-itom-v="0.77" aria-label="Zoom out">−</button><button data-itom-a="gfit">Fit</button></div></div><div class="vx-tip" id="itomTip" hidden></div><div class="itom-leg">${gLegend()}</div></div><aside class="itom-gr" id="itomGPanel"></aside></div>`;
 return `<div class="screen">${hero("CMDB · dependency views","Walk the graph to find what breaks and what caused it",story,extra)}${lensNote()}<div id="itomGStats">${gStatHTML()}</div>${dash}${card("Explorer","Hover to light up neighbors, select to trace a path, double-click to refocus, drag to rearrange, scroll to zoom. Groups of similar nodes collapse into a dashed +N more circle.",explorer,`<span class="pill mute">${V.mode==="walk"?"Dot-walk":V.view==="path"?"Path":MODES[V.mode][0]}</span>`)}<div id="itomGraphDeep">${gDeep()}</div>${card("List view of this neighborhood","The same nodes as text, grouped by distance from the focus. Useful on a phone and with a screen reader.",lrHTML({id:"itom_glist",groups:gList(),limit:8}))}${procCard("itom_graph")}</div>`}

