const XFS=["as is","lowercase","capitalize","clean text","number","date","look up person","first group","1 Up, 2 Down, 3 Warning","0 Up, 1 Down, 2 Unreachable","number, 2 decimals"];
function xf(x,v){if(v===undefined||v===null)return"";v=String(v);switch(x){case"lowercase":return v.toLowerCase();case"capitalize":return v.charAt(0).toUpperCase()+v.slice(1).toLowerCase();case"clean text":return v.replace(/\s+/g," ").replace(/^Windows (\d+) Server$/,"Windows Server $1").trim();case"number":case"number, 2 decimals":return isNaN(+v)?"(not a number)":(x==="number"?String(+v):(+v).toFixed(2));case"date":return v.slice(0,10);case"look up person":{const p=DIR.find(d=>d.email===v||d.name.toLowerCase()===v.toLowerCase()||(d.email||"").split("@")[0]===v.split("@")[0]);return p?p.name:"(no match: "+v+")"}case"first group":return v.split(",")[0];case"1 Up, 2 Down, 3 Warning":return({1:"Operational",2:"Non-operational",3:"Degraded"})[v]||v;case"0 Up, 1 Down, 2 Unreachable":return({0:"Operational",1:"Non-operational",2:"Degraded"})[v]||v;default:return v}}
function rawRow(s,c){const a=c.a||{},h=hs(c.id);switch(s.id){
 case"orion":return{NodeID:1000+h%9000,Caption:c.name,IPAddress:c.ip,MachineType:a.os||"Windows 2022 Server",Vendor:a.manufacturer||"Dell",Status:c.status==="Operational"?1:c.status==="Degraded"?3:2,LastBoot:dayStr(8+h%40)+"T02:14:08",Availability30d:+c.uptime,AvgResponseTime:12+h%30,PercentLoss:0,SysName:String(c.name).toLowerCase()};
 case"nagios":return{host_name:c.name,address:c.ip,alias:c.name,current_state:c.status==="Operational"?0:1,hostgroups:(c.grp||"unassigned")+",linux-servers",last_check:dayStr(0)+" 13:2"+h%9,percent_state_change:+(h%30/10).toFixed(1)};
 case"azure":case"aws":return s.id==="azure"?{id:"/subscriptions/"+(a.subscription_id||"sub-100001")+"/resourceGroups/"+(a.resource_group||"rg-prod")+"/providers/Microsoft.Compute/virtualMachines/"+c.name,name:c.name,type:"microsoft.compute/virtualmachines",location:(a.region||"East US 2").toLowerCase().replace(/ /g,""),subscriptionId:a.subscription_id||"sub-100001",resourceGroup:a.resource_group||"rg-prod","tags.owner":c.owner||"","sku.name":a.instance_type||"Standard_D4s_v5","properties.hardwareProfile.vmSize":a.instance_type||"Standard_D4s_v5","properties.provisioningState":"Succeeded"}:{instanceId:"i-0"+(h%9e6+1e6),"tags.Name":c.name,privateIpAddress:c.ip,instanceType:"m5.large","state.name":"running","placement.availabilityZone":"us-east-1a"};
 case"intune":return{deviceName:c.name,serialNumber:a.serial_number||"SN"+(h%9e8+1e8),operatingSystem:"Windows",osVersion:"10.0.22631",userPrincipalName:((DIR.find(d=>d.name===c.owner)||{}).email)||"unknown@meridian.example",complianceState:"compliant",lastSyncDateTime:dayStr(0)+"T11:02:41Z",model:"Latitude 7440",manufacturer:"Dell"};
 case"vcenter":return{"vm.name":c.name,"vm.moid":"vm-"+(h%900+100),host:"esx-nor-0"+(1+h%2),cluster:"Norwalk-A",power_state:"POWERED_ON","guest.ipAddress":c.ip,"guest.guestFullName":a.os||"Microsoft Windows Server 2022","config.hardware.numCPU":a.cpu_count||4,"config.hardware.memoryMB":a.ram_mb||16384};
 case"snow":return{sys_id:(h.toString(16)+"a1b2c3d4e5f6").slice(0,32),name:c.name,sys_class_name:"cmdb_ci_"+(c.cls||"server").replace("cmdb_ci_",""),serial_number:a.serial_number||"",ip_address:c.ip,install_status:"1","owned_by.name":c.owner||"","support_group.name":c.grp||"",u_environment:String(c.env||"production").toLowerCase()};
 case"entra":return{id:"a1f2e3d4-"+(h%9e3+1e3),displayName:c.name,appId:"c0ffee00-"+(h%9e3+1e3),servicePrincipalType:"Application",accountEnabled:true,owners:[c.owner],"owners[0]":((DIR.find(d=>d.name===c.owner)||{}).email)||"",tags:["WindowsAzureActiveDirectoryIntegratedApp"]};
 case"csv":return{Name:c.name,Serial:a.serial_number||"",IP:c.ip,Owner:c.owner||"",Class:clsLabel(c.cls),Environment:String(c.env||"").toLowerCase(),Rack:a.rack||""};
 default:return{}}}
function sampleCIs(s){const l=CIREG.filter(c=>c.src===s.id&&!c.merged);return(l.length>=3?l:CIREG).slice(0,3)}
function mapTargets(s){const st=I.srcs[s.id];const cl=s.tcls||"cmdb_ci";const ats=attrsOf(cl).filter(a=>!["discovery_source","last_discovered","correlation_id"].includes(a.k)||a.k==="correlation_id").map(a=>({k:a.k,l:a.label,req:a.req}));if(s.up)ats.push({k:"uptime_30d",l:"Uptime, last 30 days",req:0});const have=new Set(ats.map(a=>a.k));st.map.forEach(m=>{if(!have.has(m.a)){ats.push({k:m.a,l:m.a,req:0});have.add(m.a)}});return ats}
const MAPHINT=[[/name|caption|host/i,"name"],[/ip|address/i,"ip_address"],[/serial/i,"serial_number"],[/vendor|manufacturer/i,"manufacturer"],[/os|machinetype|operatingsystem|guestfull/i,"os"],[/owner|user/i,"owned_by"],[/group/i,"support_group"],[/status|state/i,"operational_status"],[/avail|uptime/i,"uptime_30d"],[/env/i,"environment"],[/cpu/i,"cpu_count"],[/memory|ram/i,"ram_mb"],[/location|region/i,"region"],[/subscription/i,"subscription_id"],[/cluster/i,"cluster"]];
function mapPane(){const s=SRCM[I.ing.src]||SRC[0],st=I.srcs[s.id],tg=mapTargets(s);const mapped=new Set(st.map.map(m=>m.f)),pool=s.fields.filter(f=>!mapped.has(f));
 const slots=tg.map(t=>{const m=st.map.filter(x=>x.a===t.k);return `<div class="itom-slot"><div class="itom-sl"><b>${esc(t.l)}</b>${t.req?`<span class="pill bad">required</span>`:""}<small class="tok">${esc(t.k)}</small></div><div class="itom-sd ${m.length?"":"empty"}" data-dnd="slot:${esc(t.k)}" data-dnd-scope="itommap">${m.map(x=>`<div class="itom-mf" data-dnd-id="${esc(x.f)}" tabindex="0">${grip}<span>${esc(x.f)}</span><select class="fin itom-xs" data-itom-xf="${esc(x.f)}" aria-label="Transform for ${esc(x.f)}">${XFS.map(o=>`<option ${o===x.x?"selected":""}>${esc(o)}</option>`).join("")}</select></div>`).join("")||`<span class="muted small">Drop a source field here</span>`}</div></div>`}).join("");
 const rows=sampleCIs(s).map(c=>rawRow(s,c));const prev=rows.map(r=>`<div class="itom-pv"><div><div class="eyebrow">Source record</div><pre class="itom-code">${esc(JSON.stringify(r,null,1))}</pre></div><div><div class="eyebrow">Becomes</div><dl class="kv itom-kv">${st.map.map(m=>{const t=tg.find(z=>z.k===m.a);return `<dt>${esc(t?t.l:m.a)}</dt><dd>${esc(xf(m.x,r[m.f]))||`<span class="muted">empty</span>`}</dd>`}).join("")||`<dd class="muted">Nothing is mapped yet.</dd>`}</dl><div class="muted small">Ignored fields: ${s.fields.filter(f=>!mapped.has(f)).map(f=>esc(f)).join(", ")||"none"}</div></div></div>`).join("");
 return `<div class="row" role="group" aria-label="Source">${SRC.filter(x=>x.fields.length).map(x=>`<button class="chip" data-itom-isrc="${x.id}" aria-pressed="${x.id===s.id}"><i class="itom-dot" style="background:var(${x.c})"></i>${esc(x.s)}</button>`).join("")}</div>
 <p class="story" data-role="story">${esc(s.desc)} Drag a source field onto the CI attribute it should fill. The preview shows three real records after the mapping, with transforms applied.</p>
 <div class="itom-mapg"><div><h4>Source fields ${aiChip({model:"Claude Sonnet",conf:.86,title:"Auto-map suggestion",note:"Matches unmapped source fields to CI attributes by name and sample values. Nothing is saved until you drop or accept the field.",src:["Source field names","Three sample records","Class data model"],guards:["Only maps to attributes in the data model","Person lookups never create people"]})}</h4><div class="itom-pool" data-dnd="pool" data-dnd-scope="itommap">${pool.map(f=>`<div class="itom-mf" data-dnd-id="${esc(f)}" tabindex="0">${grip}<span>${esc(f)}</span></div>`).join("")||`<span class="muted small">Every source field is mapped.</span>`}</div><div class="row"><button class="btn" data-itom-a="automap">Auto-map with AI</button><button class="btn quiet" data-itom-a="newmap">Add a mapping</button></div></div><div><h4>CI attributes</h4><div class="itom-slots">${slots}</div></div></div><h4>Preview with three records</h4>${prev}`}
function runSource(id){const s=SRCM[id],st=I.srcs[id];if(!st||st.state==="Not connected"){toast(s.s+" is not connected. Connect it first.","warn");return}const r=RNG("run"+id+I.runs.length);const cis=CIREG.filter(c=>c.src===id&&!c.merged);let seen=0,created=0;
 cis.forEach(c=>{if(c.seen>60&&hs(c.id)%3!==0)return;if(c.seen>0){c.seen=0;seen++}});if(id==="azure"&&!I.ing.newVm){const nc=XC("ci_n_vm"+(++I.seq),"vm-new-lic-0"+(I.seq%9+1),"cmdb_ci_vm_instance","",{owner:"",src:"azure",crit:"",grp:"",class:"Virtual machine",seen:0,uptime:99.9});CIREG.push(nc);I.ing.newVm=nc.id;created=1}
 const found=Math.max(cis.length,3),up=Math.round(found*.03),rj=r()<.3?1+Math.floor(r()*3):0;const run={id:"R-"+(9040+I.runs.length+1),src:id,at:"Oct 6 "+T2(NOWH),dur:(6+Math.floor(r()*40))+" s",found,created,updated:up,same:found-created-up-rj,rej:rj,st:id==="vcenter"&&st.state==="Degraded"?"Partial":"Success"};I.runs.unshift(run);st.last=run;if(st.state==="Degraded"&&run.st==="Success")st.state="Healthy";
 for(let i=0;i<rj;i++)I.rej.unshift({id:"RJ-"+(2000+I.runs.length*3+i),src:id,at:run.at,raw:`{"name":"unknown-${Math.floor(r()*900)}"}`,reason:REJ_R[i%REJ_R.length][0],fix:REJ_R[i%REJ_R.length][1],st:"open"});
 bump();audit("ran source",s.s+": "+found+" found, "+created+" created, "+rj+" rejected");toast(s.s+" synced: "+found+" found, "+created+" new, "+up+" updated, "+rj+" rejected","good");if(created)toast("1 new CI has no owner or service. It will show as an orphan until someone links it.","info");render()}
function srcForm(id){const s=SRCM[id],st=I.srcs[id];OF({id:"itom_src",title:(st.state==="Not connected"?"Connect ":"Edit connection to ")+s.s,story:"Oukala stores the connection, tests it, then runs the first sync in read-only mode: it reads records and proposes changes, and nothing is written to the source. Credentials are held in the platform vault and never shown again.",submit:st.state==="Not connected"?"Connect and test":"Save connection",
 fields:[{section:"Connection"},{k:"url",label:"Address",type:"text",req:true,ph:"https://..."},{k:"user",label:"Service account or scope",type:"text",req:true},{k:"secret",label:"Secret or token",type:"text",ph:"Stored in the vault, never shown again",help:"Leave blank to keep the current secret."},{k:"mods",label:s.id==="orion"?"Orion modules":"Scope",type:"multi",opts:s.conn.modules},{section:"Schedule"},{k:"every",label:"How often",type:"select",opts:["Every 5 minutes","Every 10 minutes","Every 30 minutes","Every hour","Every 4 hours","Daily at 02:00","On demand"]},{k:"win",label:"Run window",type:"chips",opts:["Any time","Off hours only"]},{k:"onfail",label:"If a run fails",type:"chips",opts:["Retry then alert","Alert only","Pause the source"]}],
 defaults:{url:st.conn.url,user:st.conn.user,mods:st.conn.modules.slice(),every:st.every,win:st.win,onfail:st.onfail},
 liveH:v=>{const ok=/^https?:\/\//.test(v.url||"")||s.id==="csv"||s.id==="manual";return `<span class="pill ${ok?"good":"warn"}">${ok?"Address looks valid":"Address should start with https://"}</span> <span class="muted small">${s.id==="orion"?"Orion listens for SWIS requests on port 17774. The account needs read access to Orion.Nodes and Orion.APM.":"Test connection runs when you save."}</span>`},
 onSubmit:v=>{const was=st.state;st.conn={url:v.url,user:v.user,modules:v.mods||[]};st.every=v.every;st.win=v.win;st.onfail=v.onfail;st.state="Healthy";bump();audit(was==="Not connected"?"connected source":"edited source",s.s);setTimeout(()=>runSource(id),50);return{toast:s.s+" connection tested: authenticated, "+(s.fields.length)+" fields visible. First sync running."}}})}
function srcCards(){const h=health();return `<div class="itom-sgrid">${SRC.filter(s=>s.id!=="manual").map(s=>{const st=I.srcs[s.id],n=h.bySrc[s.id]||0,lr=st.last;return `<div class="itom-sc glass"><div class="row sp"><b><i class="itom-dot" style="background:var(${s.c})"></i>${esc(s.s)}</b><span class="pill ${stCls(st.state)}">${esc(st.state)}</span></div><div class="muted small">${esc(s.kind)}${s.up?" · brings uptime":""}</div><p class="small">${esc(s.desc)}</p><dl class="kv itom-kv"><dt>Schedule</dt><dd>${esc(st.every)}</dd><dt>CIs from it</dt><dd class="num" data-role="metric">${fmt(n)}</dd><dt>Last run</dt><dd>${lr?esc(lr.at)+" · "+lr.found+" found, "+lr.updated+" updated, "+lr.rej+" rejected":"Never"}</dd></dl><div class="row"><button class="btn ${st.state==="Not connected"?"primary":""}" data-itom-a="srcform" data-itom-v="${s.id}">${st.state==="Not connected"?"Connect":"Edit connection"}</button><button class="btn" data-itom-a="runsrc" data-itom-v="${s.id}" ${st.state==="Not connected"?"disabled":""}>Run now</button>${s.fields.length?`<button class="btn quiet" data-itom-isrc="${s.id}" data-itom-a="tomap">Mapping</button>`:""}</div></div>`}).join("")}</div>`}
function runsTable(){return btHTML({id:"itom_runs",h:340,rowH:42,key:"id",exportName:"sync-runs",rows:()=>I.runs,facets:["src","st"],cols:[{k:"id",label:"Run"},{k:"src",label:"Source",fmt:r=>esc(srcN(r.src)),val:r=>srcN(r.src)},{k:"at",label:"Started",val:r=>r.at},{k:"dur",label:"Duration"},{k:"found",label:"Found",fmt:r=>`<span class="num">${fmt(r.found)}</span>`,val:r=>r.found},{k:"created",label:"Created",val:r=>r.created},{k:"updated",label:"Updated",val:r=>r.updated},{k:"same",label:"Unchanged",val:r=>r.same},{k:"rej",label:"Rejected",fmt:r=>r.rej?`<span class="pill warn">${r.rej}</span>`:"0",val:r=>r.rej},{k:"st",label:"Result",fmt:r=>`<span class="pill ${stCls(r.st)}">${r.st}</span>`,val:r=>r.st}]})}
/* ---------- SolarWinds Orion uptime lab ---------- */
const SCN={normal:["A normal day","Every node answers; availability moves by hundredths."],switch:["Core switch outage","sw-core-nor-01 was down for 4 hours; hosts behind it lose availability."],erp:["ERP host reboot","esx-nor-01 rebooted for patching and the SQL application template reports degraded."]};
const LAB_CIS=["ci_x_esx1","ci_x_esx2","ci_x_sw1","ci_x_sw2","ci_fw","ci_sea0","ci_cod0","ci_x_db2","ci_x_nas"];
function labPayload(scn){ensure();const nodes=[],apps=[];LAB_CIS.forEach((id,i)=>{const c=CIREG.find(x=>x.id===id);if(!c)return;let av=+c.uptime,st=1,desc="Node status is Up.";const r=RNG("lab"+scn+id);
  if(scn==="normal")av=+(clamp(av+(r()-.45)*.08,98.5,100)).toFixed(2);else if(scn==="switch"){if(id==="ci_x_sw1"){av=99.43-0;av=+(av-.55).toFixed(2);st=2;desc="Node status is Down."}else if(id==="ci_x_esx1"||id==="ci_x_nas"){av=+(av-.22).toFixed(2);st=3;desc="Node status is Warning."}else av=+(clamp(av+(r()-.45)*.05,98.5,100)).toFixed(2)}else{if(id==="ci_x_esx1"){av=+(av-.31).toFixed(2);st=3;desc="Node status is Warning."}else if(id==="ci_x_db2"){av=+(av-.4).toFixed(2);st=3}else av=+(clamp(av+(r()-.45)*.05,98.5,100)).toFixed(2)}
  const o={NodeID:3100+i,Caption:i===5?c.name+".lumen.example":c.name,IPAddress:c.ip,Status:st,StatusDescription:desc,LastBoot:dayStr(scn==="erp"&&id==="ci_x_esx1"?0:12+i)+"T0"+(1+i%6)+":14:08",MachineType:(c.a&&c.a.os)||"Cisco IOS",Vendor:(c.a&&c.a.manufacturer)||"Cisco",Availability30d:av,AvgResponseTime:8+i*3,PercentLoss:st===2?100:st===3?2:0,_ci:id};nodes.push(o)});
 nodes.push({NodeID:3190,Caption:"nas-nor-02",IPAddress:"10.20.4.99",Status:1,StatusDescription:"Node status is Up.",LastBoot:"2026-09-20T03:00:12",MachineType:"NetApp Release 9",Vendor:"NetApp",Availability30d:99.97,AvgResponseTime:6,PercentLoss:0,_ci:null});
 const db=nodes.find(n=>n._ci==="ci_x_db2");if(db)apps.push({ApplicationID:77,Name:"Microsoft SQL Server - db-prod-02",NodeID:db.NodeID,Status:scn==="erp"?3:1,ApplicationAvailability:db.Availability30d,_ci:"ci_x_db2"});return{nodes,apps}}
const SWQL=`SELECT n.NodeID, n.Caption, n.IPAddress, n.Status, n.StatusDescription, n.LastBoot, n.MachineType, n.Vendor,
       AVG(r.Availability) AS Availability30d, AVG(r.AvgResponseTime) AS AvgResponseTime, AVG(r.PercentLoss) AS PercentLoss
FROM Orion.Nodes n
JOIN Orion.ResponseTimeHistory r ON r.NodeID = n.NodeID
WHERE r.DateTime > ADDDAY(-30, GETUTCDATE())
GROUP BY n.NodeID, n.Caption, n.IPAddress, n.Status, n.StatusDescription, n.LastBoot, n.MachineType, n.Vendor`;
function ingestOrion(){const scn=I.ing.scn,p=labPayload(scn);const base=[];const svcBefore={};const touched=new Set();const res=[],undo=[];
 p.nodes.forEach(n=>{let c=null,by="";c=CIREG.find(x=>x.ip&&x.ip===n.IPAddress&&!x.merged&&x.life!=="Retired");if(c)by="IPAddress";if(!c){const k=normName(n.Caption);c=CIREG.find(x=>!x.merged&&x.life!=="Retired"&&normName(x.name)===k);if(c)by="Caption"}
  if(!c){res.push({n,c:null,why:"No CI has this IP address or name"});I.rej.unshift({id:"RJ-"+(3000+I.rej.length),src:"orion",at:"Oct 6 "+T2(NOWH),raw:JSON.stringify({NodeID:n.NodeID,Caption:n.Caption,IPAddress:n.IPAddress}),reason:"No match: no CI has IP "+n.IPAddress+" or name "+n.Caption,fix:"Create the CI from this node, or add the identifier to an existing CI.",st:"open"});return}
  const old={u:+c.uptime,st:c.status,hist:c._hist?c._hist.slice():null,svc:c.svc};undo.push([c,old]);const before=c.svc?(svcBefore[c.svc]=svcBefore[c.svc]||svcDerived(c.svc)):null;
  c.uptime=n.Availability30d;c.usrc="orion";c.seen=0;c._hist=null;const ns=n.Status===1?"Operational":n.Status===3?"Degraded":"Non-operational";if(c.status!==ns&&c.status!=="Retired"){logChange(c,"operational_status",c.status,ns,"orion");c.status=ns}
  if(!c.src||c.src==="manual"){}touched.add(c.svc);res.push({n,c,by,old,nu:n.Availability30d})});
 const sres=[];touched.forEach(sid=>{const s=SVCREG.find(x=>x.id===sid);if(!s)return;const b=svcBefore[sid],a=svcDerived(sid);if(!b||!a)return;const d=a.avg-b.avg;const oldAv=s.avail;s.avail=+clamp(s.avail+d,90,100).toFixed(2);undo.push([s,{avail:oldAv}]);sres.push({s,from:oldAv,to:s.avail,d})});
 I.runs.unshift({id:"R-"+(9040+I.runs.length+1),src:"orion",at:"Oct 6 "+T2(NOWH),dur:"11 s",found:p.nodes.length,created:0,updated:res.filter(x=>x.c).length,same:0,rej:res.filter(x=>!x.c).length,st:"Success"});I.srcs.orion.last=I.runs[0];
 I.ing.last={scn,res,sres,undo,apps:p.apps};bump();health();audit("ingested Orion payload",SCN[scn][0]+": "+res.filter(x=>x.c).length+" CIs updated, "+sres.length+" services moved");toast("Ingested "+p.nodes.length+" Orion nodes: "+res.filter(x=>x.c).length+" matched, "+res.filter(x=>!x.c).length+" rejected, "+sres.length+" service availabilities updated","good");render()}
function undoIngest(){const L=I.ing.last;if(!L)return;L.undo.forEach(([o,old])=>{Object.keys(old).forEach(k=>{if(k==="u")o.uptime=old.u;else if(k==="st")o.status=old.st;else if(k==="hist")o._hist=old.hist;else if(k==="avail")o.avail=old.avail})});I.ing.last=null;bump();audit("undid Orion ingest","restored uptime and service availability");toast("Restored the values from before the ingest","info");render()}
function labPane(){const scn=I.ing.scn,p=labPayload(scn),L=I.ing.last,st=I.srcs.orion;const json=JSON.stringify({results:p.nodes.map(n=>{const o={...n};delete o._ci;return o}),applications:p.apps.map(a=>{const o={...a};delete o._ci;return o})},null,1);
 const resT=L?`<div class="itom-lr"><h4>What changed</h4>${tbl(["Orion node","Matched CI","Matched by","Uptime before","After","Status"],L.res.map(x=>x.c?`<tr><td>${esc(x.n.Caption)}</td><td>${ciBtn(x.c.id)}</td><td>${esc(x.by)}</td><td class="num">${x.old.u.toFixed(2)}%</td><td class="num" data-role="metric">${x.nu.toFixed(2)}%</td><td><span class="pill ${stCls(x.c.status)}">${esc(x.c.status)}</span></td></tr>`:`<tr><td>${esc(x.n.Caption)}</td><td colspan="4"><span class="pill warn">Rejected</span> ${esc(x.why)}</td><td><button class="btn quiet" data-itom-a="mkfrom" data-itom-v="${esc(x.n.Caption)}|${esc(x.n.IPAddress)}">Create CI</button></td></tr>`),720)}
  <h4>Service availability fed from the CIs</h4>${L.sres.length?tbl(["Service","Before","After","Change","Target","Verdict"],L.sres.map(x=>`<tr><td>${esc(x.s.n)}</td><td class="num">${x.from.toFixed(2)}%</td><td class="num" data-role="metric">${x.to.toFixed(2)}%</td><td class="num">${x.d>=0?"+":""}${x.d.toFixed(2)}</td><td class="num">${x.s.tgt}%</td><td><span class="pill ${x.to>=x.s.tgt?"good":"bad"}">${x.to>=x.s.tgt?"Meets target":"Below target"}</span></td></tr>`),720):`<p class="muted">No service availability changed.</p>`}
  <p class="muted small">Service availability moves by the change in the criticality-weighted average of its monitored CIs (mission critical counts 3, somewhat critical 2, others 1). That is the same value Service 360 and the SLA screens read.</p><div class="row"><button class="btn danger" data-itom-a="undoing">Undo this ingest</button><button class="btn" data-nav="svc_360">Open service portfolio</button></div></div>`:"";
 return `<div class="itom-lab"><div class="row" role="group" aria-label="Scenario">${Object.entries(SCN).map(([k,v])=>`<button class="chip" data-itom-scn="${k}" aria-pressed="${scn===k}" title="${esc(v[1])}">${esc(v[0])}</button>`).join("")}</div><p class="story" data-role="story">${esc(SCN[scn][1])} Oukala asks Orion for 30 day availability, matches each node to a CI, writes the uptime onto the CI and re-computes the availability of every service above it. This sandbox sends a sample payload shaped like a SolarWinds Information Service (SWIS) query result.</p>
 <div class="grid g2 itom-g2"><div><div class="row sp"><h4>1. Query sent to Orion</h4><span class="pill ${stCls(st.state)}">${esc(st.state)}</span></div><pre class="itom-code">${esc(SWQL)}</pre><dl class="kv itom-kv"><dt>Endpoint</dt><dd class="tok">${esc(st.conn.url)}</dd><dt>Modules</dt><dd>${esc(st.conn.modules.join(", "))}</dd><dt>Matching</dt><dd>IPAddress first, then Caption. Both are identifiers for class Computer.</dd><dt>Precedence</dt><dd>Orion owns uptime_30d and operational_status.</dd></dl></div>
 <div><h4>2. Payload received (${p.nodes.length} nodes, ${p.apps.length} application)</h4><pre class="itom-code itom-json">${esc(json)}</pre></div></div>
 <div class="row"><button class="btn primary" data-itom-a="ingest">3. Ingest this payload</button><button class="btn" data-itom-a="srcform" data-itom-v="orion">Edit the Orion connection</button><span class="muted small">Availability is the 30 day average from Orion.ResponseTimeHistory.</span></div>${resT}</div>`}
/* ---------- reconciliation ---------- */
function mergeForm(pairId){const P=HB.dupPairs.find(p=>p.id===pairId);if(!P){toast("That candidate is no longer a duplicate","info");return}const a=P.a,b=P.b;const fields=[["owned_by","Owner","owner"],["support_group","Support group","grp"],["business_criticality","Criticality","crit"],["ip_address","IP address","ip"],["lifecycle_stage","Lifecycle stage","life"]];
 const diff=fields.filter(f=>(a[f[2]]||"")!==(b[f[2]]||""));const ff=[{k:"surv",label:"Keep this record",type:"chips",opts:[[a.id,a.name+" ("+srcN(a.src)+")"],[b.id,b.name+" ("+srcN(b.src)+")"]],req:true}];
 diff.forEach(f=>ff.push({k:"f_"+f[0],label:f[1]+" comes from",type:"chips",opts:[["a",a[f[2]]||"(empty)"],["b",b[f[2]]||"(empty)"]]}));
 OF({id:"itom_merge",title:"Merge duplicate CIs",story:"The kept record survives with its ID. Every relationship and linked record of the other one moves to it, the other becomes Retired with a pointer, and for each differing field you choose which value wins (or leave the default: the source that ranks higher in precedence).",submit:"Merge",fields:ff,defaults:Object.assign({surv:a.id},Object.fromEntries(diff.map(f=>["f_"+f[0],(a[f[2]]?"a":"b")]))),
 liveH:v=>{const s=v.surv===a.id?a:b,o=s===a?b:a;const mv=CIEDGE.filter(e=>e[0]===o.id||e[1]===o.id).length;return `<b>${esc(o.name)}</b> merges into <b>${esc(s.name)}</b>. ${mv} relationship${mv===1?"":"s"} move. Match score <b>${P.score}</b>: ${esc(P.why.join("; "))}.`},
 onSubmit:v=>{const s=v.surv===a.id?a:b,o=s===a?b:a;diff.forEach(f=>{const pick=v["f_"+f[0]]==="b"?(s===a?b:a):s===a?a:b;const src=v["f_"+f[0]]==="a"?a:b;const val=src[f[2]];if(val&&val!==s[f[2]]){logChange(s,f[0],s[f[2]],val,"person");s[f[2]]=val}});
  CIEDGE.forEach(e=>{if(e[0]===o.id)e[0]=s.id;if(e[1]===o.id)e[1]=s.id});for(let i=CIEDGE.length-1;i>=0;i--){const e=CIEDGE[i];if(e[0]===e[1]||CIEDGE.findIndex(x=>x[0]===e[0]&&x[1]===e[1]&&x[2]===e[2])!==i)CIEDGE.splice(i,1)}
  o.life="Retired";o.status="Retired";o.merged=s.id;logChange(o,"merged into","",s.name,"person");bump();health();audit("merged duplicate CIs",o.name+" into "+s.name);render();return{toast:"Merged "+o.name+" into "+s.name+". Correctness and compliance improved."}}})}
function dupTable(){return btHTML({id:"itom_dups",h:300,rowH:60,key:"id",exportName:"duplicate-candidates",rows:()=>{health();return HB.dupPairs},open:id=>mergeForm(id),cols:[{k:"a",label:"Keep (survivor)",fmt:r=>`<div class="itom-cell"><b>${esc(r.a.name)}</b><small>${esc(srcN(r.a.src))} · ${esc(r.a.id)}</small></div>`,val:r=>r.a.name},{k:"b",label:"Duplicate",fmt:r=>`<div class="itom-cell"><b>${esc(r.b.name)}</b><small>${esc(srcN(r.b.src))} · ${esc(r.b.id)}</small></div>`,val:r=>r.b.name},{k:"score",label:"Match score",fmt:r=>`<span class="pill ${r.score>=90?"bad":"warn"}">${r.score}</span>`,val:r=>r.score},{k:"why",label:"Why",fmt:r=>esc(r.why.join("; ")),val:r=>r.why.join("; "),wrap:true},{k:"x",label:"",fmt:r=>`<span class="row"><button class="btn primary" data-itom-merge="${esc(r.id)}">Merge</button><button class="btn quiet" data-itom-nodup="${esc(r.id)}">Not a duplicate</button></span>`,val:()=>""}]})}
function precPane(){return `<div class="itom-prec">${I.prec.map((p,i)=>`<div class="itom-pr"><div class="itom-pl"><b>${esc(p.a)}</b><small class="muted">first source wins</small></div><div class="itom-po" data-dnd="prec:${i}" data-dnd-scope="itomprec" data-dnd-dir="x">${p.o.map((s,j)=>`<div class="itom-pi" data-dnd-id="${esc(s)}" tabindex="0">${grip}<b class="num">${j+1}</b><i class="itom-dot" style="background:var(${srcCol(s)})"></i>${esc(srcN(s))}</div>`).join("")}</div></div>`).join("")}</div>`}
function idrTable(){return tbl(["Class","Identifier attributes (tried in order)","Kind","Partial payloads","Why"],I.idr.map((r,i)=>`<tr><td><b>${esc(clsLabel(r.cls))}</b></td><td>${r.ids.map(x=>`<span class="pill mute">${esc(x)}</span>`).join(" ")}</td><td>${r.dep?`<span class="pill info">Dependent</span>`:`<span class="pill good">Independent</span>`}</td><td>${r.partial?"Held and retried":"Rejected"}</td><td>${esc(r.note)}<div><button class="btn quiet" data-itom-idr="${i}">Edit</button></div></td></tr>`),820)}
function idrForm(i){const r=i==null?null:I.idr[i];OF({id:"itom_idr",title:r?"Edit identification rule":"New identification rule",story:"Identification decides whether an incoming record is a CI we already know or a new one. Independent classes are matched on their own attributes. Dependent classes (an application, a database instance) are matched together with the host they run on, so two apps with the same name on different hosts stay separate. Records that match nothing are created; records that match two or more are rejected for review.",submit:"Save rule",
 fields:[{k:"cls",label:"Class",type:"select",req:true,opts:CL.filter(c=>c.kind!=="rec").map(c=>[c.id,c.label])},{k:"ids",label:"Identifier attributes, in order",type:"text",req:true,ph:"serial_number, name + ip_address",help:"Separate alternatives with commas. Use + to combine attributes that must match together."},{k:"dep",label:"Dependent class",type:"toggle",help:"Identified together with the CI it runs on or is hosted on."},{k:"partial",label:"Hold partial payloads",type:"toggle",help:"Keep incomplete records for up to 90 days and retry when the missing identifier arrives."},{k:"note",label:"Why",type:"text"}],
 defaults:r?{cls:r.cls,ids:r.ids.join(", "),dep:!!r.dep,partial:!!r.partial,note:r.note}:{cls:"cmdb_ci_computer",partial:true},
 onSubmit:v=>{const o={cls:v.cls,ids:String(v.ids).split(",").map(x=>x.trim()).filter(Boolean),dep:v.dep?1:0,partial:v.partial?1:0,note:v.note||""};if(r)I.idr[i]=o;else I.idr.push(o);audit("saved identification rule",clsLabel(v.cls));render();return{toast:"Identification rule saved"}}})}
function rejTable(){return btHTML({id:"itom_rej",h:380,rowH:56,key:"id",exportName:"rejected-rows",rows:()=>I.rej,facets:["src","reason","st"],open:id=>rejForm(id),cols:[{k:"id",label:"Row"},{k:"src",label:"Source",fmt:r=>esc(srcN(r.src)),val:r=>srcN(r.src)},{k:"at",label:"When"},{k:"reason",label:"Why it was rejected",fmt:r=>`<div class="itom-cell"><b>${esc(r.reason)}</b><small class="tok">${esc(r.raw.slice(0,70))}</small></div>`,val:r=>r.reason,wrap:true},{k:"st",label:"State",fmt:r=>`<span class="pill ${r.st==="open"?"warn":r.st==="fixed"?"good":"mute"}">${esc(r.st)}</span>`,val:r=>r.st}]})}
function rejForm(id){const r=I.rej.find(x=>x.id===id);if(!r)return;OF({id:"itom_rej",title:"Rejected row "+r.id,story:"A rejected row never changes the CMDB. Fix the cause and retry, or ignore it so it stops counting against the source.",submit:"Apply",fields:[{k:"act",label:"What do you want to do",type:"chips",req:true,opts:[["retry","Fix and retry"],["create","Create a CI from it"],["ignore","Ignore this row"],["ignoreall","Ignore all rows with this reason"]]},{k:"val",label:"Corrected value",type:"text",show:v=>v.act==="retry",ph:"for example 10.20.30.4"}],defaults:{act:"retry"},
 liveH:()=>`<div><b>${esc(r.reason)}</b></div><pre class="itom-code">${esc(r.raw)}</pre><div class="muted small">Suggested fix: ${esc(r.fix)}</div>`,
 onSubmit:v=>{if(v.act==="ignoreall"){I.rej.forEach(x=>{if(x.reason===r.reason&&x.src===r.src)x.st="ignored"});audit("ignored rejected rows",r.reason);render();return{toast:"All matching rows ignored"}}if(v.act==="ignore"){r.st="ignored";audit("ignored rejected row",r.id);render();return{toast:"Row ignored"}}if(v.act==="create"){r.st="fixed";setTimeout(()=>ciForm(null,{name:(r.raw.match(/"(?:Caption|name)":"([^"]*)"/)||[])[1]||"",env:"Production"}),50);audit("creating CI from rejected row",r.id);return{toast:"Opening the new CI form"}}if(!v.val)return bad("Enter the corrected value.");r.st="fixed";audit("fixed rejected row",r.id+": "+v.val);render();return{toast:"Fixed and retried: the row was accepted on this run"}}})}
function ingestScreen(){ensure();seedIng();const h=health();const conn=SRC.filter(s=>s.id!=="manual"&&I.srcs[s.id].state!=="Not connected").length,tot=SRC.length-1;const rj=I.rej.filter(r=>r.st==="open").length,found=I.runs.filter(r=>r.at.startsWith("Oct 6")).reduce((a,r)=>a+r.found,0);const dp=h.dupPairs.length;
 const story=`<b data-role="metric">${conn}</b> of ${tot} sources are connected and feed <b>${f1(h.discPct)}%</b> of the CIs that can be discovered. Orion brings availability for <b data-role="metric">${fmt(h.upBySrc.orion?h.upBySrc.orion.n:0)}</b> CIs. Today ${fmt(found)} records were read, <b>${rj}</b> rows are rejected and waiting, and <b>${dp}</b> duplicate pair${dp===1?"":"s"} need a merge decision. Try the SolarWinds lab: it ingests a real-shaped payload and moves service availability.`;
 const extra=`<div class="row">${fchip("m_cmdb_disc")}${fchip("m_cmdb_uptime")}${stdChip("csdm","Sources write to CSDM classes through identification and reconciliation rules, the same engine pattern ServiceNow calls IRE.")}<button class="btn primary" data-itom-a="srcform" data-itom-v="orion">Connect or edit Orion</button><button class="btn" data-itom-a="csvup">Upload CSV</button>${whyPop("Discovery is how the CMDB stays true without people typing. Reconciliation is how it stays true when two tools disagree.")}</div>`;
 const stat=(l,v,s,cl)=>`<div class="stat ${cl||""}"><small>${l}</small><span class="num" data-role="metric">${v}</span><em>${s}</em></div>`;
 const statrow=`<div class="statrow">${stat("Sources connected",conn+" of "+tot,"degraded or not connected: "+(tot-conn+SRC.filter(s=>I.srcs[s.id].state==="Degraded").length))}${stat("Discovery coverage",f1(h.discPct)+"%","14 day freshness")}${stat("Read today",fmt(found),"records across all runs")}${stat("Rejected rows",rj,"waiting for a decision",rj?"crit":"")}${stat("Duplicate pairs",dp,"to merge",dp?"crit":"")}${stat("Monitored uptime",h.upAvg.toFixed(2)+"%",f1(h.upCov)+"% of CIs report")}</div>`;
 const t1=`${card("Sources","Connect a tool once, map its fields once, and it keeps the CMDB current.",srcCards())}${card("Recent runs","Every run reports what it found, created, updated, left alone and rejected.",runsTable())}`;
 const t2=card("SolarWinds Orion uptime lab","Ingest uptime and availability from SolarWinds Orion (NPM and SAM) and see it flow to CIs and services.",labPane(),`<span class="pill info">Sandbox</span>`);
 const t3=card("Field mapping","Source field to CI attribute, with preview",mapPane(),`<span class="muted small">${esc((SRCM[I.ing.src]||SRC[0]).kind)}</span>`);
 const t4=`${card("Identification rules","How an incoming record is recognized as a CI we know. Independent classes match on their own attributes, dependent classes together with their host.",idrTable(),`<button class="btn" data-itom-idr="new">New rule</button>`)}${card("Source precedence per attribute","When two sources disagree, the one nearest the top wins. Drag a source to change its rank; the most recent value breaks ties inside a rank.",precPane(),`<span class="pill info">Drag to reorder</span>`)}${card("Duplicate candidates","Same name and IP seen from two sources. Merge keeps one record, moves the relationships and retires the other.",dupTable())}`;
 const t5=card("Rejected rows","Rows that identification or reconciliation refused. Nothing here has touched the CMDB.",rejTable(),`<span class="pill ${rj?"warn":"good"}">${rj} open</span>`);
 return `<div class="screen">${hero("CMDB · discovery and ingestion","Tools feed the CMDB; rules decide what is true",story,extra)}${lensNote()}${statrow}${views("itom_ing",["Sources and runs","SolarWinds uptime lab","Field mapping","Identification and reconciliation","Rejected rows"],[t1,t2,t3,t4,t5])}${procCard("itom_disc")}</div>`}

/* ================= CMDB HEALTH AND GOVERNANCE ================= */
const FSHORT={CR1:"No owner",CR2:"No support group",CR3:"Critical but unmonitored",CR4:"Stuck in planning",CR5:"Status and lifecycle disagree",stale:"Stale",orphan:"Orphan",duplicate:"Duplicate"};
const fShort=id=>FSHORT[id]||(/^RR/.test(id)?"Missing relationship ("+id+")":id);
const primaryF=c=>{const h=hh(c);return h.fails[0]||h.flags[0]||""};
function failRows(){ensure();health();return HB.act.filter(c=>c._h&&(c._h.flags.length||c._h.fails.length))}
function failTable(){return btHTML({id:"itom_fail",h:420,rowH:54,key:"id",exportName:"cmdb-findings",rows:failRows,facets:["cls","fnd","grp"],open:id=>ciDrawer(id),
 cols:[{k:"name",label:"Configuration item",fmt:r=>`<div class="itom-cell"><b>${esc(r.name)}</b><small>${esc(r.id)}</small></div>`,val:r=>r.name},{k:"cls",label:"Class",fmt:r=>`<span class="itom-cl">${famDot(r.cls)}${esc(clsLabel(r.cls))}</span>`,val:r=>clsLabel(r.cls)},
  {k:"fnd",label:"First finding",fmt:r=>`<span class="pill warn">${esc(fShort(primaryF(r)))}</span>${hh(r).flags.length+hh(r).fails.length>1?` <span class="muted small">+${hh(r).flags.length+hh(r).fails.length-1} more</span>`:""}`,val:r=>fShort(primaryF(r))},
  {k:"grp",label:"Support group",fmt:r=>r.grp?esc(r.grp):`<span class="pill warn">None</span>`,val:r=>r.grp||"None"},{k:"owner",label:"Owner",fmt:r=>ownerOf(r.owner),val:r=>r.owner||""},{k:"hs",label:"Health",fmt:r=>`<span class="pill ${hcls(hh(r).score)}">${Math.round(hh(r).score)}</span>`,val:r=>Math.round(hh(r).score)}]})}
function ruleTable(){const h=health();const rules=compRules();const rows=rules.map(r=>{const on=!crOff[r.id];const n=on?(h.fails[r.id]||0):"off";const app=HB.act.filter(c=>!r.appl||r.appl(c)).length;return `<tr><td><b>${r.id}</b></td><td><b>${esc(r.n)}</b><div class="muted small">${esc(r.why)}</div></td><td class="num">${fmt(app)}</td><td class="num" data-role="metric">${on?`<span class="pill ${n?"warn":"good"}">${fmt(n)}</span>`:`<span class="pill mute">off</span>`}</td><td><span class="row"><button class="chip" data-itom-a="rruleon" data-itom-v="${r.id}" aria-pressed="${on}">${on?"On":"Off"}</button>${on&&n?`<button class="btn" data-itom-task="${r.id}">Create task</button>`:""}</span></td></tr>`});
 return tbl(["Rule","What it checks","Applies to","Failing","Control"],rows,780)}
function pillarRow(){const h=health();const items=[["Completeness",h.comp,"m_cmdb_comp"],["Correctness",h.corr,"m_cmdb_corr"],["Compliance",h.compl,"m_cmdb_compl"]];return `<div class="itom-pill3">${items.map(x=>`<div class="itom-hc glass"><div class="row sp"><b>${x[0]}</b><span class="pill ${hcls(x[1])}" data-role="metric">${f1(x[1])}%</span></div>${hbar(x[1],100,hcls(x[1])==="good"?"--good-f":hcls(x[1])==="warn"?"--warn-f":"--bad-f")}${fchip(x[2])}</div>`).join("")}</div>`}
/* ---------- remediation tasks (drag between columns) ---------- */
const TCOLS=["Open","In progress","Done"];
function taskCard(t){return `<div class="itom-tk glass" data-dnd-id="${esc(t.id)}" tabindex="0">${grip}<div class="itom-tkb"><div class="row sp"><b class="num">${esc(t.id)}</b><span class="pill mute">${esc(t.rule)}</span></div><div>${esc(t.t)}</div><div class="muted small">${esc(t.grp)} · due ${esc(t.due)} · <b class="num">${fmt(t.n)}</b> CIs</div><div class="row"><button class="btn quiet" data-itom-a="taskcis" data-itom-v="${esc(t.id)}">Show CIs</button>${t.dem?`<span class="pill info">Demand raised</span>`:`<button class="btn quiet" data-itom-a="taskdemand" data-itom-v="${esc(t.id)}">Raise demand</button>`}</div></div></div>`}
function taskBoard(){seedTasks();return `<div class="itom-kb">${TCOLS.map(c=>{const l=I.tasks.filter(t=>t.st===c);return `<div class="itom-kc"><div class="row sp"><b>${c}</b><span class="pill mute num">${l.length}</span></div><div class="itom-kl" data-dnd="${c}" data-dnd-scope="itomtask">${l.map(taskCard).join("")||`<span class="muted small">Drop a task here</span>`}</div></div>`}).join("")}</div>`}
/* ---------- assign support groups by drag ---------- */
function grpBoard(){health();const un=HB.noGrp.filter(c=>!c.isSvc).slice(0,10);const done=Object.entries(I.grpDone||{}).slice(-12);const gs=GROUPS.slice(0,8);
 const it=c=>`<div class="itom-it" data-dnd-id="${esc(c.id)}" tabindex="0">${grip}<span><b>${esc(c.name)}</b><small class="muted"> ${esc(clsLabel(c.cls))}</small></span></div>`;
 return `<div class="itom-gb"><div class="itom-kc"><div class="row sp"><b>No support group</b><span class="pill warn num" data-role="metric">${fmt(HB.noGrp.length)}</span></div><div class="itom-kl" data-dnd="grp|" data-dnd-scope="itomgrp">${un.map(it).join("")||`<span class="muted small">Every CI has a group.</span>`}</div><p class="muted small">Showing the first ${un.length}. Drop a CI on a group to assign it.</p></div>
 <div class="itom-gz">${gs.map(g=>{const mine=done.filter(d=>d[1]===g).map(d=>ciOf(d[0])).filter(Boolean);const tm=TEAMS.find(t=>t.n===g);return `<div class="itom-kc"><div class="row sp"><b>${esc(g)}</b><span class="pill mute num">${fmt(HB.act.filter(c=>c.grp===g).length)}</span></div><div class="itom-kl itom-gzl" data-dnd="grp|${esc(g)}" data-dnd-scope="itomgrp">${mine.map(it).join("")||`<span class="muted small">Drop CIs here</span>`}</div>${tm?`<div class="muted small">Lead ${esc(tm.mgr)}</div>`:""}</div>`}).join("")}</div></div>`}
/* ---------- attestation ---------- */
function campCard(c){const own=campOwners(c.scope),att=own.filter(o=>c.att[o[0]]),pct=own.length?att.length/own.length*100:0,cis=own.reduce((a,o)=>a+o[1],0),done=att.reduce((a,o)=>a+o[1],0);
 return `<div class="itom-cmp glass"><div class="row sp"><div><b>${esc(c.n)}</b><div class="muted small">${esc(CAMP_SCOPES[c.scope][0])} · due ${esc(c.due)}</div></div><span class="pill ${pct>=100?"good":pct>=50?"info":"warn"}" data-role="metric">${att.length} of ${own.length} owners</span></div>${hbar(pct,100,pct>=100?"--good-f":"--accent")}<p class="muted small" data-role="story">${fmt(done)} of ${fmt(cis)} CIs attested. An owner attests by confirming "I still own these and the data is right"; anything unattested at the due date goes to the support group lead.</p>
 <div class="itom-own">${own.slice(0,12).map(o=>`<div class="itom-ow"><span>${pchip(o[0])} <span class="muted small">${o[1]} CIs</span></span>${c.att[o[0]]?`<span class="pill good">Attested</span>`:`<button class="btn quiet" data-itom-a="campatt" data-itom-v="${esc(c.id+"|"+o[0])}">Attest</button>`}</div>`).join("")}${own.length>12?`<div class="muted small">+${own.length-12} more owners</div>`:""}</div><div class="row"><button class="btn" data-itom-a="campremind" data-itom-v="${esc(c.id)}" ${pct>=100?"disabled":""}>Remind ${own.length-att.length} owners</button></div></div>`}
function campForm(){OF({id:"itom_camp",title:"New attestation campaign",story:"Asks every owner in the scope to confirm they still own their CIs and the data is right. Owners get a task; unattested CIs are reported to the support group lead on the due date. Attestation is how a CMDB stays true when nothing discovers it.",submit:"Start campaign",
 fields:[{k:"n",label:"Campaign name",type:"text",req:true,ph:"for example Q1 attestation: production CIs"},{k:"scope",label:"Scope",type:"select",req:true,opts:Object.entries(CAMP_SCOPES).map(([k,v])=>[k,v[0]])},{k:"due",label:"Due",type:"date",req:true}],defaults:{scope:"prod"},
 liveH:v=>{if(!v.scope)return"";const o=campOwners(v.scope),n=o.reduce((a,x)=>a+x[1],0);return `<b>${o.length}</b> owners will get a task covering <b>${fmt(n)}</b> CIs.`},
 onSubmit:v=>{seedCamps();const id="CAMP-"+(I.camps.length+1);const m=String(v.due).match(/^(\d{4})-(\d\d)-(\d\d)/);const due=m?["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"][+m[2]-1]+" "+(+m[3]):String(v.due);I.camps.unshift({id,n:v.n,scope:v.scope,due,st:"Open",att:{}});audit("started attestation campaign",v.n);render();return{toast:"Campaign started: "+campOwners(v.scope).length+" owners notified"}}})}
function lifeBars(){const cnt={};LIFE.forEach(l=>cnt[l]=0);CIREG.forEach(c=>{if(!c.merged&&!c.isSvc)cnt[c.life||"Operational"]=(cnt[c.life||"Operational"]||0)+1});const mx=Math.max(...Object.values(cnt),1);return `<div class="itom-hb">${LIFE.map(l=>`<div class="itom-hr"><span>${l}</span>${hbar(cnt[l],mx,l==="Retired"?"--muted":l==="Operational"?"--good-f":"--accent")}<b class="num" data-role="metric">${fmt(cnt[l])}</b></div>`).join("")}</div><p class="muted small">Planned, Build, Operational, Retiring, Retired are the CSDM lifecycle stages. Retired CIs stay in the table for audit but leave health scoring.</p>`}
function audTable(){seedGov();return btHTML({id:"itom_aud",h:400,rowH:46,key:"id",exportName:"cmdb-audit-trail",rows:()=>I.aud,facets:["kind","f"],cols:[{k:"t",label:"When"},{k:"who",label:"Who",fmt:r=>r.kind==="person"?pchip(r.who):esc(r.who),val:r=>r.who},{k:"kind",label:"By",fmt:r=>`<span class="pill ${r.kind==="person"?"info":"mute"}">${r.kind==="person"?"Person":"Tool"}</span>`,val:r=>r.kind==="person"?"Person":"Tool"},{k:"cn",label:"CI",fmt:r=>ciOf(r.ci)?ciBtn(r.ci,r.cn):esc(r.cn),val:r=>r.cn},{k:"f",label:"Field"},{k:"o",label:"From",val:r=>r.o},{k:"n",label:"To",val:r=>r.n}]})}
function healthScreen(){ensure();const h=health();seedTasks();seedCamps();seedGov();const open=I.tasks.filter(t=>t.st!=="Done").length;const att=I.camps.reduce((a,c)=>{const o=campOwners(c.scope);return[a[0]+o.filter(x=>c.att[x[0]]).length,a[1]+o.length]},[0,0]);
 const story=`Health is <b data-role="metric">${f1(h.score)}</b> (target 90). Completeness is ${f1(h.comp)}%, correctness ${f1(h.corr)}% and compliance ${f1(h.compl)}%. <b>${fmt(h.failSet)}</b> CIs fail at least one audit rule and ${fmt(failRows().length)} have a finding of some kind. ${open} remediation task${open===1?"":"s"} are open and ${att[0]} of ${att[1]} owners have attested in the current campaigns.`;
 const extra=`<div class="row">${fchip("m_cmdbhealth")}${fchip("m_cmdb_comp")}${fchip("m_cmdb_corr")}${fchip("m_cmdb_compl")}${stdChip("itil5","Configuration data that is complete, correct and compliant is what lets incident, problem and change practices trust the service map.")}<button class="btn primary" data-itom-a="newcamp">New attestation campaign</button>${whyPop("Discovery cannot know who is accountable. Attestation closes that gap: owners confirm, the platform keeps the proof.")}</div>`;
 const stat=(l,v,s,cl)=>`<div class="stat ${cl||""}"><small>${l}</small><span class="num" data-role="metric">${v}</span><em>${s}</em></div>`;
 const statrow=`<div class="statrow">${stat("Overall health",f1(h.score),"target 90",h.score<75?"crit":"")}${stat("Failing audit rules",fmt(h.failSet),"CIs with 1+ failure",h.failSet?"crit":"")}${stat("Open tasks",open,"of "+I.tasks.length+" remediation tasks")}${stat("Attested",att[0]+" of "+att[1],"owners in open campaigns")}${stat("Retired",fmt(CIREG.filter(c=>c.life==="Retired"&&!c.merged).length),"kept for audit")}</div>`;
 const t1=`${card("Three scores, one health number","Overall = 0.4 × Completeness + 0.3 × Correctness + 0.3 × Compliance",`${healthMeters()}<div class="formula">Health = 0.4 × ${f1(h.comp)} + 0.3 × ${f1(h.corr)} + 0.3 × ${f1(h.compl)} = <b>${f1(h.score)}</b></div>`,fchip("m_cmdbhealth"))}${card("Audit rules","Switch a rule off if it does not fit Meridian; the score recalculates at once. Relationship rules come from the data model.",ruleTable(),`<button class="btn" data-itom-a="newrule" data-itom-v="">New relationship rule</button>`)}${card("Findings","Every CI with a stale, orphan, duplicate or audit failure. Select a row to open it.",failTable(),`<span class="pill warn num">${fmt(failRows().length)}</span>`)}`;
 const t2=card("Remediation tasks","Drag a task between columns to change its state. Each task is generated from a rule or a finding and lists the CIs it covers.",taskBoard(),`<span class="pill info">Drag to move</span>`);
 const t3=card("Assign support groups by drag","Incidents route by support group. Drop a CI on the group that should run it.",grpBoard(),`<span class="pill info">Drag to assign</span>`);
 const t4=`${card("Attestation campaigns","Owners confirm they still own what the CMDB says they own.",`<div class="itom-camps">${I.camps.map(campCard).join("")}</div>`,`<button class="btn primary" data-itom-a="newcamp">New campaign</button>`)}`;
 const t5=`${card("Lifecycle stages","CIs by CSDM lifecycle stage",lifeBars())}${card("CI audit trail","Every field change, with who or which tool made it. Tools are tracked the same as people.",audTable())}`;
 return `<div class="screen">${hero("CMDB · health and governance","Trust the CMDB, then prove it",story,extra)}${lensNote()}${statrow}${views("itom_hl",["Scores and rules","Remediation tasks","Assign groups","Attestation","Lifecycle and audit"],[t1,t2,t3,t4,t5])}${procCard("itom_health")}</div>`}
/* ---------------- FinOps ---------------- */
const MON=["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct"],ACT=[66,70,74,77,80,84,88,96,105],BUD=100,FC=112;
const SVCS=[["SQL managed instance",31.2],["App Service",24.6],["Virtual machines",18.4],["Storage",9.8],["Log Analytics",7.9],["Front Door",6.1],["Defender for Cloud",4.3],["Other",2.7]];
const DEPT=[["Publishing",38.9,36],["IT Platform",23.9,22],["Finance",17.6,16],["Legal",9.8,9]];
const UNT=[["SQL managed instance",4.6,5],["App Service",3.2,4],["Virtual machines",3.4,6],["Storage",2.1,9],["Log Analytics",1.5,2]];
I.fin.rules=I.fin.rules||[{id:"CA1",n:"Log Analytics shared cost",svc:"Log Analytics",dept:"Split by usage",pr:1}];
const RECS=[["RS1","vm-idx02","Standard_D8s_v5 to Standard_D4s_v5","CPU p95 18%, memory p95 31% over 30 days",1.45,"Low",.91],["RS2","asp-cod-test","P2v3 to P1v3","Test plan peaks at 22% CPU",.62,"Low",.88],["RS3","stcontracts","Move 4 TB of untouched files to the Cool tier","No reads for 120 days on 4 TB",.9,"Low",.86],["RS4","vm-erp-app01, vm-erp-db01","Buy a 1-year reservation","Always on for 14 months",2.1,"Medium",.82],["RS5","law-meridian-prod","Move verbose tables to Basic logs","6 tables, no alert queries",1.9,"Low",.84],["RS6","lic-test-vm02","Delete idle VM (also retires its CI)","No CPU or network use for 71 days",.64,"Low",.96],["RS7","Dev subscription","Turn off Defender plans on dev resources","No production data",.9,"Low",.8],["RS8","afd-meridian-internal","Front Door Premium to Standard","No private link or WAF custom rules used",2.94,"Medium",.79]];
const DAILY=(()=>{const a=[];for(let i=0;i<30;i++){const wk=(i%7===5||i%7===6)?-.15:.1;a.push(Math.round((3.3+.12*Math.sin(i*.9)+wk+(i>=28?1.87:0))*100)/100)}return a})();
function untagged(){return UNT.reduce((a,u)=>a+u[1],0)*(I.fin.tagFixed?.38:1)}
function showback(){const rec=14.8-untagged(),dsum=DEPT.reduce((a,d)=>a+d[1],0);const rows=DEPT.map(d=>({n:d[0],dir:d[1],bud:d[2],fix:rec*d[1]/dsum,alloc:0}));let allocd=0;
 I.fin.rules.forEach(r=>{const u=UNT.find(x=>x[0]===r.svc);if(!u)return;const amt=u[1]*(I.fin.tagFixed?.38:1);allocd+=amt;if(r.dept==="Split by usage")rows.forEach(x=>x.alloc+=amt*x.dir/dsum);else{const t=rows.find(x=>x.n===r.dept);if(t)t.alloc+=amt}});
 rows.forEach(x=>x.tot=x.dir+x.fix+x.alloc);return {rows,unalloc:Math.max(0,untagged()-allocd),allocd}}
function wasteNow(){return RECS.filter(r=>!I.fin.accepted[r[0]]).reduce((a,r)=>a+r[4],0)}
function finScreen(){const sb=showback(),W=wasteNow(),tot=105,wp=Math.round(W/tot*1000)/10;METRICS.m_cloud_waste.cur=wp;const un=untagged(),cov=(1-un/tot)*100,real=RECS.filter(r=>I.fin.accepted[r[0]]).reduce((a,r)=>a+r[4],0);
 const mu=DAILY.slice(0,25).reduce((a,b)=>a+b,0)/25,sd=Math.sqrt(DAILY.slice(0,25).reduce((a,b)=>a+(b-mu)**2,0)/25);const hi=DAILY.map(()=>mu+2*sd),lo=DAILY.map(()=>mu-2*sd),pts=DAILY.map((v,i)=>v>mu+2*sd?{i,v,color:col("--bad-f"),t:"Anomaly: $"+v.toFixed(2)+"K"}:null).filter(Boolean);
 const dim=I.dims,rows=dim==="Service"?SVCS:dim==="Department"?DEPT.map(d=>[d[0],d[1]]).concat([["Untagged",un]]):[["Production",71.2],["Test",12.4],["Development",6.6],["Untagged",un]];
 const spend=card("Where the money goes","September actual by "+dim.toLowerCase()+", $"+tot.toFixed(1)+"K total",`<div class="row">${["Service","Department","Environment"].map(d=>`<button class="chip" data-itom-findim="${d}" aria-pressed="${dim===d}">${d}</button>`).join("")}</div><div class="itom-hb">${rows.map(r=>`<div class="itom-hr"><span>${r[0]}</span><div class="itom-ht"><i style="width:${Math.max(2,r[1]/Math.max(...rows.map(x=>x[1]))*100)}%;${r[0]==="Untagged"?"background:var(--warn-f)":""}"></i></div><b class="num" data-role="metric">${K1(r[1]*1000)}</b></div>`).join("")}</div>`);
 const budget=card("Budget against actual","Monthly Azure consumption, billed through the Northwind Cloud MSA (budget line B1, $1.2M a year)",bars({labels:MON,vals:ACT.concat([FC]),fc:[9],max:120,line:BUD,lineLabel:"Budget $100K",fmt:v=>"$"+Math.round(v)+"K",alt:"Monthly cloud spend against budget"})+`<div class="formula">Budget burn = Month actual ÷ Monthly budget = $105K ÷ $100K = 105%. October forecast $112K is 112%: ${K1(112000-100000)} over unless the SQL scale-up is reverted.</div>`,fchip("m_budgetburn"));
 const anom=card("Anomaly detection","Daily cost for 30 days. The band is the mean plus or minus 2 standard deviations of the first 25 days ($"+mu.toFixed(2)+"K ± $"+(2*sd).toFixed(2)+"K).",chart({labels:DAILY.map((_,i)=>i%5===0?"-"+(30-i)+"d":i===29?"today":""),max:6,min:0,fmt:v=>"$"+v.toFixed(0)+"K",ticks:3,band:{hi,lo},series:[{vals:DAILY,color:col("--accent"),nodot:true}],pts,alt:"Daily cloud cost with anomaly band"})+`<div class="itom-an"><b>${pts.length} anomalous days</b><span data-role="story">SQL managed instance was scaled from General Purpose 8 vCore to Business Critical 16 vCore on Oct 5 at 14:20 during INC1. It adds $1,870 a day, about $56K a month if left.</span><div class="row">${aiChip({model:"FinOps Agent",conf:.92,title:"Anomaly cause",src:["Azure Cost Management daily export","Resource activity log: scale operation by Sam Patel","INC1 timeline"],guards:["Read only"]})}<button class="btn primary" data-itom-revert ${I.fin.reverted?"disabled":""}>${I.fin.reverted?"Revert scheduled":"Schedule revert after INC1"}</button></div></div>`);
 const tagc=card("Untagged spend","Resources missing a required team or costcenter tag. Tag coverage = 1 − Untagged ÷ Total spend = "+cov.toFixed(1)+"%.",tbl(["Service","Untagged","Resources","Likely owner"],UNT.map(u=>`<tr style="cursor:default"><td><b>${u[0]}</b></td><td data-role="metric">${K1(u[1]*(I.fin.tagFixed?.38:1)*1000)}</td><td>${Math.max(1,Math.round(u[2]*(I.fin.tagFixed?.38:1)))}</td><td>${u[0].includes("SQL")?"Data team":u[0]==="Virtual machines"?"Finance systems":u[0]==="App Service"?"Platform team":"Shared"}</td></tr>`),460)+`<div class="itom-an"><span data-role="story">${I.fin.tagFixed?"Tag inheritance is on: 62% of the untagged resources now take their resource group's tags.":"Most untagged resources sit in resource groups that are tagged. Azure Policy can copy the tag down."}</span><div class="row"><button class="btn primary" data-itom-tagfix ${I.fin.tagFixed?"disabled":""}>${I.fin.tagFixed?"Policy applied":"Apply tag inheritance policy"}</button>${aiChip({model:"FinOps Agent",conf:.87,title:"Tag inheritance impact",src:["Resource group tags","Azure Policy: Inherit a tag from the resource group"],guards:["Policy modifies tags only, never resources"]})}</div></div>`);
 const show=card("Showback by department","Direct tagged cost, tag-fix recovery and shared allocation. Variance is against each department's share of the $100K budget.",tbl(["Department","Direct","Recovered by tag fix","Shared allocation","Total","Budget","Variance"],sb.rows.map(r=>`<tr style="cursor:default"><td><b>${r.n}</b></td><td>${K1(r.dir*1000)}</td><td>${K1(r.fix*1000)}</td><td>${K1(r.alloc*1000)}</td><td data-role="metric"><b>${K1(r.tot*1000)}</b></td><td>${K1(r.bud*1000)}</td><td><span class="pill ${r.tot>r.bud?"warn":"good"}">${r.tot>r.bud?"+":""}${((r.tot-r.bud)).toFixed(1)}K</span></td></tr>`).concat([`<tr style="cursor:default"><td><b>Unallocated</b></td><td colspan="3" class="muted">Cost no rule or tag can place yet</td><td data-role="metric"><b>${K1(sb.unalloc*1000)}</b></td><td>$17.0K shared pool</td><td></td></tr>`]),760),`<button class="btn primary" data-itom-newalloc>Add allocation rule</button>`);
 const rec=card("Rightsizing recommendations","AI proposals from 30 days of utilization. Accepting queues a change; nothing resizes without the change approval.",`<div class="itom-recs">${RECS.map(r=>`<div class="itom-rec ${I.fin.accepted[r[0]]?"acc":""}"><div><b>${r[1]}</b> <span class="pill ${r[5]==="Low"?"good":"warn"}">${r[5]} risk</span><div>${r[2]}</div><div class="muted small">${r[3]}</div></div><div class="row"><b class="num" data-role="metric">${K1(r[4]*1000)}/mo</b>${aiChip({model:"FinOps Agent",conf:r[6],title:"Why "+r[1],src:["Azure Advisor","Azure Monitor utilization (30 days)","Pricing sheet"],guards:["Needs change approval","Reversible"]})}<button class="btn ${I.fin.accepted[r[0]]?"":"primary"}" data-itom-acc="${r[0]}" ${I.fin.accepted[r[0]]?"disabled":""}>${I.fin.accepted[r[0]]?"Accepted":"Accept"}</button></div></div>`).join("")}</div><div class="formula">Waste share = Remaining recommended savings ÷ Monthly spend = ${K1(W*1000)} ÷ $105.0K = ${wp}%. Realized so far: ${K1(real*1000)} a month.</div><div class="row">${fchip("m_cloud_waste")}<span class="muted small">Target 8% or less.</span></div>`);
 return `<div class="screen">${hero("Cloud cost (FinOps)","Know who spends what, and stop paying for idle",`September Azure spend was <b data-role="metric">$105K</b> against a $100K budget (105%), and October is forecast at $112K because the SQL instance was scaled up during the portal incident. <b>${wp}%</b> of spend is recoverable waste.`,`<div class="row">${fchip("m_budgetburn")}${fchip("m_cloud_waste")}<button class="btn" data-itom-newalloc>Add allocation rule</button>${whyPop("Finance and IT Ops share this screen: it connects spend to the budget line and to the team that owns it.")}</div>`)}${lensNote()}${views("itom_fin",["Spend and budget","Untagged and showback","Rightsizing"],[`<div class="grid g2" style="align-items:start">${budget}${anom}</div>${spend}`,`<div class="grid g2" style="align-items:start">${tagc}${show}</div>`,rec])}${procCard("itom_fin")}</div>`}
function allocForm(){OF({id:"itom_alloc",title:"Cost allocation rule",story:"A rule places untagged cost on a department so showback is complete before tags are fixed. It never changes the bill, only who sees it.",submit:"Save rule",
 fields:[{k:"n",label:"Rule name",type:"text",req:true,ph:"e.g. Shared SQL cost"},{k:"svc",label:"Applies to untagged spend in",type:"select",req:true,opts:UNT.filter(u=>!I.fin.rules.some(r=>r.svc===u[0])).map(u=>u[0])},{k:"dept",label:"Allocate to",type:"chips",opts:["Publishing","IT Platform","Finance","Legal","Split by usage"],req:true},{k:"pr",label:"Priority",type:"number",min:1,help:"Lower numbers run first."}],defaults:{dept:"Split by usage",pr:2},
 liveH:v=>{const u=UNT.find(x=>x[0]===v.svc);if(!u)return "Every untagged service already has a rule.";const a=u[1]*(I.fin.tagFixed?.38:1);return `<b>Effect:</b> ${K1(a*1000)} a month moves from Unallocated to ${v.dept==="Split by usage"?"all departments in proportion to direct spend":v.dept||"the chosen department"}. Unallocated would drop from ${K1(showback().unalloc*1000)} to ${K1(Math.max(0,showback().unalloc-a)*1000)}.`},
 onSubmit:v=>{if(!UNT.find(x=>x[0]===v.svc))return bad("All untagged services already have a rule.");I.fin.rules.push({id:nextId("CA"),n:v.n,svc:v.svc,dept:v.dept,pr:+v.pr||2});render();return {toast:"Rule saved: "+v.n,audit:"added cost allocation rule "+v.n}}})}


/* ================= ACTIONS, FORMS, DRAG AND DROP, REGISTRATION ================= */
function impactFor(id){const c=ciOf(id);if(!c)return;if(typeof window.openImpact==="function"){try{window.openImpact(c.isSvc?{type:"service",id:c.id,service:c.name}:{type:"ci",id:c.id,ci:c.name});return}catch(e){}}
 toast("The shared impact map is not loaded here. Opening the dependency view instead.","info");setFocus(id)}
function curCanvas(){return S.screen==="itom_graph"&&document.getElementById("itomCv")}
function gUpdate(keep){if(curCanvas()){I.gseq=(I.gseq||1)+1;gRebuild(!!keep);gAll()}else render()}
function setFocus(id){if(!ciOf(id))return;const g=I.g;g.focus=id;g.view="explore";g.sel=null;g.exp={};g.walk.start=g.walk.start||id;I.gseq=(I.gseq||1)+1;audit("focused dependency view",ciOf(id).name);if(curCanvas()){closeDrawer();gRebuild(false);gAll()}else go("itom_graph")}
function retireForm(id){const c=ciOf(id);if(!c)return;const w=whatIf(id);OF({id:"itom_ret",title:"Retire "+esc(c.name),story:"Retiring takes the CI out of health scoring and out of new impact analyses. Its relationships stay for the audit trail. The what-if check says "+w.verdict[1],submit:"Retire the CI",
 fields:[{k:"why",label:"Reason",type:"select",req:true,opts:["Decommissioned","Replaced by another CI","Duplicate of another CI","Never existed (data error)","Moved to a vendor"]},{k:"ack",label:"I understand "+w.lonely.length+" dependents have no alternative",type:"toggle",show:()=>w.verdict[0]==="bad"},{k:"note",label:"Note for the audit trail",type:"text"}],defaults:{why:"Decommissioned"},
 onSubmit:v=>{if(w.verdict[0]==="bad"&&!v.ack)return bad("Confirm you understand the risk, or choose Back to the CI.");logChange(c,"lifecycle_stage",c.life,"Retired","person");c.life="Retired";c.status="Retired";bump();health();audit("retired CI",c.name+": "+v.why);closeDrawer();render();return{toast:c.name+" retired. Health and impact analyses updated.",close:false}}})}
function csvForm(){OF({id:"itom_csv",title:"Upload a CSV of CIs",story:"The file is read in your browser, matched with the identification rules and shown as a preview run. Rows that match nothing become new CIs, rows that match two CIs are rejected for review. Nothing is written to a source system.",submit:"Import",
 fields:[{k:"f",label:"CSV file",type:"file",help:"A header row, then one CI per row. Columns are mapped on the Field mapping tab."},{k:"cls",label:"Class of the rows",type:"select",req:true,opts:leafOpts()},{k:"mode",label:"When a row matches an existing CI",type:"chips",opts:["Update blank fields only","Overwrite by precedence","Skip"]}],defaults:{cls:"cmdb_ci_pc_hardware",mode:"Update blank fields only"},
 liveH:v=>`Import will create 5 CIs and reject 2 rows in this sample. The source ranks lowest in precedence, so it never overwrites Orion, Intune or ServiceNow values.`,
 onSubmit:v=>{const st=I.srcs.csv;st.state="Healthy";const n=5;for(let i=0;i<n;i++){const nc=XC("ci_csv"+(++I.seq),"csv-asset-"+(I.seq%90+10),v.cls,"",{owner:"",src:"csv",crit:"",grp:"",class:clsLabel(v.cls),seen:0,uptime:100});nc.usrc="none";CIREG.push(nc)}
  const run={id:"R-"+(9040+I.runs.length+1),src:"csv",at:"Oct 6 "+T2(NOWH),dur:"2 s",found:n+2,created:n,updated:0,same:0,rej:2,st:"Success"};I.runs.unshift(run);st.last=run;for(let i=0;i<2;i++)I.rej.unshift({id:"RJ-"+(4000+I.rej.length+i),src:"csv",at:run.at,raw:'{"Name":"row'+(i+7)+'","IP":"10.20.300.4"}',reason:REJ_R[5][0],fix:REJ_R[5][1],st:"open"});
  bump();health();audit("imported CSV",n+" CIs created, 2 rejected");render();return{toast:"Imported "+n+" CIs, rejected 2 rows. The new CIs have no owner yet."}}})}
function newMapForm(){const s=SRCM[I.ing.src],st=I.srcs[s.id];const mapped=new Set(st.map.map(m=>m.f)),pool=s.fields.filter(f=>!mapped.has(f));OF({id:"itom_map",title:"Add a field mapping for "+esc(s.s),story:"Pick the source field, the CI attribute it fills and how to transform it. The preview on the mapping tab updates at once.",submit:"Add mapping",
 fields:[{k:"f",label:"Source field",type:"select",req:true,opts:pool},{k:"a",label:"CI attribute",type:"select",req:true,opts:mapTargets(s).map(t=>[t.k,t.l])},{k:"x",label:"Transform",type:"select",opts:XFS}],defaults:{f:pool[0],x:"as is"},
 liveH:v=>{const c=sampleCIs(s)[0];if(!c||!v.f)return"";const r=rawRow(s,c);return `Example: <b>${esc(String(r[v.f]))}</b> becomes <b>${esc(xf(v.x||"as is",r[v.f]))||"empty"}</b>`},
 onSubmit:v=>{st.map=st.map.filter(m=>m.a!==v.a);st.map.push({f:v.f,a:v.a,x:v.x||"as is"});audit("added field mapping",s.s+": "+v.f+" to "+v.a);render();return{toast:"Mapped "+v.f+" to "+v.a}}})}
function autoMap(){const s=SRCM[I.ing.src],st=I.srcs[s.id];const tg=mapTargets(s);let n=0;s.fields.filter(f=>!st.map.some(m=>m.f===f)).forEach(f=>{const h=MAPHINT.find(x=>x[0].test(f));if(!h)return;const t=tg.find(x=>x.k===h[1]);if(!t||st.map.some(m=>m.a===t.k))return;st.map.push({f,a:t.k,x:"as is"});n++});audit("auto-mapped fields",s.s+": "+n+" suggestions accepted");toast(n?"Mapped "+n+" more fields. Check the preview.":"No further matches found","info");render()}
function saveViewForm(){OF({id:"itom_sv",title:"Save this view",story:"A saved view remembers the quick view and every facet and search term in the CI list. It is private to you; share it from the team views screen when it is useful to others.",submit:"Save view",fields:[{k:"n",label:"Name",type:"text",req:true,ph:"for example Production, no owner"}],
 onSubmit:v=>{const b=S.bt.itom_ci||{};const id="SV"+(++I.seq);I.saved.push({id,n:v.n,view:I.view,f:JSON.parse(JSON.stringify(b.f||{})),q:b.q||""});I.curSaved=id;audit("saved CI view",v.n);render();return{toast:"Saved view "+v.n}}})}
function applySaved(i){const v=I.saved[i];if(!v)return;clearFacets("itom_ci");I.view=v.view;Object.keys(v.f||{}).forEach(k=>setFacet("itom_ci",k,v.f[k]));S.bt.itom_ci=S.bt.itom_ci||{q:"",f:{}};S.bt.itom_ci.q=v.q||"";I.curSaved=v.id;render()}
function ensureTask(rule){seedTasks();let t=I.tasks.find(x=>x.rule===rule);if(t){if(t.st==="Done")t.st="Open";return t}health();const H=HB;let list=[],ttl="",grp="Ops team";if(/^(CR|RR)/.test(rule)){list=H.act.filter(c=>c._h.fails.includes(rule));const r=compRules().find(x=>x.id===rule);ttl="Fix "+list.length+" CIs failing: "+(r?r.n:rule)}else{list=rule==="stale"?H.stale:rule==="orphan"?H.orph:H.dupPairs.map(p=>p.b);ttl="Resolve "+list.length+" "+rule+" CIs"}
 t={id:"RT-"+(101+I.tasks.length),t:ttl,rule,n:list.length,ci:list.slice(0,300).map(c=>c.id),grp,due:"Oct 30",st:"Open",dem:false};I.tasks.push(t);return t}
function taskCIs(id){const t=I.tasks.find(x=>x.id===id);if(!t)return;const rows=t.ci.map(ciOf).filter(Boolean).slice(0,300).map(c=>({id:c.id,t:c.name,sub:clsLabel(c.cls)+" · "+(c.grp||"no group"),tag:c.env,st:stCls(c.status),go:()=>ciDrawer(c.id)}));openDrawer(`<div class="eyebrow">Remediation task ${esc(t.id)}</div><h2 class="itom-h2">${esc(t.t)}</h2><p class="muted">${esc(t.grp)} · due ${esc(t.due)} · ${fmt(t.n)} CIs${t.n>rows.length?", first "+rows.length+" shown":""}</p>${lrHTML({id:"itom_tc_"+id,groups:[{key:"c",label:"CIs in this task",rows}],limit:8,empty:"Nothing left to fix."})}`)}
