DND.on("itommap",(id,from,to)=>{const st=I.srcs[I.ing.src];if(!to||to===from)return render();if(to==="pool")st.map=st.map.filter(m=>m.f!==id);else if(/^slot:/.test(to)){const a=to.slice(5);st.map=st.map.filter(m=>m.f!==id&&m.a!==a);st.map.push({f:id,a,x:"as is"})}else return render();audit("mapped field",SRCM[I.ing.src].s+": "+id+" to "+to);toast(to==="pool"?id+" unmapped":id+" now fills "+to.slice(5),"good");render()});
DND.on("itomprec",(id,from,to,index)=>{const m=/^prec:(\d+)$/.exec(to||"");if(!m||from!==to)return render();const p=I.prec[+m[1]];const o=p.o.filter(x=>x!==id);o.splice(clamp(+index||0,0,o.length),0,id);p.o=o;audit("changed source precedence",p.a+": "+o.map(srcN).join(" > "));toast(srcN(id)+" now ranks "+(o.indexOf(id)+1)+" for "+p.a,"good");render()});
DND.on("itomtask",(id,from,to)=>{const t=I.tasks.find(x=>x.id===id);if(!t||!TCOLS.includes(to)||to===t.st)return render();t.st=to;audit("moved remediation task",id+" to "+to);toast(id+" is now "+to,"good");render()});
DND.on("itomgrp",(id,from,to)=>{const c=ciOf(id),m=/^grp\|(.+)$/.exec(to||"");if(!c||!m)return render();logChange(c,"support_group",c.grp,m[1],"person");c.grp=m[1];I.grpDone=I.grpDone||{};I.grpDone[id]=m[1];bump();health();audit("reassigned support group",c.name+" to "+m[1]);toast(c.name+" now belongs to "+m[1],"good");render()});
