function midecl(incId){const open=ALLI().filter(isOpen);openForm({id:"itsm_midecl",title:"Declare a major incident",story:"A major incident gets a war room: named roles, one bridge, a live timeline, and AI-drafted updates that a person approves. Declare when a Tier 1 service is down or degraded for many people.",submit:"Declare and open the war room",defaults:{inc:incId||"",ic:"Tom Becker"},
 fields:[{k:"inc",label:"Incident",type:"select",req:true,ph:"Choose an incident",opts:ALLI().filter(isOpen).slice(0,60).map(i=>[i.id,i.id+" "+i.t.slice(0,50)])},{k:"crit",label:"Criteria met",type:"multi",req:true,opts:["Tier 1 service affected","More than 100 users","No workaround","Data or security risk","Executive request"]},{k:"ic",label:"Incident commander",type:"people",req:true},{k:"sum",label:"What we know so far",type:"longtext",wide:true,ph:"Impact, since when, what is being tried",ai:{label:"Draft",fn:v=>{const i=INC(v.inc);return i?i.d:null}}}],
 onSubmit:v=>{const i=INC(v.inc);i.maj=true;X.mi=Object.assign(MI0(),{inc:v.inc,start:i.age,declared:0,restored:null,roles:{ic:v.ic,tech:"",comms:"",scribe:""},tl:[[i.age,"System","Alert",i.t],[0,v.ic,"Decision","Major incident declared. Criteria: "+v.crit.join(", ")+"."]],comms:[],comp:COMP0.map(c=>c.slice()),pub:COMP0.map(c=>c.slice()),pir:null});X.mi.comms.push({id:"C"+(X.seq.comm++),aud:"Executive team",chan:"Email",st:"Draft",at:"",by:"",ai:.82,body:draftBody("Executive team")});
  S.v.itsm_mi=0;done("Major incident declared",v.inc);go("itsm_mi");return {toast:"War room open. Assign the remaining roles by dragging people into them."}}})}
function miUpd(){openForm({id:"itsm_miup",title:"Add a timeline entry",story:"Every decision and finding goes on the timeline while it is fresh. The post-incident review is built from this record.",submit:"Add entry",defaults:{kind:"Update",who:X.mi.roles.scribe&&!!who(X.mi.roles.scribe)?X.mi.roles.scribe:X.mi.roles.ic},fields:[{k:"kind",label:"Kind",type:"chips",opts:["Update","Finding","Hypothesis","Decision","Action","Comms"]},{k:"who",label:"Who",type:"people",req:true},{k:"x",label:"What happened",type:"longtext",req:true,wide:true}],onSubmit:v=>{X.mi.tl.push([0,v.who,v.kind,v.x]);done("Timeline entry",v.kind+" · "+v.x.slice(0,40))}})}
