const wfIdOf=s=>{const id="wf_skill_"+s.id.toLowerCase().replace("-","");return window.WFX&&WFX.get&&WFX.get(id)?id:""};
const CHAT_OK=()=>!!(window.CHATX&&CHATX.tools);
function regWF(s){if(!(window.WFX&&WFX.reg))return;const id="wf_skill_"+s.id.toLowerCase().replace("-","");const sv=s.svc?svcName(s.svc):(itOf(s.kb)||{}).svcN||"Service desk";
 WFX.reg({id,name:"Agent skill: "+s.name,kind:"incident",service:sv,owner:s.owner,std:["kcs"],steps:[{id:"t",n:"Trigger from ticket or chat",type:"auto",owner:"Automatic",sla:"Instant",next:["a"]}].concat(s.steps.map((p,i)=>({id:"s"+i,n:p[0]||p.n,type:(p[2]||p.guard)==="Needs approval"?"gate":"agent",owner:(p[2]||p.guard)==="Needs approval"?(s.appr[0]||"Approver"):s.id,system:p[1]||p.tool,sla:"1 min",next:[i<s.steps.length-1?"s"+(i+1):"v"]}))).map((x,i,a)=>x.id==="t"?Object.assign(x,{next:["s0"]}):x).concat([{id:"v",n:"Verify and close, or escalate to a person",type:"human",owner:s.owner,sla:"1 working day",next:[]}])});}
function regChat(s){if(!CHAT_OK())return;const id="oukala.skill."+s.id.toLowerCase().replace("-","");const def={id,name:s.name,description:"Run the agent skill "+s.name+" (from "+s.kb+"). "+s.guards.join(". "),params:s.inputs.map(i=>({name:i[0],type:i[1],required:!!i[2]})),risk:s.risk,requiresApproval:s.risk!=="Low"||s.appr.length>0,run:args=>runSkill(s.id,"Chat",args)};
 try{if(Array.isArray(CHATX.tools)){const i=CHATX.tools.findIndex(t=>t.id===id);i>=0?CHATX.tools[i]=def:CHATX.tools.push(def)}else CHATX.tools[id]=def}catch(e){}}
function unregChat(s){if(!CHAT_OK())return;const id="oukala.skill."+s.id.toLowerCase().replace("-","");try{if(Array.isArray(CHATX.tools)){const i=CHATX.tools.findIndex(t=>t.id===id);if(i>=0)CHATX.tools.splice(i,1)}else delete CHATX.tools[id]}catch(e){}}
function syncReg(){skills().filter(s=>s.status==="Active").forEach(s=>{regWF(s);regChat(s)})}
function runSkill(id,by,args){const s=skOf(id);if(!s||s.status!=="Active")return {ok:false,msg:"Skill is not active"};const n=s.runs+1,x=hsh(id+"|"+n),okr=s.runs?s.ok/s.runs:.9;let o="Success";if(x>okr+(1-okr)*.65)o="Failed";else if(x>okr)o="Escalated";const why={Success:"Completed all steps in the sandbox",Escalated:"A guardrail asked for a person to take over",Failed:"A tool call timed out"}[o];
 s.runs++;if(o==="Success")s.ok++;else if(o==="Escalated")s.esc++;else s.fail++;if(o==="Success")s.saved+=Math.round(12+x*20);const r={id:"RUN-"+(5000+seedRuns().length+1),sk:id,when:NOW,by:by||"You",o,ms:Math.round(1200+x*6000),cost:.03,why,imp:null};seedRuns().unshift(r);if(o!=="Success")flag(r);audit("ran agent skill",id+" · "+o+" · "+(by||"You"));X.ver++;recalcX();return {ok:o==="Success",outcome:o,msg:why,run:r.id}}
function flag(r){const imp=seedImp();const s=skOf(r.sk);if(imp.some(i=>i.sk===r.sk&&i.st==="Flagged"))return null;const i={id:"KIM-"+(imp.length+1),sk:r.sk,kb:s?s.kb:"",why:r.why+" ("+r.id+"). Review the source item for the missing case.",st:"Flagged",owner:s?s.owner:"Nia Brooks",opened:NOW,from:r.id};imp.push(i);r.imp=i.id;audit("flagged knowledge for improvement",i.kb+": "+r.why);return i}
function advance(id,to){const s=skOf(id);if(!s)return;const role=K.role,canAp=role==="Publisher"||role==="Coach";
 if(to==="In test"&&(!s.steps.length||!s.guards.length)){toast("Add at least one step and one guardrail first.","bad");return}
 if(to==="Awaiting approval"&&!(s.tests[1]&&s.tests[0]===s.tests[1])){toast("All tests must pass before approval. "+(s.tests[1]?s.tests[0]+" of "+s.tests[1]+" pass.":"There are no tests."),"bad");return}
 if(to==="Active"&&s.status==="Awaiting approval"&&!canAp){toast("Approval needs the Publisher or Coach role.","bad");return}
 if(to==="Active"&&s.risk==="High"&&s.appr.length<2){toast("High risk skills need two named approvers.","bad");return}
 const from=s.status;s.status=to;if(to==="Active"&&from==="Awaiting approval"){s.apBy="You ("+role+")";regWF(s);regChat(s)}if(to==="Active"&&from==="Paused"){regChat(s)}if(to==="Paused"||to==="Retired")unregChat(s);X.ver++;audit("agent skill "+from+" to "+to,s.id+" "+s.name);toast(s.id+": "+to,to==="Retired"?"info":"good");render();}
DND.on("kx_pipe",(id,from,to)=>{if(from===to)return;advance(id,to)});
DND.on("kx_imp",(id,from,to)=>{if(from===to)return;const i=seedImp().find(x=>x.id===id);if(!i)return;i.st=to;if(to==="Fixed and reused"){i.closed=NOW;const sk=skOf(i.sk);if(sk&&sk.status==="Paused"){toast("Skill "+sk.id+" is paused. Resume it from the registry once you have tested the fix.","info")}METRICS.m_loop_days.cur=Math.max(2,Math.round(dd(i.opened,NOW)>0?(METRICS.m_loop_days.cur*3+dd(i.opened,NOW))/4:METRICS.m_loop_days.cur))}audit("improvement task "+to,id+" "+i.kb);toast(id+": "+to,"good");render()});
/* ---------- skills dashboard ---------- */
function board(){const sk=skills(),L=["Draft","In test","Awaiting approval","Active"];return `<div class="kx-lanes">${L.map(l=>{const c=sk.filter(s=>s.status===l);return `<section class="kx-lane glass"><header><b>${l}</b><span class="pill ${l==="Active"?"good":"mute"}">${allSkills().filter(s=>s.status===l).length}</span></header><div class="kx-lc" data-dnd="${l}" data-dnd-scope="kx_pipe">${c.map(s=>`<div class="kx-sc" data-dnd-id="${s.id}" tabindex="0">${grip}<button class="kx-link" data-kx-skill="${s.id}"><b>${esc(s.name)}</b><small>${esc(s.id)} · ${esc(s.owner)} · ${s.risk} risk</small></button></div>`).join("")||'<span class="muted small">Empty</span>'}</div></section>`}).join("")}</div><p class="muted small" style="margin-top:8px">Drag a skill to the next lane. Gates: needs a step and guardrail to enter test, every test passing to ask for approval, a Publisher or Coach to activate, two approvers for High risk. Paused: ${skills().filter(s=>s.status==="Paused").length}, retired: ${skills().filter(s=>s.status==="Retired").length}.</p>`}
function skDash(){recalcX();const sk=allSkills(),runs=sk.reduce((a,s)=>a+s.runs,0),esc_=sk.reduce((a,s)=>a+s.esc,0),act=sk.filter(s=>s.status==="Active"),top=act.slice().sort((a,b)=>b.runs-a.runs).slice(0,6).map(s=>({l:s.name,v:s.runs,c:"--accent"})),out=[["Succeeded",sk.reduce((a,s)=>a+s.ok,0),"--good-f"],["Escalated to a person",esc_,"--warn-f"],["Failed",sk.reduce((a,s)=>a+s.fail,0),"--bad-f"]].map(x=>({l:x[0],v:x[1],c:x[2]}));
 return `<div class="kx-stack"><div class="statrow">${stat("Skills",num(sk.length),num(act.length)+" active")}${stat("Runs",num(runs),"last 90 days")}${stat("Success",METRICS.m_skill_ok.cur+"%","target "+METRICS.m_skill_ok.tgt+"%")}${stat("Escalations",num(esc_),"sent back to a person")}${stat("Cost saved",money0(sk.reduce((a,s)=>a+s.saved,0)),"at analyst cost per handled ticket")}${stat("Awaiting approval",sk.filter(s=>s.status==="Awaiting approval").length,"need a decision",sk.some(s=>s.status==="Awaiting approval")?"crit":"")}</div><div class="row kx-fm">${fchip("m_skill_ok")}${fchip("m_kb_ready")}${fchip("m_loop_days")}${stdChip("kcs","Skills close the KCS loop: runs flag the source item, owners fix it once, every future run benefits.")}</div>
 ${card("Skill pipeline","Knowledge item to skill to registered workflow step and chat tool. Drag a skill between lanes; each move passes a gate.",board())}<div class="grid g2">${card("Runs by outcome","How runs finished.",kxBar(out),fchip("m_skill_ok"))}${card("Busiest skills","Active skills by run count.",kxBar(top))}</div>${card("The closed loop","Failed or escalated runs flag the source item. The owner fixes it once and every later run reuses the fix.",loopHTML())}${procCard("kcs_skills")}</div>`}
/* ---------- studio ---------- */
function studioSrcOpts(){return items().filter(k=>KT[k.type].proc>=.8&&k.st!=="Retired"&&!k.skill).sort((a,b)=>b.ready-a.ready).slice(0,80)}
function skStudio(){const st=X.studio,opts=studioSrcOpts();
 const src=`<div class="kx-stack"><section class="card glass"><div class="cardhead"><div><h3>1. Pick the knowledge item</h3><span class="muted small" data-role="story">The best 80 procedural items without a skill, highest readiness first.</span></div>${fchip("m_kb_ready")}</div><div class="kx-fr"><label class="kcs-f"><span class="eyebrow">Item</span><select class="fin" data-kx-srcsel><option value="">Choose an item</option>${opts.map(k=>`<option value="${esc(k.id)}" ${st&&st.kb===k.id?"selected":""}>${esc(k.id)} · ${esc(k.t.slice(0,70))} · ${k.ready}</option>`).join("")}</select></label><button class="btn primary" data-kx-extract ${st?"":"disabled"}>Extract steps with AI</button></div>${st?"":'<p class="muted small" style="margin-top:8px">Or press Promote on any item in the Library or Lifecycle tab.</p>'}</section>`;
 if(!st)return src+`</div>`;const k=itOf(st.kb),risk=riskOf(st.steps),writes=st.steps.filter(s=>{const t=toolOf(s.tool);return t&&t[3]!=="read"});const unguarded=writes.filter(s=>!s.guard||s.guard==="Read only");const needAp=risk==="High"||st.steps.some(s=>s.guard==="Needs approval");
 const chk=[["At least one step and one input",st.steps.length>0&&st.inputs.length>0],["Every write step has a guardrail other than Read only",unguarded.length===0],["High risk tools need an approval step and two approvers",!(risk==="High")||(st.appr.length>=2&&st.steps.some(s=>s.guard==="Needs approval"))],["Sample test passed",!!(st.test&&st.test.pass===st.test.total&&st.test.total>0)]];
 return src+`<section class="card glass"><div class="cardhead"><div><h3>2. Review the steps and tool mappings</h3><span class="muted small" data-role="story">AI split ${esc(k?k.id:st.kb)} into <b>${st.steps.length} steps</b>. Check each tool and guardrail. Drag the grips to reorder.</span></div>${st.ai?aiChip({model:"Claude Sonnet",conf:st.ai.conf,title:"Steps and tools proposed by AI",note:"Extracted from the resolution section. Tool mappings come from keywords and are suggestions, not decisions.",src:[st.kb],guards:["Registered tools only","You approve every mapping"]}):""}</div>
 <div class="tscroll"><table class="kx-st"><thead><tr><th></th><th>Step</th><th>Tool or API</th><th>Guardrail</th><th></th></tr></thead><tbody data-dnd="kx_steps" data-dnd-scope="kx_steps">${st.steps.map((s,i)=>`<tr data-dnd-id="${i}" tabindex="0"><td>${grip}</td><td class="wrap"><input class="fin" data-kx-stepn="${i}" value="${esc(s.n)}" aria-label="Step ${i+1}"></td><td><select class="fin" data-kx-stept="${i}">${TOOLS.map(t=>`<option value="${t[0]}" ${t[0]===s.tool?"selected":""}>${esc(t[0])} (${t[3]}, ${t[4].toLowerCase()})</option>`).join("")}</select></td><td><select class="fin" data-kx-stepg="${i}">${GUARDS.map(g=>`<option ${g===s.guard?"selected":""}>${g}</option>`).join("")}</select></td><td><button class="btn quiet" data-kx-stepdel="${i}" aria-label="Remove step ${i+1}">Remove</button></td></tr>`).join("")}</tbody></table></div><div class="row" style="margin-top:8px"><button class="btn" data-kx-stepadd>Add a step</button></div></section>
 <section class="card glass"><div class="cardhead"><div><h3>3. Inputs, guardrails and approvals</h3><span class="muted small" data-role="story">Computed risk is <b>${risk}</b> from the tools used. ${needAp?"This skill needs approvals.":"No approval needed for reads and low risk writes."}</span></div></div><div class="grid g3"><div><div class="eyebrow">Inputs</div><div class="kx-chips">${st.inputs.map((x,i)=>`<span class="pill mute">${esc(x[0])} <button class="kx-x" data-kx-indel="${i}" aria-label="Remove input ${esc(x[0])}">x</button></span>`).join("")}</div><div class="row"><input class="fin" data-kx-inadd placeholder="Add input, press Enter" aria-label="Add input"></div></div><div><div class="eyebrow">Guardrails</div><ul class="steps small">${st.guards.map((g,i)=>`<li>${esc(g)} <button class="kx-x" data-kx-gdel="${i}" aria-label="Remove guardrail">x</button></li>`).join("")}</ul><div class="row"><input class="fin" data-kx-gadd placeholder="Add guardrail, press Enter" aria-label="Add guardrail"></div></div><div><div class="eyebrow">Approvers</div><div class="kx-chips">${["Service owner","Platform on-call","Security lead","Service desk lead","Sponsor","Chief Editor"].map(a=>`<button class="chip" data-kx-ap="${esc(a)}" aria-pressed="${st.appr.includes(a)}">${esc(a)}</button>`).join("")}</div></div></div></section>
 <section class="card glass"><div class="cardhead"><div><h3>4. Test with a sample input</h3><span class="muted small" data-role="story">A dry run goes through every step with a fake target and three checks: the happy path, a missing input and a guardrail trip.</span></div></div><div class="kx-fr">${st.inputs.map(x=>`<label class="kcs-f"><span class="eyebrow">${esc(x[0])}</span><input class="fin" data-kx-samp="${esc(x[0])}" value="${esc(st.sample[x[0]]||"")}" placeholder="${x[1]==="person"?"Taylor Reed":x[1]==="date"?"2026-11-15":"INC0110"}"></label>`).join("")}<button class="btn primary" data-kx-test>Run the test</button></div>${st.test?`<div class="kx-tr">${st.test.cases.map(c=>`<div class="kx-run"><span class="pill ${c.ok?"good":"bad"}">${c.ok?"Pass":"Fail"}</span><span><b>${esc(c.n)}</b><small class="muted"> ${esc(c.msg)}</small></span></div>`).join("")}</div><div class="kx-trace"><b>Trace of the happy path</b><ol class="kx-steps2">${st.test.trace.map(t=>`<li><b>${esc(t.n)}</b><span class="muted small"><code>${esc(t.tool)}</code> ${esc(t.res)}</span></li>`).join("")}</ol></div>`:'<p class="muted small" style="margin-top:8px">No test run yet.</p>'}</section>
 <section class="card glass"><div class="cardhead"><div><h3>5. Submit for approval</h3><span class="muted small" data-role="story">The approver sees the steps, tools, guardrails and test result. Nothing runs, and no chat tool or workflow step exists, until it is approved.</span></div></div><ul class="kx-ck">${chk.map(c=>`<li class="${c[1]?"ok":""}"><i aria-hidden="true">${c[1]?"✓":"○"}</i>${esc(c[0])}</li>`).join("")}</ul><div class="row" style="margin-top:10px"><label class="kcs-f kx-grow"><span class="eyebrow">Skill name</span><input class="fin" data-kx-name value="${esc(st.name)}"></label><button class="btn primary" data-kx-submit ${chk.every(c=>c[1])?"":"disabled"}>Submit for approval</button><button class="btn quiet" data-kx-discard>Discard</button></div></section></div>`}
function runTest(){const st=X.studio;if(!st)return;const mis=st.inputs.filter(i=>i[2]&&!(st.sample[i[0]]||"").trim());const trace=st.steps.map(s=>{const t=toolOf(s.tool);let res="ok in sandbox";if(!t)res="unknown tool";else if(t[3]!=="read"&&s.guard==="Read only")res="blocked: write tool marked read only";else if(s.guard==="Needs approval")res="paused for approval, auto-approved in test";return {n:s.n,tool:s.tool,res}});const bad=trace.some(t=>/unknown|blocked/.test(t.res));
 const cases=[{n:"Happy path with sample input",ok:!bad&&!mis.length,msg:mis.length?"Missing sample value for "+mis.map(m=>m[0]).join(", "):bad?"A step failed, see the trace":"All "+trace.length+" steps passed"},{n:"Missing required input is refused",ok:st.inputs.some(i=>i[2]),msg:st.inputs.some(i=>i[2])?"Skill stops and asks for the input":"Mark at least one input as required"},{n:"Guardrail trips and escalates",ok:st.guards.length>0,msg:st.guards.length?"Escalated to "+(st.appr[0]||"the owner")+" when '"+st.guards[0]+"' is violated":"Add a guardrail so there is something to trip"}];
 st.test={cases,trace,pass:cases.filter(c=>c.ok).length,total:cases.length};audit("tested agent skill draft",st.name+" · "+st.test.pass+" of "+st.test.total);toast(st.test.pass===st.test.total?"All 3 tests passed":st.test.pass+" of 3 tests passed",st.test.pass===st.test.total?"good":"warn");render()}
function submitStudio(){const st=X.studio;if(!st)return;const k=itOf(st.kb),id0=X.editSk,ex=id0&&skills().find(s=>s.id===id0);const risk=riskOf(st.steps);const obj={name:st.name,kb:st.kb,svc:k?k.svc:"",owner:st.owner,status:"Awaiting approval",risk,ver:ex?(+ex.ver+0.1).toFixed(1):"0.1",inputs:st.inputs,steps:st.steps.map(s=>[s.n,s.tool,s.guard]),guards:st.guards,appr:st.appr,tests:[st.test.pass,st.test.total],runs:ex?ex.runs:0,ok:ex?ex.ok:0,esc:ex?ex.esc:0,fail:ex?ex.fail:0,saved:ex?ex.saved:0,conf:st.ai?st.ai.conf:.8,model:"Claude Sonnet",created:NOW,src:st.kb};
 if(ex)Object.assign(ex,obj);else{const n=skills().length+101;obj.id="SK-"+n;skills().push(obj)}X.studio=null;X.editSk=null;X.ver++;audit("submitted agent skill for approval",obj.name);toast("Submitted. "+(st.appr[0]||"A Publisher")+" will see it in Awaiting approval.","good");X.tab=0;render()}
DND.on("kx_steps",(id,from,to,index)=>{const st=X.studio;if(!st)return;const i=+id,s=st.steps.splice(i,1)[0];st.steps.splice(Math.min(index,st.steps.length),0,s);st.test=null;audit("reordered skill steps",st.name);render()});
/* ---------- runs and improvement loop ---------- */
let SCR=null;function runRows(){const base=seedRuns();if(!SCALE.on)return base;if(!SCR){const r=RNG("kcsx-runs2"),sk=scSkills().filter(s=>s.runs),out=[];for(let i=0;i<2800&&sk.length;i++){const s=sk[Math.floor(r()*sk.length)],x=r(),o=x<.86?"Success":x<.96?"Escalated":x<.99?"Failed":"Blocked";out.push({id:"RUN-"+(9000+i),sk:s.id,when:addD(NOW,-Math.floor(r()*60)),by:"Automatic",o,ms:Math.round(800+r()*8000),cost:.02,why:o==="Success"?"Completed all steps":"Guardrail or tool issue",imp:null})}SCR=out}return base.concat(SCR)}
function runsHTML(){return btHTML({id:"kx_runs",rows:()=>runRows().map(r=>Object.assign({},r,{sn:(skOf(r.sk)||{name:r.sk}).name})),key:"id",h:420,rowH:44,facets:["o","sk"],exportName:"skill-runs",open:id=>{const r=runRows().find(x=>x.id===id);if(r&&r.o!=="Success"&&!r.imp){flag(r);X.ver++;render()}else if(r)openSkill(r.sk)},cols:[{k:"id",label:"Run"},{k:"sn",label:"Skill",wrap:true,fmt:r=>`<span class="kx-t"><b>${esc(r.sn)}</b><small>${esc(r.sk)}</small></span>`},{k:"o",label:"Outcome",fmt:r=>`<span class="pill ${r.o==="Success"?"good":r.o==="Escalated"?"warn":"bad"}">${r.o}</span>`},{k:"when",label:"When",fmt:r=>fD(r.when),val:r=>r.when},{k:"by",label:"Started by"},{k:"why",label:"What happened",wrap:true},{k:"imp",label:"Improvement",fmt:r=>r.imp?esc(r.imp):r.o!=="Success"?'<span class="muted small">click to flag</span>':""}]})}
function impBoard(){const L=["Flagged","Fixing","Fixed and reused"],imp=seedImp();return `<div class="kx-lanes kx-l3">${L.map(l=>`<section class="kx-lane glass"><header><b>${l}</b><span class="pill mute">${imp.filter(i=>i.st===l).length}</span></header><div class="kx-lc" data-dnd="${l}" data-dnd-scope="kx_imp">${imp.filter(i=>i.st===l).map(i=>`<div class="kx-sc" data-dnd-id="${i.id}" tabindex="0">${grip}<span><b>${esc(i.kb)} · ${esc(i.sk)}</b><small>${esc(i.why)}</small><span class="row" style="gap:6px;margin-top:6px">${ptxt(i.owner)}<button class="btn quiet" data-kx-item="${esc(i.kb)}">Open item</button>${l!=="Fixed and reused"?`<button class="btn quiet" data-kx-fixdraft="${esc(i.id)}">AI draft fix</button>`:""}</span></span></div>`).join("")||'<span class="muted small">Empty</span>'}</div></section>`).join("")}</div><p class="muted small" style="margin-top:8px">KCS says flag it, fix it, reuse it. Drag a task right as work progresses. When it lands in Fixed and reused, the next run uses the corrected item.</p>`}
function loopPane(){return `<div class="kx-stack">${card("The loop, live","Runs flow back into the knowledge they came from.",loopHTML(),fchip("m_loop_days"))}${card("Improvement tasks","One per source item. Created automatically when a run fails or escalates, or by hand from a run.",impBoard())}${card("Skill runs","Every run is audited. Click an escalated or failed run to flag its source item.",runsHTML())}</div>`}
/* ---------- tools ---------- */
function toolsPane(){return `<div class="kx-stack"><p class="muted small" style="margin:0" data-role="story">Skills may only call registered tools: an API or a Model Context Protocol (MCP) server action. Each tool states what it can change, how risky that is and which guardrail it needs by default.</p>${card("Tool and MCP catalog",TOOLS.length+" registered tools",`<div class="tscroll"><table><thead><tr><th>Tool</th><th>What it does</th><th>System</th><th>Kind</th><th>Risk</th><th>Used by</th></tr></thead><tbody>${TOOLS.map(t=>`<tr><td><code>${esc(t[0])}</code></td><td class="wrap"><b>${esc(t[1])}</b><span class="sub">${esc(t[5])}</span></td><td>${esc(t[2])}</td><td>${t[3]}</td><td>${pill(t[4],t[4]==="High"?"bad":t[4]==="Medium"?"warn":"good")}</td><td class="num">${allSkills().filter(s=>s.steps.some(p=>(p[1]||p.tool)===t[0])).length} skills</td></tr>`).join("")}</tbody></table></div>`,`<div class="row">${stdChip("nist","Govern and protect: least privilege per tool, human approval for high risk writes, every call logged.")}</div>`)}</div>`}
REG("kcs_skills","Agent skills","know","M13 2L4 14h7l-1 8 9-12h-7zM18 4l2 2M4 4l2 2",()=>{recalcX();syncReg();const sk=allSkills(),act=sk.filter(s=>s.status==="Active"),it=items(),ready=it.filter(k=>k.band===BANDS[0]&&!k.skill).length;if(S.v.kx_sv==null&&X.tab!=null)S.v.kx_sv=X.tab;
 return `<div class="screen">${hero("Agent skills · knowledge into action","Turn what we know into work that runs itself",`<b>${act.length} agent skills</b> are running with a <b>${METRICS.m_skill_ok.cur}%</b> success rate and ${money0(sk.reduce((a,s)=>a+s.saved,0))} saved. <b>${num(it.filter(k=>k.ready>=60&&!k.skill&&KT[k.type].proc>=.8&&k.st==="Published").length)}</b> more published procedural items score 60 or more and can be promoted. Every skill is a knowledge item with inputs, tools, guardrails, approvals and tests, registered as a workflow step and a chat tool only after a person approves it.`,`<div class="row">${fchip("m_skill_ok")}${fchip("m_kb_ready")}${fchip("m_loop_days")}<button class="btn primary" data-kx-tabgo="2">Open the Skill studio</button>${whyPop("Skills are the third stage of the knowledge lifecycle. They are never created without a source item, and never active without tests and a human approval.")}</div>`)}${lensNote()}
 ${views("kx_sv",["Dashboard","Registry","Skill studio","Runs and improvement loop","Tool catalog"],[skDash(),`<div class="kx-stack"><p class="muted small" style="margin:0" data-role="story">All skills with their status, runs, success, escalations, cost saved, tests and the readiness of the source item. Click a row for the full procedure.</p>${regHTML()}</div>`,skStudio(),loopPane(),toolsPane()])}</div>`});

