function gapExtra(){const un=T.UNANS;const rows=un.slice(0,5).map(u=>({q:u.q,why:u.n+" searches, "+u.aud,svc:(GAPN.find(g=>g[0]===u.q)||[0,"svc_cod"])[1],kind:"Search gap",n:u.n,draft:u.draft}));
 const rep=REPEAT.map(r=>({q:r[0],why:r[1],svc:r[2],kind:"Repeat incident",n:3,draft:r[4],pat:r[3]}));const all=rows.concat(rep);
 return `<section class="card glass kx-gapx"><div class="cardhead"><div><h3>From gap to work</h3><span class="muted small" data-role="story">Failed searches and repeat incidents with no article become demand for the portfolio office and a drafted item for a human to publish. Nothing is published without a Publisher approving it.</span></div>${stdChip("kcs","KCS v6: when you cannot find it, create it in the flow of work, then improve it.")}</div><div class="kx-gl">${all.map((g,i)=>`<div class="kx-gi"><div><b>${esc(g.q)}</b> ${pill(g.kind,g.kind==="Repeat incident"?"bad":"warn")}<span class="muted small">${esc(g.why)} · ${esc(svcName(g.svc))}</span></div><div class="row" style="gap:8px">${g.draft?`<button class="btn" data-kx-item="${esc(g.draft)}">Draft exists</button>`:`<button class="btn" data-kx-aidraft="${i}">AI draft</button>`}<button class="btn quiet" data-kx-demand="${i}">Raise demand</button></div></div>`).join("")}</div><p class="muted small" style="margin-top:10px">AI draft: Knowledge Curator reads the incidents and threads, drafts the item with citations (lineage shown on the item), and a Publisher approves it. Demand goes to the portfolio intake with the service and the evidence.</p></section>`}
X._gap=null;
function gapList(){const un=T.UNANS;const rows=un.slice(0,5).map(u=>({q:u.q,why:u.n+" searches, "+u.aud,svc:(GAPN.find(g=>g[0]===u.q)||[0,"svc_cod"])[1],kind:"Search gap",n:u.n,draft:u.draft}));return rows.concat(REPEAT.map(r=>({q:r[0],why:r[1],svc:r[2],kind:"Repeat incident",n:3,draft:r[4],pat:r[3]})))}
