P("kcs_edit",{title:"Article lifecycle",std:["kcs"],steps:[{n:"Draft",d:"Capture in the flow of work.",who:"human"},{n:"Structure",d:"AI helps fill sections.",who:"agent",owner:"Knowledge Curator"},{n:"Review",d:"Reviewer approves.",who:"gate",owner:"Nia Brooks"},{n:"Publish",d:"Publisher publishes.",who:"gate"},{n:"Review again",d:"Expiry date triggers a review.",who:"auto"}]});
