 if(d.kxEdit){const s=skOf(d.kxEdit);if(!s)return;const k=itOf(s.kb);X.studio={kb:s.kb,name:s.name,owner:s.owner,risk:s.risk,steps:s.steps.map(p=>({n:p[0]||p.n,tool:p[1]||p.tool,guard:p[2]||p.guard})),inputs:s.inputs.map(i=>i.slice()),guards:s.guards.slice(),appr:s.appr.slice(),test:null,sample:{},ai:{conf:s.conf,n:s.steps.length}};X.editSk=s.id;closeDrawer();S.v.kx_sv=2;go("kcs_skills");return}
 if(d.kxExtract!==undefined){const st=X.studio;if(!st)return;const k=itOf(st.kb);if(!k)return;const x=extract(k);Object.assign(st,{steps:x.steps,inputs:x.inputs,guards:x.guards,ai:x.ai,test:null});audit("AI extracted skill steps",st.kb+": "+x.steps.length+" steps");toast(x.steps.length+" steps extracted. Check each tool.","good");S.v.kx_sv=2;render();return}
 if(d.kxStepadd!==undefined){const st=X.studio;if(!st)return;st.steps.push({n:"New step",tool:"itsm.updateIncident",guard:"Notify the owner"});st.test=null;render();return}
 if(d.kxStepdel!==undefined){const st=X.studio;st.steps.splice(+d.kxStepdel,1);st.test=null;render();return}
 if(d.kxIndel!==undefined){X.studio.inputs.splice(+d.kxIndel,1);X.studio.test=null;render();return}
 if(d.kxGdel!==undefined){X.studio.guards.splice(+d.kxGdel,1);X.studio.test=null;render();return}
 if(d.kxAp){const st=X.studio,a=d.kxAp;st.appr=st.appr.includes(a)?st.appr.filter(x=>x!==a):st.appr.concat(a);render();return}
 if(d.kxTest!==undefined){runTest();return}
