 const heat=`<div class="tscroll"><table class="mat-heat"><thead><tr><th>Capability</th><th>Required level path</th><th>Why it is needed</th></tr></thead><tbody>${w.rows.filter(r=>r.leaf).sort((a,b)=>b.gap-a.gap||b.tot-a.tot).slice(0,14).map(r=>{let c="";for(let k=1;k<=mMax(r.n);k++)c+=`<i class="${k<=r.cur+.001?"on":k<=r.req?(k<=r.cv+.001?"fc":"gap"):""}${k===r.req?" tg":""}"></i>`;return `<tr><th scope="row"><button class="mat-lk" data-mat-cap="${r.id}">${H(r.n.name)}</button><small class="muted">${H(mname(r.n.model))}</small></th><td><span class="mat-lad big">${c}</span></td><td class="small">${H(r.why||"")}</td></tr>`}).join("")}</tbody></table></div>`+legend([["Reached today","--accent"],["Funded project delivers it","--warn-f"],["Gap: new work needed","--bad-f"]])+(w.leafRows.length>14?`<p class="muted small">Top 14 of ${w.leafRows.length} capabilities by gap. The table below has all of them.</p>`:"");
