const SAMPLES={csv:`# model: Zero trust maturity
# source: CISA Zero Trust Maturity Model v2 (summary)
level,name,criteria
1,Traditional,Static rules and manual configuration. Access is granted by network location.
2,Initial,Some automation of provisioning. Identity and device checks begin at the edges.
3,Advanced,Integrated policy across pillars with centralized visibility and risk-based access.
4,Optimal,"Fully automated, just-in-time access with continuous monitoring and dynamic policy."

capability,parent,current,year1,year3,year5,owner,description
Identity,,2,3,4,4,Rina Okafor,Strong authentication and least privilege for every user and service account
Devices,,2,3,3,4,Sam Patel,"Inventory, posture and compliance checks before access"
Networks,,2,2,3,4,Sam Patel,Micro-segmentation and encrypted traffic
Applications and workloads,,1,2,3,4,Jordan Lee,Access decisions per application with runtime protection
Data,,2,3,4,4,Dev Rao,Classification, encryption and access tied to data sensitivity
Conditional access policies,Identity,3,3,4,4,Rina Okafor,Risk-based sign-in policy in Entra ID`,
json:`{"name":"Knowledge-centered service adoption","source":"Consortium for Service Innovation KCS v6 (summary)","owner":"Jordan Lee",
 "levels":[{"level":1,"name":"Ad hoc","criteria":"Knowledge is written after the fact by a few experts."},{"level":2,"name":"Capture in the workflow","criteria":"Agents create articles while solving, using a simple template."},{"level":3,"name":"Structured and reused","criteria":"Articles are linked to incidents, reuse is counted and confidence is tracked."},{"level":4,"name":"Evolved","criteria":"The content is improved by the people who use it; metrics drive coaching."},{"level":5,"name":"Leveraged","criteria":"Knowledge drives self-service, deflection and agent drafting with citations."}],
 "capabilities":[{"name":"Capture and structure","current":3,"year1":4,"year3":4,"year5":5,"owner":"Jordan Lee"},{"name":"Reuse and linking","current":2,"year1":3,"year3":4,"year5":5,"owner":"Tom Becker"},{"name":"Article quality and review","current":2,"year1":3,"year3":4,"year5":5,"owner":"Jordan Lee"},{"name":"Self-service publishing","current":1,"year1":2,"year3":4,"year5":5,"owner":"Sam Patel"},{"name":"AI drafting with citations","current":1,"year1":3,"year3":4,"year5":5,"owner":"Jordan Lee"}]}`,
md:`# Accessibility operations maturity

Source: WCAG operations practice (summary)

## Levels

### Level 1: Reactive
- Issues are fixed when a complaint arrives.
- No owner for accessibility.

### Level 2: Aware
- A checklist exists and new pages are tested by hand.
- An owner is named.

### Level 3: Managed
- Automated scans run on every release.
- Defects are tracked with a service level.

### Level 4: Integrated
- Accessibility acceptance criteria are part of every requirement.
- Editors are trained on accessible authoring.

### Level 5: Embedded
- Accessibility is measured with user experience scores and audited yearly by a third party.

## Capabilities
- Accessible authoring for editors (current 2, target 3, year 3 4, year 5 5)
- Automated testing in release pipeline (current 3, target 4, year 3 4, year 5 5)
- Requirements and acceptance criteria (current 1, target 3, year 3 4, year 5 5)
- Public portal conformance (current 2, target 3, year 3 4, year 5 5)
  - Search results page (current 2, target 3)
  - Reader mode and print (current 2, target 3)`};
if(!M.ing.txt){M.ing.txt=SAMPLES.csv;M.ing.fmt="auto"}
function csvRows(t){const rows=[];let row=[],cur="",q=false;for(let i=0;i<t.length;i++){const ch=t[i];if(q){if(ch==='"'){if(t[i+1]==='"'){cur+='"';i++}else q=false}else cur+=ch}else if(ch==='"')q=true;else if(ch===","){row.push(cur);cur=""}else if(ch==="\n"||ch==="\r"){if(ch==="\r"&&t[i+1]==="\n")i++;row.push(cur);rows.push(row);row=[];cur=""}else cur+=ch}if(cur!==""||row.length){row.push(cur);rows.push(row)}return rows}
const num=v=>{const x=parseFloat(String(v).replace(/[^\d.\-]/g,""));return isNaN(x)?null:x};
function parseModel(txt,fmt){const out={name:"",source:"",owner:"",levels:[],caps:[],warn:[],fmt:fmt||"csv"};txt=(txt||"").replace(/^﻿/,"");const t=txt.trim();if(!t){out.warn.push("Nothing to read yet. Paste a model or choose a file.");return out}
 if(!fmt||fmt==="auto")fmt=/^[\[{]/.test(t)?"json":/^#{1,6}\s|^\|/m.test(t)&&!/^#\s*(model|source|owner)\s*:/im.test(t)?"md":"csv";out.fmt=fmt;
 try{
 if(fmt==="json"){const j=JSON.parse(t);const o=Array.isArray(j)?{capabilities:j}:j;out.name=o.name||o.model||"";out.source=o.source||"";out.owner=o.owner||"";
  (o.levels||[]).forEach((l,i)=>{if(Array.isArray(l))out.levels.push([String(l[0]),String(l[1]||"")]);else out.levels.push([String(l.name||l.title||"Level "+(l.level||i+1)),String(l.criteria||l.description||"")])});
  (o.capabilities||o.areas||[]).forEach(c=>{const tg=c.target&&typeof c.target==="object"?c.target:{};out.caps.push({name:String(c.name||c.capability||""),parent:c.parent||"",cur:num(c.current!=null?c.current:c.cur),y1:num(c.year1!=null?c.year1:tg.y1!=null?tg.y1:c.target),y3:num(c.year3!=null?c.year3:tg.y3),y5:num(c.year5!=null?c.year5:tg.y5),owner:c.owner||"",desc:c.description||""})})}
 else if(fmt==="md"){let sec="",lv=null;const lines=txt.split(/\r?\n/);
  lines.forEach(raw=>{const ln=raw.replace(/\s+$/,"");if(!ln.trim())return;let m;
   if(m=/^#\s+(.+)$/.exec(ln)){if(!out.name)out.name=m[1].trim();return}
   if(m=/^#{2,4}\s+(.+)$/.exec(ln)){const h=m[1].trim(),lm=/^level\s*(\d+)\s*[:\-–.]?\s*(.*)$/i.exec(h);if(lm){sec="levels";lv=[lm[2]||"Level "+lm[1],""];out.levels.push(lv);return}if(/capabilit|area|practice|domain|process|function/i.test(h)){sec="caps";lv=null;return}if(/level|scale/i.test(h)){sec="levels";lv=null;return}sec="";return}
   if(m=/^source\s*:\s*(.+)$/i.exec(ln.trim())){out.source=m[1];return}if(m=/^owner\s*:\s*(.+)$/i.exec(ln.trim())){out.owner=m[1];return}
   if(sec==="levels"){if(m=/^\s*(?:[-*]|\d+[.)])\s+(.*)$/.exec(ln)){if(lv)lv[1]+=(lv[1]?" ":"")+m[1].trim().replace(/\.?$/,".");else{const pm=/^\**(.+?)\**\s*[:\-–]\s*(.+)$/.exec(m[1]);out.levels.push(pm?[pm[1],pm[2]]:[m[1],""])}}else if(lv)lv[1]+=(lv[1]?" ":"")+ln.trim();return}
   if(sec==="caps"||(!sec&&/^\s*[-*]\s/.test(ln))){if(/^\s*\|/.test(ln)){const cs=ln.split("|").slice(1,-1).map(x=>x.trim());if(/^[-: ]+$/.test(cs.join("")))return;if(/capab|name/i.test(cs[0])&&!out._th){out._th=cs.map(x=>x.toLowerCase());return}const g=k=>{const i=(out._th||[]).findIndex(x=>x.includes(k));return i>=0?cs[i]:null};out.caps.push({name:cs[0],parent:"",cur:num(g("cur")),y1:num(g("year 1")!=null?g("year 1"):g("target")),y3:num(g("year 3")),y5:num(g("year 5")),owner:g("owner")||"",desc:""});return}
    if(m=/^(\s*)[-*]\s+(.+)$/.exec(ln)){const ind=m[1].length>=2,body=m[2];const pm=/\(([^)]*)\)\s*$/.exec(body),nm=(pm?body.slice(0,pm.index):body).trim().replace(/:.*$/,"").replace(/\*\*/g,"");const spec=pm?pm[1]:"";const gv=re=>{const x=re.exec(spec);return x?num(x[1]):null};
     const par=ind&&out.caps.length?[...out.caps].reverse().find(c=>!c.parent):null;out.caps.push({name:nm,parent:par?par.name:"",cur:gv(/cur(?:rent)?\s*[:=]?\s*(\d+)/i),y1:gv(/(?:target|year\s*1|y1)\s*[:=]?\s*(\d+)/i),y3:gv(/(?:year\s*3|y3)\s*[:=]?\s*(\d+)/i),y5:gv(/(?:year\s*5|y5)\s*[:=]?\s*(\d+)/i),owner:"",desc:(/:\s*(.+?)\s*(?:\(|$)/.exec(body)||[])[1]||""})}}});delete out._th}
 else{/* csv blocks */const lines=txt.split(/\r?\n/),blocks=[];let curB=[];lines.forEach(l=>{const m=/^#\s*(model|name|source|owner)\s*:\s*(.*)$/i.exec(l.trim());if(m){const k=m[1].toLowerCase();if(k==="model"||k==="name")out.name=m[2];else out[k]=m[2];return}if(/^#/.test(l.trim()))return;if(!l.trim()){if(curB.length)blocks.push(curB);curB=[];return}curB.push(l)});if(curB.length)blocks.push(curB);
  blocks.forEach(b=>{const rows=csvRows(b.join("\n")).filter(r=>r.some(x=>x.trim()));if(!rows.length)return;const hd=rows[0].map(x=>x.trim().toLowerCase()),ix=(...ks)=>hd.findIndex(h=>ks.some(k=>h===k||h.startsWith(k)));
   if(ix("capability","area","practice","process")>=0){const ci=ix("capability","area","practice","process"),pi=ix("parent"),cu=ix("current","cur","today"),y1=ix("year1","year 1","y1","target"),y3=ix("year3","year 3","y3"),y5=ix("year5","year 5","y5"),ow=ix("owner"),de=ix("description","desc");
    rows.slice(1).forEach(r=>out.caps.push({name:(r[ci]||"").trim(),parent:pi>=0?(r[pi]||"").trim():"",cur:cu>=0?num(r[cu]):null,y1:y1>=0?num(r[y1]):null,y3:y3>=0?num(r[y3]):null,y5:y5>=0?num(r[y5]):null,owner:ow>=0?(r[ow]||"").trim():"",desc:de>=0?(r[de]||"").trim():""}))}
   else if(ix("level")>=0||ix("number")>=0){const ni=ix("name","title"),cr=ix("criteria","description");rows.slice(1).forEach((r,i)=>out.levels.push([(ni>=0?r[ni]:r[1]||"Level "+(i+1)).trim(),(cr>=0?r[cr]:r[2]||"").trim()]))}
   else out.warn.push("Skipped a block whose header has neither a capability nor a level column: "+rows[0].join(", ").slice(0,60))})}
 }catch(e){out.warn.push("Could not read this as "+({csv:"CSV",json:"JSON",md:"Markdown"}[fmt])+": "+e.message)}
 out.caps=out.caps.filter(c=>c.name);const max=out.levels.length;
 if(!out.name)out.warn.push("No model name found. It will be called Imported model.");if(!max)out.warn.push("No levels found. Add a levels table or a Levels section. Five generic levels will be used.");if(max===1)out.warn.push("Only one level found. A maturity model needs at least two.");
 if(!out.caps.length)out.warn.push("No capabilities found. Add rows under a capability header.");
 out.caps.forEach(c=>{const mx=max||5;if(c.cur==null){c.cur=1;c.autoCur=1}if(c.cur>mx||c.cur<1){out.warn.push(`${c.name}: current level ${c.cur} is outside 1 to ${mx}. Clamped.`);c.cur=clamp(c.cur,1,mx)}
  [["y1",c.cur+1],["y3",null],["y5",null]].forEach(([k,d],i)=>{if(c[k]==null)c[k]=null;else if(c[k]>mx||c[k]<1){out.warn.push(`${c.name}: ${k} target ${c[k]} is outside 1 to ${mx}. Clamped.`);c[k]=clamp(c[k],1,mx)}});if(c.parent&&!out.caps.some(x=>x.name===c.parent)){out.warn.push(`${c.name}: parent "${c.parent}" not found. Treated as top level.`);c.parent=""}});
 const dup=out.caps.map(c=>c.name.toLowerCase()).filter((x,i,a)=>a.indexOf(x)!==i);if(dup.length)out.warn.push("Duplicate capability names: "+[...new Set(dup)].join(", "));
 return out}
const OKW={O1:/publish|standard|content|editorial|codif|taxonom|search|document|requirement|metadata|portal|authoring|knowledge|catalog|reader|delivery|release/i,O2:/risk|secur|resilien|incident|availab|identity|recover|network|device|detect|respond|protect|continuity|zero trust|access|monitor|backup|threat|govern/i,O3:/contract|vendor|supplier|invoice|financ|cost|budget|procure|obligation|spend|benefit|value/i,O4:/\bai\b|agent|model|automat|autonom|guardrail|ethic|provenance|citation|oversight|evaluation|bias|prompt/i,O5:/editor|reviewer|experience|usab|accessib|training|literacy|collaborat|authoring|self-service|coaching|workload|reuse|knowledge/i};
const SKW={id:/identity|access|authenticat|sign-in|privilege/i,net:/network|segment|traffic|zero trust|vpn/i,end:/device|endpoint|posture/i,data:/\bdata\b|catalog|quality|analytics|metadata|classif/i,search:/search|index|find|retriev/i,cr:/contract|obligation|supplier/i,fin:/financ|invoice|ledger|cost|budget/i,m365:/collaborat|email|teams|sharepoint|document/i,cod:/application|workload|authoring|publish|requirement|release|pipeline/i,portal:/portal|reader|public|conformance/i,int:/integrat|api|interoper/i,desk:/incident|request|support|desk|knowledge|self-service|ticket/i};
function aiMap(c){const txt=c.name+" "+(c.desc||"")+" "+(c.parent||"");const os=[],why=[];Object.keys(OKW).forEach(k=>{const m=txt.match(new RegExp(OKW[k].source,"gi"));if(m)os.push([k,m.length,[...new Set(m.map(x=>x.toLowerCase()))]])});os.sort((a,b)=>b[1]-a[1]);
 const sv=[];Object.keys(SKW).forEach(k=>{if(SKW[k].test(txt))sv.push(SVID(k))});const top=os.slice(0,2).filter(o=>o[1]>=1);
 return {objs:top.map(o=>o[0]),svcs:sv.slice(0,3),conf:top.length?Math.min(.93,.45+.16*top[0][1]):.3,why:top.length?"Matched "+top.map(o=>`"${o[2].slice(0,3).join(", ")}" to ${objOf(o[0]).sub||o[0]}`).join("; "):"No strategic keyword matched. Drag it to an objective.",auto:1}}
function ingestState(){const I=M.ing,p=I.res;return p}
function importModel(p,map,meta){const nid="X"+(M.xmodels.length+1),P=nid,max=p.levels.length>=2?p.levels.length:5,lv=p.levels.length>=2?p.levels:[["Initial","Ad hoc"],["Managed","Planned and tracked"],["Defined","Standard across the organization"],["Quantitatively managed","Measured and controlled"],["Optimizing","Continually improved"]];
 const mo={id:nid.toLowerCase(),n:meta.name||p.name||"Imported model",src:meta.src||"Ingested ("+({csv:"CSV",json:"JSON",md:"Markdown"}[p.fmt]||"file")+")",std:null,own:meta.owner||p.owner||"Jordan Lee",ver:meta.ver||p.source||"1.0",desc:meta.desc||("Ingested from "+(p.source||"a pasted file")+". "+p.caps.length+" capabilities, "+max+" levels."),lv,ob:[]};M.xmodels.push(mo);
 const root={id:P,model:mo.id,parent:null,name:mo.n,cur:null,t:[null,null,null],conf:.7,owner:mo.own,objs:[],svcs:[],pre:[],cr:[],mt:[],sk:[],w:1,b0:null,eff:0,mo:0,root:1,ids:[]};M.xcaps.push(root);reg(root);const idOf={};let n=0;
 const ord=p.caps.slice().sort((a,b)=>(a.parent?1:0)-(b.parent?1:0));ord.forEach(c=>{n++;const id=c.parent&&idOf[c.parent]?idOf[c.parent]+String.fromCharCode(96+n%26+1):P+"."+n,i=p.caps.indexOf(c),mp=map[i]||aiMap(c);idOf[c.name]=id;
  const y1=c.y1!=null?c.y1:Math.min(max,c.cur+1),y3=c.y3!=null?c.y3:Math.min(max,y1+(max>3?1:0)),y5=c.y5!=null?c.y5:Math.min(max,y3+1);
  const o={id,model:mo.id,parent:c.parent&&idOf[c.parent]?idOf[c.parent]:P,name:c.name,cur:c.cur,t:[y1,Math.max(y1,y3),Math.max(y1,y3,y5)],conf:.6,owner:c.owner||mo.own,objs:(mp.objs||[]).slice(),svcs:(mp.svcs||[]).slice(),pre:[],cr:[],mt:[],sk:[],w:1,b0:c.cur,eff:1.5+(n%3)*.5,mo:3+(n%3),root:0,note:c.desc||""};M.xcaps.push(o);reg(o)});
 audit("ingested maturity model",mo.n+": "+p.caps.length+" capabilities");return mo}
