function svcDrawer(id){const s=svcOf(id);if(!s)return;const L=nodesOfSvc(s.id),R=roll(L);
 openDrawer(`<div class="row"><span class="pill info">${H(s.tier)}</span>${L.length?stPill(R.st):pill("No capabilities mapped","mute")}</div><h2 style="font-size:28px;margin:12px 0 6px;padding-right:60px">${H(s.n)}</h2><p class="story" data-role="story">Service maturity is <b>${s.maturity}</b> of 5 today and <b>${s.matTgt||"not set"}</b> at Year 1. It is the average of ${L.length} capabilit${L.length===1?"y":"ies"} from ${[...new Set(L.map(n=>n.model))].length} models. Owner ${pchip(s.owner)}.</p>
 ${L.length?`<div class="dfullgrid mat-dg"><div>${glideSVG(L,{label:s.n})}</div><div>${lrHTML({id:"mat_dsv_"+s.id,groups:ALLM().map(m=>({key:m.id,label:m.n,rows:L.filter(n=>n.model===m.id).map(n=>({id:n.id,t:n.name,sub:`level ${fv(cur(n))} to ${fv(tgtN(n,0))}`,tag:"",st:status(n).s,go:()=>capDrawer(n.id)}))})).filter(g=>g.rows.length),limit:5})}</div></div>`:""}
 <div class="row mat-act"><button class="btn primary" data-mat-imp="${s.id}">Impact analysis</button><button class="btn" data-mat-newcap>Add a capability for this service</button></div>`)}
