function findNode(l){const ns=CAPS().filter(n=>!n.root).concat(CAPS().filter(n=>n.root));let best=null,bs=0;ns.forEach(n=>{const nm=n.name.toLowerCase(),words=nm.split(/[^a-z0-9]+/).filter(w=>w.length>3);let s=0;if(l.includes(nm))s=20+nm.length;else words.forEach(w=>{if(l.includes(w))s+=w.length});if(n.root&&s>0)s+=3;if(s>bs){bs=s;best=n}});return bs>=5?best:null}
