 o.rows.forEach((r,j)=>{g+=`<text class="ax" x="${L-8}" y="${T+j*ch+ch/2+4}" text-anchor="end">${H(r)}</text>`;o.data[j].forEach((v,i)=>{const a=v?.12+.88*v/mx:.05;g+=`<rect x="${L+i*cw+1}" y="${T+j*ch+1}" width="${cw-2}" height="${ch-2}" rx="4" fill="var(${o.c||"--bad-f"})" opacity="${a.toFixed(2)}"><title>${H(r+" "+o.cols[i]+": "+v+" "+(o.unit||"alerts"))}</title></rect>`})});
