function wallPane(){const A=computeAll();SYNCM();const open=A.day.filter(a=>a.active&&!a.sup&&!a.fp),crit=open.filter(a=>a.sev<=2),svcs=new Set(open.map(a=>a.svc)),h=hostRowsAll(),bad=h.filter(x=>x.status==="crit"||x.status==="flap").length,warn=h.filter(x=>x.status==="warn").length;
 const nr=Math.round((1-A.fun[4]/Math.max(1,A.fun[0]))*1000)/10;const g1=A.groups.find(g=>g.active&&g.sev<=2);
 return `<div class="statrow">${stat("Open alerts",N0(open.length),N0(crit.length)+" at Sev 1 or 2",crit.length?"crit":"")}${stat("Services affected",svcs.size+" of "+SVCREG.length,N0(A.groups.filter(g=>g.active).length)+" correlation groups")}${stat("Hosts critical or flapping",N0(bad),N0(warn)+" more in warning of "+N0(h.length)+" monitored",bad?"crit":"")}${stat("MTTD",P1(A.mttd)+" min","target 5 min · last 24 hours")}${stat("MTTA",P1(A.mtta)+" min","target 5 min · last 24 hours")}${stat("Noise reduction",P1(nr)+"%",N0(A.fun[0])+" raw events to "+N0(A.fun[4])+" actionable")}${stat("Alert fatigue index",A.fatigue,"0 calm, 100 burnout · "+P1(A.perResp)+" alerts per responder")}</div>
 ${chips(["m_mttd","m_mtta","m_noise","m_fatigue"])}
 ${g1?`<div class="obs-ban"><span class="pill bad">Incident candidate</span><span><b>${H(g1.al[0].msg.split(" (")[0].replace(/\d.*$/,"")||"Correlated alerts")}</b> ${H(SVN(g1.svcs[0]))}: ${g1.n} alerts from ${g1.cis.length} CIs fold into one group. ${H(g1.reason)}.</span><button class="btn" data-obs-grp="${g1.id}">Open group</button></div>`:""}
 ${card("Service status wall","Each tile is a service. Color is the worst open alert on any CI that supports it. Select a tile to see its CIs, alerts and impact.",wallTiles()+legend([["OK","--good-f"],["Warning","--warn-f"],["Critical","--bad-f"],["Flapping","--u3"],["Unknown (no data)","--faint"]]),`<span class="muted small">Refreshed ${hm(NOW_T)}</span>`)}
 <div class="grid g2">${card("Host groups","Hosts by class and environment, colored by status. Select a row to open the host list.",groupBars()+legend([["OK","--good-f"],["Warning","--warn-f"],["Flapping","--u3"],["Critical","--bad-f"],["Unknown","--faint"]]))}${card("Alerts per hour, last 24 hours","Stacked by severity. Each bar counts alerts after deduplication, not raw events.",hourBars())}</div>
 ${card("Top talkers","Which configuration items and rules produce the most raw events. These are the first candidates for tuning.",talkers())}
 <p class="muted small obs-note">${whyPop("Status color uses the highest severity among open, unsuppressed alerts that are not marked as false positives. A host with three or more state changes in 30 minutes shows as flapping.")} Standards followed: ${stdChip("sre","Golden signals and symptom-based alerting")} ${stdChip("itil5","Event management practice: detect, filter, correlate, trigger a response")}</p>`}

