/* ---------- correlation and noise ---------- */
function funnelHTML(){const A=computeAll(),f=A.fun,raw=f[0];const rows=[["Raw events","Every poll, log line and notification from Azure Monitor, Application Insights, Entra ID, Intune, network scans and the Lumen feed","--p5"],["Unique alerts","Duplicates with the same dedup key (rule, CI, state) folded into one alert with a count","--p4"],["After suppression","Maintenance windows and alerts marked as false positive removed","--p1"],["Correlation groups","Alerts on connected CIs within "+(O.corr.win)+" minutes folded into one group","--u3"],["Actionable groups","Groups that need a person or an agent: Sev 3 or worse, or three or more alerts","--w1"],["Incidents","Active groups at Sev 1 or 2 that become or link to an incident","--e1"]];
 return `<div class="obs-fun">${rows.map((r,i)=>{const v=f[i],w=Math.max(6,Math.log10(Math.max(2,v))/Math.log10(Math.max(10,raw))*100),pct=raw?v/raw*100:0,red=i?(f[i-1]?(1-v/f[i-1])*100:0):0;return `<div class="obs-fr"><div class="obs-fb" style="width:${w}%;background:var(${r[2]})"><b class="num" data-role="metric">${N0(v)}</b></div><div class="obs-ft"><b>${r[0]}</b><span class="muted small">${r[1]}</span><span class="small"><span class="num">${P2(pct)}%</span> of raw${i?` · <span class="num">${P1(red)}%</span> removed at this step`:""}</span></div></div>`}).join("")}</div><div class="formula">Noise reduction = 1 − actionable groups ÷ raw events = 1 − ${N0(f[4])} ÷ ${N0(raw)} = ${P1((1-f[4]/Math.max(1,raw))*100)}%. Compression to incidents = ${N0(raw)} ÷ ${Math.max(1,f[5])} = ${N0(raw/Math.max(1,f[5]))} to 1. Bar widths use a log scale because each step removes most of the volume.</div>`}
function groupCards(){const A=computeAll();return `<div class="obs-gl">${A.groups.slice(0,12).map(g=>`<article class="obs-gc ${g.active?"act":""}"><div class="row sp"><span class="row">${sevPill(g.sev)}<span class="pill mute">${g.id}</span>${g.topo?`<span class="pill info">topology</span>`:""}</span><span class="muted small">${fT(g.start)} · ${g.n} alert${g.n>1?"s":""} · ${N0(g.cnt)} events</span></div><h4><button class="obs-lk" data-obs-grp="${g.id}">${H(gTitle(g))}</button></h4><p class="muted small">${H(g.reason)}. Root cause candidate: <b>${H(ciName(g.rc))}</b>.</p><div class="row"><span class="pill ${g.active?"bad":"good"}">${g.active?"Active":"Cleared"}</span>${g.inc?`<span class="pill info">${H(g.inc.id)}</span>`:O.cand[g.id]?`<span class="pill info">Candidate raised</span>`:""}${g.cis.slice(0,3).map(c=>`<button class="chip" data-obs-ci="${H(c)}">${H(ciName(c))}</button>`).join("")}${g.cis.length>3?`<span class="muted small">+${g.cis.length-3} more</span>`:""}</div></article>`).join("")}</div>${A.groups.length>12?`<p class="muted small">Showing the 12 most severe of ${A.groups.length} groups. Use the alert stream to filter by group.</p>`:""}`}
function corrRules(){const C=O.corr;const R=[["topo","Topology","Alerts on CIs that are connected in the CMDB (up to two hops) join one group.",C.topo],["svc","Same service","Alerts on CIs of the same service join one group.",C.svc]];return `<div class="obs-cr">${R.map(r=>`<label class="row obs-crr"><span class="switch"><input type="checkbox" data-obs-corr="${r[0]}" ${r[3]?"checked":""}><span></span></span><span><b>${r[1]}</b><br><span class="muted small">${r[2]}</span></span></label>`).join("")}<label class="row obs-crr"><span class="small"><b>Time window</b><br><span class="muted">Only alerts within this many minutes of each other group together.</span></span><span class="row"><input type="range" class="rng" min="10" max="120" step="5" value="${C.win}" data-obs-corrwin><b class="num" id="obsCw">${C.win} min</b></span></label></div>`}
function corrPane(){const A=computeAll(),g=A.groups[0];return `<div class="statrow">${stat("Raw events",N0(A.fun[0]),"last 24 hours")}${stat("Correlation groups",N0(A.fun[3]),N0(A.groups.filter(x=>x.topo).length)+" folded by topology")}${stat("Actionable",N0(A.fun[4]),"need a person or an agent")}${stat("Incident candidates",N0(A.fun[5]),"Sev 1 or 2 and active",A.fun[5]?"crit":"")}</div>${chips(["m_noise"])}
 ${card("Noise reduction funnel","From every raw signal down to what a person must act on. Each step shows how much it removes.",funnelHTML())}
 <div class="grid g2" style="align-items:start">${card("Correlation rules","These settings change the groups immediately. Try turning topology off to see an alert storm unfold into separate groups.",corrRules())}${g&&g.topo?card("Largest group: dependency map",gTitle(g),topoSVG(g.cis,g.rc),`<button class="btn" data-obs-grp="${g.id}">Open group</button>`):card("Largest group","No topology group right now.","")}</div>
 ${card("Correlation groups","Each group is an incident candidate. The topology reason comes from the CMDB dependency graph, not from text matching.",groupCards())}`}

/* ---------- patterns ---------- */
function patterns(){const A=computeAll();if(patterns._k===A.key&&patterns._v)return patterns._v;const H7=A.hist.filter(a=>a.rule!=="EXT"&&a.from>=NOW_T-7*DAYMIN);const by={};H7.forEach(a=>{(by[a.rule+"|"+a.ci]=by[a.rule+"|"+a.ci]||[]).push(a)});
 const rec=[];Object.entries(by).forEach(([k,al])=>{if(al.length<3)return;const tod=al.map(a=>((a.from%DAYMIN)+DAYMIN)%DAYMIN);const m0=tod[0];const dev=tod.map(t=>{let d=t-m0;if(d>720)d-=DAYMIN;if(d<-720)d+=DAYMIN;return d});const mean=avg(dev),sdv=sd(dev),mt=((m0+mean)%DAYMIN+DAYMIN)%DAYMIN;const days=new Set(al.map(a=>Math.floor(a.from/DAYMIN))),dows=new Set(al.map(a=>dowOf(a.from)));
  const r=rOf(al[0].rule),c=ciOf(al[0].ci),reg=sdv<=35;const kind=!reg?"Irregular":dows.size===1&&al.length<=2?"Weekly":days.size>=5?"Daily":dows.size===1?"Weekly":"Repeating";
  const sp=SP.find(s=>s.ci===al[0].ci&&s.m===al[0].m&&s.tod!=null),win=O.wins.find(w=>w.cis.includes(al[0].ci));
  const cause=sp?"Scheduled job":al.some(a=>a.flaps>=1)&&!reg?"Flapping signal":al[0].m==="disk"?"Capacity growth":reg&&bh(mt)>.6?"Business hours load":reg?"Recurring batch or timer":"Unclassified";
  rec.push({k,rule:al[0].rule,rn:r?r.n:al[0].rule,ci:al[0].ci,cn:c?c.name:al[0].ci,n:al.length,kind,tod:mt,sd:sdv,reg,cause,al,fp:al.filter(a=>a.fp).length,when:(kind==="Daily"?"every day":kind==="Weekly"?"every "+DOWN[dowOf(al[0].from)]:"on "+days.size+" days")+" around "+hm(mt),dur:avg(al.map(a=>a.to-a.from)),win:!!win})});
 const flap=A.hist.filter(a=>a.flaps>=1&&a.from>=NOW_T-DAYMIN*3).sort((a,b)=>b.flaps-a.flaps);
 const hour=[...Array(24)].map(()=>0),wd=[0,0,0,0,0,0,0],grid=[...Array(7)].map(()=>Array(24).fill(0));H7.forEach(a=>{const h=Math.floor((((a.from%DAYMIN)+DAYMIN)%DAYMIN)/60);hour[h]++;wd[dowOf(a.from)]++;const di=clamp(Math.floor(a.from/DAYMIN)+6,0,6);grid[di][h]++});
 patterns._k=A.key;return patterns._v={rec:rec.sort((a,b)=>b.n-a.n),flap,hour,wd,grid,n:H7.length}}
function catBars(labels,vals,c,unit,hl){const W=720,Hh=150,L=34,mx=Math.max(1,...vals),bw=(W-L)/vals.length;let g="";for(let k=0;k<=2;k++){const y=10+(Hh-34)*(1-k/2);g+=`<line class="gridl" x1="${L}" x2="${W}" y1="${y}" y2="${y}"/><text class="ax" x="${L-6}" y="${y+4}" text-anchor="end">${Math.round(mx*k/2)}</text>`}
 vals.forEach((v,i)=>{const h=v/mx*(Hh-34),x=L+i*bw+3;g+=`<rect x="${x}" y="${Hh-24-h}" width="${bw-6}" height="${Math.max(1,h)}" rx="3" fill="var(${hl&&hl.includes(i)?"--e4":c})"><title>${labels[i]}: ${v} ${unit}</title></rect>`;if(vals.length<=8||i%3===0)g+=`<text class="ax" x="${x+(bw-6)/2}" y="${Hh-8}" text-anchor="middle">${labels[i]}</text>`});
 return `<div class="obs-heat"><svg viewBox="0 0 ${W} ${Hh}" role="img" aria-label="${H(unit)} by category" style="min-width:380px">${g}</svg></div>`}
function recTable(){const P=patterns();return btHTML({id:"obs_rec",h:380,rowH:56,key:"k",exportName:"recurring-alerts",facets:["kind","cause"],sort:{k:"n",d:-1},
 cols:[{k:"rn",label:"Pattern",wrap:1,val:r=>r.rn+" "+r.cn,fmt:r=>`<b class="obs-nm">${H(r.rn)}</b><span class="sub">${H(r.cn)}</span>`},{k:"kind",label:"Recurs",val:r=>r.kind,fmt:r=>`${r.kind==="Irregular"?`<span class="pill mute">Irregular</span>`:`<span class="pill info">${r.kind}</span>`}`},{k:"when",label:"When",val:r=>r.when,fmt:r=>H(r.when)},{k:"n",label:"Times in 7 days",val:r=>r.n,fmt:r=>`<b class="num">${r.n}</b>`},{k:"cause",label:"Likely cause",val:r=>r.cause,fmt:r=>H(r.cause)},{k:"fp",label:"Marked false positive",val:r=>r.fp,fmt:r=>r.fp+" of "+r.n},{k:"act",label:"Suggestion",val:r=>r.reg?1:0,fmt:r=>r.reg?(r.win?`<span class="pill good">Window exists</span>`:`<span class="pill warn">Suppress or schedule</span>`):`<span class="pill mute">Investigate</span>`}],
 rows:()=>P.rec,open:k=>patDrawer(k)})}
function patDrawer(k){const p=patterns().rec.find(x=>x.k===k);if(!p)return;const ser7=ser(p.ci,(rOf(p.rule)||{m:"cpu"}).m,"7d");const r=rOf(p.rule);
 openDrawer(`<div class="eyebrow">Recurring pattern · ${p.kind}</div><h2 class="obs-h2">${H(p.rn)} on ${H(p.cn)}</h2><div class="story" data-role="story">${aiChip({model:"Event Correlator",conf:p.reg?.9:.55,title:"Pattern analysis",note:"Time-of-day spread (standard deviation) and day coverage across seven days of alerts."})} Fires <b>${H(p.when)}</b>, ${p.n} times in 7 days, lasting about ${dur(p.dur)}. Spread of start time is ${Math.round(p.sd)} minutes, so it is ${p.reg?"highly regular":"not regular"}. Likely cause: <b>${H(p.cause)}</b>.</div>
 <div class="row obs-act">${p.reg&&!p.win?`<button class="btn primary" data-obs-patwin="${H(k)}">Create a daily suppression window</button>`:""}<button class="btn" data-obs-lab="${p.rule}">Test a threshold change</button><button class="btn" data-obs-ci="${H(p.ci)}">Open host</button></div>
 <div class="dfullgrid"><section class="card glass dfull2"><h3>Last 7 days with alerts marked</h3>${tsChart({series:[{l:p.cn,v:ser7.v,t0:ser7.t0,step:60}],marks:p.al.map(a=>({t:a.fired,l:fT(a.fired)})),thr:r&&r.kind==="static"?[{v:r.warn,l:"warn",c:"--warn-f"}]:[],fmt:MET[(r||{m:"cpu"}).m].fmt,h:220,min:(r||{}).m==="avail"?90:0})}</section>
 <section class="card glass dfull2"><h3>Occurrences</h3>${lrHTML({id:"obs_pat_"+k,limit:8,groups:[{key:"o",label:"Alerts ("+p.al.length+")",rows:p.al.map(a=>({id:a.id,t:fT(a.fired)+" "+a.msg,sub:a.state+" · "+dur(a.to-a.from)+" long",tag:SEVN[a.sev][0],st:a.fp?"mute":SEVN[a.sev][1],go:()=>alertDrawer(a.id)}))}]})}</section></div>`)}
function flapTable(){const P=patterns();return P.flap.length?`<div class="obs-fl">${P.flap.slice(0,8).map(a=>`<div class="obs-flr"><span class="row">${stDot("flap")}<b>${H(ciName(a.ci))}</b></span><span class="muted small">${H(a.msg)}</span><span class="row"><span class="pill info">${a.flaps+1} episodes</span><span class="muted small">${fT(a.from)} to ${a.active?"now":hm(a.to)}</span><button class="btn quiet" data-obs-hyst="${H(a.rule)}">Add hysteresis</button></span></div>`).join("")}</div>`:empty("No flapping","No signal changed state three or more times in 30 minutes.")}
function patPane(){const P=patterns(),A=computeAll(),pk=P.hour.indexOf(Math.max(...P.hour)),wk=(P.wd[1]+P.wd[2]+P.wd[3]+P.wd[4]+P.wd[5])/5,we=(P.wd[0]+P.wd[6])/2;const regn=P.rec.filter(r=>r.reg).length;
 const rows=[...Array(7)].map((_,i)=>{const t=(i-6)*DAYMIN;return dlab(t)+" "+DOWN[dowOf(t)]});
 return `<div class="statrow">${stat("Alerts analyzed",N0(P.n),"last 7 days, after deduplication")}${stat("Recurring patterns",N0(P.rec.length),N0(regn)+" are on a regular schedule")}${stat("Flapping signals",N0(P.flap.length),"in the last 3 days",P.flap.length?"crit":"")}${stat("Busiest hour",String(pk).padStart(2,"0")+":00",P.hour[pk]+" alerts started in this hour")}${stat("Weekday vs weekend",P1(wk/Math.max(.1,we))+" to 1","alerts per day, load-driven")}</div>
 <div class="grid g2" style="align-items:start">${card("When alerts start","Each cell counts alerts that started in that hour of that day. A bright column is a scheduled job; a bright block is a real outage.",heat({cols:[...Array(24)].map((_,i)=>String(i).padStart(2,"0")),every:3,rows,data:P.grid,cw:24,label:"Alert heat map by day and hour"})+legend([["Many alerts started","--bad-f"]]))}${card("Seasonality","Alerts by hour of day (left) and by weekday (right) over seven days. Weekday peaks follow editors working; night peaks are batch jobs.",catBars([...Array(24)].map((_,i)=>String(i).padStart(2,"0")),P.hour,"--p4","alerts",[pk])+catBars(DOWN,P.wd,"--u3","alerts"))}</div>
 ${card("Flapping detector","A signal that goes up and down quickly pages people over and over. These alerts were merged by flap detection (gaps under 30 minutes). Hysteresis makes a rule hold its state for longer before it changes.",flapTable())}
 ${card("Recurring alerts","Alerts that repeat on the same CI. Regular ones are almost always jobs, backups or patches: schedule a window or fix the cause. Irregular ones need investigation.",recTable())}`}

/* ---------- false positives ---------- */
function fpStats(){const A=computeAll();const rows=O.rules.map(r=>{const al=A.hist.filter(a=>a.rule===r.id&&!a.sup);const fp=al.filter(a=>a.fp).length;return {id:r.id,n:r.n,own:r.own,total:al.length,fp,rate:al.length?fp/al.length*100:0,prec:al.length?(1-fp/al.length)*100:100,r}}).filter(x=>x.total>0||true);return rows}
let SGC=null;
function suggestions(){const A=computeAll();if(SGC&&SGC.k===A.key+"|"+Object.keys(O.sg||{}).length)return SGC.v;O.sg=O.sg||{};const out=[];const P=patterns();
 P.rec.forEach(p=>{if(O.sg["W-"+p.k])return;const fpr=p.fp/p.n;if(p.reg&&!p.win&&(fpr>=.4||p.n>=4)&&p.al.every(a=>a.lvl==="warn"||fpr>=.5)){const c=clamp(.5+.28*fpr+.04*Math.min(5,p.n)+.1*(p.sd<20?1:0),0,.97);const start=Math.max(0,Math.round(p.tod-10)),end=Math.min(1439,Math.round(p.tod+p.dur+10));out.push({id:"W-"+p.k,type:"window",rule:p.rule,ci:p.ci,conf:c,from:start,to:end,n:p.n,fp:p.fp,title:"Suppress "+p.rn+" on "+p.cn+" between "+hm(start)+" and "+hm(end),why:"It fired "+p.n+" times in 7 days at the same time ("+p.when+")"+(p.fp?"; "+p.fp+" were marked as false positive or expected":"")+". No crit-level peaks fall outside this window.",before:p.n,after:0,p})}});
 O.rules.forEach(r=>{if(!r.on||r.kind!=="static"||O.sg["F-"+r.id])return;const al=A.hist.filter(a=>a.rule===r.id&&!a.sup);const fl=al.filter(a=>a.flaps>=1);if(fl.length>=2){const nr=Object.assign({},r,{forMin:r.forMin+10});const after=countEp(nr);out.push({id:"F-"+r.id,type:"hyst",rule:r.id,conf:clamp(.55+.07*fl.length,0,.95),n:al.length,fp:0,title:"Hold "+r.n+" for "+nr.forMin+" minutes before alerting",why:fl.length+" of "+al.length+" alerts flapped. A longer duration absorbs short blips.",before:al.length,after:after,patch:{forMin:nr.forMin}})}});
 O.rules.forEach(r=>{if(!r.on||r.kind!=="static"||O.sg["T-"+r.id]||r.op==="<")return;const al=A.hist.filter(a=>a.rule===r.id&&!a.sup&&a.lvl==="warn");const fpr=al.filter(a=>a.fp).length/Math.max(1,al.length);if(al.length>=4&&fpr>=.25){const th=r.warn*(r.m==="err"?1.5:1.1);const nr=Object.assign({},r,{warn:th});out.push({id:"T-"+r.id,type:"thr",rule:r.id,conf:clamp(.5+.4*fpr,0,.9),n:al.length,fp:Math.round(fpr*al.length),title:"Raise the warning threshold of "+r.n+" to "+MET[r.m].fmt(th),why:Math.round(fpr*100)+"% of its warnings were false positives.",before:al.length,after:countEp(nr),patch:{warn:th}})}});
 SGC={k:A.key+"|"+Object.keys(O.sg).length,v:out.sort((a,b)=>b.conf-a.conf)};return SGC.v}
const countEp=r=>{let n=0;CIREG.forEach(c=>{if(inCls(r,c)&&metsOf(c).includes(r.m))n+=episodes(r,c,NOW_T-7*DAYMIN,NOW_T,10).filter(e=>!e.sup).length});return n};
function sgCard(s){const r=rOf(s.rule);return `<article class="obs-sg"><div class="row sp"><span class="row"><span class="pill ${s.conf>=.85?"good":s.conf>=.7?"info":"warn"}">Confidence ${Math.round(s.conf*100)}%</span><span class="pill mute">${s.type==="window"?"Suppression window":s.type==="hyst"?"Hysteresis":"Threshold"}</span></span>${aiChip({model:"Event Correlator",conf:s.conf,title:"Suppression suggestion",note:"Based on seven days of alerts, your false positive marks and how regular the timing is."})}</div><h4>${H(s.title)}</h4><p class="muted small">${H(s.why)}</p><div class="row obs-pv"><span class="stat"><small>Alerts in 7 days now</small><span class="num">${s.before}</span></span><span class="stat"><small>With this change</small><span class="num">${s.after}</span></span><span class="stat"><small>Removed</small><span class="num">${s.before?Math.round((1-s.after/s.before)*100):0}%</span></span></div><div class="row"><button class="btn primary" data-obs-sgok="${H(s.id)}">Accept</button><button class="btn" data-obs-sgno="${H(s.id)}">Reject</button>${r?`<button class="btn quiet" data-obs-lab="${r.id}">Open in threshold lab</button>`:""}</div></article>`}
function fpPane(){const A=computeAll(),st=fpStats(),sg=suggestions(),fpAll=A.hist.filter(a=>a.fp),tot=A.hist.filter(a=>!a.sup).length;SYNCM();const q=A.day.filter(a=>!a.fp&&!a.sup&&a.m!=="event").sort((a,b)=>b.fired-a.fired).slice(0,8);
 const T=btHTML({id:"obs_fp",h:340,rowH:46,key:"id",sort:{k:"rate",d:-1},cols:[{k:"n",label:"Alert rule",wrap:1,val:r=>r.n,fmt:r=>`<b class="obs-nm">${H(r.n)}</b><span class="sub">${r.id} · ${H(r.own)}</span>`},{k:"total",label:"Alerts, 7 days",val:r=>r.total,fmt:r=>N0(r.total)},{k:"fp",label:"False positives",val:r=>r.fp,fmt:r=>N0(r.fp)},{k:"rate",label:"False positive rate",val:r=>r.rate,fmt:r=>`<span class="rel-pbl"><span class="obs-pb"><u style="width:${Math.min(100,r.rate)}%;background:var(${r.rate>=25?"--bad-f":r.rate>=10?"--warn-f":"--good-f"})"></u></span> ${P1(r.rate)}%</span>`},{k:"prec",label:"Precision",val:r=>r.prec,fmt:r=>P1(r.prec)+"%"}],rows:()=>fpStats(),open:id=>ruleDrawer(id)});
 const marks=Object.entries(O.fpMark||{}).sort((a,b)=>b[1].at-a[1].at).slice(0,8);
 return `<div class="statrow">${stat("False positive rate",P1(A.fpRate)+"%",N0(fpAll.length)+" of "+N0(tot)+" alerts in 7 days")}${stat("Open suggestions",N0(sg.length),"awaiting your decision")}${stat("Alerts a suggestion would remove",N0(sum(sg,s=>s.before-s.after)),"over the last 7 days if all accepted")}${stat("Feedback marks",N0(Object.keys(O.fpMark).length),"people and agents teaching the rules")}</div>${chips(["m_fprate","m_noise"])}
 ${card("Suppression suggestions","Each suggestion shows how many of last week's alerts it would have removed, and its confidence. Nothing changes until you accept it.",sg.length?`<div class="obs-sgl">${sg.map(sgCard).join("")}</div>`:empty("No suggestions","Mark alerts as false positives and the event correlator will propose rules."))}
 <div class="grid g2" style="align-items:start">${card("Review queue","Newest alerts. Tell the rules whether each was worth a person's time. This feedback is what the suggestions learn from.",`<div class="obs-rq">${q.map(a=>`<div class="obs-rqr"><span class="row">${sevPill(a.sev)}<button class="obs-lk" data-obs-alert="${a.id}">${H(a.msg.split(" (")[0])}</button></span><span class="muted small">${H(ciName(a.ci))} · ${fT(a.fired)}</span><span class="row"><button class="btn quiet" data-obs-valid="${H(a.id)}">Useful</button><button class="btn quiet" data-obs-fp="${H(a.id)}">False positive</button></span></div>`).join("")}</div>`)}${card("Recent feedback","Who marked what, and why.",marks.length?`<div class="obs-rq">${marks.map(([k,m])=>{const p=k.split("|");return `<div class="obs-rqr"><span><b>${H(ciName(p[1]))}</b> <span class="muted small">${H((rOf(p[0])||{n:p[0]}).n)} · ${fT(+p[2])}</span></span><span class="muted small">${H(m.kind)}: ${H(m.why)}</span><span>${resp(m.by)}</span></div>`}).join("")}</div>`:empty("No feedback yet"))}</div>
 ${card("False positive rate by rule","Precision is the share of alerts that were real. A rule below 80% is costing responders attention for nothing.",T)}`}

/* ---------- thresholds, threshold lab, maintenance windows ---------- */
const KINDN={static:"Static threshold",baseline:"Dynamic baseline",anomaly:"Anomaly detection"};
const winN=w=>w.kind==="daily"?"Every day "+hm(w.from)+" to "+hm(w.to):w.kind==="weekly"?"Every "+DOWN[w.dow]+" "+hm(w.from)+" to "+hm(w.to):"Once, "+fT(w.from)+" to "+fT(w.to);
const winActive=w=>{if(!w.on)return false;const t=NOW_T,md=t%DAYMIN;return w.kind==="daily"?md>=w.from&&md<=w.to:w.kind==="weekly"?dowOf(t)===w.dow&&md>=w.from&&md<=w.to:t>=w.from&&t<=w.to};
