/* ---------- SLOs, burn rates, synthetic checks, uptime, coverage ---------- */
function defSLO(){return [
 {id:"SL1",n:"Portal readers can load pages",svc:"svc_portal",tgt:99.9,sli:"Share of 5-minute periods with error rate under 2% and p95 latency under 3 seconds",own:"Tom Becker",good:[{ci:"ci_por4",m:"err",op:"<",th:2},{ci:"ci_por4",m:"lat",op:"<",th:3000}]},
 {id:"SL2",n:"Portal p95 latency under 2 seconds",svc:"svc_portal",tgt:99,sli:"Share of 5-minute periods with p95 latency under 2 seconds",own:"Tom Becker",good:[{ci:"ci_por4",m:"lat",op:"<",th:2000}]},
 {id:"SL3",n:"Editors can save drafts",svc:"svc_cod",tgt:99.9,sli:"Share of 5-minute periods with error rate under 2% and p95 latency under 3 seconds on the Codification Platform",own:"Priya Shah",good:[{ci:"ci_cod4",m:"err",op:"<",th:2},{ci:"ci_cod4",m:"lat",op:"<",th:3000}]},
 {id:"SL4",n:"Search index is fresh",svc:"svc_search",tgt:99.5,sli:"Share of 5-minute periods with indexer queue depth under 5,000 on both indexers",own:"Marco Ellis",good:[{ci:"ci_sea0",m:"queue",op:"<",th:5000},{ci:"ci_sea1",m:"queue",op:"<",th:5000}]},
 {id:"SL5",n:"Search API answers in under 1.5 seconds",svc:"svc_search",tgt:99.5,sli:"Share of 5-minute periods with search p95 latency under 1.5 seconds",own:"Marco Ellis",good:[{ci:"ci_sea2",m:"lat",op:"<",th:1500}]},
 {id:"SL6",n:"Sign-in works (Entra ID and MFA)",svc:"svc_id",tgt:99.95,sli:"Share of 5-minute periods with the MFA service available",own:"Rina Okafor",good:[{ci:"ci_mfa",m:"avail",op:">",th:99.5}]},
 {id:"SL7",n:"Lease postings complete",svc:"svc_erp",tgt:99.5,sli:"Share of 5-minute periods with posting latency under 3 seconds and the database disk under 95%",own:"Avery Chen",good:[{ci:"ci_erp2",m:"lat",op:"<",th:3000},{ci:"ci_erp1",m:"disk",op:"<",th:95}]},
 {id:"SL8",n:"Remote access (VPN) is up",svc:"svc_net",tgt:99.5,sli:"Share of 5-minute periods with VPN gateway availability above 98%",own:"Sam Patel",good:[{ci:"ci_vpn",m:"avail",op:">",th:98}]}]}
O.slos=O.slos||defSLO();O.slo={sel:"SL1"};
const SLC={};
function sloCalc(s){const k=s.id+JSON.stringify(s.good);if(SLC[k])return SLC[k];const N=8640,t0=NOW_T-N*5+5,bad=new Uint8Array(N);for(let i=0;i<N;i++){const t=t0+i*5;let g=true;for(const c of s.good){const v=val(c.ci,c.m,t);if(c.op==="<"?!(v<c.th):!(v>c.th)){g=false;break}}bad[i]=g?0:1}
 const allowed=(1-s.tgt/100)*N,cum=[];let c=0;for(let i=0;i<N;i++){c+=bad[i];cum.push(c)}const used=c,sli=(1-used/N)*100,left=(1-used/Math.max(.001,allowed))*100;
 const frac=(m)=>{const n=Math.round(m/5);let b=0;for(let i=N-n;i<N;i++)b+=bad[i];return b/n};const br=m=>frac(m)/Math.max(1e-9,1-s.tgt/100);
 const daily=[],remain=[];for(let d=0;d<30;d++){const a=d*288,b=(d+1)*288;let x=0;for(let i=a;i<b;i++)x+=bad[i];daily.push((1-x/288)*100);remain.push((1-cum[b-1]/Math.max(.001,allowed))*100)}
 const W=[[60,5,14.4,"Page on-call now","2% of the budget in 1 hour"],[360,30,6,"Page on-call now","5% of the budget in 6 hours"],[1440,120,3,"Open a ticket and watch","10% of the budget in 1 day"],[4320,360,1,"Open a ticket","10% of the budget in 3 days"]].map(w=>({long:w[0],short:w[1],f:w[2],act:w[3],mean:w[4],bl:br(w[0]),bs:br(w[1]),fire:br(w[0])>=w[2]&&br(w[1])>=w[2]}));
 const badMin=used*5,allowedMin=allowed*5,sinceFail=(()=>{let i=N-1;while(i>=0&&bad[i])i--;return (N-1-i)*5})();
 return SLC[k]={sli,left,used:badMin,allowed:allowedMin,daily,remain,W,burn1:br(60),burn6:br(360),bad:bad,ongoing:bad[N-1]===1,sinceFail}}
const sloSt=s=>{const c=sloCalc(s);return c.left<=0?"bad":c.left<30||c.W.some(w=>w.fire)?"warn":"good"};
const sloLeftF=sid=>{const a=O.slos.filter(s=>s.svc===sid).map(s=>sloCalc(s).left);return a.length?Math.min(...a):100};
function sloPane(){const sel=O.slos.find(s=>s.id===O.slo.sel)||O.slos[0],c=sloCalc(sel);const inb=O.slos.filter(s=>sloCalc(s).left>0).length;METRICS.m_slobudget.cur=Math.round(inb/O.slos.length*100);
 const firing=O.slos.flatMap(s=>sloCalc(s).W.filter(w=>w.fire).map(w=>({s,w})));
 const cards=`<div class="grid g3 obs-slog">${O.slos.map(s=>{const k=sloCalc(s),st=sloSt(s);return `<button class="card glass obs-slo ${s.id===sel.id?"on":""}" data-obs-slo="${s.id}" aria-pressed="${s.id===sel.id}"><div class="row sp"><span class="pill ${st}">${st==="good"?"Inside budget":st==="warn"?"Burning fast":"Budget spent"}</span><span class="muted small">${s.tgt}% over 30 days</span></div><b>${H(s.n)}</b><span class="muted small">${SVN(s.svc)}</span><div class="row sp"><span><span class="num" data-role="metric">${P2(k.sli)}%</span> <span class="muted small">SLI</span></span><span><span class="num" data-role="metric">${k.left<=0?"0":Math.round(k.left)}%</span> <span class="muted small">budget left</span></span></div>${spark(k.remain.map(v=>Math.max(-50,v)),230,28,col(st==="good"?"--good-f":st==="warn"?"--warn-f":"--bad-f"))}</button>`}).join("")}</div>`;
 const burn=`<div class="tscroll"><table><thead><tr><th>Alert window</th><th>Burn rate needed</th><th>Now (long / short)</th><th>Means</th><th>Action</th><th>State</th></tr></thead><tbody>${c.W.map(w=>`<tr><td>${w.long>=1440?w.long/1440+" d":w.long>=60?w.long/60+" h":w.long+" min"} and ${w.short>=60?w.short/60+" h":w.short+" min"}</td><td class="num">${w.f}×</td><td class="num">${P1(w.bl)}× / ${P1(w.bs)}×</td><td>${H(w.mean)}</td><td>${H(w.act)}</td><td>${w.fire?`<span class="pill bad">Firing</span>`:`<span class="pill good">Quiet</span>`}</td></tr>`).join("")}</tbody></table></div><div class="formula">Burn rate = (bad share of the window) ÷ (1 − target) = bad share ÷ ${P2(100-sel.tgt)}%. A burn rate of 1 spends exactly the whole budget by the end of the 30 days. An alert needs both the long and the short window above its factor, so it fires fast and stops fast.</div>`;
 const T=btHTML({id:"obs_slot",h:320,rowH:52,key:"id",cols:[{k:"n",label:"SLO",wrap:1,val:r=>r.n,fmt:r=>`<b class="obs-nm">${H(r.n)}</b><span class="sub">${r.id} · ${H(SVN(r.svc))}</span>`},{k:"tgt",label:"Target",val:r=>r.tgt,fmt:r=>r.tgt+"%"},{k:"sli",label:"SLI, 30 days",val:r=>r.sli,fmt:r=>P2(r.sli)+"%"},{k:"left",label:"Budget left",val:r=>r.left,fmt:r=>`<span class="pill ${r.st}">${r.left<=0?"spent":Math.round(r.left)+"%"}</span>`},{k:"burn",label:"Burn rate, 1 h",val:r=>r.burn,fmt:r=>P1(r.burn)+"×"},{k:"own",label:"Owner",val:r=>r.own,fmt:r=>resp(r.own)}],rows:()=>O.slos.map(s=>{const k=sloCalc(s);return {id:s.id,n:s.n,svc:s.svc,tgt:s.tgt,sli:k.sli,left:k.left,burn:k.burn1,own:s.own,st:sloSt(s)}}),open:id=>{O.slo.sel=id;render()}});
 return `<div class="statrow">${stat("SLOs inside budget",inb+" of "+O.slos.length,Math.round(inb/O.slos.length*100)+"% · target 90%",inb<O.slos.length?"crit":"")}${stat("Burn alerts firing",firing.length,firing.length?firing.map(f=>f.s.id).filter((x,i,a)=>a.indexOf(x)===i).join(", "):"none")}${stat("Worst SLI",P2(Math.min(...O.slos.map(s=>sloCalc(s).sli)))+"%","30 day window")}${stat("Budget spent by incidents",N0(sum(O.slos,s=>sloCalc(s).used))+" bad min","across all SLOs")}</div>${chips(["m_slobudget"])}
 ${card("Service level objectives","An SLO is a promise measured on what users feel. The error budget is what you may miss. Select one to see its budget and multi-window burn rate alerts.",cards,`<button class="btn primary" data-obs-newslo>New SLO</button>`)}
 <div class="grid g2" style="align-items:start">${card(esc(sel.n)+": error budget","Budget remaining over the last 30 days. Below zero means the promise was broken. "+(c.left<=0?"It was spent by the incident that started at 09:08 today.":"Remaining budget is shown as a percentage of the allowed bad minutes."),tsChart({series:[{l:"Budget remaining",v:c.remain.map(v=>Math.max(-100,v)),t0:NOW_T-29*DAYMIN,step:DAYMIN,c:c.left>30?"--good-f":c.left>0?"--warn-f":"--bad-f"}],thr:[{v:0,l:"budget spent",c:"--bad-f"}],min:-100,max:100,fmt:v=>Math.round(v)+"%",h:240,label:"Error budget remaining"}),fchip("m_slobudget"))}${card("Definition","What counts as good, and who owns it.",`<dl class="kv"><dt>Service</dt><dd>${svcLink(sel.svc)}</dd><dt>Objective</dt><dd>${sel.tgt}% over 30 days</dd><dt>Good period</dt><dd>${H(sel.sli)}</dd><dt>Allowed bad time</dt><dd class="num">${N0(c.allowed)} minutes (${P1(c.allowed/60)} hours)</dd><dt>Bad time so far</dt><dd class="num">${N0(c.used)} minutes</dd><dt>Owner</dt><dd>${resp(sel.own)}</dd><dt>Current state</dt><dd>${c.ongoing?`<span class="pill bad">Bad right now</span>`:`<span class="pill good">Good for ${dur(c.sinceFail)}</span>`}</dd></dl><div class="row"><button class="btn" data-obs-imp="${sel.svc}" data-obs-isvc="1">Impact analysis</button><button class="btn quiet" data-obs-nav="itsm_inc">Incidents</button></div>`)}</div>
 ${card("Multi-window, multi-burn-rate alerts","The standard SRE pattern: page quickly for fast burns, ticket for slow burns, and avoid pages for blips.",burn)}
 ${card("All SLOs","Sorted by what needs attention.",T)}`}
