 if(d.obsAddparam){paramForm(scOf(d.obsAddparam));return}
 if(d.obsPub){pubForm(scOf(d.obsPub));return}
 if(d.obsDiscard){const id=d.obsDiscard,i=O.sc.findIndex(s=>s.id===id);if(O.draft&&O.draft[id]){O.sc[i]=O.draft[id];delete O.draft[id];audit("discarded runbook changes",id);toast("Changes discarded","good");render()}return}
 if(d.obsPromote){const s=scOf(d.obsPromote);s.lvl=Math.min(4,s.lvl+1);s.hist.unshift([s.ver,TODAY,who_(),"Automation level raised to "+s.lvl+" ("+LVL[s.lvl][1]+")"]);audit("promoted standard change",s.id+" to level "+s.lvl);toast(s.id+" is now level "+s.lvl+": "+LVL[s.lvl][1],"good");render();return}
 if(d.obsSlo){O.slo.sel=d.obsSlo;render();return}if(d.obsNewslo!==undefined){sloForm();return}
 if(d.obsSyn){synDrawer(d.obsSyn);return}
 if(d.obsSynrun){const s=O.syn.find(x=>x.id===d.obsSynrun);if(s){const r=s.loc.map(l=>l+": "+(synRes(s,l,NOW_T).ok?"pass":"FAIL")+" "+synRes(s,l,NOW_T).ms+" ms");audit("ran synthetic check",s.id);toast(s.n+" "+r.join(", "),r.some(x=>/FAIL/.test(x))?"warn":"good")}return}
 if(d.obsNewsyn!==undefined){synForm();return}
 if(d.obsCovdem){const n=d.obsCovdem;if(typeof addDemand==="function"){addDemand({title:"Observability gap: "+n,reason:"The observability coverage review lists this as missing or partial for a mid-size business.",source:"Observability coverage",cost:0,service:"",kind:"Enhancement"});toast("Demand raised for "+n,"good")}else toast("Demand raised (the PPM module records it when available)","info");audit("raised demand for observability gap",n);return}
 if(d.obsCovacc){const n=d.obsCovacc;openForm({id:"obs_cova",title:"Accept this gap",story:"Accepting a gap means you will not build or buy this now. It counts as covered in the score and the reason is kept for the audit.",submit:"Accept gap",fields:[{k:"why",label:"Reason",type:"longtext",req:true,ph:"Azure Log Analytics already retains this for 2 years"}],onSubmit:v=>{O.cov=O.cov||{};O.cov[n]="accepted";audit("accepted observability gap",n+": "+v.why);render();return {toast:"Gap accepted",audit:n}}});return}
 if(d.obsExpm){O.exp.m=d.obsExpm;render();return}if(d.obsExprg){O.exp.rg=d.obsExprg;render();return}
 if(d.obsAddtile!==undefined){tileForm(d.obsAddtile);return}
 if(d.obsNewrulefrom){ruleForm({m:d.obsNewrulefrom});return}
 if(d.obsDsel){O.dashSel=d.obsDsel;O.edit=false;render();return}
