PROC.reg("itom_evt",{title:"How an event becomes an incident",std:["itil5","sre"],steps:[{n:"Detect",d:"Monitoring sources and rules raise events.",who:"auto",owner:"Ops team",sla:"Under 5 min (MTTD)",in:"Metrics, logs, synthetic checks",out:"Raw event"},{n:"Deduplicate and filter",d:"Same rule, CI and state become one alert; windows and false positives are removed.",who:"auto",in:"Raw events",out:"Unique alerts"},{n:"Correlate",d:"Alerts on connected CIs form one group with a root cause candidate.",who:"agent",owner:"Event Correlator",out:"Correlation group"},{n:"Triage",d:"A person or an agent acknowledges, classifies and picks the response.",who:"agent",owner:"Triage Agent",sla:"Under 5 min (MTTA)"},{n:"Automate or escalate",d:"A pre-approved standard change runs, or on-call is paged.",who:"gate",owner:"Ops team"},{n:"Incident, problem, change",d:"Group becomes an incident; recurring causes go to problem management.",who:"human",owner:"Tom Becker"},{n:"Learn",d:"False positive feedback tunes rules; patterns feed problems.",who:"agent",owner:"Event Correlator"}]});
PROC.reg("obs_dash",{title:"How a metric reaches a dashboard",std:["sre"],steps:[{n:"Collect",d:"Agents, Azure Monitor, SNMP and logs feed the metric model.",who:"auto"},{n:"Store and roll up",d:"Raw samples are rolled up by minute, 15 minutes and hour.",who:"auto"},{n:"Explore",d:"Compare any CIs and metrics.",who:"human",owner:"Ops team"},{n:"Build a dashboard",d:"Pick tiles, drag them into place, save.",who:"human",owner:"Platform team"},{n:"Share and review",d:"Dashboards are reviewed monthly in the service review.",who:"human",owner:"Tom Becker"}]});
PROC.reg("itom_slo",{title:"How an SLO is run",std:["sre","itil5"],steps:[{n:"Define the SLI",d:"What counts as a good 5-minute period.",who:"human",owner:"Service owner"},{n:"Set the objective",d:"For example 99.9% over 30 days.",who:"gate",owner:"Service owner"},{n:"Measure",d:"Good and bad periods counted from the metric model.",who:"auto"},{n:"Burn rate alerts",d:"Multi-window rules page or ticket.",who:"auto",sla:"5 min to 6 h windows"},{n:"Spend the budget wisely",d:"When it is spent, risky changes need approval.",who:"gate",owner:"Change manager"},{n:"Review",d:"SLOs are reviewed quarterly.",who:"human",owner:"Ops team"}]});
PROC.reg("itom_run",{title:"From alert to action",std:["itil5","sre"],steps:[{n:"Alert matches a rule",d:"Rules run in priority order.",who:"auto"},{n:"Guardrails",d:"Pre-approved, blast radius, rate, freeze, error budget, rollback.",who:"gate",owner:"Change management"},{n:"Agent diagnoses",d:"Agentic workflows gather evidence and propose.",who:"agent",owner:"Ops Agent"},{n:"Approval",d:"A person approves when risk or policy needs it.",who:"gate",owner:"Service owner"},{n:"Standard change record",d:"An auto-approved change is created.",who:"auto",owner:"Nia Brooks"},{n:"Run and validate",d:"Playbook steps, then validation; rollback on failure.",who:"auto"},{n:"Audit",d:"Every step and approval is logged.",who:"auto"}]});
PROC.reg("obs_std",{title:"Life of a standard change",std:["itil5"],steps:[{n:"Propose",d:"An owner writes the SOP, validation and rollback.",who:"human",owner:"Service owner"},{n:"CAB review",d:"The Change Advisory Board pre-approves the scope.",who:"gate",owner:"Nia Brooks",sla:"Next CAB"},{n:"Use",d:"People, scripts or agents run it, each run a change record.",who:"agent",owner:"Ops Agent"},{n:"Measure",d:"Success rate and runs build evidence.",who:"auto"},{n:"Promote",d:"Higher automation level once evidence is strong.",who:"gate",owner:"Nia Brooks"},{n:"Review yearly",d:"Pre-approval expires unless renewed.",who:"human",owner:"Nia Brooks"}]});
