function whyTier(t){return `<span class="ppl-tierkey t${t}"><i class="ppl-ai">${ico("sparkle")}</i><b>${TIERS[t].n}</b><small>${TIERS[t].s}</small></span>`}
function riskOK(a,i){if(i.risk==="high")return ["no","High-risk work (money, contracts or access) stays with people. Agents never take it."];if(a.tier===1&&i.risk!=="low")return ["no","Tier 1 agents only suggest and draft. This item needs someone to act, so assign its owner-of-record instead."];
 if(!a.scope.includes(i.tag)&&!(i.tag==="schedule"&&a.scope.includes("projects"))&&!(i.tag==="docs"&&a.scope.some(s=>["knowledge","docs","reports"].includes(s))))return ["no","Outside "+a.n+"'s scope ("+a.scope.join(", ")+"). The gateway would block it."];
 if(a.tier===2)return ["ok","Allowed. A person approves each step, so "+nameOf(a.owner)+" gets approval requests."];return ["ok","Allowed within its limits."]}
function effect(item,e){const w=item.w0,before=util(e,w),after=util(e,w,item);let rule=null;if(e.kind==="agent")rule=riskOK(e,item);return {w,before,after,over:after!=null&&after>100,rule}}
const effText=f=>f.before==null?`${pctT(f.after)} (on leave that week)`:`${pctT(f.before)} → ${pctT(f.after)}`;
function bestAlt(item,skip){const tag=item.tag;const c=st.people.filter(p=>p.id!==skip&&p.type!=="vendor"&&p.kind==="human").map(p=>({p,u:util(p,item.w0,item)})).filter(x=>x.u!=null&&x.u<=100).sort((a,b)=>a.u-b.u);return c[0]}
