const PATHS0=[{id:"LP1",t:"New hire first week",c:["C1","C3","C6","C4"],a:"Everyone, within 5 days of starting"},{id:"LP2",t:"Editor certification",c:["C2","C8","C7"],a:"Standards editors before acceptance testing on Nov 13"},{id:"LP3",t:"Platform and operations access",c:["C5","C3","C9"],a:"Anyone with production access"},{id:"LP4",t:"AI champion",c:["C6","C7"],a:"One per team, supports peers"}];
st.courses=st.courses||seedCourses();st.paths=st.paths||PATHS0;st.enr=st.enr||{};st.nudges=st.nudges||{};st.tr=st.tr||{sel:"C3",mod:0,quiz:false,ans:{},cat:"All",xsel:0,done:{}};
const COURSE=id=>st.courses.find(c=>c.id===id);
const inAud=(c,p)=>c.aud.includes("All")||c.aud.includes(p.team)||c.aud.includes(p.role);
function seedStatus(p,c){const r=hash(p.id+c.id);if(daysTo(c.due)<=0){if(r<c.rate){const d=addD(c.due,-Math.floor(hash(p.id+c.id+"d")*28)-1);return {st:"done",due:c.due,done:d,score:Math.round(78+hash(p.id+c.id+"s")*21),exp:c.recur?addM(d,c.recur):null}}return r<c.rate+.07?{st:"progress",due:c.due,pct:Math.round(20+hash(p.id+"p")*60)}:{st:"todo",due:c.due,pct:0}}
 if(r<c.rate*.6){const d=addD(TODAY_ISO,-Math.floor(hash(p.id+c.id+"d")*20)-1);return {st:"done",due:c.due,done:d,score:Math.round(80+hash(p.id+c.id+"s")*19),exp:c.recur?addM(d,c.recur):null}}return r<.62?{st:"progress",due:c.due,pct:Math.round(20+hash(p.id+"p")*60)}:{st:"todo",due:c.due,pct:0}}
function ensureEnr(pid,fresh){const p=H(pid);if(!p)return;const E=st.enr[pid]=st.enr[pid]||{};st.courses.forEach(c=>{if(!E[c.id]&&inAud(c,p)){const e=fresh?{st:"todo",due:LP1(c.id)?addD(p.start||"2026-10-12",5):c.due,pct:0}:seedStatus(p,c);if(c.cert&&e.st!=="done"){const pd=hash(p.id+c.id+"cx")<.12?addD("2025-09-10",Math.floor(hash(p.id+"q")*20)):addD("2025-10-20",Math.floor(hash(p.id+c.id+"x")*60));e.prev=pd;e.exp=addM(pd,12)}E[c.id]=e}})}
const LP1=cid=>(st.paths[0].c||[]).includes(cid);
function ensureAll(){st.people.forEach(p=>ensureEnr(p.id))}
const overdueOf=pid=>Object.entries(st.enr[pid]||{}).filter(([cid,e])=>e.st!=="done"&&daysTo(e.due)<0).map(([cid,e])=>({c:COURSE(cid),e,days:-daysTo(e.due)}));
function trainStat(){ensureAll();let t=0,d=0;st.people.forEach(p=>Object.entries(st.enr[p.id]||{}).forEach(([cid,e])=>{const c=COURSE(cid);if(c.mand&&daysTo(e.due)<=0){t++;if(e.st==="done")d++}}));return {pct:t?d/t*100:100,t,d}}
const courseStat=c=>{ensureAll();let n=0,d=0,o=0,pr=0;st.people.forEach(p=>{const e=(st.enr[p.id]||{})[c.id];if(!e)return;n++;if(e.st==="done")d++;else{if(daysTo(e.due)<0)o++;if(e.st==="progress")pr++}});return {n,d,o,pr,pct:n?d/n*100:0}};
/* xAPI statement stream */
const VERBS={launched:"http://adlnet.gov/expapi/verbs/launched",progressed:"http://adlnet.gov/expapi/verbs/progressed",completed:"http://adlnet.gov/expapi/verbs/completed",passed:"http://adlnet.gov/expapi/verbs/passed",failed:"http://adlnet.gov/expapi/verbs/failed"};
function stmt(v,pid,cid,res,t){const p=H(pid),c=COURSE(cid);return {id:"b"+Math.floor(hash(pid+cid+v+(t||nowT()))*1e9).toString(16).padStart(8,"0")+"-5e1a-4c0f-9d7e-0f6a2c9d41ab",actor:{objectType:"Agent",name:p.n,mbox:"mailto:"+p.n.toLowerCase().replace(/[^a-z]+/g,".")+"@meridian.example"},verb:{id:VERBS[v],display:{"en-US":v}},object:{objectType:"Activity",id:"https://learn.meridian.example/courses/"+cid,definition:{type:"http://adlnet.gov/expapi/activities/course",name:{"en-US":c?c.t:cid}}},result:res||undefined,context:{platform:"Oukala Learning",extensions:{"https://oukala.example/ext/package":c?c.src:""}},timestamp:"2026-10-06T"+(t||new Date().toTimeString().slice(0,8))+"Z"}}
function emit(v,pid,cid,res){st.xapi.unshift(stmt(v,pid,cid,res));st.xapi=st.xapi.slice(0,40)}
if(!st.xapi){st.xapi=[];ensureAll();[["launched","lm","C3","08:02:11"],["progressed","lm","C3","08:09:40",{extensions:{"https://oukala.example/ext/progress":.6}}],["completed","lm","C3","08:21:05",{completion:true,duration:"PT19M",score:{scaled:.9}}],["passed","lm","C3","08:21:06",{success:true,score:{scaled:.9,raw:9,max:10}}],["launched","gn","C6","08:40:51"],["failed","gn","C6","08:55:13",{success:false,score:{scaled:.62}}]].forEach(x=>st.xapi.push(stmt(x[0],x[1],x[2],x[4],x[3])));st.xapi.reverse()}
const vclass=v=>({launched:"info",progressed:"mute",completed:"good",passed:"good",failed:"bad"}[v]||"mute");
/* parts */
const cidFmt=c=>`<span class="pill mute">${esc(c.id)}</span>`;
function courseCard(c){const s=courseStat(c),late=daysTo(c.due)<0;return `<button class="ppl-cc card glass" data-ppl-course="${c.id}" style="--cc:var(${CATC[c.cat]})"><span class="row"><span class="pill" style="background:color-mix(in srgb,var(--cc) 18%,transparent);color:var(--ink)">${esc(c.cat)}</span>${c.mand?'<span class="pill warn">Mandatory</span>':""}${c.src!=="Native"?`<span class="pill metric">${esc(c.src)}</span>`:""}</span><b>${esc(c.t)}</b><span class="muted small">${c.mins} min · ${c.mods.length} modules · pass mark ${c.pass}% · ${c.recur?"every "+c.recur+" months":"one time"}</span><span class="bar"><i style="width:${s.pct}%;background:${col(late&&s.pct<90?"--warn-f":"--good-f")}"></i></span><span class="row sp small"><span><b data-role="metric">${Math.round(s.pct)}%</b> done of ${s.n}</span><span class="${s.o?"":"muted"}" style="${s.o?"color:var(--bad);font-weight:700":""}">${s.o?s.o+" overdue":"due "+dFmt(c.due)}</span></span></button>`}
function catalogPane(){const f=st.tr.cat;const list=st.courses.filter(c=>f==="All"||c.cat===f);
 return `${card("Course catalog","Four families: compliance, security awareness, product training and AI safe use. Select a course for modules, audience and who is behind.",`<div class="row" style="margin-bottom:12px">${["All",...CATS].map(k=>`<button class="chip" data-ppl-cat="${k}" aria-pressed="${f===k}">${k}</button>`).join("")}</div><div class="grid g3">${list.map(courseCard).join("")}</div>`,`<button class="btn primary" data-ppl-design="1">Design a course</button>`)}
 ${card("Learning paths","Bundles of courses assigned together to a role or a moment such as a start date.",`<div class="grid g2">${st.paths.map(lp=>{const cs=lp.c.map(COURSE).filter(Boolean),ss=cs.map(courseStat),pct=ss.length?ss.reduce((a,s)=>a+s.pct,0)/ss.length:0;return `<div class="tile glass"><b>${esc(lp.t)}</b><span class="muted small" data-role="story">${esc(lp.a)}</span><div class="row">${cs.map(c=>`<button class="chip" data-ppl-course="${c.id}">${esc(c.t.length>28?c.t.slice(0,27)+"…":c.t)}</button>`).join("")}</div><span class="bar"><i style="width:${pct}%;background:${col("--p4")}"></i></span><span class="small muted">${Math.round(pct)}% average completion · ${cs.reduce((a,c)=>a+c.mins,0)} minutes total</span></div>`}).join("")}</div>`)}`}
function gridTrain(){const teams=[...new Set(st.people.map(p=>p.team))];const cols=st.courses;
 const cells=teams.map(t=>{const m=st.people.filter(p=>p.team===t);return `<div class="ppl-tr"><span class="ppl-hn"><b>${esc(t)}</b><small class="muted">${m.length}</small></span>${cols.map(c=>{const a=m.filter(p=>(st.enr[p.id]||{})[c.id]);if(!a.length)return `<span class="ppl-tc na" aria-label="not assigned">·</span>`;const d=a.filter(p=>st.enr[p.id][c.id].st==="done").length,pct=d/a.length*100,late=daysTo(c.due)<0;const col2=pct>=90?"--good-f":pct>=70?"--p5":late?"--bad-f":"--warn-f";return `<button class="ppl-tc" style="--cc:var(${col2})" data-ppl-cell2="${esc(t)}:${c.id}" aria-label="${esc(t)}, ${esc(c.t)}, ${Math.round(pct)}% complete">${Math.round(pct)}</button>`}).join("")}</div>`}).join("");
 return `<div class="ppl-heatwrap"><div class="ppl-tg"><div class="ppl-tr ppl-hh"><span></span>${cols.map(c=>`<b title="${esc(c.t)}">${esc(c.id)}</b>`).join("")}</div>${cells}</div></div><div class="legend-row" style="margin-top:10px">${[["--good-f","90%+"],["--p5","70 to 89%"],["--warn-f","under 70%, not yet due"],["--bad-f","under 70% and past due"]].map(([c,t])=>`<span><i class="sw" style="background:${col(c)}"></i>${t}</span>`).join("")}<span>${st.courses.map(c=>c.id+" "+esc(c.t.slice(0,22))).join(" · ")}</span></div>`}
function assignPane(){const ts=trainStat();
 return `${card("Completion by team and course",`${Math.round(ts.pct)}% of mandatory courses due to date are done (${ts.d} of ${ts.t}). Select a cell for names.`,gridTrain(),fchip("m_trainc"))}
 ${card("Assignments by role","Who has to take what, and by when. Changing an audience creates enrollments with the due date.",`<div class="tablewrap"><table><thead><tr><th>Course</th><th>Audience</th><th>Due</th><th>Enrolled</th><th>Done</th><th>Overdue</th><th></th></tr></thead><tbody>${st.courses.map(c=>{const s=courseStat(c);return `<tr data-nopick><td><b>${esc(c.t)}</b><span class="sub">${c.mand?"Mandatory":"Optional"} · ${esc(c.cat)}</span></td><td>${c.aud.map(a=>`<span class="pill mute">${esc(a)}</span>`).join(" ")}</td><td>${dFmt(c.due)}${daysTo(c.due)<0?' <span class="pill bad">closed</span>':""}</td><td class="num">${s.n}</td><td class="num">${s.d}</td><td class="num" style="${s.o?"color:var(--bad)":""}">${s.o}</td><td><button class="btn quiet" data-ppl-assigncourse="${c.id}">Assign</button></td></tr>`}).join("")}</tbody></table></div>`,`<button class="btn primary" data-ppl-assigncourse="">Assign a course</button>`)}`}
function certRows(){ensureAll();const r=[];st.people.forEach(p=>Object.entries(st.enr[p.id]||{}).forEach(([cid,e])=>{const c=COURSE(cid);if(c.cert&&e.exp)r.push({p,c,e,days:daysTo(e.exp)})}));return r.sort((a,b)=>a.days-b.days)}
function certPane(){const cr=certRows(),exp=cr.filter(x=>x.days<0),soon=cr.filter(x=>x.days>=0&&x.days<=60);
 return `${card("Certificates and expiry",`${exp.length} expired and ${soon.length} expire in the next 60 days. An expired privileged-access certificate removes production access until renewed.`,`<div class="tablewrap"><table><thead><tr><th>Person</th><th>Certificate</th><th>Expires</th><th>Days left</th><th>State</th><th></th></tr></thead><tbody>${cr.slice(0,14).map(x=>`<tr data-nopick><td><button class="chip" data-ppl-open="${x.p.id}">${esc(x.p.n)}</button></td><td>${esc(x.c.t)}</td><td>${dFmt(x.e.exp)}</td><td class="num">${x.days}</td><td><span class="pill ${x.days<0?"bad":x.days<=60?"warn":"good"}">${x.days<0?"Expired":x.days<=60?"Expiring":"Valid"}</span></td><td>${x.days<=60?`<button class="btn quiet" data-ppl-renew="${x.p.id}:${x.c.id}">Renew</button>`:""}</td></tr>`).join("")}</tbody></table></div>`)}`}
function nudgePane(){ensureAll();const rows=st.people.map(p=>({p,o:overdueOf(p.id)})).filter(x=>x.o.length).sort((a,b)=>Math.max(...b.o.map(z=>z.days))-Math.max(...a.o.map(z=>z.days)));const tot=rows.reduce((a,x)=>a+x.o.length,0);
 const sec3=rows.filter(x=>x.o.some(z=>z.c.id==="C3"));
 const lvl=d=>d>14?["bad","Access review"]:d>7?["warn","Copy manager"]:["info","Reminder"];
 return `${card("Overdue and nudges",`<b>${rows.length} people</b> have ${tot} overdue courses. Security awareness closed Oct 2 and ${sec3.length} people have not finished it. Learning Coach drafts a reminder, copies the manager after day 7 and asks for an access review after day 14.`,`<div class="needs">${rows.slice(0,10).map(x=>{const mx=Math.max(...x.o.map(z=>z.days)),[lc,lt]=lvl(mx),n=st.nudges[x.p.id]||0;return `<div class="need" style="grid-template-columns:auto 1fr auto"><i class="av" style="background:${col(x.p.c)};width:36px;height:36px;font-size:12px">${ini(x.p.n)}</i><div><b>${esc(x.p.n)} <span class="muted small">${esc(x.p.team)}</span></b><span class="muted small">${x.o.map(z=>esc(z.c.t.length>34?z.c.t.slice(0,33)+"…":z.c.t)+" ("+z.days+" days late)").join(" · ")}</span><span class="row" style="gap:6px"><span class="pill ${lc}">${lt}</span>${n?`<span class="pill mute">${n} nudge${n>1?"s":""} sent</span>`:""}</span></div><div class="act"><button class="btn" data-ppl-nudge="${x.p.id}:preview">Preview</button><button class="btn primary" data-ppl-nudge="${x.p.id}:send">Send</button></div></div>`}).join("")||empty("Nobody is overdue","")}</div>`,`<button class="btn primary" data-ppl-nudgeall="1">${ico("sparkle")} Send all reminders</button>`)}
 <div class="card glass"><div class="cardhead"><h3>Remediation ladder</h3><span class="muted small">What happens when a mandatory course is not finished</span></div><div class="ppl-ladder"><div><b>Day 1</b><span>Learning Coach sends a friendly reminder with a 10-minute link.</span></div><div><b>Day 8</b><span>The manager is copied. First Officer adds a calendar block.</span></div><div><b>Day 15</b><span>People office asks Entra ID access review to remove privileged roles until done.</span></div></div><div class="row" style="margin-top:12px">${fchip("m_trainc")}${aiChip({model:"Learning Coach",conf:.9,title:"Drafted reminders",src:["Enrollments","Due dates","Manager chain"],guards:["Drafts reminders only","Escalations are sent by a person","No performance data"]})}</div></div>`}
function nudgeDraft(p){const o=overdueOf(p.id);const mx=Math.max(0,...o.map(z=>z.days));return `Hi ${p.n.split(" ")[0]}, ${o.length>1?"you have "+o.length+" overdue courses":"your "+(o[0]?o[0].c.t:"course")+" is overdue"}. It takes about ${o.reduce((a,z)=>a+z.c.mins,0)} minutes in total and you can pick up where you left off. ${mx>7?"I have copied "+nameOf(p.mgr)+" so work can be planned around it. ":""}${mx>14?"If it is not done by Friday, privileged access will be reviewed. ":""}Thank you, Learning Coach on behalf of the People office.`}
function sendNudge(pid){const p=H(pid);st.nudges[pid]=(st.nudges[pid]||0)+1;audit("sent training nudge",p.n);toast("Reminder sent to "+p.n+(overdueOf(pid).some(z=>z.days>7)?" and "+nameOf(p.mgr):""),"good")}
function designForm(){openForm({id:"ppl_design",title:"Design a course",story:"Describe the course and Oukala builds the shell: modules, a quiz with a pass mark, who must take it and when it repeats. People in the audience get an enrollment right away.",submit:"Create course",
 fields:[{section:"Course"},{k:"t",label:"Title",type:"text",req:true,ph:"Handling embargoed drafts"},{k:"cat",label:"Category",type:"chips",req:true,opts:CATS},{k:"mods",label:"Modules (one per line)",type:"longtext",req:true,wide:true,ph:"Why it matters\nWhat good looks like",ai:{label:"Draft outline",fn:v=>GEN.join("\n")}},{k:"mins",label:"Minutes",type:"number",min:5,max:240,ph:"30"},
 {section:"Quiz and pass"},{k:"q",label:"Quiz questions",type:"range",min:3,max:20,step:1},{k:"pass",label:"Pass mark",type:"range",min:50,max:100,step:5,unit:"%"},
 {section:"Who and when"},{k:"aud",label:"Audience",type:"multi",req:true,opts:["All",...new Set(st.people.map(p=>p.team))]},{k:"recur",label:"Repeats",type:"chips",opts:[["0","Never"],["3","3 months"],["6","6 months"],["12","12 months"]]},{k:"due",label:"First due date",type:"date",req:true},{k:"mand",label:"Mandatory",type:"toggle"}],
 defaults:{q:8,pass:80,recur:"12",aud:[],mand:false,mins:30,due:"2026-11-30"},
 live:v=>{const el=document.getElementById("pplDsLive");if(!el)return;const n=(v.aud||[]).includes("All")?st.people.length:st.people.filter(p=>(v.aud||[]).includes(p.team)).length;const mods=String(v.mods||"").split("\n").filter(x=>x.trim());el.innerHTML=`<div class="ppl-eff small">${mods.length} modules, ${v.q} questions, pass at ${v.pass}%. ${n} people would be enrolled. ${v.mand&&v.recur&&+v.recur?"Completion counts toward mandatory training and repeats every "+v.recur+" months.":""}</div>`},extra:'<div id="pplDsLive" style="flex-basis:100%"></div>',
 onSubmit:v=>{const id="C"+(st.courses.length+1);const c={id,t:v.t,cat:v.cat,mins:v.mins||30,mods:String(v.mods).split("\n").map(x=>x.trim()).filter(Boolean),q:v.q,pass:v.pass,recur:+v.recur||0,aud:v.aud,due:v.due,mand:!!v.mand,rate:.3,src:"Native",cert:false,owner:"People office"};st.courses.push(c);st.people.forEach(p=>{if(inAud(c,p)){const E=st.enr[p.id]=st.enr[p.id]||{};E[id]={st:"todo",due:c.due,pct:0}}});return {toast:"Course created and "+courseStat(c).n+" people enrolled",audit:v.t}}})}
function importForm(){openForm({id:"ppl_import",title:"Import a SCORM or xAPI package",story:"Upload a package from your authoring tool. Oukala reads its manifest, creates the course, and starts listening for learning statements from the player. SCORM 1.2 and 2004 packages are wrapped, xAPI and cmi5 packages send statements to the learning record store directly.",submit:"Import package",
 fields:[{k:"pkg",label:"Package (.zip)",type:"file",accept:".zip,.xml,.json",req:true,ph:"Choose a package or drop it here",help:"imsmanifest.xml (SCORM) or tincan.xml / cmi5.xml (xAPI) at the root"},{k:"std",label:"Standard",type:"chips",req:true,opts:["SCORM 1.2","SCORM 2004","xAPI","cmi5"]},{k:"t",label:"Course title",type:"text",req:true,ph:"Read from the manifest"},{k:"cat",label:"Category",type:"select",opts:CATS},{k:"aud",label:"Audience",type:"multi",opts:["All",...new Set(st.people.map(p=>p.team))]},{k:"pass",label:"Pass mark",type:"range",min:50,max:100,step:5,unit:"%"},{k:"due",label:"Due date",type:"date"}],
 defaults:{std:"SCORM 1.2",cat:"Security awareness",aud:[],pass:80,due:"2026-11-30"},
 onFile:(f,v)=>{if(!f)return;if(!v.t)v.t=f.name.replace(/\.[a-z0-9]+$/i,"").replace(/[-_]+/g," ").replace(/\b\w/g,m=>m.toUpperCase());if(/xapi|tincan/i.test(f.name))v.std="xAPI";else if(/cmi5/i.test(f.name))v.std="cmi5";else if(/2004/.test(f.name))v.std="SCORM 2004";v.size=Math.round(f.size/1024)},
 live:v=>{const el=document.getElementById("pplImLive");if(el)el.innerHTML=`<div class="ppl-eff small">${v.pkg?`<b>${esc(v.pkg)}</b>${v.size?" · "+v.size+" KB":""}. Expected entry: ${/xAPI|cmi5/.test(v.std||"")?"tincan.xml or cmi5.xml with an activity launch URL":"imsmanifest.xml with a SCO launch file"}. After import, the player emits statements such as <code>launched</code>, <code>progressed</code> and <code>passed</code> into the stream on this tab.`:"Choose a file to see what Oukala will read."}</div>`},extra:'<div id="pplImLive" style="flex-basis:100%"></div>',
 onSubmit:v=>{const id="C"+(st.courses.length+1);const c={id,t:v.t,cat:v.cat||"Product training",mins:25,mods:["Launch SCO 1","SCO 2","SCO 3","Assessment"],q:6,pass:v.pass,recur:0,aud:v.aud&&v.aud.length?v.aud:["All"],due:v.due||"2026-11-30",mand:false,rate:.3,src:v.std,cert:false,owner:"People office",pkg:v.pkg};st.courses.push(c);st.people.forEach(p=>{if(inAud(c,p)){const E=st.enr[p.id]=st.enr[p.id]||{};E[id]={st:"todo",due:c.due,pct:0}}});emit("launched","oh",id);emit("progressed","oh",id,{extensions:{"https://oukala.example/ext/progress":.25}});st.tr.xsel=0;st.tr.sel=id;S.v.ppl_train=3;audit("imported learning package",v.pkg+" as "+v.std);return {toast:"Imported "+v.t+" ("+v.std+"). Two test statements captured below.",audit:v.t}}})}
function xapiCard(){const x=st.xapi,s=x[clamp(st.tr.xsel,0,x.length-1)]||x[0];
 return card("xAPI statement stream","Every launch, progress step and result the player sends is a statement: who (actor), did what (verb), to what (object), with what result. Select one to see the JSON.",`<div class="split"><div class="ppl-xs">${x.slice(0,8).map((t,i)=>`<button class="ppl-xr ${i===st.tr.xsel?"on":""}" data-ppl-xs="${i}"><span class="pill ${vclass(t.verb.display["en-US"])}">${t.verb.display["en-US"]}</span><span><b>${esc(t.actor.name)}</b><small class="muted">${esc(t.object.definition.name["en-US"])}</small></span><small class="muted">${t.timestamp.slice(11,19)}</small></button>`).join("")}</div><pre class="ppl-json" aria-label="Statement JSON">${esc(JSON.stringify(s,null,2))}</pre></div>`,aiChip({model:"Learning Coach",conf:.9,title:"Statement mapping",src:["SCORM runtime calls mapped to xAPI verbs","Learning record store"],guards:["Statements carry names and results only","Retained 400 days"]}))}
function designPane(){return `<div class="grid g2" style="align-items:start">${card("Course designer","Build a course from a title and an outline. The quiz and the pass mark are part of the course, not an afterthought.",`<div class="ppl-eff"><p class="small">Modules, a quiz, a pass mark, an audience and a repeat cycle. Learning Coach can draft the outline from the title.</p></div><div class="row" style="margin-top:12px"><button class="btn primary" data-ppl-design="1">Design a course</button></div>`)}${card("Import a package","Bring in a SCORM or xAPI course from any authoring tool. It lands in the catalog beside native courses.",`<div class="ppl-eff"><p class="small">Supported: SCORM 1.2, SCORM 2004 4th edition, xAPI (Tin Can) and cmi5. The package file is read in your browser for this demo and not uploaded.</p></div><div class="row" style="margin-top:12px"><button class="btn primary" data-ppl-import="1">Import SCORM or xAPI package</button></div>`)}</div>${xapiCard()}`}
function learnPane(){ensureEnr("oh");const E=st.enr.oh,list=Object.entries(E).map(([cid,e])=>({c:COURSE(cid),e})),sel=COURSE(st.tr.sel)&&E[st.tr.sel]?st.tr.sel:(list[0]||{c:{id:null}}).c.id,c=COURSE(sel),e=E[sel];
 if(!c)return empty("No courses assigned","");const mods=c.mods,done=(st.tr.done[sel]||[]),pct=e.st==="done"?100:Math.round(done.length/mods.length*100);const allDone=done.length>=mods.length;const qz=QZ[sel]||GQ;
 const player=`<div class="ppl-player"><div class="ppl-pv"><span class="eyebrow">Module ${Math.min(st.tr.mod+1,mods.length)} of ${mods.length}</span><h3>${esc(st.tr.quiz?"Knowledge check":mods[Math.min(st.tr.mod,mods.length-1)])}</h3>${st.tr.quiz?`<div class="ppl-qz">${qz.map((q,i)=>`<div><b>${i+1}. ${esc(q[0])}</b><div class="fchips" role="radiogroup">${q[1].map((o,j)=>`<button class="chip" data-ppl-ans="${i}:${j}" aria-pressed="${st.tr.ans[i]===j}">${esc(o)}</button>`).join("")}</div></div>`).join("")}<button class="btn primary" data-ppl-submitquiz="1" ${Object.keys(st.tr.ans).length<qz.length?"disabled":""}>Submit answers (pass mark ${c.pass}%)</button></div>`:`<p class="muted" data-role="story">${esc(c.t)}. In this module you will see a short scenario and then choose what to do. It takes about ${Math.max(3,Math.round(c.mins/mods.length))} minutes.</p><div class="ppl-vid" aria-hidden="true"><span>${ico("book")}</span></div><div class="row"><button class="btn" data-ppl-mod="prev" ${st.tr.mod<=0?"disabled":""}>Back</button><button class="btn primary" data-ppl-mod="done">${done.includes(st.tr.mod)?"Next module":"Mark complete and continue"}</button>${allDone&&e.st!=="done"?'<button class="btn" data-ppl-mod="quiz">Take the quiz</button>':""}</div>`}</div><div class="ppl-pl"><div class="row sp small"><b>Progress</b><span class="num" data-role="metric">${pct}%</span></div><span class="bar"><i style="width:${pct}%;background:${col("--good-f")}"></i></span>${mods.map((m,i)=>`<button class="ppl-mi ${i===st.tr.mod&&!st.tr.quiz?"on":""} ${done.includes(i)||e.st==="done"?"ok":""}" data-ppl-gomod="${i}"><i>${done.includes(i)||e.st==="done"?"✓":i+1}</i>${esc(m)}</button>`).join("")}<button class="ppl-mi ${st.tr.quiz?"on":""} ${e.st==="done"?"ok":""}" data-ppl-mod="quiz" ${allDone||e.st==="done"?"":"disabled"}><i>${e.st==="done"?"✓":"?"}</i>Quiz</button></div></div>`;
 return `${card("My learning",`Omar's transcript. The mini-player below is what a learner sees; each step it takes sends an xAPI statement to the stream.`,`<div class="row" style="margin-bottom:12px">${list.map(x=>`<button class="chip" data-ppl-sel="${x.c.id}" aria-pressed="${x.c.id===sel}">${esc(x.c.t.length>26?x.c.t.slice(0,25)+"…":x.c.t)} ${x.e.st==="done"?"✓":""}</button>`).join("")}</div>${player}`)}${xapiCard()}`}
function trainScreen(){updMetrics();const ts=trainStat(),od=st.people.filter(p=>overdueOf(p.id).length),sec3=st.people.filter(p=>overdueOf(p.id).some(z=>z.c.id==="C3")),cr=certRows(),soon=cr.filter(x=>x.days<=60).length;
 const story=`<b>${Math.round(ts.pct)}%</b> of mandatory courses due to date are complete, against a 95% target. <b>${sec3.length} people</b> have not finished Security awareness 2026, which closed Oct 2, and <b>${soon} certificates</b> expire or have expired within 60 days. Learning Coach has reminders ready.`;
 return `<div class="screen">${hero("Training and learning","Is everyone ready to do the work safely",story,`<div class="row">${fchip("m_trainc")}<button class="btn primary" data-ppl-design="1">Design a course</button><button class="btn" data-ppl-import="1">Import SCORM or xAPI</button>${whyPop("Training connects to access: privileged roles in Entra ID depend on the privileged access certificate staying valid.")}</div>`)}${lensNote()}${tiles([TL("Mandatory completion",Math.round(ts.pct)+"%",ts.d+" of "+ts.t+" due to date",ts.pct>=95?"good":ts.pct>=85?"warn":"bad"),TL("People with overdue courses",od.length,"of "+st.people.length,od.length>5?"bad":"warn"),TL("Certificates expiring or expired",soon,"within 60 days",soon?"warn":"good"),TL("Courses in catalog",st.courses.length,st.courses.filter(c=>c.src!=="Native").length+" imported packages","good")])}${views("ppl_train",["Catalog and paths","Assignments and completion","Certificates and nudges","Designer and import","My learning"],[catalogPane(),assignPane(),certPane()+nudgePane(),designPane(),learnPane()])}</div>`}
