function assignCourseForm(cid){openForm({id:"ppl_asg",title:"Assign a course",story:"Adds the audience to the course, creates an enrollment for each person with the due date, and Learning Coach will remind them before it is late.",submit:"Assign",fields:[{k:"c",label:"Course",type:"select",req:true,opts:st.courses.map(c=>[c.id,c.t])},{k:"aud",label:"Audience",type:"multi",req:true,opts:["All",...new Set(st.people.map(p=>p.team))]},{k:"due",label:"Due date",type:"date",req:true}],defaults:{c:cid||"",aud:[],due:"2026-11-15"},
 live:v=>{const el=document.getElementById("pplAsgLive"),c=COURSE(v.c);if(!el||!c)return;const n=st.people.filter(p=>(v.aud||[]).includes("All")||(v.aud||[]).includes(p.team)).filter(p=>!((st.enr[p.id]||{})[c.id])).length;el.innerHTML=`<div class="ppl-eff small">${n} new enrollments for ${esc(c.t)}, due ${v.due?dFmt(v.due):"(pick a date)"}.</div>`},extra:'<div id="pplAsgLive" style="flex-basis:100%"></div>',
 onSubmit:v=>{const c=COURSE(v.c);let n=0;st.people.forEach(p=>{if((v.aud.includes("All")||v.aud.includes(p.team))&&!((st.enr[p.id]||{})[c.id])){(st.enr[p.id]=st.enr[p.id]||{})[c.id]={st:"todo",due:v.due,pct:0};n++}});v.aud.forEach(a=>{if(!c.aud.includes(a))c.aud.push(a)});return {toast:n+" people enrolled in "+c.t,audit:c.t}}})}
function courseDrawer(id){const c=COURSE(id),s=courseStat(c);openDrawer(`<div class="eyebrow">${esc(c.cat)} · ${esc(c.src)}</div><h3>${esc(c.t)}</h3><p class="muted" data-role="story">${c.mins} minutes across ${c.mods.length} modules, pass mark ${c.pass}%. ${s.n} people are enrolled, ${s.d} are done and ${s.o} are overdue.</p><dl class="kv"><dt>Audience</dt><dd>${c.aud.map(a=>`<span class="pill mute">${esc(a)}</span>`).join(" ")}</dd><dt>Due</dt><dd>${dFmt(c.due)}</dd><dt>Repeats</dt><dd>${c.recur?"Every "+c.recur+" months":"Never"}</dd><dt>Owner</dt><dd>${esc(c.owner)}</dd>${c.pkg?`<dt>Package</dt><dd>${esc(c.pkg)}</dd>`:""}</dl><div class="eyebrow">Modules</div><ol class="ppl-ol">${c.mods.map(m=>`<li>${esc(m)}</li>`).join("")}<li><b>Quiz</b>, ${c.q} questions</li></ol><div class="row" style="margin-top:14px"><button class="btn primary" data-ppl-assigncourse="${c.id}">Assign</button><button class="btn" data-ppl-try="${c.id}">Preview as learner</button></div>`)}
