function curve(pts){if(pts.length<2)return "";let d=`M${pts[0][0]} ${pts[0][1]}`;for(let i=0;i<pts.length-1;i++){const p0=pts[i-1]||pts[i],p1=pts[i],p2=pts[i+1],p3=pts[i+2]||p2;d+=` C${(p1[0]+(p2[0]-p0[0])/6).toFixed(1)} ${(p1[1]+(p2[1]-p0[1])/6).toFixed(1)} ${(p2[0]-(p3[0]-p1[0])/6).toFixed(1)} ${(p2[1]-(p3[1]-p1[1])/6).toFixed(1)} ${p2[0]} ${p2[1]}`}return d}
function emoSvg(j){const n=j.stages.length,W=n*COLW,Hh=150,ys=v=>16+(5-v)*(Hh-36)/4,xs=i=>COLW/2+i*COLW;const pts=j.stages.map((s,i)=>[xs(i),ys(s.em)]);
 let g=[1,2,3,4,5].map(v=>`<line x1="0" x2="${W}" y1="${ys(v)}" y2="${ys(v)}" stroke="var(--hair)" ${v===3?'stroke-dasharray="4 5" stroke-width="1.6"':""}/><text class="ax" x="5" y="${ys(v)-4}" style="font-size:10px">${v===5?"Delighted":v===3?"Neutral":v===1?"Frustrated":""}</text>`).join("");
 const lo=Math.min(...j.stages.map(s=>s.em));
 g+=`<path d="${curve(pts)}L${xs(n-1)} ${ys(1)}L${xs(0)} ${ys(1)}Z" fill="${col("--p4")}" opacity=".10"/><path d="${curve(pts)}" fill="none" stroke="${col("--p4")}" stroke-width="3.4" stroke-linecap="round"/>`;
 g+=pts.map((p,i)=>{const s=j.stages[i],c=s.em<=2?"--bad-f":s.em>=4?"--good-f":"--warn-f";return `<circle cx="${p[0]}" cy="${p[1]}" r="9" fill="${col(c)}" stroke="var(--bg)" stroke-width="2.5"><title>${esc(s.n)}: ${s.em} of 5</title></circle><text x="${p[0]}" y="${p[1]+4}" text-anchor="middle" font-size="10.5" font-weight="800" fill="#fff" style="font-family:var(--f-body)">${s.em}</text>${s.em===lo?`<text class="ax" x="${p[0]}" y="${p[1]+24}" text-anchor="middle" style="font-size:10px;fill:${col("--bad")}">lowest point</text>`:""}`}).join("");
 return `<svg viewBox="0 0 ${W} ${Hh}" width="${W}" height="${Hh}" role="img" aria-label="Emotion curve for ${esc(j.n)}, scored 1 frustrated to 5 delighted, drawn to scale">${g}</svg>`}
function jmap(j){const n=j.stages.length;const lane=(l,fn)=>`<div class="ppl-jl">${l}</div>${j.stages.map((s,i)=>`<div class="ppl-jc">${fn(s,i)}</div>`).join("")}`;
 return `<div class="ppl-heatwrap"><div class="ppl-jm" style="grid-template-columns:${LBL}px repeat(${n},${COLW}px)">
 <div class="ppl-jl"></div>${j.stages.map((s,i)=>`<div class="ppl-jh"><span class="num">${i+1}</span><b>${esc(s.n)}</b></div>`).join("")}
 ${lane("Actions",s=>`<ul>${s.act.map(a=>`<li>${esc(a)}</li>`).join("")}</ul>`)}
 ${lane("Touchpoints",s=>s.tp.map(a=>`<span class="pill info">${esc(a)}</span>`).join(" "))}
 <div class="ppl-jl">Emotions<small class="muted">1 to 5</small></div><div class="ppl-jemo" style="grid-column:2 / span ${n}">${emoSvg(j)}</div>
 <div class="ppl-jl"></div>${j.stages.map(s=>`<div class="ppl-jc ppl-jmod"><button class="chip" data-ppl-emo="${s.id}:-1" aria-label="Lower emotion score for ${esc(s.n)}">−</button><b class="num">${s.em}</b><button class="chip" data-ppl-emo="${s.id}:1" aria-label="Raise emotion score for ${esc(s.n)}">+</button></div>`).join("")}
 ${lane("Pain points",s=>s.pain.map(p=>`<div class="ppl-pain s${p.sev}"><span>${esc(p.t)}</span><button class="btn quiet" data-ppl-raisepain="${p.id}" ${p.raised?"disabled":""}>${p.raised?"Raised":"Raise as demand"}</button></div>`).join("")||'<span class="muted small">None</span>')}
 ${lane("Opportunities",s=>`<ul class="opp">${s.opp.map(a=>`<li>${esc(a)}</li>`).join("")}</ul>`)}
 ${lane("Owner",s=>`<span class="pill metric">${esc(s.own)}</span>`)}
 ${lane("Systems",s=>s.sys.map(a=>`<span class="pill mute">${esc(a)}</span>`).join(" "))}
 </div></div>`}
function findPain(id){for(const j of st.jr.list)for(const s of j.stages)for(const p of s.pain)if(p.id===id)return {j,s,p}}
function painForm(id){const f=findPain(id);if(!f)return;const {j,s,p}=f;openForm({id:"ppl_pain",title:"Raise as demand",story:"Turns this pain point into a demand request. Nothing is added to Demand and priorities yet: it queues here for the Portfolio Agent to score, and you can edit the draft first.",submit:"Queue the request",
 fields:[{k:"t",label:"Request title",type:"text",req:true,ai:{label:"Rewrite",fn:v=>"Fix: "+p.t.replace(/\.$/,"")}},{k:"why",label:"Why it matters",type:"longtext",req:true,wide:true,ai:{label:"Draft",fn:v=>`In "${j.n}", stage "${s.n}" scores ${s.em} of 5. ${p.t}. Fixing it should lift the journey sentiment and reduce tickets.`}},{k:"sp",label:"Sponsor",type:"people"},{k:"urg",label:"Urgency",type:"range",min:1,max:5},{k:"cost",label:"Rough cost",type:"money",step:5000}],
 defaults:{t:"Fix: "+p.t,why:`${j.n}, stage ${s.n}. ${p.t}.`,urg:p.sev+1,sp:"oh",cost:60000},
 onSubmit:v=>{p.raised=true;st.jr.raised.unshift({id:"JD"+(st.jr.raised.length+1),t:v.t,why:v.why,sp:v.sp,urg:v.urg,cost:v.cost,from:j.n+" · "+s.n,at:nowT()});return {toast:"Queued: "+v.t.slice(0,40)+". Portfolio Agent will score it.",audit:v.t}}},null)}
function stageForm(){const j=JR();openForm({id:"ppl_stage",title:"Add a stage",story:"Adds a column to "+j.n+". Fill in the lanes afterwards with Add touchpoint. The emotion curve redraws to scale.",submit:"Add stage",fields:[{k:"n",label:"Stage name",type:"text",req:true,ph:"Equipment returned"},{k:"after",label:"Place after",type:"select",opts:[["-1","At the start"],...j.stages.map((s,i)=>[String(i),s.n])]},{k:"em",label:"Emotion score",type:"range",min:1,max:5},{k:"own",label:"Owner",type:"text",ph:"People office"},{k:"sys",label:"System",type:"text",ph:"HR system"}],defaults:{after:String(j.stages.length-1),em:3},
 onSubmit:v=>{const s={id:"st"+Math.floor(Math.random()*1e5),n:v.n,em:v.em,act:[],tp:[],pain:[],opp:[],own:v.own||"Unassigned",sys:v.sys?[v.sys]:[]};j.stages.splice(+v.after+1,0,s);return {toast:"Stage added to "+j.n,audit:v.n}}})}
function tpForm(sid){const j=JR();openForm({id:"ppl_tp",title:"Add to a stage",story:"Adds an action, touchpoint, pain point, opportunity or system to a stage.",submit:"Add",fields:[{k:"s",label:"Stage",type:"select",req:true,opts:j.stages.map(s=>[s.id,s.n])},{k:"lane",label:"Lane",type:"chips",req:true,opts:[["act","Action"],["tp","Touchpoint"],["pain","Pain point"],["opp","Opportunity"],["sys","System"]]},{k:"t",label:"Text",type:"text",req:true,ph:"Describe it in a few words"},{k:"sev",label:"How painful",type:"range",min:1,max:3,show:v=>v.lane==="pain"}],defaults:{s:sid||j.stages[0].id,lane:"tp",sev:2},
 onSubmit:v=>{const s=j.stages.find(x=>x.id===v.s);if(v.lane==="pain")s.pain.push({id:"pn"+Math.floor(Math.random()*1e5),t:v.t,sev:v.sev||2,raised:false});else s[v.lane].push(v.t);return {toast:"Added to "+s.n,audit:v.t}}})}
function jrScreen(){const j=JR(),avg=jrAvg(j);METRICS.m_emo.cur=Math.round(jrAvg(st.jr.list[0])*10)/10;
 const low=j.stages.reduce((a,s)=>s.em<a.em?s:a,j.stages[0]),pains=j.stages.reduce((a,s)=>a+s.pain.length,0),rz=j.stages.reduce((a,s)=>a+s.pain.filter(p=>p.raised).length,0);
 const story=`<b>${esc(j.n)}</b> averages <b>${avg.toFixed(1)} of 5</b> across ${j.stages.length} stages. The lowest point is <b>${esc(low.n)}</b> (${low.em}), where ${low.pain[0]?esc(low.pain[0].t.toLowerCase())+".":"people feel stuck."} ${pains} pain points are mapped and ${rz} already raised as demand.`;
 const strip=`<div class="ppl-strip" data-dnd="jstages" data-dnd-scope="ppljs" data-dnd-dir="x">${j.stages.map((s,i)=>`<div class="ppl-ss" data-dnd-id="${s.id}" tabindex="0">${grip}<span><b>${i+1}</b> ${esc(s.n)}</span></div>`).join("")}</div>`;
 const raised=st.jr.raised.length?`<div class="needs">${st.jr.raised.map(r=>`<div class="need" style="grid-template-columns:auto 1fr auto"><div class="ico info">${ico("bolt")}</div><div><b>${esc(r.t)}</b><span class="muted small" data-role="story">${esc(r.from)} · urgency ${r.urg} · sponsor ${esc(nameOf(r.sp))} · about ${money(r.cost||0)}</span></div><span class="pill info">Queued at ${r.at}</span></div>`).join("")}</div>`:empty("Nothing raised yet","Select Raise as demand on a pain point.");
 return `<div class="screen">${hero("Journey maps","See the work through the person's eyes",story,`<div class="row">${fchip("m_emo")}<button class="btn primary" data-ppl-stage="1">Add stage</button><button class="btn" data-ppl-tp="">Add touchpoint</button>${aiChip({model:"Claude Sonnet",conf:.78,title:"How the emotion scores were set",src:["Survey comments","Service desk tickets","Manager interviews"],guards:["Aggregated, no names"]})}${whyPop("Journeys link experience to delivery: a pain point can become a demand request and a stage owner can be a person or an agent.")}</div>`)}${lensNote()}
 <div class="row">${st.jr.list.map(x=>`<button class="chip" data-ppl-jr="${x.id}" aria-pressed="${x.id===j.id}">${esc(x.n)}</button>`).join("")}</div>
 ${card(esc(j.n),esc(j.story)+" Drag a stage chip to reorder the columns.",`<div class="eyebrow" style="margin-bottom:6px">Stages</div>${strip}<div style="margin-top:14px">${jmap(j)}</div><div class="legend-row" style="margin-top:10px"><span><i class="sw" style="background:${col("--good-f")}"></i>4 to 5 good</span><span><i class="sw" style="background:${col("--warn-f")}"></i>3 neutral</span><span><i class="sw" style="background:${col("--bad-f")}"></i>1 to 2 painful</span><span>Curve and dots are plotted to one 1 to 5 scale</span></div>`,`<span class="pill metric" data-role="metric">${avg.toFixed(1)} avg</span>`)}
 ${card("Raised as demand","Pain points you queued. They wait for the Portfolio Agent to score them and are not yet in Demand and priorities.",raised)}</div>`}
REG("ppl_jrny","Journey maps","people","M3 18c3-8 5 0 8-6s5-4 7-8M3 21h18M18 4l3 0 0 3",jrScreen);
DND.on("ppljs",(id,from,to,idx)=>{const j=JR(),old=j.stages.findIndex(s=>s.id===id);if(old<0)return;const [s]=j.stages.splice(old,1);const at=old<idx?idx-1:idx;j.stages.splice(clamp(at,0,j.stages.length),0,s);toast(s.n+" is now stage "+(clamp(at,0,j.stages.length-1)+1));audit("reordered journey stage",j.n+": "+s.n);render()});
