function openCount(n){try{return workFor(n).reduce((a,g)=>a+g.rows.length,0)}catch(e){return 0}}
/* ---- work queue (assign to a team first, then to a person) ---- */
function seedWQ(){const W=(id,t,h,w0,n,type,risk,tag,srcx,team,owner)=>({id,t,h,w0,n,type,risk,tag,src:srcx,team:team||null,owner:owner||null});
 return [W("W1","Update runbook RB-031 for failover",8,0,2,"bau","med","runbooks","Task p3_3","Ops team"),W("W2","Review Lumen SOW-4 change order",5,0,1,"bau","high","vendor","Task p2_2","PMO"),
 W("W3","Prepare Architecture Review Board pre-read for the Taxonomy hub",6,1,1,"bau","low","docs","Task p2_1"),W("W4","Triage Portal latency alerts (Sev 2 follow-up)",10,0,2,"inc","med","incidents","INC0412","Ops team"),
 W("W5","Write editor acceptance test scripts",12,1,2,"proj","low","docs","Task p1_6"),W("W6","Spot check taxonomy mapping output",8,2,3,"proj","low","schedule","Task p2_3"),
 W("W7","Run migration design workshop prep",10,3,2,"proj","med","docs","Task p4_2"),W("W8","Follow up with staff who have not finished security training",4,0,2,"train","low","training","Training"),
 W("W9","Clean up stale knowledge articles",6,1,2,"bau","low","knowledge","Knowledge"),W("W10","Reforecast Vendor services after the Lumen slip",6,0,1,"bau","med","finance","Budget B2","Finance"),
 W("W11","Portal Sev 2 incident command",24,0,2,"inc","med","incidents","INC0412","Ops team","Tom Becker"),W("W12","Hosting tier change risk review",6,0,1,"chg","med","ops","CHG0312","Change management","Nia Brooks"),
 W("W13","Beta defect triage",10,0,3,"proj","low","platform","Task p1_4","Platform team","Sam Patel"),W("W14","Contract Repository vendor demos",8,0,2,"proj","med","vendor","Task p4_1","Architecture","Jordan Lee")]}
st.org.wq=st.org.wq||seedWQ();
if(!st.org.audit.length)st.org.audit=[{t:"08:10",item:"Beta defect triage",from:"Priya Shah",to:"Sam Patel",before:.88,after:1.04,by:"Resource Agent, approved by Maya Ortiz",why:"Priya needed cover for a vendor call"},{t:"Yesterday",item:"Failover rehearsal plan",from:"Tom Becker",to:"Ops Agent",before:null,after:.77,by:"Tom Becker",why:"Routine runbook steps within the Ops Agent's scope"}];
const RULES={runbooks:/runbook|failover|diagnos/,docs:/article|doc|knowledge|meeting|minutes|editor/,incidents:/incident|triage|diagnos/,vendor:/contract|invoice|clause/,schedule:/schedule|portfolio|critical|forecast/,training:/training|remind/,knowledge:/article|knowledge/,finance:/invoice|reforecast|actual|budget/,platform:/test|runbook|diagnos|capacity/,ops:/runbook|change|risk/};
function ruleFor(r,it){if(r.kind!=="ai")return null;const tier=ATIER[r.name]||1;if(it.risk==="high")return ["no","High-risk work (money, contracts or access) stays with people. Agents never take it."];if(tier===1&&it.risk!=="low")return ["no","Tier 1 agents only suggest and draft. This item needs someone to act, so assign its owner of record instead."];
 const sc=(r.skills.join(" ")+" "+r.role).toLowerCase();if(RULES[it.tag]&&!RULES[it.tag].test(sc))return ["no","Outside "+r.name+"'s scope ("+r.skills.join(", ")+"). The AI gateway would block it."];return ["ok",tier===2?"Allowed. "+(acctOf(r.name)||"The accountable human")+" approves each step.":tier===3?"Allowed within its limits.":"Allowed as a draft only."]}
function effectOf(it,name){const m=PM(name);let pk=0,b=0;for(let w=it.w0;w<it.w0+it.n&&w<NWK;w++){if(m.cap[w]<=.5)continue;const bb=m.tot[w]/m.cap[w],aa=(m.tot[w]+it.h)/m.cap[w];if(aa>pk){pk=aa;b=bb}}return {before:m.cap[it.w0]>.5?m.tot[it.w0]/m.cap[it.w0]:null,after:pk||null,over:pk>1.0001,rule:ruleFor(who(name),it)}}
const effBar=(b,a)=>`<div class="pp2-eff"><div class="pp2-effbar"><i style="width:${clamp((b||0)/1.5*100,0,100)}%;background:var(${uCol(b)})"></i><u style="left:${clamp((b||0)/1.5*100,0,100)}%;width:${clamp(((a||0)-(b||0))/1.5*100,0,100-clamp((b||0)/1.5*100,0,100))}%;background:var(${uCol(a)})"></u><s style="left:66.6%"></s></div><div class="row sp small"><span>Now ${pc(b)}</span><span>After ${pc(a)}</span><span class="muted">Capacity line at 100%</span></div></div>`;
function doAssign(it,name,why,by){const from=it.owner,ef=effectOf(it,name);it.owner=name;it.team=it.team||(who(name)||{}).team||null;bumpMv();
 st.org.audit.unshift({t:new Date().toLocaleTimeString("en-US",{hour:"2-digit",minute:"2-digit"}),item:it.t,from:from||(it.team?it.team+" queue":"Unassigned"),to:name,before:ef.before,after:ef.after,by:by||"Omar Hamid",why:why||"Assigned from the work queue",iid:it.id,prevTeam:it.team});
 audit("assigned work",it.t+" → "+name+" ("+pc(ef.before)+" to "+pc(ef.after)+")");toast(it.t.slice(0,38)+" is with "+name+" ("+pc(ef.after)+")",ef.over?"warn":"good");render()}
function assignForm(id){const it=st.org.wq.find(x=>x.id===id);if(!it)return;const pool=DIR.filter(d=>d.kind!=="msp"&&(!it.team||d.team===it.team||it.owner)).slice(0,300);const opts=[["","Pick a worker"]].concat((pool.length?pool:DIR).slice(0,300).map(d=>[d.name,d.name+" · "+KINDS[d.kind]+" · "+pc(uNow(d.name,it.w0))]));
 openForm({id:"pp2_assign",title:"Assign: "+it.t,story:`${it.h} hours a week for ${it.n} week${it.n>1?"s":""}, starting the week of ${WK[it.w0].lab}. Work goes to a team first. A person takes it by claiming it, or you assign it here with a reason. The line below shows the effect before you save. AI agents are checked against their tier and scope.`,submit:"Assign",
 fields:[{k:"to",label:"Assign to",type:"select",opts,req:true,help:it.team?"Showing "+it.team+". Choose a team on the board to see others.":"Unassigned items can go to any worker."},{k:"why",label:"Reason for assigning to an individual",type:"text",req:true,ph:"Skill match, cover for leave, balance",ai:{label:"Suggest",fn:v=>{const r=who(v.to);return r?(r.kind==="ai"?"Routine work within "+r.name+"'s scope; "+(acctOf(r.name)||"its owner")+" stays accountable":"Skill match and room in the week of "+WK[it.w0].lab+" ("+pc(uNow(r.name,it.w0))+" before)"):"Best fit by skill and available hours"}}}],
 live:v=>{const r=who(v.to);if(!r)return "";const ef=effectOf(it,r.name);return effBar(ef.before,ef.after)+(ef.over?`<p class="small" style="color:var(--bad)"><b>Overload:</b> ${E(r.name)} would be over capacity.</p>`:"")+(ef.rule?`<p class="small ${ef.rule[0]==="no"?"":"muted"}" style="${ef.rule[0]==="no"?"color:var(--bad)":""}">${E(ef.rule[1])}</p>`:"")},
 onSubmit:v=>{const r=who(v.to),ef=effectOf(it,v.to);if(ef.rule&&ef.rule[0]==="no"){toast(ef.rule[1],"bad");audit("blocked assignment",it.t+" → "+v.to);return {close:false,toast:"Not assigned"}}doAssign(it,v.to,v.why);return {toast:"Assigned to "+v.to,audit:v.to}}})}
/* ---- node, branch, tree ---- */
const passes=(n)=>{const r=who(n);const ks=mpGet("pp2k"),ts=mpGet("pp2t");if(ks.length&&!ks.includes(r.kind))return false;if(ts.length&&r.team&&!ts.includes(r.team))return false;const q=(st.org.q||"").toLowerCase();if(q&&!(n+" "+r.role+" "+r.team+" "+(r.skills||[]).join(" ")).toLowerCase().includes(q))return false;return true};
const filt=()=>{const ks=mpGet("pp2k"),ts=mpGet("pp2t");return ks.length<4||ts.length<teamList().length||!!st.org.q};
function nodeHTML(n,small){const r=who(n);const u=uNow(n),k=r.kind;const tier=k==="ai"?ATIER[n]||1:0;const dim=filt()&&!passes(n);
 const sub=k==="ai"?`Tier ${tier} agent`:k==="msp"?"Service team":k==="contractor"?"Contract ends "+(r.end?new Date(r.end+"T00:00:00Z").toLocaleDateString("en-US",{month:"short",day:"numeric",timeZone:"UTC"}):"open"):roleOf(r);
 const m=k==="msp"?"":`<em class="pp2-pc ${uCls(u)}" data-role="metric">${pc(u)}</em>`;
 return `<div class="pp2-node k-${k} ${dim?"dim":""} ${st.org.sel===n?"sel":""}" data-person="${E(n)}" data-pp2-node="${E(n)}" tabindex="0" role="button" aria-label="${E(n)}, ${E(KINDS[k])}, ${E(roleOf(r))}, ${pc(u)} of capacity this week">${avatar(r,{size:small?34:42})}<span class="pp2-tx"><b>${E(n)}</b><small>${E(sub)}</small><span class="pp2-m">${m}<span>${hasKids(n)?spanOf(n)+" direct":openCount(n)+" open"}</span></span></span></div>`}
const isOpen=(n,lvl)=>st.org.open[n]!==undefined?st.org.open[n]:lvl<st.org.depth;
function branch(n,lvl){const ks=kidsOf(n),open=isOpen(n,lvl);let sub="";
 if(open&&ks.length){const lv=ks.filter(k=>!hasKids(k)),br=ks.filter(k=>hasKids(k));const lim=12+(st.org.more[n]||0);const sh=lv.slice(0,lim);
  sub=`<ul>${lv.length?`<li class="pp2-stack"><div class="pp2-leafcol">${sh.map(x=>nodeHTML(x,true)).join("")}${lv.length>sh.length?`<button class="btn quiet" data-pp2-act="more" data-a="${E(n)}">Show ${Math.min(12,lv.length-sh.length)} more (${lv.length-sh.length} not shown)</button>`:""}</div></li>`:""}${br.map(k=>branch(k,lvl+1)).join("")}</ul>`}
 const sz=HX().size.get(n)||0;const km=kindMix(n);
 return `<li>${nodeHTML(n)}${ks.length?`<button class="pp2-tog" data-pp2-act="tog" data-a="${E(n)}" data-l="${lvl}" aria-expanded="${open}" aria-label="${open?"Collapse":"Expand"} ${E(n)}">${open?"−":"+"+sz+(km.ai?" · "+km.ai+" AI":"")}</button>`:""}${sub}</li>`}
function vacHTML(){const L=st.vac.filter(v=>v.status!=="Filled");return L.length?`<div class="pp2-vac">${L.map(v=>`<button class="pp2-vc" data-pp2-act="vacancy" data-a="${v.id}"><span class="pill warn">Vacancy</span><b>${E(v.title)}</b><small>${E(v.team)} · reports to ${E(v.mgr)} · ${E(v.status)}</small></button>`).join("")}</div>`:""}
function jumpTo(n){const r=who(n);if(!r)return;const p=pathTo(n).slice(1);p.forEach(x=>st.org.open[x]=true);st.org.sel=n;st.org.q="";S.mpSel.pp2k=undefined;S.mpSel.pp2t=undefined;st.org.jump=n;render()}
/* ---- screen ---- */
function orgStats(){const k={human:0,ai:0,contractor:0,msp:0};DIR.forEach(d=>k[d.kind]++);const mg=DIR.filter(d=>isMgr(d.name)).map(d=>({n:d.name,s:spanOf(d.name),h:kidsOf(d.name).filter(c=>kindOf(c)==="human").length}));
 const wide=mg.filter(x=>x.s>12).sort((a,b)=>b.s-a.s),narrow=mg.filter(x=>x.s<3&&x.n!==ROOT);const over=DIR.filter(d=>d.kind!=="msp"&&d.kind!=="ai").filter(d=>{const m=PM(d.name);return m.util[st.org.week]>1.0001&&m.cap[st.org.week]>.5});
 const ending=DIR.filter(d=>d.kind==="contractor"&&d.end&&wkOfIso(d.end)<14&&wkOfIso(d.end)>=0).sort((a,b)=>a.end.localeCompare(b.end));const aiOver=DIR.filter(d=>d.kind==="ai"&&(uNow(d.name)||0)>.9);
 const avg=mg.length?mean(mg.map(x=>x.s)):0;return {k,mg,wide,narrow,over,ending,aiOver,avg,vac:st.vac.filter(v=>v.status!=="Filled")}}
function attention(O){const out=[];O.wide.slice(0,2).forEach(x=>out.push({cls:"warn",t:`${x.n} has ${x.s} direct reports`,sub:"Span of control above 12 slows feedback. Add a lead or move a team.",f:()=>person360(x.n)}));
 O.ending.slice(0,2).forEach(d=>{const h=Math.round(mean(Array.from(PM(d.name).tot).slice(0,12)));out.push({cls:"warn",t:`${d.name}'s contract ends ${new Date(d.end+"T00:00:00Z").toLocaleDateString("en-US",{month:"short",day:"numeric",timeZone:"UTC"})}`,sub:`About ${h} hours a week of work has no successor yet. Sponsor: ${SPON[d.name]||d.mgr||"unassigned"}.`,f:()=>person360(d.name)})});
 O.over.slice(0,2).forEach(d=>out.push({cls:"bad",t:`${d.name} is at ${pc(uNow(d.name))} this week`,sub:"Over capacity. Open the capacity outlook for fixes.",f:()=>person360(d.name)}));
 st.vac.filter(v=>v.status!=="Filled"&&(Date.parse("2026-10-06")-Date.parse(v.opened))/DAY>35).slice(0,2).forEach(v=>out.push({cls:"warn",t:`${v.title} has been open ${Math.round((Date.parse("2026-10-06")-Date.parse(v.opened))/DAY)} days`,sub:`${v.team}. Consider a contractor, an AI agent or a managed service provider while you hire.`,f:()=>ACT.vacancy({dataset:{a:v.id}})}));
 O.aiOver.slice(0,1).forEach(d=>out.push({cls:"warn",t:`${d.name} is above 90% of its task capacity`,sub:"Accountable human: "+acctOf(d.name)+". Raise its limit or split the work.",f:()=>person360(d.name)}));return out}
function teamRows(){return teamList().map(t=>{const L=DIR.filter(d=>d.team===t),a=teamAgg(t,null);const h=L.filter(d=>d.kind==="human");return {id:t,team:t,mgr:TEAMMGR(t)||"",n:L.length,human:h.length,ai:L.filter(d=>d.kind==="ai").length,ct:L.filter(d=>d.kind==="contractor").length,msp:L.filter(d=>d.kind==="msp").length,u:avgU(a,0,11),over:ovStats(L.filter(d=>d.kind!=="msp").map(d=>d.name),0,11).people,vac:st.vac.filter(v=>v.team===t&&v.status!=="Filled").length}})}
function mixBars(){const rows=teamRows().filter(r=>r.n>0).sort((a,b)=>b.n-a.n);const mx=Math.max(...rows.map(r=>r.n));return `<div class="pp2-mix">${rows.map(r=>`<button class="pp2-mrow" data-pp2-act="team" data-a="${E(r.team)}"><span class="pp2-mn">${E(r.team)}</span><span class="pp2-mb" style="width:${Math.max(6,r.n/mx*100)}%">${[["human","--good-f"],["ai","--u3"],["ct","--w1"],["msp","--p4"]].map(([k,c])=>r[k]?`<i style="flex:${r[k]};background:var(${c})" title="${r[k]}"></i>`:"").join("")}</span><b class="num">${r.n}</b></button>`).join("")}</div>${KLEG}`}
function spanHist(O){const b=[["0 to 2",0,2],["3 to 5",3,5],["6 to 8",6,8],["9 to 12",9,12],["13 or more",13,999]].map(x=>({l:x[0],n:O.mg.filter(m=>m.s>=x[1]&&m.s<=x[2]).length,c:x[1]>=13?"--bad-f":x[1]>=9?"--warn-f":"--good-f"}));const mx=Math.max(1,...b.map(x=>x.n));
 return `<div class="pp2-hist" role="img" aria-label="Managers by number of direct reports">${b.map(x=>`<div><b class="num" data-role="metric">${x.n}</b><i style="height:${Math.max(4,x.n/mx*100)}px;background:var(${x.c})"></i><small>${x.l}</small></div>`).join("")}</div><div class="muted small">Direct reports per manager. A healthy span is 5 to 9 (guidance, not a rule): green is 0 to 8, amber 9 to 12, red above 12. Average ${f1(O.avg)}.</div>`}
function orgDash(){const O=orgStats(),A=attention(O);const tr=teamRows();
 const agents=DIR.filter(d=>d.kind==="ai").map(d=>({d,u:uNow(d.name),t:ATIER[d.name]||1,o:acctOf(d.name)}));
 const msps=DIR.filter(d=>d.kind==="msp"),cts=DIR.filter(d=>d.kind==="contractor");
 return `<div class="statrow">${stat("Workers",fmt(DIR.length),`${fmt(O.k.human)} employees · ${fmt(O.k.ai)} AI agents · ${fmt(O.k.contractor)} contractors · ${fmt(O.k.msp)} providers`)}${stat("Managers",O.mg.length,"average span "+f1(O.avg)+(O.wide.length?" · "+O.wide.length+" wider than 12":""),O.wide.length?"crit":"")}${stat("Vacancies",O.vac.length,"open requisitions with a hiring manager")}${stat("Over capacity this week",O.over.length,"people above 100% of available hours",O.over.length>3?"crit":"")}${stat("AI agents with an accountable human",O.k.ai?"100%":"n/a","every agent reports to a named person")}${stat("Contract ends in 14 weeks",O.ending.length,O.ending.length?O.ending.map(d=>first(d.name)).join(", "):"none")}</div>
 <div class="grid g2">${card("People by team and kind","Bar length is headcount. Color shows who the work is done by.",mixBars())}${card("Span of control",O.wide.length?`${O.wide.length} manager${O.wide.length>1?"s":""} with more than 12 direct reports`:"Spans are within guidance",spanHist(O),stdChip("hr","Span of control is one of the structural signals reviewed each cycle."))}</div>
 ${card("Needs attention","What changed in the org this week and who should look at it.",A.length?`<div class="pp2-att">${A.map((a,i)=>`<button class="pp2-ai ${a.cls}" data-pp2-act="att" data-a="${i}"><span class="pill ${a.cls}">${a.cls==="bad"?"Act now":"Watch"}</span><span><b>${E(a.t)}</b><small>${E(a.sub)}</small></span></button>`).join("")}</div>`:empty("Nothing needs attention","The org is within guidance."))}
 <div class="grid g2">${card("AI agents and the humans accountable for them","Each agent reports to a named person who answers for what it does. Tier says how much it may do alone.",`<div class="tscroll"><table><thead><tr><th>Agent</th><th>Tier</th><th>Accountable human</th><th>Task capacity used</th></tr></thead><tbody>${agents.map(a=>`<tr><td>${pchip(a.d.name)}</td><td>${ptag("Tier "+a.t,a.t===3?"warn":a.t===2?"info":"mute")}</td><td>${pchip(a.o)}</td><td class="num">${pc(a.u)}</td></tr>`).join("")}</tbody></table></div>`)}
 ${card("Managed service providers as service teams","A provider is a team with a contract, a service level and a sponsor, not a person.",`<div class="pp2-svc">${msps.map(m=>{const sv=SVCREG.filter(s=>(s.owner===m.name)||(s.sme||[]).includes(m.name)).map(s=>s.n);return `<button class="pp2-sc" data-person="${E(m.name)}">${avatar(m,{size:44})}<span><b>${E(m.name)}</b><small>${E(m.sla||m.role)}</small><small>Contract ${E(m.contract||"")} · sponsor ${E(SPON[m.name]||"")} · ${pc(uNow(m.name))} of contracted hours used</small></span></button>`}).join("")}</div>`)}</div>
 ${card("Teams","Open a team for its people, load and vacancies.",btHTML({id:"pp2_teams",cols:[{k:"team",label:"Team",fmt:r=>`<b>${E(r.team)}</b>`},{k:"mgr",label:"Manager",fmt:r=>r.mgr?pchip(r.mgr):""},{k:"n",label:"Workers"},{k:"human",label:"Employees"},{k:"ai",label:"AI"},{k:"ct",label:"Contractors"},{k:"msp",label:"Providers"},{k:"u",label:"Load, next 12 weeks",val:r=>Math.round(r.u*100),fmt:r=>`<span class="pill ${uCls(r.u)}">${pc(r.u)}</span>`},{k:"over",label:"People over 100%"},{k:"vac",label:"Vacancies"}],rows:tr,key:"id",h:340,rowH:44,exportName:"teams",open:id=>ACT.team({dataset:{a:id}})}))}`}
function orgChart(){const kinds=mpHTML({id:"pp2k",label:"Kinds of worker",opts:Object.entries(KINDS).map(([v,l])=>({v,l})),all:"All kinds"});const tm=mpHTML({id:"pp2t",label:"Teams",opts:teamList().map(t=>({v:t,l:t})),all:"All teams"});
 const tray=`<aside class="card glass pp2-tray"><div class="cardhead"><div><h3>Open work</h3><span class="muted small" data-role="story">Work goes to a team first. Drag a card onto a team on the Work queue tab, then a person claims it or you assign it with a reason.</span></div></div><div class="pp2-wl">${st.org.wq.filter(i=>!i.owner).slice(0,8).map(wi).join("")||empty("All work has an owner","")}</div><button class="btn" data-pp2-tab="ppl_org:5">Open the work queue</button></aside>`;
 return `<div class="pp2-bar"><label class="pp2-search"><span class="muted small">Jump to a person, role, skill or team</span><input type="search" class="txtin" placeholder="Search ${fmt(DIR.length)} workers" value="${E(st.org.q)}" data-pp2-orgq aria-label="Search the org chart" autocomplete="off"><div class="pp2-sug" id="pp2Sug" role="listbox"></div></label>${kinds}${tm}<label class="muted small">Levels open<select data-pp2-depth>${[1,2,3,4,99].map(d=>`<option value="${d}" ${st.org.depth===d?"selected":""}>${d===99?"All":d}</option>`).join("")}</select></label><div class="row"><button class="btn" data-pp2-act="zoom" data-a="-1" aria-label="Zoom out">−</button><button class="btn" data-pp2-act="zoom" data-a="0">Fit</button><button class="btn" data-pp2-act="zoom" data-a="1" aria-label="Zoom in">+</button><button class="btn" data-pp2-act="all" data-a="1">Expand all</button><button class="btn" data-pp2-act="all" data-a="0">Collapse</button></div><div class="row"><button class="btn primary" data-pp2-act="addw">Add worker</button><button class="btn" data-pp2-act="addvac">Add vacancy</button></div></div>
 <div class="pp2-key">${KLEG}<span class="muted small">Agents hang under their accountable human, contractors and providers under their sponsor. Ring text is this week's load. Dimmed cards do not match the filter.</span></div>
 <div class="pp2-split">${tray}<div class="card glass pp2-chartcard"><div class="cardhead"><div><h3>${E(who(ROOT).name)} and ${fmt(DIR.length-1)} others</h3><span class="muted small" data-role="story">Select a card for the full profile. Use + and − to open or close a team; big branches show twelve people at a time.</span></div>${stdChip("tt","The team topology tab shows the same teams by team type and how they interact.")}</div><div class="pp2-treewrap" id="pp2Tree"><div class="pp2-tree" style="zoom:${st.org.zoom}"><ul>${branch(ROOT,0)}</ul></div></div>${vacHTML()}</div></div>`}
const wi=i=>`<div class="pp2-wi" data-dnd-id="${i.id}" tabindex="0" role="group" aria-label="${E(i.t)}">${grip}<div class="pp2-wt"><b>${E(i.t).replace(/-/g,"\u2011")}</b><small class="muted">${i.h} h a week · ${i.n} wk from ${WK[i.w0].lab} · ${E(i.src)}</small><span class="row" style="gap:6px"><span class="pill ${i.risk==="high"?"bad":i.risk==="med"?"warn":"mute"}">${i.risk} risk</span>${i.owner?`<span class="pill info">${E(i.owner)}</span>`:i.team?`<span class="pill metric">${E(i.team)} queue</span>`:""}</span></div><button class="btn quiet" data-pp2-act="assign" data-a="${i.id}">${i.owner?"Move":"Assign"}</button></div>`;
function queueTab(){const teams=teamList();const cols=[["__none","Unassigned"]].concat(teams.map(t=>[t,t]));
 return `<p class="story" data-role="story">Work waits in a team queue (ITIL assigns to a group first). <b>${st.org.wq.filter(i=>!i.owner&&!i.team).length}</b> items have no team, <b>${st.org.wq.filter(i=>!i.owner&&i.team).length}</b> wait for someone on their team to claim them, <b>${st.org.wq.filter(i=>i.owner).length}</b> have a named person. Drag a card between teams; use Assign to give it to a person with a reason.</p>
 <div class="pp2-kanban">${cols.map(([k,l])=>{const L=st.org.wq.filter(i=>k==="__none"?!i.team&&!i.owner:i.team===k&&!i.owner);return `<div class="pp2-kc"><h4>${E(l)} <span class="muted">${L.length}</span></h4><div class="pp2-kl" data-dnd="${E(k)}" data-dnd-scope="pp2wq">${L.map(wi).join("")}</div></div>`}).join("")}</div>
 ${card("Assigned to a person","Drag a card back to a team queue to release it.",`<div class="pp2-asg">${st.org.wq.filter(i=>i.owner).map(i=>`<div class="pp2-ar">${pchip(i.owner)}<span><b>${E(i.t)}</b><small class="muted">${i.h} h a week · ${E(i.team||"")}</small></span><button class="btn quiet" data-pp2-act="release" data-a="${i.id}">Release to team</button></div>`).join("")||empty("Nothing assigned yet","")}</div>`)}
 ${card("Reassignment audit","Every move of work, with its effect on the new owner and who approved it.",st.org.audit.length?`<div class="tscroll"><table><thead><tr><th>Time</th><th>Work item</th><th>From</th><th>To</th><th>Load after</th><th>By</th><th>Why</th><th></th></tr></thead><tbody>${st.org.audit.map((x,i)=>`<tr><td>${E(x.t)}</td><td>${E(x.item)}</td><td>${E(x.from||"")}</td><td>${E(x.to||"")}</td><td class="num">${x.before==null?"":pc(x.before)+" → "}<b>${pc(x.after)}</b></td><td>${E(x.by)}</td><td class="muted small">${E(x.why)}</td><td>${x.iid?`<button class="btn quiet" data-pp2-act="undo" data-a="${i}">Undo</button>`:""}</td></tr>`).join("")}</tbody></table></div>`:empty("No reassignments yet",""))}`}
DND.on("pp2wq",(id,from,to,idx)=>{const it=st.org.wq.find(x=>x.id===id);if(!it)return;const t=to==="__none"?null:to;if(it.team===t)return;const was=it.team;it.team=t;it.owner=null;bumpMv();st.org.audit.unshift({t:new Date().toLocaleTimeString("en-US",{hour:"2-digit",minute:"2-digit"}),item:it.t,from:was?was+" queue":"Unassigned",to:t?t+" queue":"Unassigned",before:null,after:null,by:"Omar Hamid",why:"Dragged on the work queue"});audit("moved work to team queue",it.t+" → "+(t||"unassigned"));toast(t?it.t.slice(0,40)+" is in the "+t+" queue":"Back to unassigned","good");render()});
function listTab(){const rows=()=>DIR.map(d=>{const u=uNow(d.name,0),u12=avgU(PM(d.name),0,11);return {id:d.name,name:d.name,kind:KINDS[d.kind],role:roleOf(d),team:d.team||"",rel:HX().par.get(d.name)||"",span:spanOf(d.name),size:HX().size.get(d.name)||0,u:u,u12:u12,hrs:d.kind==="msp"?(MSPH[d.name]||160):d.hrs||40,lvl:levelOf(d),fam:rfam(d),ten:d.tenure||""}});
 return btHTML({id:"pp2_people",cols:[{k:"name",label:"Name",fmt:r=>pchip(r.name)},{k:"kind",label:"Kind",fmt:r=>kindPill(who(r.name).kind),val:r=>r.kind},{k:"role",label:"Role"},{k:"team",label:"Team"},{k:"rel",label:"Manager, accountable human or sponsor",fmt:r=>r.rel?E(r.rel):"",val:r=>r.rel},{k:"span",label:"Direct reports"},{k:"size",label:"Organization size"},{k:"u",label:"Load this week",val:r=>r.u==null?-1:Math.round(r.u*100),fmt:r=>`<span class="pill ${uCls(r.u)}">${pc(r.u)}</span>`},{k:"u12",label:"Load, 12 weeks",val:r=>Math.round(r.u12*100),fmt:r=>`<span class="pill ${uCls(r.u12)}">${pc(r.u12)}</span>`},{k:"hrs",label:"Hours a week"},{k:"lvl",label:"Level"},{k:"fam",label:"Role family"}],rows,key:"id",h:560,rowH:46,facets:["kind","team","fam"],groupBy:["team","kind","fam"],exportName:"org-people",open:id=>person360(id)})}
function matrixData(){const WK0=wdOf(WEEK0);let tasks=[],P=null;try{tasks=PPMX.tasksOf({}).filter(t=>!t.ms&&t.pct<100);P=PPMX.plan("now",PPMX.tasksOf({}))}catch(e){return {projs:[],cells:{},teams:[]}}
 const cells={},totP={};const teamOfName=nm=>{const r=who(nm);return r&&r.name===nm?r.team:nm};
 tasks.forEach(t=>{const r=P.R[t.id];if(!r)return;const ov=Math.max(0,Math.min(r.ef,WK0+60)-Math.max(r.es,WK0));if(ov<=0)return;const weeks=ov/5;const add=(tm,f)=>{if(!tm)return;const k=tm+"|"+t.p;cells[k]=(cells[k]||0)+f*weeks/12;totP[t.p]=(totP[t.p]||0)+f*weeks/12};(t.res||[]).forEach(([n,f])=>add(teamOfName(n),f));(t.asg||[]).forEach(([n,u])=>add(teamOfName(n),u/100));if(!(t.res||[]).length&&!(t.asg||[]).length&&t.own)add(teamOfName(t.own),.2)});
 const projs=PPMX.projects().filter(p=>totP[p.id]).sort((a,b)=>totP[b.id]-totP[a.id]).slice(0,10);const teams=teamList().filter(t=>projs.some(p=>cells[t+"|"+p.id]));return {projs,cells,teams,totP}}
function matrixTab(){const M=matrixData();if(!M.projs.length)return empty("No project allocations found","The planning engine has no open tasks with resources.");const mx=Math.max(.5,...Object.values(M.cells));
 return `<p class="story" data-role="story">Matrix view: each team is a row and each project a column. A cell is the average full-time equivalent (FTE) the project needs from that team over the next 12 weeks. People keep one line manager and are lent to projects, so each person's FTE across columns adds up to their load.</p>
 <div class="tscroll"><table class="pp2-mx"><thead><tr><th>Team</th>${M.projs.map(p=>`<th><button class="pp2-lnk" data-pp2-act="mxproj" data-a="${p.id}">${E(p.short||p.n)}</button></th>`).join("")}<th>Total</th></tr></thead><tbody>${M.teams.map(t=>{let tot=0;return `<tr><th scope="row">${E(t)}</th>${M.projs.map(p=>{const v=M.cells[t+"|"+p.id]||0;tot+=v;return `<td>${v?`<button class="pp2-mc" data-pp2-act="mxcell" data-a="${E(t)}|${p.id}" style="--a:${Math.round(10+v/mx*70)}%">${f1(v)}</button>`:""}</td>`}).join("")}<td class="num"><b>${f1(tot)}</b></td></tr>`}).join("")}<tr><th scope="row">Project total</th>${M.projs.map(p=>`<td class="num"><b>${f1(M.totP[p.id]||0)}</b></td>`).join("")}<td></td></tr></tbody></table></div><div class="legend" role="note"><span><i style="background:var(--accent);opacity:.5"></i>Darker is more FTE</span><span>Values are FTE averaged over 12 weeks (hours ÷ 40)</span></div>`}
const TOPO={"Editors":["stream","Stream-aligned: standards publishing"],"Service desk":["stream","Stream-aligned: employee support"],"Finance":["stream","Stream-aligned: finance operations"],"Platform team":["platform","Platform: Codification platform and APIs"],"Ops team":["platform","Platform: hosting, monitoring and runbooks"],"Data team":["platform","Platform: data and taxonomy services"],"AI agents":["platform","Platform: agents under the AI gateway"],"Architecture":["enable","Enabling: patterns and design reviews"],"Security":["enable","Enabling: identity, access and controls"],"PMO":["enable","Enabling: delivery governance"],"Change management":["enable","Enabling: change and release practice"],"Lumen (vendor)":["sub","Complicated subsystem: search indexing"],"Leadership":["enable","Enabling: direction and funding"]};
const TOPOT={stream:["Stream-aligned","--good-f"],platform:["Platform","--p4"],enable:["Enabling","--u3"],sub:["Complicated subsystem","--w1"]};
const TEDGE=[["Platform team","Editors","xaas"],["Data team","Editors","xaas"],["Ops team","Service desk","xaas"],["Architecture","Platform team","facil"],["Security","Platform team","facil"],["Security","Service desk","facil"],["Lumen (vendor)","Platform team","collab"],["Lumen (vendor)","Data team","collab"],["PMO","Platform team","facil"],["Change management","Ops team","collab"],["AI agents","Service desk","xaas"],["AI agents","Editors","xaas"],["Finance","PMO","collab"]];
const TMODE={collab:["Collaboration","--w1"],xaas:["X-as-a-service","--p4"],facil:["Facilitating","--u3"]};
function topoTab(){const rows=teamList().filter(t=>TOPO[t]);const lanes=["stream","platform","enable","sub"];const pos={};lanes.forEach((l,li)=>rows.filter(t=>TOPO[t][0]===l).forEach((t,i)=>pos[t]={x:70+i*150,y:48+li*118,l}));
 const W=Math.max(640,...Object.values(pos).map(p=>p.x+110)),Hh=48+4*118;
 const svcN=t=>SVCREG.filter(s=>{const o=who(s.owner);return o&&o.team===t}).length;
 const edges=TEDGE.filter(e=>pos[e[0]]&&pos[e[1]]).map(e=>{const a=pos[e[0]],b=pos[e[1]],m=TMODE[e[2]];return `<path d="M${a.x} ${a.y+20}C${a.x} ${(a.y+b.y)/2+20} ${b.x} ${(a.y+b.y)/2-10} ${b.x} ${b.y-20}" fill="none" stroke="var(${m[1]})" stroke-width="2.4" ${e[2]==="facil"?'stroke-dasharray="6 5"':e[2]==="collab"?'stroke-dasharray="1 5" stroke-linecap="round"':""}><title>${E(e[0])} to ${E(e[1])}: ${m[0]}</title></path>`}).join("");
 const nodes=rows.map(t=>{const p=pos[t],n=DIR.filter(d=>d.team===t).length,cl=svcN(t)/Math.max(1,DIR.filter(d=>d.team===t&&d.kind==="human").length);const big=n>9&&TOPO[t][0]!=="platform";return `<g class="pp2-tn" data-pp2-act="team" data-a="${E(t)}" tabindex="0" role="button" aria-label="${E(t)}, ${n} workers"><rect x="${p.x-62}" y="${p.y-22}" width="124" height="44" rx="12" fill="var(${TOPOT[p.l][1]})" opacity=".22" stroke="var(${TOPOT[p.l][1]})" stroke-width="${big?3:1.5}"/><text x="${p.x}" y="${p.y-3}" text-anchor="middle" font-size="12" font-weight="700" fill="currentColor">${E(t.length>17?t.slice(0,16)+"…":t)}</text><text x="${p.x}" y="${p.y+13}" text-anchor="middle" font-size="10.5" fill="currentColor" opacity=".7">${n} workers · ${svcN(t)} svc</text></g>`}).join("");
 const lb=lanes.map((l,li)=>`<text x="6" y="${48+li*118-30}" font-size="11" font-weight="700" fill="currentColor" opacity=".7">${TOPOT[l][0]}</text>`).join("");
 return `<p class="story" data-role="story">Team Topologies view: ${rows.length} teams in four types. Platform teams offer services; stream-aligned teams own a flow of work; enabling teams coach; Lumen owns a complicated subsystem. A thick outline marks a stream-aligned or enabling team larger than 9 people, the size guidance in the model.</p><div class="pp2-topo"><svg viewBox="0 0 ${W} ${Hh}" width="${W}" height="${Hh}" role="img" aria-label="Team topology of Meridian">${lb}${edges}${nodes}</svg></div>${legend(Object.values(TMODE).map(m=>[m[0],m[1]]))}${legend(lanes.map(l=>[TOPOT[l][0],TOPOT[l][1]]))}${card("Team types","Each team's type, its job and how loaded it is.",`<div class="tscroll"><table><thead><tr><th>Team</th><th>Type and job</th><th>Workers</th><th>Services owned</th><th>Load, 12 weeks</th></tr></thead><tbody>${rows.map(t=>{const a=teamAgg(t,null);return `<tr><td><button class="pp2-lnk" data-pp2-act="team" data-a="${E(t)}">${E(t)}</button></td><td>${E(TOPO[t][1])}</td><td class="num">${DIR.filter(d=>d.team===t).length}</td><td class="num">${svcN(t)}</td><td><span class="pill ${uCls(avgU(a,0,11))}">${pc(avgU(a,0,11))}</span></td></tr>`}).join("")}</tbody></table></div>`)}`}
function workloadTab(){const tm=mpHTML({id:"pp2wt",label:"Teams to show",opts:teamList().map(t=>({v:t,l:t})),all:"All teams",def:null});const sel=S.mpSel.pp2wt?mpGet("pp2wt"):teamList().slice(0,1);if(!S.mpSel.pp2wt)S.mpSel.pp2wt=sel;const lim=30+(st.org.wmore||0);
 const names=DIR.filter(d=>sel.includes(d.team)&&d.kind!=="msp").map(d=>d.name).sort((a,b)=>Math.max(...Array.from(PM(b).util.slice(0,8)))-Math.max(...Array.from(PM(a).util.slice(0,8))));
 const cell=(n,w)=>{const m=PM(n),u=m.cap[w]>.5?m.tot[w]/m.cap[w]:null;return `<button class="pp2-hc" style="--cc:var(${uCol(u)});--a:${u==null?30:u>1?Math.min(88,60+(u-1)*120):u>.85?58:u>=.5?36+(u-.5)*40:26}" data-pp2-act="cell" data-a="${E(n)}|${w}" aria-label="${E(n)}, week of ${WK[w].lab}, ${pc(u)}">${u==null?"Off":Math.round(u*100)}</button>`};
 return `<div class="pp2-bar">${tm}<span class="muted small">Showing ${Math.min(lim,names.length)} of ${names.length} workers, busiest first. The full 52 weeks, all teams and all work types are in Resource planning.</span><button class="btn" data-go="ppl_cap">Open Resource planning</button></div><div class="tscroll"><div class="pp2-heat" style="--cols:8"><div class="pp2-hr pp2-hh"><span></span>${WK.slice(0,8).map(w=>`<b>${w.lab}</b>`).join("")}</div>${names.slice(0,lim).map(n=>`<div class="pp2-hr"><span class="pp2-hn">${pchip(n)}</span>${[0,1,2,3,4,5,6,7].map(w=>cell(n,w)).join("")}</div>`).join("")}</div></div>${names.length>lim?`<button class="btn" data-pp2-act="wmore">Show 30 more</button>`:""}<div class="legend" role="note">${[["--p6","under 50%"],["--good-f","50 to 85%"],["--warn-f","85 to 100%"],["--bad-f","over 100%"]].map(([c,t])=>`<span><i style="background:var(${c})"></i>${t}</span>`).join("")}<span>Formula: demand hours ÷ (contract hours − PTO − holidays)</span></div>`}
function syncMetricsOrg(){}
function orgScreen(){const O=orgStats();const tab=tabIdx("ppl_org",6);const t0=performance.now();
 const story=`<b>${fmt(DIR.length)} workers</b> in one chart: ${fmt(O.k.human)} employees, ${fmt(O.k.ai)} AI agents each under a named human, ${fmt(O.k.contractor)} contractors under a sponsor and ${fmt(O.k.msp)} managed service providers as service teams. <b>${O.over.length}</b> ${O.over.length===1?"person is":"people are"} over capacity the week of ${WK[st.org.week].lab}${O.over.length?", led by "+O.over.slice(0,3).map(d=>E(d.name)).join(", "):""}. ${O.wide.length?`<b>${E(O.wide[0].n)}</b> has the widest span at ${O.wide[0].s}. `:""}${O.vac.length} vacancies are open.`;
 const panes=[orgDash,orgChart,listTab,matrixTab,topoTab,()=>queueTab()+"<div class=\"pp2-div\"></div>"+workloadTab()];
 return `<div class="screen">${hero("People and work","Who is carrying what",story,`<div class="row">${fchip("m_pp_util")}${fchip("m_pp_over")}<button class="btn primary" data-pp2-act="addw">Add worker</button><button class="btn" data-pp2-act="addvac">Add vacancy</button>${stdChip("tt")}${stdChip("hr")}${aiChip({model:"Resource Agent",conf:.84,title:"How load and spans were computed",src:["Directory (employees, agents, contractors, providers)","Schedule engine tasks","Incidents, requests, changes","Approved PTO and holidays"],guards:["Proposes only. You decide.","Does not see pay or performance data"]})}${whyPop("Workload comes from every kind of work: projects, incidents, requests, changes, on-call, operational work, meetings, time off and training.")}</div>`)}${lensNote()}${tabsBar("ppl_org",["Dashboard","Org chart","List","Matrix","Team topology","Work queue and weekly load"])}<div class="pp2-pane">${panes[tab]()}</div>${procCard("ppl_org")}</div>`}
REG("ppl_org","Org chart and workload","people","M9 3h6v5H9zM3 16h6v5H3zM15 16h6v5h-6zM12 8v4M6 16v-4h12v4",orgScreen);
PROC.reg("ppl_org",{title:"How a person, agent, contractor or provider joins the org",std:["itil5","hr","tt"],steps:[{n:"Request",d:"A manager opens a vacancy or resource request for a skill and a period.",who:"human",owner:"Omar Hamid",sla:"Same day",in:"Business need",out:"Vacancy or resource request"},{n:"Funding gate",d:"CIO approves headcount, or the demand lands in Demand and priorities.",who:"gate",owner:"Omar Hamid",sla:"5 working days",in:"Request and cost",out:"Approved or declined"},{n:"Find the best source",d:"Resource Agent compares an employee, contractor, AI agent or provider for skill, cost and availability.",who:"agent",owner:"Maya Ortiz",sla:"1 day",in:"Skills and dates",out:"Ranked options"},{n:"Onboard",d:"Accounts, equipment, training and the onboarding journey start automatically.",who:"auto",owner:"Nia Brooks",sla:"Before day 1",in:"Accepted option",out:"Active worker"},{n:"Name the line",d:"A manager, accountable human (agent) or sponsor (contractor, provider) is set.",who:"human",owner:"Sam Patel",sla:"Day 1",in:"New worker",out:"Reporting line"},{n:"Review each quarter",d:"Spans, load and contract end dates are reviewed.",who:"auto",owner:"Maya Ortiz",sla:"Quarterly",in:"Org data",out:"Actions"}]});


/* ---- org actions, drawers and forms ---- */
function typeBars(m,w){const mx=Math.max(m.cap[w],m.tot[w],1);return `<div class="pp2-stackbar" role="img" aria-label="Hours by work type">${WT.map(([k,l,c])=>m.T[k][w]>0?`<i style="width:${m.T[k][w]/mx*100}%;background:var(${c})" title="${l}: ${f1(m.T[k][w])} h"></i>`:"").join("")}${m.pto[w]>0?`<i class="pto" style="width:${m.pto[w]/mx*100}%" title="Time off: ${f1(m.pto[w])} h"></i>`:""}<s style="left:${m.cap[w]/mx*100}%"></s></div>`}
const typeLeg=()=>legend(WT.map(x=>[x[1],x[2]]).concat([["Time off","--faint"]]));
function cellDrawer(n,w){const m=PM(n),r=who(n);const u=m.cap[w]>.5?m.tot[w]/m.cap[w]:null;const rows=WT.filter(x=>m.T[x[0]][w]>0).map(x=>`<tr><td><i class="pp2-sw" style="background:var(${x[2]})"></i>${x[1]}</td><td class="num">${f1(m.T[x[0]][w])} h</td><td class="num">${m.tot[w]?Math.round(m.T[x[0]][w]/m.tot[w]*100):0}%</td></tr>`).join("");
 openDrawer(`<div class="eyebrow">Week of ${WK[w].lab}</div><div class="row">${avatar(r,{size:56})}<div><h2 style="font-size:28px;margin:0">${E(n)}</h2>${kindPill(r.kind)}</div></div><p class="story" data-role="story">${E(first(n))} has <b>${f1(m.tot[w])} hours</b> of work against <b>${f1(m.cap[w])} available hours</b> (${f1(m.base)} contracted${m.pto[w]>0?` minus ${f1(m.pto[w])} time off or holidays`:""}), so load is <b>${pc(u)}</b>.${u>1?" That is above a sustainable level.":u!=null&&u<.5?" There is room for more.":""}</p>${typeBars(m,w)}${typeLeg()}<div class="tscroll"><table><thead><tr><th>Work type</th><th>Hours</th><th>Share</th></tr></thead><tbody>${rows||'<tr><td colspan="3" class="muted">No work planned</td></tr>'}</tbody></table></div><div class="row" style="margin-top:14px"><button class="btn primary" data-person="${E(n)}">Open everything on their plate</button><button class="btn" data-pp2-act="gocap" data-a="${E(n)}">Open in Resource planning</button></div>`)}
function teamDrawer(t){const L=DIR.filter(d=>d.team===t),a=teamAgg(t,null),tp=TOPO[t];const vac=st.vac.filter(v=>v.team===t&&v.status!=="Filled");const top=L.filter(d=>d.kind!=="msp").map(d=>({d,u:avgU(PM(d.name),0,11)})).sort((a,b)=>b.u-a.u);const mgr=TEAMMGR(t);
 openDrawer(`<div class="eyebrow">Team${tp?" · "+E(tp[1].split(":")[0]):""}</div><h2 style="font-size:30px;margin:4px 0 8px">${E(t)}</h2><p class="story" data-role="story">${L.length} workers: ${["human","ai","contractor","msp"].map(k=>L.filter(d=>d.kind===k).length+" "+KINDS[k].toLowerCase()+(L.filter(d=>d.kind===k).length===1?"":"s")).join(", ")}. Load over the next 12 weeks is <b>${pc(avgU(a,0,11))}</b>${vac.length?` and ${vac.length} role${vac.length>1?"s are":" is"} still open`:""}.</p>
 <div class="dfullgrid"><div><div class="eyebrow">Demand by work type, next 12 weeks</div>${WT.map(([k,l,c])=>{const s=Array.from(a.T[k]).slice(0,12).reduce((x,y)=>x+y,0)/12;return `<div class="row sp small" style="margin:6px 0"><span><i class="pp2-sw" style="background:var(${c})"></i>${l}</span><b class="num">${f1(s)} h/wk</b></div>`}).join("")}${manager(mgr)}</div>
 <div><div class="eyebrow">Busiest people</div><div class="pp2-asg">${top.slice(0,8).map(x=>`<div class="pp2-ar">${pchip(x.d.name)}<span class="pill ${uCls(x.u)}">${pc(x.u)}</span></div>`).join("")}</div>${top.length>8?`<p class="muted small">${top.length-8} more in the List tab.</p>`:""}${vac.length?`<div class="eyebrow" style="margin-top:12px">Vacancies</div>${vac.map(v=>`<button class="pp2-vc" data-pp2-act="vacancy" data-a="${v.id}"><b>${E(v.title)}</b><small>${E(v.status)}</small></button>`).join("")}`:""}</div></div>
 <div class="row" style="margin-top:14px"><button class="btn primary" data-pp2-act="capteam" data-a="${E(t)}">Open in Resource planning</button><button class="btn" data-pp2-act="addw" data-a="${E(t)}">Add worker to ${E(t)}</button></div>`);function manager(m){return m?`<div class="eyebrow" style="margin-top:12px">Manager</div>${pchip(m)}`:""}}
function vacDrawer(id){const v=st.vac.find(x=>x.id===id);if(!v)return;const days=Math.round((Date.parse("2026-10-06")-Date.parse(v.opened))/DAY);
 openDrawer(`<div class="eyebrow">Vacancy ${E(v.id)}</div><h2 style="font-size:28px;margin:4px 0 8px">${E(v.title)}</h2><p class="story" data-role="story">Open ${days} days in ${E(v.team)}, reporting to ${E(v.mgr)}. Until it is filled, about ${v.kind==="human"?32:36} hours a week of demand is carried by the team or goes unstaffed.</p><dl class="kv"><dt>Status</dt><dd>${ptag(v.status,v.status==="Offer out"?"good":"warn")}</dd><dt>Kind</dt><dd>${kindPill(v.kind)}</dd><dt>Reports to</dt><dd>${pchip(v.mgr)}</dd><dt>Skills</dt><dd>${v.skills.map(s=>ptag(s,"info")).join(" ")}</dd><dt>Loaded annual cost</dt><dd class="num">${money(v.loaded)}</dd></dl>
 <div class="eyebrow">Fill it faster</div><div class="pp2-asg">${[["Contractor","Starts in about 2 weeks at $"+Math.round(v.loaded/1800*1.35)+" an hour",v.kind!=="contractor"],["AI agent","Takes the routine share of the work now, a person keeps the rest",true],["Managed service provider","For steady run work with a service level",v.team==="Service desk"||v.team==="Ops team"]].filter(x=>x[2]).map(x=>`<div class="pp2-ar"><span><b>${x[0]}</b><small class="muted">${x[1]}</small></span><button class="btn quiet" data-pp2-act="resreq" data-a="${E(v.team)}|${E(x[0])}">Raise a resource request</button></div>`).join("")}</div>
 <div class="row" style="margin-top:14px"><button class="btn primary" data-pp2-act="fillvac" data-a="${v.id}">Mark filled</button></div>`)}
