 addw(t){addWorkerForm(t.dataset&&t.dataset.a)},addvac(){addVacForm()},vacancy(t){vacDrawer(t.dataset.a)},fillvac(t){const v=st.vac.find(x=>x.id===t.dataset.a);if(v){v.status="Filled";bump();audit("filled vacancy",v.title);toast(v.title+" marked filled","good");closeDrawer();render()}},
 att(t){const A=attention(orgStats())[+t.dataset.a];if(A)A.f()},team(t){teamDrawer(t.dataset.a)},cell(t){const [n,w]=t.dataset.a.split("|");cellDrawer(n,+w)},wmore(){st.org.wmore=(st.org.wmore||0)+30;render()},
 assign(t){assignForm(t.dataset.a)},release(t){const it=st.org.wq.find(x=>x.id===t.dataset.a);if(it){it.owner=null;bumpMv();audit("released work to team",it.t);toast("Back in the "+(it.team||"team")+" queue","good");render()}},
 undo(t){const x=st.org.audit[+t.dataset.a];const it=x&&st.org.wq.find(y=>y.id===x.iid);if(it){it.owner=null;it.team=x.prevTeam||null;st.org.audit.splice(+t.dataset.a,1);bumpMv();audit("undid assignment",it.t);toast("Assignment undone","good");render()}},
 gocap(t){st.cap.person=t.dataset.a;st.tab.ppl_cap=3;closeDrawer();go("ppl_cap")},capteam(t){S.mpSel.pp2ct=[t.dataset.a];st.tab.ppl_cap=1;closeDrawer();go("ppl_cap")},
 mxproj(t){const p=PROJ.concat(PPMX.projects()).find(x=>x.id===t.dataset.a);if(p)(window.ppmOpenProject||((id)=>go("plan",id)))(p.id)},
 mxcell(t){const [tm,pid]=t.dataset.a.split("|");const tasks=PPMX.tasksOf({p:pid,open:true}).filter(x=>!x.ms&&((x.res||[]).some(r=>r[0]===tm||(who(r[0])||{}).team===tm)||(x.asg||[]).some(a=>(who(a[0])||{}).team===tm)));const p=PPMX.projects().find(x=>x.id===pid)||{};
  openDrawer(`<div class="eyebrow">Matrix cell</div><h2 style="font-size:26px;margin:4px 0 8px">${E(tm)} on ${E(p.n||pid)}</h2><p class="story" data-role="story">${tasks.length} open tasks need people from ${E(tm)}.</p>${lrHTML({id:"pp2mx"+pid,groups:[{key:"t",label:"Open tasks",rows:tasks.map(x=>({id:x.id,t:x.n,sub:"Owner "+(x.own||"")+" · "+x.pct+"% done",tag:x.id,st:x.pct>0?"info":"mute",go:()=>go("plan",pid)}))}],limit:10})}`)},
