function REV(n){let r=PF.rev[n];if(r)return r;const m=mgrOfPerson(n)||"x";const z=(hs(n+"a")+hs(n+"b")+hs(n+"c")-1.5)*1.7;const rating=clamp(Math.round(3.3+mOff(m)+z),1,5);const pot=clamp(Math.round(1.5+(rating-3)*.35+(hs(n+"p")-.5)*1.8+.5),1,3);const u=hs(n+"st");
 const status=u<.04?"Not started":u<.08?"Self review done":u<.42?"Manager draft":"Submitted";
 r=PF.rev[n]={n,rating:status==="Submitted"?rating:null,draft:rating,pot,status,self:u<.04?null:clamp(Math.round(3.4+(hs(n+"s")-.45)*1.6),1,5),comp:null,strengths:"",growth:"",ready:"",by:m,at:status==="Submitted"?"Oct "+(5+Math.floor(hs(n+"d")*2)):"",edited:false};return r}
