 /* real signals where the platform has them */
 try{const tk=TASKS.filter(t=>t.own===n&&t.pct>=100&&t.af!=null&&t.bf!=null);if(tk.length>=2){v.ontime=Math.round(tk.filter(t=>t.af<=t.bf).length/tk.length*1000)/10;src.ontime="Calculated from "+tk.length+" finished schedule tasks you own"}}catch(e){}
