function perfOf(n){const key=n+"|"+PF.v+"|"+(st.ver||0)+"|"+DIR.length;if(PFC["p"+key])return PFC["p"+key];const O=opsOf(n),peers=peersOf(n);const rows=[];let ws=0,acc=0;
 MM.forEach(([k,id,w,d,lab,dec])=>{const v=O.v[k];if(v==null){rows.push({k,id,lab,v:null,dec,w});return}const pv=peers.map(p=>opsOf(p).v[k]).filter(x=>x!=null);const p25=pv.length?pv.slice().sort((a,b)=>a-b)[Math.floor(pv.length*.25)]:v,p75=pv.length?pv.slice().sort((a,b)=>a-b)[Math.floor(pv.length*.75)]:v;let pct=pctOf(pv,v);if(d==="min")pct=100-pct;
  rows.push({k,id,lab,v,dec,w,pv,med:med(pv),p25,p75,pct,band:bandOf(id,v),d,src:O.src[k]});ws+=w;acc+=w*pct});
 const idx=ws?Math.round(acc/ws):null;
 /* fairness: hours and mix versus peers */
 const m=PM(n),hrs=mean(Array.from(m.tot).slice(0,12)),ph=peers.length?mean(peers.map(p=>mean(Array.from(PM(p).tot).slice(0,12)))):hrs,oc=mean(Array.from(m.T.oncall).slice(0,12)),poc=peers.length?mean(peers.map(p=>mean(Array.from(PM(p).T.oncall).slice(0,12)))):oc,inc=mean(Array.from(m.T.inc).slice(0,12)),pin=peers.length?mean(peers.map(p=>mean(Array.from(PM(p).T.inc).slice(0,12)))):inc,pto=m.pto.slice(0,12).reduce((a,b)=>a+b,0)/m.base;
 const flags=[];if(hrs>ph*1.15)flags.push(["warn","Carries "+Math.round((hrs/ph-1)*100)+"% more planned hours than peers ("+f1(hrs)+" vs "+f1(ph)+" a week). Output per hour may be a fairer comparison."]);if(oc>poc*1.8&&oc>2)flags.push(["warn","On-call load is "+f1(oc/Math.max(.1,poc))+" times the peer average. Interrupted weeks lower planned-task results."]);if(inc>pin*1.4&&inc>3)flags.push(["info","Takes "+Math.round((inc/Math.max(.1,pin)-1)*100)+"% more incident work than peers. Incident work is harder to plan."]);if(pto>.25)flags.push(["info","About "+Math.round(pto*5)+" working days of the last 12 weeks were time off. The evidence window is shorter, so small samples swing more."]);if(peers.length<5)flags.push(["info","Only "+peers.length+" peers in this group, so percentiles are rough. Compared with the whole "+rfam(who(n)).toLowerCase()+" family instead."]);
 const out={n,rows,idx,peers:peers.length,flags,hrs,ph,oc,poc,fam:O.fam};PFC["p"+key]=out;return out}
function trendFor(n,id){const o=perfOf(n),r=o.rows.find(x=>x.id===id);const v=r&&r.v!=null?r.v:METRICS[id].cur;const s=(hs(n+id+"tr")-.5)*.12;return [...Array(8)].map((_,i)=>+(v*(1+s*(7-i)/7*(i%2?1:.6))).toFixed(2)).map((x,i,a)=>i===7?v:x)}
