 const names=DIR.filter(d=>d.kind!=="msp"&&d.kind!=="ai").slice(0,60).map(d=>perfOf(d.name).idx).filter(x=>x!=null);if(names.length)METRICS.m_pf_idx.cur=Math.round(mean(names));
