function goalForm(pre){const tg=teamGoals();openForm({id:"pp2_goal",title:"Add a goal",story:"A goal has an owner, a measurable result and a parent. A personal goal links to a team goal and a team goal links to a strategic objective, which is how the work is traced to strategy.",submit:"Add goal",fields:[{k:"level",label:"Level",type:"chips",req:true,opts:[["person","Personal"],["team","Team"]]},{k:"owner",label:"Owner",type:"select",req:true,opts:DIR.filter(d=>d.kind==="human").slice(0,300).map(d=>[d.name,d.name+" · "+d.team]),ph:"Choose an owner"},{k:"title",label:"Objective",type:"text",req:true,ph:"Cut mean time to restore on the portal",ai:{label:"Sharpen",fn:v=>(v.title||"Improve a service")+" by a measurable amount before Dec 18"}},{k:"kr",label:"Key result",type:"text",req:true,ph:"From 5 hours to 3 hours"},{k:"parent",label:"Supports team goal",type:"select",opts:tg.map(t=>[t.id,t.team+": "+t.title]),show:v=>v.level==="person",ph:"Optional but recommended"},{k:"obj",label:"Strategic objective",type:"select",opts:companyObjs().map(o=>[o.id,o.n]),show:v=>v.level==="team",ph:"Choose an objective"}],defaults:Object.assign({level:"person"},pre||{}),
 live:v=>v.level==="person"&&!v.parent?'<p class="small" style="color:var(--warn)">Without a team goal this personal goal will count as not linked to strategy.</p>':"",
 onSubmit:v=>{const r=who(v.owner);const g={id:"G-"+Date.now(),owner:v.owner,level:v.level,title:v.title,kr:v.kr,team:r?r.team:"",parent:v.parent||null,obj:v.obj||(v.parent&&(tg.find(t=>t.id===v.parent)||{}).obj)||null,pct:0,conf:"warn",due:"2026-12-18"};if(v.level==="team")g.krs=[{n:v.kr,start:0,tgt:100,cur:0,p:0}];PF.goals.push(g);pfBump();audit("added goal",v.title);return {toast:"Goal added"+(g.obj?" and linked to strategy":"")}}})}
function checkinForm(id){const all=teamGoals().concat(reviewees().flatMap(d=>goalsOf(d.name)));const g=all.find(x=>x.id===id);if(!g)return;openForm({id:"pp2_checkin",title:"Check in: "+g.title,story:"A check-in takes a minute: where is it now, how confident are you, what is in the way. Weekly check-ins are what make goals useful.",submit:"Save check-in",fields:[{k:"pct",label:"Progress",type:"range",min:0,max:100,unit:"%"},{k:"conf",label:"Confidence",type:"chips",opts:[["good","On track"],["warn","At risk"],["bad","Off track"]]},{k:"note",label:"What is in the way",type:"longtext",wide:true}],defaults:{pct:g.pct,conf:g.conf},onSubmit:v=>{g.pct=+v.pct;g.conf=v.conf;pfBump();audit("goal check-in",g.title+": "+v.pct+"%");return {toast:"Check-in saved"}}})}
function linkForm(id){const g=reviewees().flatMap(d=>goalsOf(d.name)).concat(PF.goals).find(x=>x.id===id);if(!g)return;const r=who(g.owner);openForm({id:"pp2_link",title:"Link a goal",story:"Pick the team goal this one supports. The strategic objective follows from it.",submit:"Link",fields:[{k:"p",label:"Team goal",type:"select",req:true,opts:teamGoals().filter(t=>t.team===(r||{}).team||true).map(t=>[t.id,t.team+": "+t.title])}],defaults:{p:(teamGoals().find(t=>t.team===(r||{}).team)||{}).id},onSubmit:v=>{const t=teamGoals().find(x=>x.id===v.p);g.parent=v.p;g.obj=t&&t.obj;pfBump();audit("linked goal",g.title+" → "+(t&&t.title));return {toast:"Linked to "+(t?t.title:"a team goal")}}})}
function succForm(role){openForm({id:"pp2_succ",title:"Add a successor for "+role,story:"Names a successor with a readiness. A leader reviews the bench each quarter.",submit:"Add",fields:[{k:"n",label:"Successor",type:"select",req:true,opts:DIR.filter(d=>d.kind==="human").slice(0,300).map(d=>[d.name,d.name+" · "+d.role]),ph:"Choose a person"},{k:"ready",label:"Readiness",type:"chips",req:true,opts:["Ready now","1 to 2 years","3 or more years"]}],defaults:{ready:"1 to 2 years"},onSubmit:v=>{PF.succ=PF.succ||{};const k=KEYROLES.find(x=>x[0]===role);const cur=succOf(k).filter(x=>x.n!==v.n);PF.succ[role]=cur.concat([{n:v.n,ready:v.ready}]);audit("added successor",role+": "+v.n);return {toast:v.n+" added to the bench for "+role}}})}
function oneForm(w){const o=oneOn(myMgr).find(x=>x.w===w)||{cad:"Weekly",last:7};openForm({id:"pp2_one",title:"Plan a 1:1 with "+w,story:"Builds an agenda from open actions, recent feedback and goals due. First Officer files the notes you approve.",submit:"Add to calendar",fields:[{k:"when",label:"When",type:"date",req:true},{k:"agenda",label:"Agenda",type:"longtext",wide:true,ai:{label:"Draft agenda",fn:v=>"1. Wins since last time\n2. Goals and blockers ("+goalsOf(w).map(g=>g.title).slice(0,2).join("; ")+")\n3. Feedback to share\n4. Career and development"}}],defaults:{when:"2026-10-08"},onSubmit:v=>{audit("planned 1:1",w+" on "+v.when);return {toast:"1:1 with "+w+" planned"}}})}
function r360Drawer(id){const x=PF.f360.find(y=>y.id===id);if(!x)return;const d=x.rev.filter(r=>r[1]==="done").length;openDrawer(`<div class="eyebrow">360 summary</div><h2 style="font-size:28px;margin:4px 0">${E(x.subject)}</h2><p class="story" data-role="story">${d} of ${x.rev.length} people responded. Answers are anonymous and shown only as averages and themes. ${AIC("How the 360 themes were summarized")}</p>${COMPS.slice(0,6).map(c=>{const v=+(2.4+hs(x.subject+c[0]+"360")*1.5).toFixed(1);return `<div class="pp2-mr"><div class="row sp"><b>${c[1]}</b><span class="num">${v} of 4</span></div>${bar(v/4*100,"--accent")}</div>`}).join("")}<div class="pp2-nar"><p><b>Themes</b> Seen as calm under pressure and clear in writing. Several respondents would like earlier notice when priorities change.</p><p class="small muted">Themes are drafted from free-text answers with names and identifying details removed. The manager reads them with ${E(x.subject)}; nobody sees who said what.</p></div>`)}
function allCell(k){const [p,q]=k.split("_");const L=reviewees().filter(d=>{const b=boxOf(d.name);return b.perf+"_"+b.pot===k&&(REV(d.name).status==="Submitted"||PF.cal[d.name])&&mpGet("pp2nt").includes(d.team)});openDrawer(`<div class="eyebrow">9-box</div><h2 style="font-size:28px;margin:4px 0">${NB[k][0]} <span class="muted">${L.length}</span></h2><p class="story" data-role="story">${NB[k][1]}.</p>${lrHTML({id:"pp2nb"+k,groups:[{key:"a",label:"People",rows:L.map(d=>({id:d.name,t:d.name,sub:d.team+" · rating "+REV(d.name).rating,tag:levelOf(d),st:"info",go:()=>perfDrawer(d.name)}))}],limit:12})}`)}
Object.assign(ACT,{review(t){closeDrawer();reviewForm(t.dataset.a)},giveFb(t){closeDrawer();fbForm(t.dataset&&t.dataset.a)},req360(t){closeDrawer();f360Form(t.dataset&&t.dataset.a)},devadd(t){closeDrawer();devForm(t.dataset.a)},goal(t){goalDrawer(t.dataset.a)},checkin(t){closeDrawer();checkinForm(t.dataset.a)},linkgoal(t){closeDrawer();linkForm(t.dataset.a)},addgoal(){goalForm()},nball(t){allCell(t.dataset.a)},patt(t){const A=pfAttention()[+t.dataset.a];if(A)A.f()},r360(t){r360Drawer(t.dataset.a)},nudge360(t){const x=PF.f360.find(y=>y.id===t.dataset.a);if(x){x.rev.forEach(r=>{if(r[1]==="pending"&&hs(r[0]+x.id)>.4)r[1]="done"});audit("reminded 360 reviewers",x.subject);toast("Reminders sent. Some reviewers have answered.","good");render()}},oneon(t){oneForm(t.dataset.a)},succadd(t){succForm(t.dataset.a)},perfopen(t){perfDrawer(t.dataset.a)},
 sugrev(t){const f=FORMST.pp2_f360;if(f){f.vals.rev=(f.vals.rev||[]).includes(t.dataset.a)?f.vals.rev:(f.vals.rev||[]).concat(t.dataset.a);refreshLive("pp2_f360");toast(t.dataset.a+" added","good")}}});
/* Person 360: performance and growth */
P360_TABS.push({label:"Performance and growth",fn:r=>{const n=r.name;let h=perfBlock(n,true);if(r.kind==="human"){const dv=devOf(n),p=promo(n),g=goalsOf(n);h+=`<div class="eyebrow" style="margin-top:14px">Goals and growth</div><dl class="kv"><dt>Goals</dt><dd>${g.map(x=>E(x.title)+" ("+x.pct+"%)").join("; ")}</dd><dt>Development focus</dt><dd>${E(dv.focus)}</dd><dt>Promotion readiness</dt><dd>${p.label} (${p.ok} of 4 criteria)</dd><dt>Succession</dt><dd>${KEYROLES.filter(k=>succOf(k).some(s=>s.n===n)).map(k=>"Bench for "+k[0]).join(", ")||"Not on a bench"}</dd></dl>`}
 return h+`<div class="row" style="margin-top:12px"><button class="btn primary" data-pp2-act="perfopen" data-a="${E(n)}">Open the full evidence</button>${r.kind==="human"?`<button class="btn" data-pp2-act="review" data-a="${E(n)}">Review</button><button class="btn" data-pp2-act="giveFb" data-a="${E(n)}">Give feedback</button>`:""}</div>`}});
/* work providers: what people owe in the performance process */
WORK.push({kind:"Reviews to write",tag:"REV",fn:n=>kidsOf(n).filter(k=>kindOf(k)==="human").filter(k=>REV(k).status!=="Submitted").slice(0,6).map(k=>({id:"REV-"+k,t:"Review for "+k,sub:revPillText(REV(k).status)+" · closes Oct 23",due:"Oct 23",st:"warn",hrs:1.5,go:()=>{go("ppl_perf");setTimeout(()=>reviewForm(k),80)}}))});
WORK.push({kind:"Feedback and 360 requests",tag:"FB",fn:n=>PF.f360.filter(x=>x.rev.some(r=>r[0]===n&&r[1]==="pending")).map(x=>({id:"R360-"+x.id,t:"360 feedback about "+x.subject,sub:"Due "+DT(x.due)+" · anonymous",due:DT(x.due),st:"info",hrs:.5,go:()=>go("ppl_perf")}))});
WORK.push({kind:"Development actions",tag:"DEV",fn:n=>{const d=PF.dev[n];return d?d.actions.filter(a=>a.st!=="Done").map((a,i)=>({id:"DEV-"+i,t:a.t,sub:"Development plan · due "+DT(a.due),due:DT(a.due),st:"mute",hrs:1,go:()=>perfDrawer(n)})):[]}});
WORK.push({kind:"Assigned work queue",tag:"WQ",fn:n=>st.org.wq.filter(i=>i.owner===n).map(i=>({id:i.id,t:i.t,sub:i.h+" h a week for "+i.n+" weeks · "+i.src,due:"",st:i.risk==="high"?"bad":"info",hrs:i.h,go:()=>{st.tab.ppl_org=5;go("ppl_org")}}))});
