function syncCap(){try{const names=DIR.map(d=>d.name);const a=agg(names,"all:"+DIR.length+"|"+(st.mv||0)+"|"+(st.ver||0));METRICS.m_pp_util.cur=+(avgU(a,0,11)*100).toFixed(0);const o=ovStats(names,0,11);METRICS.m_pp_over.cur=+(o.over/Math.max(1,o.pw)*100).toFixed(1);const dec=CAP.reqs.filter(q=>q.decided);METRICS.m_pp_rr.cur=dec.length?Math.round(dec.filter(q=>q.days<=5).length/dec.length*100):METRICS.m_pp_rr.cur}catch(e){}}
