function plate(n){const out=[],r=who(n);if(!r)return out;
 try{if(window.PPMX){PPMX.tasksOf({}).filter(t=>!t.ms&&t.pct<100&&((t.asg||[]).some(a=>a[0]===n)||t.own===n||(t.res||[]).some(x=>x[0]===n))).slice(0,10).forEach(t=>out.push({type:"proj",id:t.id,t:t.n,sub:"Project task · "+t.pct+"% done",go:()=>go("plan",t.p)}))}}catch(e){}
 try{((S.itsm&&S.itsm.inc)||[]).filter(i=>i.own===n&&!/Resolved|Closed/.test(i.st)).slice(0,8).forEach(i=>out.push({type:"inc",id:i.id,t:i.t||i.sh||i.title||i.id,sub:"Incident · "+(i.st||""),go:()=>go("itsm")}))}catch(e){}
 try{((S.itsm&&S.itsm.chg)||[]).filter(c=>c.own===n&&!c.hist&&!/Closed|Cancel/.test(c.st||"")).slice(0,6).forEach(c=>out.push({type:"chg",id:c.id,t:c.t||c.sh||c.title||c.id,sub:"Change · "+(c.st||""),go:()=>go("itsm")}))}catch(e){}
 try{(window.REQREG||[]).filter(q=>!q.done&&q.withN===n).slice(0,6).forEach(q=>out.push({type:"req",id:q.id,t:q.t||q.title||q.id,sub:"Request waiting on "+first(n),go:()=>go("svc")}))}catch(e){}
 try{MEETINGS.filter(m=>(m.att||[]).includes(n)).slice(0,6).forEach(m=>out.push({type:"mtg",id:m.id,t:m.t,sub:"Meeting · "+f1(m.e-m.s)+" h",go:()=>go("cal")}))}catch(e){}
 try{(window.OCX&&OCX.allPto()||[]).filter(p=>p.who===n&&p.st!=="denied").slice(0,4).forEach((p,i)=>out.push({type:"pto",id:"PTO"+i,t:"Time off "+p.from+" to "+p.to,sub:"Leave · "+(p.st||"approved"),go:()=>go("oncall")}))}catch(e){}
 try{(window.OCX&&OCX.shiftsOf(n)||[]).slice(0,3).forEach((s,i)=>out.push({type:"oncall",id:"OC"+i,t:"On-call shift",sub:"Rota",go:()=>go("oncall")}))}catch(e){}
 st.org.wq.filter(i=>i.owner===n).forEach(i=>out.push({type:i.type||"bau",id:i.id,t:i.t,sub:"Assigned work · "+i.h+" h a week",go:()=>{st.tab.ppl_org=5;go("ppl_org")}}));
 return out}
const TYPN=Object.fromEntries(WT.map(x=>[x[0],x[1]]));
function verdict(n){const m=PM(n),r=m.r,tg=tgtOf(r);const u12=avgU({cap:m.cap,tot:m.tot},0,11);let room=1e9;for(let w=0;w<8;w++)if(m.cap[w]>.5)room=Math.min(room,Math.max(0,tg[1]*m.cap[w]-m.tot[w]));if(room===1e9)room=0;
 const idx=r.kind==="human"||r.kind==="contractor"?(perfOf(n)||{}).idx:null;let cls,head,tx;
 if(u12>1.0001){cls="bad";head="No. Over capacity.";tx=`${first(n)} averages ${pc(u12)} over the next 12 weeks. Take work off before adding any.`}
 else if(u12>tg[1]){cls="warn";head="Not without trade-offs.";tx=`${first(n)} is above the ${pc(tg[1])} ceiling for ${E(rfam(r))}. Add work only if something else moves.`}
 else if(room<2){cls="warn";head="Only a little.";tx=`Less than 2 hours a week of room through week 8, at a ceiling of ${pc(tg[1])}.`}
 else{cls="good";head="Yes, about "+Math.floor(room)+" hours a week.";tx=`There is room through week 8 before ${first(n)} reaches the ${pc(tg[1])} ceiling for ${E(rfam(r))}.`}
 let perf="";if(idx!=null&&cls==="good")perf=idx>=60?` The evidence index is ${idx}, above peers, so this is a good person for stretch work.`:idx<40?` The evidence index is ${idx}, below peers. Use the room for coaching and smaller, well-defined work first.`:` The evidence index is ${idx}, in line with peers.`;
 return {cls,head,tx:tx+perf,room,u12,idx}}
function weekStack(m,w0,w1){const mx=Math.max(1,...Array.from(m.cap.slice(w0,w1+1)),...Array.from(m.tot.slice(w0,w1+1)));return `<div class="pp2-ws" role="img" aria-label="Weekly hours by work type">${[...Array(w1-w0+1)].map((_,i)=>{const w=w0+i;return `<button class="pp2-wc" data-pp2-act="cell" data-a="${E(m.r.name)}|${w}" aria-label="Week of ${wkLab(w)}, ${pc(m.cap[w]>.5?m.tot[w]/m.cap[w]:null)}"><span class="pp2-wcs">${WT.map(([k,l,c])=>m.T[k][w]>0?`<i style="height:${m.T[k][w]/mx*100}%;background:var(${c})" title="${l}: ${f1(m.T[k][w])} h"></i>`:"").join("")}${m.pto[w]>0?`<i class="pto" style="height:${m.pto[w]/mx*100}%" title="Time off"></i>`:""}</span><s style="bottom:${m.cap[w]/mx*100}%"></s><small>${i%2===0?WK[w].lab.replace(" ",""):""}</small></button>`}).join("")}</div>`}
function personTab(){const n=CAP.person&&who(CAP.person)?CAP.person:null;
 const pick=`<div class="pp2-bar"><label class="pp2-search"><span class="muted small">Find a person</span><input type="search" data-pp2-pq placeholder="Name, role, team or skill" aria-label="Find a person" autocomplete="off"><div class="pp2-sug" id="pp2PSug" role="listbox"></div></label>${n?"":'<span class="muted small">Or choose one from the lists on the other tabs.</span>'}</div>`;
 if(!n){const top=DIR.filter(d=>d.kind==="human").map(d=>({d,u:avgU(PM(d.name),0,11)})).sort((a,b)=>b.u-a.u).slice(0,6);return pick+`<p class="story" data-role="story">Pull one person and see everything on their plate: projects, incidents, requests, changes, on-call, meetings, leave and training, week by week, with a plain answer to "can they take more?". Start with the busiest people.</p>${lrHTML({id:"pp2pk",groups:[{key:"a",label:"Busiest over the next 12 weeks",rows:top.map(x=>({id:x.d.name,t:x.d.name,sub:x.d.role+" · "+x.d.team,tag:pc(x.u),st:uCls(x.u),go:()=>{CAP.person=x.d.name;render()}}))}],limit:6})}`}
 const r=who(n),m=PM(n),v=verdict(n),tg=tgtOf(r),items=plate(n),byT={};items.forEach(i=>(byT[i.type]=byT[i.type]||[]).push(i));const lv=levelOpts(n);
 return pick+`<div class="pp2-pcard"><div class="row" style="gap:14px">${avatar(r,{size:64})}<div><h2 style="font-size:30px;margin:0">${E(n)}</h2><div class="row" style="gap:8px">${kindPill(r.kind)}<span class="pill mute">${E(roleOf(r))} · ${E(r.team||"")}</span><span class="pill mute">${E(rfam(r))}</span></div></div></div>
  <div class="pp2-verdict ${v.cls}"><div class="eyebrow">Can ${E(first(n))} handle more?</div><div class="pp2-vh">${v.head}</div><p>${v.tx}</p></div></div>
 <div class="statrow">${stat("Load, next 12 weeks",pc(v.u12),"band for "+E(rfam(r))+": "+pc(tg[0])+" to "+pc(tg[1]),uCls(v.u12)==="bad"?"crit":"")}${stat("Contracted hours",f1(m.base)+" h","a week"+(r.kind==="contractor"&&r.end?" until "+E(r.end):""))}${stat("Time off in 12 weeks",f1(mean(Array.from(m.pto.slice(0,12)))*12)+" h","leave and holidays")}${stat("Weeks over 100%",String(Array.from(m.util.slice(0,26)).filter((u,w)=>u>1.0001&&m.cap[w]>.5).length),"in the next 26")}</div>
 ${card("Week by week, next 12 weeks","Each column is a week. The line is available hours. Select a week for the breakdown.",weekStack(m,0,11)+typeLeg())}
 ${card("Everything on the plate","Pulled live from the project plan, incident, request and change queues, the calendar and the on-call rota.",WT.filter(x=>byT[x[0]]).length?WT.filter(x=>byT[x[0]]).map(([k,l,c])=>`<div class="pp2-pl"><h4><i class="pp2-sw" style="background:var(${c})"></i>${l} <span class="muted">${byT[k].length}</span> <span class="muted small">${f1(m.T[k][0])} h this week</span></h4>${byT[k].slice(0,6).map(i=>`<button class="pp2-it" data-pp2-act="plate" data-a="${E(n)}|${E(i.id)}"><b>${E(i.t)}</b><small>${E(i.sub)}</small></button>`).join("")}</div>`).join("")+`<p class="muted small">Operational work, training and part of the meeting time are modeled from the role family. ${f1(m.T.bau[0]+m.T.train[0])} h this week.</p>`:'<p class="muted">Nothing is assigned beyond modeled operational work.</p>')}
 ${r.kind==="human"||r.kind==="contractor"?card("How they are doing against their peers","Evidence only. The same data the performance cycle uses, shown beside the load.",`<p class="small">${v.idx!=null?`Evidence index <b>${v.idx}</b> against peers in ${E(r.team||"the organization")}.`:"Not enough evidence yet."} High load changes how the evidence reads, so the fairness check on the performance screen adjusts for it.</p><button class="btn" data-pp2-act="perfopen" data-a="${E(n)}">Open the evidence</button>`):""}
 ${lv?card("Over capacity: ways to fix it","Four ways to bring the weeks under 100%. Nothing changes until you apply one.",`<button class="btn primary" data-pp2-act="level" data-a="${E(n)}">Show fixes</button>`):""}
 <div class="row" style="margin-top:12px"><button class="btn" data-person="${E(n)}">Open Person 360</button><button class="btn" data-pp2-act="assign" data-a="">Assign work</button><button class="btn quiet" data-pp2-act="gocap" data-a="">Choose someone else</button></div>`}
/* ---- group helpers ---- */
function groupNames(dim,label){const kd=selSet("pp2ck",KINDSET),tm=selSet("pp2ct",teamList());return DIR.filter(d=>kd.includes(d.kind)&&(!d.team||tm.includes(d.team))&&(dim==="team"?d.team===label:dim==="fam"?rfam(d)===label:dim==="kind"?d.kind===label:dim==="skill"?(d.skills||[]).includes(label):true)).map(d=>d.name)}
const gagg=(dim,label)=>agg(groupNames(dim,label),"g:"+dim+":"+label+"|"+selSet("pp2ck",KINDSET).join(",")+"|"+selSet("pp2ct",teamList()).join(",")+"|"+DIR.length+"|"+(st.mv||0)+"|"+(st.ver||0));
function groupRows(dim){const kd=selSet("pp2ck",KINDSET),tm=selSet("pp2ct",teamList());const base=DIR.filter(d=>kd.includes(d.kind)&&(!d.team||tm.includes(d.team)));
 if(dim==="team")return teamList().filter(t=>tm.includes(t)).map(t=>[t,t]);if(dim==="fam")return ROLEFAMS.filter(f=>base.some(d=>rfam(d)===f)).map(f=>[f,f]);if(dim==="kind")return kd.map(k=>[k,KINDS[k]]);
 if(dim==="skill"){const c={};base.forEach(d=>(d.skills||[]).forEach(s=>c[s]=(c[s]||0)+1));return Object.entries(c).filter(x=>x[1]>=2).sort((a,b)=>b[1]-a[1]).slice(0,24).map(x=>[x[0],x[0]+" ("+x[1]+")"])}
 return []}
const cellVal=(A,w,wt)=>{const d=wt==="all"?A.tot[w]:A.T[wt][w];return A.cap[w]>.5?d/A.cap[w]:null};
const heatCell=(u,attrs,ov)=>`<button class="pp2-hc2${ov?" hid":""}" style="--cc:var(${uCol(u)});--a:${u==null?24:u>1?Math.min(88,60+(u-1)*120):u>.85?58:u>=.5?36+(u-.5)*40:24}" ${attrs}></button>`;
function ovWeeks(names){const o=new Float32Array(NWK);names.forEach(n=>{const m=PM(n);for(let w=0;w<NWK;w++)if(m.cap[w]>.5&&m.util[w]>1.0001)o[w]++});return o}
function heatTab(){const dim=CAP.heat,wt=CAP.wt;const dims=[["team","Team"],["fam","Role family"],["kind","Kind of worker"],["skill","Skill"],["person","Person"]];
 const sw=`<div class="pp2-bar"><div class="vsw glass" role="group" aria-label="Group rows by">${dims.map(d=>`<button class="${d[0]===dim?"on":""}" data-pp2-act="heatdim" data-a="${d[0]}" aria-pressed="${d[0]===dim}">${d[1]}</button>`).join("")}</div><label class="small">Show <select data-pp2-wt aria-label="Work type">${[["all","All work types"]].concat(WT.map(x=>[x[0],x[1]])).map(o=>`<option value="${o[0]}"${o[0]===wt?" selected":""}>${o[1]}</option>`).join("")}</select></label><button class="btn" data-pp2-act="capcsv">Export CSV</button></div>`;
 let rows;const lim=25+(CAP.pg.heat||0);
 if(dim==="person"){const nm=scopeNames().filter(n=>who(n)&&who(n).kind!=="msp").map(n=>({n,u:avgU(PM(n),0,11)})).sort((a,b)=>b.u-a.u);rows=nm.slice(0,lim).map(x=>{const m=PM(x.n);return {lab:x.n,sub:pc(x.u),node:`<span class="pp2-hl">${pchip(x.n)}</span>`,cells:[...Array(NWK)].map((_,w)=>heatCell(cellVal({cap:m.cap,tot:m.tot,T:m.T},w,wt),`data-pp2-act="cell" data-a="${E(x.n)}|${w}" title="${E(x.n)}, week of ${WK[w].lab}: ${pc(cellVal({cap:m.cap,tot:m.tot,T:m.T},w,wt))}" aria-label="${E(x.n)} week of ${WK[w].lab}"`,false)).join("")}});rows.more=nm.length>lim?nm.length-lim:0}
 else{rows=groupRows(dim).map(([k,l])=>{const A=gagg(dim,k);const gn=groupNames(dim,k).length;const o=dim==="skill"||dim==="kind"||dim==="fam"||dim==="team"?ovWeeks(groupNames(dim,k)):new Float32Array(NWK);return {lab:l,sub:pc(avgU(A,0,11)),node:`<button class="pp2-hl pp2-lnk" data-pp2-act="rgrp" data-a="${dim}|${E(k)}">${E(l)}</button>`,cells:[...Array(NWK)].map((_,w)=>{const u=cellVal(A,w,wt);return heatCell(u,`data-pp2-act="rcell" data-a="${dim}|${E(k)}|${w}" title="${E(l)}, week of ${WK[w].lab}: ${pc(u)}${o[w]?", "+o[w]+" "+(o[w]===1?"person":"people")+" over 100%":""}" aria-label="${E(l)} week of ${WK[w].lab}"`,(o[w]>=2||o[w]>=.12*gn)&&(u==null||u<=1.0001))}).join("")}})}
 const mons=`<div class="pp2-hmon">${MONTHS.map(m=>`<span style="grid-column:${m.w0+2}/span ${m.w1-m.w0+1}">${m.lab}</span>`).join("")}</div>`;
 return scopeBar()+sw+`<p class="story" data-role="story">${dim==="person"?"One row per person, busiest first. ":""}Each cell is one week, from the week of ${WK[0].lab} through ${WK[NWK-1].lab}. Red cells have more work than available hours. A <b>ringed</b> cell is a group that looks fine on average while at least one person in it is over 100%. Select a row name to see the people, a cell to see the week.</p>
 <div class="tscroll"><div class="pp2-heat2" style="--cols:${NWK}">${mons}${rows.map(r=>`<div class="pp2-hr2"><span class="pp2-hn2">${r.node}<small>${r.sub}</small></span>${r.cells}</div>`).join("")}</div></div>
 ${rows.more?`<button class="btn" data-pp2-act="heatmore">Show 25 more of ${rows.more}</button>`:""}${legend([["Under 50%","--p6"],["50% to 85%","--good-f"],["85% to 100%","--warn-f"],["Over 100%","--bad-f"],["No capacity","--faint"]])}<p class="muted small">Ringed cell means a group below 100% in total with someone over it. Percent is work hours divided by available hours after leave and holidays.</p>`}
/* ---- group and cell drawers ---- */
function groupDrawer(dim,k,w){const names=groupNames(dim,k),A=gagg(dim,k);const ppl=names.filter(n=>who(n).kind!=="msp").map(n=>({n,u:w==null?avgU(PM(n),0,11):(PM(n).cap[w]>.5?PM(n).tot[w]/PM(n).cap[w]:null)})).sort((a,b)=>(b.u||0)-(a.u||0));
 const over=ppl.filter(x=>x.u>1.0001).length;const lab=dim==="kind"?KINDS[k]:k;
 openDrawer(`<div class="eyebrow">${w==null?"Next 12 weeks":"Week of "+WK[w].lab}</div><h2 style="font-size:28px;margin:4px 0 8px">${E(lab)}</h2><p class="story" data-role="story">${names.length} workers. ${w==null?"Average load "+pc(avgU(A,0,11)):"Load "+pc(cellVal(A,w,"all"))}, ${over} ${over===1?"person":"people"} over 100%. Demand is ${f1(w==null?mean(Array.from(A.tot.slice(0,12))):A.tot[w])} hours a week against ${f1(w==null?mean(Array.from(A.cap.slice(0,12))):A.cap[w])} available.</p>
 ${w!=null?`<div class="pp2-stackbar" role="img" aria-label="Hours by work type">${WT.map(([kk,l,c])=>A.T[kk][w]>0?`<i style="width:${A.T[kk][w]/Math.max(A.cap[w],A.tot[w],1)*100}%;background:var(${c})" title="${l}: ${f1(A.T[kk][w])} h"></i>`:"").join("")}</div>${typeLeg()}`:""}
 ${lrHTML({id:"pp2gd"+dim+k,groups:[{key:"a",label:"People, busiest first",rows:ppl.map(x=>({id:x.n,t:x.n,sub:roleOf(who(x.n))+" · "+KINDS[who(x.n).kind],tag:pc(x.u),st:uCls(x.u),go:()=>{closeDrawer();CAP.person=x.n;st.tab.ppl_cap=3;go("ppl_cap")}}))}],limit:10})}
 <div class="row" style="margin-top:12px">${dim==="team"?`<button class="btn" data-pp2-act="team" data-a="${E(k)}">Open the team</button>`:""}<button class="btn" data-pp2-act="newreq" data-a="${dim==="team"?E(k):""}">Request resources</button></div>`)}
/* ---- leveling ---- */
function overWeeks(n,w0,w1){const m=PM(n),out=[];for(let w=w0;w<=w1;w++)if(m.cap[w]>.5&&m.util[w]>1.0001)out.push([w,m.tot[w]-m.cap[w]]);return out}
let FXN=1;
function levelOpts(n){const m=PM(n),r=m.r,ow=overWeeks(n,0,25);if(!ow.length)return null;const tot=ow.reduce((a,x)=>a+x[1],0),wA=ow[0][0],wB=ow[ow.length-1][0];
 const peers=DIR.filter(d=>(d.kind==="human"||d.kind==="contractor")&&d.team===r.team&&d.name!==n).map(d=>d.name);let best=null;
 peers.forEach(p=>{const pm=PM(p);let room=0;ow.forEach(([w,h])=>{room+=Math.min(h,m.T.proj[w],Math.max(0,pm.cap[w]*.88-pm.tot[w]))});if(!best||room>best.room)best={p,room}});
 const moved=best?best.room:0;const ag=DIR.filter(d=>d.kind==="ai").map(d=>({d,u:avgU(PM(d.name),0,25)})).sort((a,b)=>a.u-b.u)[0];
 const offH=ow.reduce((a,[w,h])=>a+Math.min(h,(m.T.req[w]+m.T.bau[w])*.35),0);const dh=ow.reduce((a,[w,h])=>a+Math.min(h,m.T.proj[w]),0);const rate=rateAvg();const fte=Math.max(.25,Math.ceil(Math.max(...ow.map(x=>x[1]))/40*4)/4);
 const dateOf=w=>isoOfWk(clamp(w,0,NWK-1));
 const opts=[
  {id:"move",t:best&&moved>0?"Move "+f1(moved)+" hours to "+best.p:"Move project work to a teammate",h:moved,cost:0,ok:moved>0,risk:best?"Needs "+best.p+" to agree. Skills match is checked against the team, not the task.":"No one in the team has room.",apply:()=>{const id="FX"+FXN++;ow.forEach(([w,h])=>{const pm=PM(best.p);const x=Math.min(h,m.T.proj[w],Math.max(0,pm.cap[w]*.88-pm.tot[w]));if(x>0.01){CAP.ov.push({fx:id,owner:n,type:"proj",w,h:-x});CAP.ov.push({fx:id,owner:best.p,type:"proj",w,h:x})}});return {id,t:"Moved project work from "+n+" to "+best.p}}},
  {id:"ctr",t:"Add a contractor for "+f1(fte)+" FTE",h:tot,cost:Math.round(tot*rate),ok:true,risk:"Takes about 2 weeks to onboard. About $"+fmt(tot*rate)+" at $"+rate+" an hour. Creates a resource request for approval.",apply:()=>{const id="FX"+FXN++;const q={id:"RQ"+(CAP.reqs.length+1),title:"Contractor to relieve "+n,team:r.team,role:rfam(r),kind:"contractor",skills:(r.skills||[]).slice(0,2),fte,from:dateOf(wA),to:dateOf(wB+1),status:"Resource manager",by:"Resource Agent",why:"Leveling "+n+": "+f1(tot)+" hours over capacity.",at:"2026-10-07",fx:id};CAP.reqs.unshift(q);ow.forEach(([w,h])=>{const x=Math.min(h,m.T.proj[w]);if(x>0)CAP.ov.push({fx:id,owner:n,type:"proj",w,h:-x})});return {id,t:"Requested a contractor for "+n+"'s overload",req:q.id}}},
  {id:"agent",t:ag?"Offload "+f1(offH)+" hours of requests and routine work to "+ag.d.name:"Offload routine work to an AI agent",h:offH,cost:Math.round(offH*.5*8),ok:!!ag&&offH>.5,risk:"The agent works inside its autonomy tier and "+(ag?E(acctOf(ag.d.name)||"its owner"):"its owner")+" stays accountable. Covers requests and routine work only.",apply:()=>{const id="FX"+FXN++;ow.forEach(([w,h])=>{const rq=m.T.req[w],bu=m.T.bau[w],x=Math.min(h,(rq+bu)*.35);if(x>0.01){const a=Math.min(x,rq*.35),b=x-a;if(a>0)CAP.ov.push({fx:id,owner:n,type:"req",w,h:-a});if(b>0)CAP.ov.push({fx:id,owner:n,type:"bau",w,h:-b});CAP.ov.push({fx:id,owner:ag.d.name,type:"req",w,h:x*.5})}});return {id,t:"Offloaded routine work from "+n+" to "+ag.d.name}}},
  {id:"defer",t:"Defer "+f1(dh)+" hours of project work by "+Math.max(2,Math.ceil(ow.length/2))+" weeks",h:dh,cost:0,ok:dh>0,risk:"Project dates move. Check the critical path before agreeing.",apply:()=>{const id="FX"+FXN++;const sh=Math.max(2,Math.ceil(ow.length/2));ow.forEach(([w,h])=>{const x=Math.min(h,m.T.proj[w]);if(x>0){CAP.ov.push({fx:id,owner:n,type:"proj",w,h:-x});const t=Math.min(NWK-1,wB+1+(w%sh));CAP.ov.push({fx:id,owner:n,type:"proj",w:t,h:x})}});return {id,t:"Deferred project work for "+n}}}];
 return {n,ow,tot,opts,peak:Math.max(...ow.map(x=>x[1]))}}
function levelDrawer(n){const L=levelOpts(n);if(!L){toast(n+" is not over capacity in the next 26 weeks.","info");return}const r=who(n);
 openDrawer(`<div class="eyebrow">Leveling</div><div class="row">${avatar(r,{size:52})}<div><h2 style="font-size:28px;margin:0">${E(n)}</h2>${kindPill(r.kind)}</div></div><p class="story" data-role="story">${L.ow.length} weeks over 100% in the next 26, ${f1(L.tot)} hours above capacity in total, worst week ${f1(L.peak)} hours over. The Resource Agent ranked four fixes. You decide; each one can be undone.</p>
 ${L.opts.map((o,i)=>`<div class="pp2-fix${o.ok?"":" off"}"><div class="row sp"><b>${i+1}. ${E(o.t)}</b><span class="pill ${o.ok?"info":"mute"}">${o.ok?f1(Math.min(o.h,L.tot))+" h":"Not available"}</span></div><p class="small muted">${o.risk}</p>${o.cost?`<p class="small">Estimated cost $${fmt(o.cost)}</p>`:""}<button class="btn ${i===0&&o.ok?"primary":""}" data-pp2-act="fix" data-a="${E(n)}|${o.id}"${o.ok?"":" disabled"}>Apply this</button></div>`).join("")}
 ${aiChip({model:"Resource Agent",conf:.82,title:"How the fixes were found",src:["Team members' available hours for the same weeks","Agent load and autonomy tiers","Contractor rate card","Project task hours"],guards:["Proposes only. You decide.","Nothing moves without your Apply"]})}`)}
function applyFix(n,id){const L=levelOpts(n);if(!L)return;const o=L.opts.find(x=>x.id===id);if(!o||!o.ok)return;const before=Math.max(...PM(n).util.slice(0,26));const res=o.apply();bumpMv();const after=Math.max(...PM(n).util.slice(0,26));CAP.applied.unshift({id:res.id,n,t:res.t,at:"Oct 7",before,after,req:res.req});audit("leveling applied",res.t);toast(res.t+". Peak load "+pc(before)+" to "+pc(after)+".","good");closeDrawer();render()}
function undoFix(id){CAP.ov=CAP.ov.filter(o=>o.fx!==id);CAP.reqs=CAP.reqs.filter(q=>q.fx!==id);CAP.applied=CAP.applied.filter(a=>a.id!==id);bumpMv();audit("leveling undone",id);toast("Undone","good");render()}
function overTab(){const names=scopeNames().filter(n=>who(n).kind!=="msp");const rows=[];names.forEach(n=>{const ow=overWeeks(n,0,25);if(ow.length)rows.push({id:n,name:n,team:who(n).team||"",kind:KINDS[who(n).kind],weeks:ow.length,peak:Math.round(Math.max(...ow.map(x=>x[1]))),hrs:Math.round(ow.reduce((a,x)=>a+x[1],0)),first:wkLab(ow[0][0])})});rows.sort((a,b)=>b.hrs-a.hrs);
 const tmo={};rows.forEach(r=>tmo[r.team]=(tmo[r.team]||0)+1);const topT=Object.entries(tmo).sort((a,b)=>b[1]-a[1])[0];
 return scopeBar()+`<p class="story" data-role="story"><b>${rows.length}</b> ${rows.length===1?"person is":"people are"} over capacity in the next 26 weeks${topT?`, most of them in <b>${E(topT[0])}</b> (${topT[1]})`:""}. For each person the Resource Agent offers four fixes: move work to a teammate, add a contractor, offload routine work to an AI agent, or defer project work. Nothing changes until you apply one.</p>
 ${CAP.applied.length?card("Applied fixes","Each fix can be undone.",`<ul class="pp2-fixes">${CAP.applied.map(a=>`<li><span><b>${E(a.t)}</b> <span class="muted small">peak ${pc(a.before)} to ${pc(a.after)} · ${a.at}</span></span><button class="btn quiet" data-pp2-act="unfix" data-a="${a.id}">Undo</button></li>`).join("")}</ul>`):""}
 ${card("People over capacity","Sorted by hours above capacity. Select a person to see the fixes.",btHTML({id:"pp2_ovl",cols:[{k:"name",label:"Person",fmt:r=>pchip(r.name)},{k:"team",label:"Team"},{k:"kind",label:"Kind"},{k:"weeks",label:"Weeks over"},{k:"peak",label:"Worst week (h over)"},{k:"hrs",label:"Total hours over"},{k:"first",label:"First week"},{k:"fix",label:"",fmt:r=>`<button class="btn quiet" data-pp2-act="level" data-a="${E(r.name)}">Fixes</button>`}],rows:()=>rows,key:"id",h:440,rowH:44,facets:["team","kind"],groupBy:["team"],exportName:"over-capacity",open:id=>levelDrawer(id)}))}`}
/* ---- dashboard ---- */
function capDash(){const t0=performance.now();syncCap();const names=scopeNames();const A=scopeAgg(),ms=performance.now()-t0;const o=ovStats(names,0,11);const gap=gapFTE(0,11);const pend=CAP.reqs.filter(q=>q.status==="Submitted"||q.status==="Resource manager");
 const teams=teamList().map(t=>{const a=gagg("team",t);const L=groupNames("team",t);const ov=ovStats(L,0,11);return {id:t,team:t,n:L.length,u:Math.round(avgU(a,0,11)*100),peak:Math.round(Math.max(...Array.from(a.util.slice(0,12)).map(x=>Math.min(x,3)))*100),over:ov.people,gap:+(Math.max(0,mean(Array.from(a.tot.slice(0,12)))-mean(Array.from(a.cap.slice(0,12))))/40).toFixed(1),fut:Math.round(avgU(a,12,25)*100)}}).filter(r=>r.n);
 const pk=(()=>{let b=0;for(let w=0;w<26;w++)if(A.util[w]>A.util[b])b=w;return b})();
 const story=`Every kind of work is turned into hours per person per week: projects, incidents, requests, changes, on-call, operational work, meetings, training and leave. For <b>${fmt(names.length)} workers</b> over ${NWK} weeks, load over the next 12 weeks is <b>${pc(avgU(A,0,11))}</b>. <b>${o.people}</b> ${o.people===1?"person is":"people are"} over 100% in at least one week (${o.over} weeks in total across them). Demand with no named person is <b>${f1(gap)} FTE</b>. The tightest week is ${wkLab(pk)} at ${pc(A.util[pk])}. ${pend.length} resource ${pend.length===1?"request is":"requests are"} waiting.`;
 const lab=WK.map(w=>w.lab);const mx=Math.max(1,...Array.from(A.tot),...Array.from(A.cap))*1.08;
 return scopeBar()+`<p class="story" data-role="story">${story}</p>
 <div class="statrow">${stat("Load, next 12 weeks",pc(avgU(A,0,11)),"target band 70% to 88%",avgU(A,0,11)>1?"crit":"")}${stat("People over capacity",String(o.people),fmt(o.over)+" person-weeks",o.people?"warn":"")}${stat("Unstaffed demand",f1(gap)+" FTE","no named person")}${stat("Resource requests waiting",String(pend.length),"answered in 5 days")}</div>
 ${card("Capacity against demand, all 52 weeks","Demand is every work type added together. The dashed line is available hours after leave and holidays.",lineChart(lab,[{vals:Array.from(A.tot),color:"var(--p4)",area:true},{vals:Array.from(A.cap),color:"var(--good-f)",dash:true}],{max:mx,every:4,fmt:v=>fmt(v/1000*10)/10+"k",w:900,h:280})+legend([["Demand (all work types)","--p4"],["Available hours","--good-f"]]))}
 ${card("Teams","Average load over the next 12 weeks and the 13 weeks after. Select a team to see its people.",btHTML({id:"pp2_cteams",cols:[{k:"team",label:"Team",fmt:r=>`<button class="pp2-lnk" data-pp2-act="rgrp" data-a="team|${E(r.team)}">${E(r.team)}</button>`},{k:"n",label:"Workers"},{k:"u",label:"Load, next 12 weeks",fmt:r=>`<span class="pill ${uCls(r.u/100)}">${r.u}%</span>`},{k:"fut",label:"Weeks 13 to 26",fmt:r=>r.fut+"%"},{k:"peak",label:"Peak week",fmt:r=>r.peak+"%"},{k:"over",label:"People over 100%"},{k:"gap",label:"Shortfall (FTE)"}],rows:()=>teams,key:"id",h:300,rowH:44,exportName:"team-capacity"}))}
 ${card("Everyone","Each person's load against the target band for their role family. Select a row for everything on their plate.",btHTML({id:"pp2_cppl",cols:[{k:"name",label:"Person",fmt:r=>pchip(r.name)},{k:"kind",label:"Kind"},{k:"team",label:"Team"},{k:"fam",label:"Role family"},{k:"u",label:"Load, next 12 weeks",fmt:r=>`<span class="pill ${uCls(r.u/100)}">${r.u}%</span>`},{k:"band",label:"Target band"},{k:"over",label:"Weeks over 100%"},{k:"room",label:"Room (h a week)"}],rows:()=>names.filter(n=>who(n).kind!=="msp").map(n=>{const m=PM(n),r=m.r,tg=tgtOf(r),u=avgU({cap:m.cap,tot:m.tot},0,11);let room=1e9;for(let w=0;w<8;w++)if(m.cap[w]>.5)room=Math.min(room,Math.max(0,tg[1]*m.cap[w]-m.tot[w]));return {id:n,name:n,kind:KINDS[r.kind],team:r.team||"",fam:rfam(r),u:Math.round(u*100),band:Math.round(tg[0]*100)+"% to "+Math.round(tg[1]*100)+"%",over:Array.from(m.util.slice(0,26)).filter((x,w)=>x>1.0001&&m.cap[w]>.5).length,room:room===1e9?0:Math.round(room)}}),key:"id",h:460,rowH:44,facets:["team","kind","fam"],groupBy:["team","fam","kind"],exportName:"people-capacity",open:id=>{CAP.person=id;st.tab.ppl_cap=3;go("ppl_cap")}}))}
 ${card("Scale test","The model is rebuilt from the sources on demand, so it holds for hundreds or thousands of people.",`<p class="small">${fmt(DIR.length)} workers × ${NWK} weeks × ${WT.length} work types = <b>${fmt(DIR.length*NWK*WT.length)}</b> cells. ${CAP.scaleMs!=null?`Last full rebuild took <b>${Math.round(CAP.scaleMs)} ms</b>.`:"Run the test to time a full rebuild."} Switch on Enterprise mode (about 400 people) in the settings menu to try it.</p><button class="btn" data-pp2-act="scaletest">Rebuild all and time it</button>`)}`}
function workTab(){const A=scopeAgg();const mons=MONTHS.map(m=>{const n=m.w1-m.w0+1;const o={lab:m.lab,cap:0};WTK.forEach(k=>{let s=0;for(let w=m.w0;w<=m.w1;w++)s+=A.T[k][w];o[k]=s/n});for(let w=m.w0;w<=m.w1;w++)o.cap+=A.cap[w];o.cap/=n;return o});const mx=Math.max(1,...mons.map(o=>Math.max(o.cap,WTK.reduce((a,k)=>a+o[k],0))))*1.05;
 const tot=WTK.reduce((a,k)=>a+mean(Array.from(A.T[k].slice(0,12))),0)||1;
 const srcN={proj:()=>{try{return PPMX.tasksOf({}).filter(t=>!t.ms&&t.pct<100).length}catch(e){return TASKS.length}},inc:()=>{try{return S.itsm.inc.filter(i=>!/Resolved|Closed/.test(i.st)).length}catch(e){return 0}},req:()=>(window.REQREG||[]).filter(r=>!r.done).length,chg:()=>{try{return S.itsm.chg.filter(c=>!c.hist).length+(window.RELX?RELX.releases.length:0)}catch(e){return 0}},oncall:()=>{try{return OCX.allPto().length}catch(e){return 0}},bau:()=>DIR.length,mtg:()=>MEETINGS.length,train:()=>DIR.length};
 const from={proj:"Schedule engine (project plans)",inc:"Incident and problem queues",req:"Service catalog requests",chg:"Change calendar and release trains",oncall:"On-call rota",bau:"Role-family operating model",mtg:"Calendar",train:"Learning plans"};
 return scopeBar()+`<p class="story" data-role="story">This is how the model scales across every kind of work: each work type is an adapter that turns its records into hours per person per week, and everything downstream (heatmaps, leveling, scenarios, forecasts) reads the same hours. A new work type is one adapter. Today there are ${WT.length}, plus leave and holidays, which reduce capacity instead of adding demand.</p>
 ${card("Demand by work type, by month","Average weekly hours across the selected workers. The line is available hours.",`<div class="pp2-mobars" role="img" aria-label="Monthly demand by work type">${mons.map(o=>`<div class="pp2-mb"><span class="pp2-mobs">${WT.map(([k,l,c])=>o[k]>0?`<i style="height:${o[k]/mx*100}%;background:var(${c})" title="${l}: ${fmt(o[k])} h"></i>`:"").join("")}</span><s style="bottom:${o.cap/mx*100}%"></s><small>${o.lab}</small></div>`).join("")}</div>${typeLeg()}`)}
 ${card("Where each work type comes from","Adapters, their sources and how many records feed the model right now.",`<div class="tscroll"><table><thead><tr><th>Work type</th><th>Source</th><th>Records</th><th>Hours a week, next 12 weeks</th><th>Share</th><th>Fills the gap with</th></tr></thead><tbody>${WT.map(([k,l,c])=>{const h=mean(Array.from(A.T[k].slice(0,12)));return `<tr><td><i class="pp2-sw" style="background:var(${c})"></i>${l}</td><td>${from[k]}</td><td class="num">${fmt(srcN[k]())}</td><td class="num">${fmt(h)}</td><td class="num">${Math.round(h/tot*100)}%</td><td class="small">${{proj:"Contractor or defer",inc:"Agent triage and on-call swaps",req:"AI agent fulfillment",chg:"Release train scheduling",oncall:"Rota swaps",bau:"Automation and agents",mtg:"Fewer, shorter meetings",train:"Defer outside peaks"}[k]}</td></tr>`}).join("")}</tbody></table></div><p class="muted small">Leave and holidays come from approved time off and the company calendar. Contractors drop to zero after their end date. Providers count contracted hours, not people.</p>`)}`}
/* ---- scenarios ---- */
function scenCalc(sc,A){const tms=selSet("pp2ct",teamList());const add=new Float32Array(NWK),capAdd=new Float32Array(NWK),cut=new Float32Array(NWK);
 for(let w=0;w<NWK;w++){if(w>=sc.from&&w<sc.from+sc.weeks)capAdd[w]=sc.ctr*sc.ctrH;cut[w]=A.T.bau[w]*sc.bau/100+A.T.req[w]*sc.agent/100*.5}
 let cost=sc.ctr*sc.ctrH*Math.min(sc.weeks,NWK-sc.from)*rateAvg();const picked=[];(sc.proj||[]).forEach(id=>{const d=DEMAND.find(x=>x.id===id);if(!d)return;picked.push(d);cost+=d.cost*1000;const w0=Math.round(d.m0*4.35),w1=Math.min(NWK-1,Math.round((d.m0+d.mo)*4.35));(d.res||[]).forEach(([t,f])=>{if(tms.includes(t))for(let w=w0;w<=w1;w++)add[w]+=f*40})});
 const u0=[],u1=[];let o0=0,o1=0;for(let w=0;w<NWK;w++){u0.push(A.cap[w]>.5?A.tot[w]/A.cap[w]:0);const c=A.cap[w]+capAdd[w],d=A.tot[w]+add[w]-cut[w];u1.push(c>.5?d/c:0);if(u0[w]>1.0001)o0++;if(u1[w]>1.0001)o1++}
 return {u0,u1,o0,o1,cost,picked,peak0:Math.max(...u0),peak1:Math.max(...u1),avg0:mean(u0.slice(0,26)),avg1:mean(u1.slice(0,26)),hoursCut:cut.reduce((a,b)=>a+b,0)}}
function scenTab(){const A=scopeAgg(),sc=CAP.scen,R=scenCalc(sc,A);const lab=WK.map(w=>w.lab);
 return scopeBar()+`<p class="story" data-role="story">Try a change on paper before committing to it. Your current assumptions: <b>${sc.ctr} contractors</b> at ${sc.ctrH} hours a week for ${sc.weeks} weeks from ${wkLab(sc.from)}${sc.proj.length?`, approve <b>${sc.proj.map(id=>E((DEMAND.find(d=>d.id===id)||{}).n||id)).join(" and ")}</b>`:""}${sc.bau?`, cut operational work by <b>${sc.bau}%</b>`:""}${sc.agent?`, move <b>${sc.agent}%</b> of requests to agents`:""}. Over the next 26 weeks that moves average load from <b>${pc(R.avg0)}</b> to <b>${pc(R.avg1)}</b> and weeks above 100% from ${R.o0} to ${R.o1} of ${NWK}.</p>
 <div class="row" style="margin-bottom:12px"><button class="btn primary" data-pp2-act="scenedit">Change assumptions</button><button class="btn" data-pp2-act="scensave">Save scenario</button><button class="btn" data-pp2-act="scencommit"${sc.ctr||sc.proj.length?"":" disabled"}>Turn into resource requests</button></div>
 <div class="statrow">${stat("Peak load",pc(R.peak0)+" to "+pc(R.peak1),"all 52 weeks",R.peak1>1?"crit":"")}${stat("Weeks above 100%",R.o0+" to "+R.o1,"of "+NWK)}${stat("Added cost","$"+fmt(R.cost/1000)+"k","contractors and approved projects")}${stat("Hours freed a week",fmt(R.hoursCut/NWK),"operational cut and agent offload")}</div>
 ${card("Load before and after","Solid is today. Dashed is with your assumptions.",lineChart(lab,[{vals:R.u0.map(v=>Math.min(v*100,160)),color:"var(--p4)"},{vals:R.u1.map(v=>Math.min(v*100,160)),color:"var(--good-f)",dash:true},{vals:lab.map(()=>100),color:"var(--bad-f)",dash:true,w:1.5}],{max:160,every:4,fmt:v=>Math.round(v)+"%",w:900,h:260})+legend([["Today","--p4"],["With assumptions","--good-f"],["100% line","--bad-f"]]))}
 ${R.picked.length?card("Projects in this scenario","Each project adds its resource ask to the teams in scope.",`<div class="tscroll"><table><thead><tr><th>Project</th><th>Cost</th><th>Needs</th><th>Starts</th></tr></thead><tbody>${R.picked.map(d=>`<tr><td>${E(d.n)}</td><td class="num">$${fmt(d.cost)}k</td><td>${d.res.map(x=>E(x[0])+" "+x[1]+" FTE").join(", ")}</td><td>${wkLab(Math.round(d.m0*4.35))}</td></tr>`).join("")}</tbody></table></div>`):""}
 ${CAP.saved.length?card("Saved scenarios","Compare what you tried.",`<div class="tscroll"><table><thead><tr><th>Name</th><th>Peak</th><th>Weeks above 100%</th><th>Cost</th><th></th></tr></thead><tbody>${CAP.saved.map((s,i)=>`<tr><td>${E(s.n)}</td><td class="num">${pc(s.peak)}</td><td class="num">${s.over}</td><td class="num">$${fmt(s.cost/1000)}k</td><td><button class="btn quiet" data-pp2-act="scenload" data-a="${i}">Load</button></td></tr>`).join("")}</tbody></table></div>`):""}`}
function scenForm(){const sc=CAP.scen;openForm({id:"pp2_scen",title:"Scenario assumptions",story:"Change anything and the result updates below. Nothing is committed until you turn the scenario into requests.",submit:"Use these assumptions",fields:[{k:"ctr",label:"Contractors to add",type:"number",min:0,max:40},{k:"ctrH",label:"Hours a week each",type:"number",min:8,max:40},{k:"from",label:"Starting week",type:"select",opts:WK.slice(0,40).map(w=>[String(w.i),"Week of "+w.lab])},{k:"weeks",label:"For how many weeks",type:"number",min:2,max:52},{k:"proj",label:"Approve these projects",type:"multi",opts:DEMAND.filter(d=>d.st<=3).map(d=>[d.id,d.n+" ($"+d.cost+"k)"])},{k:"bau",label:"Cut operational work by",type:"range",min:0,max:30,unit:"%"},{k:"agent",label:"Move this share of requests to agents",type:"range",min:0,max:60,unit:"%"}],defaults:{ctr:sc.ctr,ctrH:sc.ctrH,from:String(sc.from),weeks:sc.weeks,proj:sc.proj,bau:sc.bau,agent:sc.agent},
 live:v=>{const R=scenCalc({ctr:+v.ctr||0,ctrH:+v.ctrH||0,from:+v.from||0,weeks:+v.weeks||1,proj:v.proj||[],bau:+v.bau||0,agent:+v.agent||0},scopeAgg());return `<div class="pp2-live"><b>Result</b> Average load, next 26 weeks: ${pc(R.avg0)} to <b>${pc(R.avg1)}</b>. Weeks above 100%: ${R.o0} to <b>${R.o1}</b>. Added cost $${fmt(R.cost/1000)}k.</div>`},
 onSubmit:v=>{CAP.scen={ctr:+v.ctr||0,ctrH:+v.ctrH||0,from:+v.from||0,weeks:+v.weeks||1,proj:v.proj||[],bau:+v.bau||0,agent:+v.agent||0};audit("changed capacity scenario","");return {toast:"Scenario updated"}}})}
/* ---- forecast ---- */
function forecastTab(){const A=scopeAgg();const mons=MONTHS.map(m=>{let c=0,d=0,n=0;for(let w=m.w0;w<=m.w1;w++){c+=A.cap[w];d+=A.tot[w];n++}c/=n;d/=n;return {lab:m.lab,cap:c,dem:d,gap:(d-c)/40,n}});const gapM=mons.filter(m=>m.gap>.5);const mxG=Math.max(0,...mons.map(m=>m.gap));const avgGap=gapM.length?mean(gapM.map(m=>m.gap)):0;const peak=mons.reduce((a,m)=>m.gap>a.gap?m:a,mons[0]);
 const rate=rateAvg(),loaded=loadedAvg();const weeksG=gapM.length*4.35;const hireC=avgGap*loaded*Math.max(1,gapM.length)/12*1.0,ctrC=avgGap*40*weeksG*rate,mspC=Math.max(avgGap*40*weeksG*88,3*160*88);const reqShare=(()=>{let r=0,t=0;for(let w=0;w<26;w++){r+=A.T.req[w]+A.T.bau[w]*.5;t+=A.tot[w]}return t?r/t:0})();const aiC=gapM.length?Math.round(avgGap*40*weeksG*reqShare*.35):0;
 const rec=gapM.length===0?"No gap to fill. Hold the current team.":gapM.length>=9?"The shortfall lasts most of the year, so hiring is cheaper than renting. Open a role now: with a 10-week lead time the first months need a contractor bridge.":gapM.length<=5?"The shortfall is short-lived. A contractor or provider is cheaper than a hire you would not need after "+gapM[gapM.length-1].lab+".":"A mix fits: hire for the baseline gap and use contractors for the peak.";
 const mx=Math.max(1,...mons.map(m=>Math.max(m.cap,m.dem)))*1.1;
 return scopeBar()+`<p class="story" data-role="story">${gapM.length?`Demand is above capacity in <b>${gapM.length} of 12 months</b>, worst in <b>${peak.lab}</b> at ${f1(peak.gap)} FTE short (average ${f1(avgGap)} FTE in the months that are short). ${rec}`:"Capacity covers demand in every month. "+rec}</p>
 ${card("Demand against capacity, by month","Average weekly hours. Bars over the line are months with a shortfall.",`<div class="pp2-mobars" role="img" aria-label="Monthly demand against capacity">${mons.map(m=>`<div class="pp2-mob ${m.gap>.5?"short":""}"><span class="pp2-mobs"><i style="height:${m.dem/mx*100}%;background:var(${m.gap>.5?"--bad-f":"--p4"})" title="Demand ${fmt(m.dem)} h"></i></span><s style="bottom:${m.cap/mx*100}%"></s><small>${m.lab}</small><em>${m.gap>.5?f1(m.gap)+" FTE":""}</em></div>`).join("")}</div>${legend([["Demand","--p4"],["Demand above capacity","--bad-f"],["Available hours","--good-f"]])}`)}
 ${card("Hire or buy","Cost to cover the shortfall over the year for each option. Estimates, based on today's rate card and open roles.",`<div class="tscroll"><table><thead><tr><th>Option</th><th>Lead time</th><th>Cost for the gap</th><th>Good when</th><th>Watch for</th></tr></thead><tbody>
 <tr><td><b>Hire employees</b></td><td>About 10 weeks</td><td class="num">$${fmt(hireC/1000)}k</td><td class="small">The gap lasts 9 months or more</td><td class="small">Half productivity for the first 3 months</td></tr>
 <tr><td><b>Contractors</b></td><td>About 2 weeks</td><td class="num">$${fmt(ctrC/1000)}k</td><td class="small">Short or uncertain demand</td><td class="small">$${rate} an hour average; knowledge leaves with them</td></tr>
 <tr><td><b>Managed service provider</b></td><td>About 4 weeks</td><td class="num">$${fmt(mspC/1000)}k</td><td class="small">Steady, well-defined run work</td><td class="small">Minimum monthly commitment; credits for missed levels</td></tr>
 <tr><td><b>AI agents</b></td><td>Days</td><td class="num">$${fmt(aiC*8/1000)}k</td><td class="small">Requests and routine work (${Math.round(reqShare*100)}% of demand)</td><td class="small">Covers up to ${fmt(aiC)} hours; needs an accountable human</td></tr></tbody></table></div><div class="row" style="margin-top:12px"><button class="btn primary" data-pp2-act="newreq" data-a="">Request resources</button><button class="btn" data-pp2-act="scenedit">Try it as a scenario</button></div>`)}
 ${card("Open roles","Roles already being filled count against the gap once started.",st.vac.filter(v=>v.status!=="Filled").length?`<div class="tscroll"><table><thead><tr><th>Role</th><th>Team</th><th>Status</th><th>Open since</th><th>Skills</th></tr></thead><tbody>${st.vac.filter(v=>v.status!=="Filled").map(v=>`<tr><td>${E(v.title)}</td><td>${E(v.team)}</td><td><span class="pill info">${E(v.status)}</span></td><td>${E(v.opened)}</td><td class="small">${E((v.skills||[]).join(", "))}</td></tr>`).join("")}</tbody></table></div>`:'<p class="muted">No open roles.</p>')}`}
/* ---- bench and requests ---- */
function candidates(q){const w0=clamp(wkOfIso(q.from),0,NWK-1),w1=clamp(wkOfIso(q.to),w0,NWK-1);const L=DIR.filter(d=>(q.kind==="any"||d.kind===q.kind)&&d.team&&!(d.kind==="contractor"&&d.end&&wkOfIso(d.end)<w1)).map(d=>{const m=PM(d.name),tg=tgtOf(d);let room=0,n=0;for(let w=w0;w<=Math.min(w1,w0+11);w++){room+=Math.max(0,tg[1]*m.cap[w]-m.tot[w]);n++}room/=Math.max(1,n);const ov=(q.skills||[]).filter(s=>(d.skills||[]).some(x=>x.toLowerCase()===s.toLowerCase())).length;return {d,room,ov,score:ov*20+Math.min(room,q.fte*40)+(d.team===q.team?5:0)}}).filter(x=>x.room>=q.fte*40*.4||q.kind==="ai").sort((a,b)=>b.score-a.score);return L.slice(0,5)}
function rqCard(q){const c=q.status==="Filled"?[]:candidates(q).slice(0,2);return `<div class="pp2-wi" data-dnd-id="${q.id}"><span class="grip" aria-hidden="true"></span><div><button class="pp2-lnk" data-pp2-act="rq" data-a="${q.id}"><b>${E(q.title)}</b></button><div class="small muted">${E(q.team)} · ${RQKIND[q.kind]} · ${q.fte} FTE · ${DT(q.from)} to ${DT(q.to)}</div>${c.length?`<div class="small">Best matches: ${c.map(x=>E(x.d.name)).join(", ")}</div>`:q.filledBy?`<div class="small">Filled by ${pchip(q.filledBy)}</div>`:""}</div></div>`}
function benchTab(){const names=DIR.filter(d=>d.kind!=="msp"&&d.team).map(d=>d.name);const bench=names.map(n=>{const m=PM(n),u=avgU({cap:m.cap,tot:m.tot},0,7);let room=0;for(let w=0;w<8;w++)room+=Math.max(0,tgtOf(m.r)[1]*m.cap[w]-m.tot[w]);return {id:n,name:n,kind:KINDS[m.r.kind],team:m.r.team||"",u:Math.round(u*100),room:Math.round(room/8),skills:(m.r.skills||[]).slice(0,3).join(", ")}}).filter(r=>r.u<65&&r.room>=8).sort((a,b)=>b.room-a.room);
 const cols=RQST.map(s=>[s,s]);const open=CAP.reqs.filter(q=>q.status!=="Filled");const fte=open.reduce((a,q)=>a+q.fte,0);
 return `<p class="story" data-role="story">${open.length} open resource requests ask for <b>${f1(fte)} FTE</b>. ${bench.length} people have room of 8 hours a week or more over the next 8 weeks. Drag a request between columns as it moves through the resource manager. The agent lists the best matches from all four kinds of worker, checked against skills and available hours.</p>
 <div class="row" style="margin-bottom:12px"><button class="btn primary" data-pp2-act="newreq" data-a="">New resource request</button></div>
 <div class="pp2-kanban pp2-k4">${cols.map(([k,l])=>{const L=CAP.reqs.filter(q=>q.status===k);return `<div class="pp2-kc"><h4>${l} <span class="muted">${L.length}</span></h4><div class="pp2-kl" data-dnd="${k}" data-dnd-scope="pp2rq">${L.map(rqCard).join("")}</div></div>`}).join("")}</div>
 ${legend([["Submitted","--faint"],["With the resource manager","--p4"],["Approved","--good-f"],["Filled","--s3"]])}
 ${card("Bench","People and providers with room in the next 8 weeks.",btHTML({id:"pp2_bench",cols:[{k:"name",label:"Person",fmt:r=>pchip(r.name)},{k:"kind",label:"Kind"},{k:"team",label:"Team"},{k:"u",label:"Load",fmt:r=>`<span class="pill ${uCls(r.u/100)}">${r.u}%</span>`},{k:"room",label:"Room (h a week)"},{k:"skills",label:"Skills"}],rows:()=>bench,key:"id",h:380,rowH:44,facets:["team","kind"],groupBy:["team","kind"],exportName:"bench",open:id=>{CAP.person=id;st.tab.ppl_cap=3;go("ppl_cap")}}))}`}
function rqDrawer(id){const q=CAP.reqs.find(x=>x.id===id);if(!q)return;const c=candidates(q);openDrawer(`<div class="eyebrow">Resource request ${q.id}</div><h2 style="font-size:26px;margin:4px 0 8px">${E(q.title)}</h2><p class="story" data-role="story">${E(q.by)} asks for <b>${q.fte} FTE</b> from ${DT(q.from)} to ${DT(q.to)} for ${E(q.team)}. ${E(q.why)}</p><dl class="kv"><dt>Kind</dt><dd>${RQKIND[q.kind]}</dd><dt>Role family</dt><dd>${E(q.role||"")}</dd><dt>Skills</dt><dd>${E((q.skills||[]).join(", ")||"Any")}</dd><dt>Status</dt><dd><span class="pill info">${q.status}</span></dd></dl>
 ${q.status!=="Filled"?`<div class="eyebrow" style="margin-top:12px">Best matches</div>${c.length?lrHTML({id:"pp2rm"+q.id,groups:[{key:"a",label:"Skills and room",rows:c.map(x=>({id:x.d.name,t:x.d.name,sub:KINDS[x.d.kind]+" · "+x.ov+" skill match"+(x.ov===1?"":"es")+" · "+Math.round(x.room)+" h a week free",tag:x.d.team,st:"info",go:()=>{CAP.person=x.d.name;closeDrawer();st.tab.ppl_cap=3;go("ppl_cap")}}))}],limit:5}):'<p class="muted small">No one has room. Consider a contractor.</p>'}<div class="row" style="margin-top:12px">${q.status!=="Approved"?`<button class="btn primary" data-pp2-act="rqmove" data-a="${q.id}|Approved">Approve</button>`:""}<button class="btn" data-pp2-act="rqfill" data-a="${q.id}">Mark filled</button></div>`:`<p class="small">Filled by ${q.filledBy?pchip(q.filledBy):"a named person"}.</p>`}`)}
function fillForm(id){const q=CAP.reqs.find(x=>x.id===id);if(!q)return;const c=candidates(q);openForm({id:"pp2_fill",title:"Who fills "+q.title+"?",story:"Pick the person or worker who takes this on. Their hours start counting from the first week.",submit:"Mark filled",fields:[{k:"p",label:"Person",type:"select",req:true,opts:c.map(x=>[x.d.name,x.d.name+" · "+KINDS[x.d.kind]]).concat(DIR.filter(d=>d.team===q.team).slice(0,30).map(d=>[d.name,d.name+" · "+d.team])).filter((o,i,a)=>a.findIndex(z=>z[0]===o[0])===i)}],defaults:{p:c[0]&&c[0].d.name},onSubmit:v=>{q.status="Filled";q.fulfilled=true;q.filledBy=v.p;const w0=clamp(wkOfIso(q.from),0,NWK-1),w1=clamp(wkOfIso(q.to),w0,NWK-1);for(let w=w0;w<=w1;w++)CAP.ov.push({fx:"FL"+q.id,owner:v.p,type:"proj",w,h:q.fte*40});decide(q);bumpMv();audit("filled resource request",q.title+" with "+v.p);return {toast:q.title+" filled by "+v.p}}})}
function decide(q){q.decided=true;q.days=Math.max(1,Math.round((Date.parse("2026-10-07")-Date.parse(q.at))/DAY));}
DND.on("pp2rq",(id,from,to)=>{const q=CAP.reqs.find(x=>x.id===id);if(!q||q.status===to)return;if(to==="Filled"){render();fillForm(id);return}q.status=to;if(to==="Approved")decide(q);bumpMv();audit("moved resource request",q.title+" to "+to);toast(q.title+" is now "+to.toLowerCase(),"good");render()});
function newReq(pre){const tms=teamList();openForm({id:"pp2_nreq",title:"New resource request",story:"Describe the need. A request creates unstaffed demand in the plan until it is filled, so the heatmaps show the pressure right away.",submit:"Submit request",fields:[{k:"title",label:"What is needed",type:"text",req:true,ph:"Two engineers for the portal build",ai:{label:"Write it",fn:v=>"Extra "+(v.role||"capacity")+" for "+(v.team||"the team")}},{k:"team",label:"Team",type:"select",req:true,opts:tms},{k:"kind",label:"Kind of worker",type:"chips",opts:Object.entries(RQKIND)},{k:"role",label:"Role family",type:"select",opts:ROLEFAMS},{k:"skills",label:"Skills",type:"multi",opts:[...new Set(DIR.flatMap(d=>d.skills||[]))].slice(0,60).map(s=>[s,s])},{k:"fte",label:"Full-time equivalents",type:"range",min:.25,max:6,step:.25},{k:"from",label:"From",type:"date",req:true},{k:"to",label:"To",type:"date",req:true},{k:"why",label:"Why",type:"longtext",wide:true,req:true}],
 defaults:Object.assign({kind:"any",fte:1,from:"2026-11-02",to:"2027-01-29",team:tms[0],role:"Engineer or architect"},pre||{}),
 live:v=>{const q={kind:v.kind||"any",skills:v.skills||[],fte:+v.fte||1,from:v.from||"2026-11-02",to:v.to||"2027-01-29",team:v.team};const c=candidates(q);const wks=Math.max(1,(Date.parse(q.to)-Date.parse(q.from))/(7*DAY));return `<div class="pp2-live"><b>Estimate</b> ${f1(q.fte*40*wks)} hours. As contractors about $${fmt(q.fte*40*wks*rateAvg()/1000)}k. ${c.length?"Best match today: "+E(c[0].d.name)+" ("+Math.round(c[0].room)+" h a week free).":"No one in the directory has room, so this is likely a contractor or hire."}</div>`},
 onSubmit:v=>{const q={id:"RQ"+(CAP.reqs.length+1),title:v.title,team:v.team,role:v.role,kind:v.kind||"any",skills:v.skills||[],fte:+v.fte,from:v.from,to:v.to,status:"Submitted",by:"Omar Hamid",why:v.why,at:"2026-10-07"};CAP.reqs.unshift(q);bumpMv();audit("resource request",v.title);return {toast:"Request submitted. It is shown as unstaffed demand until filled."}}})}
/* ---- targets ---- */
function targetsTab(){const rows=ROLEFAMS.map(f=>{const L=DIR.filter(d=>rfam(d)===f&&d.kind!=="msp");const u=L.length?mean(L.map(d=>avgU({cap:PM(d.name).cap,tot:PM(d.name).tot},0,11))):0;const tg=CAP.tgt[f]||[.6,.85];return {f,n:L.length,u,lo:tg[0],hi:tg[1],st:u>tg[1]?"over":u<tg[0]?"under":"in"}});
 return `<p class="story" data-role="story">A target band says how busy each kind of role should be. A manager at 100% has no time to manage; a service desk analyst at 60% is waiting for work. ${rows.filter(r=>r.st==="over").length} role families are above their band and ${rows.filter(r=>r.st==="under").length} are below. Bands feed the "can they handle more?" answer and the overload checks.</p>
 ${card("Utilization targets by role family","Average load over the next 12 weeks against the band.",`<div class="tscroll"><table><thead><tr><th>Role family</th><th>People</th><th>Load, 12 weeks</th><th>Band</th><th></th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td>${E(r.f)}</td><td class="num">${r.n}</td><td class="num">${pc(r.u)}</td><td class="num">${pc(r.lo)} to ${pc(r.hi)}</td><td><span class="pill ${r.st==="over"?"bad":r.st==="under"?"info":"good"}">${r.st==="over"?"Above band":r.st==="under"?"Below band":"In band"}</span></td><td><button class="btn quiet" data-pp2-act="tgt" data-a="${E(r.f)}">Edit</button></td></tr>`).join("")}</tbody></table></div>${legend([["In band","--good-f"],["Above band","--bad-f"],["Below band","--p6"]])}`)}`}
function tgtForm(f){const t=CAP.tgt[f];openForm({id:"pp2_tgt",title:"Target band for "+f,story:"Sets the load a healthy person in this role family should carry. Over the high end is flagged as risk; under the low end as spare capacity.",submit:"Save band",fields:[{k:"lo",label:"Low end",type:"range",min:30,max:90,unit:"%"},{k:"hi",label:"High end",type:"range",min:50,max:100,unit:"%"}],defaults:{lo:Math.round(t[0]*100),hi:Math.round(t[1]*100)},live:v=>+v.lo>=+v.hi?'<p class="small" style="color:var(--bad-f)">The low end must be below the high end.</p>':"",onSubmit:v=>{if(+v.lo>=+v.hi)return {toast:"The low end must be below the high end.",keep:true};CAP.tgt[f]=[+v.lo/100,+v.hi/100];TGT0[f]=CAP.tgt[f];audit("changed utilization target",f+": "+v.lo+"% to "+v.hi+"%");return {toast:"Band saved for "+f}}})}
/* ---- screen ---- */
function capScreen(){syncCap();const tab=tabIdx("ppl_cap",9);const panes=[capDash,heatTab,workTab,personTab,overTab,scenTab,forecastTab,benchTab,targetsTab];
 const A=agg(DIR.map(d=>d.name),"all:"+DIR.length+"|"+(st.mv||0)+"|"+(st.ver||0));const o=ovStats(DIR.map(d=>d.name),0,11);
 const story=`Planning covers <b>every kind of work</b>, not only projects: incidents, requests, changes, on-call, operational work, meetings, training and leave, for ${fmt(DIR.length)} employees, contractors, AI agents and providers across ${NWK} weeks. Load over the next 12 weeks is <b>${pc(avgU(A,0,11))}</b>, with <b>${o.people}</b> ${o.people===1?"person":"people"} over capacity. Pull any person to see everything on their plate and whether they can take more.`;
 return `<div class="screen">${hero("People and work","Resource planning",story,`<div class="row">${fchip("m_pp_util")}${fchip("m_pp_over")}${fchip("m_pp_gap")}<button class="btn primary" data-pp2-act="newreq" data-a="">Request resources</button><button class="btn" data-pp2-act="gocap" data-a="">Find a person</button>${stdChip("capplan")}${aiChip({model:"Resource Agent",conf:.82,title:"How capacity is computed",src:["Project plans and the schedule engine","Incidents, requests and changes","Calendar, leave and holidays","On-call rota","Contract end dates and provider hours"],guards:["Proposes only. You decide.","Does not see pay or performance ratings"]})}</div>`)}${lensNote()}${tabsBar("ppl_cap",["Dashboard","Heatmap","Work types","Person","Over capacity","Scenarios","Forecast","Bench and requests","Targets"])}<div class="pp2-pane">${panes[tab]()}</div>${procCard("ppl_cap")}</div>`}
REG("ppl_cap","Resource planning","people","M3 20V9M9 20V4M15 20v-8M21 20v-5M2 20h20",capScreen);
PROC.reg("ppl_cap",{title:"How resource planning works",std:["capplan","tt"],steps:[{n:"Collect demand",d:"Every work type reports hours per person per week: projects, incidents, requests, changes, on-call, operational work, meetings, training.",who:"auto",owner:"Resource Agent",sla:"Continuous",in:"Plans, queues, calendar",out:"Hours per person per week"},{n:"Subtract leave and holidays",d:"Approved time off and the company calendar reduce available hours. Contracts end on their end date.",who:"auto",owner:"Resource Agent",sla:"Continuous",in:"Leave, holidays, contracts",out:"Available hours"},{n:"Spot pressure",d:"Group and person load against the target band for the role family.",who:"agent",owner:"Resource Agent",sla:"Daily",in:"Demand and capacity",out:"Over and under capacity"},{n:"Propose fixes",d:"Move work, add a contractor, offload to an agent, or defer. Each with cost and risk.",who:"agent",owner:"Resource Agent",sla:"Same day",in:"Over capacity",out:"Ranked fixes"},{n:"Decide and request",d:"A manager applies a fix or raises a resource request. The resource manager approves.",who:"gate",owner:"Omar Hamid",sla:"5 working days",in:"Fix or request",out:"Decision"},{n:"Fill and re-plan",d:"The filled request adds hours to the named person and the plan updates.",who:"human",owner:"Priya Shah",sla:"Per request",in:"Approved request",out:"Updated plan"}]});
/* actions */
Object.assign(ACT,{heatdim(t){CAP.heat=t.dataset.a;CAP.pg.heat=0;render()},heatmore(){CAP.pg.heat=(CAP.pg.heat||0)+25;render()},rgrp(t){const [d,k]=t.dataset.a.split("|");groupDrawer(d,k,null)},rcell(t){const [d,k,w]=t.dataset.a.split("|");groupDrawer(d,k,+w)},level(t){levelDrawer(t.dataset.a)},fix(t){const [n,id]=t.dataset.a.split("|");applyFix(n,id)},unfix(t){undoFix(t.dataset.a)},
 capcsv(){const dim=CAP.heat;const rows=dim==="person"?scopeNames().map(n=>[n,PM(n)]):groupRows(dim).map(([k,l])=>[l,gagg(dim,k)]);csv("capacity-"+dim+".csv",[["Row"].concat(WK.map(w=>w.iso))].concat(rows.map(([l,a])=>[l].concat(WK.map((w,i)=>{const u=CAP.wt==="all"?(a.cap[i]>.5?a.tot[i]/a.cap[i]:null):cellVal(a,i,CAP.wt);return u==null?"":Math.round(u*100)})))));audit("exported capacity",dim);toast("Exported "+rows.length+" rows","good")},
 scaletest(){const t=performance.now();PMC.clear();TAC.clear();SRC=null;DIR.forEach(d=>PM(d.name));CAP.scaleMs=performance.now()-t;toast("Rebuilt "+fmt(DIR.length*NWK*WT.length)+" cells in "+Math.round(CAP.scaleMs)+" ms","good");render()},
 newreq(t){closeDrawer();newReq(t&&t.dataset&&t.dataset.a?{team:t.dataset.a,kind:t.dataset.b||"any"}:t&&t.dataset&&t.dataset.b?{kind:t.dataset.b}:null)},rq(t){rqDrawer(t.dataset.a)},rqmove(t){const [id,s]=t.dataset.a.split("|");const q=CAP.reqs.find(x=>x.id===id);if(q){q.status=s;if(s==="Approved")decide(q);bumpMv();audit("approved resource request",q.title);toast("Approved","good");closeDrawer();render()}},rqfill(t){closeDrawer();fillForm(t.dataset.a)},tgt(t){tgtForm(t.dataset.a)},
 scenedit(){scenForm()},scensave(){const R=scenCalc(CAP.scen,scopeAgg());CAP.saved.push({n:"Scenario "+(CAP.saved.length+1)+": "+CAP.scen.ctr+" contractors"+(CAP.scen.proj.length?" and "+CAP.scen.proj.length+" project(s)":""),peak:R.peak1,over:R.o1,cost:R.cost,sc:JSON.parse(JSON.stringify(CAP.scen))});toast("Scenario saved","good");render()},scenload(t){const s=CAP.saved[+t.dataset.a];if(s){CAP.scen=JSON.parse(JSON.stringify(s.sc));render()}},
 scencommit(){const sc=CAP.scen;const tm=selSet("pp2ct",teamList())[0]||"Platform team";if(sc.ctr>0)CAP.reqs.unshift({id:"RQ"+(CAP.reqs.length+1),title:sc.ctr+" contractors from the scenario",team:tm,role:"Engineer or architect",kind:"contractor",skills:[],fte:sc.ctr*sc.ctrH/40,from:isoOfWk(sc.from),to:isoOfWk(Math.min(NWK-1,sc.from+sc.weeks)),status:"Submitted",by:"Omar Hamid",why:"From a capacity scenario.",at:"2026-10-07"});(sc.proj||[]).forEach(id=>{const d=DEMAND.find(x=>x.id===id);if(d)(d.res||[]).forEach(([team,f])=>CAP.reqs.unshift({id:"RQ"+(CAP.reqs.length+1),title:"Capacity for "+d.n,team,role:"Engineer or architect",kind:"any",skills:[],fte:f,from:isoOfWk(Math.round(d.m0*4.35)),to:isoOfWk(Math.min(NWK-1,Math.round((d.m0+d.mo)*4.35))),status:"Submitted",by:"Omar Hamid",why:"Scenario for "+d.n,at:"2026-10-07",proj:d.id}))});bumpMv();audit("committed scenario to resource requests","");toast("Requests created. See Bench and requests.","good");st.tab.ppl_cap=7;render()},
 plate(t){const [n,id]=t.dataset.a.split("|");const it=plate(n).find(x=>String(x.id)===id);if(it&&it.go)it.go()},
 gocap(t){CAP.person=t.dataset.a||null;st.tab.ppl_cap=3;closeDrawer();go("ppl_cap")}});
document.addEventListener("input",e=>{const t=e.target.closest("[data-pp2-pq]");if(!t)return;const q=t.value.trim().toLowerCase();const box=document.getElementById("pp2PSug");if(!box)return;if(q.length<2){box.innerHTML="";return}const L=DIR.filter(d=>(d.name+" "+d.role+" "+d.team+" "+(d.skills||[]).join(" ")).toLowerCase().includes(q)).slice(0,8);box.innerHTML=L.map(d=>`<button type="button" role="option" data-pp2-act="gocap" data-a="${E(d.name)}">${avatar(d,{size:26})}<span><b>${E(d.name)}</b> <small>${E(roleOf(d))} · ${E(d.team||"")}</small></span></button>`).join("")||'<span class="muted small" style="padding:8px">No matches</span>'});
