DND.on("ppmst",(id,from,to)=>{const f=+from.split(":")[1],t=+to.split(":")[1],d=DEMAND.find(x=>x.id===id);if(!d||f===t)return;
 if(S.conv[id]){toast("This request is already a project","info");return render()}
 if(t>=3&&!d.obj){toast("Link a strategic objective before it can go to the review board.","bad");return render()}
 if(t>=2&&(!d.cost||!d.ben)){toast("Add cost and benefit before scoring.","bad");return render()}
 d.st=t;delete S.dst[id];audit("moved demand",d.id+" to "+DSTAGES[t]);toast(`${d.n} moved to ${DSTAGES[t]}`,"good");render()});

const tok=s=>new Set((s||"").toLowerCase().replace(/[^a-z0-9 ]/g," ").split(/\s+/).filter(w=>w.length>3&&!/^(that|this|with|from|have|will|their|them|than|more|into|your|they|when)$/.test(w)));
function dupOf(v){const a=tok((v.title||"")+" "+(v.why||""));if(a.size<2)return null;let best=null,bs=0;DEMAND.forEach(d=>{const b=tok(d.n+" "+d.why),i=[...a].filter(x=>b.has(x)).length,s=i/Math.max(3,Math.min(a.size,b.size));if(s>bs){bs=s;best=d}});return bs>=.28?{d:best,pct:Math.min(96,Math.round(bs*130))}:null}
const OBJS=()=>["O1","O2"].map(o=>[o,N(o).n]);
function suggest(v){const t=((v.title||"")+" "+(v.why||"")).toLowerCase();let s=2,r=1,u=2;if(/publish|standard|editor|codif|reader|comment|public/.test(t))s=4;if(/strategic|board|objective|modern/.test(t))s=5;if(/risk|audit|control|security|resilien|outage|compliance|regulat|fasb|asc/.test(t))r=4;if(/regulat|deadline|effective|mandate|expires?|renew/.test(t))u=5;else if(/before|by q|quarter|window/.test(t))u=3;return {s,r,u}}

/* ---------- fund and create a project ---------- */
const COLS=["--p2","--s4","--e1","--u4","--p6","--w3"];let pnum=4;
const DEFTASKS=[{n:"Plan and mobilize",dur:10},{n:"Deliver",dur:45},{n:"Go live",dur:0,ms:1}];
function addProject(o){pnum++;while(PROJ.some(p=>p.id==="PR"+pnum))pnum++;const id="PR"+pnum,c=COLS[(pnum-5)%COLS.length];PROJ.push({id,n:o.name,short:o.short||o.name.split(" ").slice(0,2).join(" "),c,owner:o.pm,bac:o.cost,paid:0,rec:null,src:o.src||"demand"});
 let prev=null;(o.tasks||DEFTASKS).forEach((t,i)=>{const tid=`p${pnum}_${i+1}`;TASKS.push(Object.assign({id:tid,p:id,pred:prev?[prev]:[],pct:0,own:o.pm,res:[]},t));prev=tid;});
 const nb=cpm(t=>t.bdur!=null?t.bdur:t.dur);BASE.R=nb.R;BASE.pe=nb.pe;if(o.team)P.team[id]=o.team.filter(x=>x!==o.pm);PJC.clear();_pjl=null;resetC();return id}
function seedTeam(d,pm){const out=[];(d.res||[]).forEach(([t])=>{DIR.filter(r=>r.team===t&&r.name!==pm&&r.kind!=="msp"&&!out.includes(r.name)).slice(0,2).forEach(r=>out.push(r.name))});return out.slice(0,5)}
function template(d,start,pm){const fte=d.res.reduce((a,r)=>a+r[1],0)||2,days=Math.max(40,Math.min(150,Math.round(d.pm*21/fte))),sh=x=>Math.max(3,Math.round(days*x));
 return [{n:"Charter and plan",dur:sh(.1),snet:start,res:[["Architecture",1]]},{n:"Design",dur:sh(.15),res:[["Architecture",1],...d.res.slice(0,1)]},{n:"Build",dur:sh(.5),res:d.res},{n:"Test and acceptance",dur:sh(.2),res:d.res.map(r=>[r[0],Math.max(1,Math.round(r[1]/2))])},{n:"Go live",dur:0,ms:1,res:[]}]}
function fundSpec(d){return {id:"ppm_fund",title:`Fund “${esc(d.n)}”`,story:"Funding turns the request into a project: a plan with gates, a budget, a team and a place on the master schedule. You can change any of it afterwards.",submit:"Fund and create the project",
 fields:[{k:"name",label:"Project name",type:"text",req:true,wide:true},{k:"pm",label:"Project manager",type:"people",req:true,help:"Drag people onto projects later in Projects and teams."},{k:"start",label:"Start date",type:"date",req:true},{k:"cost",label:"Approved budget (K)",type:"number",unit:" K",min:1,req:true},
  {k:"src",label:"Funding source",type:"chips",opts:["FY27 envelope","Management reserve","Grant"]},{k:"tmpl",label:"Plan template",type:"chips",opts:["Standard delivery","Vendor led","Agile"]},
  {k:"gates",label:"Also create",type:"multi",opts:["Stage-gate milestones","Budget line","Risk register","Resource requests"]}],
 live:v=>{const T=template(d,v.start||nextMon(),v.pm),days=T.reduce((a,t)=>a+t.dur,0);return `<b>Creates ${T.length-1} tasks and a go-live milestone</b> (${days} work days), starting ${v.start?fmtD(wdOf(v.start),1):"next Monday"}. Team: ${d.res.map(r=>esc(r[0])+" ("+r[1]+")").join(", ")}. It leaves the demand queue and takes its place on the master schedule and capacity heatmap.`},
 onSubmit:v=>{const id=addProject({name:v.name,pm:v.pm,cost:+v.cost,tasks:template(d,v.start,v.pm)});S.dapp[d.id]="Approved";S.conv[d.id]={pid:id};P.focus=id;P.team[id]=seedTeam(d,v.pm);return {toast:`${v.name} is now project ${id}, with ${v.pm} as manager. Opening it.`,audit:`${d.id} funded as ${id}`}},defaults:{name:d.n,pm:"Priya Shah",start:nextMon(),cost:d.cost,src:"FY27 envelope",tmpl:"Standard delivery",gates:["Stage-gate milestones","Budget line"]}}}
document.addEventListener("click",e=>{const t=e.target.closest("[data-dapp]");if(!t)return;const [id,v]=t.dataset.dapp.split(":");if(v!=="Approved")return;e.stopImmediatePropagation();e.preventDefault();const d=DEMAND.find(x=>x.id===id);if(S.conv[id]){toast("Already a project: "+S.conv[id].pid,"info");return}closeDrawer();openForm(fundSpec(d));FORMST.ppm_fund.vals.name=d.n},true);
const _fs=submitForm;submitForm=function(fid){const r=_fs(fid);if(fid==="ppm_fund"&&r){setTimeout(()=>go("ppm_proj"),50)}return r};

/* ---------- intake pane ---------- */
function intakePane(){const sub=DEMAND.filter(d=>d.st<=1&&!S.merged[d.id]).length,steps=[["Submit","Web form, email to intake, Teams message, a trigger, or a journey pain point",DEMAND.length],["Screen","Portfolio Agent checks for duplicates and missing facts",DEMAND.filter(d=>d.st>=1).length],["Score","Sponsor confirms four 0 to 5 ratings",DEMAND.filter(d=>d.st>=2).length],["Decide","Review board funds, parks or returns it",DEMAND.filter(d=>d.st>=3).length],["Deliver","Funded requests become projects automatically",Object.keys(S.conv).length]];
 const recent=DEMAND.slice().sort((a,b)=>b.id.slice(1)-a.id.slice(1)).slice(0,6);
 return `<div class="card glass"><div class="cardhead"><div><h3>How intake works</h3><span class="muted small" data-role="story">${sub} request${sub===1?" is":"s are"} waiting at the first two gates. Median decision time is ${METRICS.m_intake.cur} days against a target of ${METRICS.m_intake.tgt}.</span></div><div class="row">${fchip("m_intake")}<button class="btn primary" data-ppm-intake>New request</button></div></div>
 <div class="ppm-steps">${steps.map((s,i)=>`<div class="ppm-step"><span class="num">${i+1}</span><b>${s[0]}</b><small>${s[1]}</small><span class="pill mute num">${s[2]}</span></div>`).join("")}</div></div>
 <div class="grid g2" style="margin-top:18px"><section class="card glass"><div class="cardhead"><div><h3>Ways in</h3><span class="muted small">Every channel lands in the same queue, with the same fields.</span></div></div><div class="needs">${[["New request form","Full form with live score preview",`<button class="btn" data-ppm-intake>Open the form</button>`],["Email to intake","Forward a note to intake@meridian.example. Claude fills the form and asks the sender to confirm.",`<button class="btn" data-ppm-mail>Try an example</button>`],["From a contract","Upload a statement of work and its milestones, invoices and service levels are read for you.",`<button class="btn" data-go="ppm_sow">Open SOW analyzer</button>`],["From a pain point","Journey maps and incident trends can raise a request with the evidence attached.",`<button class="btn" data-go="ppl_jrny">See journey maps</button>`]].map(x=>`<div class="need" style="grid-template-columns:minmax(0,1fr) auto"><div><b>${x[0]}</b><span class="muted">${x[1]}</span></div>${x[2]}</div>`).join("")}</div></section>
 <section class="card glass"><div class="cardhead"><div><h3>What Portfolio Agent checks</h3></div>${aiChip({model:"Portfolio Agent",conf:.84,title:"Intake screening",note:"Compares wording with existing requests, checks required facts, and suggests ratings from the text. It never decides.",src:["Request text","Open demand","Objectives O1 and O2"],guards:["Suggestions only","Sponsor confirms scores"]})}</div><div class="needs">${["Duplicate wording against every open request","Objective, service and capability linked; cost and benefit stated","Hard dates (regulator, contract, event) and who owns them","Team capacity in the months it would start","Past decisions on similar requests"].map(t=>`<div class="need" style="grid-template-columns:auto 1fr"><div class="ico good">${ico("check")}</div><div><b>${t}</b></div></div>`).join("")}</div></section></div>
 <section class="card glass" style="margin-top:18px"><div class="cardhead"><div><h3>Demand that creates itself</h3><span class="muted small" data-role="story">When a service needs to scale, breaches its service level, fails a release review or sits below its maturity target, the system raises a request for you: scored, linked to the service, and logged. It is all connected.</span><div class="row">${fchip("m_trigd")}${stdChip("tbm","Technology Business Management (TBM) unit costs show when a service is about to outgrow its capacity or sit mostly idle. That becomes a scale up or scale down request.")}</div><div class="needs">${[["tbm","Unit-cost model says scale up","Search and indexing passes 85% of provisioned capacity in January"],["tbd","Unit-cost model says scale down","Three Azure test environments idle for 60 days"],["sla","Service level breach","Codification Portal availability under target two months running"],["chg","Release or change finding","Unsupported TLS listener found in a release review"],["mat","Maturity gap","Service continuity below its level 3 target"]].map(x=>`<div class="need" style="grid-template-columns:minmax(0,1fr) auto"><div><b>${x[1]}</b><span class="muted">${x[2]}</span></div><button class="btn" data-ppm-trig="${x[0]}">Simulate this trigger</button></div>`).join("")}</div><p class="muted small" style="margin-top:12px">Other modules call <code>addDemand({title, reason, source, cost, service, kind, pm})</code>. The request appears at the top of Priorities with a Created by trigger badge, already scored, and a person screens it before the board.</p></section>
 <section class="card glass" style="margin-top:18px"><div class="cardhead"><h3>Recent requests</h3></div><div class="needs">${recent.map(d=>`<button class="need" data-dem="${d.id}" style="grid-template-columns:minmax(0,1fr) auto"><div><b>${esc3(d.n)}</b><span class="muted">${esc3(d.who)} · ${DSTAGES[d.st]} · ${K$(d.cost)}${d.wk?" · "+esc3(d.wk):""}</span></div><span class="pill ${d.trig?"info":d.obj?"mute":"warn"}">${d.trig?"Trigger":d.obj?"Objective linked":"No objective"}</span></button>`).join("")}</div></section>`}
