function tmRaw(pid){if(!P.team[pid]){const p=prjOf(pid);let a=[];if(SEED_TEAM[pid])a=SEED_TEAM[pid].slice();else if(p&&p.scaled){const r=RNG("team"+pid),n=3+Math.floor(r()*5),W={human:.6,contractor:.5,ai:.35,msp:.3};let g=0;while(a.length<n&&g++<80){const x=DIR[Math.floor(r()*DIR.length)];if(r()<W[x.kind]&&x.name!==p.owner&&!a.includes(x.name))a.push(x.name)}}else{a=[...new Set(TASKS.filter(t=>t.p===pid).map(t=>t.own))].filter(x=>x&&x!==(p||{}).owner)}P.team[pid]=a.filter(x=>x!==(p||{}).owner)}return P.team[pid]}
