function pokerPanel(s,mine,fac){const t=tmOf(s.tm),voters=t.mem.filter(m=>{const k=(who(m.n)||{}).kind;return k==="human"||k==="contractor"}).slice(0,5);const base=sizeFrom(fac.c,fac.u,fac.e),bi=FIBS.indexOf(base);
 const cards=voters.map(m=>{const r=RNG(s.id+m.n)();const off=r<.2?-1:r>.82?1:0;const v=FIBS[Math.max(0,Math.min(6,bi+off))];return {n:m.n,v}});const ai=FIBS[Math.max(0,Math.min(6,FIBS.indexOf(nearFib(s.pts))))];cards.push({n:"Test Agent",v:ai,ai:1});
 const shown=mine?cards.concat([{n:"You",v:+mine,me:1}]):cards,vs=shown.map(c=>c.v),lo=Math.min(...vs),hi=Math.max(...vs),spread=FIBS.indexOf(hi)-FIBS.indexOf(lo);
 return `<div class="rel-pk"><div class="rel-pkc">${shown.map(c=>`<div class="rel-pcard ${mine?"":"hid"}"><b>${mine?c.v:"?"}</b><small>${c.me?"You":esc(c.n.split(" ")[0])}</small>${c.ai?"<small>AI</small>":""}</div>`).join("")||""}${!mine?'<div class="rel-pcard hid me"><b>?</b><small>You</small></div>':""}</div><p class="small">${!mine?"Pick a size to reveal everyone's cards. Votes stay hidden until you choose, so nobody anchors the others.":spread<=1?`<b>Consensus.</b> Votes sit within one step (${lo} to ${hi}). Use ${hi===lo?hi:FIBS[Math.round((FIBS.indexOf(lo)+FIBS.indexOf(hi))/2)]} points.`:`<b>Wide spread (${lo} to ${hi}).</b> The highest and lowest voters explain their reasoning, then everyone votes again.`} The factors suggest <b>${base}</b> points; the closest reference story is "${esc(refFor(base)[1])}".</p></div>`}
function estimateForm(sid){const s0=sid?stories().find(x=>x.id===sid):STORY.find(x=>x.sp==="26.4.2"&&x.dor)||STORY[0];
 openForm({id:"rel_est",title:"Estimate a story",story:"The team estimates together with planning poker: everyone picks a card in secret, then the cards are shown at once. Points are relative size on the Fibonacci scale, not hours. Saving updates the story and the sprint's commitment.",submit:"Save estimate",defaults:{sid:s0.id,cx:3,un:3,ef:3,pts:String(s0.pts)},
 fields:[{k:"sid",label:"Story id",type:"text",req:true,ph:"ST-1042",help:"For example "+s0.id},{k:"cx",label:"Complexity (1 to 5)",type:"range",min:1,max:5},{k:"un",label:"Uncertainty (1 to 5)",type:"range",min:1,max:5},{k:"ef",label:"Effort (1 to 5)",type:"range",min:1,max:5},{k:"pts",label:"Your vote",type:"chips",req:true,opts:FIBL,help:"Anything above 8 should be split."}],
 live:v=>{const s=stories().find(x=>x.id===(v.sid||"").trim().toUpperCase());if(!s)return `<div class="rel-lv glass"><p class="small">Enter a story id to see its team's cards.</p></div>`;return `<div class="rel-lv glass"><b>${esc(s.id+" "+s.t)}</b><span class="small muted"> · ${esc(tmName(s.tm))} · currently ${s.pts} points</span>${pokerPanel(s,v.pts,{c:v.cx,u:v.un,e:v.ef})}${+v.pts>8?'<p class="small rel-od">Above 8 points: split this story before it enters a sprint.</p>':""}</div>`},
 onSubmit:v=>{const s=stories().find(x=>x.id===(v.sid||"").trim().toUpperCase());if(!s)return {toast:"Story not found",close:false};const was=s.pts;s.pts=+v.pts;audit("estimated story",s.id+": "+was+" → "+s.pts);render();return {toast:s.id+" is now "+s.pts+" points"}}})}
function newStoryForm(){const t0=R.bt;
 openForm({id:"rel_story",title:"New story",story:"A story is one small, testable slice of value. Saving puts it in the team backlog (or the chosen sprint), checks it against the definition of ready and links it to a feature so it rolls up to a release.",submit:"Create story",defaults:{ty:"Story",tm:t0,pts:"3",sp:"",top:true},
 fields:[{k:"t",label:"Title",type:"text",req:true,wide:true,ph:"Show cross references in the compare panel"},{k:"ty",label:"Kind",type:"chips",opts:[["Story","Enhancement"],["Defect","Defect"],["Enabler","Enabler"],["Spike","Spike"]]},{k:"sev",label:"Severity",type:"chips",opts:[["1","1 Critical"],["2","2 High"],["3","3 Medium"],["4","4 Low"]],show:v=>v.ty==="Defect"},{k:"tm",label:"Team",type:"select",req:true,opts:TEAM.map(t=>[t.id,t.n])},{k:"ft",label:"Feature",type:"select",ph:"No feature (maintenance)",opts:FEAT.filter(f=>f.st!=="Done").map(f=>[f.id,f.id+" "+f.t])},{k:"pts",label:"Points",type:"chips",opts:FIBL,help:"Use the reference stories in Standards and ceremonies."},{k:"ac",label:"Acceptance criteria",type:"longtext",wide:true,ph:"One per line, in Given, When, Then form",ai:{label:"Draft",fn:v=>"Given the change is in use, when the user completes the task, then the result is correct.\nGiven an error, then a plain message explains what to do next.\nGiven keyboard-only use, then every step works."}},{k:"sp",label:"Plan into",type:"select",opts:[["","Backlog"],["26.4.2","Sprint 26.4.2"],["26.4.3","Sprint 26.4.3"]]},{k:"top",label:"Rank at the top of the backlog",type:"toggle"}],
 live:v=>{const n=(v.ac||"").split("\n").filter(x=>x.trim()).length,chk=[["Has a title",!!v.t],["Two or more acceptance criteria",n>=2],["Eight points or fewer",+v.pts<=8],["Linked to a feature",!!v.ft]];return `<div class="rel-lv glass"><b>Definition of ready</b><ul class="rel-ck2">${chk.map(c=>`<li class="${c[1]?"ok":"no"}">${c[1]?"Yes":"No"} · ${c[0]}</li>`).join("")}</ul><span class="small muted">Next: the product owner of ${esc(tmName(v.tm))} sees it in the team backlog.</span></div>`},
 onSubmit:v=>{const mx=Math.max(...STORY.map(x=>+x.id.slice(3)))+1;const n=(v.ac||"").split("\n").filter(x=>x.trim()).length;const t=tmOf(v.tm);const s=Object.assign(mkStory(t,RNG("n"+mx),{}),{id:"ST-"+mx,t:v.t,ty:v.ty||"Story",cat:v.ty==="Defect"?"Defect":v.ty==="Story"||!v.ty?"Enhancement":"Enabler",tm:v.tm,ft:v.ft||null,pts:+v.pts||3,sp:v.sp||null,st:"To do",as:null,sev:v.ty==="Defect"?+v.sev||3:0,ac:Math.max(2,n),acm:0,pr:null,ta:{n:0,p:0},tm_:{n:0,p:0},ct:TODAYI,dor:n>=2&&(+v.pts||3)<=8,found:"",esc:false,rk:v.top?0:9999});STORY.push(s);STORY.filter(x=>x.tm===v.tm&&x.st!=="Done").sort((a,b)=>a.rk-b.rk).forEach((x,i)=>x.rk=i+1);rebuild();audit("created story",s.id);R.bt=v.tm;render();return {toast:s.id+" created in "+tmName(v.tm)+(v.sp?" and planned into "+v.sp:"")}}})}
function pickFill(tid,sp,pctCap,readyOnly,commit){const t=tmOf(tid),cap=Math.round(capOf(t,"x")*pctCap/100);let acc=sum(STORY.filter(s=>s.tm===tid&&s.sp===sp),s=>s.pts);const out=[];for(const s of teamBacklog(tid)){if(readyOnly&&!s.dor)continue;if(acc+s.pts>cap)continue;out.push(s);acc+=s.pts;if(acc>=cap)break}return {out,acc,cap}}
function planForm(){openForm({id:"rel_plan",title:"Plan a sprint",story:"Sprint planning: the product owner brings the ranked backlog, the team brings its capacity, and together they commit to a goal. This form fills the sprint from the top of the backlog up to a share of capacity, skipping stories that are not ready if you ask. You can still drag stories afterward.",submit:"Plan sprint",defaults:{tm:R.bt,sp:"26.4.2",fill:95,ready:true,goal:""},
 fields:[{k:"tm",label:"Team",type:"select",opts:TEAM.map(t=>[t.id,t.n]),req:true},{k:"sp",label:"Sprint",type:"chips",opts:[["26.4.2","26.4.2 · Oct 12"],["26.4.3","26.4.3 · Oct 26"]]},{k:"goal",label:"Sprint goal",type:"longtext",wide:true,ph:"One sentence the whole team can say",ai:{label:"Draft",fn:v=>"Get "+((FEAT.find(f=>f.tms.includes(v.tm)&&f.st==="Implementing")||{}).t||"the top feature")+" ready for acceptance testing."}},{k:"fill",label:"Fill to capacity",type:"range",min:50,max:110,unit:"%"},{k:"ready",label:"Only stories that meet the definition of ready",type:"toggle"}],
 live:v=>{const f=pickFill(v.tm,v.sp||"26.4.2",+v.fill||95,v.ready,0),t=tmOf(v.tm);return `<div class="rel-lv glass"><b>${esc(t.n)} · sprint ${v.sp}</b><p class="small">Capacity target ${f.cap} points. Already committed ${sum(STORY.filter(s=>s.tm===v.tm&&s.sp===(v.sp||"26.4.2")),s=>s.pts)}. This will add <b>${f.out.length} stories</b> and bring the sprint to <b>${f.acc} points</b> (${pct(f.acc,capOf(t,"x"))}% of full capacity).</p><span class="small muted">Capacity = Σ (allocation × days × 6 focus hours × type factor) ÷ ${t.hpp} hours per point.</span></div>`},
 onSubmit:v=>{const sp=v.sp||"26.4.2",f=pickFill(v.tm,sp,+v.fill||95,v.ready,1);f.out.forEach(s=>s.sp=sp);R.goals=R.goals||{};if(v.goal)R.goals[v.tm+sp]=v.goal;R.bt=v.tm;audit("planned sprint",tmName(v.tm)+" "+sp+": "+f.out.length+" stories");render();return {toast:f.out.length+" stories added to sprint "+sp}}})}
function assignForm(sid){const s=sOf(sid);const t=tmOf(s.tm);openForm({id:"rel_asg",title:"Claim or assign "+s.id,story:"Work is assigned to the team first. A person claims it, or someone assigns it with a stated reason so the choice is traceable. The assignee's load updates at once.",submit:"Assign",defaults:{who:t.mem[0].n},fields:[{k:"who",label:"Assignee",type:"select",req:true,opts:t.mem.map(m=>[m.n,m.n+" · "+m.role+" ("+KINDS[(who(m.n)||{kind:"human"}).kind]+")"])},{k:"why",label:"Reason (needed when you assign someone else)",type:"text",wide:true,ph:"I know this area, or capacity, or skill match"}],live:v=>{const w=workload(v.who);return `<div class="rel-lv glass"><span class="small">${esc(v.who||"")} is at <b>${w.pct}%</b> load. ${s.pts*2} more hours a week takes them to about <b>${Math.round((w.hrs+s.pts*2+4)/w.cap*100)}%</b>.</span></div>`},onSubmit:v=>{s.as=v.who;audit("assigned story",s.id+" to "+v.who+(v.why?": "+v.why:""));render();return {toast:s.id+" assigned to "+v.who}}})}
function wsjfForm(fid){const f=ftOf(fid),O=["1","2","3","5","8","13","20"];openForm({id:"rel_wsjf",title:"Re-score WSJF: "+f.id,story:"Weighted shortest job first ranks work by cost of delay divided by job size. Score each part relative to the other features on the train, then discuss the outliers.",submit:"Save scores",defaults:{bv:String(f.bv),tc:String(f.tc),rr:String(f.rr),js:String(f.js)},fields:[{k:"bv",label:"Business value",type:"chips",opts:O},{k:"tc",label:"Time criticality",type:"chips",opts:O},{k:"rr",label:"Risk reduction or opportunity enablement",type:"chips",opts:O},{k:"js",label:"Job size",type:"chips",opts:O}],live:v=>{const w=rnd1((+v.bv+ +v.tc+ +v.rr)/(+v.js||1));return `<div class="rel-lv glass"><div class="formula" data-role="metric">WSJF = (${v.bv} + ${v.tc} + ${v.rr}) ÷ ${v.js} = <b>${w}</b></div><span class="small muted">Before: ${wsjf(f)}. Program backlog rank changes if the score crosses a neighbor.</span></div>`},onSubmit:v=>{f.bv=+v.bv;f.tc=+v.tc;f.rr=+v.rr;f.js=+v.js;delete f.rk;audit("re-scored WSJF",f.id+" → "+wsjf(f));render();return {toast:f.id+" WSJF is now "+wsjf(f)}}})}
