function openRec(agId,recId){const a=agId==="__draft"?(SL.dr&&SL.dr.ag):agById(agId);if(!a)return;const rec=poolOf(a.tbl).find(x=>x.id===recId);if(!rec)return;const cal=calOf(a.sch);
 if(a.kind!=="duration"){const items=evalAg(a).items.find(x=>x.id===recId);openDrawer(`<div class="eyebrow">${E(a.id)}</div><h2 style="font-size:26px;margin:6px 0">${E(recId)}</h2><p class="story" data-role="story">${items&&items.score?`Scored ${items.score} of 5.`:"Counted in the result."} ${E(rec.f.service||"")}, ${E(rec.f.priority||"")}. ${rec.cause?"Recorded reason: "+E(tagCause(rec)):""}</p>`);return}
 const log=[];const x=replay(a,rec,cal,log);const names=fd;
 let prev={};const rows=log.map((l,ix)=>{const ch=Object.entries(l.set).filter(e=>["state","priority","assignment_group"].includes(e[0])&&prev[e[0]]!==e[1]);Object.assign(prev,l.set);const what=ix===0?"Opened as "+(l.set.state||"new")+(l.set.priority?", "+l.set.priority:""):ch.map(e=>fieldLabel(a.tbl,e[0])+" to "+e[1]).join(", ")||"Updated";return `<tr><td class="nowrap">${fdt(l.t)}</td><td>${E(what)}</td><td><span class="pill ${l.st==="running"?"info":l.st==="paused"?"warn":l.st==="stopped"?"good":"mute"}">${l.st==="idle"?"Not started":l.st[0].toUpperCase()+l.st.slice(1)}</span> <span class="num small">${l.st==="idle"?"":hrsStr(l.run)}</span>${l.note?`<br><small class="muted">${E(l.note)}</small>`:""}</td></tr>`}).join("");
 openDrawer(`<div class="row" style="gap:8px;flex-wrap:wrap;padding-right:130px">${tPill(a.ty)}<span class="pill ${x&&x.breached?"bad":x&&x.open?"warn":"good"}">${x?x.stage:"Not measured"}</span></div><h2 style="font-size:28px;margin:10px 0 4px">${E(recId)}</h2>
 <p class="story" data-role="story">${x?`The clock ${x.st==="stopped"?"stopped":x.st==="cancelled"?"was cancelled":"is still "+x.st} after <b>${hrsStr(x.run)}</b> of schedule time against a target of <b>${hrsStr(a.target.hours)}</b> (${Math.round(x.pct*100)}%). ${x.breached?"That is "+hrsStr(x.run-a.target.hours)+" over."+(rec.cause?" Reason on record: "+E(tagCause(rec))+".":""):"Inside the target."}`:"The start condition was never met for this record."}</p>
 <dl class="kv"><dt>Agreement</dt><dd><button class="btn quiet" data-sla-open="${E(a.id)}">${E(a.n)}</button></dd><dt>Service</dt><dd>${E(rec.f.service||"")}</dd><dt>Priority</dt><dd>${E(rec.f.priority||"")}</dd><dt>Assignment group</dt><dd>${E(rec.f.assignment_group||"")}</dd><dt>Schedule</dt><dd>${E((SCH.find(s=>s.id===a.sch.cal)||SCH[1]).n)}, ${E(a.sch.tz)}</dd></dl>
 <div class="eyebrow" style="margin-top:14px">Clock history, replayed from the record</div><div class="tscroll"><table><thead><tr><th>When</th><th>What changed</th><th>Clock and elapsed</th></tr></thead><tbody>${rows}</tbody></table></div>
 <p class="muted small">Elapsed counts only hours inside the schedule, and stops counting while the pause condition is true.</p>
 ${x&&x.breached?`<div class="row" style="margin-top:10px"><button class="btn" data-sla-reason="${E(rec.id)}">Record the breach reason</button></div>`:""}`)}

