 const svcMp=mpHTML({id:"sla_dr_svc",label:"Services",opts:SVCREG.map(s=>({v:s.n,l:s.n,sub:s.tier+" · "+s.owner})),all:"All services",onChange:sel=>{const d=dr().ag;d.act.svcs=sel.length===SVCREG.length?[]:sel;dr().dirty=1;rePrev()}});
