 if(t=T.closest("[data-sla-ty]")){const k=t.dataset.slaTy;openList(TYN(k).replace(/^an? /,"").replace(/^./,c=>c.toUpperCase())+"s",TYPEN[k]+"s.",a=>a.ty===k);return}
