 const KB=[
  {id:"KB0101",t:"Reset your password and register multifactor sign-in",sum:"Use the sign-in page's Forgot password link, verify with the Authenticator app, then register a second method.",steps:["Go to the Meridian sign-in page and choose Forgot password","Approve the prompt in Microsoft Authenticator (or enter the 6-digit code)","Choose a new password of 14 or more characters","Add a backup method (phone call or security key) under Security info"],views:2140,up:93,tags:"password reset mfa multifactor authenticator sign in locked"},
  {id:"KB0107",t:"Connect to the VPN from home or on the road",sum:"Open the Meridian VPN client, pick Parker HQ, and sign in with your work account. Split tunnel keeps Teams calls fast.",steps:["Install Meridian VPN from Company Portal","Choose the Parker HQ gateway","Sign in and approve the Authenticator prompt","If it fails twice, run Reset VPN profile from the tray menu"],views:1378,up:88,tags:"vpn remote home connect tunnel"},
  {id:"KB0114",t:"Request access to the Contract Repository",sum:"Access is by role (Reader, Contributor, Admin) and by collection. Your manager and the data owner approve; Admin also needs a security review.",steps:["Open the catalog item Access to the Contract Repository","Pick the role and the collections you need","Your manager and the data owner approve (usually within 1 business day)","Identity adds you to the Entra ID group; sign out and back in"],views:964,up:90,tags:"contract repository access permission role leases vendor contracts"},
  {id:"KB0122",t:"What counts as a standard laptop, and when you can upgrade",sum:"Standard is the 14-inch ultralight. Developer and designer models need a short business justification and budget owner approval.",steps:["Standard laptops are refreshed every 4 years","Choose Developer or Designer if your work needs more memory or graphics","Add a justification; the budget owner approves anything over $2,000"],views:803,up:84,tags:"laptop standard upgrade refresh hardware computer"},
  {id:"KB0131",t:"Book a conference room with hybrid meeting equipment",sum:"Book the room in Outlook, then request AV support if you need recording, livestream or interpreter audio.",steps:["Reserve the room in Outlook (rooms show as resources)","For a Teams Room kit no request is needed","For recording or livestream, request Conference room AV support at least 2 business days ahead"],views:611,up:86,tags:"conference room av audio video hybrid meeting teams room recording livestream"},
  {id:"KB0138",t:"Spot and report a phishing email",sum:"Do not click. Use the Report button in Outlook; Security reviews within 30 minutes during business hours.",steps:["Do not open attachments or links","Select Report, then Phishing in Outlook","If you clicked, change your password and tell the service desk"],views:1790,up:95,tags:"phishing spam scam suspicious email report security"},
  {id:"KB0143",t:"Install software from Company Portal",sum:"Approved titles install without a ticket. Titles that carry a licence cost need a request so asset management can confirm a free licence.",steps:["Open Company Portal on your laptop","Search for the app and select Install","If it says Request, use the Software install catalog item"],views:1022,up:89,tags:"install software company portal app license licence visio acrobat power bi"},
  {id:"KB0150",t:"Teams phone: voicemail, forwarding and call queues",sum:"Set forwarding in Teams under Settings, then Calls. Call queues for Standards Support are managed by the service desk.",steps:["Open Teams, then Settings, then Calls","Choose call forwarding and pick a target","Voicemail greeting is under the same page"],views:455,up:81,tags:"teams phone voicemail forward calls queue"},
  {id:"KB0156",t:"Find lease and contract documents in the Contract Repository",sum:"Search by counterparty, clause or standard reference. Filters for ASC 842 leases and Lumen statements of work are saved in Favorites.",steps:["Open the Contract Repository and use the search box","Use the Collections filter for Leases or Vendor contracts","Save a search to Favorites to reuse it"],views:732,up:79,tags:"find search contract repository lease documents clause asc 842 lumen sow"}];
