 const t0=pl?NOW:r.created;const ends=rows.filter(s=>!P[s.id].sk).map(s=>P[s.id].e);const tEnd=Math.max(...ends,NOW+HR);const span=Math.max(tEnd-t0,HR);const x=t=>clamp((t-t0)/span*100,0,100);
 const ticks=[];const unit=span>10*DAY?DAY*2:span>3*DAY?DAY:6*HR;for(let t=0;t<=span;t+=unit)ticks.push(t);
