 d.ftime=Math.round(med(d.cyc)*10)/10;d.cpr=d.pc.length?Math.round(sum(d.pc)/d.pc.length):0;d.xlaAvg=d.xla.length?Math.round(sum(d.xla)/d.xla.length*100)/100:0;d.ontime=pc(d.onT,d.dep30);d.ftaRate=pc(d.fta,d.apDec);
