/* natural language: pick the best item and fill the form */
function bestItem(q){const l=" "+String(q).toLowerCase()+" ";const sc=pubItems().map(c=>{let s=0;(c.kw||[]).forEach(([re])=>{if(re.test(l))s+=1});String(c.n+" "+c.short+" "+c.cat).toLowerCase().split(/\W+/).filter(w=>w.length>3).forEach(w=>{if(l.includes(w))s+=.6});if(c.id==="laptop"&&/laptop|computer|notebook/.test(l))s+=3;if(c.id==="onboarding"&&/hire|onboard|join|start(s|ing)? (on|next)/.test(l))s+=3;if(c.id==="access"&&/access|permission/.test(l))s+=2;if(c.id==="software"&&/install|software|licen[cs]e/.test(l))s+=2;if(c.id==="av"&&/room|boardroom|hybrid|recording|av\b/.test(l))s+=2;if(c.id==="project"&&/project|initiative/.test(l))s+=2;return {c,s}}).sort((a,b)=>b.s-a.s);return sc[0]&&sc[0].s>=1?sc[0].c:null}
