const AST_P={Ordered:"info",Received:"info","In stock":"mute",Deployed:"good","In repair":"warn",Retired:"mute",Decommissioned:"mute"};
const astPill=s=>`<span class="pill ${AST_P[s]}">${s}</span>`;
