function astAgg(){if(ASC.d&&ASC.n===ASSETS.length&&ASC.v===REQV&&ASC.sc===SCALE.on)return ASC.d;const d={n:ASSETS.length,st:Object.fromEntries(AST_ST.map(s=>[s,0])),cls:{},war:0,warOld:0,intuneBad:0,intuneN:0,value:0,age:[0,0,0,0]};
 ASSETS.forEach(a=>{d.st[a.st]++;(d.cls[a.cls]=d.cls[a.cls]||{n:0,dep:0,stock:0})[a.st==="Deployed"?"dep":a.st==="In stock"?"stock":"n"]++;d.cls[a.cls].n+=a.st==="Deployed"||a.st==="In stock"?0:0;if(a.st==="Deployed"||a.st==="In stock"||a.st==="In repair"){d.value+=a.cost;if(a.war<NOW)d.warOld++;else if(a.war<NOW+90*DAY)d.war++;const y=(NOW-a.bought)/DAY/365;d.age[y<1?0:y<2?1:y<3?2:3]++}
  if(a.intune!==null&&a.st==="Deployed"){d.intuneN++;if(!a.intune)d.intuneBad++}});
 d.acc=d.intuneN?Math.round((1-d.intuneBad/d.intuneN)*1000)/10:100;ASC={v:REQV,n:ASSETS.length,sc:SCALE.on,d};const m=METRICS.m_astacc;if(m){m.cur=d.acc;m.tr=m.tr.slice(0,7).concat(d.acc)}return d}
