function astNewForm(){openForm({id:"svc_an",title:"Add an asset",story:"Use this for devices bought outside the catalog. Devices ordered through a request are added automatically.",submit:"Add asset",fields:[{k:"cls",label:"Class",type:"chips",opts:Object.keys(AMOD),req:true},{k:"model",label:"Model",type:"text",req:true},{k:"cost",label:"Cost",type:"money",req:true},{k:"bought",label:"Purchase date",type:"date",req:true},{k:"st",label:"State",type:"select",opts:AST_ST},{k:"who",label:"Assigned to",type:"people",show:v=>v.st==="Deployed"},{k:"loc",label:"Location",type:"text"}],defaults:{cls:"Laptop",st:"In stock",bought:iso(NOW),loc:"Parker HQ stockroom"},
  live:v=>{const mm=(AMOD[v.cls]||[]).map(x=>x[0]);return `<div class="svc-lint"><p class="muted small">Common ${E(v.cls||"")} models: ${E(mm.join(", "))}. Warranty is set to ${WAR_Y[v.cls]||3} years from purchase.</p></div>`},
  onSubmit:v=>{const a=mkAsset({id:"MSF-"+(AST_SEQ++),cls:v.cls,model:v.model,st:v.st,who:v.st==="Deployed"?v.who:"",cost:+v.cost,bought:v.bought,loc:v.loc||"Parker HQ"});ASSETS.unshift(a);REQV++;render();return{toast:a.id+" added",audit:a.id}}})}
function openLic(id){const l0=LICB.find(x=>x.id===id);if(!l0)return;const l=lv(l0),s=lstat(l);const r=RNG("lic"+id+(SCALE.on?"s":"d")),P=poolPeople();const rows=[];for(let i=0;i<l.asg;i++){const p=P[Math.floor(r()*P.length)];rows.push({id:id+"-"+i,who:p.name,last:Math.floor(r()*r()*160),since:NOW-Math.floor(r()*900)*DAY})}
 openDrawer(`<div class="row"><span class="pill ${s[1]}">${s[0]}</span><span class="pill mute">${E(l.v)}</span></div><h2>${E(l.n)}</h2><div class="statrow">${[["Entitled",N(l.ent),l.m],["Assigned",N(l.asg),pc(l.asg,l.ent)+"% used"],["Unused 90 days",N(l.un),"reclaimable"],["Exposure",money(expo(l)),"at "+money(l.price)+" each"]].map(x=>`<div class="stat"><small>${x[0]}</small><span class="num">${x[1]}</span><em>${x[2]}</em></div>`).join("")}</div><dl class="kv"><dt>Renews</dt><dd>${fdy(l.renew)}</dd><dt>Owner</dt><dd>${wh(l.own)}</dd><dt>Lifecycle</dt><dd>${E(l.life)}</dd></dl>
 ${btHTML({id:"svc_licasg_"+id,cols:[{k:"who",label:"Assigned to",fmt:x=>wh(x.who),val:x=>x.who},{k:"last",label:"Days since last use",fmt:x=>`<span class="pill ${x.last>90?"warn":"mute"}">${x.last}</span>`,val:x=>x.last,cls:"num"},{k:"since",label:"Since",fmt:x=>fd(x.since),val:x=>x.since}],rows:()=>rows,key:"id",h:320,rowH:44,exportName:"license_"+id})}
 <div class="row"><button class="btn primary" data-svc="reclaim|${id}">Reclaim unused seats</button></div>`)}
function reclaimForm(id){const L=licAgg().L.filter(l=>l.un>0);if(!L.length){toast("No unused seats to reclaim","info");return}const l0=id&&L.find(l=>l.id===id)||L[0];
 openForm({id:"svc_rc",title:"Reclaim unused seats",story:"Seats with no sign-in for 90 days go back to the pool. People are told one week before and can ask to keep theirs.",submit:"Reclaim",fields:[{k:"lic",label:"Title",type:"select",opts:L.map(l=>[l.id,l.n+" ("+l.un+" unused)"]),req:true},{k:"q",label:"Seats to reclaim",type:"number",req:true}],defaults:{lic:l0.id,q:l0.un},
  live:v=>{const l=L.find(x=>x.id===v.lic);if(!l)return"";const q=Math.min(+v.q||0,l.un);return `<div class="svc-lint"><div class="row"><span class="pill metric">${money(q*l.price)} a year avoided</span><span class="pill info">${l.asg} to ${l.asg-q} assigned of ${l.ent}</span>${+v.q>l.un?`<span class="pill warn">Only ${l.un} are unused</span>`:""}</div></div>`},
  onSubmit:v=>{const l=L.find(x=>x.id===v.lic),b=LICB.find(x=>x.id===v.lic),q=Math.min(+v.q||0,l.un);if(q<1)return{toast:"Choose at least one seat",close:false};const k=LF();b.asg=Math.max(0,b.asg-Math.ceil(q/k));b.un=Math.max(0,b.un-Math.ceil(q/k));RECL.unshift({n:l.n,q,price:l.price,at:NOW,by:ME});REQV++;render();return{toast:q+" "+l.n+" seats reclaimed",audit:l.n+" "+q}}})}
