  for(let i=0;i<n;i++){const e=EVT[Math.floor(r()*EVT.length)],ch=CHN[Math.floor(r()*CHN.length)][0],x=r(),st=x<.84?"Delivered":x<.87?"Failed":x<.96?"Suppressed":"Deferred",ts=NOW-Math.floor(r()*24*60)*60000;rows.push({id:"G"+(1000+i),ts,t:pad(new Date(ts).getUTCHours())+":"+pad(new Date(ts).getUTCMinutes()),ev:e.id,who:P[Math.floor(r()*P.length)].name,ch,st,why:st==="Delivered"?"":why[st][Math.floor(r()*why[st].length)],perm:st==="Failed"&&r()<.3})}
