SV.off=SV.off||[];
const people=()=>DIR.filter(d=>d.kind==="human"&&!d.generated);
function mkOff(s,n,i){const r=RNG(s.id+n),base=Math.max(4,Math.round(Math.sqrt(s.users)));const u=UNITS[n]||["per user per month",+(s.cost/Math.max(1,s.users)/Math.max(1,s.offerings.length)).toFixed(2)];
 const subs=SUBS[n]||["Standard","Extended"];const pend=1+Math.floor(r()*base*.35),appr=2+Math.floor(r()*base*.3),dep=Math.round(Math.min(s.users,s.users*(.25+r()*.6))),dec=1+Math.floor(r()*base*.2);
 const ppl=people();const states=["Awaiting approval","Approved","Deployed","Decommissioned"];
 const recent=Array.from({length:6},(_,k)=>{const st=states[Math.floor(r()*4)];return{id:"RITM00"+(11200+Math.floor(r()*800)),sub:subs[Math.floor(r()*subs.length)],by:ppl[Math.floor(r()*ppl.length)].name,st,date:"Oct "+(1+Math.floor(r()*6)),cost:Math.round(u[1]*(1+r()*3))}});
 const price=u[1];const rules=[];if(price>=400)rules.push(["Cost per request is $400 or more","Budget owner approves"]);if(/Privileged|API|Standards API|licens/i.test(n))rules.push(["Grants privileged or licensed access","Security and service owner approve"]);rules.push(["Requester is a manager or above","Manager approval skipped"]);rules.push(["Decommission request","Service owner confirms and licenses are reclaimed"]);
 return{id:"off_"+s.id+"_"+i,svc:s.id,n,subs,unit:u[0],price,sla:[8,24,40,72,120][Math.floor(r()*5)],req:{pending:pend,approved:appr,deployed:dep,decommissioned:dec},recent,rules,cat:slug(n),life:"Live"}}
function offerings(svc){SVCREG.forEach(s=>{if(!SV.off.some(o=>o.svc===s.id))s.offerings.forEach((n,i)=>SV.off.push(mkOff(s,n,i)))});return svc?SV.off.filter(o=>o.svc===svc):SV.off}
SV.offerings=offerings;
const offCost=o=>{if(window.TBMX&&TBMX.offering){try{const x=TBMX.offering(o.id);if(x)return x}catch(e){}}return{unit:o.unit,cost:o.price,volume:o.req.deployed,monthly:Math.round(o.price*o.req.deployed/12)}};

