/* ================= stats per service ================= */
function stats(s){const r=recsFor([s.id]);const created=SV.created.filter(c=>c.svc===s.id).length;const reqs=offerings(s.id).reduce((a,o)=>a+o.req.pending,0);const degCI=svcCIs(s.id).filter(c=>c.status!=="Operational").length;const gap=+(s.avail-s.tgt).toFixed(2);
 const st=gap>=0?"good":gap>-.2?"warn":"bad";const major=r.inc.some(i=>+i.imp===1);return{inc:r.inc.length+created,chg:r.chg.length,reqs,degCI,gap,st,major,atRisk:gap<0||degCI>0||major,r}}
const mapScore=s=>{let n=0;if(svcCIs(s.id).length)n++;if(s.obj.length)n++;if(rels(s.id).length)n++;if(stake(s.id).length>2)n++;n++;n++;n++;return n};
const tierPill=t=>`<span class="pill ${t==="Tier 1"?"bad":t==="Tier 2"?"warn":"mute"}">${t}</span>`;
const stat=(l,v,sub,cls)=>`<div class="stat ${cls||""}"><small>${l}</small><span class="num" data-role="metric">${v}</span><em>${sub||""}</em></div>`;
const statrow=a=>`<div class="statrow">${a.join("")}</div>`;
const MATN=["Initial","Managed","Defined","Measured","Optimizing"];

/* mini-map used inside screens (click opens full impact analysis) */
function miniMap(focus,dir,depth,fails){const m=drawMap({focus,dir,depth,fails:fails||[],exp:{},cap:{0:5,1:5,2:5,3:6}});return `<div class="svx-map svx-mini" data-s360-minimap="${focus}">${m.svg.replace(/data-imp-node=/g,"data-s360-node=")}</div><p class="small muted">${m.n} boxes${m.hidden?`, ${m.hidden} collapsed`:""}. Click a box to open the full impact analysis centered there.</p>`}

