function dash(){const A=SVCREG.map(s=>({s,x:stats(s)}));const t1=A.filter(a=>a.s.tier==="Tier 1");const below=A.filter(a=>a.x.gap<0);const cost=SVCREG.reduce((a,s)=>a+s.cost,0);const mat=SVCREG.reduce((a,s)=>a+s.maturity,0)/SVCREG.length;
 const inc=A.reduce((a,b)=>a+b.x.inc,0),chg=A.reduce((a,b)=>a+b.x.chg,0),req=A.reduce((a,b)=>a+b.x.reqs,0),risk=A.filter(a=>a.x.atRisk);
 const t1avg=t1.reduce((a,b)=>a+b.s.avail*b.s.users,0)/t1.reduce((a,b)=>a+b.s.users,0);METRICS.m_svc_avail.cur=+t1avg.toFixed(2);
 const sorted=A.slice().sort((a,b)=>a.x.gap-b.x.gap);const lo=98.8;const pos=v=>Math.max(0,Math.min(100,(v-lo)/(100-lo)*100));
 const bul=sorted.map(a=>`<div class="svx-bul"><button type="button" class="linkb" data-s360-open="${a.s.id}"><b>${H(a.s.n)}</b></button><div class="svx-bt" title="Availability ${a.s.avail}% against target ${a.s.tgt}%"><i style="width:${pos(a.s.avail)}%;background:var(${a.x.st==="good"?"--good-f":a.x.st==="warn"?"--warn-f":"--bad-f"})"></i><u style="left:${pos(a.s.tgt)}%"></u></div><span class="num small">${a.s.avail}%</span></div>`).join("");
 const maxC=Math.max(...SVCREG.map(s=>s.cost));const costBars=SVCREG.slice().sort((a,b)=>b.cost-a.cost).slice(0,8).map(s=>`<div class="svx-bul"><button type="button" class="linkb" data-s360-open="${s.id}"><b>${H(s.n)}</b></button><div class="svx-bt"><i style="width:${s.cost/maxC*100}%;background:var(--p4)"></i></div><span class="num small">${D$(s.cost)}</span></div>`).join("");
 const tiers=["Tier 1","Tier 2","Tier 3"].map(t=>{const biz=SVCREG.filter(s=>s.tier===t&&layerOf(s.id)===2).length,tech=SVCREG.filter(s=>s.tier===t&&layerOf(s.id)===1).length;return`<div class="svx-col"><div class="svx-stack"><i style="height:${biz*16}px;background:var(--p4)" title="${biz} business services"></i><i style="height:${tech*16}px;background:var(--u3)" title="${tech} technology services"></i></div><b>${t}</b><small class="muted">${biz+tech}</small></div>`}).join("");
 const mats=[1,2,3,4,5].map(l=>{const n=SVCREG.filter(s=>s.maturity===l).length;return`<div class="svx-col"><div class="svx-stack"><i style="height:${n*16}px;background:var(--w1)" title="${n} services"></i></div><b>${l}</b><small class="muted">${MATN[l-1]}</small></div>`}).join("");
 return `${statrow([stat("Services",SVCREG.length,t1.length+" Tier 1, "+(SVCREG.length-t1.length)+" others"),stat("Below target",below.length,"of "+SVCREG.length+" availability targets",below.length?"crit":""),stat("Tier 1 availability",METRICS.m_svc_avail.cur+"%","target "+METRICS.m_svc_avail.tgt+"% "),stat("Run cost a month",D$(cost),"all services"),stat("Average maturity",mat.toFixed(1),"of 5"),stat("Open incidents",inc,"on mapped services",inc?"crit":""),stat("Open changes",chg,"planned or underway"),stat("Pending requests",req,"waiting on approval or fulfillment")])}
 <div class="grid g2" style="align-items:start">${card("Availability against target","Bar is this month's availability, the line is the target. Red means below target.",bul+legend([["Meets target","--good-f"],["Within 0.2 points","--warn-f"],["Below target","--bad-f"]]),fchip("m_svc_avail"))}
 <div class="grid" style="gap:18px">${card("Needs attention",risk.length+" of "+SVCREG.length+" services are at risk",risk.length?risk.slice(0,5).map(a=>`<div class="svx-r"><span class="pill ${a.x.st==="good"?"warn":a.x.st}">${a.x.gap<0?a.x.gap.toFixed(2)+" pts":a.x.major?"Major incident":"Degraded CI"}</span><button type="button" class="linkb" data-s360-open="${a.s.id}"><b>${H(a.s.n)}</b></button><button class="btn quiet" data-s360-imp="${a.s.id}">Impact</button></div>`).join(""):'<p class="muted">Every service meets target.</p>',"")}
 ${card("Services by tier","Business services in teal, technology services in purple.",`<div class="svx-cols">${tiers}</div>${legend([["Business services","--p4"],["Technology services","--u3"]])}`,"")}</div>
 ${card("Run cost by service","Monthly cost. The Cost transparency screen shows where each dollar comes from.",costBars,`<button class="btn quiet" data-s360-tbm>Cost transparency</button>`)}
 ${card("Maturity","Count of services at each level, from Initial (1) to Optimizing (5).",`<div class="svx-cols">${mats}</div>`,stdChip("cmmi","Maturity levels 1 to 5 follow the CMMI scale; the Maturity models screen scores the dimensions."))}</div>`}
function listTable(){const rows=()=>SVCREG.map(s=>{const x=stats(s);return{id:s.id,n:s.n,tier:s.tier,layer:layerOf(s.id)===1?"Technology":"Business",owner:s.owner,avail:s.avail,tgt:s.tgt,gap:x.gap,users:s.users,cost:s.cost,mat:s.maturity,inc:x.inc,chg:x.chg,off:s.offerings.length,st:x.st}});
 return btHTML({id:"s360list",rows,key:"id",h:440,rowH:44,facets:["tier","layer"],groupBy:["tier","layer","owner"],exportName:"services",open:id=>{S.svc360.sel=id;S.v.s360d=0;render()},cols:[{k:"n",label:"Service",fmt:r=>`<b>${H(r.n)}</b>`},{k:"tier",label:"Tier",fmt:r=>tierPill(r.tier)},{k:"layer",label:"Layer"},{k:"owner",label:"Owner"},{k:"avail",label:"Availability",fmt:r=>`<span class="num">${r.avail}%</span>`},{k:"gap",label:"Against target",fmt:r=>`<span class="pill ${r.st}">${r.gap>=0?"+":""}${r.gap.toFixed(2)} pts</span>`},{k:"users",label:"Users",fmt:r=>`<span class="num">${N(r.users)}</span>`},{k:"cost",label:"Cost a month",fmt:r=>`<span class="num">${D$(r.cost)}</span>`},{k:"mat",label:"Maturity",fmt:r=>`${r.mat} · ${MATN[r.mat-1]}`},{k:"inc",label:"Incidents"},{k:"chg",label:"Changes"},{k:"off",label:"Offerings"}]})}

