 fs.forEach((f,i)=>{s+=`<line x1="${X(i)}" x2="${X(i)}" y1="${T}" y2="${T+ph}" stroke="var(--muted)" stroke-width="1.5"${C.mk([f.label,"Range "+fnum(ex[i][0])+" to "+fnum(ex[i][1])])}/>`+(C.thumb?"":`<text class="ax" x="${X(i)}" y="${T-12}" text-anchor="middle" style="font-weight:700">${E(C.trunc(f.label,16))}</text><text class="ax" x="${X(i)}" y="${T-1}" text-anchor="middle">${E(fnum(ex[i][1]))}</text><text class="ax" x="${X(i)}" y="${T+ph+12}" text-anchor="middle">${E(fnum(ex[i][0]))}</text>`)});
