function vennFam(C){const en=C.spec.enc;if(!en.x||!en.color)throw new Error("Pick X (the items) and Color (the sets they belong to).");const sets=new Map();C.rows.forEach(r=>{const c=String(r[en.color]),k=String(r[en.x]);let a=sets.get(c);if(!a)sets.set(c,a=new Set());a.add(k)});const top=[...sets.entries()].sort((a,b)=>b[1].size-a[1].size).slice(0,3);if(top.length<2)throw new Error("Needs at least two sets in Color.");const inter=(a,b)=>[...a].filter(x=>b.has(x));const R0=Math.min(C.W*.24,C.H*.34),cx=C.W/2,cy=C.H/2+(top.length===3?6:0),d=R0*1.05,pos=top.length===2?[[cx-d*.55,cy],[cx+d*.55,cy]]:[[cx-d*.55,cy-d*.32],[cx+d*.55,cy-d*.32],[cx,cy+d*.62]];let s="";
 top.forEach((t,i)=>{s+=`<circle class="vz-m" cx="${r1(pos[i][0])}" cy="${r1(pos[i][1])}" r="${r1(R0)}" fill="${C.col(i)}" fill-opacity=".34" stroke="${C.col(i)}" stroke-width="2"${C.mk([t[0],t[1].size+" distinct "+C.F(en.x).label.toLowerCase()],[en.color,t[0]])}/>`+(C.thumb?"":`<text class="ax" x="${r1(pos[i][0]+(i===0?-R0*.55:i===1?R0*.55:0))}" y="${r1(pos[i][1]+(i===2?R0*.9:-R0-6)+(i===2?10:0))}" text-anchor="middle" style="font-weight:700;fill:var(--ink)">${E(C.trunc(t[0],18))} (${t[1].size})</text>`)});
 const lab=(x,y,n,t)=>C.thumb?"":`<text class="vz-big" x="${r1(x)}" y="${r1(y)}" text-anchor="middle" font-size="${n>99?15:18}"${C.mk(t)}>${n}</text>`;const ab=inter(top[0][1],top[1][1]);if(top.length===2){lab(cx,cy+5,ab.length,[top[0][0]+" and "+top[1][0],ab.length+" shared"]);s+=lab(cx,cy+5,ab.length,[top[0][0]+" and "+top[1][0],ab.length+" shared"]);s+=lab(pos[0][0]-R0*.5,cy+5,top[0][1].size-ab.length,["Only "+top[0][0]]);s+=lab(pos[1][0]+R0*.5,cy+5,top[1][1].size-ab.length,["Only "+top[1][0]])}
 else{const abc=inter(new Set(ab),top[2][1]).length,ac=inter(top[0][1],top[2][1]).length,bc=inter(top[1][1],top[2][1]).length;s+=lab(cx,cy-d*.05,abc,["All three sets",abc+" items"])+lab(cx,cy-d*.75,ab.length-abc,[top[0][0]+" and "+top[1][0]+" only"])+lab(cx-d*.78,cy+d*.45,ac-abc,[top[0][0]+" and "+top[2][0]+" only"])+lab(cx+d*.78,cy+d*.45,bc-abc,[top[1][0]+" and "+top[2][0]+" only"])+lab(pos[0][0]-R0*.5,pos[0][1]-R0*.2,top[0][1].size-ab.length-ac+abc,["Only "+top[0][0]])+lab(pos[1][0]+R0*.5,pos[1][1]-R0*.2,top[1][1].size-ab.length-bc+abc,["Only "+top[1][0]])+lab(cx,pos[2][1]+R0*.55,top[2][1].size-ac-bc+abc,["Only "+top[2][0]])}
 C.legend=[];C.desc+="Overlap of "+top.length+" sets, counting distinct "+C.F(en.x).label.toLowerCase()+".";C.table=tbl(["Set","Distinct items"],top.map(t=>[t[0],String(t[1].size)]),C);return C.svg(s)}
