 nodes.forEach((p,n)=>{s+=`<circle cx="${r1(p[0])}" cy="${r1(p[1])}" r="${C.thumb?2.4:4.5}" fill="var(--ink)" stroke="var(--bg)" stroke-width="1.5"/>`+(C.thumb?"":`<text class="ax vz-ml" x="${r1(p[0]+7)}" y="${r1(p[1]+3)}">${E(C.trunc(n,18))}</text>`)});
