const ZONES=[["Reception",10,10,150,100],["Open plan",160,10,270,150],["Editors bay",440,10,230,150],["Server closet",10,180,150,80],["Conference",160,180,310,80],["Kitchen",480,180,190,80]];
function floorBase(C,k,heat){const sx=C.W/680;return ZONES.map(z=>`<rect x="${r1(z[1]*sx)}" y="${r1(z[2]*sx)}" width="${r1(z[3]*sx)}" height="${r1(z[4]*sx)}" rx="${C.thumb?3:8}" fill="var(--glass2)" stroke="var(--hair)" stroke-width="1.6"/>`+(C.thumb?"":`<text class="ax" x="${r1((z[1]+8)*sx)}" y="${r1((z[2]+16)*sx)}" style="font-weight:700">${z[0]}</text>`)).join("")}
function floorMap(C,heat){const rows=C.rows;if(!C.F("x")||!C.F("y"))throw new Error("Needs the Office floor plan devices source.");const sx=C.W/680,H=Math.round(C.W*270/680);let s=floorBase(C,0,heat);const yk=heat&&C.spec.enc.y&&C.F(C.spec.enc.y)&&C.F(C.spec.enc.y).t==="n"?C.spec.enc.y:"temp";
 if(heat){const vs=rows.map(r=>+r[yk]),mn=Math.min(...vs),mx=Math.max(...vs);let defs="",blobs="";rows.forEach((r,i)=>{const t=(r[yk]-mn)/((mx-mn)||1);defs+=`<radialGradient id="vzh${KID}_${i}"><stop offset="0" stop-color="${C.seq(Math.min(1,t*1.1))}" stop-opacity=".95"/><stop offset="1" stop-color="${C.seq(t)}" stop-opacity="0"/></radialGradient>`;blobs+=`<circle cx="${r1(r.x*sx)}" cy="${r1(r.y*sx)}" r="${r1((38+t*30)*sx)}" fill="url(#vzh${KID}_${i})"/>`});s=`<defs>${defs}</defs>`+s+blobs;rows.forEach(r=>{s+=`<circle class="vz-m" cx="${r1(r.x*sx)}" cy="${r1(r.y*sx)}" r="${C.thumb?2.5:5}" fill="var(--ink)" stroke="var(--bg)" stroke-width="1.5"${C.mk([r.asset+" · "+r.zone,C.F(yk).label+": "+r[yk]+(yk==="temp"?" °F":""),"Status: "+r.status],["zone",r.zone])}/>`});C.legend=[];C.desc+="Heat overlay of "+C.F(yk).label+" on the floor plan; hottest "+fnum(mx)+", coolest "+fnum(mn)+".";C.table=tbl(["Asset","Zone",C.F(yk).label],rows.map(r=>[r.asset,r.zone,String(r[yk])]),C);return {html:C.svg(s,"",H),ramp:[fnum(mn),fnum(mx)]}}
 const SH={Desk:(x,y,c)=>`<rect x="${x-6}" y="${y-5}" width="12" height="10" rx="2" fill="${c}"/>`,"Access point":(x,y,c)=>`<circle cx="${x}" cy="${y}" r="6" fill="${c}"/><circle cx="${x}" cy="${y}" r="10" fill="none" stroke="${c}" stroke-opacity=".5"/>`,Sensor:(x,y,c)=>`<path d="M${x} ${y-7}L${x+7} ${y+6}H${x-7}Z" fill="${c}"/>`,Printer:(x,y,c)=>`<rect x="${x-7}" y="${y-4}" width="14" height="9" rx="2" fill="${c}"/><rect x="${x-4}" y="${y-8}" width="8" height="5" fill="${c}"/>`,Switch:(x,y,c)=>`<rect x="${x-9}" y="${y-4}" width="18" height="8" rx="2" fill="${c}"/>`,Display:(x,y,c)=>`<rect x="${x-9}" y="${y-6}" width="18" height="11" rx="2" fill="${c}"/>`};
 rows.forEach(r=>{const x=r.x*sx,y=r.y*sx,c=STCOL[r.status]||"var(--faint)";s+=`<g class="vz-m" transform="scale(1)"${C.mk([r.asset+" · "+r.zone,"Status: "+r.status,"Temperature "+r.temp+" °F · load "+r.load+"%"],["zone",r.zone])}>${(SH[r.kind]||SH.Desk)(r1(x),r1(y),c)}</g>`});
 C.legend=["Healthy","Warning","Down"].map(k=>[k,STCOL[k]]);C.desc+=rows.length+" devices on the floor plan.";C.table=tbl(["Asset","Zone","Status"],rows.map(r=>[r.asset,r.zone,r.status]),C);return C.svg(s,"",H)}
