/* map interactions: zoom buttons, wheel, drag, cluster click */
function zoomBy(m,f,cx,cy){const z=m.zoom||(m.zoom={k:1,x:0,y:0}),nk=clamp(z.k*f,1,24);f=nk/z.k;z.x=cx-(cx-z.x)*f;z.y=cy-(cy-z.y)*f;z.k=nk;if(nk===1){z.x=0;z.y=0}}
function redrawMap(id){const m=MNT[id];if(!m)return;cancelAnimationFrame(m.mraf);m.mraf=requestAnimationFrame(()=>draw(id))}
document.addEventListener("click",e=>{let t;if(t=e.target.closest("[data-viz-zm]")){const [id,op]=t.dataset.vizZm.split(":"),m=MNT[id];if(!m)return;const W=m.el.clientWidth,H=W*.5;if(op==="reset")m.zoom={k:1,x:0,y:0};else zoomBy(m,op==="in"?1.7:1/1.7,W/2,H/2);redrawMap(id);return}
 if(t=e.target.closest("[data-viz-zt]")){const svg=t.closest("svg"),id=svg&&svg.dataset.vzmap,m=MNT[id];if(!m)return;const [x,y]=t.dataset.vizZt.split(",").map(Number);zoomBy(m,2.2,x,y);const W=m.el.clientWidth;const z=m.zoom;z.x+=W/2-x;z.y+=W*.26-y;redrawMap(id)}});
document.addEventListener("wheel",e=>{const svg=e.target.closest&&e.target.closest("svg.vz-map");if(!svg||!svg.dataset.vzmap||svg.closest(".vz-thumb"))return;const m=MNT[svg.dataset.vzmap];if(!m||!e.ctrlKey&&!e.shiftKey&&!m.o.wheel)return;e.preventDefault();const b=svg.getBoundingClientRect();zoomBy(m,e.deltaY<0?1.25:.8,(e.clientX-b.left)*(m.el.clientWidth/b.width),(e.clientY-b.top)*(m.el.clientWidth/b.width));redrawMap(svg.dataset.vzmap)},{passive:false});
let DRAG=null;document.addEventListener("pointerdown",e=>{const svg=e.target.closest&&e.target.closest("svg.vz-map");if(!svg||!svg.dataset.vzmap||svg.closest(".vz-thumb")||e.target.closest("[data-tt]"))return;const m=MNT[svg.dataset.vzmap];if(!m||!m.zoom||m.zoom.k<=1)return;DRAG={m,id:svg.dataset.vzmap,x:e.clientX,y:e.clientY,z:Object.assign({},m.zoom),k:m.el.clientWidth/svg.getBoundingClientRect().width};svg.setPointerCapture&&svg.setPointerCapture(e.pointerId)});
document.addEventListener("pointermove",e=>{if(!DRAG)return;DRAG.m.zoom.x=DRAG.z.x+(e.clientX-DRAG.x)*DRAG.k;DRAG.m.zoom.y=DRAG.z.y+(e.clientY-DRAG.y)*DRAG.k;redrawMap(DRAG.id)});document.addEventListener("pointerup",()=>{DRAG=null});
