   const ref=m[1].trim(),id=byCode.get(ref)||(TASK(ref)?ref:null);if(!id){const sm=wbsOutline(pid).find(x=>x.sum&&x.wbs===ref);return {ok:0,why:sm?"WBS "+ref+" is a summary line. Links connect tasks and milestones.":"No task with WBS code \""+ref+"\" in this project."}}
