document.addEventListener("click",e=>{const t=e.target.closest("[data-nav],[data-go],[data-needgo],[data-rec],[data-rec-pick],[data-trace],[data-impact],[data-step],[data-sort],[data-invpick],[data-decide],[data-saverules],[data-meet],[data-fo],[data-fo-level],[data-scope],[data-restore],[data-quick],[data-autolvl],[data-lin],[data-ctok],[data-mf],[data-runrem],[data-newmetric],[data-trend],[data-unused],[data-kgscen],[data-kgn],[data-linkfile],[data-mktasks],[data-draft],[data-ask],[data-sr],[data-chatact],#arm,#pause,#fire,#cancel");if(!t)return;const d=t.dataset;
 if(d.nav)return go(d.nav);if(d.go){const [a,b]=d.go.split(":");return go(a,b)}if(d.needgo){const [a,b]=d.needgo.split("|");return go(a,b)}
 if(d.rec){closeDrawer();return recDrawer(d.rec)}if(d.recPick){S.rec=d.recPick;S.flowSel=null;return render()}if(d.trace)return go("trace",d.trace);if(d.impact){S.v.kg=1;return go("kg",d.impact)}
 if(d.step)return stepDrawer(d.step);if(d.sort){S.sort={k:d.sort,d:S.sort.k===d.sort?-S.sort.d:1};return render()}
 if(d.invpick){S.inv=d.invpick;return render()}
 if(d.decide){const i=INV();if(d.decide==="__undo"){delete S.dec[i.id];audit("undid decision",i.id)}else{S.dec[i.id]=d.decide;const w=($("#why")||{}).value;audit(d.decide.toLowerCase()+" invoice",i.id+(w?" · "+w:""));if(({Approved:"approve","On hold":"hold",Rejected:"reject"})[d.decide]!==i.rec){METRICS.m_override.cur=Math.min(40,METRICS.m_override.cur+1)}}return render()}
 if(d.saverules!=null){const B=backtest();METRICS.m_auto.cur=Math.round(B.a/B.n*100);audit("saved auto-approval rules",B.a+" of "+B.n+" would clear");return render()}
 if(d.meet)return meetingDrawer(d.meet);if(d.fo){const [id,v]=d.fo.split(":");S.fo[id]=v;audit(v==="ok"?"filed record":"dismissed record",id);return render()}if(d.foLevel!=null){S.foLevel=+d.foLevel;audit("set First Officer autonomy",AUTO_LEVELS[+d.foLevel]);return render()}
 if(d.scope){S.ct.scope=d.scope;S.ct.armed=false;S.ct.target=ctTargets()[0][0];return render()}
 if(t.id==="arm"){if(!S.ct.reason.trim()){$("#rsn").focus();$("#rsn").placeholder="A reason is required";return}S.ct.armed=true;return render()}if(t.id==="cancel"){S.ct.armed=false;return render()}
 if(t.id==="pause"||t.id==="fire"){const r=S.ct.reason.trim();if(!r){$("#rsn").focus();$("#rsn").placeholder="A reason is required";return}const b=blast();b.hit.forEach(a=>a.st=t.id==="fire"?"killed":"paused");S.ct.log.unshift([new Date().toLocaleTimeString("en-US",{hour:"2-digit",minute:"2-digit"}),(t.id==="fire"?"Stopped ":"Paused ")+SCOPES.find(s=>s[0]===S.ct.scope)[1].toLowerCase()+" ("+S.ct.target+"): "+b.hit.map(a=>a.n).join(", ")+" · "+r]);audit(t.id==="fire"?"kill switch":"paused agents",S.ct.scope+":"+S.ct.target+" · "+r);S.ct.armed=false;S.ct.reason="";return render()}
 if(d.restore){const a=S.agents.find(x=>x.id===d.restore);a.st="running";audit("restored agent",a.n);return render()}if(d.quick){const a=S.agents.find(x=>x.id===d.quick);a.st="paused";S.ct.log.unshift([new Date().toLocaleTimeString("en-US",{hour:"2-digit",minute:"2-digit"}),"Paused "+a.n+" from the fleet view"]);audit("paused agent",a.n);return render()}
 if(d.autolvl){const [id,l]=d.autolvl.split(":");const a=S.agents.find(x=>x.id===id);a.auto=+l;audit("set agent autonomy",a.n+" → "+AUTO_LEVELS[+l]);return render()}
 if(d.lin){S.ct.lin=d.lin;S.v.tower=2;return render()}if(d.ctok){const [i,v]=d.ctok.split(":");audit(v+" agent request","item "+i);t.closest(".need").style.opacity=".4";t.closest(".need").querySelectorAll("button").forEach(b=>b.disabled=true);return}
 if(d.mf){S.metricFilter=d.mf;return render()}if(d.runrem){const m=METRICS[d.runrem];m.rem.state="running";audit("ran remediation",m.rem.ref);t.textContent="Started";t.disabled=true;return}
 if(d.newmetric!=null){const n=$("#nm-name").value.trim(),f=$("#nm-f").value.trim(),tg=parseFloat($("#nm-t").value);if(!n||!f||isNaN(tg)){$("#nm-name").focus();return}const dir=($("input[name=nd]:checked")||{}).value||"max";const id="m_"+Date.now();METRICS[id]={n,f,u:"",cur:dir==="max"?tg*.9:tg*1.1,tgt:tg,badAt:dir==="max"?tg*.8:tg*1.25,dir,max:tg*1.5,tr:[1,1,1,1,1,1,1,1].map((x,i)=>tg*(dir==="max"?.8+i*.02:1.2-i*.02)),owner:"You",use:["Metrics"],rem:null};audit("defined metric",n);return render()}
 if(d.trend){const x=TRENDS.find(y=>y.id===d.trend);x.st="Research";audit("sent trend to research",x.ev);return render()}if(d.unused!=null){audit("queued field removal",UNUSED[+d.unused][0]);t.textContent="Queued";t.disabled=true;return}
 if(d.kgscen){S.kgStart=d.kgscen;S.kgTasks=null;S.kgDone={};return render()}if(d.kgn){S.kgStart=d.kgn;S.kgTasks=null;S.kgDone={};audit("simulated a change",d.kgn);return render()}
 if(d.linkfile){const [name,tid]=d.linkfile.split("|");const slot=FILESLOT[S.kgNew.length%FILESLOT.length];const id="fx"+(S.kgNew.length+1);S.kgNew.push({id,t:"file",n:name,owner:(ANODE(tid)||{}).owner||"Unassigned",x:slot.x,y:slot.y,sub:"\\\\fileshare",hrs:1,file:true});KG_EXTRA.push([id,tid,"is the source of"]);S.kgLinked[name]=true;audit("linked file",name+" → "+tid);return render()}
 if(d.mktasks!=null){const imp=impact(S.kgStart);const due=S.kgStart==="std1"?"Nov 30":"Before the change window";S.kgTasks=Object.entries(imp.owners).map(([o,its])=>({o,n:its.length,h:its.reduce((a,b)=>a+b.hrs,0),due}));audit("created review tasks",S.kgStart+" · "+S.kgTasks.length+" owners");S.v.kg=1;return render()}if(d.draft!=null){S.kgDone.draft=1;audit("asked agents to draft updates",S.kgStart);S.v.kg=1;return render()}
 if(d.ask){closeDrawer();return ask(d.ask)}if(d.sr!=null){const box=$("#sugg");box.classList.remove("open");if(d.sr==="ask"){const q=$("#q").value.trim();$("#q").value="";return ask(q)}const r=S._sr[+d.sr];$("#q").value="";return r.f()}
 if(d.chatact){const m=S.chat[+d.chatact];if(m&&m.act){m.act()}return}});
document.addEventListener("click",e=>{if(e.target.closest("#chxOrb")&&window.CHATX&&CHATX.open)CHATX.open("chat")});
document.addEventListener("keydown",e=>{if(e.key==="Enter"||e.key===" "){const t=e.target.closest&&e.target.closest("[data-step],[data-kgn],[data-lin].tn");if(t){e.preventDefault();t.click()}}
 if(e.key==="/"&&!/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)){e.preventDefault();$("#q").focus()}
 if(e.target.id==="q"&&e.key==="Enter"){const q=e.target.value.trim();if(q){e.target.value="";$("#sugg").classList.remove("open");ask(q)}}if(e.key==="Escape"){$("#sugg").classList.remove("open");const c=$("#chatOpen");if(!window.CHATX&&c&&c.checked&&document.activeElement.id==="chatq")c.checked=false}});
document.addEventListener("input",e=>{const t=e.target;if(t.id==="q")showSugg();if(t.id==="rsn")S.ct.reason=t.value});
document.addEventListener("change",e=>{const t=e.target,d=t.dataset;
 if(d.vw){const [n,i]=d.vw.split(":");S.v[n]=+i;return}
 if(d.rule){const [id,k]=d.rule.split(":");const r=S.rules.find(x=>x.id===id);r[k]=t.tagName==="SELECT"?t.value:(parseFloat(t.value)||0);if(id==="r1"&&k==="amt")r.amt=Math.min(50000,r.amt);S.v.inv=2;audit("edited rule",id+" "+k+" = "+r[k]);return render()}
 if(d.auto){METRICS[d.auto].rem.auto=t.checked;audit("set automatic remediation",d.auto+" "+(t.checked?"on":"off"));return}
 if(t.name==="tg"){S.ct.target=t.value;S.ct.armed=false;S.v.tower=3;return render()}
 if(t.name==="persona"){S.persona=t.value;savePrefs();audit("switched persona",PERSONAS[S.persona].n);if(!SCREENS.some(s=>s[0]===S.screen))S.screen="home";return render()}
 if(d.pref){PREF[d.pref]=t.value;applyPrefs();savePrefs();audit("changed preference",d.pref+" = "+t.value);return}});
document.addEventListener("toggle",e=>{if(e.target.id==="profilePop"&&e.newState==="open"){$$("input[name=persona]").forEach(i=>i.checked=i.value===S.persona);$$("[data-pref]").forEach(i=>i.checked=PREF[i.dataset.pref]===i.value);$("#auditCountPref").textContent=AUDIT.length}},true);
document.addEventListener("submit",e=>{if(e.target.id==="chatForm"){e.preventDefault();const q=$("#chatq").value.trim();if(q){$("#chatq").value="";const sl=$("#chxSlash");if(sl)sl.hidden=true;ask(q)}}});

