setInterval(()=>{const s=$("#stream");if(!s)return;const pool=[["good","Test Agent passed 24 of 24 checks"],["info","First Officer prepared a pre-read for the 15:00 review"],["good","Invoice Advisor scored INV-20440: reject, 88%"],["warn","Guardrail: blocked a response that cited no source"],["info","Ops Agent recorded rehearsal progress for RB-031"]];const p=pool[Math.floor(Math.random()*pool.length)];const n=new Date();const el=document.createElement("div");el.className="ev-line";el.innerHTML=`<span class="faint tabular">${String(n.getHours()).padStart(2,"0")}:${String(n.getMinutes()).padStart(2,"0")}</span><span class="dot ${p[0]==="info"?"mute":p[0]}"></span><span>${p[1]}</span>`;s.prepend(el);while(s.children.length>7)s.lastChild.remove()},4500);
